window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[16]=[{"i":36934,"n":"פאגו, עזרא ממנטובה וונציה","f":"יצחק","b":"מקובל מחכמי איטליה. מפיץ את תורתו של ר ישראל סרוק באיטליה."},{"i":36935,"n":"פאגי, שלמה משלוניקי","dt":"רצג - כא חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":36936,"n":"פאגיו, משה מאנקונא","dt":"שיו - ח אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":36937,"n":"פאגעל, חנוך זונדל מוישעווע","b":"רב בוישעווע-הונגריה, חסיד רמ\"מ מויזניץ בעל \"צמח צדיק\", עלה לצפת וכיהן כדיין אצל ר שמואל הלר. חתם ב\"מעשה אבות\" ירושלים תרסא אודות איסור בתלרג על בתי ספר מודרנים."},{"i":36938,"n":"פאגר, מאיר דב מארה\"ב","f":"משה אלעזר מוילנא","k":"בעל יד מאיר","dt":"תרסו","dp":"ארה\"ב","b":"אב\"ד ברומשישוק-תרכו, רב בקידאן לצדו של ר שלמה זלמן טרויב, היגר לארה\"ב. חיבר גם \"לקוטי יעקב\", \"פסקי הלכות\", ועוד - בכת\"י."},{"i":36939,"n":"פאדואה, הלל מטבריה","b":"גביר בטבריה, ממיסדי ביהמ\"ד \"משמיע ישועה\" יחד עם חברו ר שלמה רוקח - בזמן חידוש הישוב בידי ר חיים אבולעפיה, סייע בהדפסת \"זמרת הארץ\"-תקה."},{"i":36940,"n":"פאדובני, אלישמע מאיר","bp":"מודנא","dt":"תקץ - כא אלול","b":"תלמיד ר ישמעאל הכהן בעל \"זרע אמת\", ר שמואל יהודה סיניגאליא ממודנא. מרביץ תורה במודנא, כפריד, רב במנטובה, מו\"ץ בפאדובה. חיבר פסקים ודרושים בכת\"י."},{"i":36941,"n":"פאדרו, שלמה מירושלים - א","dt":"תקנה - יו כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":36942,"n":"פאדרו, שלמה מירושלים - ב","dt":"תקעה - ו אייר","dp":"ירושלים","b":"גביר מחכמי ירושלים."},{"i":36943,"n":"פאהן, זאב מהמבורג ורנדסבורג","f":"פנחס","dt":"תרג - טז שבט","b":"תלמיד ר רפאל הכהן בהמבורג. מו\"צ ברנדסבורג-תקמג."},{"i":36944,"n":"פאהן, ראובן מהאליטש","k":"בעל מחיי הקראים","b":"סופר וחוקר את חיי הקראים."},{"i":36945,"n":"פאהרילע, ישראל מהוסיאטין","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":36946,"n":"פאוויר, אליעזר מזולקוא","k":"בעל ספורי הפלאות","b":"ספרא בזולקוא. חיבר ספורי מעשים בלשון אשכנז בשם \"ספורי הפלאות\" ובו ספורי מעשיות מר שמואל ובנו ר יהודה החסיד."},{"i":36947,"n":"פאזין, ליב","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":36948,"n":"פאחאסטר, איזיק","b":"רב בפאחוסט-תק\"ס"},{"i":36949,"n":"פאטארני, לוי מפאס","f":"סלימן","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":36950,"n":"פאטיפא, פרץ מסלאטפינא","b":"חתנו - ר שלמה פרוכטר מסוטשעל"},{"i":36951,"n":"פאטיקר, ישכר מלבוב","f":"מנחם מנדל","b":"ר\"מ בלבוב, חתם בפנקס הקהלה."},{"i":36952,"n":"פאטיקר, מנחם מנדל מברעזן","f":"אשר או יחיאל מיכל","dt":"תעז - ג טבת","dp":"לבוב","b":"רב בברעזאן (באוצר הרבנים שם אביו ר יחיאל מיכל מנמירוב)."},{"i":36953,"n":"פאיאנס, דוד מביאליסטוק","bt":"תרכ","dt":"תרצה - ד אד\"ב","b":"רב בסופרסלה, קנישין(=קונישין), ביאליסטוק. אודותיו ב\"עץ חיים\" צינוביץ."},{"i":36954,"n":"פאיס, שמואל משלוניקי","b":"חכם שלם בשלוניקי-ראשית שנות ה-תר'."},{"i":36955,"n":"פאיש, יצחק מירושלים","bp":"אשכנז","dp":"ירושלים","b":"מחכמי אשכנז, עלה לצפת ועבר לירושלים-תיב ולמד עם ר שם טוב פילו. בשנת תטז בשליחות באירופה. עבר לחברון, חתם על כתב שליחות ר חייא דיין. בשנת תלב בשליחות חברון באשכנז. גיסו (אחי אשתו) של ר שמואל גאון מירושלים."},{"i":36956,"n":"פאל, בער סגל מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין."},{"i":36957,"n":"פאל, מאיר מטעט סעטשין","f":"אליעזר","dt":"תקצ - י סיון","b":"רב בטעט-סעטשין-תקפא. מחותן עם החת\"ס. בנו - ר משה-נפטר בחיי אביו ונספד ב\"מספד מר\" לר שמעון וייס מאויבן."},{"i":36958,"n":"פאל, משה זאב ממוגנדורף","b":"מו\"צ במוגנדורף,ווייצן-תר\"כ"},{"i":36959,"n":"פאל, שמואל מאבאי","b":"רב באבאי-תק\"ע"},{"i":36960,"n":"פאלאטשע, יצחק מאמשטרדם","b":"רב לספרדים באמשטרדם-תרע."},{"i":36961,"n":"פאלבר, בנימין","f":"ישראל","b":"נכד ר יצחק חיות מאונסדורף. עלה לארץ. נזכר אצל החת\"ס."},{"i":36962,"n":"פאלבר, ישראל","b":"תלמיד ה\"נודע ביהודה\". חתן ר יצחק חיות מאונסדורף. בנו - ר בנימין."},{"i":36963,"n":"פאלומבו, אברהם מקושטא","f":"אליהו","b":"מחכמי קושטא"},{"i":36964,"n":"פאלומבו, אליהו מקושטא","k":"בעל יד אליהו","b":"דיין בקושטא-תקלג, רב ראשי-תקמט."},{"i":36965,"n":"פאלומבו, נסים מקושטא","f":"אליהו","k":"בעל יפה ענף","bt":"תקנז","dt":"תרא","b":"נכד ר אליהו מקושטא. רב בקושטא."},{"i":36966,"n":"פאליי, אברהם נח משקלוב ות\"א","f":"חיים","bt":"תרלו","dt":"תרצא","dp":"תל אביב","b":"חתן ר אריה ליב ולפרט מגרינקישק. תלמיד ישיבת סלובודקה ור ברוך בר לייבוביץ בעיר הלוסק והיה שם ר\"מ, ר\"מ בשקלוב, בשנת תרפה עלה לחברון, אחר כך ראש ישיבת \"היכל התלמוד\" בתל אביב. מאגרותיו ב\"תבונה\" - ירושלים תשא."},{"i":36967,"n":"פאליי, ג'ון","k":"בעל די שווארצע חברה","bt":"1871","bp":"רדושקביץ","dt":"1907","dp":"ניו יורק","b":"תלמיד ישיבת מינסק, וולוזין. היגר לארה\"ב וכתב בעתונים יהודיים ובהם \"פאלק אדוואקאט\", \"אידישע פרעסע\", \"אידישע גאזעטן\" - שהיה אז העתון היהודי הנפוץ ביותר בעולם. חיבר גם \"ערב רב\", ועוד."},{"i":36968,"n":"פאליי, עוזר מפינלנד וארה\"ב","f":"אהרן בונם","bt":"תרכט","bp":"שאצק-פלך מינסק","b":"תלמיד ישיבת נוברדוק, נסמך מאת ר יחיאל מיכל אפשטין, ר נתן שוחט מדעאבעל. חתן ר אליהו דיין מליוביץ. רב באבא(שם עיר)-פינלנד-תרס, קליבלנד-תרעג."},{"i":36969,"n":"פאליי, צבי","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":36970,"n":"פאליי-שקלובר, נח","b":"משגיח רוחני במאלטש,עלה לירושלים,מגדולי המשפיעים-תר\"צ"},{"i":36971,"n":"פאליק, יהושע","dt":"תקצה - ד סיון","b":"מו\"צ בשילווץ"},{"i":36972,"n":"פאליק, צבי הירש מהורודישץ","b":"תלמיד ר מנחם מנדל מליובאויטש, בנו ר יהודה ליב, ונכדו ר שלמה זלמן מקפוסט. רב בלאזני-תרכ."},{"i":36973,"n":"פאליר, משה מקוברין","f":"ישראל","k":"אדמור מקוברין","bt":"תקמד","dt":"תריח - כט ניסן","b":"תלמיד ר משה משרשוב, ר מרדכי מלכוביץ ובנו ר נח. אדמור בקוברין-תקצב, ונסע כאדמור אל ר משה צבי מסאווראן ור ישראל מרוזין. ירש מרבו האדמור מלכוביץ את נשיאות ארץ ישראל ל\"כולל רייסין\" ופעל למען הישוב היהודי בארץ ישראל. הלחין מנגינות רבות לזמר \"יה אכסוף\". מתלמידיו ר אברהם מסלונים. מתורתו ב\"אמרות טהורות\", \"אור ישרים\", \"תורת אבות\", \"אמרות משה\". אחיו של ר מנחם אליעזר שעלה לארץ-תקצג.","bk":[["דבש השדה",""]]},{"i":36974,"n":"פאלק הכהן מטשיטשליניק וקישינוב","dt":"תקמב","b":"נכד בעל הסמ\"ע. תלמיד הבעשט. חתן ר שמרל מוארחיבקא. רב בקישינוב."},{"i":36975,"n":"פאלק מקידאן","b":"רב בקידאן בזמן ר פנחס בעל \"אבן הראשה\". נזכר ב\"בן אורי\"-זולקווא תפט בענין הנחת שני זוגות תפילין."},{"i":36976,"n":"פאלקאר, יוסף ממכנאס","b":"מחכמי מכנאס, חתם-תף עם ר אברהם ן חסין."},{"i":36977,"n":"פאלקי, רפאל יהושע אשכנזי","dt":"תפה - כח חשון","dp":"שלוניקי","b":"מחכמי חברון, בשליחות באזמיר ובדמשק-תפד, בשנת תעח היה בשלוניקי ופגש את רבני העיר שחלקו לו כבוד ונזכר אצל ר שמואל שלום משלוניקי, ור חיים משה אמאריליו ב\"יד משה\". היה בדמשק והגיה ספרי תורה. נפטר בשליחותו, ונספד ע\"י גדולי שלוניקי."},{"i":36978,"n":"פאנו די, אברהם","b":"גביר. מכתב בקשה אליו מירושלים-תרסה."},{"i":36979,"n":"פאנו, יוסף צמח עובדיה מלוגו","b":"רב בלוגו-איטליה-תקץ, חתם על מכתב בקשת עזרה מקהלות איטליה."},{"i":36980,"n":"פאנו, יעקב","b":"מגדולי חכמי איטליה בבולוניה-ש\"כ"},{"i":36981,"n":"פאנו, שלמה ברוך מאיטליה","f":"שמואל","b":"רב במנטובה - סוף המאה ה-17. החליף תשובות עם ר שמואל אבוהב."},{"i":36982,"n":"פאנו, שמואל ממנטובה","f":"יהודה","b":"ר\"מ בישיבת מנטובה - באמצע המאה ה-17."},{"i":36983,"n":"פאניג'יל, אליהו משה מירושלים","f":"יהודה","k":"בעל תורת משה","bt":"תרי","bp":"ירושלים","dt":"תרעט - כט טבת","dp":"ירושלים","b":"למד בישיבות ירושלים, עסקן ציבורי, עמד בראש מוסדות שונים בירושלים, בשנת תרלט בשליחות לערי גורגי'ה ודסטין בקוקז. בשנת תרנב בשליחות במצרים, ובשנת תרנח בהודו, בשנת תרסז נתמנה כראשון לציון. חיבר ספר \"בינה לעתים ותיקון ישכר\" ירושלים תרלז, \"קאנטיגה די קאסטיגיריו ירושלים תרלו. ועוד בכתב יד. פרסם מאמרים ב\"המאסף\". ?? באוצר מופיע גם תחת אליהו משה בן יהודה ??"},{"i":36984,"n":"פאניג'יל, יהודה מירושלים","f":"ישראל","bt":"תקפא-ו","bp":"טאטאר-פזארג'יק","dt":"תרנז - כז שבט","dp":"ירושלים","b":"בן אחות ר רפאל מאיר-המרפ\"א וגדל אצלו אחר שהתייתם. ר\"מ \"דורש ציון\" בירושלים. בנו - ר אליהו משה-הראשל\"צ."},{"i":36985,"n":"פאניג'יל, יהודה שלמה","f":"רפאל מאיר","dt":"תרסז - כז תשרי","dp":"ירושלים","b":"מחכמי ירושלים, נפטר צעיר."},{"i":36986,"n":"פאניג'יל, יוסף חי מירושלים","f":"אליהו משה ישראל","bt":"תרמג","bp":"ירושלים","dt":"תשז - כו תשרי","b":"תלמיד \"דורש ציון\", \"תפארת ירושלים\", ר שלמה בכר, ר דוד פיזנטי, ר שמעון חרוש, ר נחם ב' יצחק, ר ב\"צ קואינקה, למד בביהמ\"ד לרבנים בקושטא. חתן נכדת ר נסים ברוך-ראב\"ד ירושלים. משנה לר דוד פאפו בבגדד-תרסה, מורה בירושלים ומזכירו של אביו-הראשל\"צ, רב בבצרה, סירב לרבנות בבל על מקום ר דוד פאפו וחזר לירושלים, רב קהילת הספרדים בבואנוס איירס."},{"i":36987,"n":"פאניג'יל, רפאל מאיר מירושלים","f":"יהודה","k":"מרפ\"א - בעל לב מרפא","r":"הראשל\"צ","bt":"תקסד","bp":"טאטאר-פזרזוק - בולגריה","dt":"תרנג - יד טבת","dp":"ירושלים","b":"עלה לירושלים בילדותו עם הוריו-תקסז, חתן ר אשר הלוי - רב בירושלים. בשליחות בתונס ואלגי'ר, ובמרוקו. בנו יחידו נפטר בחייו ובתו נשאה לר חיים משה אלישר (=החמ\"א) בן ה\"ראשון לציון\". בשנת תר בשליחות באיטליה, בהיותו ברומא-תרה פעל להסכם שלום בתוך הקהלה, נפגש עם האפיפיור שאפשר לו להכנס לגנזי הותיקן. בשנת תריד ראבד הספרדים ובשנת תרם נבחר ל\"ראשון לציון\" לאחר ר אברהם אשכנזי. חיבר \"לב מרפא\" ירושלים תרמז, ועוד. פעל כנגד קונטרס אנטישמי בשם \"צראח אל בר פי בוק אל חר\" שהאשימה את היהודים בעלילת דם, ובהשפעתו פקד השולטן לבער את הספר. אירח בליל הסדר את נכדיו של מלך אנגליה שביקרו בירושלים ובהם מי שהיה לימים המלך ג'ורג' החמישי. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["לב מרפא -",""]]},{"i":36988,"n":"פאנסס, אליהו משה מאמשטרדם","bt":"תרלה","dt":"תשב","b":"רב באמסטרדם תרפ\"ט"},{"i":36989,"n":"פאנציירי, אברהם","dp":"דמשק","b":"רב בדמשק"},{"i":36990,"n":"פאס - דפוס","b":"בית דפוס בפאס, מתקופת גירוש ספרד-רעז עד רפב."},{"i":36991,"n":"פאס די, יצחק מאיטליה","f":"שמואל או משה","k":"בעל מאירת עינים","dt":"תקך","dp":"שלוניקי","b":"מחכמי שלוניקי (לפי ארזי הלבנון - איטליה), רב בסופיה-תקד, חזק לשלוניקי (בגלל שהסתכסך עם גבירי הקהל בסופיה). נשא ונתן עם ר חיים אבולעפיה שהיה אז רב בלאריסה. תשובות ממנו ב\"דבר משה\" וב\"חיי אברהם\" ועוד. חיבר \"ברך יצחק\", \"הודאת אמונת ישראל\", \"טהרת הנפש\" ועוד."},{"i":36992,"n":"פאס די, שמואל מליוורנו - א","dt":"תן","b":"רב בליוורנו, ראש ישיבה בונציה. רבו של ר\"י אירגס בעל \"דברי יוסף\" המביא מדבריו בספרו. חתם-תנט? על מכתב תמיכה בר משה חגיז (ואולי החותם הוא הרב השני בשם זה)."},{"i":36993,"n":"פאס די, שמואל מליוורנו ב","dt":"תצד","b":"רב בונציה. נזכר ב\"לקט הקמח\". קינה לזכרו מר יצחק פאציפיקו."},{"i":36994,"n":"פאס, מנדלן","dt":"תכז","b":"רב בפרנקפורט,פוזנא"},{"i":36995,"n":"פאס, שלמה","dt":"שע","b":"מרבני פאס. (ראה גם שלמה חגיז מפאס וירושלים)."},{"i":36996,"n":"פאסטאג, עזריאל","b":"פרסם מאמרים ב\"תלפיות\" - שנחאי תשו."},{"i":36997,"n":"פאסי, וידאל מסופיה","dt":"תקנז - ח סיון","dp":"סופיה","b":"רב בסופיה."},{"i":36998,"n":"פאסי, יהודה משלוניקי ומזיתרא","dt":"שלז - כח אלול","dp":"שלוניקי","b":"מחכמי שלוניקי, רב במזיתרא."},{"i":36999,"n":"פאסי, יוסף מספרד ושלוניקי","bt":"רכב","bp":"טולדו(=טוליטולא)","dp":"אדרינופול","b":"תלמיד ר יצחק אבוהב, ודון יצחק אברבנל. ממגורשי ספרד, רב בשלוניקי וראש ישיבה, ונתמנה לאחד מ-3 ראשי הקהלות בשלוניקי יחד עם ר אליעזר השמעוני ור יהודה בנבנישתי (אחר פטירת ר שלמה טאיטצק ור יעקב ן חביב), עבר לאדרינופול-רעד. בניו: ר מאיר, ר יצחק. תשובות ממנו בספרי חכמי דורו, חיבר חדושים על מסכת כתובות בכת\"י. מתלמידיו: ר אהרן מטרני, דון שמואל אברבנל, ר שלמה עטיה, ר ישראל די קוריאל, ר אברהם סיראלוו, ר מאיר ן וירגא, ומתלמידיו באדרינופול: ר משה בן יוסף טרני, ר ישראל די קוריאל, ור אהרן טרני. בנו - ר מאיר מירושלים."},{"i":37000,"n":"פאסי, יעקב משלוניקי","dt":"תס","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":37001,"n":"פאסי, יצחק ממצרים","b":"תלמיד הרדב\"ז. מחכמי מצרים, וחברו של האר\"י - אחד משלושת החכמים בשם יצחק שעליהם אמר הארי כי יתפרסמו."},{"i":37002,"n":"פאסי, יצחק משלוניקי","f":"יוסף פאסי","b":"מגדולי שאלוניקי-ש\"כ,ממגורשי ספרד"},{"i":37003,"n":"פאסי, יצחק משלוניקי","f":"יוסף","b":"אחיו של ר מאיר שעלה לירושלים-רפד. מחכמי שלוניקי-שנות ה-ר'."},{"i":37004,"n":"פאסי, יצחק משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שסג."},{"i":37005,"n":"פאסי, יצחק משלוניקי","dt":"של - אדר","dp":"שלוניקי","b":"מחכמי שלוניקי, מוצאו מפאס-מרוקו."},{"i":37006,"n":"פאסי, מאיר משלוניקי וירושלים","f":"יוסף משלוניקי","b":"מחכמי שלוניקי, קושטא, עלה לירושלים-רפד וכיהן כדיין אצל הרלב\"ח, ונזכר בשו\"ת הרלב\"ח. נזכר גם בשו\"ת ר יוסף קארו, ור יעקב בירב, והמבי\"ט."},{"i":37007,"n":"פאפא, זאב וולף מסנט-פעטר","dt":"תקפג - כג ניסן","b":"רבה הראשון של סנט-פעטר-מחוז בורשוד גומור."},{"i":37008,"n":"פאפא, יהושע מוינה","b":"דיין בוינה"},{"i":37009,"n":"פאפא, משה","b":"מגדולי רבני צפת-ש\"כ"},{"i":37010,"n":"פאפא, נתנאל חיים מאנטיפולי","b":"רב באנטיפולי, עלה לירושלים. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":37011,"n":"פאפאק, אהרן מנ\"י","b":"תלמיד בישיבת \"תומכי תמימים\" - נ\"י תשד. פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":37012,"n":"פאפו, אברהם דוד","b":"רב באיספלטירו-תק\"ל"},{"i":37013,"n":"פאפו, אברהם דוד מראגוזה","f":"שמואל","b":"רב ברגוזה-תפב ועבר משם. מתורתו ב\"שמש צדקה\" בענין מחלוקת עם הרב מורפורגו - בנוגע לברית לאבל ביומו הראשון - משנת תצא."},{"i":37014,"n":"פאפו, אברהם מסרייבו","b":"רב בסרייבו-שץ."},{"i":37015,"n":"פאפו, אברהם מסרייבו - ב","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":37016,"n":"פאפו, אליעזר - הנכד","f":"יהודה","b":"עלה לירושלים עם אביו. חתנו - ר אהרן עזריאל בעל \"כפי אהרן\"."},{"i":37017,"n":"פאפו, אליעזר יחזקאל מסרייבו","f":"יהודה (יצחק)","k":"בעל פלא יועץ","bt":"תקמה","bp":"סאראייבו","dt":"תקפח - כ תשרי","b":"רב בסרייבו, סליסטרא-תקפ, מרביץ תורה, חיבר \"פלא יועץ\".","bk":[["פלא יועץ – מוסר",""],["אורות אלים - מוסר",""],["אלף המגן - מוסר",""],["בית תפילה – מוסר ופי' התפלה",""],["חדש האביב – ש\"ס",""],["חסד לאלפים – או\"ח",""],["יעלזו חסידים – ס' חסידים",""]]},{"i":37018,"n":"פאפו, אליעזר מסרייבו","f":"שם טוב","k":"בעל דמשק אליעזר","dt":"תרנח - י אייר","dp":"ירושלים","b":"רב בשאראי(=סרייבו), מחבר \"דמשק אליעזר\" בילוגרד תרך, ועוד. עלה לירושלים, בהקדמה לספרו \"משק ביתי\" כותב על צערו על כי לא היו לו בנים זכרים."},{"i":37019,"n":"פאפו, בנימין משלוניקי","b":"ממגורשי ספרד-רנב, רב בשאלוניקי."},{"i":37020,"n":"פאפו, דוד מקושטא","f":"שלמה","k":"בעל בני מאיר","bt":"תרו-תרח","bp":"קושטא","dt":"תרפז - כב ניסן","dp":"ירושלים","b":"עלה בגיל שבע לירושלים, בשנת תרמד בשליחות לערי מצרים ותורכיה, היה חכם באשי בעיר ברוסה(=ברושה) ליד אזמיר וכיהן שם שמונה שנים, ואחר כך רב במונסטיר, טריפולי-לוב-תרנג, רב הכולל בבגדד-תרנט, בזמן המלחמה נחשד על ידי הסולטן שהוא מתנגד לו. בשנת תרע חזר לירושלים וכיהן כראבד לאחר שסירב לכהן כחכם באשי. חיבר \"בני מאיר\" ירושלים תרעד, \"פני דוד\" ירושלים תרפד. ראש ביה\"ח \"משגב לדך\".","bk":[["פני דוד חכם באשי בבבל",""]]},{"i":37021,"n":"פאפו, יהודה מירושלים","f":"אליעזר","k":"פל\"א - בעל שבר פושעי","dt":"תרלג - יב ניסן","dp":"ירושלים","b":"עלה לירושלים-לפני תרטז, מחכמי ירושלים, עבר לחברון וחזר לירושלים. עסק במסחר יחד עם הגביר יעקב ולירו. בשנת תרג חתם על הסכמה לספר דברי שלום לר רפאל שלום שרעבי. בשנת תרד על הסכם בעדה הספרדית. בשנת תרו חתם בכתבי פולמוס גאגין. חיבר \"שבר פושעים\" אודות המחלוקת בירושלים. מחכמי \"בית אל\". תרגם ללדינו את ספרו של אביו \"פלא יועץ\". חתם גם בשם \"יהודה יעלה\"."},{"i":37022,"n":"פאפו, יוסף אברהם מרוסג'וק","dt":"תרפג","dp":"רוסג'וק","b":"עסקן צבור ציוני ברוסג'וק, פרסם מאמרים ב\"השופר\". תרגם מחזות ללאדינו ובהם \"שאול\", \"עתליה\", ועוד."},{"i":37023,"n":"פאפו, יוסף מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":37024,"n":"פאפו, יעקב מפטרץ-יוון","b":"ממגורשי ספרד, בא לפטרוס(=פטרץ)-יון. רב בפטרץ-שם. לפי רוזניס היה מבני העדה הרומנית ולא מספרד. נזכר בשו\"ת ר יעקב בירב. תיווך ועשה שלום בין העדה הספרדית לעדה הסיציליאנית. נכדו (בן בתו) ר יעקב הלוי מפטרץ וונציה."},{"i":37025,"n":"פאפו, מיכאל","bp":"ישראל","dt":"תרצא - יא אדר","dp":"קליבלנד-ארה\"ב","b":"מנהל המושבה \"באר טוביה\" מטעם יק\"א, מטולה, יסוד המעלה, נסע למצרים ללמוד גידול הכותנה-תרעא, ארה\"ב-תרפא."},{"i":37026,"n":"פאפו, מיכאל מוינה","f":"שם טוב","bt":"תרד","b":"רב עדת הספרדים בוינה-תרלב. הו\"ל סידור בנוסח ספרד."},{"i":37027,"n":"פאפו, מיכאל משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":37028,"n":"פאפו, מנחם מוינה","f":"מיכאל מוינה","bp":"וינה","b":"תלמיד הפרופ' שמואל קרויס המזכירו בספר \"גבעת שאול\" לר שאול בן עבדאלה יוסף שאותו הוציא לאור."},{"i":37029,"n":"פאפו, משה מצפת","b":"מחכמי צפת בזמן ר יוסף קארו המזכירו בתשובותיו, וכן העיד על מציאות שודדים בין דמשק לארם צובא."},{"i":37030,"n":"פאפולא ירושלמי","b":"מחכמי קושטא-שנות ה-ת'."},{"i":37031,"n":"פאפולה, יום טוב","f":"רפאל מירושלים","b":"נכד-אבי אמו ר יום טוב אלגזי. רב בירושלים-תר."},{"i":37032,"n":"פאפולה, יוסף חי מירושלים","f":"יעקב","b":"חתן ר יעקב פינצ'י. מחכמי \"בית אל\" בירושלים. נפטר צעיר."},{"i":37033,"n":"פאפולה, יעקב בכור מירושלים","f":"נסים שבתי מיכאל","bt":"תרכח","bp":"ירושלים","b":"מורה לעברית, מלמד ב\"דורש ציון\", דיין בטשקנט-תרסז, חזר לארץ-תרעב וכיהן כמזכיר הרבנות הראשית בתל אביב, עסקן ציבור."},{"i":37034,"n":"פאפולה, יעקב מירושלים","f":"יום טוב","dt":"תרמו - כב שבט","dp":"ירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים. גיסו של ר מאיר כלב מירקדו."},{"i":37035,"n":"פאפולה, נסים שבתי מיכאל","f":"יעקב","bt":"תרח","bp":"ירושלים","dt":"תרע - כג סיון","dp":"ירושלים","b":"חתן ר כלב מאיר מירקדו מירושלים. ש\"ץ ק\"ק אסטמבולים בירושלים אצל ר יוסף עוזיאל, מחכמי \"בית אל\". בניו: יעקב, יוסף, יום טוב מורנו, מאיר עזריה, רפאל אפרים, משה חי."},{"i":37036,"n":"פאפולה, עזריה מירושלים","f":"רפאל המנגן?","dt":"תקב-ך","dp":"ירושלים","b":"מחכמי ירושלים בזמן ר שלום מזרחי שרעבי, הצליח להציל כמה נפשות מידי השלטון. חתם על תיקונים שונים לטובת הקהלה. בניו - ר מיכאל, ר רפאל-חתן ר יו\"ט אלגזי."},{"i":37037,"n":"פאפולה, עזריה מירושלים","f":"רפאל","dt":"תקלח","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":37038,"n":"פאפולה, רפאל - המנגן - א","b":"מנגן בירושלים. ראש משפחת פאפלא בירושלים."},{"i":37039,"n":"פאפולה, רפאל מירושלים","f":"עזריה מירושלים","b":"רב בירושלים-תקל. חתן ר יום טוב אלגזי. נזכר בכתב היוחסין של משפחת אלגזי."},{"i":37040,"n":"פאפולה, שבתי מירושלים","f":"עזריה","k":"בעל ספר רפואה","b":"רב ורופא בירושלים. חיבר ספר רפואה."},{"i":37041,"n":"פאפע נתנאל חיים","bt":"1835","dt":"ה'תרסה 1905","bk":[["סידור תפלת ישרים",""]]},{"i":37042,"n":"פאפקין, צבי חיים מארה\"ב","bt":"תרלה","bp":"לידא-פלך וילנא","b":"תלמיד ר דובער פרוזשינר מלידא, ר יהודה בעל \"פני יהודה\" בישיבת סלונים, ישיבת מיילס בוילנא אצל ר בן ציון ולטמן ור ישראל איסר, למד בקיבוץ בואראנאווא, וולוזין, איווענעץ. היגר לארה\"ב-תרס וכיהן כרב בניו בדפורד, יוטיקא-ניו יורק-תרסח. נסמך מאת: ר שלמה הכהן מוילנא, ר יוסף שלופר מסלונים, ר מרדכי מסלונים, ר יצחק יעקב ריינס."},{"i":37043,"n":"פאצוואר, יוסף מפינסק","f":"יהודה ליב","b":"רב בפינסק. בנו בעל \"כבוד חכמים\"."},{"i":37044,"n":"פאציפיקו, אברהם מונציה","f":"יצחק","dt":"תקנה","b":"רב בונציה. חתם על חרם בשנת תקכא - בענין מס בונציה - כנגד ר יעקב חזק מפדובה."},{"i":37045,"n":"פאציפיקו, יעקב מגיברלטר","b":"יהודי מגיברלטר, פקיד בקונסוליה האנגלית בראבאט-מרוקו-שנות ה-תק'."},{"i":37046,"n":"פאציפיקו, יצחק מונציה","f":"אשר","k":"בעל משפט שלום","dt":"תקו - יג ניסן","dp":"ונציה","b":"דרשן, פייטן, ורב בונציה. חותנו של הר\"ר קורינלדי בעל \"בית דוד\" שהביא תשובה ממנו. חיבר \"משפט שלום\" - בכת\"י. היה לו מחלוקת עם ר נתנאל הלוי מפדובה אודות ס\"ת. הגיה מחזור אשכנז ע\"פ הדרת קדש ונדפס עם שיר ממנו."},{"i":37047,"n":"פאק, אשר ישעיה מפאקוי","f":"חנוך העניך-זכרון יוס","b":"דומ\"ץ בקאשוי אצל אביו."},{"i":37048,"n":"פאק, חנוך הנך מקאשוי","f":"אלקנה מרישא","k":"בעל זכרון יוסף","bt":"תרם","bp":"רישא","dt":"תשד","b":"חתן ר אשר ישעיה הלוי וינפלד מגורליץ. רב בקאשוי. נספה בשואה. (פסקו האחרון היה שלא לאבד עצמו לדעת אלא למסור נפשו על קדוש השם). חיבר \"זכרון יוסף\" ברדיוב תרפט. בנו - ר אשר ישעיה מקאשוי."},{"i":37049,"n":"פאק, מנחם","dt":"תשד","b":"רב בקאשוי"},{"i":37050,"n":"פאקאסי, אהרן מסיציליה","b":"רב במסינה-סיציליה-קן. פעל לנדות את אהרן הרופא-קמ שפנה לשלטונות שיכריחו את הרב לבטל את הנידוי."},{"i":37051,"n":"פאקס, יחזקאל מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":37052,"n":"פאקשיווע, אברהם זאב מארה\"ב","b":"רב ביוניון הילל-ארה\"ב. מדבריו ב\"משנת יעב\"ץ\"."},{"i":37053,"n":"פאר, דוד יהודה מקמינקא","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":37054,"n":"פאראגה, מרדכי מאיטליה","b":"מחכמי איטליה, עשה עצמו משיח בן יוסף, נזכר ב\"מעשה טוביה\"."},{"i":37055,"n":"פאראדיש, משה","b":"מחכמי צפת, בשנת תטו בשליחות בתורכיה ובאיטליה, נמנה על בית מדרשו של ר שמואל אבוהב. היה בין המסכימים על שות מהרי בירב, היה בשליחות באזמיר עם ר יונתן גלנטי בשנים תטו-תיח."},{"i":37056,"n":"פאראס, יצחק","b":"נזכר ב\"אבני זכרון\"."},{"i":37057,"n":"פאראס, יצחק מונציה","b":"רב בונציה-שלט."},{"i":37058,"n":"פאראש, ג'יליבי משלוניקי","b":"גביר בשלוניקי ומשבעת טובי העיר-תקף בזמן ר שאול מולכו, והיה מחלוקת בינם לבין הרב בענין המס."},{"i":37059,"n":"פארבירז, יעקב","f":"יצחק","bt":"תרלו","b":"חתן ר מרדכי הורביץ מזאמושט. רב בזאוויחוסט-פלך ראדום-תרנט."},{"i":37060,"n":"פארדו - משפחה","b":"משפחת רבנים מגולי ספרד באיטליה, בשלוניקי ועוד."},{"i":37061,"n":"פארדו, אברהם","dt":"תר"},{"i":37062,"n":"פארדו, אברהם הזקן מבלגרד","f":"יעקב","k":"בעל ציצים ופרחים","b":"מרבני בלגרד-תרי, חיבר \"ציצים ופרחים\"."},{"i":37063,"n":"פארדו, אברהם מזימלין","f":"יצחק","k":"בעל חיבת אברהם","dt":"תקעה - כז סיון","dp":"זעמלין(=זימלין)","b":"מו\"צ בזימלין-ליד בלגרד. בנו - ר חיים שמואל הו\"ל את ספרו \"חבת אברהם\" בלגרד תרכב."},{"i":37064,"n":"פארדו, אברהם מירושלים","b":"דיין, ראש ישיבת \"בית אהרן\" בירושלים-תקיח."},{"i":37065,"n":"פארדו, אברהם מליוורנו","f":"חיים דוד-שושנים לדוד","k":"חתן הרב חיד\"א","dt":"תקפ - ו אייר","dp":"ירושלים","b":"רב בליוורנו. חתנו של החיד\"א, חדושים משמו מביא החידא בספרו \"יוסף אומץ\", עלה לירושלים עם אביו, ונתמנה לאחר פטירת החיד\"א לראש הישיבה. הוציא לאור את ספרי אביו \"חסדי דוד ושושנים לדוד\", עם הקדמה משלו. תשובה ממנו ב\"יוסף אומץ\"."},{"i":37066,"n":"פארדו, אברהם משלוניקי","f":"יוסף","dp":"ירושלים","b":"חתן אחיו - ר יצחק. רב בשלוניקי, היה מרבני אמשטרדם ואחר כך עלה לירושלים. אחיהם של ר דוד ור יצחק פארדו."},{"i":37067,"n":"פארדו, אברהם משלוניקי","dt":"שעט","dp":"שלוניקי","b":"מרבני שלוניקי, ואחר כך בצפת. נזכר בשות המבי\"ט בהקשר עם צוואתו שנכתבה באדר שלה. כתבי יד ממנו (ניו יורק קולמוביה)"},{"i":37068,"n":"פארדו, אהרן מירושלים","b":"פרנס ירושלים בימי ר משה גלנטי (שפ-תמט), תעודה חתומה ממנו משנת תנו, פורסמה בידי בניהו בספונות ב."},{"i":37069,"n":"פארדו, אהרן מירושלים","b":"דיין, מחכמי ירושלים, ראש ישיבת \"בית אהרן\""},{"i":37070,"n":"פארדו, ברוך","b":"בשנת תקנח בשליחות באיטליה, כתב יד של \"פירוש נביאים\" לחברי חברת מקרא קודש באיטליה וביניהם ר יצחק ברוך פארדו, נמצא בספריה הלאומית (ס 3496)."},{"i":37071,"n":"פארדו, דוד הרופא מאיטליה","bt":"תקפא","bp":"ראגוזה-איטליה","dt":"תרנז - ב אב","dp":"קושטא","b":"למד רפואה בוינה, רופא בקושטא ויסד בה את אגודת הרופאים."},{"i":37072,"n":"פארדו, דוד מאישפלאטו","b":"היה תקופה מסוימת באישפלאטו-תקד ונשאל שם."},{"i":37073,"n":"פארדו, דוד מירושלים","b":"ממיסדי ישיבת \"חסד לאברהם\" בירושלים-תקז."},{"i":37074,"n":"פארדו, דוד מלונדון","f":"יוסף מאמ\"ד ולונדון","k":"בעל שלחן הטהור","dt":"תעג","dp":"סורינום","b":"רב בלונדון, סורינום-אמריקה, ונזכר באגרת ר דוד ניטו מלונדון. דודיו ר שאול ור יאשיהו. הביא לדפוס \"שלחן טהור\" לאביו ר יוסף פארדו - אמשטרדם תמו."},{"i":37075,"n":"פארדו, דוד מקושטא ואמשטרדם","f":"יוסף","b":"מחכמי שלוניקי, רב באמשטרדם. הסכים על \"עשרה מאמרות\"-תד."},{"i":37076,"n":"פארדו, דוד שמואל (שלמה)","f":"יעקב - קהלות יעקב","k":"בעל כללים על השס","dt":"תריח","dp":"ירושלים","b":"נכד ר דוד-בעל שושנים לדוד. היה רב בוירונה, בשנת תקפט הסכים על ספר \"יד אבשלום\" - תקפט, חיבר ספר כללים על השס והפוסקים."},{"i":37077,"n":"פארדו, חיים אליהו מקושטא","b":"יסד בית דפוס בקושטא-תקמב, נסגר אחרי זמן קצר. בנו - המדפיס רפאל חיים אליה פארדו."},{"i":37078,"n":"פארדו, חיים דוד - הזקן","f":"יעקב","k":"בעל שושנים לדוד","bt":"תע-תעט","bp":"ונציה","dt":"תקנא-ב -יב סיון","dp":"ירושלים","b":"לאחר שנתייתם גדל אצל קרובו ר משה אשכנזי בעל \"בנין נערים\" (המחבר היה ר יעקב בליליוס ולא ר משה אשכנזי). תלמיד גדולי ונציה ר יעקב בליליוס, ר אברהם פאפו ור שלמה זלמן מלבוב, היה רב בראגוזה-תק, איספלאטרו(=ספליט), סרייבו-תקכה, בלגרד-תקלו, שהה זמן מה בקורפו, עלה לירושלים-תקמב ועמד בראש ישיבת \"חסד לאברהם ובנין שלמה\". מחותן עם החיד\"א (בנו ר אברהם נשא את בתו של החיד\"א), חיבר ספרים רבים וביניהם \"למנצח לדוד\" שלונקי תקכה. כתב \"כתובות\" לחג השבועות על הקשר בין ה לעם ישראל, הכתובות נכנסו לחלק מסדורי התפלה. כתב בספליט(=איספלטרו) פזמון על הצלה בז' באדר מעלילה על היהודים, בשנת תקיב הדפיס בונציה את פירושו למשנה \"שושנים לדוד\", חיבר פיוטים ושירים, חיבר \"חסדי דוד\" על התוספתא. בניו - ר יעקב, ר יצחק, ר אברהם-חתן החיד\"א."},{"i":37079,"n":"פארדו, חיים דוד מסמנדריא","f":"יעקב - קהלת יעקב","b":"נכד ר חיים דוד בעל שושנים לדוד. רב בסמנדריא-ליד בלגרד-תקנה. (ראה גם ר דוד שמואל פארדו - שעליו נכתב שהיה בנו של ר יעקב ונכד בעל שושנים לדוד)."},{"i":37080,"n":"פארדו, חיים יעקב מירושלים","dt":"תרם","dp":"ירושלים","b":"מראשי ישיבת \"בית אהרן\" בירושלים, הסכים עם חכמי ישיבת \"בית אהרן\"-תרח, וחתם עם ראשי הישיבה לגביר ר\"ש אבו קצין-תרב. נספד ב\"איש אמונים\". אולי הוא שהו\"ל \"חסדי דוד\" ח\"ג להרד\"ף - תרן."},{"i":37081,"n":"פארדו, יאשיה מאמשטרדם וקורסאו","f":"דוד מאמשטרדם","k":"בעל מזבח הזהב - כת\"י","b":"מחכמי אמשטרדם, תלמיד וחתן ר שאול הלוי מורטירא מאמשטרדם. רב ברוטרדם-תכח, אמשטרדם ור\"מ בישיבת ר יצחק אבוהב שם, רב בקורסאו-תלד, ג'מאיקה-תמג. דרוש ממנו ב\"גנזי נסתרות\". שיר ממנו בספר חותנו \"גבעת שאול\". אחיו של ר שאול פארדו (ברוין) מניו יורק. ודודו של ר דוד פארדו מסורינום."},{"i":37082,"n":"פארדו, יוסף מאדרינופול","b":"רב באדרינופול-שנות ה-ש'. נזכר בשו\"ת מהרשד\"ם."},{"i":37083,"n":"פארדו, יוסף מאמשטרדם ושלוניקי","k":"בעל שלחן הטהור","dt":"שפ","dp":"אמשטרדם","b":"רב בשלוניקי, ונציה, רבה הראשון של הקהלה הספרדית באמשטרדם. ר יהודה אריה ממודנא ב\"חיי יהודה\" כתב שחיבר ביאור לתורה. בהקדמת \"כלי יקר\" מזכירו. בניו - ר יצחק, ר אברהם מירושלים, ר דוד."},{"i":37084,"n":"פארדו, יעקב מספאלטרו וראגוזה","f":"חיים דוד-שושנים לדוד","k":"בעל קהלת יעקב","bp":"ספאלטו(=ספליט)","dp":"ירושלים","b":"\"מרפא לנפש\", ועוד. בנו - ר דוד שמואל פארדו - רב בוירונה על מקום אבותיו, בעל ספר כללים על הש\"ס."},{"i":37085,"n":"פארדו, יעקב משלוניקי","dt":"רצה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37086,"n":"פארדו, יעקב משלוניקי","dt":"תיט - יז תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37087,"n":"פארדו, יצחק דוד מסרייבו","f":"חיים דוד-שושנים לדוד","k":"בעל תועפות ראם","bp":"ספאלטו(=ספליט)","dp":"איסקופיה","b":"אב\"ד סרייבו-תקן עד תקס על מקום אביו. אחיו של ר יעקב מספאלאטרו. חיבר \"תועפות ראם\" שלוניקי תקעא, תשובה שלו בספרו של אביו \"מזמור לדוד\". נפטר בדרכו לארץ בהיותו אצל בניו באיסקופיה. חיבר \"פירות גינוסר\", \"תועפות ראם\". תלמידו - ר דוד פינטו - כתב על רבו בספרו \"מזמור לדוד\". הסכים על \"עבודת התמיד\"-תקנב, \"אפי זוטרי\"-תקנה, \"תולעת שני\"-תקס."},{"i":37088,"n":"פארדו, יצחק מאזמיר","b":"עשיר,מרבני אזמיר-ש\"צ"},{"i":37089,"n":"פארדו, יצחק מאזמיר","f":"נתנאל","b":"תלמיד ר שבתי יונה. מחכמי אזמיר, שלוניקי-שנות ה-ת'. מוזכר ב\"קורא הדורות\"."},{"i":37090,"n":"פארדו, יצחק משלוניקי","f":"יוסף","b":"פרוש, דרשן ור\"מ בשלוניקי, עבר לאישקופיא-שנת ת'. אחיו ר אברהם ור דוד."},{"i":37091,"n":"פארדו, יצחק משלוניקי","b":"מחכמי שלוניקי ופקידי הת\"ת-שץ - בערך."},{"i":37092,"n":"פארדו, משה מירושלים","f":"רפאל דוד","k":"המפ\"ה - בעל שמו משה","bt":"תקע-ד","bp":"ירושלים","dt":"תרמח - טז אב","dp":"אלכסנדריה","b":"נכד ר יצחק אבולעפיה מצד אמו ונינו של החיד\"א מצד אביו. נתייתם בילדותו ונתחנך ע\"י ר אברהם דוד קארייו ולמד בישיבת \"חסד לאברהם\" בירושלים. דיין אצל ר אברהם אשכנזי בירושלים ועמו שימשו ר אפרים בכר משה ור ברוך פינטו. בשליחות בצפון אפריקה-תרל, ובדרכו חזרה עבר באלכסנדריה ונתמנה לרב על מקום ר נתן עמרם בעל \"קנין פירות\". חיבר גם \"צדק ומשפט, ועוד. חתם בשם - המפ\"ה (ר\"ת שמו)","bk":[["צדק ומשפט",""]]},{"i":37093,"n":"פארדו, משה מתורכיה","r":"אב\"ד ריבאטיץ ובלאז'וב","dt":"תשנו - יב אדר","b":"עלה לארץ והקים את מוסד \"אור החיים\" לבנות בבני ברק. ספר לתולדותיו - \"ומשה היה רועה\"."},{"i":37094,"n":"פארדו, נסים יהודה-נדי\"ף","k":"בעל לוח כללי למאה שנ","bt":"תריט","bp":"אזמיר","dt":"תרעג - יד אב","dp":"קהיר","b":"מורה לשפות בקהיר, משכיל ועסקן בקהילה. פרסם מאמרים בצרפתית ולאדינו. חיבר \"קאלינדאריו ז'ודיאו פירפיטואו אי מיקסטו\" - לוח למאה שנה - אזמיר תרע."},{"i":37095,"n":"פארדו, נתנאל משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שנז."},{"i":37096,"n":"פארדו, רבנו מירושלים","b":"מחכמי ישיבת אהל יעקב-תרצב."},{"i":37097,"n":"פארדו, רפאל מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":37098,"n":"פארדו, רפאל מקושטא","f":"חיים אליה מקושטא","b":"מדפיס בקושטא על מקום אביו-תקמב."},{"i":37099,"n":"פארדו, שאול (ברוין) מאמשטרדם","f":"דוד בן יוסף מאמשטרדם","dt":"תסח","dp":"ניו יורק","b":"אחיו של ר יאשיהו ור יוסף. מחכמי אמשטרדם, הגיע לאמריקה והתישב בניופארט, רב בניו יורק-תנה - והיה הרב הראשון בקהלה הראשונה שם."},{"i":37100,"n":"פארדו, שלמה משלוניקי","dt":"שצה - ב אב","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":37101,"n":"פארדו, שמואל אליעזר מירושלים","b":"רב ודרשן בירושלים-תרפד, דיין עם ר חנניה גבריאל, ור דוד פאפו."},{"i":37102,"n":"פארדו, שמואל בכור משלוניקי","b":"מדפיס בשלוניקי-תקסג אצל מרדכי נחמן ורפאל קלעי."},{"i":37103,"n":"פארו די, ברוך הרופא משלוניקי","dt":"שפח - ג סיון","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":37104,"n":"פארו, יוסף הרופא משלוניקי","f":"משה","dt":"רעב - כא אב","dp":"שלוניקי","b":"רופא בשלוניקי, אולי הוא הפייטן שחיבר שיר לספר מאיר איוב לר מאיר ן עראמה."},{"i":37105,"n":"פארו, יוסף משלוניקי - ב","b":"דיין בשלוניקי-שמח."},{"i":37106,"n":"פארו, יצחק הנריקס","dt":"תקכב","dp":"קורסאו","b":"רב בקורסאו."},{"i":37107,"n":"פארו, משה משלוניקי","dt":"רע - יג אלול","dp":"שלוניקי","b":"מחכמי שלוניקי. בנו - ר יוסף."},{"i":37108,"n":"פארוז, סעדיה מאלגיר","bt":"תקל - בערך","dt":"תרי - בערך","b":"רב בתלמסאן-אלגיר-תקע. בעל נכסים. חתימתו בפנקס בית הדין."},{"i":37109,"n":"פארח, אברהם","bp":"ספרד","b":"מחכמי ירושלים, עלה בשנת קלג מקשטיליה, בשות הריבש מספר עליו."},{"i":37110,"n":"פארידיס, אליהו (פרדס)","k":"אליהו פרדס","bt":"תקצד","bp":"חלב","dt":"תרלד - כ אלול","dp":"ירושלים","b":"עלה לירושלים, מקובל מחכמי \"בית אל\", חתן ר' וידאל קואינקה."},{"i":37111,"n":"פארידיס, משה מצפת","b":"רב בצפת-תכ, בשליחות באזמיר עם ר יונתן גלנטי."},{"i":37112,"n":"פארידיס, עזרא מפאס","b":"סופר מחכמי פאס-שנות ה-ש' בזמן ר יהודה עוזיאל."},{"i":37113,"n":"פאריז, חיים אריה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":37114,"n":"פארשער, אליקום מהולנד","f":"אברהם","k":"בעל פשר דבר","b":"מחכמי הולנד-תר, תרגם ספר ישעיהו להולנדית, וחיבר לו פירוש \"פשר דבר\"."},{"i":37115,"n":"פאשטור, משה משלוניקי","dt":"רצח - כב אייר","dp":"שלוניקי","b":"מחכמי שלוניקי. נהרג עק\"ה."},{"i":37116,"n":"פאשריאל, אברהם משלוניקי","b":"חתן ר לוי קוזין. מחכמי שלוניקי-שע."},{"i":37117,"n":"פאשריאל, יוסף משלוניקי","b":"נכד-אבי אמו - ר לוי קוזין. מחכמי שלוניקי-שץ, תלמיד ר שלמה הלוי הבחור ומגדולי ישיבתו."},{"i":37118,"n":"פאשריאל, לוי משלוניקי","f":"אברהם","dt":"תכב - כא אדר","b":"נכד-אבי אמו - ר לוי קוזין בעל \"עלית קיר קטנה\". תלמיד ר אברהם מוטאל. ר דוד קונפורטי - למד עמו בזמן שברחו מהמגפה-תח."},{"i":37119,"n":"פ\"ב, אברהם","f":"זלמן הקדוש (הי\"ד)","b":"מגדולי אשכנז-תק\"י"},{"i":37120,"n":"פבזנר, עקיבא","f":"יצחק","bt":"תרלא","bp":"וורוניעז-פלך צרניגובו","b":"רב בסמילא-פלך פולטובה-תרסג."},{"i":37121,"n":"פבירזסקי, אברהם מאיר מקיטייראד","f":"שלום","bt":"תר","b":"מו\"צ במחנובקה(=וארניפקא)-פלך ברדיטשוב-תרכו, קיטיירד(=קיטייראד)-פלך קיוב-תרסג. חיבר שו\"ת - בכת\"י."},{"i":37122,"n":"פבל, חיים אהרן בצלאל","f":"רפאל הכהן","bt":"תרם","dt":"תשג","b":"תלמיד ישיבת נווהרדוק, קובנא, וולוזין. רב ברזינובסקי(=ראזענאווסקי)-פלך ויטבסק-תרסט, פרידריך-שטאט-תרעט."},{"i":37123,"n":"פבל, מרדכי צבי הירש מדלטין","b":"רב בדלטין."},{"i":37124,"n":"פבסט, מרדכי מקרעפלד","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":37125,"n":"פבר, אברהם מטירנוי","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי(=טורנא). פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":37126,"n":"פבר, חיים מאויהל","f":"יעקב מספש","k":"בעל מורשת חיים","bt":"תרמו","bp":"ספש","dt":"תשג - ב אייר","dp":"בודפשט"},{"i":37127,"n":"פבר, יואל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":37128,"n":"פבר, יעקב מספש וטורנא","b":"מחכמי ספש (ליד קאשוי), טורנא, פרשבורג. בנו - ר חיים מאויהל. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":37129,"n":"פבר, שלמה","b":"השו\"ב של הדברי חיים."},{"i":37130,"n":"פגיון","k":"בעל הלכות שחיטה ראה: פיג'ון","b":"חיבר הלכות שחיטה. נזכר בתשובות ר יצחק לוי ואלי."},{"i":37131,"n":"פגיירו, משה מאיטליה","b":"חתנו - ר עמנואל אירגאז מליוורנו. מוזכר בהקדמה ל\"דברי יוסף\" לר יוסף אירגאז."},{"i":37132,"n":"פג'ין, מרדכי ממרוקו","f":"מסעוד","b":"מחכמי מרוקו, חתם על פס\"ד עם ר שמואל ן סעדון."},{"i":37133,"n":"פדבה, חנוך דב מוינה וירושלים","f":"אליעזר זאב","k":"בעל חשב האפוד","bt":"תרסו","bp":"בוסק","b":"חסיד בלז. חתן ר נפתלי גוטסמן. רב בוינה. עלה לירושלים-תש, כיהן כרב שכונה. בזיוו\"ש חתן ר אברהם אהרן זוננפלד בן הגריח. רב בלונדון-תשטו. חיבר \"חשב האפוד\" ירושלים תשכג."},{"i":37134,"n":"פדובה, אהרן משה","f":"יעקב מאיר מבריסק","k":"בעל באור הרא\"ם","dt":"תרמג - תשרי","b":"נכד ר שאול לוין מקרלין. אחיו של ר וולף מבריסק. חתן הגביר ר חיים נחמן פרנס מוילנא. בנו ר אריה ליב. חתנו ר יעקב ויטקינד משקלוב. נכדו-בן בתו ר חיים נחמן בעל \"חוט המשולש\"."},{"i":37135,"n":"פדובה, חיים מבריסק","f":"אהרן מבריסק","dt":"תקצו - כב אדר","b":"רב בבריסק"},{"i":37136,"n":"פדובה, יהודה מצליח ממודנא","f":"אברהם","k":"בעל אוצרות שלג","dt":"תפח","b":"רב ומקובל במודנא. חיבר \"תוכחת מגולה\" - כנראה כנגד נחמיה חייא חיון, חיבר פיוט הנדפס בתקוני שובבי\"ם (והמדפיסים העלימו שמו) - כמוזכר אצל הרמ\"ז ב\"חמשה סדרים\". הניח פסקים בכת\"י. תלמיד תלמידו - ר בעל \"זרע אמת\" מזכירו בספרו כאחד הגדולים. תשובה ממנו ב\"פחד יצחק\"-תפב, וב\"פני הכרובים\". בנו ר מנחם עזריה פדובה - רב בפרינצי."},{"i":37137,"n":"פדובה, יוסף מצליח","b":"חיבר שיר לכבוד חברת \"שומרים לבוקר\"."},{"i":37138,"n":"פדובה, יעקב מאיר מבריסק","f":"חיים בן אהרן בן מאיר","k":"בעל מקור מים חיים","dt":"תרטו - כא כסלו","dp":"בריסק","b":"נכד ר אהרן מבריסק בעל \"מנחת אהרן\". מגדולי חכמי דורו, רב בבריסק-תר על מקום ר יצחק איזיק בן ישראל (שהיה באופן זמני על מקום ר אריה ליב קצנלנבוגן) ור צבי הירש אורנשטין על מקומו אחריו. בניו - ר ראובן זאב מבריסק, ר אהרן משה פדובה - חתן הגביר ר שאול לוין מקרלין, ר צבי הירש מבריסק, ר שמשון מבריסק. חיבר גם \"נחלי מים\", ועוד. נספד ב\"בכי מסתרים\" לקרובו ר דב בער בן יעקב קעסטין. פרסם מאמרים ב\"פליטת סופרים\" - וילנא תרכג. הגדול ממינסק שפגשו כשהיה ילד קטן סיפר שהשעה שעמד בפניו פעלה עליו יותר מכל מוריו ומלמדיו."},{"i":37139,"n":"פדובה, יעקב שמעון מקאלושיק","f":"ישראל אהרן מאופוטשנא","k":"אדמור מקאלושיק","bt":"תרמה","dt":"תשא - כג אדר","b":"חתן ר אליעזר מראדויל (זלוטשוב). אדמור בקלושיק-ליד לודז עוד בחיי אביו, עבר ללודז וכיהן כאדמור מקאלושיק. שלח את ילדיו לארץ-תרפה בעליית \"כפר חסידים\". בנו ר ישראל אהרן-נספה בשואה."},{"i":37140,"n":"פדובה, יצחק מרדכי מאופוטשנא","f":"ישראל אהרן מאופוטשנא","k":"אדמור מאופוטשנא","bt":"תרמד","dt":"תשב","dp":"אופוטשנא","b":"רב באופוטשנא בחיי אביו, ועל מקומו אחריו כאדמור. נספה בשואה."},{"i":37141,"n":"פדובה, ישראל אהרן","f":"יעקב שמעון מקאלושיק","bt":"תרעו","dt":"תשד","b":"חתן ר יצחק מנחם מאלכסנדר. נספה בשואה."},{"i":37142,"n":"פדובה, ישראל אהרן מאופטשנא","f":"שמעון קצנלנבוגן מזאו","k":"אדמור מאופוטשנא פשיס","dt":"תרעה","dp":"אופוטשנא","b":"מצאצי ר יצחק מנסכיז. אחיו של ר יעקב פרלוב מנובומינסק. חתן ר לוי יהודה מאיר מפשיסחא, ואדמור על מקומו אחריו, עבר לאופוטשנא. נהרג עק\"ה בידי הקוזקים."},{"i":37143,"n":"פדובה, ישראל משה מדרויא","f":"שאול פאדובה","b":"רב ומו\"צ בדרויא(=דרויע)-תרנ."},{"i":37144,"n":"פדובה, מאיר ממנטובה","f":"אפרים","bp":"פדובה","dt":"תקמג","b":"רב וסופר סת\"ם ומדפיס במנטובה."},{"i":37145,"n":"פדובה, מנשה חיים מקורפו","b":"תשובות אליו ב\"דבר שמואל\""},{"i":37146,"n":"פדובה, ראובן זאב מבריסק","f":"יעקב מאיר מבריסק","b":"רב בבריסק. אחיו - ר אהרן משה בעל \"ביאורי הרא\"ם\"."},{"i":37147,"n":"פדובה, שאול מוילקומיר","f":"ישראל ליפשיץ מוילנא","b":"אביו נקרא גם ר ישראל אנטאקאלר. מו\"צ בווראנאוו, בריינסק, פלאצק(=פלצק), רב בוילקומיר-תרמד עד תרע. חתנו ר יצחק בנן של ר דוד טביל ממינסק. גיסו-בעל אחותו ר אלעזר קלינברג מוילנא ופילדלפיה."},{"i":37148,"n":"פדובני, אלישמע מאיר ממודנא","k":"בעל קצור הלכות יו\"ד","dt":"תקן - באו' תקץ","dp":"פדובה","b":"תלמיד ר ישמעאל הכהן בעל \"זרע אמת\" ור שלמה יאודה סיניגאליא ממדונא. רב במודנא, מנטובה עם ר יעקב קאזיס, פדובה. חיבר פסקים ודרושים בכת\"י."},{"i":37149,"n":"פדלון, נתן מטריפולי","bt":"תרלח","bp":"טריפולי","dt":"תשכה","dp":"ישראל","b":"תלמיד ר משה סרוסי. רב בטריפולי, עלה לארץ והתישב בתל אביב, וכיהן כראש ישיבת \"אליהו הנביא\"."},{"i":37150,"n":"פדליאש, שלמה יצחק","dt":"תשג","b":"רב בבאפט"},{"i":37151,"n":"פדלשטין, צמח","f":"צבי","bt":"1885","bp":"ניישטט-שאקי","dt":"1945","dp":"מחנה דאוטמרגן-גרמניה","b":"למד היסטוריה ופילוסופיה בברלין. מנהל בי\"ס בקאליש, מורה בגימנסיה של קרינסקי בוארשא. הקים גימנסיה במינסק, מנהל הגימנסיה בוילקוביסק-1922, מנהל הגימנסיה הריאלית העברית בקובנא. פעיל בתנועה הציונית וחבר המרכז הציוני ומרכז \"תרבות\", נואם מזהיר ועתונאי מוכשר. שליח \"תרבות\" בארה\"ב-1929 יחד עם המשורר שאול טשרניחובסקי. ביקר בארץ-1935 ופרסי את רשמי ביקורו ב\"אידישע שטימע\". מורה לעברית בוילנא-1940, מנהל הדואר בגיטו וילנא בזמן השואה, מרצה ופעיל בחיי הגיטו. כתב זכרונות וערוך את \"ידיעות הגיטו\". תרגם לעברית את \"אאידה\". נספה בשואה."},{"i":37152,"n":"פדנהכט, יהושע ברוך מברזן","f":"יוסף מברזן","k":"בעל חוברת יזרעאל","bt":"תרו","bp":"ברזן","dt":"תרע","b":"מנהל פנקסי הקהלה בברזן. ממנהיגי המזרחי. חיבר \"חוברת יזרעאל\" ברזן תרנח."},{"i":37153,"n":"פדנהכט, יוסף מברזן","bt":"תקסו","dt":"תרלו","dp":"ברזן","b":"ראה הקהל בברזן."},{"i":37154,"n":"פדר טוביה","bt":"1760","dt":"ה'תקעז 1817","bk":[["בית נאמן",""],["קול מחצצים",""]]},{"i":37155,"n":"פדר, דוד מאיר מסוירז","f":"ישראל משה","k":"בעל שות הרדם","bt":"תקף","dt":"תרנח - יח תשרי","b":"תלמיד ר אברהם מסטרטין, ר שלום מבלז ור ישראל מרוזין. רב ברוהטין-תר, סוירז-תריד, ברזן. חיבר גם \"אמרי דוד\" פרמישלא תרלג, ועוד."},{"i":37156,"n":"פדר, ישראל שמחה מפאריס","b":"פרסם מאמרים ב\"אוצר החיים\" - זאמושט תרצז."},{"i":37157,"n":"פדרבוש, שמעון מנרול","f":"צבי הירש מזורביצה","k":"בעל שלמות היהדות","bt":"תרנב","bp":"נרול(=נארול)","dt":"תשכט - ז אלול","b":"תלמיד ר דובריש רפפורט מראווא בעל \"דרך המלך\", ר יעקב טעפיך מראווא רוסקא, נסמך מאת מהרש\"ם מבראזן, ר מאיר אריק מטורנא, ר יעקב טעפיך מראווא. רב ודוקטור, הקים מוסדות חינוך בצביון דתי-לאומי. חתן ר ישעיה איש הורביץ מוינה. ציר בסיים הפולני-תרפג, מיסד המזרחי בגליציה, רבה של פינלנד-תרץ ומרצה באוניברסיטה של הלסינקי (איחד את הקהלות הלסינגפורס, וירבורג, ואובו), עבר לניו יורק-תש וכיהן כרב בניו יורק, ונשיא הפועל המזרחי בארה\"ב. פרסם מאמרים רבים וביניהם בפינית ובשבדית. חיבר \"שלמות היהדות על רעיון המזרחי\" ירושלים תרפז, \"חקרי תלמוד\" ירושלים תרצח, ועוד."},{"i":37158,"n":"פדרמן, ליב מגריווא","b":"יסד מנין חדש בגריווא בשם \"מנין של ר יחזקאל\", עם ר שלמה ארונוביץ."},{"i":37159,"n":"פואה, אברהם יוסף ישעיה הלל","b":"מחכמי איטליה-תקיח."},{"i":37160,"n":"פואה, אליה מנחם מאיטליה","dt":"תצח - ה טבת","dp":"איטליה","b":"גביר מחכמי איטליה, נדב בצוואתו להקמת בית מדרש. שיר לכבודו-תצח מאת ר יוסף יהודה לוי."},{"i":37161,"n":"פואה, אליעזר נחמן מריגיו","k":"בעל גרן ארנן","r":"ארנ\"ן הם אותיות ראשונות ואחרונות משמו, אליעזר נחמן","dt":"תיט - ב תמוז","b":"רב במודנא, ריגיו. תלמיד הרמ\"ע. היה לו חברה קדושה בעירו בשם \"חברת העלובים\". חיבר חידושים על ההגדה - ונציה וליוורנו, \"גורן ארנן\" ועוד. חתם שמו - ארנן\".","bk":[["גרן ארנן - עה\"ת (נדפס רק חלק קטן מהספר)",""],["מאמרים על התשובה",""],["מדרש בחידוש - הגדה של פסח",""]]},{"i":37162,"n":"פואה, גד שמואל מונציה","b":"מדפיס בונציה-תקלז."},{"i":37163,"n":"פואה, חזקיה מריגייו","f":"יצחק","b":"רב בריגייו - גיסו של הרמ\"ע מפאנו. תשובה ממנו ב\"פלגי מים\" בענין המקוה ברוויגו-שסב."},{"i":37164,"n":"פואה, חיים מאיטליה וירושלים","b":"מחכמי איטליה שעלה לירושלים. מופיע ב\"חרבות ירושלים\" כאחד מהנפגעים בפרעות אבן פארוך."},{"i":37165,"n":"פואה, יוסף הרופא מקושטא","b":"רופא מחכמי קושטא-שנות ה-ת'. סייע בהוצאות הדפסת \"ראשית חכמה\"-תצו, פעל לטובת יהודי ירושלים."},{"i":37166,"n":"פואה, יחיאל מריגייו","b":"רב בריגייו. נזכר בשו\"ת הרמ\"ז. חתנו של ר נתן שפירא מירושלים."},{"i":37167,"n":"פואה, יצחק מריגייו","k":"חותן הרמ\"ע מפאנו","b":"רב במנטובה-של, בריגייו בזמן ר שמואל יהודה קצנלנבוגן. בניו ר חזקיה ור יחיאל. חתנו - הרמ\"ע מפאנו. נספד ב\"נפוצות יהודה\" לר יהודה מוסקאטו."},{"i":37168,"n":"פואה, ישראל מירושלים","b":"מחכמי ירושלים. מתשובותיו ב\"כנסת הגדולה\". בשליחות באיטליה-תלב, (ולא ידוע אם חזר לארץ), היה גם בקושטא. נזכר ב\"באר עשק\" כ\"גדול הדור\". מתשובותיו ב\"כנסת הגדולה\". אולי אחיו - ר חיים."},{"i":37169,"n":"פואה, מנחם רפאל מאיטליה","b":"חיבר תפלות ושירים מיוחדים בקהלת קוני-איטליה-תקלו."},{"i":37170,"n":"פואה, משה דוד מאיטליה","b":"מחכמי איטליה-תקכד, רב בסיניגאליה-איטליה-תקל ופגש את החיד\"א בהיותו שם."},{"i":37171,"n":"פואה, נתנאל מריגיו","b":"רב בריגייו-ת\"כ"},{"i":37172,"n":"פוביאן, משה מקושטא","f":"אליעזר","b":"מחכמי קושטא-שח. תרגם ספר משלי ואיוב ליוונית."},{"i":37173,"n":"פוביני, אברהם שמשון לוי מטור","b":"רב בטורינו בזמן ר אס\"י מקזאלי ור\"י למפרונטי והר\"ש מורפורגו. תשובות ממנו ב\"פחד יצחק\" ו\"שמש צדקה\". הוסיף מראי מקום ל\"עין ישראל\" לר יהודה שמואל סיני."},{"i":37174,"n":"פוביני, שמואל אברהם לוי מאיטלי","b":"דיין בפיימונטי-תכ\"ד"},{"i":37175,"n":"פוברסקי, דוד מבני ברק","b":"ראש ישיבת פוניבז-בני ברק."},{"i":37176,"n":"פוגורלסקי, משה מרדכי מפאצפי","b":"רב בפוצ'יב(=פאצפי), עלה לארץ-תרצז. פרסם מאמרים ב\"יגדיל תורה\" - בוברויסק תרפח (תחת שלטון הקומוניסטים ברוסיה)."},{"i":37177,"n":"פוגל, אורי","k":"בעל דעת קדושים","b":"חיבר \"דעת קדושים\" למברג תרנז."},{"i":37178,"n":"פוגל, דובריש מבוצאץ","b":"מחכמי קיטוב-תרס."},{"i":37179,"n":"פוגל, חנוך זונדל מוישווה וצפת","f":"נפתלי","dt":"תרן","dp":"צפת","b":"תלמיד ר משולם איגרא מפרשבורג, ור מנחם מנדל מקוסוב ובנו ר חיים. רב באויבר-וישווה-תקץ בזמן הרב הראשון של העיר ר יוסף יוזפא הכהן וכיהנו שניהם ללא מינוי רשמי ובהמשך קיבל מינוי רשמי. עלה לצפת-תרכו ועל מקומו ר שמואל גינצלר."},{"i":37180,"n":"פוגל, יהודה אריה מצנסטחוב","b":"פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו."},{"i":37181,"n":"פוגל, יחיאל מיכל מריזאווליה","f":"אברהם משה מריסקווה","bt":"תרלט","dt":"תרצה - יד שבט","b":"נכד ר חנוך זונדל פוגל מאויבר-וישווה. תלמיד \"קדושת יו\"ט\" בסיגט, חתן ר מרדכי גרטנר מריזאווליה, רב ודיין בריזאווליה, מלמד בחצר האדמור ר חיים האגר מאטיניע לנכדו המיועד להוראה. דיין מומחה והגיעו אליו מכל ישובי הסביבה."},{"i":37182,"n":"פוגל, ישראל","b":"רב בזליחוב"},{"i":37183,"n":"פוגל, נתן מאג'סט מיקלוש","f":"מנחם מנדל מאורמין","dt":"תרסט - תשרי","b":"רב באורמין על מקום אביו. רב בנאג'סט מיקלוד-תרכט כ-40 שנה."},{"i":37184,"n":"פוגל, שלום מנרול","f":"מאיר","bt":"תרע","bp":"נרול","dt":"תשמה","b":"חסיד בלז. חתן ר משה פאליק הופנר מווריש. גורש לסיביר, חזר לפולין, פרג ואנטורפן שם שימש מלמד. בשנת תשט התמנה לגבאי של האדמור מבלז ושימש מנהל הישיבה."},{"i":37185,"n":"פוגלמן, אהרן זליג מקמפנא","f":"שמעון","b":"מחכמי קמפנא. הו\"ל ספר אביו \"שער שמעון\"."},{"i":37186,"n":"פוגלמן, גרשון ממריאמפול","b":"רב במריאמפול-תרף."},{"i":37187,"n":"פוגלמן, יהושע הלוי מסאמטור","b":"אב\"ד סאמטור. בנו ר שמעון-גיסו של ר עקיבא איגר מפוזנא (חתנו?)."},{"i":37188,"n":"פוגלמן, מרדכי מקטוביץ","f":"מנחם נחום מסקול","k":"בעל בית מרדכי","bt":"תרנט","bp":"פרימישלן","dt":"תשמד","b":"אחיינו של המהרש\"ם. רב ודוקטור - שלט בשמונה שפות, פרופסור בבית המדרש בפלורנץ. מנהל בית המדרש למורים בוילנא ומרצה לתלמוד בוארשא. חתן ר צבי יהודה לאו מלמברג. רב בקטוביץ-תרפח. ניצל מהשואה ועלה לארץ-תש. רב בקרית מוצקין. חיבר \"בית מרדכי\" ירושלים תשלא. אשתו בילה חיברה \"מבית אבא עד הלום\". פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"קול תורה\" - ירושלים תרץ-תשז."},{"i":37189,"n":"פוגלמן, שמעון הלוי","f":"יהושע מסאמטור","k":"בעל שער שמעון","b":"תלמידו וגיסו של ר עקיבא איגר מפוזנא. חתן ר משלם זלמן אשכנזי מלובלין. ראש ישיבה, רב בקאליש, ראגזן(=רוגזן)-תקפב, פארדן. התכתב עם גדולי דורו ובהם: גיסו, ר יעקב מליסא, בעל \"חמדת שלמה\", ועוד. חיבר 15 ספרים על הש\"ס ותשובות - בכת\"י, ורוב כתביו נשרפו. מכתביו נדפס ע\"י בנו ר אהרן זליגג מקמפנא - \"שער שמעון\" - וארשא תרמה, כן נדפס \"חדושי רבנו שמעון הלוי\" - תשכט."},{"i":37190,"n":"פוגלמן, שמשון ממריאמפול","f":"גרשון","k":"בעל אור האשכול","dt":"תשג","b":"רב במריאמפול(=מארימנט). חיבר \"אור האשכול\". פרסם ב\"אור המאיר\"."},{"i":37191,"n":"פוגלשטין, צבי הרמן מקניגסברג","k":"בעל הנהלת הבית בערי","bt":"תרל-ג","bp":"פילזן-בוהמיה","b":"אביו היה רב בשטעטין. תלמיד ביהמ\"ד לרבנים בברלין, וברסלוי, בעל תואר ד\"ר. רב באפלן-תרנה, קניגסברג-תרנז. חיבר \"הנהלת הבית בערי השדה בזמן המשנה\", השתתף בחיבור \"דברי ימי ישראל בעיר רומא\"."},{"i":37192,"n":"פוגרמנסקי, אברהם מרדכי מליטא","bp":"טאווריג","dt":"תשי","dp":"שוויץ - בני ברק","b":"נכד ר חיים סגל מיאנובה בעל \"אורח חיים\". תלמיד ישיבות טלז, קובנא. ניצל מהשואה ואחריה עבר לפריס ולימד חוג של תלמידי חכמים. נפטר צעיר."},{"i":37193,"n":"פוגרמנסקי, מאטל","b":"ר\"מ בהיידה"},{"i":37194,"n":"פוגרמסקי, מרדכי","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":37195,"n":"פודגירצקי, ליבוש צבי מקאהרליק","f":"מרדכי","bt":"תרז","b":"מצאצאי ר חיים רפפורט מלבוב. רב בקהרליק(=קאהרליק)-פלך קיוב-תרלה."},{"i":37196,"n":"פודהורצר, אליעזר יעקב מטרנופול","b":"שו\"ב בטרנופול-תרסד."},{"i":37197,"n":"פודהורצר, אלעזר יעקב מצפת","f":"יונה מטרנופול-צפת","bt":"תרך","bp":"צפת","dt":"תרפה","b":"מחכמי צפת ועסקן. בשליחות באוסטרו-הונגריה - תרמז. ממחדשי הישוב היהודי במירון ומגואלי ביהכנ\"ס שמעל קבר רשבי. יצג את הקהלה בפני השלטון. חתן ר רפאל זילברמן."},{"i":37198,"n":"פודהורצר, אריה ליבוש מטרמבובלה","f":"משה מהרימלוב","bt":"תקן","dt":"תרי","b":"רב באוזירן, טרנופול, טרמבובלה-תקפח. בנו ר יעקב שו\"ב בטרנופול."},{"i":37199,"n":"פודהורצר, יונה מטרנופול","f":"יעקב מטרנופול","bt":"תקעד","bp":"טרנופול","dt":"תרנד","dp":"צפת","b":"עלה לצפת-[תקצז] בהוראת האדמור מזידיטשוב. חתן ר יחיאל אשר כהנא-שפירא מזלין. בשליחות בגליציה והונגריה. הדפיס ספר \"אמרי משה\" לזקנו. חתום על אגרות מטעם קהילת צפת."},{"i":37200,"n":"פודהורצר, יעקב מאוזירן","f":"משה מהרימלוב","b":"רב באוזירן על מקום אחיו - ר אריה ליבוש - שעבר לטרמבובלה."},{"i":37201,"n":"פודהורצר, משה אברהם מהרימלוב","f":"יעקב מטרנופול","k":"בעל אמרי משה","bt":"תקכ","dt":"תקצו","b":"רב בהרימלוב, עזב את הרבנות ועבר לטרנופול. חיבר \"אמרי משה\" צפת תרכו."},{"i":37202,"n":"פודהורצר, משה מצפת (פדהצור)","f":"אלעזר יעקב מצפת","bt":"תרמט","bp":"צפת","dt":"תשכב","dp":"תל אביב","b":"תלמיד הרידבז בצפת. עסקן ציבור. בהשפעתו ניצלו יהודי צפת בפרעות תרפט ותרצו. בשנת תשח - ראש העיר הראשון. חתן דודו ר אלעזר זילברמן. פרסם מאמרים בעתוני הארץ והגולה."},{"i":37203,"n":"פודהייצר, צבי הירש מלבוב","f":"יום טוב","b":"חתם-תל בפנקס קהלת לבוב, וחתימתו נתקיימה בידי הדיינים ר אברהם גרויפין ור אפרים בן שלום פרידמן."},{"i":37204,"n":"פודולבסקי, שלום","f":"ליבר","bt":"תרעא","bp":"הורודץ","b":"תלמיד ישיבת קוברין אצל ר פסח פרוסקין ור יוסף ליב נענעדיק, ישיבת מיר. נסמך מאת: ר פסח פרוסקין, ר שלמה מתתיה מקוברין, ר שמחה זליג מבריסק. רב בקהלת אנשי פאניזול בניו יורק-תרצח, קהלת \"תורה ואמונה\", ר\"מ בישיבת חפץ חיים בניו יורק. חבר אגודת הרבנים באמריקה."},{"i":37205,"n":"פודולסקי, שלמה מתל אביב","dt":"תשיט","b":"מרביץ תורה בתל אביב"},{"i":37206,"n":"פודולסקר, אברהם משדה לבן","b":"מג\"מ בשדה לבן-תק\"י"},{"i":37207,"n":"פודילא, שמואל מקהיר","b":"מחכמי קהיר, נזכר בספר הדרשות לר חיים חברייא. מתלמידי האר\"י הראשונים. חתם-שעה על קבלת עדות, עם ר אלעזר חאמי, ר משה עטייה, ור משה יונה. ונזכר בספר הדרשות לר שבתי ברכה."},{"i":37208,"n":"פודרביטל, אהרן מרדכי מקולשיץ","f":"[שמחה]","b":"שו\"ב בקולשיץ-תרפב, חתנו ר נפתלי צעלער על מקומו אחריו. רב על מקום ר אברהם אביש חיים בוך. נספה בשואה."},{"i":37209,"n":"פודרביטל, יחזקאל מיאסלו","b":"הכין ציור של המקדש וכליו עם הסכמת ר\"ש פירר - תרצח."},{"i":37210,"n":"פודרביטל, שמחה מקולשיץ","dt":"תש..","b":"רב בקולשיץ, ראש ישיבה ברישא. נספה בשואה."},{"i":37211,"n":"פודרובסקי, יעקב צבי מילובקה","f":"שלמה מקוברין","bt":"תרלב","bp":"קוברין","dt":"תרצא - ג תמוז","b":"תלמיד ישיבת סלובודקא. רב ביאלובקה-פלך גרודנא-תרסד. נסמך מאת: ר אליהו חיים מייזל, ר שמואל מוהליבר."},{"i":37212,"n":"פוהן מיכל מפונידאל","dt":"תש..","b":"רבה האחרון של פונידאל. נספה בשואה."},{"i":37213,"n":"פוהן, אליהו בן ציון מטריסק","f":"חיים מטריסק","dt":"תש..","b":"רבה האחרון של טריסק(=טרישקי) על מקום אביו לאחר ר ישראל יהושע סגל מלמד. נספה בשואה. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":37214,"n":"פוהן, חיים מטריסק","dt":"תשג","b":"רב בטריסק(=טרישקי)-תרנא ובנו ר אליהו גם הוא רב בטריסק אחריו (לא על מקומו), רבה האחרון של פראן. נספה בשואה."},{"i":37215,"n":"פוהן, יעקב מבאזעלאן","dt":"תשג","b":"רב בבאזעלאן"},{"i":37216,"n":"פוור, אליעזר מזולקוא","f":"יעקב קופל מטרנופול","b":"סופר הקהלה בזולקוא-תקנד. הביא לדפוס \"תיקון השלחן\" זאולקוא תקסד. חלוץ הספרות העעמית היהודית באידיש וביניהם - \"מלחמה בשלום-מחזה מחיי יוסף ואחיו\" מאת ר חיים אברהם ממוהילב."},{"i":37217,"n":"פוזיצר, שמואל מבריסק","dt":"תרא - כט תשרי","dp":"בריסק","b":"רב בבריסק. נספד ב\"נחלי מים\". יש אומרים תאריך פטירתו - תקצח."},{"i":37218,"n":"פוזן, אליהו","b":"רב בוורשנה-תקמ\"ו,לנצבורג"},{"i":37219,"n":"פוזן, גרשון","bt":"תריג","dt":"תרצג","b":"דומ\"צ בפרנקפורט-תרמ\"ג"},{"i":37220,"n":"פוזן, יעקב מרנזיבורג","f":"אריה ליב מפוזן","b":"נשלח ע\"י ר רפאל הכהן מהמבורג לכהן כמו\"צ ברנזיבורג(=רנדסבורג)-ליד אלטונא-תקלו, מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג."},{"i":37221,"n":"פוזן, שלמה מפרידברג","b":"מחכמי פפד\"מ. רב בפרידברג-תקנג על מקום ר שמואל פופרש."},{"i":37222,"n":"פוזן, שמעון ישראל מניו יורק","f":"גרשון","dt":"תשכט - כא ניסן","b":"תלמיד ר יואל פלנר מבעלעד ואויהל ותלמיד האדמור ממונקטש בעל \"מנחת אלעזר\". רב בעדנבורג-תרצ\"ב, שאפראן, אחרי השואה בארה\"ב, חתנו ר צבי הירש על מקומו אחריו, וחתנו ר אליהו פולק רב בואטקעט. הסכים על \"הפלפול\" - שאפראן תרצח."},{"i":37223,"n":"פוזנא, אליעזר מפפד\"מ","f":"גרשן מפפד\"מ","bt":"תרנג","dp":"תשל","b":"תלמיד ישיבת רש\"ז ברויאר בפפד\"מ ופאפא. דיין בפפד\"מ-תרצג, ברח להולנד, ומשם ללונדון וכיהן כדיין-תשד."},{"i":37224,"n":"פוזנא, גרשון מפפד\"מ","f":"אליעזר ליזר בן יעקב","b":"דיין בפפד\"מ. בנו - ר אליעזר מפפד\"מ ולונדון (נפטר - תשל)."},{"i":37225,"n":"פוזנא, יעקב מפפד\"מ","b":"דיין בפפד\"מ אצל בעל ההפלאה. בנו - ר יעקב, נכדו - ר גרשון מפפד\"מ."},{"i":37226,"n":"פוזננסקי, אליהו","f":"שמואל שרגא פיבש","bt":"תרם","b":"תלמיד ר אברהם ברנשטין מסוכטשוב. רב בחאטש-פלך וארשא-תרסז."},{"i":37227,"n":"פוזנסקי, שמואל אבא","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":37228,"n":"פוזנר, דוד","f":"דב בער מירלש","b":"נכד ר משלם זלמן מירלש מאה\"ו. בנו - ר שמואל צבי."},{"i":37229,"n":"פוזנר, דוד טבלי מקורטשין","f":"הירץ","k":"בעל ילקוט דוד","b":"מגדולי חכמי קורוטשין-שנת ת', חיבר גם \"שערי ציון\"."},{"i":37230,"n":"פוזנר, הרץ מפוזנא","b":"מגדולי חכמי פוזנא"},{"i":37231,"n":"פוזנר, חיים מוארשא","f":"שמואל דב","bt":"תרל","dt":"תשג","b":"רב בניישטט-תרנו, מו\"צ בוארשא-תרסו. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":37232,"n":"פוזנר, ישראל מקלוואריה","f":"דוד","bt":"תרפז","bp":"קלווריה","b":"תלמיד כתר תורה דרדומסק בקראקא. ניצל מהשואה. עלה לארץ דרך קפריסין. ממיסדי מושב קוממיות. חסיד גור. גזבר קרן השביעית."},{"i":37233,"n":"פוזנר, מאיר מדנציג","f":"יהודה ליב","k":"בעל בית מאיר","bt":"תפט","dt":"תקסז","b":"ישב אצל חותנו בפוזנא-(בפרבר שלאנק). עבר לליסא ולמד עם ר דוד טעביל מליסא. פוסק, מגדולי חכמי דורו, אב\"ד מזריטש-תקכג, דנציג-תקס ושו\"ב (=שוטלנד, לאנגפור, וינבערג). בין השואלים אותו היה ר עקיבא איגר. נשא ונתן עם ר אברהם דנציג בעל חיי אדם. חתנו - ר יהודה מראויטש(=ראביטש)."},{"i":37234,"n":"פוזנר, מרדכי","f":"ברוך","dt":"תקפג - יח אדר","b":"רב באוארשא"},{"i":37235,"n":"פוזנר, משה ישראל מדוברובנא","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":37236,"n":"פוזנר, נחמיה מקשנוב","b":"רב בקשנוב-תקפח על מקום רבו ר שלמה בוכנר. נכדו - הרב פרומר מקוזיגלוב."},{"i":37237,"n":"פוזנר, נתן מנוידואהר","b":"רב בנובידוואהר-תר\"כ"},{"i":37238,"n":"פוזנר, עקיבא ברוך מירושלים","k":"בעל סדר ברכת הלבנה","bt":"תרנ","dt":"תשכב - ב אייר","b":"רב בקיל-תרפ\"ד,עלה לירושלים-תרצ\"ד"},{"i":37239,"n":"פוזנר, שלום מלינדען","b":"תשובה ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":37240,"n":"פוזנר, שלמה דוד מארה\"ב","k":"בעל אשד הנהר","bt":"תריב","dt":"תרצה - טו אב","b":"רב בג'רסי סיטי-ארה\"ב-תרסז. חיבר \"אשד הנהר\" נ\"י תרצב, פרסם מאמרים ב\"המצפה\" - נ\"י תרע. ?? לא באוצר ??"},{"i":37241,"n":"פוזנר, שלמה הלוי","b":"רב-שנת תר\"ך"},{"i":37242,"n":"פוזנר, שלמה זלמן מוארשא","bt":"תקם","dt":"תרח - כא ניסן","dp":"פלונסק","b":"גביר מחכמי וארשא, התישב בכפר קוהארי שאותו קנה והקים שם בית חרושת לבדים כדי לספק עבודה ליהודים, וכן ישב על אדמתו אכרים יהודים - באחוזותיו ישבו כ-500 יהודים. יסד בית מדרש בביתו ובין הלומדים שם: ר ישראל יהושע מקוטנא, ר חיים ריינרד ואסרצוג, ר מרדכי כהן גרינבוים מסערפץ, ועוד. סירב לרבנות וארשא על מקום ר שלמה ליפשיץ בעל \"חמדת שלמה\"."},{"i":37243,"n":"פוזנר, שלמה מאושפיצין","b":"רב ומלמד תורה באושפיצין. פרסם מאמרים ב\"כתר תורה\" - אושפיצין תרצט."},{"i":37244,"n":"פוזנר, שמואל צבי","f":"דוד","b":"נינו של ר משלם זלמן מירלש מאה\"ו."},{"i":37245,"n":"פוזנרזון, נתן מוונגרוב","b":"מחסידי האדמור ר מנחם מנדל מקוצק ובנו ר דוד. דיין בפלוצק, אב\"ד נובידבור(=נאוידואהר), ליטומירסק, וונגרוב. מחדושיו על הש\"ס נדפס \"אבות דרבי נתן\" בסוף ספר \"מחשבות ישראל\"."},{"i":37246,"n":"פוחוביצר, יהודה ליב מפינסק","f":"יוסף","k":"בעל קנה חכמה","bt":"שצ","bp":"פינסק","dt":"אחרי ה'תס","dp":"ירושלים","b":"תלמיד ר נפתלי בן יצחק כץ רבה של פינסק, היה רב בביחוב וכנראה שימש גם ברבנות בפוחויצה ומכאן שמו, לאחר פרעות תח תט חזר לפינסק וכיהן כרב בפינסק ובנו ר אליהו על מקומו אחריו. עלה לירושלים דרך ונציה. בהיותו בהמבורג נפגש עם ה\"חכם צבי\" והתידדו. חיבר \"קנה חכמה\" פפדא תמב, \"דרך חכמה\", \"דעת חכמה\", \"קנה חכמה\", \"כבוד חכמים\", \"דברי חכמים\", ועוד.","bk":[["דברי חכמים",""]]},{"i":37247,"n":"פוטערפוס, יחזקאל ממינסק","f":"גבריאל","b":"נכד הגאב\"ד מדולהינוב. מחכמי מינסק. בנו - הגביר ר משה ממינסק."},{"i":37248,"n":"פוטפוביץ, אברהם צבי מלינטופא","f":"יהודה","bt":"תרכז","bp":"אנטיפאליא-פלך גרודנא","b":"תלמיד כולל קובנא. רב בלינטופא-פלך וילנא-תרנז. נסמך מאת: ר שלמה הכהן מוילנא, ר משה שפירא מריגא, ר יוסף שלויפר מסלונים."},{"i":37249,"n":"פוטרמן, בנימין מאילוקסט","bp":"וילנא","b":"רב באילקוסט-תרכו על מקום ר ביינש ור מרדכי מרגליות על מקומו אחריו, ארוצישיק-פלך שוינציאן-תרלד."},{"i":37250,"n":"פוטרניק, חיים מבוקובסק","f":"ישכר בריש מבוקובסק","k":"בעל ספורים חדשים","bt":"תרם","dt":"תשב","b":"מלמד תלמידים בבוקובסק. חיבר ספרים ממה שנתחדש לו בזמן לימודו. חיבר \"ספורים חדשים\" מונקטש תרסט, ועוד."},{"i":37251,"n":"פוטשר, יהודה ליב הלוי מטיטשין","b":"רב בטיטשין-תרנב."},{"i":37252,"n":"פויאן, משה מקושטא","b":"מחכמי קושטא ומלמד תורה - בשנות ה-ש'. תרגם ליונית ספר משלי ואיוב ונדפסו."},{"i":37253,"n":"פויבר, אורי מפרג","k":"בעל שום שכל","dt":"תטז - ד חשון","b":"דומ\"צ בפרג"},{"i":37254,"n":"פוייטו, יהודה","f":"יעקב","b":"תשובה ממנו ב\"דבר שמואל\"."},{"i":37255,"n":"פוייטו, יוסף","k":"בעל קיצור ראשית חכמה","b":"מקובל-ש\"מ"},{"i":37256,"n":"פוייטי, יעקב מאיטליה","k":"בעל קיצור ר\"ח","b":"מחכמי איטליה. חיבר קיצור ר\"ח, ודרשות, והספד על פטירת ר יוסף קארו."},{"i":37257,"n":"פויכטוונג, דוד מניקלשבורג","f":"מאיר פויכטוונג","b":"נואם,רב בניקלסבורג-תרנ\"ב,רב בווינה-תרס\"ג,הרב הראשי בווינה-תרפ\"ז"},{"i":37258,"n":"פויכטוונג, מאיר מנייטרא, ניקלב","dt":"תרמח","b":"רב בעטנגן, נייטרא-תרך, ניקלבורג-תרכא."},{"i":37259,"n":"פויכטונגר, אשר-ואשתו פרחה ששון","b":"חתן דוד ששון מבומבי ולונדון, אשתו פרחה היתה מלומדת מפורסמת. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":37260,"n":"פויסט, אהרן מלעסלא","k":"בעל ציון לדרוש","b":"שו\"ב מחכמי לעסלא. חתן ר שרגא פיביש פרנקל. עבר לקראקא-תרכו ופתח בית מסחר לספרים - רצה להקים את הספריה הגדולה בעולם. חיבר \"ציון לדרוש - דורש לציון\", ועוד. כמו כן הוציא רשימות וקטלוגים של ספריו שהופצו ברחבי העולם."},{"i":37261,"n":"פויר אליעזר בן יעקב קופל","bt":"1760","dt":"ה'תקפ 1820","bk":[["גדולת יוסף",""]]},{"i":37262,"n":"פוירשטין, אלכסנדר סנדר","f":"יעקב מפרהינסק","k":"בעל דברי אסף","bt":"תרפה","bp":"דיסבורג","dt":"תשס","b":"ניצל מהשואה ועבר ללונדון. תלמיד ישיבת ר משה שניידר. מנהל יסודי התורה. עלה לירושלים-תשנא. חיבר \"דברי אסף\" ירושלים תשסג."},{"i":37263,"n":"פוכר, שלמה ממיטאוי","f":"פייטל","bt":"תקצג","bp":"ניישטט-שאקי(=ולדיסלב)","dt":"תרנט","dp":"ריגא","b":"תלמיד ישיבת יורבורג, ביהמ\"ד לרבנים בוילנא. רב מטעם במיטאוי-קורלנד, ריגא-תרנג. פעל כנגד המסיון בפלך קורלנד, ופעל כנגד המומר גורלנד. פעל לשיפור מצבם החוקי של יהודי קורלנד. רב מטעם בריגה-1893. חברת \"מפיצי השכלה\" יסדה קרן על שמו לתמיכה ברבנים וסופרים זקנים, ומשפחתם. פעל לבנין ביהכ\"נ הגדול במיטאוי."},{"i":37264,"n":"פולאגי, חיים מאזמיר","b":"רב באיזמיר"},{"i":37265,"n":"פולאגי, מרדכי מירושלים","dt":"תצט","dp":"ירושלים","b":"מחכמי ירושלים, נספד על ידי ר ישראל יעקב אלגזי בספר \"שארית יעקב\"."},{"i":37266,"n":"פולאצק, אברהם מבוסקוביץ","k":"בעל יפה נוף","bt":"תקנט","bp":"פרערוי-מורביה","dt":"תרמד","dp":"בוסקוביץ","b":"תלמיד ר משה פרלס בקויטיין, ר גבריאל אנגלסמן מנובומסטו. אב\"ד פרערוי-תקפט, וייסקירכן-תקצד, בוסקוביץ-תר, רב ראשי במורביה-תריא וראש ישיבה. יצא נגד אספת הריפורמים בברושוויג."},{"i":37267,"n":"פולאקו, אלקנא מקושטא","f":"יעקב","b":"רב בקושטא בזמן הרא\"ם."},{"i":37268,"n":"פולאקו, חיים הלוי מחברון","bt":"תקי","dt":"תר-תרה","b":"אחיו של ר אליעזר ירוחם וילנא-אלישר? פקיד חברון - תקמח-תקצח, מחכמי חברון, בקי בירושלמי על פה, בשנת תקן הסכים על ספר \"שמן המור\", בשנת תקנה חתם על כתב שליחות ר אברהם רוביו ועוד, בשנת תקץ על אגרת שליחות ר יוסף עייאש ובשנת תקצה על אגרת המלצה לר מנחם בורלא. סופר עליו שידע תלמוד ירושלמי בעל פה."},{"i":37269,"n":"פולאקו, יוסף הלוי מחברון","b":"מחכמי חברון, חברו של החיד\"\"א המזכירו בספריו."},{"i":37270,"n":"פולבסקי, דב בר","dt":"תשג","b":"רב בוועד הרבנים בווילנה"},{"i":37271,"n":"פולבסקי, נח נפתלי מקוברין","f":"ישראל יעקב מקוברין","k":"אדמור מקוברין","bt":"תקצו","dt":"תרמט - כו אב","b":"נכד ר משה פאליר מקוברין. חתן דודו ר ברוך חיים לוין ממינסק-חתנו של ר משה מקוברין. אדמור מקוברין על מקום זקנו לחלק מחסידי קוברין. חיבר \"ברכות לעד\" בתוך \"אמרות טהורות\". ?? לא באוצר ??","bk":[["ברכות יצחק \\ ברכת יצחק",""]]},{"i":37272,"n":"פולגאר ן, יצחק מבורגוס - ספרד","f":"יוסף מספרד","k":"בעל עזר הדת","b":"מחכמי ספרד בבורגוס בדור שאחר הרשב\"א. היה ידיד נעורים למומר אבנר מבורגוס בעל \"מנחת קנאות\" וחיבר כנגדו \"איגרת החרפות\" המומר השיב לו ב\"תשובות למחרף\" ור יצחק חיבר ספר \"עזר הדת\" להסברת היהדות."},{"i":37273,"n":"פולד (פולדא), אהרן מפפד\"מ","k":"בעל בית אהרן","bt":"תקנא","dt":"תרח","b":"תלמיד ר פנחס הורביץ בעל ההפלאה. רב וגביר בפפד\"מ. דיין אצל ר זלמן טריר ור בער אדלר, ועסק בעניני חיזוק הדת בפפד\"מ יחד עם ידידו ר דב בער אדלר, ושלחו איגרת הסכמה לר זכריה פרנקל-תרה - שעזב את ועידת הרבנים בפפד\"מ כמחאה על הריפורמה. היה בקשרי מכתבים עם החת\"ס, ר עקיבא איגר, ועוד. מגדולי הלוחמים בריפורמים בדורו. חיבר קינה על אסיפת הריפורמים בבראונשויג-תרד (בה הוחלט על היתר לשאת נוכריה, ועוד). (באוצר הרבנים תאריך פטירתו - תרכא - כה כסלו)"},{"i":37274,"n":"פולד, אכילס מפאריס","bt":"1800","bp":"פאריס","b":"מדינאי וכלכלן בפאריס, פעל לעזרת היהודים בעלילת הדם בדמשק (שבה היה מעורב קונסול צרפת בדמשק)."},{"i":37275,"n":"פולד, ל. מפפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":37276,"n":"פולדא, אליהו מפולדא","f":"יהודה ליב מוישניצא","dt":"תפה","b":"רב בפולדא. חיבר פירוש על הירושלמי."},{"i":37277,"n":"פולדא, דוד טבלי מפפד\"מ","f":"יצחק","dt":"תנא - טו אלול","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":37278,"n":"פולדא-ניימרק, נתן מפפד\"מ","f":"מרדכי גימפל","dt":"תקלב - יח טבת","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":37279,"n":"פולווערמאכער, יוסף הלפרין","b":"חתן ר אהרן מגזע צבי מלונטשיץ."},{"i":37280,"n":"פולופ, פנחס הכהן מפרטיוש","b":"חתנו - ר יוסף הלוי ברגר מסאמאש-אויוואר."},{"i":37281,"n":"פולטורנו, אלחנן מאיטליה","b":"מחכמי לומברדיה-ר'. אבי משפחת פולטוראני באיטליה."},{"i":37282,"n":"פולטינוב, אברהם יהודה מדטנובה","f":"חיים אליהו","bt":"תרמ","dt":"תשא","b":"רב בטרסקוב, דטנובה ור משה אהרן קושלבסקי על מקומו אחריו, וישטיניץ על מקום ר יצחק אלחנן נידרלנד, וילקוביסק. נספה בשואה."},{"i":37283,"n":"פולטרק, מוניע מלמברג","b":"מחכמי למברג. מתורתו ב\"חוטים המשולשים\"."},{"i":37284,"n":"פולטשק, דוד מלאשאנץ","f":"אברהם","bp":"דיאנדיאש","b":"תלמיד הכת\"ס. רב בלאשאנץ-טוגאר."},{"i":37285,"n":"פוליאב, משה אהרן מניו יורק","f":"ישראל בן צבי","k":"בעל מחנה ישראל","bt":"תרמח","bp":"טימקוביץ-פלך מינסק","b":"תלמיד ישיבת סלוצק, ונסמך מאת ר איסר זלמן מלצר. חתן ר אברהם הופמן. רב קהלת אהבת צדק אנשי טימקוביץ בניו יורק-תרפא, ראש ישיבת יצחק אלחנן בניו יורק. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"המסלה\" - נ\"י תרצו, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן, \"תלפיות\" - נ\"י תשד. חיבר \"אור השמש\" ניו יורק תשיט, \"אורח מישור\" תשט, \"באר אברהם\" נ\"י תרצט. חבר אגודת הרבנים באמריקה."},{"i":37286,"n":"פוליאבסקי, אברהם מארה\"ב","b":"רב בפואבלו-קולורדו-תרעב. פרסם מאמר כנגד השינויים בסדרי הלוחות."},{"i":37287,"n":"פוליאק, חייםזליג הלוי","bt":"תרמג","b":"רב בדליאטיץ-תרס\"ג,ניישטט-תרס\"ח"},{"i":37288,"n":"פולידור, משה משלוניקי","dt":"תקם","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה."},{"i":37289,"n":"פוליט, חיים נסים","b":"מחכמי ורבני איזמיר,חתנו של ר' אברהם פאלאג'י,כתב הספד עליו בספר \"אברהם את ידו\""},{"i":37290,"n":"פוליטי, יום טוב מאזמיר","bt":"תרנד","bp":"מאגנסיה","b":"מראשי הקהלה באזמיר, פעיל צבור ומארגן מוסדות צדקה וחסד."},{"i":37291,"n":"פולייסי, שמשון"},{"i":37292,"n":"פוליישי, דוד משלוניקי","dt":"תכט","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":37293,"n":"פוליכרון מקושטא ואזמיר","f":"יצחק קלמן","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע, אזמיר-תצג אצל ר יונה ור דוד חזן."},{"i":37294,"n":"פולינו די, חננאל מאיטליה","b":"מומר באיטליה, הלשין עם חבריו על התלמוד, וכתוצאה מההלשנה נשרף התלמוד-שיד."},{"i":37295,"n":"פוליץ, משה מניקלשבורג","bt":"תמ","dt":"תקכ","b":"רב בלונדנבורג,ניקלסבורג-תקי\"ג,רב מדינת מהרן-תקי\"ח"},{"i":37296,"n":"פוליצ'וק, שלמה מביאליסטוק ונ\"","f":"יוסף","k":"העילוי ממייצעט","bt":"תרלח","bp":"מייצ'ט-פלך גרודנא","dt":"תרפח - כא תמוז","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין בגיל 12! והנציב כינהו כ\"עילוי ממייצ'ט\", כשנסגרה הישיבה עבר עם רבו ר חיים סולוביציק - שהחשיבו הרבה - לבריסק, תלמיד ישיבת סלובודקה, ואצל ר שמחה זיסל בקעלם, וילנא בקיבוץ של ר חיים עוזר. ר\"מ בישיבת לידא. ראש ישיבת לידא-תרסג, בזמן מלחה\"ע ה-I ייסד ישיבה בקירובה(=יליזבטגרד=יעליסאועטגראד), ר\"מ בישיבת תחכמוני בביאליסטוק, עבר לארה\"ב וכיהן כראש ישיבת \"רבי יצחק אלחנן\" בניו יורק-תרפא. מחדושיו נדפס \"חדושי העילוי ממייצעט\". מתורתו ב\"מלכי בקדש\". פרסם מאמרים ב\"מגדל תורה\" - נ\"י תרפה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן. נספד ב\"אידנו\" נ\"י תרפט."},{"i":37297,"n":"פוליקאר, רחמים יצחק אברהם","b":"דיין באדרינופול-עד שנת תקעא. הניח חדושים בכת\"י וחלקם נדפסו בספר חתנו - ר יצחק טרני."},{"i":37298,"n":"פוליקנסקי, יהודה ליב לואיס","f":"יחזקאל יצחק","bt":"1881","bp":"וילנא","dt":"1947","dp":"תל אביב","b":"היגר לדרום אפריקה-1900. יסד עם אחיו פנחס את תעשיית הסיגריות \"האחים פוליקנסקי\". עסקן ציוני ותורם למפעלים ציוניים רבים. ביקר בארץ-1909, עלה לארץ-1929 והקים ביח\"ר לסיגריות \"דובק\". השתתף ביסוד \"גן רווה\"-ליד נס ציונה."},{"i":37299,"n":"פוליקר, רחמים יצחק אברהם מאדרי","b":"רב באדרינופול-תקע בערך."},{"i":37300,"n":"פולישוק, משה סגל מלייפניק","b":"תלמיד ר פנחס ליב מאויבן ישן (פריידיגר?)."},{"i":37301,"n":"פולמן, חנוך הניך מפיעטרקוב","b":"מדפיס בפיעטרקוב. הדפיס קובץ \"בית מאיר\" - תרצא - של ישיבת אוסטרובצה."},{"i":37302,"n":"פולמן, יהודה ליב"},{"i":37303,"n":"פולנסקי, אברהם ליב מדינילוביץ","b":"רב בדינילוביץ-פלך וילנא-תרע. בנו - ר מאניש איסר מאלשאן."},{"i":37304,"n":"פולנסקי, אברהם מקלניבלט","b":"רב בקלניבלט(=קאלניבלאט). בנו - ר שמשון אהרן מטעפליק וירושלים, חתנו - ר משה צבי רבינוביץ מקאלינבלאט (על מקום חותנו?)."},{"i":37305,"n":"פולנסקי, אהרן מקאלניבלאט","f":"שמואל מקאלניבלט","b":"גיסו של ר ישראל נחמן הלפרין מזוינירודקא. חתן ר דניאל דוד מטשיטשלניק בן ר שמריל מוורחיבקא. מצאצאיו ר שמשון אהרן פולונסקי מטעפליק."},{"i":37306,"n":"פולנסקי, איסר מנוס","dt":"תשג","b":"רב בליבוי"},{"i":37307,"n":"פולנסקי, אליהו פנחס מקלניבלט","f":"אהרן מקאלניבלט","b":"חתן ר אריה ליב מבענדר בן שמעון שלמה מסאווראן. בניו ר דוד שמואל-חתן ר אליעזר ליבר מקאדני, ר מנחם נחום מקאלניבלט-חתן ר איריה ליב מליטין."},{"i":37308,"n":"פולנסקי, דוד שמואל","f":"אליהו פנחס מקאלינבלט","b":"חתן ר אליעזר ליבר מקאדני. אביו של ר לוי יצחק מניגרשט."},{"i":37309,"n":"פולנסקי, מאניש איסר מאלשאן","f":"אברהם ליב מדנילביץ","bt":"תרמב (תרמג)","bp":"דאנילביץ-פלך וילנא","dt":"תשא-ב","b":"תלמיד ישיבת סלונים, לידא. נסמך מאת ר יצחק יעקב ריינס. חתן ר מאיר רבינזון מרדושקביץ. רב בדקשיץ, אולשן(=אלשאן)-פלך וילנא-תרסז, מו\"צ ברדיאנסקי, רב בשוונציאן(=סווינציאן)-תרפב, ליבוא(=ליבאווא). נספה בשואה עם משפחתו וניצלו בתו שיינע קמינצקי מניו יורק ובנו - ר יוסף בפאריס."},{"i":37310,"n":"פולנסקי, מנחם נחום מקלניבלט","f":"אליהו פנחס מקאלניבלט","b":"חתן ר אריה ליב מליטין בן ר חנינא ליפא מחמלניק-תלמיד הבעשט. בנו ר אברהם יצחק מקאלניבלט ונכדו ר שמשון אהרן מטפליק."},{"i":37311,"n":"פולנסקי, שלמה אהרן מירושלים","b":"ר\"מ בישיבת \"רבנו חיים יוסף\" בירושלים. מעורכי \"תורת בית הוראה\" - ירושלים תשג."},{"i":37312,"n":"פולנסקי, שמואל מקלניבלט","f":"מרדכי געליש בן משה","k":"אדמור מזאוינרודקא","dt":"תקעב - ד כסלו","b":"חתן ר פנחס מקוריץ. אדמור בזאווינרודקא, עבר לקאלניבלאט-תקנג וכיהן כרב הגליל ובו הקהלות טולנא, שפולא וקיילרקא ובנו ר אהרן על מקומו אחריו. חתנו ר ישראל נחמן הלפרין רב בזווינירודקא על מקומו וחיבר חדושים על התורה ובה מחדושי חותנו - בכת\"י."},{"i":37313,"n":"פולנסקי, שמשון אהרן - הטעפליקר","f":"אברהם יצחק מקלינבלט","k":"בעל דברי אהרן","r":"רב בטעפליק ובסוף ימיו רב בשכונת בית ישראל","bt":"תרלו","bp":"ויהלין","dt":"תשח - כח סיון","dp":"ירושלים","b":"רב במיידווין(=מידובה)-פלך קיוב-תרנו, טעפליק-תרסא (ועל שמה נקרא), עלה לירושלים-תרפב והיה רב בשכונת \"בית ישראל\". מתורתו נדפס \"דברי אהרן\". הו\"ל \"אהל תורה\" - ירושלים תרפו, יחד עם ר ישעיהו זאב וינוגרד. מעורכי \"אוצר הפוסקים\" - ירושלים תשו.","bk":[["דברי אהרן - ש\"ס ופוסקים \\ חידושי הרב מטעפליק",""]]},{"i":37314,"n":"פולסטרו, יעקב מפליבנא","b":"פרנס מראשי קהלת פליבנא-שנות ה-ש'."},{"i":37315,"n":"פולסטרו, יצחק מקושטא","k":"בעל זכרון בירושלים","b":"מחכמי קושטא. חיבר \"זכרון בירושלים\" - קושטא תקג."},{"i":37316,"n":"פולסטרו, מנחם מליפאנטו","b":"רב בליפאנטו-שנות ה-ש'."},{"i":37317,"n":"פולסטרו, מנחם משלוניקי","b":"רב בשלוניקי בזמן מהרשד\"מ. חברו של ר משה חסי. היה במחלוקת עם ר יוסף פירמון - וחכמי הדור התערבו במחלוקת. שיר שלו ב\"אגדת שמואל\" לר שמואל אריפול."},{"i":37318,"n":"פולסטרו, משה מארטא-יוון","b":"רופא מחכמי ארטא-יוון בזמן ר שמואל קלעי - ר'-ש'."},{"i":37319,"n":"פולסטרו, שבתי משלוניקי","dp":"ירושלים","b":"חברו של ר יצחק טרויא. תלמיד ר יוסף איסקאפה ור דוד קונפורטי, מחכמי שלוניקי, עלה לירושלים תד ( או אחר פטירת אשתו-שעו.) ורב בחברון-תט. וחתם על התקנה לשחרור ת\"ח ממס-תו, חזר לירושלים ולימד תורה וכיהן כדיין עם ר ישראל בנימין ור ישראל עזריה זאבי. אשתו דונה נפטרה צעירה בשלוניקי שעו."},{"i":37320,"n":"פולסטרו, שמואל מפטרץ","b":"רב בפטרץ-שנות ה-ש'."},{"i":37321,"n":"פולץ, גרשון מניקלשבורג","f":"משה","dt":"תקלב - יז אד\"א","b":"אב\"ד בניקלשבורג-תקיג, רב המדינה-תקיח. נשא ונתן עם ר יחזקאל לנדא בעל \"נודע ביהודה\" שהזכירו בספרו. חתניו - ר יצחק רפפורט מלייפניק, ר חיים בן סעדיה ישעיה קצנלנבוגן ממזריטש."},{"i":37322,"n":"פולצקר, עזריאל","b":"רב בפאליצק-תק\"מ"},{"i":37323,"n":"פולצר, יעקב מצנסטחוב","b":"מחכמי ישיבת חכמי לובלין-תרצז."},{"i":37324,"n":"פולק גבריאל בן יצחק איזק","bt":"1803","dt":"ה'תרכט 1869","bk":[["חקי האלהים",""],["מראה גבר",""]]},{"i":37325,"n":"פולק יעקב בן יצחק","bt":"1470","dt":"ה'שא 1541","bk":[["פסק החרם",""],["פסק החרם של הרב יעקב פולק",""]]},{"i":37326,"n":"פולק לוי בן דוד","dt":"ה'תקסו 1806","bk":[["עמודי שיטים לבית הלוי",""]]},{"i":37327,"n":"פולק, אביגדור מסיגט","f":"יונתן","dt":"תרצו - יג שבט","b":"אחר פטירת אביו גדל אצל ר יוסף מאיר וייס האדמור מספינקא בעל \"אמרי יוסף\" (שנשא את אמו), והיה גם חתנו. רב ואדמור בברגסאס אחר פטירת חותנו, רב חסידי ספינקא בסיגט. בניו: ר יוסף מאיר רב בברגסאס, ר שמואל צבי - נספה בשואה, ר יהונתן בנימין נפטר תרצט."},{"i":37328,"n":"פולק, אברהם הלוי מאויהל","f":"דוד יהודה מלאפוש","dt":"תש - יג אלול","dp":"ירושלים","b":"תלמיד השב\"ס, וזקנו ר יצחק זעקל פולק ודודו ר משה הלוי פולק מבאניהאד. חתן ר זכריה מילר מאויהל. רב באויהל. עלה לירושלים-תרצה. בניו - ר יוסף אשר מוערפעלט, ר משה מלעוועלק, ר יצחק זעקל מדונא-פאלדוואר, ור זכריה מאראסי."},{"i":37329,"n":"פולק, אברהם הלוי מבאניהאד","f":"משה מבניהאד-וידבר מש","bt":"תרל-כו","bp":"מגנדורף","dt":"תשד - יח תמוז","b":"תלמיד השב\"ס, וזקנו ר יצחק זעקל פולק. חתן ר אברהם יונתן יהודה ליב קריצלר מבאניהאד. רב בבניהאד(=בוניהאד)-תרנז. נספה בשואה. הו\"ל ספרי אביו עם הוספות ממנו, פרסם מאמרים ב\"וילקט יוסף\". גיסו-בעל אחותו - ר ישעיה זילברשטין בעל \"ובתורה הזאת\"."},{"i":37330,"n":"פולק, אברהם חיים מאפטא","f":"אברהם מאפטא","dt":"שפג - ב-כ אלול","b":"נכד-אבי אמו המהרש\"ל, נולד אחר פטירת אביו וגדל אצל דודו ר אליעזר-אחיו של הרמ\"א וחתן המהרש\"ל. חתן ר משה ר יעקעלעס מקראקא. אב\"ד אפטא, וינה ואולי גם בניקלשבורג. מחותן עם בעל תוספות יום טוב. בניו: ר יצחק אייק מהורדנא, ר צבי הירש מלובלין, חתנו - ר יעקב טעמרילש מלובלין וקרמניץ בעל \"ספרא דצניעותא דיעקב\", ומצאצאיו כמה משפחות מיוחסות בישראל."},{"i":37331,"n":"פולק, אברהם מארה\"ב","b":"רב בפאקיפסי-ארה\"ב, מעקיספורט-פנסילבניה."},{"i":37332,"n":"פולק, אברהם מב'פורד","dt":"תרסג","b":"רב בב'פורד"},{"i":37333,"n":"פולק, אברהם מלובמלא","k":"בעל צפנת פענח","dt":"שמה - יא שבט","b":"מגדולי חכמי דורו,רב בלובמלא"},{"i":37334,"n":"פולק, אברהם מסעבען","f":"משה יהודה מבערעטי","b":"חתנו - ר אשר אנשל יונגרייז מזילאה."},{"i":37335,"n":"פולק, אברהם מפולין","f":"יעקב","b":"חתן ר יצחק בצלאל מלודמיר, ובזיוו\"ש חתן המהרש\"ל. מחכמי פולין(-אפטא?)-שן. הסכים על \"מתנות כהונה\", נזכר בשו\"ת הב\"ח החדשות. בנו ר אברהם חיים (נולד אחר פטירתו) נכד המהרש\"ל אב\"ד אפטא ווינה."},{"i":37336,"n":"פולק, אברהם מפתח תקוה","f":"יוסף מאיר מברגסאס","k":"אדמור מספינקא פתח תק","b":"נכד ר יוסף מאיר וייס האדמור מספינקא. לאחר השואה עלה לארץ וגדל אצל אביו חורגו ר אהרן מבלז, הקים בימ\"ד בפתח תקוה ע\"ש אביו חורגו. חתן ר מרדכי וובר. בנו ר יהושע הקים בימ\"ד בירושלים ע\"ש סבו ר יחיאל לאבין."},{"i":37337,"n":"פולק, אברהם מרוזינאי","f":"אריה ליב פולק","dt":"תפו - יא שבט","b":"מו\"צ ברוזינאי"},{"i":37338,"n":"פולק, אליהו יוסף ממינסק","f":"יעקב","dt":"תרמא - ד טבת","dp":"מינסק","b":"גביר במינסק, מראשי חברת \"פועל כפים\". מבניו - הגבירים ר משה, ר בנימין ממינסק."},{"i":37339,"n":"פולק, אליהו מניו יורק","f":"ישעיה מואדקערט","b":"רב בואדקערט-ברוקלין."},{"i":37340,"n":"פולק, אליעזר מבודפשט","b":"רב בבודפשט-תרלג."},{"i":37341,"n":"פולק, אליעזר מפיסרו","b":"תלמיד ר\"י ברונא, ר יעקב וייל, תלמידו או נכדו של ר דוד שווידניץ. מחכמי אשכנז-רן. התישב בפרג בזזמן ר אליהו מפרג והיה מחלוקת ביניהם בהתערבות גדולי הדור ובהם בעל \"תרומת הדשן\"."},{"i":37342,"n":"פולק, אשר הלוי מסטמר וגרוסורדי","f":"משה בן דוד יהודה","bt":"תרסב","b":"רב בקיראי-דארוץ-ליד סטמר, רב בבעלעניעש(=באלניש)-תרצב. ניצל מהשואה, ואחריה רב בגרוסורדין על מקום ר יצחק יעקב וייס. עלה לארץ-תשי וכיהן כרב בקרית אתא."},{"i":37343,"n":"פולק, בנימין וולף יאקרס מפרשבו","k":"בעל אסיפת בנימין","b":"רב בפרשבורג-תע. גיסו - ר אברהם ברוידא מפרג."},{"i":37344,"n":"פולק, בנימין וולף מאיזנשטט","k":"בעל אסיפת בנימין","dt":"תקכט - כח אב","b":"נכד ר בנימין וולף מפרשבורג. רב באייזנשטט. חיבר ביאור על הסמ\"ק בשם \"אסיפת בנימין\"-בכת\"י (ר\"י זלצר פרסם ב\"נטעי בחורים\" קטע מכתה\"י וקבע שהמדובר בזקנו ר בנימין וולף מפרשבורג ובעקבותיו הלכו נוספים - אך למעשה המדובר בחיבורו של הנכד)."},{"i":37345,"n":"פולק, בנימין ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":37346,"n":"פולק, בצלאל מפרשבורג וסילאג-צה","bt":"תקצח","bp":"פרשבורג","dt":"תרכג","b":"תלמיד ר עזריאל הילדסהימר באיזנשטט. חתן ר אשר אנשל ניימאן מוויצען, ועבר לשם. רבה הראשון של סילאג'-צה-תרכג. לתולדותיו - \"הגאון שנשכח\" ירושלים תשמב."},{"i":37347,"n":"פולק, דוד","f":"משה מסערדאוהל","b":"חתן ר וולף באנדא מסערדאוהל."},{"i":37348,"n":"פולק, דוד יהודה ממאדיאר-לאפוש","f":"יצחק זקל הלוי מבניהד","b":"נכד ר זעקל שפיץ מבאניהאד. תלמיד ר יהודה אסאד ובעל \"ייטב לב\". חתן ר אשר אריה שטסל מלאפוש ועבר לשם. מחכמי מאג'אר-לאפוש וראש הח\"ק כ-40 שנה. מתורתו בספר אחיו ר משה מבאניהאד בעל \"וידבר משה\". השיא את כל בנותיו לתלמידי חכמים ובהם ר יוסף ליב סופר מפאקש. בנו - ר אברהם פולק מאויהל-ירושלים. מחתניו - ר יוסף ליב סופר בעל \"ליקוטי סופר\"."},{"i":37349,"n":"פולק, דוד יהודה מסובאטה","b":"נכד ר דוד יהודה פולק מלאפוש. רב בקיראי-דארוץ. חתן ר גרשון מנדל קאהן מערדאסנזשארץ. רב בעיירת הקייט סובאטה-תרצז. נספה בשואה."},{"i":37350,"n":"פולק, דוד יהודה מראב","f":"ישעיה מואדקערט","bt":"תרע","dt":"תשד - יט שבט","b":"תלמיד הדעת סופר, ודודו ר שמעון גרינפלד מסעמיהאלי. חתן ר בנציון סנידרס מראב, ועבר לשם. רב בראב-תרצה בביהמ\"ד של רבי דניאל גרוס."},{"i":37351,"n":"פולק, דוד מדרזדין","b":"רב בדרזדין-תק\"פ"},{"i":37352,"n":"פולק, דוד ממיקסביץ","dt":"תשג","b":"רב במיקסביץ"},{"i":37353,"n":"פולק, הלל מסאסרגן","f":"אליעזר מאייבנשיץ","k":"בעל קודש הלולים","bt":"תקע","bp":"נייטרא","dt":"תרנג - א אדר","dp":"סאסרגען","b":"תלמיד החת\"ס, ולמד ביחד עם קרובו ר הלל ליכטנשטין. חתן הגביר ר יעקב בר פלדמן מכפר פעטרא-ליד מארגרטן, ועבר לשם ולמד עם גיסו ר יהושע אהרן צבי וינברגר. רב בכפר בודוש-ליד ביטריץ-תרך, רבה הראשון של סאסרגן-תרכז. הניח חדושים בכת\"י וציוה לשרוף את רובם. היה אחד מהעדים לגלוי אליהו עם החת\"ס. לתולדותיו ב\"מראה הבזק\""},{"i":37354,"n":"פולק, זכריה סגל","f":"אברהם","dt":"תשד","b":"רב באראסי"},{"i":37355,"n":"פולק, זליג הירש הלוי","dt":"תשג","b":"רב בקנישין"},{"i":37356,"n":"פולק, זלמן","f":"משה מסערדאוהל"},{"i":37357,"n":"פולק, חיים אברהם מברגסאס","k":"אדמור מברגסאס","bt":"תרן","dt":"תרצג - יג טבת","b":"חתן ר זלמן ליב בן משה מדרוהוביטש (שושלת זידיטשוב). רב ואדמור בברגסאס. חתנו ר נפתלי צבי לאבין בן ר סנדר ליפא - אדמור בניו יורק."},{"i":37358,"n":"פולק, חיים בנימין מסערעד","dt":"תר - כז שבט","b":"רב בטרענטשין, רב בסערעד על מקום ר משה מייזלש ור וולף פוקס על מקומו אחריו."},{"i":37359,"n":"פולק, חיים זליג מקנישין וניישט","f":"מנחם מנדל הלוי","b":"תלמיד כולל קובנא, ומלמד תורה שם, ממלא מקום הרב בדעליאטיץ-תרסג, רב בניישטאט-פלך מינסק, קניהניטש(=קנישין) לפני השואה. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו, \"ירושלים\" - וארשא תרצו."},{"i":37360,"n":"פולק, חיים יוסף מטרביטש","f":"שבתי","k":"בעל מקור חיים","bt":"תקנט","bp":"טרביטש","dt":"תרם - ב טבת","dp":"טרביטש","b":"נכד ר חיים טויסיג מטרביטש. תלמיד החת\"ס, ור אלעזר לעוו, ור אריה יהודה טויבר מגלנטא. חתן ר נתן נטע אסטריכר מטריטש ועבר לשם. רב בטרביטש-תקפט, בנו ר שמואל על מקומו אחריו. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך, \"אור תורה\" - לבוב תרלג, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":37361,"n":"פולק, יהודה ליב מזולקוא","f":"נתן","dt":"תקכד - טו אד\"ב","dp":"זולקוא","b":"דרשן בזולקוא, אחיינו - ר גדליה בן יצחק מליניץ המזכירו בספרו \"תשואות חן\"."},{"i":37362,"n":"פולק, יהודה ליב מפריישטטל","b":"דומ\"צ בפריישטטל-תרע\"ד"},{"i":37363,"n":"פולק, יהושע מסעבען","f":"משה יהודה ליב מבערטי","k":"בעל חושבי מחשבות","bp":"בערטי-אויפלו","dt":"תשא - תשו","dp":"סעבען","b":"תלמיד השב\"ס ור ישעיה הכהן רובין ממיהאלפאלוא. חסיד בלז. חתן ר מנחם אויסשפיץ. מחכמי סעבען-תרנד, הרמאנשטדט. הו\"ל ספר אחיו ר שמעון - \"שם משמעון\". ניצל מהשואה ונפטר כמה שנים אחריה. בנו ר מנחם וחתנו ר שלמה טסלר הו\"ל את ספרו \"חשבי מחשבות\" ובנו חיבר הקדמה לספרו."},{"i":37364,"n":"פולק, יהושע מפעטראווסלא","b":"מחכמי פעטראווסלע-תרכא. בניו - ר שרגא פייש מוויצען, ור מנחם מנדל מטורוק-בעטשע."},{"i":37365,"n":"פולק, יהושע עוזר מזענטא","f":"שמעון מזענטא","bt":"תרלה","bp":"זענטא","dt":"תשא - כה ניסן","dp":"זענטא","b":"תלמיד השב\"ס. חתן ר משה דייטש מטארנאליא. ראש הקהל בזענטא וראש לשכת היראים במדינת יוגוסלוביה. בנו ר שלום מערלוי(=אויהל)-לונדון בעל \"דברי שלום\", וחתנו ר אברהם סופר מלונדון."},{"i":37366,"n":"פולק, יואל מתל אביב","f":"שרגא פייש מוייצען","dt":"תשכג - יח אייר","dp":"תל אביב","b":"תלמיד השב\"ס. חתן ר עקיבא גינז-שלזינגר מוינה. רב בוינה. עלה לארץ-תרצט וכיהן כרב חוג חתם סופר בתל אביב ובנו ר יעקב יהודה על מקומו אחריו בירושלים."},{"i":37367,"n":"פולק, יונתן בנימין מספינקא","bp":"קראלי","dt":"תרכט - בערך","dp":"צאנז","b":"תלמיד הכת\"ס, והמכתב סופר. חתן ר עזרא יעקב באש מפסינקא ועבר לשם. נפטר צעיר, אלמנתו נישאה לר יוסף מאיר וייס האדמור מספינקא. בנו ר אביגדור - רב חסידי ספינקא בסיגט."},{"i":37368,"n":"פולק, יוסף אשר הלוי מוארפלט","f":"אברהם מאוהל","k":"בעל שארית יוסף אשר","bt":"תרנח","bp":"אוהל","dt":"תשד - כז אייר","b":"תלמיד הדעת סופר, ודודו ר יוסף ליב סופר מפאקש, ור יעקב יחזקאל גרינולד מצעהלים ופאפא. חתן ר יהודה אלטמן ממעזא-טשאטה, וכיהן כר\"מ בישיבת חותנו. בזיוו\"ש חתן ר משה טננבוים מוארפעלט (גיסו של חותנו הראשון ר יהודה אלטמן - בנושאו את אלמנת ר שלום דב פישל מוארפלט), רב בוארפעלט-תרפב על מקום חותנו וחתנו הראשון-ר פישל סלומון. ביקר בארץ-תרפט. נספה בשואה."},{"i":37369,"n":"פולק, יוסף יעקב מאויבן","b":"רב באויבן ישן, מכתב ממנו אל ידידו ר פנחס ליב פריידיגר-תריב."},{"i":37370,"n":"פולק, יוסף מאיר מברגסאס","f":"אביגדור מסיגט","bt":"תרע","bp":"ספינקא","dt":"תשא - ד אלול","b":"נתיתם בילדותו וגדל אצל דודו ר יצחק איזיק מספיקנא שהסמיכו לאדמור. חתן ר יחיאל חיים ממאקובה. תלמיד ר אהרן ראט האדמור מתולדות אהרן, שמינהו לרב בברגסאס על מקומו כשעלה לירושלים. נספה בשואה. אלמנתו שניצלה נישאה לאדמור ר אהרן רוקח מבלז, בנו ר אברהם אלתר גדל אצל ר אהרן מבלז. מתורתו ב\"זכרון צדיק\". חתנו - ר מנחם מנדל בן בנימין מנדלסון רב בקוממיות."},{"i":37371,"n":"פולק, יוסף שמעון מהרמאנשטט","f":"אברהם מהרמאנשטדט","k":"בעל ראשי בשמים-תשב","b":"חסיד בלז מחכמי הרמאנשטאדט, התכתב עם גדולי הרבנים בשאלות וחדושי תורה. חתן נכדת ר יצחק בעהם מקרלוה, ועבר לשם. עבר לסטמר והיה עורך הירחון \"בית ועד לחכמים\" - סטמר תרפב כ-20 שנה (ויצא כנגד האדמור מגור, האדמור ממונקטש, ור משה שמואל גלזנר - על שני האחרונים אמר שספריהם טעונים גניזה, והיה במחלוקת עם עורכי \"הבחור\" - דעווא תרפח (בין היתר האשים את עורכי \"הבחור\" בציונות), ופרסמו דברי פולמוס ביניהם.), והחל להדפיס אנציקלופדיה תלמודית בשם \"ראשי בשמים\" ח\"א סינער-ואראהל תשב. ב\"קובץ דרושים\" - פיעטרקוב תרפג - קריאה מרבני פולין להחרים אותו ואת \"בית ועד לחכמים\" - שיש להם דין של ספרי אפיקורסות, ביקורת כנגדו על שפגע באדמור מגור גם ב\"קול תורה\" - פאביאניץ תרפו. נספה בשואה."},{"i":37372,"n":"פולק, יעקב הלוי","f":"יצחק","k":"בעל ויקם עדות ליעקב","b":"אולי נכד ר יעקב בעל החילוקים. תלמיד המהר\"ל מפרג. מחכמי אשכנז-של. תשובה ממנו בענין עגונה - נדפסה בפרג שנד."},{"i":37373,"n":"פולק, יעקב הלוי מפולין וירושלי","f":"יוסף או יהודה או יצח","k":"בעל החילוקים","bt":"רל","bp":"פולין","dt":"רץ-שא - כא סיון","dp":"לובלין או ארץ ישראל","b":"מחכמי פולין, רב בפרג וראש ישיבה עם ר יעקב מרגליות (או בנו ר יצחק). תלמיד ר יעקב מרגליות בנירנברג. חתנו של ר משה בן אפרים פישל מקראקא, (שאשתו היתה מקורבת למלכה בונה, אשת המלך זיגמונד הראשון בקראקא). היה אב\"ד בפרג בשנת רנב, מתלמידיו ר שלום שכנא מלובלין (חותנו של הרמא), ומהר\"ם פאדובה. ר יעקב היה אבי שיטת החילוקים והפלפול. בגלל מחלוקת עבר לקראקא והיה בה רב וראש ישיבה. בשנת רפ עלה לארץ ישראל (ויש חולקים על כך, לדעת רוזניס הגיע לקושטא). לא חיבר ספרים אך הניח הגהות על גליונות ספריו ובהם על המרדכי, הסמ\"ג, והטור."},{"i":37374,"n":"פולק, יצחק זעקל הלוי","f":"אברהם","dt":"תשד","b":"רב בדונאפעלדוואר"},{"i":37375,"n":"פולק, יצחק זקל הלוי מבאניהאד","f":"אברהם מבאניהאד","k":"בעל ברכת יצחק","bt":"תקעג","bp":"באניהאד","dt":"תרנא - א תמוז","dp":"באניהאד","b":"נכד ר ישראל שפיץ מבאניהאד. תלמיד ר צבי הירש הלר בעל \"טיב גיטין\", החת\"ס - והיה לומד עמו בחברותא מדי לילה וגם למד עם הכת\"ס בחברותא, ור יעקב מאיר צבי פרידלנדר מבאניהאד. חתן ר חיים צבי אדלר מסערדאוהל ועבר לשם (בשידוכו של החת\"ס). רב בסערדאוהל ועמד בראש הישיבה שם, מאדיאר-לאפוש-תרלב, רבה הראשון של בניהאד-תרלד ועזר בניהול ישיבת בנו ר משה - ראש הישיבה שם, ועל מקום בנו אחריו (ר משה נפטר בחיי אביו - סירב לרבנות העיר על מקום בנו). (הביא מדברי \"טעם המלך\" בפני החת\"ס - שלא התיחס לדברים - ואח\"כ אמר כי המחבר הנ\"ל בפרג התנגד למנוי ר שמואל לנדא לאב\"ד פרג על מקום אביו ה\"נודע ביהודה\" - ומי יודע איזה קלקול לדורות נגרם בגלל זה)","bk":[["ברכות יצחק \\ ברכת יצחק",""]]},{"i":37376,"n":"פולק, ישעיה מגרוסורדין.","f":"יהודה","dt":"תרפה - כג תמוז","b":"חתן הגביר ר משה אולמן מגרוסורדין. רב בחברת ש\"ס בגרוסורדין, ובנו ר משה על מקומו אחריו."},{"i":37377,"n":"פולק, ישעיה מואדקערט","f":"ברוך מזענטא","k":"בעל דברי ישע","bt":"תרלא","bp":"זענטא","dt":"תשא - כב סיון","dp":"ואדקערט","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש, ור ישעיה זילברשטין מוויצען. חתן ר יהודה גרינפלד מסעמיהאלי ועבר לשם. רב בואדקערט(=שולד-ואדקערט)-תרסה ובנו ר משה מרדכי על מקומו אחריו. הו\"ל \"שם אפרים\" עם ביאוריו ועוד."},{"i":37378,"n":"פולק, ישראל הלוי ממאקווא","f":"משה מבאניהאד-ברכת מש","bt":"תרלד","bp":"באניהאד","dt":"תרצט - א דרה","dp":"בודפשט - באניהאד","b":"גביר תלמיד חכם. תלמיד השב\"ס. חתן ר יהושע בלוי ממאקווא, ועבר לשם. חיבר הקדמה לספר אביו \"ברכת משה\"."},{"i":37379,"n":"פולק, לוי מטריטש ושטמפן","f":"דוד ממטרסדורף","k":"בעל עמודי שיטים","bp":"מטרסדורף","dt":"תקסז - ז חשון","dp":"טריטש?","b":"תלמיד הנודע ביהודה בפרג - שגם הסכים על ספרו, ור יוסף ליברלש. רב בטריטש ומלמד תורה שם על מקום ר אברהם שפירא ור אלעזר רוקח בעל \"שמן רוקח\" על מקומו אחריו, שטמפן-תקנט. נפטר ללא ילדים. תשובה אליו בשו\"ת נודע ביהודה."},{"i":37380,"n":"פולק, ליב","b":"מוכיח-שנת ת\"ק"},{"i":37381,"n":"פולק, ליב מאויסע","bt":"תקמט","dt":"תקצב - ה שבט","b":"גדול בנגלה ונסתר,רב באויססע"},{"i":37382,"n":"פולק, מאיר מריטבא","b":"רב בריטבה-תר\"מ"},{"i":37383,"n":"פולק, מנחם הלוי מסערנטש ונ\"י","f":"אברהם מקלינורדין","k":"בעל חלק לוי","r":"רב בסערנעטש, ואח\"כ בביהכ\"נ חברה בחורים אנשי אונגרין","bt":"תרן","bp":"קלינורדין","dt":"תשיג - ה תשרי","dp":"ניו יורק","b":"תלמיד הדעת סופר, ר משה חיים ליטש-רוזנבוים מקלינורדין ועוד. חתן ר יצחק כהנא מסיניווער, ובזיוו\"ש חתן ר פנחס ביליצר מסערנטש. רב בסערענטש-תרעג על מקום חותנו. עבר לאמריקה וכיהן כרב \"אהבת ישורון\" בניו יורק-תש, ואהבת בחורים אנשי אונגרן שם, חתנו ר יהודה ליב למברגר על מקומו אחריו. חיבר גם \"עיון מנחם\" ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב.","bk":[["חלק לוי - שו\"ת וחידושים",""],["עיון מנחם - אגדות הש\"ס",""]]},{"i":37384,"n":"פולק, מנחם מנדל מטורוק-בעטשע","f":"יהושע מפעטראוסלע","b":"תלמיד השב\"ס. חתן ר שלמה קליין מזענטא. רב בזענטא, טורוק-בעטשע-תרסא על מקום אחיו - ר שרגא פייש פולק."},{"i":37385,"n":"פולק, מקס משופרון","dt":"תשד","dp":"אושוויץ","b":"רב הקהילה הניאולוגית בשופרון. הסטוריון וחיבר ספר על תולדות הקהילה. נספה בשואה."},{"i":37386,"n":"פולק, מרדכי מאיר מהעלישוי","bt":"תקץ","bp":"קאלין","dt":"תרנה - כו סיון","b":"תלמיד ר דניאל פרנק מקאלין ור גדליה טיקטין מברסלוי. משב\"ק אצל רבו הכת\"ס ומורה הבית. חתן ר יצחק יהודה ליב פריישטט מוינה. רב ברייניץ (וייסקירכן), העלישויא-תרכז, וינה-תרן."},{"i":37387,"n":"פולק, מרדכי משה מואדקערט","f":"ישעיה מואדקערט","b":"רב בואדקערט על מקום אביו. ניצל מהשואה."},{"i":37388,"n":"פולק, משה הלוי מבאניהאד","f":"יצחק זאקל מבאניהאד","k":"בעל וידבר משה","r":"אב\"ד בנאהרט (באהניד)","bt":"תרה","bp":"סערדאוהל","dt":"תרמט - ד חשון","dp":"באניהאד","b":"תלמיד הכת\"ס, ר יהודה אסאד, ור עזרא צורף מסערדאוהל. חתן ר אליעזר צבי הרש לוינגר ממאגנדורף בעל \"בני לוי\" ועבר לשם. רב הקהילה החרדית בבניהאד-תרלב וראש ישיבה שם - ואביו מסייע על ידו ור יהודה גרינוולד בעל \"זכרון יהודה\" על מקומו אחריו - (אביו סירב לרבנות ובנו ר אברהם היה צעיר מדי). חיבר גם \"ברכת משה\", ועוד.","bk":[["ברכת משה - חולין",""],["וידבר משה - על התורה ומועדים וכללים",""],["שיורי ברכה - סוגיות השייכות למסכת חולין",""],["תיקון משה - דרושים על התורה",""]]},{"i":37389,"n":"פולק, משה זאב מגרוסורדין ונ\"י","f":"חיים יעקב","bp":"מארוש-ואשארהי","dt":"תשמו - ז פסח","dp":"ניו יורק","b":"תלמיד ר מרדכי בריסק בטשאנד, ור מנחם סופר מואשארהי. חתן ר אהרן אויש מלופן. ניצל מהשואה, ואחריה רבה האחרון של גרוסורדין. היגר לארה\"ב בשנות ה-60, וכיהן כרב ק\"ק \"באר משה\" בניו יורק. (לפי מורשת הונגריה - היה בנו של ר אשר מגרוסורדין)."},{"i":37390,"n":"פולק, משה יהודה ליב מבערעטי","bt":"תקפג","bp":"פעזינג","dt":"תרמג - כב אד\"א","dp":"בערטי-אויפאלו","b":"תלמיד החת\"ס והכת\"ס. חתן ר שמעון הוק מפרג. מחכמי ביהאר-דיאסעג, בערטי-אויפאלו."},{"i":37391,"n":"פולק, משה יהודה מסטמר","b":"עורך \"הישיבה\" - סטמר-אראדעא תרפט - קובץ לתלמידי ישיבות ובו סקירה על ישיבות הזמן."},{"i":37392,"n":"פולק, משה מבאניהאד","f":"אברהם","bt":"תקסה","bp":"באניהאד","dt":"תרכו - כא תשרי","dp":"סערדאוהל","b":"תלמיד החת\"ס. רב בסערדאוהל."},{"i":37393,"n":"פולק, משה מגרוסורדין","f":"ישעיה","dt":"תש..","b":"רב בחברת ש\"ס בגרוסורדין-תרפה על מקום אביו. נספה בשואה."},{"i":37394,"n":"פולק, משה ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":37395,"n":"פולק, משה מסרדאוהל","b":"דומ\"צ בסרדאהעל-תר\"י"},{"i":37396,"n":"פולק, עזריאל מאיזנשטט - א","f":"בנימין זאב פולק","b":"דומ\"צ באייזנשטט-תק\"נ"},{"i":37397,"n":"פולק, עזריאל מאיזנשטט - ב","k":"הו\"ל נשק בר","bt":"תקסג","bp":"[העדיעס]","dt":"תרמז - כ כסלו","dp":"אייזנשטט","b":"תלמיד החת\"ס. רב באייזנשטט-תקצה כ-40 שנה. הו\"ל \"נשק בר\" לר ניסן שידלוב. בנו - ר צבי יהודה - נפטר צעיר."},{"i":37398,"n":"פולק, עקיבא משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":37399,"n":"פולק, צבי יהודה הרש מאיזנשטט","f":"עזריאל מאייזנשטט","dt":"תרכב - כה טבת","b":"תלמיד הכת\"ס, והמכתב סופר ור אהרן זינגר ממטרסדורף. מחכמי איזנשטט. רשם מתורת רבו הכת\"ס. נפטר בצעירותו."},{"i":37400,"n":"פולק, צבי מאויבר-וישווה","b":"שו\"ב באויבר-וישווה. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":37401,"n":"פולק, שלמה זלמן מזענטא","f":"שמעון מזענטא","b":"גיסו של ר יהושע עוזר מזענטא. חתנו - ר משה ולץ מבודפשט, ור שלמה זלמן אולמן ממאקווא."},{"i":37402,"n":"פולק, שלמה יו\"ט מדערעטשקע","f":"ישעיה מואדקערט","k":"בעל פניני שלמה-תשנב","b":"רב בדערעטשקע, לאנדסברג-ברוקלין."},{"i":37403,"n":"פולק, שמואל מפעשטרזעבעט","b":"נאמן קהלת פעשטערזשעבעט, חתם-תרפט עם הרב - ר אברהם דב קריסהאבער."},{"i":37404,"n":"פולק, שמעון מזענטא","b":"חתן ר שלמה זלמן אולמן ממאקווא. בנו - ר יהושע עוזר מזענטא, וחתנו - ר נחום שלזינגר מטאפלטשאן."},{"i":37405,"n":"פולק, שמעון מיעמרינג וגרוסורדי","f":"משה יהודה ליב","k":"בעל שם משמעון-תרצב","bt":"תריח","bp":"ברט-אויפאלו-הונגריה","dt":"תרץ - ז אייר","dp":"גרוסורדין","b":"תלמיד ר יואל אונגר מפאקש. חתן ר ישעיה הכהן רובין בעל \"עטרת ישעיה\" ממיהאליפאלווא. רב בימרינג(=יעמרינג)-תרמא, בעלעניעש(=באלניש)-ליד גרוסורדין-תרנח על מקום חותנו - עזב בגלל מחלוקת-תרפו ועבר לגרוסורדין. אחיו ר יהושע הו\"ל את ספרו עם הקדמה מחתנו ר משה בונם קרויס מבאדען-שוייץ. חיבר גם \"קול ברמה והפרשה\". פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":37406,"n":"פולק, שרגא","f":"אברהם פולק","bt":"תרלז","dt":"תרעא - יט חשון","b":"רב בב'פורעד-תרס\"ג"},{"i":37407,"n":"פולק, שרגא פיבל מזענטא","b":"חתניו - ר שרגא פיבל פולק מזענטא, ור ישעיה זילברשטין מוויצען."},{"i":37408,"n":"פולק, שרגא פייש מוויצען","f":"יהושע מפעטראווסלע","k":"בעל תשב\"י","bt":"תרכא","bp":"פעטראווסלע","dt":"תשד - כה תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס, ור מרדכי לעוו מפעטראווסלע, ועוד. חתן ר שלמה הכהן קליין מזענטא. רב בטורוק-בעטשע-תרמו, קהילת סטטוס-קוו בוויצען-תרסא ורב בית הכלא המרכזי במקום. נספה בשואה. בנו ר יואל רב בתל אביב. חתנו ר דניאל שלזינגר משאלגא-טאריאן."},{"i":37409,"n":"פולק-ויינרעבע, משה משליינינג","f":"יהודה הלוי מלאסק","bt":"תקמה או תקן","bp":"ללאסק","dt":"תרל - כ שבט","dp":"שליינינג","b":"תלמיד החת\"ס. רב בגינז-תקפה (בבית משפחת שאי), שליינינג-תקצד."},{"i":37410,"n":"פומפיאנסקי, אהרן אליהו","f":"אריה ליב","k":"בעל שירי ציון","bt":"1835","bp":"וילנא","dt":"1893","b":"תלמיד ביהמ\"ד לרבנים בוילנא. משורר ומשכיל. הו\"ל את המהדורה הרוסית של \"הכרמל\", עורך \"יאוור\", \"זאפיסקי\" - ובו מחקר בקורות היהודים בארצות הבלטיות. רב מטעם בפוניבז כ-12 שנה, ריגה כ-20 שנה. הו\"ל תהלים עם תרגום רוסי וביאור. חיבר גם \"שלמה המלך החכם\". פרסם מאמרים בעניני חינוך והיסטוריה."},{"i":37411,"n":"פומרנץ, אשר ממינסק","b":"גביר מחכמי מינסק בזמן כהונת הגדול ממינסק."},{"i":37412,"n":"פומרנץ, חיים אהרן דוב מדוברובה","f":"צבי הירש","bt":"תרל","bp":"ברעזי-פלך גרודנא","b":"רב בדובראבה(=דובראווא)-פלך הורדנא-תרס, טרסטינה-פלך גרודנא."},{"i":37413,"n":"פומרנץ, יעקב מאיר מירושלים","k":"הו\"ל חמש ידות ותשובו","dt":"תשלד - יב ניסן","b":"נכד ר בנימין בישקא בעל \"בן אוני\". רב בגריבה, ברוק(=בראק), ארה\"ב-תשא, עלה לירושלים-תשכג. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח. הו\"ל ספר זקנו \"חמש ידות ותשובות שער בנימין\" ת\"א תשלה ובראשו תולדות זקנו."},{"i":37414,"n":"פומרנץ, שלום ממעליץ","f":"זאב וולף","b":"רב במעליץ. נספה בשואה."},{"i":37415,"n":"פומרנציק, אריה","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"תבונה\" - ירושלים תשא-תשח, \"תורת ארץ ישראל\" - ירושלים תרץ, והספד עליו שם."},{"i":37416,"n":"פון, אליהו","dt":"תשא","b":"רב בטרישק"},{"i":37417,"n":"פון, מיכל מפנדיל","dt":"תשג","b":"תלמיד בכולל סלובודקא. רב בפאנידל. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":37418,"n":"פונדיק, אהרן מוילנא","f":"יצחק איזיק חבר מסלונ","bt":"תקמט","bp":"הורדנא","dt":"תרמו - ד כסלו","dp":"וילנא","b":"גביר מחכמי וילנא."},{"i":37419,"n":"פונדמינסקי, שניאור זלמן מחברון","b":"מראשי קהלת חב\"ד בחברון, חתם-תרלב עם ר שמעון מנשה חייקין ואחרים."},{"i":37420,"n":"פונדק, דב מזבורוב","b":"שו\"ב מחכמי זבורוב-תקצח."},{"i":37421,"n":"פונזננסקי, מיכאל מרדמוסק","f":"מנחם מנדל","k":"בעל דעת חכמים","b":"שו\"ב ברדמוסק בזמן ר שלמה מרדומסק שהיה מתיעץ עמו בעניני הלכה. השיב תשובות רבות. חיבר גם \"דעת הזבח\"."},{"i":37422,"n":"פונטאנילה, אברהם מיכאל מאיטליה","f":"שמואל חיים","k":"בעל אור עינים","b":"מחכמי איטליה. חיבר ספר על עיבור השנים בשם \"אור עינים\", ובו זמני קבלת שבת באיטליה."},{"i":37423,"n":"פונטאנילה, דוד מאיטליה","f":"מצליח","b":"מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה."},{"i":37424,"n":"פונטאנילה, ישראל ברכיה","f":"יוסף יקותיאל","b":"רב באיטליה-תפח בזמן ר ישראל בנימין בסאן. תשובה ממנו ב\"תודת שלמים\" ו\"פחד יצחק\" -תפח."},{"i":37425,"n":"פונטו, אליעזר מפרג","b":"מחכמי פרג-תקך. נשאל מאת קהילת פפד\"מ אודות ר יחזקאל בעל \"נודע ביהודה\" - כשהיה מועמד לרבנות פפד\"מ."},{"i":37426,"n":"פונטיקורבו, שבתי מרומא","b":"מחכמי הישיבה ברומא. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":37427,"n":"פונטרימולי, אברהם","f":"חיים בנימין","k":"בעל אשר לאברהם","b":"מחכמי איזמיר, חיבר \"אשר לאברהם\""},{"i":37428,"n":"פונטרימולי, אלישע מפיאמונטי","k":"בעל סוד בחורים","b":"רב בפיאימונט-איטליה, חיבר \"סוד בחורים\", \"דברי שיר\" ועוד - נמצאים באוצר ספרי ר חיים מיכל - ונזכרים בספרו."},{"i":37429,"n":"פונטרימולי, בנימין מאזמיר","k":"בעל שבט בנימין","dt":"תץ - טז סיון","dp":"אזמיר","b":"רב באזמיר. אולי הוא זקנו של ר בנימין פונטרימולי מצפת שרשום כמחבר אותו הספר."},{"i":37430,"n":"פונטרימולי, בנימין מצפת ואזמיר","k":"בעל שבט בנימין","dt":"תקמד - טז סיון","dp":"אזמיר","b":"מחכמי צפת, בא לאזמיר-תקכ\"ז, דיין שם, חיבר \"שבט בנימין\"","bk":[["שבט בנימין",""]]},{"i":37431,"n":"פונטרימולי, גבריאל מקסאלי","b":"ר\"מ בישיבת קסאלי, טורינו-תעד. רב בזמן רב אס\"י מקזאלי(=קסאלי). מתורתו ב\"שמש צדק\". חתם עם הרא\"ש פוביני ועם רב אס\"י מקזאלי - הסכמה לר שמשון מורפורגו בנדון מים שאין להם סוף. מתלמידיו ר יצחק רפאל פינצי. מתורתו ב\"אמונת חכמים\"."},{"i":37432,"n":"פונטרימולי, ח' שמואל מאזמיר","b":"מחכמי ורבני איזמיר"},{"i":37433,"n":"פונטרימולי, חייא מאזמיר","k":"בעל צפיחית בדבש","dt":"תקצב","dp":"אזמיר","b":"רב ודיין באיזמיר,חיבר \"צפיחית בדבש\""},{"i":37434,"n":"פונטרימולי, חיים בנימין מאזמיר","f":"חייא-צפיחית בדבש","k":"בעל פתח הדביר","r":"מחכמי איזמיר","bt":"אולי תקנה","dt":"תרלג - י ניסן","dp":"אזמיר","b":"חתן ר יהושע אברהם קריספין בעל \"אברהם במחזה\". דיין באיזמיר אצל ר חיים פאלאג'י. חיבר \"פתח הדביר\".","bk":[["פתח הדביר [על שו\"ע או\"ח]",""],["פתח הדביר –",""]]},{"i":37435,"n":"פונטרימולי, ישעיה יוסף מאזמיר","f":"חיים בנימין-פתח הדבי","k":"בעל פנים במשפט","dt":"תרל - כד אב","b":"רב באזמיר ודיין עם ר אברהם פלאג'י שהזכירו בספרו \"אברהם את ידו\". נפטר בחיי אביו."},{"i":37436,"n":"פונטרימולי, מירקאדו חיים ישעיה","dt":"תקעד","dp":"אזמיר","b":"רב באזמיר ונספה במגפה שם. מתורתו בספרי אביו ואחיו. בנו ר נסים בנימין - נפטר במגפה-תרכה, ונכדו ר ג'יליבי שמואל חייא פונטרימולי בעל \"חסד ומשפט\"."},{"i":37437,"n":"פונטרימולי, משה","b":"אין פרטים"},{"i":37438,"n":"פונטרימולי, רפאל חייא מאזמיר","k":"בעל דרכי איש","b":"רב באזמיר."},{"i":37439,"n":"פונידלר, שמואל ברזינר(ורזינר)","f":"יצחק","bt":"תרלה","bp":"באריזינו-פלך מינסק","dt":"תשא","dp":"ריטובה","b":"תלמיד ר יצחק-איצה'לה בפוניבז, ישיבת סלובודקה, ור שמחה זיסל בקלם והיה ממקורביו ונשלח ע\"י כמשפיע בישיבות סלוצק, מיר, טלז-תרסה, וסלובודקה. רב בוארז'אן-תרעב, רב בבאריזינו בזמן מלחה\"ע ה-I, חזר לוארז'אן-תרפא, רבה האחרון של ריטובה-תרפב. עלה לארץ-תרפז וכיהן כמנהל כולל אברכים, לאחר פרעות תרפט חזר לליטא. התכונן לחזור-תש לנהל את ישיבת בית התלמוד בתל אביב - אך לא הספיק. נספה בשואה."},{"i":37440,"n":"פוניס די, משה מאזמיר","b":"גביר בקושטא הקים ישיבה בזמן ר אברהם בן יצחק רוזניס."},{"i":37441,"n":"פונסיקא די, אברהם","k":"בעל עיני אברהם","dt":"תלה - כג תמוז","dp":"אלטונא","b":"רב עדת הספרדים בגליקשטאדט, אב\"ד בהמבורג ואלטונא. (באוצר תאריך הפטירה - תיא)."},{"i":37442,"n":"פונסיקה, דניאל הרופא מקושטא","bt":"תכח","bp":"או פורטו-פורטוגל","dt":"תק","dp":"פאריס","b":"מאנוסי פורטוגל, הגמון בפורוגל, ברח לפאריס ולמד רפואה וחזר ליהדות, הגיע לקושטא-תם והיה רופא ציר צרפת, מקורב לשלטון, רופא נסיך ואלאכיה-תע, רופא השולטן-תעד, חזר לפאריס ופגש את הסופר האנטישמי וולטיר שאמר עליו \"אולי הפילוסוף היחידי בעמו\"."},{"i":37443,"n":"פונפדר, יעקב משאלא","b":"רב בנייטרא. בניו - ר שמעון יהודה מטאקייא ור מרדכי מבעקעש. חתנו ר אברהם יהודה שטרן משאק"},{"i":37444,"n":"פונפדר, מרדכי","r":"אב\"ד בעקעש","bt":"תקצה","dt":"תרכח - כב כסלו","b":"רב בבעקעש","bk":[["מאמר מרדכי - חידושי סוגיות ש\"ס",""]]},{"i":37445,"n":"פונפדר, שמעון יהודה מוואשוואר","k":"בעל מעיני מים - תשן","r":"אב\"ד מאגנדארף וטוקאי","dt":"תרלג - כט חשון","b":"רב בוואשוואר, מוגנדורף, טוקאי(=טאקאי)-תרל. מתורתו ב\"מאמר מרדכי\" לאחיו ר מרדכי מבעקעש.","bk":[["מעיני מים \\ מקוה מים - מקוואות",""]]},{"i":37446,"n":"פונק, אדוארד מפרשבורג - רופא","b":"רופא בפרשבורג-תקצט - קיבל זכות ישיבה בעיר עצמה."},{"i":37447,"n":"פונק, יואל אליעזר משניאדובה","b":"שו\"ב בשניאדובה, חתנו - ר אברהם מתתיה כגן מארה\"ב."},{"i":37448,"n":"פונק, שלמה מבוסקוביץ","k":"בעל התלמוד","bt":"תרכו","bp":"סעגיען","dt":"תרפח - יב סיון","b":"תלמיד השב\"ס, ור עזריאל הילסהימר מאיזנשטט. רב בקרומונוי, בוסקוביץ-תרנד, וממלא מקום רב המדינה, רב בוינה-תרעה. חיבר ספרים בל\"א."},{"i":37449,"n":"פונש די, יצחק","dp":"שלוניקי","b":"מחכמי שלוניקי-שי."},{"i":37450,"n":"פוס, בן ציון מרודניק","b":"רב ברודניק-תרסד."},{"i":37451,"n":"פוסטמן, אליקים גצל מהוסיאנטין","dt":"תשג","dp":"טרנוב","b":"גבאי, מזכיר ומלמדו של האדמור משה פרידמן מהוסיאטין. עבר לקראקא עם האדמור. נספה בשואה. בנו ר חיים משה יחיאל פלדמן (שם משפחת אמו) רב בברלין."},{"i":37452,"n":"פוסמן, שלום מליזנסק","b":"עבר לניו יורק וכיהן כרב בזמן מלחמת העולם הראשונה."},{"i":37453,"n":"פוססטרנם, יהושע מזרצין","b":"מעורכי \"תלפיות\" - טרנוב תרצח."},{"i":37454,"n":"פוסק, אליהו מזלטופול","f":"משה צבי","k":"בעל מור ואהלות","bt":"תריט","bp":"זלטופולי-פלך קיוב","dt":"תרצג","b":"רב במוהליבקה(=מוחילאויקי)-פלך חרסון-תרמא, זלטופול-תרמח, אליפאליא(=אטאפאליא = זלטופול?). הסכים על \"אהל יצחק\" - סטמר תרסג. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"בית ועד לחכמים\" - לונדון תרסב, \"בית ועד לחכמים\" - סטמר תרפב, \"כנסת הגדולה\" - וארשא תרן. מאמר ממנו ב\"הפוסק\" - תל אביב תש-תשיד, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":37455,"n":"פוסק, אריה ליב מניקלשבורג","k":"בעל דמיון אריה","b":"מגדולי חכמי ניקלסבורג-ש\"נ"},{"i":37456,"n":"פוסק, הלל מטרטובנד","f":"אליהו - מור ואהלות","k":"בעל דברי הלל","bt":"תרמא","bp":"זלטופול","dt":"תשיג - יב אייר","b":"נסמך מאת: אביו, רמ\"נ הלוי רובינשטין, ר\"י הלפרין מאודסה. רב בזלטופול-תרע, מרקולשט-תרפא, טטרבונר(=טרטובאנד)-תרפב, עלה לתל אביב-תרצה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. עורך \"הפוסק\" - תל אביב תש. הו\"ל ספרי אביו. מיסד האגודה לתקנת עגונות."},{"i":37457,"n":"פוסק, חיים","b":"פוסק,ראב\"ד בניקלסורג-ת\"ע"},{"i":37458,"n":"פוסק, משה צבי","b":"רב בשדה לבן-תר\"כ"},{"i":37459,"n":"פופל, אברהם דוב מהאידוצשק","f":"אריה","bt":"תרכט","bp":"האנושישוק-פלך קובנא","dt":"תרפג","dp":"מאריאמפול","b":"תלמיד ישיבת איישישוק. רב בהנושישוק(=האנישישאק)-פלך קובנא-תרנז, הידוצישוק(=האיידוצישאק)-פלך וילנא-תרסה, מאריאמפול. פעיל באספות ובמוסדות האוטונומיה היהודית, יו\"ר אגודת הרבנים, פעיל באגו\"י, ותומך בציונות. נבחר לסיים הליטאי - ונאומו שם כנגד עונש מוות זכה לפרסום גדול בעולם."},{"i":37460,"n":"פופס, ישראל ליב","bt":"1883","bp":"נאוויראן","dt":"1912","dp":"היידלברג","b":"פרסם ב\"הזמן\", \"השלוח\"-תרסו וחתם \"בן ישראל\". תלמיד פילוסופיה בהידלברג. התאבד."},{"i":37461,"n":"פופערט, נפתלי הרץ מהמבורג","f":"שמשון","dt":"תקיג - ז טבת","dp":"אלטונא","b":"מראשי קהלת המבורג, עמד לצדו של ר יונתן איבשביץ בזמן המחלוקת יחד עם חבריו: ר אליהו אופנהיים, ר דוד רינטל, ר אברהם גוגנהיימר."},{"i":37462,"n":"פופקא, אברהם אריה מארה\"ב","f":"אליעזר מפילדלפיה","bt":"תרעא","bp":"קאליש","b":"תלמיד ישיבת ראדין, ברנוביץ, רוזינוי, קוברין, מזריטש. נסמך מאת: ר חיים עוזר גרודזינסקי, ר משה לונדינסקי, ר דב גרייזל מקרעווע. חתן ר משה שוסטק. רב בפילדלפיה. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":37463,"n":"פופקא, אברהם יצחק מסוכטשוב","b":"מחותן עם ר יצחק יוסף חזן מלוביטש."},{"i":37464,"n":"פופקא, אליעזר מביעלאוויזש","f":"חיים יהושע השל","bp":"ראדין","dt":"תשכב - יג תשרי","b":"תלמיד ישיבת נוברדוק, סלובודקא, טלז, וולוזין. נסמך מאת: ר רפאל שפירא. חתן ר יעקב משה ספיר מסראטוב. רב בביעלאוויו(=ביעלאוויזש)-פלך גרודנא, קאליש-פלך לומזה, פילדלפיה-ארה\"ב-תרצב. אשתו היתה בקיאה בתלמוד. בניו: ר יצחק מניו יורק, ר אברהם מפילדלפיה, ר ראובן מפילדלפיה, ר מרדכי מפילדלפיה, ר ברוך אהרן מפיטסבורג. חתנו - ר מרדכי סוביצקי מבוסטון. גיסו - ר שבתי ליב ראשקעס מסט לואיס."},{"i":37465,"n":"פופקא, אריה ליב הכהן","f":"החפץ חיים","bt":"תרכא","dt":"תרצט - כג כסלו","b":"רב בראדין-תרצד. (באוצר מופיע תאריך פטירתו גם - כח שבט), סייע לאביו בחיבור ה\"משנה ברורה\"."},{"i":37466,"n":"פופקא, ברוך אהרן מארה\"ב","f":"אליעזר מפילדלפיה","bp":"ויעליזש-רוסיה","b":"תלמיד ישיבת רבי יצחק אלחנן בניו יורק. נסמך מאת ר יוסף דב סולוביציק, ר דב אריה לוונטל, ר\"א ארונוביץ. חתן ר דוד שלמה נאוואסעלער מפילדלפיה. רב קהלת \"שערי תורה\" בפיטסבורג על מקום ר משה שמעון זיוויץ. עורך \"כוכב מזהיר\", ו\"אידנו\". חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":37467,"n":"פופקא, חיים יצחק מארה\"ב","f":"אליעזר מפילדלפיה","bt":"תרסט","bp":"סראטוב","b":"תלמיד ישיבת אהל תורה בברנוביץ, ישיבת ראדין. נסמך מאת: ר משה לנדינסקי מראדין. חתן האדמור ר חיים משה יהושע שניאורסון מטאאמשפול וקוידנוב(-נכד בעל התניא). רב בניו יורק, ור\"מ בישיבת \"אהבת תורה\", \"תורת חיים\". חבר אגודת הרבנים באמריקה."},{"i":37468,"n":"פופקא, ראובן מארה\"ב","f":"אליעזר מפילדלפיה","k":"בעל תורת ראובן","bt":"תרעג","bp":"ויעליז-פלך ויטבסק","dt":"תשט - תמוז","dp":"פילדלפיה","b":"תלמיד ישיבת ראדין, ברנוביץ. חתן ר מאיר שוסטר (ממשפחת ר שמחה זיסל מקעלם). רב בקהלת \"בני ישראל דלאגאן\" בפילדלפיה. חבר אגודת הרבנים באמריקה."},{"i":37469,"n":"פופר - משפחה","b":"משפחה באזור שטמפן, סעניץ, האליטש ושאשוואר."},{"i":37470,"n":"פופר, אריה יהודה ליב מקיצע","bt":"תקלו","bp":"שטאמפן","dt":"תרד - כו אלול","dp":"וינה","b":"רב בטשוס, קיצע-תקפג על מקום ר צבי הירש ברוידא. תלמיד החת\"ס. תשובה אליו ב\"חתם סופר\". הסכים על \"אמונת ישראל\" לר שמואל הנדלר משטמפן, \"בית יצחק\"-תקפד. מתורתו ב\"יד גבריאל\"-תקצה. אחיו - הגביר ר הרש פופר שטאמפי מסעניץ."},{"i":37471,"n":"פופר, הרש מ"},{"i":37472,"n":"פופר, מנחם מנדל משטמפן והאליטש","b":"גביר בהאליטש, שטמפן-תקסג."},{"i":37473,"n":"פופר, צבי הירש ליב מסעמניץ","b":"גביר בסעניץ(=סמניץ), שטמפן-תקכה. חתנו - ר ירמיה לעוו בעל \"דברי ירמיהו\", אחיו - ר אריה ליב פופר מקיצע."},{"i":37474,"n":"פופר, שמעון מפרג","bt":"תקעו","bp":"רונשברג (בוהמיה)","dt":"תרמג - טו חשון","dp":"פרג","b":"תלמיד החת\"ס. רב בפטשוי (בוהמיה)-תרה, האהענמס (אוסטריה)-תריב, דיין בפרג-תרלב."},{"i":37475,"n":"פופרש, אברהם הכהן מטפליץ","b":"תלמיד ר יונתן איבשיץ. רב בטפליץ-תקמ."},{"i":37476,"n":"פופרש, דב בריש מברוד","f":"יצחק איזיק","b":"מחכמי ברודי-תרכג ונשיא ארץ ישראל. חתן ר לוי הכהן מקאזין."},{"i":37477,"n":"פופרש, זאב וולף הכהן","f":"יעקב מפפד\"מ","dt":"תקיח - ח כסלו","b":"דיין בפפד\"מ-תפ בערך, רב בפרידברג ובנו ר שמואל זנויל על מקומו אחריו. חתנו - ר אהרן אוכס."},{"i":37478,"n":"פופרש, זאב וולף מפרמישלא","f":"דב בריש","k":"בעל זבד טוב","bt":"תקפז","dt":"תרס","b":"רב בפשוורסק-תרל. פרמישלא. חיבר \"זבד טוב\" פרמישלא תרנה, ועוד."},{"i":37479,"n":"פופרש, חנוך זונדל","f":"יהודה ליב","k":"בעל ראשית ביכורים","b":"חתן ר ליב בעל \"ראשית בכורים\" ו\"חינוך בית יהודה\". רב בפפערשא(שוואבן), שנייטוך-תס."},{"i":37480,"n":"פופרש, יוסף מברוד","f":"יעקב","k":"בעל מנחה חדשה","bt":"תרל","bp":"ברודי","dt":"תרצט","b":"נכד ה\"מנחת חינוך\". רב בברודי. נשיא ארץ ישראל. חתן ר ישראל אלעזר הלוי קמינר (גיסו של האדמור מגור). בנו ר יחזקאל שרגא על מקומו אחריו. חיבר \"מנחה חדשה\" ברודי תרצד."},{"i":37481,"n":"פופרש, יעקב הכהן כץ מפרג","f":"בנימין מפרג","k":"בעל שב יעקב","dt":"תק - כב שבט","b":"מרביץ תורה, פוסק, דיין בפרג, רב בקובלנץ-תנז, נבחר לרב בהלברשטט אך נענה להצעת פפד\"מ, פפד\"מ-תעה על מקום ר אברהם ברוידא, ור יעקב יושע בעל \"פני יהושע\" על מקומו אחריו-תקא. לחם בשבתאות ואף במקובלים ואילץ את הרמח\"ל - שביקר בפפד\"מ להתחייב שלא ללמד קבלה. מבניו:\" ר וולף הכהן מפרידברג. מחתניו: ר נפתלי הירש קצנלנבוגן. מתלמידיו: ר יוסף שטינהרט, ר יוסף ואסרט-ילינגען, ר יעקב ברלין."},{"i":37482,"n":"פופרש, יעקב יהודה ליב מהמבורג","f":"חנוך זונדל מפפערשא","k":"בעל לשם זבח","dt":"תקלט - כב חשון","dp":"המבורג","b":"חתן ר צדוק וידמונד. תלמיד ר יעקב הכהן מפפד\"מ בעל \"שב יעקב\". דיין בהמבורג אצל ר יונתן איבשיץ, ומחכמי הקלויז ישן-תקיג, ר\"מ בקלויז חדש-תקטז, עמד לצדו של יונתן איבשיץ בזמן המחלוקת, ומילא את מקומו של ר יונתן עד למינויו של ר דוד ברלין כראב\"ד."},{"i":37483,"n":"פופרש, יעקב מברוד","f":"ראובן","bt":"תקצה","dt":"תרס","b":"מחכמי ברודי. חתן בזיוו\"ש של ה\"מנחת חינוך\"."},{"i":37484,"n":"פופרש, יצחק איזיק מברוד","bt":"תקם","dt":"תר","b":"מחכמי ברודי, ממשפחת שפירא וקיבל את שם אמו - נכד ר מאיר הכהן פאפירש. חברו של ה\"ישועות יעקב\"."},{"i":37485,"n":"פופרש, יצחק הכהן מפרג","f":"משה","dt":"שפב - יב סיון","dp":"פרג","b":"מחכמי פרג."},{"i":37486,"n":"פופרש, מאיר הכהן מירושלים","f":"יהודה ליב","k":"בעל אור הישר","bt":"ה'שפד","bp":"אשכנז","dt":"תכב - ב אדר","dp":"ירושלים","b":"רב בקראקא, מגדולי המקובלים, גיסו של ר נתן גוטה, תלמיד ר ישראל אשכנזי ור יעקב צמח, עסק בסידור כתבי הארי והבאתם לדפוס לצורך כך ביקר בדמשק אצל ר שמואל ויטאל. חיבר ספרים רבים וביניהם \"אור הישר\" המבורג תק. בשנת תיז חתם על כתב שליחות ר יצחק פאיש.","bk":[["אור צדיקים [הנהגות ומוסר]",""],["דרך סעודה",""]]},{"i":37487,"n":"פופרש, מאיר הכהן מפוזנא","f":"זנוול פפרש","b":"מקובל,דיין בפוזנא-תקי\"ט"},{"i":37488,"n":"פופרש, צדוק מהמבורג","f":"יהודה יעקב-לשם זבח","dt":"תקפז - יג חשון","dp":"אלטונא","b":"מחכמי הקלויז ישן בהמבורג על מקום ר משה היילבוט, גבאי הח\"ק. ממלא מקום הרב בהמבורג לאחר הפרדות הקהלות."},{"i":37489,"n":"פופרש, ראובן מברוד","f":"יצחק איזיק","bt":"תקס","dt":"תרי","b":"מחכמי ברודי, חתן ר יעקב ברז\"פ."},{"i":37490,"n":"פופרש, ראובן מטבריה","b":"מחסידי טבריה-תקפב. כתב במכתב על מאסרם של ר זאב וולף מטשרני אוסרהא, ור הירש הורוקר."},{"i":37491,"n":"פופרש, שמואל זנוול","b":"רב-שנת ת\"ס"},{"i":37492,"n":"פופרש, שמואל זנויל הכהן מפריד","f":"זאב וולף מפרידבורג","dt":"תקלט","b":"נכד ר יעקב פופרש בעל \"שב יעקב\". דיין בפוזנא-תצח-תקיח, ובנו ר מאיר לצדו ועל מקומו אחריו, רב בפרידברג, ור שלמה פוזן על מקומו אחריו."},{"i":37493,"n":"פופרש, שמחה מטעפליץ","dt":"תקך - א שבט","dp":"טעפליץ-שאנוי-בוהמיה","b":"חתן ר יצחק שולהוף בעל מגילת אויבן. אב\"ד בפרג יחד עם ר יונתן איבשיץ על מקום ר דוד אופנהיים, רב בטעפליץ-שאנוי-בוהמיה-תקא ור יצחק קליש על מקומו אחריו (ביניהם כיהן באופן זמני הדיין ר הירץ)."},{"i":37494,"n":"פופרש-קצנלנבוגן, אברהם","b":"אין פרטים - חתם שמו פ\"פ לקא\"ב - פופרש לבית קצנלנבוגן. (אולי ממשפחת ר נפתלי הרש ממנהיים שהיה חתנו של ר יעקב פופרש מפרג)."},{"i":37495,"n":"פופרש-קצנלנבוגן, משה","f":"אברהם","b":"אין פרטים - חתם שמו פ\"פ לקא\"ב - פופרש לבית קצנלנבוגן. (אולי ממשפחת ר נפתלי הרש ממנהיים שהיה חתנו של ר יעקב פופרש מפרג)."},{"i":37496,"n":"פופרש-קצנלנבוגן, פנחס","b":"אין פרטים - חתם שמו פ\"פ לקא\"ב - פופרש לבית קצנלנבוגן. (אולי ממשפחת ר נפתלי הרש ממנהיים שהיה חתנו של ר יעקב פופרש מפרג)."},{"i":37497,"n":"פוקי, יהודה הקראי מקושטא","f":"אליעזר ג'יליבי-צלבי","k":"בעל שער יהודה","b":"ראש העדה הקראית בקושטא-שמב. חיבר \"שער יהודה\" על דיני העריות של הקראים."},{"i":37498,"n":"פוקי, שלמה מסוריה","b":"מחכמי סוריה, תלמיד הרא\"ם, נזכר אצל ר יוסף קארו."},{"i":37499,"n":"פוקי, שלמה מצפת","b":"מגדולי חכמי צפת-ש\"כ"},{"i":37500,"n":"פוקס, אברהם עזרא מבלשביץ","f":"יעקב פנחס מאמשינוב","k":"אדמור מבלשביץ","b":"חתן ר מאיר גוטשטיין מבלשביץ, רב בבלשביץ על מקום חותנו וכיהן גם כאדמור. חיבר \"תוספות עזרא\" למברג תרנו."},{"i":37501,"n":"פוקס, אהרן מבוברקא","f":"משה","b":"רב בבוברקא על מקום אביו - עד מלחמת העולם הראשונה."},{"i":37502,"n":"פוקס, אריה ליב מרגנדורף ועספרם","dt":"תקצז","b":"חתן הגביר ר שלמה טלטש ממורביה. רב ברגנדורף, ועספרם. נזכר בשו\"ת החת\"ס, \"פרשת מרדכי\", \"שיני עפרים\". הסכים על \"בית יצחק\"-תקסד."},{"i":37503,"n":"פוקס, בנימין זאב וולף מסערעד","f":"משה צבי מלשברין","bt":"תקעד","bp":"לאשברין","dt":"תרלד - ו תשרי","dp":"סערעד","b":"תלמיד החת\"ס, ור מאיר א\"ש מאונגוואר, ור חיים קיצע מאירשא. חתן ר דניאל. רב בסערעד-תרח על מקום ר חיים בנימין פולק ובנו ר משה הירש על מקומו אחריו."},{"i":37504,"n":"פוקס, בנימין מגרוסורדין","f":"משה צבי הרש מסערעד","bt":"תרלד-ח","bp":"סערעד-ליד פרשבורג","dt":"תרצו - כא אדר","dp":"גרוסורדין","b":"תלמיד השב\"ס, ור יהודה גרינולד מסטמר ור מרדכי יהודה וינקלר מעדילא-מאדע. מחברי ונואם באגודת \"אהבת ציון\" בפרשבורג - בהיותו תלמיד בישיבה. חתן דודו ר ישראל גרוס מטאקייא (שהיה חתן זקנו ר זאב וולף פוקס מסערעד), (ולפי אהלי שם חתן גיסו ר אליעזר דייטש). רב בברשוב-תרסא, קראנשטאר-תרסב, יאקא-תרסה, פעזינג(=באזין)-תרסט, נאדי-באניא(=נאגי-באניא)-תרסח-ע, גרוסורדין-תרעח על מקום אביו והרב ד\"ר אהרן קרויס על מקומו אחריו. היה נואם מחונן, נפטר באמצע דרשה ובה דרש להפסיק את המריבות ולהתאחד לנוכח הסכנות הגדולות שבפניהם ניצבים היהודים. כתביו אבדו בשואה. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":37505,"n":"פוקס, דוד דוב","b":"רב בסומפולנה-תר\"ע-תר\"פ"},{"i":37506,"n":"פוקס, יואל מבלאשקי","f":"דוד דוב פוקס","bt":"תרסא","dt":"תרצא","b":"רב בראדזיוב,סומפולנא,בלאשקי-תרע\"ז"},{"i":37507,"n":"פוקס, יעקב קופל מפערימאטש","b":"דומ\"צ בבאשאטץ-תרס\"ו,עדיעק,פערימאטש"},{"i":37508,"n":"פוקס, ישעיה מרוזדול","b":"רב ברוזדול-תרמח."},{"i":37509,"n":"פוקס, ישראל אליהו מלונטשיץ","b":"רב בלונטשיץ-תרצא. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"כרמנו\" - אלכסנדר-לודז תרצג, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":37510,"n":"פוקס, ישראל מדוינסק","dt":"תשג","b":"רב בדוינסק"},{"i":37511,"n":"פוקס, מרדכי יהודה"},{"i":37512,"n":"פוקס, משה מבוברקא","b":"נכד ר שמעון מירוסלב. רב בבוברקא - בנו ר אהרן על מקומו אחריו."},{"i":37513,"n":"פוקס, משה מנ\"י","b":"רב בנ\"י. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":37514,"n":"פוקס, משה צבי הרש מגרוסורדין","f":"בנימין זאב וולף מסער","k":"בעל יד רמה-תש","r":"תלמיד מהר\"ם שיק והכתב סופר, ואב\"ד גראסווארדיין","bt":"תרא-ג","bp":"לאוואש-ברן-לשברין","dt":"תרעא - א תמוז","dp":"טרנטשין - גרוסורדין","b":"מגדולי הרבנים בהונגריה בדורו. תלמיד מהר\"ם שיק, ר דב שיק, והכת\"ס ור ישראל פרידמן קערט מוערבא. חתן הגביר ר דוד גאנצל (או נאגזל) מסערעד ועבר לשם, ולמד ביחד עם ר יהודה גרינוולד. רב בסערעד-ליד פרשבורג-תרלד על מקום אביו, רב וראש ישיבה בגרוסורדין-תרמב כ-30 שנה ובנו ר בנימין על מקומו אחריו. מתלמידיו - ר ליב פרידמן מפרשבורג, ר יוסף חיים פישמן מטעלענד, חתנו ר יעקב שלום קליין מהאלמין, ועוד. נכדו ר דב בער קליין מהלאמין הו\"ל את ספרו \"יד רמה\" אראדעא (גרוסורדין) תש. עם הקדמה ותולדות המחבר מחתנו ותלמידו ר יעקב שלום קליין שהיה דיין בגרוס ורדין-תרמב והאלמין. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, ושם גם מכתב אליו מר אליעזר דייטש מבאניהאד - שדורש ממנו שלא לעזוב את הרבנות בגרוסורדין וללחום שלא יעשו פרצות בחומת הדת. בנו - ר בנימין מנאדיבאניא.","bk":[["יד רמה - שו\"ת",""]]},{"i":37515,"n":"פוקס, צבי יהודה ממעזא","f":"מנחם אליעזר מגעסטלי","bt":"תרמג","bp":"געסטלי","dt":"תשם - כה תמוז","dp":"פתח תקוה","b":"תלמיד השב\"ס והדעת סופר, ור מרדכי יהודה וינקלר מהעדילא-מאדא. חתן ר שלמה קליין מביהאר-מעזא-קרסטש. רב במעזא-קרסטש על מקום חותנו-תרסט. ניצל מהשואה, ואחריה רב בגרוסורדין. עלה לארץ וכיהן כרב בפתח תקוה. נכדו ר שלמה פולק רב בבית חלקיה. (מורשת רבני הונגריה - נרשם שנספה בשואה)."},{"i":37516,"n":"פוקס, שאול מקראקא","dt":"תקנג - ט סיון","b":"מו\"צ בקרקא"},{"i":37517,"n":"פוקס, שמעון מפרשוב","dt":"תרצג - כו אדר","b":"רב בסענדרא,שיראקא,פרעשוב"},{"i":37518,"n":"פורא, שמואל מדוברומיל","b":"רב בדוברומיל, זלישטשיק."},{"i":37519,"n":"פוראדו, אברהם משלוניקי","dt":"תקיז - אחרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. סייע בהדפסת \"מעשה נסים\"-תקיז."},{"i":37520,"n":"פוראדו, דוד משלוניקי","dt":"תקכד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37521,"n":"פוראט ן, יעקב משלוניקי","dt":"שסח - כח אדר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37522,"n":"פורגא, יעקב חיים","b":"מחדושיו בספר \"עבודת ישראל\" לר ישראל קמחי."},{"i":37523,"n":"פורגא, יעקב מקושטא","f":"דוד","b":"מגיה בדפוס יונה אשכנזי ונפתלי בן עזריאל בקושטא-שנות ה-ת'."},{"i":37524,"n":"פורגס, יום טוב ליפמן מסערדהאלי","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":37525,"n":"פורהאנד, זאב צבי מפרג","f":"מרדכי","bt":"תרעג","bp":"בעטלאן","dt":"תשסא - ד טבת","dp":"ניו יורק","b":"תלמיד הדעת סופר, וזקנו ר משה ממאקווא. חתן ר נחום רוזנר מברדיוב. ניצל מהשואה ואחריה רב בפרג, עבר לניו יורק וכיהן כר\"מ ב\"היכל משה\" בניו יורק."},{"i":37526,"n":"פורהאנד, מרדכי מבעטלאן","f":"משה ממאקווא","bt":"תרמז","bp":"נייטרא","dt":"תשד","b":"תלמיד בעל \"קדושת יו\"ט\", ר אליעזר דייטש בבניהאד, ובעל \"ארוגת הבשם\" בחוסט. חתן ר יהודה ליכטנשטין מבעטלאן. דיין בבעטלאן אצל חותנו=תרסח, דיין בנייטרא-תרעג על מקום אביו שעבר למאקווא. נספה בשואה. הדפיס את ספר זקנו - ר מרדכי שינפלד מנייטרא. (באהלי שם - חתן ר ברוך בנדיט - אחיו של ר יהודה מבעטלאן)."},{"i":37527,"n":"פורהאנד, משה ממאקווא ונייטרא","k":"בעל אהל משה-תשלז","bt":"תרך","dt":"תשד - א סיון","b":"דיין בנייטרא-תרמז וראש ישיבה במקום, רבה האחרון של מאקאווה(=מאקוב)-תרעג. אביו של ר מרדכי מבעטלאן ונייטרא."},{"i":37528,"n":"פורוזובסקי, מאיר מאוזרניצא","k":"אדמור מאוזרניצא","dt":"תרע","b":"רב באוזרניצא. ונתפרסם כ\"בעל שם\"."},{"i":37529,"n":"פורח, קלמן","dt":"תשג","b":"רב בגרייבה."},{"i":37530,"n":"פורט כהן, יהודה","b":"מגדולי חכמי פרג-שנ\"ח"},{"i":37531,"n":"פורט, משה יעקב מניו יורק","k":"בעל רוח יעקב","b":"רב באגסלאוישאק, ניו יורק-תרסה."},{"i":37532,"n":"פורט, צבי","f":"שבתי","bt":"1898","bp":"קובנא","b":"פעיל ציבור בליטא. ממייסדי הבנק העממי היהודי בקובנא וממיסדי הקאואפרציה האשראית היהודית בליטא. פעיל קרנות ציוניות. עלה לארץ-1937 והיה מפעילי איגוד יוצאי ליטא בארץ, ומיוזמי השיכון ליוצאי ליטא ברמת השרון."},{"i":37533,"n":"פורטארא, אברהם מליסבון","k":"בעל תרגום איוב צרפתי","bp":"לונדון","dt":"תקעז","b":"בן לאנוסי פורטוגל, גדל בלונדון, עבר לצרפת. היה בועד יהודי צרפת לפני המהפכה הצרפתית, ניצל ממות בזמן המהפכה, ממארגני אסיפת הרבנים של נפוליאון (הסנהדרין), היה בעל השפעה על נפוליאון לטובת היהודים. חיבר ספרים ותרגומים בצרפתית."},{"i":37534,"n":"פורטגנג, פנחס","b":"מתומכי ישיבת טשבין בארה\"ב."},{"i":37535,"n":"פורטו כהן, שמואל ממנטובה","b":"מגדולי מרביצי התורה במנטובה-ש\"ל"},{"i":37536,"n":"פורטו, אברהם הכהן מוירונה","f":"יחיאל","k":"בעל חות יאיר","bt":"שכט","b":"תלמיד ר שמואל יהודה קצנלנבוגן בנו של מהר\"ם פדובא, מהר\"ם נוויירא, ר\"י מוסקאט. רב בוירונה, קרימונה, ליוורנו. חיבר שו\"ת בכת\"י. תשובה ממנו ב\"פחד יצחק\", וב\"נחלת יעקב\". חתם על פסק רבני וירונה בענין מחלוקת עם אנשי פיררה. חיבר \"חות יאיר\", שמוש אברהם\" ועוד. שימש כמגיה בונציה-שלד. בנו ר משה מסטאלי. (לעתים יש בלבול בינו לבין ר אברהם מנחם בן יעקב פורטו-רפפורט)."},{"i":37537,"n":"פורטו, זכריה מרומא","f":"אפרים","k":"בעל אסף המזכיר","bp":"ארבינו-איטליה","dt":"תלה - לפני","b":"מחכמי רומא - סירב לרבנות - ולכן נקרא ה\"חבר\". רב בפרינצי, רומא, חיבר \"אסף המזכיר\"רשימת מראי מקומות של דרשות מהספר \"עין יעקב\" באגדה, עשיר, נדיב, תמך בישוב א\"י נפטר לפני-תל\"ה"},{"i":37538,"n":"פורטו, יצחק כץ","b":"הזכירו מהר\"ם פדובה בספרו."},{"i":37539,"n":"פורטו, משה הכהן","f":"יחיאל כהן רפא","k":"מכפ\"י","dt":"שפד - כח תמוז","b":"רב בבריאה-פימנט(איטליה). חיבר \"פלגי מים\"."},{"i":37540,"n":"פורטו, שמחה הכהן","f":"גרשון פורטו","k":"בעל קול שמחה","b":"מגדולי ויניציאה-שמ\"ט,עבר למהרין פרוסטין-שס\"ג,ווינה"},{"i":37541,"n":"פורטו-רפפורט, אברהם מנחם הכהן","f":"יעקב","k":"בעל מנחה בלולה","dt":"שסד - יז חשון","b":"אבי משפחת רפפורט. למד בונציה עם ר אליהו בחור אשכנזי, למד גם רפואה. מגיה ספרים בונציה-שיד. חיבר גם \"מנחה בלולה\". רב בוירונה, קרימונה, ונציה-שס, שידלוב?. חיבר \"מנחה בלולה\", \"צפנת פענח\" - בכת\"י (מוזכר אצל די רוסי). מגיה בדפוס ברגדין בונציה. גזר צום על שריפת התלמוד-שיד. בנו ר יעקב הכהן בעל \"קיצור שרש שי\"."},{"i":37542,"n":"פורטוגיז, שלום מאלגיר","bt":"תק - בערך","dt":"תקף - בערך","b":"רב ומקובל באלגיר והתפרנס ממסחר. נזכר ב\"אשכבתא דרבנן\". נזכר ב\"ימים אחדים\" ליוורנו תקן."},{"i":37543,"n":"פורטוגל, אליעזר זוסיא מסקולען","f":"ישראל אברהם מסקולען","k":"אדמור מסקולען ונ\"י","r":"אדמו\"ר מסקולען","bt":"תרנח","dt":"תשמב - כט אב","dp":"מונסי","b":"נכד ר חיים מסלפקביץ. חתן ר יעקב נכד ר אריה ליב המוכיח מפולנאה. ומקורב לאדמורי בית רוזין. רב בסקולען-תרעה על מקום אביו, עבר לטשרנוביץ בגלל מחלוקת (על כך ב\"זקן אהרן\") וכיהן כנשיא אגו\"י, ניצל מהשואה, ואחריה רב בבוקרשט, ושם דאג למאות יתומים מניצולי השואה, ועל כך נאסר כמה פעמים, בשנת תשך הופעל לחץ על הרומנים לשחררו, ואז הגיע לניו יורק והמשיך לעסוק בעזרה ליהודי מזרח אירופה הנתונים תחת השלטון הקומוניסטי. הקים בארץ רשת תתי\"ם \"חסד לאברהם\" לעזרה ליתומים וילדים. בנו ר ישראל אברהם אדמור על מקומו אחריו. חיבר \"נועם אליעזר\", ו\"קדושת אליעזר\". הלחין ניגונים ידועים.","bk":[["נועם אליעזר – תורה ומועדים",""],["קדושת אליעזר – אבות",""],["קונטרס השבת",""],["נועם אליעזר – תורה ומועדים, חידושי גור אריה – שבת עירובין פסחים, גבורות ה' (נדפס בתוך שו\"ת שם ושארית ישראל לאביו)",""]]},{"i":37544,"n":"פורטוגל, ישראל אברהם מנ\"י","f":"אליעזר זוסיא מסקולען","k":"אדמור מסקולען נ\"י","b":"חתן ר מנחם זאב שטרן מירושלים. אדמור מסקולען בנ\"י על מקום אביו. הקים מרכז תורה בבני ברק."},{"i":37545,"n":"פורטוגל, ישראל אברהם מסקולען","k":"אדמור מסקולען","r":"מסקולען,","bt":"תר","dt":"תרעה - יח אייר","b":"חתן ר חיים אב\"ד סלפקביץ. רב בסטודיניצא, לינוויץ, נובו-אודיצא, סקולען ובנו ר אליעזר זוסיא על מקומו אחריו. (לא היה אדמור בארה\"ב ככתוב באוצר).","bk":[["שם ושארית ישראל – שו\"ת",""]]},{"i":37546,"n":"פורטמן, זליג הכהן מארה\"ב","f":"שמעון","bt":"תרנה","bp":"סטראבין-פלך מינסק","b":"תלמיד ישיבת סלוצק, ראדין, שקלוב. נסמך מאת ר איסר זלמן מלצר, ר דוד פינשטיין מסטרבין. רב ור\"מ בקפטקביץ-פלך מאזיר, אסיפוביטש-פלך בוברויסק, רב ור\"מ בראקאווי-ניו יורק-תרץ. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג. חבר אגודת ישראל."},{"i":37547,"n":"פורטמן, ישראל תנחום מז'אזמיר","dt":"תשא","b":"חתן ר בן ציון זאב קרניץ משוואקשנה, רב בשוועקשנא(=שוואקשנה)-תרפט על מקומו אחריו, רבה האחרון של ז'אזמיר על מקום ר יואל יצחק קצנלנבוגן. נספה בשואה."},{"i":37548,"n":"פורטמן, נחמיה הכהן","k":"בעל תורת חיים","bt":"תרמג","dt":"תשא - תמוז","b":"רבה האחרון של ניישטט-שאקי(=ניישטט שירווינט). נספה בשואה."},{"i":37549,"n":"פורטנוי, אליעזר ממונטריאול","b":"רב במונטריאול, ור\"מ בישיבת מיר. פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר. עורך \"מרכז התורה\" - מונטריאול תשב."},{"i":37550,"n":"פורטר - ציר אנגליה בטורקיה","b":"ציר אנגליה בתורכיה-תקי, כתב על בני כת ה\"דונמה\" בשלוניקי."},{"i":37551,"n":"פוריך, אלעזר הלוי","b":"מרבני אלכסנדריה"},{"i":37552,"n":"פורילה, אלימלך מאיסטיטשקה","f":"אפרים מרדכי מאיסטיט'","b":"רב בסלטוינה, איסטיטשקה, הוסיאטין, ניצל מהשואה ועבר לארה\"ב וכיהן כרב בניו יורק. חתן ר פנחס הורביץ מהוסיאטין."},{"i":37553,"n":"פורילה, אלימלך מהוסיאטין","dt":"תשיז","b":"רב בהוסיאטין-תר\"ע,ניו יורק"},{"i":37554,"n":"פורילה, אפרים מרדכי מאיסטיטשקה","f":"חיים יוסף ממיקוליניץ","k":"בעל מאמר מרדכי","bp":"מיקוליניץ","b":"רב באיסטיטשקה(=אושטיצק)-תרל. חתן ר ישראל שטרן מאיסטיטשקה. בנו ר אלימלך על מקומו אחריו. חיבר \"מאמר מרדכי\" תרעב. כתביו הרבים נשרפו בתרעד. ?? לא באוצר ??"},{"i":37555,"n":"פורילה, זאב וולף מבוצאץ","f":"אלכסנדר זיסקינד","k":"בעל שארית יהודה","bt":"תקעח","bp":"טויסט","dt":"תרס","b":"סוחר מצליח ולמדן בבוצאץ. פרנס הקהלה ונדבן. בשריפה בביתו נשרפו ספריו ורבים מחדושיו. בידידות עם גדולי דורו. חיבר \"שארית יהודה\" למברג תרמ, ועוד. ?? לא באוצר ??"},{"i":37556,"n":"פורילה, ישעיה ממיקוליניץ","b":"רב במיקוליניץ. חתן ר אריה יהודה ליבש בומזה תלמיד הבעשט."},{"i":37557,"n":"פורילה, ישראל","f":"אלימלך מאיסטיטשקה","k":"בעל באר שרים","b":"גיליד גליצה ועבר לארה\"ב, רב בניו יורק. חתן ר שלום משה שפירא מבורו-פארק. חיבר \"באר שרים\" ניו יורק תשח. ?? לא באוצר ??"},{"i":37558,"n":"פורילה, שמואל מבוצאץ","f":"חיים צבי מצבואץ","bt":"תקץ","bp":"בוצאץ","dt":"תרנא","b":"מחכמי בוצאץ. חתן דודו הגביר ר נח אליעזר מילר. לזכרו \"ציון לנפש\" מאת תלמידו דרוהוביטש תרנד."},{"i":37559,"n":"פורילי זאב וולף בן אלכסנדר זיסקינד","bt":"1818","dt":"ה'תרס 1900","bk":[["דרישת הזאב",""],["דרך אמונה",""],["חוסן רב",""],["חקת הפסח",""],["מוסך השבת",""]]},{"i":37560,"n":"פורינץ, אשר","b":"מגדולי חכמי איטליה בפלורנץ-ש\"נ"},{"i":37561,"n":"פורית, שלמה משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":37562,"n":"פורכטגוט, יחזקאל","f":"[אלתר]","b":"מחכמי קראקא, עבר לאנטורפן."},{"i":37563,"n":"פורמא ן, משה מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":37564,"n":"פורמיגיני, יצחק מטריאסט","f":"משה","b":"רב בטריאסט-שנות ה-ת' - בזמן ר דוד אופנהיים. מתורתו ב\"שמש צדקה\" ו\"פחד יצחק\" ועוד."},{"i":37565,"n":"פורמיג'יני, יצחק מליוורנו","b":"רב בליוורנו-תק, טורינו. החידא היה אצלו בתקטז. חתם-תקד עם רבני מודנא ר מנשה יהושע מצליח, ר משה ליפשיץ ור אברהם חי גרציאנו בענין 'וי\"ו' קטיעא בפרשת פנחס."},{"i":37566,"n":"פורמיגיני, נתן שלמה מאיטליה","b":"מחכמי איטליה."},{"i":37567,"n":"פורמש, משה ממרוקו אלגיר","f":"שלמה","b":"רב בקלעת חמאד בדור שאחרי רבינו חננאל, כנזכר בספר \"יוחסין\" לראב\"ד."},{"i":37568,"n":"פורמש, שלמה הדיין","b":"דיין בקלעת חמאד-מרוקו, אחרי רבנו חננאל ורבנו נסים."},{"i":37569,"n":"פורנא ן, יוסף משלוניקי","dt":"רפא","b":"מחכמי שלוניקי."},{"i":37570,"n":"פורנא ן, יעקב מקושטא","f":"דוד","b":"מגיה בדפוס יונה בן יעקב בקושטא-תעא."},{"i":37571,"n":"פורנברג, קרל - רוזנברג, ישעיהו","f":"חיים","k":"בעל וועלט געשיכטע","bt":"1871","bp":"סלובודקה","dt":"1938","b":"היגר לארה\"ב, חבר ב\"בונד\". עורך \"די אידישע ארבייטער וועלט\" - שיקגו, יסד את \"אידישע שטימע\", השתתף בעריכת האנציקלופדיה היהודית רוסית. ?? לא באוצר ??"},{"i":37572,"n":"פורקעס, דוד","b":"רב-שנת תק\"י"},{"i":37573,"n":"פורר, יהודה ליב מואבאלניק","f":"אברהם","bt":"תרלט","b":"רב בוובלוניקי(=ואבאלניק)-פלך קובנא-תרסז."},{"i":37574,"n":"פורר, יהודה ליב מואבולניק","dt":"תש..","b":"רבה האחרון של ואבולניק-ליטא-תרסז. נספה בשואה."},{"i":37575,"n":"פורר, מנשה מצרפת, בוסטון","k":"בעל משנת מנשה","b":"ר\"מ בישיבת \"אור יוסף\" בצרפת, רב בבוסטון."},{"i":37576,"n":"פורשלגר, מיכאל אליעזר","bt":"תרמו","dt":"תשיט - טו חשון","b":"גדול בנגלה ונסתר,רב בבלטימור"},{"i":37577,"n":"פורת, אליעזר אבא מארה\"ב","f":"אריה ליב מירושלים","bp":"ירושלים","b":"סוחר בשיקגו."},{"i":37578,"n":"פורת, אריה ליב מירושלים","f":"יוסף","b":"ראש משפחת פורת בירושלים."},{"i":37579,"n":"פורת, יוסף בעל התוספות","f":"רשב\"ם או משה","b":"מגדולי בעלי התוספות בטרויש-ד'תתקמ. נזכר בשאת הראב\"ן מאת הרשב\"ם \"ומפלגי מימיו.. לארבעה ראשים והנהר הרביעי הוא פרת\", אך לדעת המרדכי שם אביו - משה."},{"i":37580,"n":"פורת, יצחק מפאס","b":"מחכמי פאס-שנות ה-תק', קינה לזכרו מאת ר חיים דוד סירירו."},{"i":37581,"n":"פורת, ישראל מארה\"ב","f":"אריה ליב בן יוסף","k":"בעל מבוא התלמוד","bt":"תרמז","bp":"ירושלים","dt":"תשלד - יט ניסן","b":"תלמיד ישיבות \"עץ חיים\", \"אהל משה\" בירושלים, נסמך מאת: הרידב\"ז, ר חיים ברלין, ר אברהם יצחק קוק. יסד בירושלים \"בית ועד לחכמים\". היה מועמד למשרת רב ראשי בארץ ישראל-תרעא, ר\"מ ומנהל ביהמ\"ד \"דרוש לציון\" ורשת בתי חנוך לעדות הספרדים בירושלים. בשליחות בקושטא לטובת חכמי התורה ובני הישיבות בארץ. רב בפליינפלד-ניו ג'רסי-תרפג, קליבלנד-תשב. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":37582,"n":"פורת, נח מירושלים","f":"אריה ליב מירושלים","bp":"ירושלים","b":"מורה בת\"ת נצח ישראל בפתח תקוה, ת\"ת מזרחי בירושלים."},{"i":37583,"n":"פורת, שלמה משלוניקי","b":"מחכמי שלוניקי-שנות הר'-ש'."},{"i":37584,"n":"פורת-פוריית, משה פרגר מירושלים","f":"ישראל נפתלי הירש","k":"בעל דרכי ציון","bp":"פרג","b":"מחכמי ירושלים ממשפחת בעל השל\"ה. היה סופר סתם. בשנת תי בשליחות באשכנז. חיבר \"דרכי ציון\" פרנקפורט תי."},{"i":37585,"n":"פושטיר, יהודה מאלגיר","f":"יעקב","bt":"רע","dt":"שן - בערך","b":"רב ומשורר בתלמסאן. נזכר במכתב ר יהודה שוראקי ור מימון כלץ, מבוא ל\"עומר השכחה\" מאת ר שמואל סיראט - ירושלים תשלג."},{"i":37586,"n":"פושניץ, יצחק","dt":"תרסד","b":"רב בדברינקא-תרי\"ד"},{"i":37587,"n":"פושניץ, מנחם מנדל מדאברייא","f":"יצחק","bt":"תרלא","b":"רב בדברינקה(=דאברייא)-פלך חרסון לצד אביו ועל מקומו אחריו-תרסד."},{"i":37588,"n":"פ\"ח, יצחק מירושלים","f":"שלמה","bp":"ירושלים","dt":"תרמו - ח שבט","dp":"ירושלים","b":"מחכמי ירושלים, מתורגמן של ר ישעיה ברדקי במגעיו עם השלטון. נזכר בשטר חזקה-תקצח. בשליחות במצרים. ראה גם: יצחק בן שלמה אשכנזי מחברון."},{"i":37589,"n":"פ\"ח, שלמה מוילנא וירושלים","f":"ישראל","b":"מחכמי ירושלים, עסק בפיתוח חותמות, עסקן ופעיל בישוב ארץ ישראל. בנו - ר יצחק. בשליחות להביא כספי התרומות מוילנא לירושלים-תקפה בערך."},{"i":37590,"n":"פחאל, יעקב מאלגיר","bt":"שי","dt":"שפ - בערך","b":"רב בקצמטינא, תשובות אליו מרשב\"ץ."},{"i":37591,"n":"פחימא, יעקב מאלגיר","bt":"תק","dt":"תקף - בערך","b":"רב בתלמסאן. נזכר בשטר-תקלב."},{"i":37592,"n":"פחימא, שאול מתילית-מרוקו","b":"מחכמי תילית-מרוקו, חתם-תרס בערך על תקנה של השד\"ר ר מסעוד אדהאן."},{"i":37593,"n":"פחימה, ישעיה ממרוקו","f":"יוסף","b":"מחכמי מרוקו-מהשנים-תר-תש. חיבר ליקוטים."},{"i":37594,"n":"פטאל, אברהם הלוי","f":"משה","k":"בעל ויאמר אברהם","r":"חמיו של הרב 'עובדיה יוסף'","bt":"תרנב","bp":"חלב","dt":"תשמא - יט תמוז","dp":"ירושלים","b":"ירושלים-תר\"פ, רב ודיין באנטיוכיה, עבר לדמשק, מלמד, דרשן, עלה שוב לירושלים-תרצ\"ו, למד קבלה, חיבר \"ויאמר אברהם\", חותנו של ר' עובדיה יוסף","bk":[["ויאמר אברהם - על התורה",""],["ויאמר אברהם",""]]},{"i":37595,"n":"פטוכובסקי, שמואל","bp":"ליטא","dt":"1941","b":"סגן ראש עירית שאוולי, בזמן הכיבוש הנאצי היה חבר המועצה היהודית. נספה בשואה."},{"i":37596,"n":"פטיט, שלמה (הקטן)","f":"שמואל","bp":"צרפת","b":"מחכמי צרפת מזמן בעלי התוספות, עלה לעכו בשנת מ' (1280). ממתנגדי \"מורה נבוכים\", היה מעורב במחלוקת גם בעכו וגם בכל קהלות ישראל בענין זה. מתלמידיו ר יצחק בן טודרוס ור יצחק בן שמואל מעכו שהיו גם מתלמידי הרמבן."},{"i":37597,"n":"פטיט, שלמה מארץ ישראל","f":"שמואל","b":"מחכמי ארץ ישראל בדור שאחרי הרמבן. התנגד לפילוסופיה של הרמבם, והחרים את לומדי \"מורה נבוכים\". בשנת ה'נ הוטל עליו חרם בידי ראש הגולה ר דוד בן דניאל שחם עם רבנים נוספים."},{"i":37598,"n":"פטילון, יהודה ליאון","dt":"תשלח","dp":"ירושלים","b":"בעל מופת,צייר ביפו"},{"i":37599,"n":"פטישמכר, ישכר דב מפלאוונא","f":"יחזקאל","bp":"טרנוב","b":"רב בפלאוונא, טרנוב-תרעד."},{"i":37600,"n":"פטמן, אליהו","dt":"תש","b":"מרבני וורשה"},{"i":37601,"n":"פטמן, דוד מפרשבורג","b":"שו\"ב בפרשבורג."},{"i":37602,"n":"פטמן, חיים פסח מפסט וצפת","k":"בעל תורת חיים","b":"רב בפעסט, צפת, ניו יורק."},{"i":37603,"n":"פטמן, יהודה ליב מפרשבורג","f":"דוד מפרשבורג","b":"ש\"ץ בבית המדרש של ישיבת פרשבורג - שבו הקפידו על נוסח פרשבורג הקדום ועם הנהגות שתיקן החת\"ס."},{"i":37604,"n":"פטר בעל התוספות מצרפת","k":"בעל התוספות","dt":"ד'תתקז","b":"עק\"ה,מגדולי חכמי דורו בצרפת,מבעלי התוספות"},{"i":37605,"n":"פטרזייל, יאיר מברלין","bt":"תרל","dt":"תרצח","dp":"תל אביב","b":"רב בברלין, בשנת תרצד עלה לתל אביב. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":37606,"n":"פטרזילקי, יעקב מנאדאש","f":"ישכר בער בלוך","b":"רב בנאדאש-תקצ\"ו"},{"i":37607,"n":"פטרמן, ליטמן מפרוטוויץ","b":"שו\"ב בפרוטוויץ חדש. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":37608,"n":"פטרפרוינד, חיים","f":"אברהם מקרניץ","b":"חתן ר יצחק יעקב הירשנהורן מטרנוב."},{"i":37609,"n":"פטרפרוינד, משה","f":"חיים יצחק מטשבין","dt":"תשנח","b":"ניצל מהשואה ועבר ליוהניסבורג. חסיד בובוב. עלה לארץ."},{"i":37610,"n":"פטרפרוינד-וינפלד, אברהם צבי","f":"משה יהודה ויינפלד","dt":"תש..","b":"שו\"ב בצאנז. נכד הרבי ר השל. חתן ר יהושע ברוינפלד מגורליץ. נספה בשואה."},{"i":37611,"n":"פיאדי, מנחם מסופיה","f":"מרדכי","b":"סוחר בסופיה-תקסה, נהרג ליד סאמאקוב עם יזרעאל אלקלעי מניש."},{"i":37612,"n":"פיאדי, שלמה מסופיה","b":"רב בסופיה-שנות ה-ת'-תק', ודיינים אצלו - ר אברהם בכר יצחק, ר ישעיה בכר חיים ברוך."},{"i":37613,"n":"פיאטילאי, יהודה מרומא","f":"מרדכי","b":"רב ברומא. חתום ב\"מלחמה לה'\"-תעד על החרם נגד נחמיה חיון."},{"i":37614,"n":"פיאטניצקי, יוסף","f":"אהרן","bt":"1882","bp":"ליטא","dt":"1938","b":"חבר במפלגת ס.ד. בקובנא. נאסר-1902 וברח לחו\"ל, נאסר שנית-1906. מזכיר ועד המפלגה הקומוניסטית במוסקבה. חבר בועדת הטיהור-1933. הוצא להורג-1938."},{"i":37615,"n":"פיאטרושקא, שמחה מקנדה","k":"בעל יידישע פאלקס אנצ","bp":"פולין","b":"הגיע מפולין לקנדה. חיבר פירוש למשנה באידיש, אנציקלופדיה יהודית באידיש-תשד."},{"i":37616,"n":"פיאלקוב, אשר מסטולין","bt":"תרלה","dt":"תשג","b":"רב בסטאלין(=סטולין)-תרנ\"ד"},{"i":37617,"n":"פיאמנטה, יוסף מאיטליה","k":"בעל אור בוקר","dt":"תפא","b":"מקובל, אב\"ד באנקונה. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה. חיבר ספר בקשות לעת רעש - על הרעש שהיה בשנת תנא, חיבר קינה על פטירת ר משה זכות-תנח."},{"i":37618,"n":"פיאסקובסקי, מרדכי ליב מליפנא","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":37619,"n":"פיאסקר, צבי הירש מקראקא","f":"ישראל","b":"פרנס ומנהיג בקראקא-תקם."},{"i":37620,"n":"פיארה די, משלם מספרד","f":"שלמה","b":"משורר מחכמי ספרד בזמן הרמבן, תלמיד ר עזרא ור עזריאל בן שלמה מגירונה. חכתב שירים לכבוד הרמב\"ן. מקורב לר אברהם ן חסדאי ולר יצחק בר יהודה השנירי, מתנגד לפילוספיה של הרמבם. מגדולי המשוררים בדורו."},{"i":37621,"n":"פיבוש","k":"ראה: פיבוש","b":"רב בסטאניסלב"},{"i":37622,"n":"פיבוש אשכנזי מוילנא וירושלים","f":"מהר\"ם מהורודישץ","k":"אורי שרגא","b":"תלמיד ר ישראל יפה בעל \"אור ישראל\" משקלוב. רב בוילנא על מקום ר מנחם מאניש חיות. עלה לארץ ונתקבל לנשיא. אחיו של ר יצחק מסמיאטיש, ר דוד מיאנוב. מצאצאיו ר יצחק בעל \"זיר יצחק\"."},{"i":37623,"n":"פיבוש אשכנזי מירושלים","b":"ראש העדה האשכנזית בירושלים בשנת רעד, כמה מפסקיו בספר \"חדושי דינים לרבני ירושלים הקדמונים\"."},{"i":37624,"n":"פיבוש הכהן מואנדסבק","f":"אברהם כץ","dt":"תקלז - יג חשון","dp":"ונדסבק","b":"מקובל, דיין בואנדסבק. מגיה מחזור אלטונא וחיבר לו הקדמה."},{"i":37625,"n":"פיבוש יפה, אהרן אורי","b":"מגדולי חכמי איטליה,רב בוירונה-שפ\"ד"},{"i":37626,"n":"פיבוש י\"ץ מאוסטרהא","b":"רב באוסטרהא. נזכר ב\"נודע ביהודה\" בדבר היתר עגונה בת ר שמואל שמלקא כץ מאוסטרהא - בזמן השריפה-תקלז וכתב קונטרס לאיסור, וכנגדו כתב ר יוסף חיים מאוסטרהא והאלשיץ קונטרס להיתר ושלחו דבריהם ל\"נודע ביהודה\" בפרג."},{"i":37627,"n":"פיבוש מבריסק","b":"רב בבריסק-שנות הת'. מתלמידיו - בעל הב\"ח."},{"i":37628,"n":"פיבוש מוינה","b":"מגדולי חכמי דורו,רב בווינה-ת\"כ"},{"i":37629,"n":"פיבוש מירושלים","k":"ר' פייבוש הזקן","b":"מרבני אשכנז בירושלים-ש\"כ"},{"i":37630,"n":"פיבוש ממיר וירושלים","dt":"תריח - טו אלול","dp":"ירושלים","b":"דיין במיר, עלה לירושלים."},{"i":37631,"n":"פיבוש מקולוניא","b":"מרביץ תורה בקולוניא-רי\"ז"},{"i":37632,"n":"פיבוש מקלן","b":"מגדולי חכמי אשכנז,רב בקלן-ר\"י"},{"i":37633,"n":"פיבוש מקראקא","b":"תקנות ממנו בענין שבת ב\"כבוד חכמים\"."},{"i":37634,"n":"פיבוש, אורי שרגא","dt":"תקפא - כד אד\"ב","b":"רב בשאחטיץ"},{"i":37635,"n":"פיבושביץ, שמואל (שאול)","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":37636,"n":"פיביש הכהן מאושיצא","b":"רב באושיצא."},{"i":37637,"n":"פיביש מבולשוויץ","b":"תלמיד ר אלימלך מליזנסק, ור משה יהודה ליב מסאסוב."},{"i":37638,"n":"פיביש מהיבנוב","dp":"מזבוז","b":"תלמיד החוזה מלובלין, ר אברהם יהושע השל מאפטא וידידו של ר נפתלי מרופשיץ והשר שלום מבלז. שימש כש\"ץ אצל החוזה ובשעת תפילתו רץ ממקום למקום בהתלהבות. נטמן ליד הבעשט במזבוז."},{"i":37639,"n":"פיבל הלוי מברודשין","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":37640,"n":"פיבל מלבוב","f":"יעקב קופל","b":"מראשי קהלת לבוב, חתם-תקד על כרוז ותקנה."},{"i":37641,"n":"פיבל מלכביץ","b":"רב בלעכוויץ"},{"i":37642,"n":"פיבל מפפד\"א וברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":37643,"n":"פיבל מקאליש","b":"דומ\"צ בקאליש"},{"i":37644,"n":"פיבל מקראקא","dt":"תנז - ז אב","b":"ראב\"ד בקרקא"},{"i":37645,"n":"פיבל מריקי","b":"אב\"ד ריקי. משמשו של ר מנחם מנדל מקוצק."},{"i":37646,"n":"פיבל סגי נהור מטבריה","b":"מחסידי טבריה."},{"i":37647,"n":"פיבלסון, אברהם יצחק","f":"שמואל אביגדור","b":"רב בביסיגולה על מקום ר אהרן באקשט, ור ישראל בנימין פיבלסון על מקומו אחריו."},{"i":37648,"n":"פיבלסון, אברהם יצחק מנ\"י","f":"שמואל אביגדור","b":"היגר לניו יורק-אחרי תרעח, יסד עם ר יוסף רוזין את ועד הרבנים בניו יורק. עורך ופרסם מאמרים ב\"המסלה\" - נ\"י תרצו."},{"i":37649,"n":"פיבלסון, אליהו מאיר מקופישוק","f":"ברוך מואיגובה","k":"בעל האמת והשלום","bt":"תרכז - כה טבת","bp":"ואיגובה(=ויגובר)","dt":"תרפה-ח - כה טבת","b":"נכד ר יוסף מערזוויליג בן ישראל בן ליב. תלמיד ישיבת קעלם, גריבין, טלז, סלובודקא, וולוזין. חתן ר חיים שאול לונץ מקעלם. רב בקרוק-מחוז קידאן-תרנז (פלך קובנא), קופישוק-פלך קובנא-תרסז וחתנו ר זלמן פרצובסקי על מקומו אחריו. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"הפלס\", \"שערי ציון\" - ירושלים תרפא, ועוד. התנגד לציונות. חיבר גם \"פקוח נפש\", \"מעין ברוך\", ועוד - בכת\"י."},{"i":37650,"n":"פיבלסון, בנימין","bt":"1896","bp":"קובנא","dt":"1920","dp":"מינכן","b":"תלמיד ביה\"ס לאמנות \"בצלאל\" בירושלים, ומורה שם. צייר, התפרסם בריקמה וציור על זכוכית.."},{"i":37651,"n":"פיבלסון, ברוך ויגובאר הזקן","f":"יוסף מערזוויליג","b":"גביר בעל אחוזה ותלמיד חכם בויגובה(=ויגובר). רב בויגובר, רב בשוקיאן-תרל. בניו: ר ישראל בנימין מבייסאגולא בעל \"לבני ישראל\", ר שמואל אביגדור מפלונגיאן, ר אליהו מאיר, ר יוסף אליעזר. וחתנו ר שלמה יעקב שיין."},{"i":37652,"n":"פיבלסון, ברוך יוסף מראדין","f":"אליהו מאיר פייבלסון","bt":"תרנו","dt":"תרצג - יט אב","b":"ר\"מ בראדין. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":37653,"n":"פיבלסון, ברוך משה מארה\"ב","f":"שמואל אביגדור","k":"בעל ברכות משה","bt":"תרמב","bp":"בייסיגולה-ליטא","b":"תלמיד ישיבות טלז, סלובודקה. רב בביסיגולה-תרפב, ניו יורק-תרצח. מזכיר \"עזרת תורה\". פרסם מאמרים בעתונות היהודית באמריקה. עלה לארץ."},{"i":37654,"n":"פיבלסון, ברוך משוקיאן הנכד","f":"ישראל בנימין בנדט","dt":"תשב","b":"רב בשוקיאן על מקום אביו. נספה בשואה."},{"i":37655,"n":"פיבלסון, יוסף","f":"ישראל בנימין","dt":"תשג","b":"רב בסלובודקה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":37656,"n":"פיבלסון, יוסף אליעזר מואיגובה","f":"ברוך מואיגובה","bp":"ואיגובה","b":"רב בויגובה-תרפ."},{"i":37657,"n":"פיבלסון, ישראל בנימין בנדט","f":"ברוך מואיגובה","k":"בעל סגולות ישראל","bt":"תרכה","bp":"ואיגובה","dt":"תרצז-ח - א סיון","b":"תלמיד ישיבות קלם, גרובין, טלז, סלובודקה, וולוזין. רב בביסיגולה(=בייסאגאלא)פלך קובנא-תרנח על מקום ר אברהם יצחק פיבלסון ובנו ר יוסף על מקומו אחריו, שוקיאן-תרפד על מקום אביו. חיבר גם \"מוסר ישראל\", \"לבני ישראל\", ועוד. חתנו - ר יעקב ולפה אב\"ד אוז'וונט-ליטא. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"כנסת הגדולה\" - וארשא תרן, \"שערי ציון\" - ירושלים תרפא, \"מאסף דרושי\" - וילנא תרסט, \"המצפה\" - נ\"י תרע, \"הפלס\" - ברלין תרסא-תרסה, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":37658,"n":"פיבלסון, שמואל אביגדור מליטא","f":"ברוך מואיגובה","bt":"תריב-ט","bp":"ואיגובה","dt":"תרפה-ט -יז כסלו","dp":"ברלין","b":"תלמיד ישיבת טלז, איישישוק, ביאליסטוק יחד עם ר מאיר שמחה הכהן בעל \"אור שמח\". נהג ללמוד 80 דפים ביום. רב בביסיגולה-תרמה על מקום ר אברהם יצחק גרושקין ור אהרן באקשט על מקומו אחריו, שוואקשנה-עד תרסא, אניקשט על מקום ר אברהם אהרן בורשטין ור אליהו בער שור על מקומו אחריו, פלונגיאן-פלך קובנא. דרשן מוכשר. הניח חבורים על הש\"ס ושו\"ע שנכתבו בקיצור וברמזים. גיסו של ר שלמה יעקב שיין בעל \"אבני שיש\"-בעל אחותו."},{"i":37659,"n":"פיגו, אברהם מאזמיר","b":"רב באזמיר-שנות ה-ש'."},{"i":37660,"n":"פיגו, אפרים","dt":"שסו - ה כסלו","b":"מגדולי רבני איטליה, רב בוויניציאה. אביו של ר עזריה."},{"i":37661,"n":"פיגו, וידאל משלוניקי","dt":"שעה - כב אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37662,"n":"פיגו, יהודה מצפת","b":"רב בצפת-שצו."},{"i":37663,"n":"פיגו, משה מקושטא","f":"יוסף","k":"בעל זכרון תורת משה","b":"מחכמי קושטא. חיבר מפתח מאמרי הש\"ס בשם \"זכרון תורת משה\" - קושטא שיד. בנו - יוסף נפטר בחיי אביו."},{"i":37664,"n":"פיגו, משה משלוניקי","dt":"תלד - ה חשון","dp":"שלוניקי","b":"מחכמי שלוניקי. ממשפחת ר שלמה פיג'ו ור יוסף פיג'ו."},{"i":37665,"n":"פיגו, עזריה מונציה","f":"אפרים","k":"בעל גדולי תרומה","bt":"שלט","bp":"ונציה","dt":"תז - א אד\"א","b":"למד מדעים באוניברסיטה בונציה. תלמיד ר אברהם אבוהב. רב בפיזא-שסז, ונציה-שפז, רוויגו-תה. חיבר את ספרו \"גדולי תרומה\" על ספר התרומה ללא ספרי הש\"ס - שנשרפו בפקודת האפיפיור, ונעזר בכח זכרונו, ואכן בעל הש\"ך שחיבב מאוד את הספר השיג עליו כמה פעמים שנעלמו ממנו מה שכתוב במקום פלוני. בניו ר אפרים שחיבר ביאור ל\"אדם וחוה\" ור אליעזר נפטרו בחייו במגפה. מתלמידיו ר משה זכות, ר יעקב יזבל ור שמואל אבוהב. תשובה ממנו ב\"המאור\" - תל אביב תרצה."},{"i":37666,"n":"פיגו, שלמה","b":"מגדולי חכמי שאלוניקי-ת\"כ"},{"i":37667,"n":"פיג'וטו - משפחה","b":"משפחה שמוצאה מאיטליה, וישבו גם בחלב, מצרים ועוד."},{"i":37668,"n":"פיג'וטו, אליהו","f":"רפאל","b":"קונסול אוסטריה בחלב, יסד ישיבה בירושלים בשם \"כסא אליהו\" בראשות היש\"א ברכה (התקימה עד תרנו)."},{"i":37669,"n":"פיג'וטו, בנימין פרנקלין","bt":"1834","bp":"ניו יורק","dt":"תרנא","dp":"ניו יורק","b":"קונסול ארה\"ב בבוקרשט, וסייע ליהודי רומניה. עורך הירחון \"מנורה\"."},{"i":37670,"n":"פיג'וטו, דוד הלל מביירות","b":"גביר מחכמי ביירות, תרם לטובת עניי ירושלים באמצעות גבאי הצדקה הגביר יעקב ולירו."},{"i":37671,"n":"פיג'וטו, דניאל משה מחלב","f":"משה","b":"גביר בחלב, קונסול רוסיה בחלב. בנו - העסקן משה פיג'וטו."},{"i":37672,"n":"פיג'וטו, הלל חי (חיים) מליוורנ","dt":"תריט - י סיון","dp":"חלב","b":"חתן מהר\"ם ן חביב. עבר מליוורנו לחלב, גביר נדיב שסייע ליהודי ארץ ישראל. שיר לזכרו אצל ר נתן עמרם בקונטרס פיוטים. סייע בהדפסת \"מחנה יהודה\" לר\"י קצין."},{"i":37673,"n":"פיג'וטו, חי משה","f":"חיים הלל חי","k":"בעל ויחל משה","dt":"תקעה - כו טבת","dp":"דמשק","b":"רב בחלב, דמשק, חיבר \"ויחל משה\". אחיו של הגביר ר רפאל."},{"i":37674,"n":"פיג'וטו, יוסף עזרא מאלכסנדריה","bt":"תרלב","bp":"אלכסנדריה","b":"גביר מחכמי מצרים."},{"i":37675,"n":"פיג'וטו, יצחק מדמשק","b":"גביר בדמשק, נאסר בעלילת הדם-תר."},{"i":37676,"n":"פיג'וטו, יצחק שלמה","b":"אין פרטים"},{"i":37677,"n":"פיג'וטו, משה אליהו מחלב","b":"נכד הגביר ר רפאל. קונסול אוסטריה בחלב, ביקר בירושלים עם הקיסר פרנץ יוסף-תרל. מתומכי הישוב היהודי בארץ."},{"i":37678,"n":"פיג'וטו, משה חיים מחלב","bt":"תקסו","bp":"חלב","dt":"תרלט","dp":"לונדון","b":"מראשי הקהלה בחלב, פעל ליסד בית מדרש, היגר לגיברלטר, מרוקו, והיה נציג ועד הקהלות המאוחדות באנגליה בזמן מלחמת מרוקו ספרד-תרך. בנו - ג'יימס."},{"i":37679,"n":"פיג'וטו, משה מדמשק","b":"גביר בדמשק-תקסח"},{"i":37680,"n":"פיג'וטו, משה מחלב","f":"דניאל","bt":"תרכח","bp":"חלב","b":"נכד ר משה-קונסול אוסטריה בחלב. היגר מחלב לאנבירס-בלגיה, מנצסטר-אנגליה-תרסז, סייע בהקמת \"אוצר התישבות היהודים\", \"קרן היסוד\". ראש הקהלה הספרדית במנצסטר (הקהלה מנתה כ-500 משפחות). עלה לארץ והתישב בתל אביב."},{"i":37681,"n":"פיג'וטו, רפאל","dp":"טבריה","b":"קונסול אוסטריה בחלב-1838, ובנו אליהו על מקומו אחריו, ונכדו משה ונינו דניאל אחריהם. חתם על כתב שליחות ר זכריה זמירו, עלה לארץ-תריד והתישב בטבריה."},{"i":37682,"n":"פיג'וטו, שמואל דניאל מחלב","b":"אין פרטים"},{"i":37683,"n":"פיג'ון, יוסף משלוניקי - א","k":"בעל מנהגי הבדיקה","dt":"שסט - אחרי","b":"מחכמי שלוניקי, ובקי בדיני שחיטות ובדיקות ועל פי הוראותיו נהגו בשלוניקי. נזכר בתשובות ר יצחק לוי ואלי. חתנו - ר דוד פלורנטין משלוניקי."},{"i":37684,"n":"פיג'ון, יוסף משלוניקי - ב","dt":"תקלג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37685,"n":"פיג'ון, יוסף משלוניקי וקושטא","k":"בעל דורש משפט","dp":"קושטא","b":"מחכמי שלוניקי-שנות ה-ת', עבר לקושטא. מכונה \"הבודק הגדול\" והיה מגדולי מורי ההוראה בדורו."},{"i":37686,"n":"פיג'ון, יצחק משלוניקי","b":"מחכמי שלוניקי-תלג, שאל את ר חיים בנבנישתי."},{"i":37687,"n":"פיג'ון, מנחם מאזמיר","bt":"תקנג","dt":"תרכד","dp":"אזמיר","b":"רב ודיין באזמיר. תלמיד ר יצחק נאברו. חתן ר חיים פלאג'י שמזכירו בספרו. בנו - ר יצחק."},{"i":37688,"n":"פיג'ון, שלמה משלוניקי","b":"תלמיד הרשד\"ם. מחכמי שלוניקי. קרובו של ר יוסף פיג'ון."},{"i":37689,"n":"פיגלסברג, חיים","dt":"תרכו - ד שבט","b":"רב פעלים,רב בקישקערעש"},{"i":37690,"n":"פיגלסון, בן ציון","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":37691,"n":"פיגלשטוק, אברהם ממונטוידאו","f":"שלום מצעהלים","bt":"תרן","bp":"צעהלים","dt":"תשיב","dp":"ניו יורק","b":"תלמיד הדעת סופר, ועוד. חתן ר ישעיה פרידמן מטלאפטשן. רב בוינה-תרפה, ברח לאורגוואי-תש ונתמנה לדיין במונטוידאו (בקהילת הר מלבסקי), עבר לניו יורק."},{"i":37692,"n":"פיגנבוים, דוד הלוי","dt":"תשג","b":"רב בפרוזשינע"},{"i":37693,"n":"פיגנבוים, יוסף מטורנא","b":"מחכמי טורנא-תרנז. מחותן עם ר חיים גלרנטר."},{"i":37694,"n":"פיגנבוים, יעקב שלמה מוארשא","f":"יצחק הכהן מוארשא","b":"הו\"ל \"שערי תורה\" - וארשא תרסג-תרצט - יחד עם אחיו ר ישראל."},{"i":37695,"n":"פיגנבוים, יצחק הכהן מוארשא","f":"ישראל איסר","k":"בעל זכרון מרדכי","bt":"תקצא","dt":"תרעא - כד אייר","b":"חסיד קוצק, גור, אלכסנדר, ומחשובי תלמידי ר אברהם מסוכטשוב. רב בוארשא-תרכא. עורך \"יגדיל תורה\", \"שערי תורה\" - וארשא תרסג. מתומכי הישוב בארץ. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":37696,"n":"פיגנבוים, ישראל איסר מוארשא","f":"יצחק הכהן מוארשא","dt":"תש..","b":"עורך: \"שער יעקב\" ו\"שערי תורה\" - וארשא תרפב (בתוך \"שער בת רבים), \"שערי תורה\" - וארשא תרסג-תרצט. נספה בשואה."},{"i":37697,"n":"פיגנבוים, מרדכי","b":"חסיד טשבין?-תרמט."},{"i":37698,"n":"פיגנבוים, נחום","b":"רב בקרסניברד-תר\"ס"},{"i":37699,"n":"פיגנבוים, שלום יוסף הלוי מלוקט","f":"זאב","k":"בעל נתיבות שלום","bt":"תרכב","dt":"תרצה - כח חשון","b":"מו\"ץ בסמוטריטש-גליציה-תרנ, רב בלוקאטש(=לאקאטש)-ווהלין-תרסא. נסמך מאת ר שמואל אברהם מקונסטנטין, רמ\"א מיאזלוויץ. חיבר גם \"שמן למנחה\" על \"מנחת חינוך\", ועוד. הסכים על \"אהל יצחק\" - סטמר תרסג. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"בית ועד לחכמים\" - סטמר תרפב, \"הנצח\" - לבוב תרפז, \"אהל תורה\" - קראקא תרפח, \"אור המאיר\" - וארשא תרצו, \"אור תורה\" - לבוב תרפו, \"אסיפת חכמים\" - מלניץ תרפח, \"הבאר\" - זאמושץ-וארשא - תרפד, \"דגל הרבנים\" - וארשא תרפו, \"חדרי תורה\", \"יגדיל תורה\" - פראגא-וארשא תרפז, \"כרם בית שמואל\" - פיעטרקוב תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג, \"הלבנון\" - סטמר תרפח, \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב, \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, \"עמק הלכה\" - וארשא תרפו, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג, \"קול תורה\" - וארשא תרסח, \"קול תורה\" - פאביאניץ תרפו, \"רשפי אש\" - לודז תרפז, \"שערי תורה\" - וארשא תרסג, \"התפוח\" - בנדין תרפח.","bk":[["משיב שלום [שו\"ת]",""],["נתיבות שלום [עה\"ת]",""]]},{"i":37700,"n":"פיגנזון, שמואל שרגא","f":"שלום","k":"שפ\"ן הסופר","bt":"1836","bp":"וילקומיר","dt":"1928","dp":"וילנא","b":"מנהל דפוס ראם בוילנא-1867. חיבר הקדמות ומבואות לספרים רבים. פרסם מאמרים רבים בחתימת \"שפן הסופר\". הו\"ל אגרון \"מכתב משולש\"-תרלט. סיפק חומר מדעי רב לפור' פ. דליטש. חיבר \"לתולדות דפוס ראם\", \"עלבונה של תורה\" - על השחתות הצנזורה."},{"i":37701,"n":"פיהם, שמואל מאיטליה וקראקא","f":"יצחק הקדוש","b":"מגיה בדפוס קרימונה-שטז, ונציה-שכד, פדובה, קראקא-של. חיבר הקדמות ושירים לספרים שהדפיס. חתם על פסקי דין עם ר יוסף אוטולינגו מקרימונה, ובענין גט תמרי."},{"i":37702,"n":"פיוואני, יוסף כהנא מפרג","f":"איזיק","k":"בעל זכרון יוסף","bp":"פרג","b":"מחכמי פרג בקי במדעים. חיבר ספר על חכמת המדידה - \"זכרון יוסף\" פרג תקנד."},{"i":37703,"n":"פיוטנק, אהרן יונה הלוי","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":37704,"n":"פיוטרקובסקי, אברהם","k":"בעל פסקי תשובה","dt":"תשא","b":"מו\"צ בטומשוב-תרצ, לודז-תרצג."},{"i":37705,"n":"פיוטרקובסקי, אברהם מפאביאניץ","b":"פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד."},{"i":37706,"n":"פיוטרקובסקי, אהרן חריף מלאסק","f":"משה מפיעטרקוב","dt":"תקצא - ח אב","b":"תלמיד ר פישל מסטריקוב. דיין בלאסק אצל ר מאיר צילך, ומראשוני החסידים שם, בנו - ר יצחק על מקומו אחריו."},{"i":37707,"n":"פיוטרקובסקי, אפרים הכהן","b":"פרסם מאמרים ב\"הלפיד\" - וארשא תרצז."},{"i":37708,"n":"פיוטרקובסקי, חיים יצחק מאוזרקו","b":"רב באוזרקוב. פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד."},{"i":37709,"n":"פיוטרקובסקי, יהושע ליב יחזקאל","b":"מחכמי לודז. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":37710,"n":"פיוטרקובסקי, יצחק מלאסק","f":"אהרן חריף מלאסק","k":"ר יצחק ר אהרן'ס","b":"דיין בלאסק-תר על מקום אביו."},{"i":37711,"n":"פיוטרקובסקי, ליבוש יחזקאל מלוד","b":"מחכמי לודז. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":37712,"n":"פיוטרקובסקי, משה מפיעטרקוב","b":"ראב\"ד בפיעטרקוב-תק\"מ. בנו - ר אהרן מלאסק. מתלמידיו ר אברהם צבי פצנובסקי בעל \"ברית אברהם\"."},{"i":37713,"n":"פיומי, דניאל בירב מתימן","bp":"תימן","dt":"ד'תתקמה","dp":"צנעא","b":"מחכמי תימן הקדומים, פייטן"},{"i":37714,"n":"פיומי, עובדיה תמים ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":37715,"n":"פיונטניצקי, יוסף מלומזה","f":"משה","k":"בעל נחל העורבים"},{"i":37716,"n":"פיורי, ברוך מרומא","f":"יואב","b":"מוזכר ב\"פחד יצחק\" בענין תשובת ר אליקים ממאציראטה על מצות יבום."},{"i":37717,"n":"פיורקא, אברהם מרדכי מגריבה","b":"הו\"ל \"בית המדרש החדש\" - גריבה תרפח."},{"i":37718,"n":"פיזא די, יחיאל נסים","f":"שמואל","k":"בעל מנחת קנאות","b":"גביר עשיר, רב בפיזא, פירארה-רצט. חיבר \"מנחת קנאות\" לכבוד ר יוחנן טריווש בעל \"קמחא דאבישונא\" - והוא תשובה לאגרת התנצלות של ר ידעיה הפניני."},{"i":37719,"n":"פיזה, נסים יוסף מאדרינופול","b":"דיין באדרינופול, חתם-תקצה על בקשת עזרה לקהלה מקהלת רוסג'וק לאחר השריפה עם הרבנים ר יוסף בכמוהר\"ר מרדכי ור יקיר אשטרוק גירון, ועם משה אלפאסה, חיים עובדיה, אהרן רודריג ויהודה בן יצחק."},{"i":37720,"n":"פיזיץ, אהרן מויסאקי","b":"רב בויסאקי"},{"i":37721,"n":"פיזיץ, אורי יצחק איזיק מירושלי","f":"אבא קדש מבריסק","k":"בעל מאורי יצחק","dt":"תרכז - י שבט","dp":"ירושלים","b":"נכד ר אהרן מויסאקי. מחכמי בריסק, עלה לירושלים, דיין בירושלים. חיבר קונקורדנציה תלמודית בשם \"מאורי יצחק\"."},{"i":37722,"n":"פיזיצר, משה","b":"רב בבריסק-תר\"י"},{"i":37723,"n":"פיזמן, יעקב שלמה הכהן מאסטרלנק","bt":"תרלא","bp":"אסטרלנקה","b":"רב בסרדניק-פלך קובנא, מו\"צ באסטרלנקה-פלך לומזה-תרסד."},{"i":37724,"n":"פיזנטי משה בן חיים","bt":"1540","dt":"ה'שלז 1577","bk":[["חקת הפסח",""],["ישע אלהים",""],["ישע אלקים",""],["נר מצוה",""]]},{"i":37725,"n":"פיזנטי, אברהם בכור","f":"יצחק","bt":"תרט","bp":"ירושלים","dt":"תרע - כא שבט","dp":"ירושלים","b":"מחנך מחכמי ירושלים. גיסו של ר יעקב חי בורלה."},{"i":37726,"n":"פיזנטי, בן ציון מירושלים","f":"יצחק חיים","bt":"תרלו","dt":"תרץ - ז טבת","dp":"ירושלים","b":"מרבני ירושלים, סופר בי\"ד, הדפיס ספרי ה\"בן איש חי\"."},{"i":37727,"n":"פיזנטי, דוד רחמים מירושלים","dt":"תרפג - כט אדר","dp":"ירושלים"},{"i":37728,"n":"פיזנטי, חיים יצחק מירושלים","f":"יהודה יהושע מקושטא","dt":"תקעו - כא תשרי","dp":"ירושלים","b":"מחכמי קושטא, עלה לירושלים, ראש ישיבת \"זרע יצחק\", דיין בירושלים-תרל אצל ר דוד ן שמעון(=דב\"ש), חתם על הסכמות ותעודות משנת תריט, וחתם עם ר אליהו עזרא ור יצחק בן מנחם בן ואליד-תרל, והסכים על מינוי ר יונה משה נבון לראשון לציון."},{"i":37729,"n":"פיזנטי, חיים מירושלים","f":"יצחק","dt":"תקעו - כא תשרי","dp":"ירושלים","b":"דיין בירושלים."},{"i":37730,"n":"פיזנטי, חיים משה מירושלים","b":"מחכמי ירושלים, בשנת תקצח במרוקו, חבר בית דינו של ר אברהם חיים גגין-אג\"ן וחתום עמו בשנת תרו ובשנת תרטז. משבעת טובי העיר, בשליחות ירושלים במרוקו-תקצח."},{"i":37731,"n":"פיזנטי, יהודה יהושע מקושטא","bp":"ירושלים","b":"רב בקושטא, עלה לירושלים-תרלז. חתנו של ר חיים דניאל שלמה פינסו בעל \"שיח חדש\", והיה מגדולי הדיינים בירושלים-תרסט וחבר בית דינו של ר חיים דוד סוראנגה, ואצל ר יוסף נסים בורלא."},{"i":37732,"n":"פיזנטי, יהודה יצחק מירושלים","f":"יצחק","dt":"תקכו-ז -כד חשון","dp":"ירושלים","b":"רופא מחכמי ירושלים."},{"i":37733,"n":"פיזנטי, יהודה מירושלים","f":"יצחק חיים","dt":"תרעה - יב אב","dp":"ירושלים","b":"דיין בירושלים. אחיו של ר בן ציון-מזכיר ביה\"ד."},{"i":37734,"n":"פיזנטי, יוסף מירושלים","b":"חזן ומשורר בירושלים בחברת \"ויעתר יצחק\" ע\"ש הנדיב רפאל יצחק אלטראס."},{"i":37735,"n":"פיזנטי, משה מירושלים","f":"חיים בן שם טוב","k":"בעל נר מצוה","bt":"שא-שיא","bp":"ירושלים או צפת","dt":"שלג","dp":"מקרינורו (יון)","b":"ממשפחה ממגורשי ספרד, עבר לאנקונה, כנראה למד בצפת, נדד במקומות רבים, בין היתר מלמד לילדי ר שמואל אף נעים(=קלומיטי) בקושטא, היה במצרים אצל ר שלמה אלשקר. נשבה עם עוד שני יהודים (אברהם זפרנא ויעקב סוסי) ע\"י תורכים שדרשו כופר עבורו-שלג, יהודי ארטא שלחו שליח בשם דוד הכהן עם הכופר אולם התורכים רצחו את השבויים. המעשה נזכר ב\"משפטי שמואל\" לר שמואל קלעי שישב כדיין בדין על כך. חיבר גם \"נר מצוה\", \"חקת הפסח\" על ההגדה, ועוד.ממגורשי ספרד, עבר לאנקונה, כנראה למד בצפת, נדד במקומות רבים, בין היתר מלמד לילדי ר שמואל נעים בקושטא, היה במצרים אצל ר שלמה אלשקר. נשבה עם עוד שני יהודים (אברהם זפרנא ויעקב סוסי) ע\"י תורכים שדרשו כופר עבורו-שלג, יהודי ארטה שלחו שליח בשם דוד הכהן עם הכופר אולם התורכים רצחו את השבויים. המעשה נזכר ב\"משפטי שמואל\" לר שמואל קלעי שישב כדיין בדין על כך. חיבר גם \"נר מצוה\", \"חקת הפסח\" על ההגדה, ועוד."},{"i":37736,"n":"פיזנטי, רחמים אברהם יהודה","b":"מחכמי ירושלים, חתם-תקסב על תקנה בענין הכנסות הקהלה."},{"i":37737,"n":"פיזנטי, רפאל שלמה בכור","dt":"תרכט - יב סיון","dp":"ירושלים","b":"מחכמי \"בית אל\" בירושלים."},{"i":37738,"n":"פיזנטי, שמואל מירושלים","f":"יצחק","b":"מחכמי ירושלים, חתם-תרעא על שטר בוררות עם רבני ירושלים."},{"i":37739,"n":"פיזנץ, יוסף שלום","b":"רב-שנת ת\"ס,מרבני אשכנז"},{"i":37740,"n":"פיזנץ, מאיר","f":"יוסף שלום פיזנץ","b":"מגדולי חכמי אשכנז-ת\"צ"},{"i":37741,"n":"פיזרו, אליהו","k":"בעל מכתב מאליהו","b":"חיבר מאמרים בתלמוד בדרך פילוסופיה, יצא בדרכו לארץ-שכג, הגיע לקפריסין וחיכה לשמוע אם חלפה מגפת הדבר בארץ ישראל, כתב מכתב לבני משפחתו בשם \"מכתב מאליהו\". תורגם לגרמנית בידי יוסט ונדפס - 1861."},{"i":37742,"n":"פיזרו, חיים","b":"מגדולי חכמי שאלוניקי-ש\"נ"},{"i":37743,"n":"פיט, שלום מליזנסק","b":"עבר מליזנסק לניו יורק וכיהן שם כרב-תרעח."},{"i":37744,"n":"פיטרו, אברהם","b":"מרבני מצרים"},{"i":37745,"n":"פייאנו, יעקב רפאל מבולוניה","f":"יחיאל חיים","k":"בעל חדושי דינים","b":"רב בבולוניה-שא. חיבר חדושי דינים וביאור לענין אליהו... תשובה ממנו ב\"דבר מתנה\" לר מתתיה טירני."},{"i":37746,"n":"פייאצה, ישראל חי","b":"תלמיד ר חיים יצחק מוספיה בעל \"חיים וחסד\" באישפלטארו, ונזכר בספרו."},{"i":37747,"n":"פייאצה, משה אהרן רחמים","k":"בעל אורה ושמחה","b":"רב בליוורנו. חיבר ספר לנערי בני ישראל \"אורה ושמחה\" ובו הלכות, ליקוטי שירים, קטעים מאפלטון ומהזהר, ומחדושי המחבר."},{"i":37748,"n":"פייג, דוד מסטמר","f":"מאיר מקעכניא","b":"תלמיד השב\"ס, וישיבת פאקש. חתן ר מרדכי גרייף מריסקווא. מחכמי קעכניא, סטמר. נספה בשואה."},{"i":37749,"n":"פייגין, יחזקאל מריגא","b":"בא כח האדמור מליובאביטש בריגא-תרפט. עורך \"התמים\" - וארשא תרצה, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":37750,"n":"פייגל, יו\"ט ליפמן צבי מדיאנדאש","f":"יהודה ליב","bp":"אדא","dt":"תש..","dp":"אושוויץ","b":"מצאצאי ר אליקים גץ הכהן שווערין מבייאה. תלמיד הכת\"ס. חתן ר יוסף אלעזר רוזנפלד מפריישטט. רב בדיאנדיאש (קהילת סטטוס קווא)-תרנז. נספה בשואה."},{"i":37751,"n":"פייגלסברג, חיים מקיש","f":"משה","bt":"תקע","bp":"פרוינקירכן","dt":"תרכו - ד שבט","dp":"קיש-קערעש","b":"תלמיד החת\"ס, ור משה קאניזשא-פשרהופר מפרוינקירכן. רב באירשא, קיש-קערעש, וחתנו ר משולם רובינשטין על מקומו אחריו."},{"i":37752,"n":"פייגן, יצחק מגריווא","b":"מראשי קהלת גריווא, יסד ביכ\"נ-תרכז."},{"i":37753,"n":"פייגעס, אברהם","f":"משה"},{"i":37754,"n":"פייגעס, דוד שמואל","b":"רב בזמן הגר\"א. נזכר בהלל בן שחר."},{"i":37755,"n":"פייגעס, יעקב אוריה מוילנא","f":"אברהם","k":"אוריה פייגעס","dt":"תקנה - כב שבט","dp":"וילנא","b":"חתן ר משלם זלמן ז\"ק מפוקרוי. מראשי קהילת וילנא. בנו ישראל נפטר בחייו-תקמד."},{"i":37756,"n":"פייגעס, משלם זלמן מוילנא","f":"אורי","k":"ר זלמן ר אורי'ס","dt":"תקצב-ו - ב אב","dp":"וילנא","b":"חתן ר מרדכי צבי הירש הלוי מהארחוב(=חורחאב) בן ר יצחק מהמבורג, ובזיוו\"ש חתן ר אליעזר משרשוב. גביר מחכמי וילנא. פרנס קהילת וילנא יחד עם ר ליבעלי ר בער'ש ור שמואל יהודה'ס - ונקראו \"שלשה עמודי וילנא\". חתם בהסכמה על יסוד ישיבת וולוזין-תקסד. ממשגיחי ישיבת מייליס בראשיתה יחד עם ר אבלי. נספד ע\"י ר דוד מנוברדוק בספרו \"גליא מסכת\", וכן נספד ב\"עמק הבכא\". מבניו - ר יצחק ישראל איסר מוילנא."},{"i":37757,"n":"פייזר, יהודה ליב חריף מליסא","b":"פרנס מחכמי ליסא-שנות ה-ת'-תק'. בנו - ר שמעון בעל נחלת שמעוני."},{"i":37758,"n":"פייזר, שמעון מליסא","f":"יהודה ליב מליסא","k":"בעל נחלת שמעוני","b":"חיבר \"נחלת שמעוני\", ואוד."},{"i":37759,"n":"פייטל מלאסק","b":"רב בלוסק"},{"i":37760,"n":"פייטל מסלונים","b":"דיין בסלונים-שנות ה-תק'-תר', כ-50 שנה בתקופת רבנות ר איזל חריף."},{"i":37761,"n":"פיימאהן, אברהם","f":"ישעיה מפרוסקרוב","b":"חתן ר ישראל חיים גרבטה מקולטשין."},{"i":37762,"n":"פיימאהן, ישעיה מפרוסקרוב","b":"גביר בפפרוסקרוב-פודוליה. בנו - ר אברהם."},{"i":37763,"n":"פיימר, יוסף מסלוצק הזקן","f":"מאיר משקוד","bt":"תקנו","bp":"שקוד-ליטא","dt":"תרכד - ל ניסן","dp":"סלוצק","b":"תלמיד ישיבת וולוזין והיה תלמידו המובהק של ר חיים מוולוזין. אב\"ד בסלוצק-תקפט כ-35 שנה ובנו ר מאיר על מקומו אחריו. השיב בהלכה לקרובים ורחוקים, הניח חדושים ושו\"ת - בכת\"י."},{"i":37764,"n":"פיימר, יוסף מסלוצק הנכד","f":"מאיר מסלוצק","bt":"תרלד-ה","bp":"ברזין","dt":"תרצט - א-ד כסלו","b":"רב ה\"בעלי בתים\" בסלוצק-תרסא - בחיי אביו, ניו יורק-תרפב. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":37765,"n":"פיימר, מאיר מסלוצק","f":"יוסף פיימר","b":"רב בסלוצק-תרמ על מקום אביו, קרליץ, לכוביץ. בנו ר יוסף - רב בסלוצק."},{"i":37766,"n":"פיימר-באהמר, ישראל","f":"יוסף פיימר מסלוצק","b":"עבר לברלין ופנה להשכלה."},{"i":37767,"n":"פיין, אליעזר מקאוואעש האז","b":"גביר מחכמי קאוואעש האז, קיבל ברכה מהאדמור ר שמואל פרנקל מדאראג."},{"i":37768,"n":"פיין, אליעזר משקודוויל","b":"מגיד שיעור \"דף\" לבעלי בתים למדנים בשקודוויל."},{"i":37769,"n":"פיין, חיים מראדזין","dt":"תשג","dp":"סיביר","b":"חתן ר שמואל זנויל קלפפיש מוארשא. אב\"ד ראדזין-תרפח, בזמן השואה ברח לרוסיה הוגלה לסיביר ונספה שם. גיסו (נשואים לשתי אחיות) - ר שלמה דוד כהנא מוארשא)."},{"i":37770,"n":"פיין, יהודה ליב מסלונים","f":"שבתי","bt":"תרלא","bp":"וילקומיר","dt":"תשג","b":"נכד ר אריה ליב גינצבורג מיאנעייא-פלך קובנא בעל \"אבק מוגמר\". חתן ר יעקב קנציפוביץ מסלובודוקה. תלמיד ישיבת סלובודקה, קיבוץ הפרושים באיישישוק, תלמיד ר יהודה ליב-אב\"ד מינסק, ותלמיד מובהק לר איצל'ה מפוניבז. רב בפיסאצנה-פלך מינסק-תרנה, קופישוק-פלך קובנא-תרנט, אושמיאנה(=אסמינה)-תרסו וראש ישיבה שם, סלונים-תרף וראש ישיבה שם. נסמך מאת: ר יצחק אלחנן מקובנא, ר יהודה ליב ממינסק. נספה בשואה עם בני עדתו. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח, \"קובץ דרושים\" - פיעטרקוב תרפג, \"תלפיות\" - טרנוב תרצח. בנו - ר שבתי, ונכדו - ר ראובן פיין בעל \"בין המשפתיים\". חתנו - ר בנימין זאב וולף קאהן."},{"i":37771,"n":"פיין, יוסף דב מארה\"ב","f":"יצחק","bt":"תרמד","bp":"סלוצק","b":"תלמיד ישיבת טלז, וולוזין, סלוצק. נסמך מאת: ר רפאל שפירא, ר מרדכי רוזנבלט מסלונים, ר איסר זלמן מלצר. מחכמי קאפוליא, רב ברובליא-פלך מינסק, היגר לארה\"ב-תרעו וכיהן כרב בפורטלנד. פרסם מאמרים ב\"שערי ציון\". חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":37772,"n":"פיין, יצחק","b":"תלמיד ר נחום טרוויש בעל \"שלום ירושלים\". רב בשנים תרך-תרלה לא ידוע היכן. חברם של - ר מאיר ציפר בעל \"מי השלוח\", ר מיכאל שפיצר (אין פרטים)."},{"i":37773,"n":"פיין, יצחק ממינסק","b":"גביר מחכמי מינסק. חתנו - ר איזל חריף בעל \"עמק יהושע\"."},{"i":37774,"n":"פיין, נחמיה מואוויה","dt":"תשג","b":"רבה האחרון של וועוויא(=ואוויה). נספה בשואה."},{"i":37775,"n":"פיין, ראובן","k":"בעל בין המשפתיים","b":"נכד ר יהודה ליב פיין מסלונים. ראש ישיבה \"תורה ודעת\"."},{"i":37776,"n":"פיין, שבתי מבעליצא","f":"יהודה ליב מאסמינא","dt":"תשג","b":"תלמיד ישיבת וולוזין. רב בבעליצא."},{"i":37777,"n":"פיין, שמואל מנחם הלוי מארה\"ב","k":"בעל זכרון שמואל","bp":"פלך קובנא","dt":"תרצט - ט חשון","b":"רב באפשא-פלך קובנא-תרע, טווער, דטרויט-תרפו. חיבר גם \"איתן שמואל\" סט לואיס תרצד. פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, \"היהודי\" - נ\"י תרצו, \"המגיד\" - סטמר תרפח-תרצט."},{"i":37778,"n":"פיינבוים, שאול מסאלוק","b":"רב בסאלוק-פלך קובנא-תרמב."},{"i":37779,"n":"פיינבוים, שלום יוסף מלוקטש","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":37780,"n":"פיינברג, גבריאל מסלנט","f":"אריה","k":"בעל באר רחובות","bt":"תקפה","bp":"בלבירישוק","dt":"תרסה","b":"תלמיד ר ישראל סלנטר ור אריה ליב שפירא בקובנא. רב בווילקי, סלנט על מקום ר הלל מיליקובסקי, סלובודקה, ממל-תרכ. התעוור בזקנותו והמשיך ללמד ש\"ס ופוסקים בע\"פ. על ספרו הסכימו ר יצחק אלחנן ספקטור ור שמואל סלנט. מאמר ממנו ב\"עמק הלכה\" - באטארקס תרפא."},{"i":37781,"n":"פיינברג, גרשון אליהו","f":"יהודה","k":"הו\"ל לקח טוב"},{"i":37782,"n":"פיינברג, דוד מארה\"ב","f":"נפתלי הרץ קלצקין משי","dt":"תרסז","dp":"ניו יורק","b":"מחכמי שקופישוק, היגר לארה\"ב."},{"i":37783,"n":"פיינברג, דוד מפטרבורג","bt":"1840","bp":"קובנא","dt":"1916","dp":"פטרבורג","b":"עסקן יהודי בפטרבורג. מזכיר הקהילה וממיסדי ביהכ\"נ הגדול, בית העלמין, ועוד. פעל בועד \"יק\"א\" להתישבות בארגנטינה, ומושבה אחת נקראה על שמו."},{"i":37784,"n":"פיינברג, דניאל","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":37785,"n":"פיינברג, יהושע מאווריטש","k":"בעל זכרון יהושע","dt":"תרנב - יד אב","b":"תלמיד ר אהרן מטשרנוביל. רב באווריטש."},{"i":37786,"n":"פיינברג, יצחק מלייפון","dt":"תשג","b":"רב בלייפון"},{"i":37787,"n":"פיינברג, יצחק מקובנא","f":"דוד","bt":"1822","bp":"באלבירישוק-ליטא","dt":"1912","dp":"קובנא","b":"אחיו של ר גבריאל פינברג. תלמיד אברהם מאפו. עסקן ציבור ורופא מפורסם בקובנא וסירב להמיר דתו בתמורה לקתדרה לרפואה באוני'. פרסם מאמרים בעניני רפואה. חבר עירית קובנא ופרש במחאה על שלילת זכות הבחירה מן היהודים. ייצג את יהדות ליטא בועידות בפטרבורג, ובעל תארי כבוד רבים מטעם שלטון הצאר. ממיסדי \"ספרית מאפו\" בקובנא. הוריש את ספרייתו הגדולה לבית הספרים הלאומי בירושלים."},{"i":37788,"n":"פיינברג, ישראל יצחק","b":"חתן ר אברהם אבלי מוארז'אן בעל \"אהבת איתן\". אב\"ד לייפון."},{"i":37789,"n":"פיינברג, נחמן שמואל","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":37790,"n":"פיינברג, נתן","f":"אריה","bt":"1895","bp":"קובנא","b":"מנהל מחלקה במשרד לעניני היהודים בליטא-1919. מזכיר ועד המשלחות היהודיות בפאריס. עלה לארץ והיה עו\"ד בתל אביב-1925. פרסם מאמרים רבים. תרגם ספרים בנושאי משפט בינלאומי."},{"i":37791,"n":"פיינברג, שלמה לוי מקובנא","f":"ישראל","bt":"1821","bp":"יורבורג","dt":"1893","dp":"קניגסברג","b":"נכד(-אבי אמו) ר דוד הכהן קאסוואר מקוסוב ווילנא (ר\"מ בישיבת מייליס-הארבעים). גביר תלמיד חכם. מגדולי הבנקאים ברוסיה. חתן הברונית רוזה פון הרטנשטין מוינה. התישב בקובנא, ועסק במעשי צדקה וחסד ותמיכה בלומדי תורה. קיבל תואר \"יועץ מסחרי\"-1887, עבר לקניגסברג והיה פעיל בחיים הציבוריים שם. השתתף בועידת הרבנים בפטרבורג-1881."},{"i":37792,"n":"פיינברג, שמואל דוד מניו יורק","f":"צבי","bt":"תקצד","bp":"ניעשוויז","b":"תלמיד ר ראובן מדוינסק, ר יוסף דב סולוביציק. מו\"צ בנישוויז-תרכד, היגר לארה\"ב (בעקבות צאצאיו) וכיהן כרב בקהלת יוצאי ניעשויז בניו יורק-תרסג"},{"i":37793,"n":"פיינגולד, ישראל מקראקא","f":"שרגא פיביש מקולבסוב","dt":"תש..","b":"בעל בית מדרש בקראקא. נספה בשואה."},{"i":37794,"n":"פיינזילבר, אהרן יוסף מיאלובקא","f":"אריה-פני אריה","k":"בעל עבודת אהרן","b":"רב ביאלאבקה-תר\"מ"},{"i":37795,"n":"פיינזילבר, אריה הלוי מוולקוביס","k":"בעל פני אריה","b":"תלמיד ר יעקב מאיר יאלאווקער. רב בוולקוביסק-תרי."},{"i":37796,"n":"פיינזילבר, שלמה הלוי מועקשנא","f":"אהרן יוסף-עבודת אהרן","k":"בעל נשמת חיים","bt":"תרלא","bp":"יאלובקה-פלך גרודנא","dt":"תשא - ה אלול","b":"תלמיד ישיבות ליטא. רב בטוריק-תרנו, פרזווא(=פאראזאווא)-פלך גרודנא-תרנז, וועקשנא(=ואקשנה)-פלך קובנא-תרסד וראש ישיבה, עבר למינסק וכיהן כרב בזמן מלחה\"ע ה-I והקים שם ישיבה, חזר לואקשנה, רבה האחרון של קידאן-תרפה והקים שם בית תלמוד. כיהן כיו\"ר אגודת הרבנים בליטא, ולאחר ביטול האוטונומיה היהודית הוכר מרכז אגודת הרבנים כנציג הציבור היהודי, והוא היה הנושא ונותן עם השלטון הליטאי בעיניני היהודים. בשנת תש הגיעו פליטים רבים מפולין לקידאן והקים להם ישיבה, נספה בשואה עם בני עדתו, חתנו ר אהרן גלין אמר לליטאים שעמדו סביבם לפני מותו \"הדם השפוך לא ישקוט\". חתנו ר שלמה קרביצקי מלוקניק. נסמך מאת: ר יצחק אלחנן מקובנא."},{"i":37797,"n":"פיינזינגר, ישראל יעקב מראסיין","f":"יצחק","k":"ישראל שקודער","dt":"תרז - ג ניסן","dp":"ראסיין","b":"ש\"ץ קהלת ראסיין."},{"i":37798,"n":"פיינטא, לוי מהייצפלד","dt":"תקמב - כב טבת","b":"רב בהייצפלד"},{"i":37799,"n":"פיינר, יוסף מלודז","bt":"תרכז","b":"רב באלכסנדר, מו\"צ בלודז-תרעח."},{"i":37800,"n":"פיינשטין, אליהו מפרוזין","f":"אהרן הלוי מסטראבין","k":"בעל הליכות אליהו","bt":"תרג","bp":"סטרובין","dt":"תרפט - כז תשרי","b":"חתן ר יצחק יחיאל דוידזון מקרליץ (לפי ברוורמן-אנשי שם - חתן ר יצחק יואל מקרליץ). רב בקרליץ, חסלביץ על מקום ר ליפא יו\"ט הלפרין בעל \"מלבושי יו\"ט\", דראצ'ין, פרוז'אן(=פרוזין) על מקום הגדול ממינסק ובהמלצתו. סירב לרבנות קובנא על מקום ר צבי רבינוביץ, וכן סירב לרבנות בירושלים. חתניו: ר מנחם קרקובסקי מוילנא, ר משה סולוביציק מראסיין ונכדו - ר יוסף דב מבוסטון, ר שמואל יצחק מייזל מלודז, ר דוד פיגנבוים על מקומו אחריו בפרוז'אן. נכדו-בן בתו - ר יוסף דב סולוביציק מבוסטון. אחיינו-בן אחיו - ר משה פיינשטין מניו יורק."},{"i":37801,"n":"פיינשטין, אריה ליב מבריסק","k":"בעל עיר תהלה","b":"חיבר ספר זכרון לקורות קהלת בריסק בשם \"עיר תהלה\"."},{"i":37802,"n":"פיינשטין, דוד מירושלים","b":"גבאי כוללות הספרדים בירושלים, בשליחות הכוללות באמריקה-תרן."},{"i":37803,"n":"פיינשטין, דוד מסטרבין","b":"חתן ר יצחק יחיאל דוידוביץ. רב באוזדא, סטרבין-תרע. בניו - ר משה מארה\"ב, ר מרדכי משקלוב. חתנו - ר יצחק איזיק סגל שמואל מארה\"ב."},{"i":37804,"n":"פיינשטין, חיים יעקב הכהן מצפת","f":"יהודה","k":"בעל תורת אמך","b":"מחכמי צפת-תרכ, ומרוכשי אדמות אום ג'וני - עליה הוקמה המשובה ראש פינה. בשליחות קהלת החסידים בצפת במזרח ובהודו-תרכו, תרלג, תרמג. הדפיס בכלכתה \"אמרי שבת\", \"תורת אמך\"."},{"i":37805,"n":"פיינשטין, יחיאל מיכל מארה\"ב","f":"אברהם יצחק בן דוד","bp":"אוזדא-פלך מינסק","b":"תלמיד זקנו - ר דוד מאוזדא וסטארבין, ישיבת קלצק, מיר, תלמיד וחתן ר יצחק זאב סולוביציק בבריסק, ניצל מהשואה דרך וילנא והגיע לארה\"ב, יסד ישיבה בבוסטון, ר\"מ ב\"תפארת ירושלים\" בניו יורק. פרסם מאמרים ב\"הפרדס\". פעיל בועד ההצלה."},{"i":37806,"n":"פיינשטין, מרדכי מלידא","f":"שרגא פייטל פינשטיין","bt":"תקצ","dt":"תרסג","b":"דיין בלידא-תרמ\"ג,לודז-תרמ\"ד,רב בנובי אלכסנדרובסקי-תרמ\"ו"},{"i":37807,"n":"פיינשטין, מרדכי משקלוב","f":"דוד מססטרבין","dp":"סיביר","b":"רבה האחרון של שקלוב. אחיו של ר משה מניו יורק - מסופר בשם ר חיים עוזר שאמר \"שמעתי על שני אחים בלב רוסיה הלומדים תורה כמו שהיתה נלמדת לפני מאה שנה\". עליו בספר על ר משה פיינשטין."},{"i":37808,"n":"פיינשטין, משה מוארשא","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":37809,"n":"פיינשטין, משה מניו יורק","f":"דוד מסטרבין","k":"בעל אגרות משה","bt":"תרנה","bp":"אוזדא - פלך מינסק","b":"מגדולי דורו. תלמיד ר איסר זלמן מלצר מסלוצק, ר פסח פרוסקין משקלוב. רב באוזדא-תרעז על מקום אביו שעבר לסטארבין, ליובאן-פלך מינסק-תרפא (בתקופת הקומוניסטים), הגיע לארה\"ב-תרצז, וכיהן כראש ישיבת \"תפארת ירושלים\" בניו יורק, ונשיא אגודת הרבנים. חיבר גם \"דברות משה\" ועוד. בניו ר ראובן מניו יורק ור דוד מניו יורק, חתנו ר אליהו משה שיסגאל ר\"מ ב\"תורה ודעת\" בניו יורק. פרסם מאמרים ב\"יגדיל תורה\" - בוברויסק תרפח (תחת שלטון הקומוניסטים ברוסיה), \"המסלה\" - נ\"י תרצו."},{"i":37810,"n":"פיינשטין, שמואל מוולוזין וירוש","f":"אביגדור","b":"נאמן הח\"ק בירושלים, חתם-תרכב על מכתב לר\"ש קלמר. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":37811,"n":"פיינשטין, שרגא פייטל מסלונים","b":"מו\"צ בסלונים-תרך. חתנו - ר אברהם יצחק אפשטין מיורבורג."},{"i":37812,"n":"פייס, אורי שרגא מאוברענהיים","f":"בנימין וולף","dp":"פריז","b":"חיבר דרושים יחד עם אביו. התישב בפריז."},{"i":37813,"n":"פייער, אברהם מאוסציא","f":"שלמה מאיר מאוסציא","k":"בעל זכרון אברהם","bt":"תריב","bp":"אוסציא","dt":"תרצו - יח אדר","dp":"ניו יורק","b":"למד בישיבת פרשבורג. נדד ברחבי אירופה והמזרח התיכון. התישב בהוסיאטין. פרסם בכתבי עת שונים. עבר להתישבות יק\"א בקנדה והתפרנס מעבודה כאיכר. עבר לניו יורק ושימש כמגיד שיעור. חיבר \"זכרון אברהם\" ניו יורק תרפד, \"נשמת כל חי\" וינה תרפז."},{"i":37814,"n":"פייער, אברהם מלמברג","f":"נתן מזולקוא","k":"בעל משכיות כסף","bt":"תרי","bp":"זולקווא","dt":"תרע","b":"מחכמי מונקטש-תרנא, רב ודרשן בלמברג-תרסד. חיבר \"משכיות כסף\" למברג תרסה, ועוד."},{"i":37815,"n":"פייער, יהודה צבי מרדיכוב","f":"ישראל האדמור מלמברג","bt":"תרס","bp":"דרוהוביטש","dt":"תשג","b":"חתן ר יקותיאל אפרתי מחוליוב. רב בחוליוב ורדיכוב. נספה בשואה."},{"i":37816,"n":"פייף, אליהו מארה\"ב","bt":"1882","bp":"שאקי","dt":"1959","dp":"ארה\"ב","b":"היגר לארה\"ב-1903 ועסק בתעשייה. חבר הנהלת המגבית היהודית המאוחדת. פעיל בארגוני צדקה ותרבות שונים בארה\"ב."},{"i":37817,"n":"פייפר, יצחק מהונגריה","b":"תלמיד ישיבת השב\"ס בפרשבורג, מחברי אגודת \"אהבת ציון\" ונואם באגודה - בהיותו בישיבת פרשבורג. מזכיר ההסתדרות הציונית בהונגריה."},{"i":37818,"n":"פייפר, ישראל יהודה מניימרקט","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":37819,"n":"פייפר, פנחס יהודה זליג מקאווגר","k":"בעל אמרי פי","bt":"תקסו","bp":"יעמרינג","dt":"תרכט - ב תשרי","dp":"קאוועגרעש","b":"תלמיד החת\"ס. חתן ר יחזקי' כץ מבעלעד. רב בקאוועגרעש(=קובאגו-אורש)-תקצב. מתורתו בקונטרס 'אמרי פי' שנדפס בתוך ספר חותנו 'מגדנות יחזקיהו' - בני ברק תשסב. חתניו - ר יוסף שמואל הרשלר מסאבאדי, ר אברהם אליעזר אקשטין מבודפשט."},{"i":37820,"n":"פייפרט, ישראל מרדכי מדרום אפרי","f":"צבי","k":"בעל ילקוט הפנינים","bt":"1851","bp":"וילקומיר","b":"בן למשפחה המיוחסת להגר\"א. לאחר שנתייתם גדל אצל ר וועלוועלע מירעס ור בנימין. נטה להשכלה בהשפעת משה לילינבלום ולתנועת חיבת ציון. היגר לאנגליה, דרום אפריקה ועסק במסחר טבק. מראשוני העסקנים הציונים בדרום אפריקה. חיבר שירים עבריים וספר באידיש, ובהם \"שאלת יחס המולדות\" קייפטאון תרעו."},{"i":37821,"n":"פייקין, אברהם יצחק איזיק","bt":"תרמ","dt":"תרצח","dp":"ארץ ישראל","b":"תלמיד ר שמריה נח מבברויסק, היה רב בסלובודקה ובמינסק, עלה בשנת תרצד."},{"i":37822,"n":"פיירו, יעקב מאדרינופול","b":"מחכמי אדרינופול בדור שאחר הגירוש, נזכר בשו\"ת הרא\"ם."},{"i":37823,"n":"פיכמן, דון יוסף","dt":"קלט","b":"מחכמי ספרד, יועץ המלך, בדורו של הר\"נ, נהרג"},{"i":37824,"n":"פיכמן, יעקב"},{"i":37825,"n":"פיכנפלד, משה","b":"רב בסנטימישל-תק\"צ"},{"i":37826,"n":"פילבוגן בי\"ח, יעקב הירש","f":"משה אריה פיילבוגן","k":"בעל חשרת מים","b":"נכד(-אבי אמו) ר צבי הירש בי\"ח מניקלשבורג. דיין בניקלשבורג-תקס אצל ר מרדכי בנט. הו\"ל \"שמלה חדשה\" - וינה תקנו."},{"i":37827,"n":"פילבוגן בי\"ח, משה אריה","b":"חתן ר צבי הירש בי\"ח מניקלשבורג. דיין בניקלסבורג-תקכ. בנו - ר יעקבער (יעקב הירש) מניקלשבורג."},{"i":37828,"n":"פילבוגן, ? מדרזניץ","f":"אפרים מהאלמוי","b":"רב בדרזניץ. אין פרטים נוספים."},{"i":37829,"n":"פילבסקי, בנימין דובער מוילנא","f":"חיים בינש מרזאנקי","bt":"תרלב","b":"תלמיד ישיבת איישישוק. מו\"צ בוילנא-שכונת פיאסקס. נסמך מאת: ר שלמה הכהן מוילנא, ר אליעזר שמחה רבינוביץ מקאלואריא, ר יעקב דוד מסלוצק-רידב\"ז, ר משה בצלאל מסובאלק."},{"i":37830,"n":"פילבסקי, חיים בונש","b":"רב בראזנסקי-תר\"ל"},{"i":37831,"n":"פילבר, יעקב יצחק ממדיניץ","b":"מחכמי מדיניץ. תלמיד ר יצחק חיות בעל \"שדה יצחק\" - שהשיב לו בספרו."},{"i":37832,"n":"פילו, שם טוב משלוניקי וירושלים","dp":"מצרים","b":"רב בשלוניקי או אזמיר, עלה לירושלים ולמד עם ר דוד קונפורטי, ראש ישיבה בצפת, חתן ר יהודה ביגה משלוניקי בעל \"מלכי יהודה\". בשנת תכב בשליחות, בשנת תיח חתם עם חכמי אזמיר על \"הליכות אלי\" לר שלמה אלגזי."},{"i":37833,"n":"פילוט, משה אלימלך","f":"אליקים גץ","b":"רב בסטריא"},{"i":37834,"n":"פילוס, מנחם מליפאנטו","b":"דיין בליפאנטו-שנות ה-ת' אצל ר דניאל יצחק."},{"i":37835,"n":"פילוסוף, אברהם מירושלים","f":"יעקב","bt":"תרכד","bp":"לאריסה","b":"עלה לירושלים-תרכו, מקובל, אב\"ד, מחברי הרבנות הראשית-תרפא."},{"i":37836,"n":"פילוסוף, אברהם מלאריסה","b":"מראשי קהלת לאריסה-תפב. רב לצדו של ר אליהו חנדלי-תקד יחד עם ר שמואל בן יצחק משען."},{"i":37837,"n":"פילוסוף, אליהו מקושטא - ב","b":"רב בקושטא-שמו."},{"i":37838,"n":"פילוסוף, אליהו מקנדיא וקושטא","b":"רב ופייטן בקנדיא(=כרתים). פיוטים ממנו במחזור קנדיא, רב ומסדר הגיטין בקושטא-רנ. חברו של ר אליהו ן חיים. אולי הוא המחבר ספר ההיגיון."},{"i":37839,"n":"פילוסוף, בנימין","b":"מחכמי טורקיה, רב בארטא בזמן מהרשד\"ם"},{"i":37840,"n":"פילוסוף, בנימין משלוניקי","dt":"שלא - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37841,"n":"פילוסוף, יוסף מארטא","b":"רב בארטא-שנות ה-ש'."},{"i":37842,"n":"פילוסוף, יוסף משלוניקי","b":"תלמיד וחתן ר ברוך אנגל. רב בשלוניקי בזמן שבתי צבי. נתן לש\"ץ את בתו-תלד - לאחר התאסלמותו של ש\"ץ. תלמיד בישיבת נתן העזתי בשלוניקי. לדעת רוזנס התאסלם לבסוף."},{"i":37843,"n":"פילוסוף, משה מבוכרה","f":"חיים","bt":"תרכו","bp":"סמרקנד-בוכרה","dt":"תרסא - בערך","dp":"ירושלים","b":"תלמיד אביו חורגו ר בנימין פוזיילוף (מולא פוזיל) רבה של סמרקנד. קיבל את שמו \"פילוסוף\" בגלל למדנותו. רב בסמרקנד מטעם השלטונות. עלה לירושלים-תרסא. בנו ר משה - ר בטשקנט."},{"i":37844,"n":"פילוסוף, שבתי משלוניקי","dt":"רץ - כג תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37845,"n":"פילוסוף-קירידו, יעקב צבי ידידי","f":"יוסף משלוניקי","dt":"תמג","dp":"אלכסנדריה","b":"גיסו-אחי אשתו של ש\"ץ. לאחר פטירת ש\"ץ הכריז על עצמו משיח בן יוסף. הוחרם ע\"י רבני שלוניקי, התאסלם-תמג עם מאות משפחות מחסידיו והיו ראשוני כת ה\"דונמה\". נסע למכה ונפטר בדרכו באלכסנדריה. (יש אומרים שהוא עצמו לא התאסלם - משום שהוזכר בברכת המתים אצל רבני שלוניקי)."},{"i":37846,"n":"פילוער, יצחק","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":37847,"n":"פילזארו, אברהם ישראל מאמשטרדם","k":"בעל שבט יאודה","b":"מחכמי אמשטרדם-שנות ה-ת'. חיבר \"שבט יאודה\" בכת\"י (אצל די רוסי)."},{"i":37848,"n":"פילטינוב, אברהם יהודה","f":"חיים אליהו","bt":"תרכז","b":"רב בטרסקוב-פלך קובנא-תרנה, דנטובה-פלך סובאלק, וישטיניץ(=וישטינעץ)-פלך סובאלק."},{"i":37849,"n":"פילטינוב, דוד","dt":"תשג","b":"רב בווישטניץ,וילקוביסק"},{"i":37850,"n":"פיליפ (פילוב), שמואל מלבוב","k":"עורך בית הבחירה"},{"i":37851,"n":"פיליפ (פיליב), צבי הירש","f":"אהרן","k":"בעל צמח ה לצבי","b":"חתן ר יצחק באראן. חיבר \"צמח ה לצבי\" פשמישל תרסח, ועוד."},{"i":37852,"n":"פיליפ, אברהם הכהן מבוטשאם","b":"מחכמי בוטשאם. חתנו - ר משה רייך ממעדיאש."},{"i":37853,"n":"פיליפ, אשר משארוש-פוטוק","b":"רב בשארוש-פוטוק-מחוז זמפלן-תרץ. תרגם את כתבי הרש\"ר הירש להונגרית."},{"i":37854,"n":"פיליפ, בנציון הכהן מסטמר","f":"ברוך צבי מאילאנדא","dt":"תשד - ו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר חיים צבי שפיץ מנאדי-טארנא ועבר לשם, מחכמי גרוסורדין, בערגסאס, סטמר-תרף."},{"i":37855,"n":"פיליפ, דוד אריה ליב מנדבורנה","f":"צבי הירש מנדבורנא","k":"אדמור מנדבורנא","bt":"תקלה","dt":"תרט - יז שבט","b":"תלמיד ר מנחם מנדל מקוסוב. אדמור בנדבורנה על מקום אביו. חתן ר מאיר בנו של ר לוי יצחק מברדיטשוב. נכדו ר צבי חיים מגיד מטעטש."},{"i":37856,"n":"פיליפ, חיים צבי מלבוב","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":37857,"n":"פיליפ, יהושע מאסאד","b":"רב באסאד-תק\"ה"},{"i":37858,"n":"פיליפ, יעקב מאסאד","b":"רב באסאד-תקל\"ו"},{"i":37859,"n":"פיליפ, משה יחיאל מיכל","f":"צבי הירש מנדבורנא"},{"i":37860,"n":"פיליפ, נחמן מגרוסורדין","f":"יעקב אליעזר","dt":"תש - ב אייר","dp":"גרוסורדין","b":"בנו - אברהם."},{"i":37861,"n":"פיליפ, צבי הירש מנדבורנה","f":"שלום זליג-דברי שלום","k":"אדמור מנדבורנא","bt":"תצז","dt":"תקסא-ב - כ סיון","b":"נכד ר שאול ואהל. נפגש בילדותו עם הבעשט שברכו. תלמיד המגיד ממזריטש, וגדול תלמידי המגיד מזלוטשוב. חתן ר אלימלך הורושבסקי -המגיד מישרים מדרוהוביטש. מגיד מישרים בדולינא-תקלז, רב ואדמור בנדבורנה-תקמו ותלמידו ר מנחם מנדל מקוסוב על מקומו אחריו, חתנו ר יצחק מרדיויל בן המגיד מזלוטשוב על מקומו כאדמור בנדבורנה אחריו. חיבר \"אלפא ביתא\" תקן (בעילום שמו), \"מילי דאבות\" ברדיטשוב תקעח, ועוד. בניו ר דוד אריה ליב, ר משה יחיאל מיכל. ?? לא באוצר - מופיע תחת 2 שמות שונים ??","bk":[["אלפא ביתא","חסידות"]]},{"i":37862,"n":"פיליפובסקי, צבי הירש מלונדון","k":"בעל מועד המועדים","bt":"1816","bp":"וירבאלן","dt":"1872","dp":"לונדון","b":"היגר ללונדון ועסק בהוראה עברית. חיבר ספר על לוח השנה העברי, הקראי, הנוצרי והמוסלמי. עורך שנתן \"האסיף\" - לונדון תרז, הו\"ל \"מבחר הפנינים\", פרסם גם ספרים בבעיות מתמטיות."},{"i":37863,"n":"פיליפובר-ווסרצוגחיים מוישטיניץ","dt":"תרלה - ח אדר","b":"רב בווישטניץ(=וישטיניץ)."},{"i":37864,"n":"פיליפופובסקי, מנחם מנדל מוילקו","b":"רב בוילקוביסק. פרסם מאמרים ב\"חכמי ליטא\" - קאלואריא תרמה."},{"i":37865,"n":"פיליפס, אלעזר מארה\"ב","k":"בעל ומרפא בכנפיה","b":"רב בארה\"ב-תרסו. חיבר גם \"מרפא ארוכה\"."},{"i":37866,"n":"פיליפס, הרולד מאיר","f":"יעקב","bt":"1874","bp":"קאלואריה","b":"היגר בילדותו לארה\"ב. משפטן ומצטיין בשחמט והשתתף בתחרויות בינלאומיות. נשיא מועדון השחמט של מנהטן. ממנהלי ישיבה אוניברסיטה בניו יורק."},{"i":37867,"n":"פיליפס, יעקב מאנגליה","f":"יצחק מאנגליה","bt":"תרכח","b":"רב בסבונז,סונדרלנד,פורט-אליזבט-תר\"ע"},{"i":37868,"n":"פיליפס, יצחק מאנגליה","f":"אליעזר","bt":"תרד","bp":"לונדון","b":"תלמיד ביהמ\"ד לרבנים בלונדון. רב בפורטסמות-אנגליה-תרל. בנו - ר יעקב מפורט אליזבת."},{"i":37869,"n":"פיליפס, ליב לואיס מדרום אפריקה","f":"יצחק מאנגליה","bt":"תרמא","b":"גדול בתורה ומדע,רב בפרטוריה-דרום-אפריקה-תרסט."},{"i":37870,"n":"פיליפס, נתנאל","f":"יעקב","bt":"1894","bp":"קאלואריה","b":"היגר בילדותו לארה\"ב. משפטן. ממיסדי הליגה הלאומית לאזרחות אמריקאית. חבר הועד האמריקאי ליסוד פקולטה למשפטים באוני' העברית בירושלים."},{"i":37871,"n":"פיליפסטול, דב בר מלעסלא","k":"בעל נחלי דבש","b":"אב\"ד פין, בירנבאום. חברו של ר עקיבא איגר שהסכים על ספרו."},{"i":37872,"n":"פיליץ, דניאל","b":"רב בשטול-ויסבורג,סגדין"},{"i":37873,"n":"פיליץ, דניאל מסאגאד","b":"רב בקהילה הניאולוגית בסאגאד, ומנהל ביה\"ס היהודי. פרסם חוברת בשם בדוי - \"תיאודור ברגר\" - ובה יצא כנגד התלמוד ובעד תיקונים בדת - ועל כך פרצה מחלוקת והוחדח מתפקידו, להגנתו יצאו הרב שטינהרט מאראד, ור ליב שוואב מבודפשט שהזהירו את הרבנים החרדים מקנאות מופרזת."},{"i":37874,"n":"פיליץ, חננאל","dt":"תקסז","b":"רב בווספרם"},{"i":37875,"n":"פיליץ, יואב","f":"חננאל פיליץ","dt":"תריז - כד אייר","b":"מו\"צ בווספרם"},{"i":37876,"n":"פילכנפלד, משה מראגזאן","dt":"תרלב - ז אדר","b":"רב בראגאזאן. פרסם מאמרים ב\"תבונה\" - ממל-קניגסברג תרכא."},{"i":37877,"n":"פילץ, משה דוד מרישא","b":"רב ברישא-[תר]."},{"i":37878,"n":"פילצר, אהרן שמחה מגומבין","bt":"תקעג","dt":"תרמח","b":"תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, והשפת אמת. רב בדומביה, פארינטשוב, גומבין."},{"i":37879,"n":"פילצר, חיים","b":"חתנו - ר יעקב וינר."},{"i":37880,"n":"פילצר, שלמה מאיר מלמברג","b":"מחכמי למברג, ליסקא - תשובה אליו בטוט\"ד."},{"i":37881,"n":"פילר, אהרן מקראקא","f":"אליהו","bt":"תרלט","bp":"טענצין","dt":"תשא","b":"חסיד בלז. חתן ר נתן קירשבוים. מחכמי אזיארנא, עבר לקראקא. נספה בשואה."},{"i":37882,"n":"פילר, אליהו מטענצין","f":"אלעזר ליפא","bt":"תרך","bp":"קראקא","dt":"תרצא","b":"מחכמי טענצין ומקורב למאור ושמש ולצדיקי דורו. מוהל."},{"i":37883,"n":"פילר, אלעזר מברוקלין","f":"אהרן מקראקא","bp":"סטנוב","b":"ניצל מהשואה, הקים את אגודת ישראל בצ'כיה לאחר השחרור, עבר לצרפת-תשט. חתן ר מרדכי צבי מייזלס מאושפיצין. עבר לארה\"ב-תשיא ומחסידי בובוב שם."},{"i":37884,"n":"פילר, שמואל","dt":"תקפז - א אדר","b":"תלמיד החוזה מלובלין."},{"i":37885,"n":"פילשטין, שלמה דב בריש מאודסה","b":"דיין באודסה, אצל רר יחיאל צבי הלפרין. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":37886,"n":"פימיינטא, אברהם ממצרים","b":"מחכמי מצרים-שנות ה-ת', חברו של ר אברהם אסכנדרי."},{"i":37887,"n":"פימיינטא, משה מטנג'יר","b":"מחכמי טנג'יר-שנות ה-תק'-תר'."},{"i":37888,"n":"פימינטיל, אברהם הכהן מאמשטרדם","k":"בעל מנחת כהן","bt":"1627","dt":"תנז","b":"ראש ישיבת \"כתר תורה\" באמשטרדם, אב\"ד בהמבורג, חיבר \"מנחת כהן\"","bk":[["מנחת כהן [הקדמה]","מערכות"],["מנחת כהן [מבוא השמש]","מערכות"],["מנחת כהן [ספר התערובות]","מערכות"],["מנחת כהן [משמרת השבת]","מערכות"],["מנחת כהן -",""]]},{"i":37889,"n":"פין שמואל יוסף בן יצחק איזיק","bt":"1818","dt":"ה'תרנ 1890","bk":[["כנסת ישראל",""],["קריה נאמנה",""]]},{"i":37890,"n":"פין, בן ציון מטריסק","dt":"תשג","b":"רב בטריסק"},{"i":37891,"n":"פין, בנימין מוילנא","f":"שמואל יוסף","bt":"תרז","dt":"תרנט - כז אב","b":"רופא. תרם את ספרייתו הגדולה של אביו לבית עקד ספרים הכללי בוילנא. נפטר ללא ילדים."},{"i":37892,"n":"פין, יהודה","bt":"1866","bp":"שאקי","b":"אביו - דודנו של רש\"י פין. היגר לאנגליה והיה ממיסדי אגודת פועלי המחט. עבר לארה\"ב-1886 ויסד שם את אגודת החייטים שממנה צמח \"יונייטד גרמנט וורקרס\" - אחד האיגודים המקצועיים הגדולים בעולם. חזר לאנגליה והו\"ל עתונים סוציאליסטים. פרסם מאמרים בעניני שיתוף פעולה בין בעלי הרכוש ובין הפועלים. התנגד לקומוניזם."},{"i":37893,"n":"פין, שמואל יוסף מוילנא","f":"יצחק איזיק","k":"רש\"י פין - בעל האוצר","bt":"1819","bp":"גרודנא","dt":"תרנא - יא טבת","dp":"וילנא","b":"חתן ר בנימין נתנזון מוילנא. תלמיד ר אברהם קצנלנבוגן ובימ\"ד הגביר ר שמחה בארד (-אביו של ר אברהם קצנלנבוגן) שהיה בית ועד למשכילי וילנא, ובימ\"ד יסו\"ד - אצל ר חיים גיטקע טויבעס, ובבימ\"ד הגר\"א - וחיבר שם ביאור על ביאור הגר\"א להלכות נט\"י ועוד. חתן ר ברל רעללעס. מראשי משכילי יהדות ליטא בזמנו. מורה בביה\"ס של הרש קלצקי וניסן רוזנטל, מורה בביהמ\"ד לרבנים בוילנא. גבאי צ\"ג בוילנא-תרלח. הו\"ל \"פרחי צפון\" בטאונה הראשון של תנועת ההשכלה בליטא. הו\"ל \"הכרמל\". חיבר ספרים בהסטוריה ובלשנות. תרגם ספרים מגרמנית. חיבר גם \"תולדות היהודים בוילנא\", \"תלמוד לשון רוסיה\"."},{"i":37894,"n":"פינא די, דוד צרפתי מאמשטרדם","f":"אהרן","b":"רופא ודרשן באמשטרדם, מפקח חברת \"אבי יתומים\" על מקום אביו. חיבר שירים. דרש בחנוכת בית הכנסת הגדול באמשטרדם, הספיד את ר יצחק פינטו-תנג."},{"i":37895,"n":"פינגרהוט, אברהם משה הלוי מאלגי","f":"יצחק מאיר","k":"בעל שו\"ת","bt":"תרסט","bp":"טורקן-פולין","dt":"תשכב - א אייר","b":"הגיע מפולין וכיהן כרב בפורטוגל, אלגיר-תרצו, דיין בפאריס-תשיז. שאלות ממנו לחכמי מרוקו. חיבר שו\"ת שהשיב הרב א\"מ פינגרהוט - ירושלים תשכד. נזכר ב\"צאן יוסף\" לר\"י בן נאים, וב\"פרחי כהונה\"."},{"i":37896,"n":"פינדלינג, משה מחיפה","k":"בעל תחוקת עבודה","bt":"תרסז","dt":"תשלד - יא חשון","b":"רב בחיפה"},{"i":37897,"n":"פינדרוס, אברהם מראדוויל","f":"חיים יהודה","bt":"תרלז","b":"מצאצאי בעל \"סדר הדורות\". תלמיד ישיבות סלוצק, בוברויסק, כולל קובנא, ותלמיד ר ברוך דב ליבוביץ. רב בראדוויל-ווהלין-תרסה. נסמך מאת: ר חיים סולוביציק, ר צבי הירש רבינוביץ מקובנא, , ר משה דנישבסקי מסלובודקא, הרידב\"ז, ר משה שמואל שפירא מבוברויסק, ר ברוך דב ליבוביץ."},{"i":37898,"n":"פינחס בן פילטא","bt":"1620","dt":"ה'תכג 1663","bk":[["ברית שלום",""]]},{"i":37899,"n":"פינחס זליג בן משה","bt":"1700","dt":"ה'תקל 1770","bk":[["עטרת פז",""]]},{"i":37900,"n":"פינחסיק, אברהם מקראסנאלוק","f":"אליקום מרדכי","bt":"תריט","b":"רב בקראסנאלוק-פלך מינסק-תרן."},{"i":37901,"n":"פינטו, אברהם","bp":"ספאלאטו?","b":"אחיו - ר דוד מבלגרד וסרייבו."},{"i":37902,"n":"פינטו, אברהם","b":"רב שנות ה-ת'. התכתב עם ר משה ריבקש בעל באר הגולה (הכרמל שנה ז גו' 2)."},{"i":37903,"n":"פינטו, אברהם מירושלים","dt":"תרעב - ח סיון","b":"דיין בירושלים"},{"i":37904,"n":"פינטו, אברהם מירושלים ובוכרה","f":"ברוך","dt":"תרפז - כג חשון","dp":"ירושלים","b":"תלמיד ר יצחק אשכנזי, בשליחות קהלת ירושלים, ישב על כסא הרבנות בבוכרה. חזר לירושלים והיה מחכמי \"פורת יוסף\", דיין אצל ר אברהם פילוסוף. פרסם מאמרים ב\"המאסף\"."},{"i":37905,"n":"פינטו, אברהם ממראקש","f":"יעקב","k":"בעל מור דרור","dt":"תקפו - אחרי","b":"מו\"צ במראקש-מרוקו, עם הדיינים ר יצחק חרוש, ר משה ן עטר, ר שלמה אסבאג. חתם על הסכמה ל\"תהלה לדוד\" לר דוד חסין. חיבר חדושים על מסכת כתובות. (יש רושמים תאריך פטירתו - תקסד, והוא טעות כי חתם בשנת תקפו)."},{"i":37906,"n":"פינטו, אברהם ממרוקו","b":"מגדולי רבני מרוקו-תק\"י"},{"i":37907,"n":"פינטו, אברהם משלוניקי","dt":"שעט - יז אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37908,"n":"פינטו, אברהם משלוניקי וצפת","b":"רב בשלוניקי, עלה לצפת-שלה, ונזכר בשו\"ת המבי\"ט. בנו - ר משה ממצרים."},{"i":37909,"n":"פינטו, אפרים משלוניקי","b":"מחכמי שלוניקי, ראש ישיבה בצפת-שפג, בשליחות בטורקיה."},{"i":37910,"n":"פינטו, בן ציון מסרייבו","b":"רב בשאריי-בושנה(=סרייבו), עלה לארץ."},{"i":37911,"n":"פינטו, בנימין","f":"משה","b":"דיין"},{"i":37912,"n":"פינטו, בנימין מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":37913,"n":"פינטו, ברוך מירושלים","bt":"תרא","dt":"תרנג - תמוז","dp":"ירושלים","b":"דיין בירושלים, חבר בית דינו של ר אהרן עזריאל, בתריט יצא בשליחות למרוקו עם ר יוסף נסים בורלא. הספידו ר יעקב שאול אלישר"},{"i":37914,"n":"פינטו, דוד מאמשטרדם","b":"גביר באמשטרדם. הקדיש ישיבה \"מגן דוד\" בירושלים. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת."},{"i":37915,"n":"פינטו, דוד מבלגרד","b":"רב בבלגרד-תקמח. (אולי הוא שהיה גם רב בסרייבו)."},{"i":37916,"n":"פינטו, דוד מסרייבו","bp":"ספאלאטו(=ספליט)","dt":"תקעד","b":"תלמיד ר יצחק בן שם טוב צבי, ר חיים דוד פארדו בעל שושנים לדוד, ובנו ר יצחק פארדו. רב בבלגרד, סרייבו וראש ישיבה שם. אחיו - ר אברהם."},{"i":37917,"n":"פינטו, דניאל מחלב","f":"יאשיהו - ריא\"ף","k":"בעל לחם חמודות","dt":"תמא - ז-יז אב","b":"רב בארם צובא, מתלמידי ש\"ץ (ואולי הוא חכם אחר?). בנו - ר שמואל מאר\"ץ."},{"i":37918,"n":"פינטו, חיים אפרים מצפת","dt":"תכד - לפני","b":"מחכמי צפת בשנת שצז, חתם על מכתב לקהילת מנטובה, והוא בין החותמים על הסכמה לספר \"חוט המשולש\"."},{"i":37919,"n":"פינטו, חיים ממרוקו - הגדול","f":"שלמה","bt":"תקג","bp":"אגאדיר-מרוקו","dt":"תרה - כז אלול","dp":"מוגאדור","b":"לאחר שנתייתם גדל אצל קרוביו במוגאדור. תלמיד ר יעקב ביבאס ממוגאדור. רב במוגאדור על מקום רבו, חתם על פס\"ד-תקצה עם ר יוסף אלמליח, נזכר ב\"שופריה דיעקב\", חתם עם ר דוד חזאן-תקפז. נתפרסם כאיש מופת."},{"i":37920,"n":"פינטו, חיים ממרוקו - הקטן","f":"יהודה הדאן","bt":"תרכה","bp":"מוגאדור","dt":"תרצח - טז חשון","dp":"קזבלנקה","b":"נכד ר חיים הגדול. רב במוגאדור, קזבלנקה."},{"i":37921,"n":"פינטו, חיים מצפת","f":"יוסף","b":"מקובל, רב בצויירא, צפת תקפג."},{"i":37922,"n":"פינטו, חיים מקושטא","b":"דיין בקושטא-תקעה, ממונה על איסור והיתר עם ר יוסף מימון ור יוסף הלוי."},{"i":37923,"n":"פינטו, יאשיהו מדמשק וצפת","f":"יוסף","k":"בעל כסף נבחר","bt":"שכה","bp":"דמשק","dt":"תח - אדר (שץ?)","dp":"דמשק","b":"תלמיד ר יעקב אבולעפיה ונסמך על ידו - ונקרא \"הרב המוסמך\", רב בדמשק-שפ על מקום ר חיים ויטאל שהיה מחותנו - חתנו היה ר שמואל ויטאל. בשנת שפה עלה לצפת וכיהן כרב, לאחר פטירת בנו יוסף חזר לדמשק. חיבר ספר \"כסף נבחר\" דמשק שסה, \"כסף מזוקק\" ונציה שפח, ועוד. בנו ר דניאל היה רב בארם צובא."},{"i":37924,"n":"פינטו, יהודה","f":"חיים","k":"ר' הדאן","b":"מחכמי אגאדיר ומוגאדור"},{"i":37925,"n":"פינטו, יהודה","b":"שד\"ר חברון בתורכיה-תר\"ד"},{"i":37926,"n":"פינטו, יוסף מאישקופיה","b":"דיין באישקופיה-שנות ה-ת'."},{"i":37927,"n":"פינטו, יוסף ממראקש","f":"יעקב","dt":"כפר וארזאזאת","b":"מלוב\"ן מחכמי מראקש, חתם על פס\"ד-תקמח."},{"i":37928,"n":"פינטו, יעקב ממראקש","f":"ראובן","k":"בעל מקדש מלך","b":"תלמיד ר אברהם אזולאי. מו\"ץ במראקש. חיבר עם ר שלם בוזגלו ואחרים \"מקדש מלך\" על הזהר."},{"i":37929,"n":"פינטו, יעקב ממראקש","f":"אברהם בן יעקב","b":"מו\"ץ במראקש-תקפד."},{"i":37930,"n":"פינטו, יעקב ממראקש - הנכד","f":"מימון","b":"נינו של ר יעקב פינטו בעל \"מקדש מלך\". מו\"ץ במראקש."},{"i":37931,"n":"פינטו, יצחק מאמשטרדם","bt":"תעה","bp":"בורדו","dt":"תקמז","dp":"אמשטרדם","b":"בן למשפחה פורטוגזית בבורדו-צרפת, עבר לאמשטרדם, האג. גביר מראשי הקהלה הספרדית. פרסם ספרים בצרפתית, והתוכח עם וולטייר שכתב כנגד היהודים - ובספרו הבדיל ר יצחק בין היהודים הספרדים שאותם הצדיק לבין האשכנזים, פעל לגירוש היהודים האשכנזים מבורדו."},{"i":37932,"n":"פינטו, יצחק ממראקש-מרוקו","f":"יעקב - מקדש מלך","dp":"תונס","b":"מחכמי מראקש. חתם בהסכמה-תקסד עם רבני פאס. נאלץ לברוח ממראקש לאחר שהרג נוצרי שלקח ישראלית, וברח לפאס ומשם לתונס."},{"i":37933,"n":"פינטו, יצחק מפאס","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":37934,"n":"פינטו, ישועה (ישעיה) מחברון","b":"רב בחברון. חתם על כתב שליחות ר יוסף מולכו-תקפב, ושל ר יוסף דוד עייאש-תקץ."},{"i":37935,"n":"פינטו, ישי מסופיה","b":"רב קהילת הספרדים בסופיה עם ר חיים ן משה."},{"i":37936,"n":"פינטו, ישעיה מירושלים","dt":"תק - בערך","dp":"ירושלים","b":"מחכמי ירושלים. נספד ב\"שמע יעקב\"-תק."},{"i":37937,"n":"פינטו, כלב מדמשק","dt":"של","dp":"דמשק","b":"מחכמי דמשק-שכה, עלה לצפת בזמן ר חיים ויטאל. נזכר ב\"אבקת רוכל\"."},{"i":37938,"n":"פינטו, מימון ממראקש","f":"יצחק","b":"נכד ר יעקב פינטו בעל \"מקדש מלך\". מחכמי מראקש-תקצב, וחתם עם ר דוד צבאח ב\"הלכתא למשיחא\"."},{"i":37939,"n":"פינטו, מסעוד ממראקש","b":"מחכמי מראקש - חתם עם חכמי עירו-תרמא."},{"i":37940,"n":"פינטו, מסעוד מצפת","b":"מצאצאי ר יאשיהו פינטו, נכד(-בן בתו) ר מסעוד בונאן. חתן ר חיים דוד אבולעפיה. בשליחות צפת-תקפו."},{"i":37941,"n":"פינטו, משה אהרן","f":"חיים הקטן","bp":"מוגאדור","dt":"תשמה - ה אלול","dp":"אשדוד","b":"מקובל, מצדיקי מרוקו, הסתגר כ-40 שנה בציווי אביו ועסק בתענית בתפילות ובלימוד, עבר לקזבלנקה, עלה לארץ והתישב באשדוד והתפרסם בכח ברכותיו ותפילותיו."},{"i":37942,"n":"פינטו, משה מאלכסנדריה","b":"מחכמי אלכסנדריה. חתם על קבלת עדות-שסד עם ר יעקב קשטרו."},{"i":37943,"n":"פינטו, משה מהאג","b":"גביר בהאג-תקלז, בזמן ביקור החיד\"א."},{"i":37944,"n":"פינטו, משה ממראקש","f":"אברהם","b":"מו\"ץ במראקש, חתם-תרט על פס\"ד עם ר דוד צבאח, ר אלעזר חזאן, ר רפאל מסעוד ן מוחא, ועוד."},{"i":37945,"n":"פינטו, משה ממראקש","f":"יעקב - מקדש מלך","b":"מחכמי מראקש - שנות ה-ת'-תק'."},{"i":37946,"n":"פינטו, משה ממראקש וטבריה","f":"יצחק","b":"מצאצאי ר יעקב פינטו בעל \"מקדש מלך\". עלה לארץ, מחכמי טבריה, בשליחות בצפון אפריקה-תקפח."},{"i":37947,"n":"פינטו, נסים ממרוקו","dt":"תרח - כח חשון","dp":"ירושלים","b":"רב במרוקו, עלה לירושלים."},{"i":37948,"n":"פינטו, ראובן ממראקש-מרוקו","b":"רב במראקש - שנות הת'. אביו של ר יעקב פינטו."},{"i":37949,"n":"פינטו, שלמה מאנקונא","dt":"שיו - ח אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":37950,"n":"פינטו, שמואל מאמשטרדם","b":"מחכמי אמשטרדם-תרך, תלמיד ר יצחק אבוהב, מגיה התנ\"ך במהדורת עטיאש. מלמד בחברת \"תמימי דרך\" עם המיסד ר יוסף פרנקו סראנו, ובישיבת \"תורה אור\"."},{"i":37951,"n":"פינטו, שמואל מחלב","f":"דניאל בן יאשיהו","dt":"תעה - ו כסלו","dp":"חלב","b":"דיין בחלב. תשובה ממנו ב\"דברי יוסף\" לר יוסף אירגס. נזכר במכתב ר ישראל איסר בן אליקים געץ, שפרסם בניהו (הסכמה ורשות בדפוסי ונציה) - ובו מתאר את פגישתו עם ר שמואל בחלב. חיבר שו\"ת. מתומכי ש\"ץ?"},{"i":37952,"n":"פינטו, שמואל משלוניקי ובלגרד","b":"רב בשלוניקי, בלגרד-תן."},{"i":37953,"n":"פינטר, אברהם מבוקובסק","f":"חיים מבוקובסק","bt":"תרס","dt":"תשב","b":"רב בבוקובסק על מקום אביו. חתן ר אשר מאיר הלברשטט. נספה בשואה. פרסם מאמרים ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":37954,"n":"פינטר, אברהם מטורנא","f":"יצחק מבוקובסק","bt":"תרך","dt":"תרצז","dp":"פוט (הולנד)","b":"ויתר על רבנות בוקובסק לאחיו ר חיים. עבר לטורנא. חתן ר שלמה זלמן קנריק מרישא."},{"i":37955,"n":"פינטר, אליהו מבוקובסק","b":"רב בבוקובסק-תרלט."},{"i":37956,"n":"פינטר, חיים מבוקובסק","f":"יצחק מבוקובסק","bt":"תרמא","dt":"תשא-ג","dp":"לונדון","b":"חתן ר פנחס צימט מוליצקה. מלחין פורה. רב בבוקובסק(=ביקאווסק) (לחסידי צאנז)-תרסח על מקום אביו. רב בוינה-תרפב. עבר לאנגליה-תרצט. בנו ר אברהם על מקומו בבוקובסק."},{"i":37957,"n":"פינטר, יואל משה","f":"מרדכי מסאנוק","k":"בעל קול מרדכי","b":"נכד ר יצחק מבוקובסק. חתן ר אהרן הלברשטט מביאלא-ביליץ. ניצל מהשואה ועבר לניו יורק. חיבר \"קול מרדכי\" ניו יורק תשכז."},{"i":37958,"n":"פינטר, יחזקאל מקורטשין","b":"מחכמי קורטשין-תרצט."},{"i":37959,"n":"פינטר, יצחק מבוקובסק","f":"מרדכי","bt":"תר","dt":"תרסה","b":"רב בבוקובסק. חתן הגביר ר מאיר לנדא מלינסק."},{"i":37960,"n":"פינטר, מרדכי","f":"אברהם הרצוג פודוליר","b":"החליף שם משפחתו לפינטר אחר שברח מרוסיה. בנו ר יצחק - רב בבוקובסק."},{"i":37961,"n":"פינטר, פנחס מניו יורק","f":"צבי הירש מדוברומיל","b":"רב בניו יורק. הוציא מחדש \"שדה יהושע\" ו\"כרם יהושע\" עם הקדמה ממנו ועם מגילת יוחסין שלו."},{"i":37962,"n":"פינטר, צבי הירש","f":"אברהם מדוקלא","dp":"ניו יורק","b":"חסיד שיניבה. נכד לאחים ר שמלקא ור פנחס בעל ההפלאה. מחכמי דוברומיל. חתן ר ישכר בר הכהן לויטרבך מדרוהוביטש."},{"i":37963,"n":"פינטר, שמואל שמלקא מבוקובסק","f":"חיים מבוקובסק","b":"עבר ללונדון וכיהן שם כרב. חתן ר ישראל אריה מרגליות האדמור מפרימישלן."},{"i":37964,"n":"פינטשובר, יוחנן מפפד\"מ","b":"ר\"מ בפפד\"מ-תקי. גיסו של ר אליהו מאילינוב."},{"i":37965,"n":"פינטשובר, יחיאל מיכל מטבריה","f":"משה","dt":"תקנב - לפני","b":"בשליחות קהילת החסידים בטבריה-תקמט. לאחר פטירתו דאג בעל התניא לכספים עבור האלמנה והיתומים."},{"i":37966,"n":"פינטשוק, משה אהרן מחומסק","dt":"תשג","b":"רב בחומסק"},{"i":37967,"n":"פינטשוק, שלמה","dt":"תשג","b":"רב במאלאריטע"},{"i":37968,"n":"פינטשוק, שלמה מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":37969,"n":"פינייא די לה, יעקב מג'מייקה","dt":"תקיא","dp":"ג'מייקא","b":"רב בג'מייקא-תקח."},{"i":37970,"n":"פינייא, חיים מאזמיר","b":"גביר מחכמי אזמיר, מתומכי ר חיים בנבנישתי בעל כנסת הגדולה. ממשפחת ר שמואל פינייא ממצרים. ממתנגדי ש\"ץ ונאלץ לברוח ממאמיניו של ש\"ץ, אולם לאחר זמן הפך לתומך בש\"ץ."},{"i":37971,"n":"פיניירו, אברהם","bp":"חלב","dt":"תקכד","dp":"חלב","b":"גביר, מתומכי התורה"},{"i":37972,"n":"פיניירו, משה מאזמיר","dt":"תקעה - יט אייר","b":"מראשוני מאמיני ש\"ץ-תח, והמשיך להאמין גם אחרי המרתו של ש\"ץ-תכז. גיסו - ר יוסף אירגאז מליוורנו."},{"i":37973,"n":"פיניצי, שלום מסרייבו","f":"משה","dt":"תרלח","dp":"אלכסנדריה","b":"רב וראש ישיבה בסרייבו !(=שאראי בוסניה), הגיע לארץ כדי לחלוץ לאלמנת אחיו, ובשבו דרך אלכסנדריה נפטר."},{"i":37974,"n":"פינלס, בנימין וולף מלמברג","b":"רב בלמברג - תשובה אליו \"חדושי אנשי שם\"."},{"i":37975,"n":"פינלס, הלל מגלינא","b":"גביר מחכמי גלינא-תרעב."},{"i":37976,"n":"פינלס, יוסף מדוברומיל","b":"מחכמי דוברומיל. חתן ר אברהם גוט."},{"i":37977,"n":"פינלס, צבי הירש מלמברג","b":"מחכמי למברג - תשובות אליו - טוט\"ד."},{"i":37978,"n":"פינלס, צבי מנחם הירש מנדל","f":"שלמה","k":"בעל כך דרכה של תורה","bt":"תקסו","bp":"טיסמניץ","dt":"תרל - ט אב","dp":"גאלאץ","b":"מחכמי ברודי, אודסה, גאלאץ(=גאלאטץ). פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"כרם חמד\", ועוד. חתם בשם \"שלש\" (סופי תיבות שמו - הירש מנדל פינלש). חבר ב\"כל ישראל חברים\" - אליאנס. בנו - שמואל."},{"i":37979,"n":"פינלס, שלום","f":"[צבי מנחם מטיסמניץ]","b":"תשובות אליו - מהרי\"א הלוי - תרכט, ועוד."},{"i":37980,"n":"פינס, אהרן","f":"יעקב פינס"},{"i":37981,"n":"פינס, אליהו זוטא מסלוצק","f":"אהרן","k":"בעל תנא דבי אליהו","dt":"תקנו - טו ניסן","b":"נכד ר אליהו בן יהודה ליב פוחוביצר מפינסק. מו\"צ בשקלוב. נוסח מצבתו ב\"דעת קדושים\"-\"יתרון דעת\" - תרנב. בנו - ר מרדכי מסלוצק."},{"i":37982,"n":"פינס, אליעזר משערשוב","f":"דוד","b":"תלמיד ר פנחס מואנגרוב בעל \"נחלת עזריאל\". רב בשרשוב(=שארשוב). בנו - ר פנחס שמואל."},{"i":37983,"n":"פינס, אליעזר צבי מטארגין","k":"בעל מדת משנה","bt":"תרד","dt":"תרצז - כא טבת","b":"רב בטורוגין(=טארגין), ובנו ר יעקב על מקומו אחריו. חתנו - ר יהודה לאבא מליגום."},{"i":37984,"n":"פינס, אריה ליב מראזינאי","f":"צבי הירש","b":"רב בראזינאי. אחיינו של ר יצחק מסלונים-חתן ר אלעזר מקעלין בעל \"אור חדש\". בנו - ר נח, ונכדו ר יחיאל מיכל."},{"i":37985,"n":"פינס, דב בער ממינסק","b":"חתן הגביר ר שמחה אטינגר ממינסק. גביר מראשי קהלת מינסק-תרמג, עמד בראש חברת \"תומכי תורה\"."},{"i":37986,"n":"פינס, דוד","f":"אליהו פינס","b":"בנו - ר אליעזר משארשוב."},{"i":37987,"n":"פינס, חיים שאול מביאליסטוק","f":"מרדכי מוילקוביסק","b":"מחכמי ביאליסטוק-תר."},{"i":37988,"n":"פינס, יוסף מארץ ישראל","b":"עסקן צבור, פעל להקמת ישיבת \"היכל התלמוד\" בתל אביב-תרצד."},{"i":37989,"n":"פינס, יחיאל מיכל מירושלים","f":"נח בן אריה ליב","k":"בעל ילדי רוחי - תרלב","bt":"1842","bp":"רוז'נוי-ליטא","dt":"1912","b":"בגיל 12 פרסם ב\"הלבנון\". חיבר \"ילדי רוחי\" ובו סתר את רעיונות ההתבוללות והתקונים בדת. עלה לארץ-1878 ועסק בישוב הארץ וגאולת קרקעות והחייאת הלשון העברית. ממיסדי השכונות \"אהל משה\", \"מזכרת משה\" בירושלים, \"יהודיה\", \"פתח תקוה\". פרסם ב\"הצבי\", \"חבצלת\" והתוכח במאמריו עם \"אחד העם\" בנושא הדת והלאומיות. היה מחלוקת נגדו מצד רבני ירושלים בגלל התנגדותו ל\"חלוקה\". ממיסדי \"ועד הלשון\". מורה בביהמ\"ד למורים בירושלים. תרגם ספרים לעברית. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט. חתנו דוד ילין ויוסף מיוחס הו\"ל מבחר מאמריו בשם \"בנין הארץ\", פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"המסדרונה\" - פפד\"מ-ירושלים תרמה, \"הפלס\" - ברלין תרסא-תרסה."},{"i":37990,"n":"פינס, יעקב מטארגין","dt":"תש..","b":"רבה האחרון של טאורוגין(=טארגין)-תרפ על מקום אביו. נספה בשואה."},{"i":37991,"n":"פינס, יעקב ממינסק","b":"רב במינסק-תר\"מ"},{"i":37992,"n":"פינס, יעקב מסלוצק","b":"רב בסלוצק"},{"i":37993,"n":"פינס, יצחק ממינסק","f":"נפתלי","dt":"תקצו","b":"רב במינסק על מקום ר שמואל סגל. בנו - ר משה שמואל ממינסק."},{"i":37994,"n":"פינס, יצחק ממינסק - ב","b":"דומ\"צ במינסק-תרע. בנו - ר שמואל ממינסק."},{"i":37995,"n":"פינס, ישראל יוסף מוילנא","f":"מרדכי מירושלים","bt":"תקעח","dt":"תרמו - יז טבת","dp":"וילנא","b":"נכד ר נח פינס מוילקוביסק - ומכן שם משפחתו. גביר מחכמי וילנא. פעל רבות לטובת היהודים בזמן מגפת הכולירה-תרח והקים מרכז רפואי יחד עם חברו ר יהושע צבי קוסובסקי."},{"i":37996,"n":"פינס, מיכל זלמן מפרוזין","b":"גביר מחכמי פרוזין, מקורב לגדול ממינסק."},{"i":37997,"n":"פינס, מרדכי מוילנא","f":"מרדכי ר צמח'ס","dt":"תקיט - ו תשרי","dp":"וילנא","b":"חתן ר נח פינס (וקיבל את שמו). אחיו ר שמעון הגדול. בניו - ר אליהו הינדיש מוילנא, ר ישראל מגיד מישרים, ר שאול מאסטרין, ר ירחמיאל."},{"i":37998,"n":"פינס, מרדכי מסלוצק","f":"אליהו זוטא מסלוצק","b":"רב בסלוצק-תר. חתנו - ר עקיבא אלטשול מטשאווס."},{"i":37999,"n":"פינס, משה שמואל ממינסק","f":"יצחק","dt":"תרכב - טו סיון","dp":"מינסק","b":"תלמיד ר מנחם מנדל ממינסק. מו\"ץ במינסק-תרך."},{"i":38000,"n":"פינס, נח מוילקוביסק","b":"גביר בוילקוביסק - בשנות התק'. בניו: הגביר ר ליב מראזינאי, ר יעקב שמואל מוילקוביסק, ר אבא משוינצאן, ר הירש מקיוב, ר חיים שאול מביאליסטוק. חתנו - ר מרדכי פינס מוילנא (קיבל את שם חותנו)-אביו של הגביר ר ישראל יוסף."},{"i":38001,"n":"פינס, נח מסלונים","dt":"תרלב - כג חשון","b":"רב בסלונים. בנו - ר יחיאל מיכל."},{"i":38002,"n":"פינס, פנחס שמואל מאבולניק","f":"אליעזר משרשוב","b":"רב באבונליק."},{"i":38003,"n":"פינס, שלמה זלמן מקידאן וציריך","f":"דובער ממינסק","k":"בעל איזהו נשך","bt":"תרלד","bp":"מינסק","dt":"תשטו","dp":"ציריך","b":"רב במינסק-תרס, סוסלוביץ(=סויסלאטש)-פלך מינסק-תרע, סויסלאטש-פלך וילנא, קידאן-תרפ, ציריך. בנו - ר אהרן קוטלר. חיבר גם \"פנס שלמה\", ועוד. פרסם מאמרים ב\"אור תורה\" - לונדון תרצד, \"בית המדרש\" - מונטרא תש, \"שערי ציון\" - ירושלים תרפא. גיסו של ר חנוך הנדל פרידלנד מפאריטש.","bk":[["איזהו נשך - הלכות ריבית",""],["מוסר המקרא והתלמוד",""],["נבואת הושע",""],["פירוש על ישעיהו",""],["פירוש על תהלים",""],["פנס שלמה - חידושים וביאורים לכמה מסכתות והלכות ברמב\"ם",""]]},{"i":38004,"n":"פינס, שמחה","b":"פרסם מאמרים ב\"היכל התלמוד\" - ת\"א תשא."},{"i":38005,"n":"פינס, שניאור זלמן מסויסלוץ","bt":"תרטז","dt":"תרסג - כד אב","b":"דרשן,רב בסוויסלוץ-תרנ\"א"},{"i":38006,"n":"פינסו, אברהם חיים מירושלים","f":"רחמים ישראל","dt":"תרנו","dp":"ירושלים","b":"מרבני ירושלים וחברון, בשליחות-תרכז עם ר אהרן עזריאל. חתניו: ר נסים אלישר, ר שמעון אשריקי, ר רפאל כהן שאקו, ר אלעזר מיוחס."},{"i":38007,"n":"פינסו, אברהם מירושלים","b":"מחכמי ירושלים, תלמידו וחתנו - ר שמעון אשריקי ממרוקו וירושלים."},{"i":38008,"n":"פינסו, אברהם מסרייבו וירושלים","f":"ישראל","k":"בעל תולעת שני","bt":"תק - בערך","dt":"תקף - יח חשון","dp":"ירושלים","b":"חתן ר דוד פארדו בעל שושנים לדוד. רב בסרייבו וראש ישיבה, עלה לירושלים. בנו - ר דניאל סייע בהוצאת ספרי אביו \"תולעת שני\" שלונקי תקסה. \"אפי זוטרי\" שלוניקי תקסה, ועוד. בנו ר חיים דוד שלמה פינסו בעל \"שם חדש\""},{"i":38009,"n":"פינסו, חיים דניאל שלמה מירושלי","f":"אברהם - תולעת שני","k":"בעל שם חדש","bp":"סרייבו","dt":"תרא - כב אייר","dp":"ירושלים?","b":"תלמיד ר דוד פארדו. מחכמי סרייבו, עלה לארץ-תקס עם אביו - שהיה רב בסרייבו. מקובל ומראשי ישיבת \"בית אל\" בירושלים. חיבר \"שם חדש\" ירושלים תרג.","bk":[["שם חדש [על היראים]",""],["שם חדש – יראים",""],["שם חדש",""]]},{"i":38010,"n":"פינסו, יוסף שמואל משלוניקי","f":"ישורון חי","b":"רופא מחכמי שלוניקי, שאלה ממנו-תצז לר אהרן אמריליו."},{"i":38011,"n":"פינסו, יעקב מבוקרשט","k":"בעל תולעת יעקב","dt":"תרט - כב טבת","dp":"ירושלים","b":"אב\"ד בוקרשט ואחר כך בטאטאר פדארג'יק(=פזארדגיק)-בולגריה, עלה לירושלים ונתמנה לראב\"ד. בשנת תרד חתם על הסכם השלום בעדה הספרדית. חיבר \"תולעת יעקב\", תשובה ממנו בספר \"חוקי חיים\" (סימן יט). הסכים על \"ספר התקנות\", סידור תפלת ישראל, \"טוב ירושלים\", \"דברי שלום\". (ראה גם ר יעקב פינצי)."},{"i":38012,"n":"פינסו, מרדכי מאיפסולה","b":"גביר באיפסולה-שנות ה-ש'-ת'."},{"i":38013,"n":"פינסו, עמנואל","b":"רב-שנת תק\"כ"},{"i":38014,"n":"פינסו, עמנואל מבוסניה","b":"נזכר ב\"קהילת יעקב\" לאחיינו ר יעקב פארדו."},{"i":38015,"n":"פינסון, קופל שוב","bt":"1904","bp":"פוסטאב-פלך וילנא","dt":"1961","b":"היגר בילדותו לארה\"ב. היסטוריון, עורך באנציקלופדיה למדעי החברה האמריקאית. פרופ' להסטוריה, מרצה ב\"יייווא\". חיבר ספרים באנגלית."},{"i":38016,"n":"פינסטרבוש, אביש","f":"אלישע מסמבור","b":"ממשתתפי \"תלפיות\" - תרצח."},{"i":38017,"n":"פינסטרבוש, שמריה מסמבור","f":"אלישע","bt":"תרסט","bp":"סמבור","dt":"תשג","b":"מתלמידי מהרם שפירא בלובלין, שימש כ\"רב פורים\" בישיבה במשך שנים. חתן הגביר הרמלע ממעליץ. רב באנפול, ראדום, ראחוב עד השואה, נשיא המכינה של הישיבה. נספה בשואה. פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":38018,"n":"פינסי, אברהם מתונס","b":"מרבני תונס"},{"i":38019,"n":"פינסי, יוסף מאמשטרדם","f":"יצחק","k":"בעל פרדס שושנים","bp":"אמשטרדם","b":"בן לאנוס שהגיע לאמשטרדם, למד באמשטרדם ובליוורנו. חיבר שירים ומחזות בעברית וספרדית. התישב באנטורפן."},{"i":38020,"n":"פינסק, ליב","k":"בעל דמיון אריה","b":"רופא-שנת ת\"נ"},{"i":38021,"n":"פינסקי, מאיר","b":"רב באוקריינה-תרפ\"ז"},{"i":38022,"n":"פינסקי, קלמן זליג","b":"פרסם מאמרים ב\"קול תורה\" - גייטסהד תשז."},{"i":38023,"n":"פינסקר, אברהם מירושלים","b":"רב בירושלים, דיין אצל ר ישראל משקלוב. נסע בשליחותו להונגריה להדפסת \"פאת השלחן\", בשליחות-תרז ונשדד בדרכו. נזכר ב\"יהודה יעלה\" לר יהודה אסאד, שפגשו בשליחותו. חתנו - ר יעקב גולדמן. בנו - ר זאב וולפנזון."},{"i":38024,"n":"פינסקר, גרשון דובער מחרסון","f":"שלמה זלמן","bt":"תרה","b":"רב בברזנובאטא-פלך חרסון-תרלו, חרסון-תרמו."},{"i":38025,"n":"פינסקר, שבח מטרנוב","f":"מרדכי הלוי","dt":"תקעו","b":"רב ומגיד בטרנוב. סבב בערים לשאת דרשות. בנו ר שמחה בעל לקוטי קדמוניות, ונכדו יהודה ליב מראשי הציונות."},{"i":38026,"n":"פינסקר, שלמה זלמן","b":"רב בקרייצבורג, לובאויטש, חרסון-תרך."},{"i":38027,"n":"פינעדא די, תומש מפורטוגל ואמשט","bt":"שעד","bp":"בעאירא-פורטוגל","dt":"תם","dp":"אמשטרדם","b":"מאנוסי פורטוגל נאסר ע\"י האינקויזיציה, ברח לאמשטרדם. תרגם את ספרו של החכם סטפנוס ביצנטינוס, עם הוספות רבות ממנו. נספד מאת ר דניאל לוי די באריוס."},{"i":38028,"n":"פינפר, חיים מראסיין","f":"פסח צייקישקער","b":"נכד ר אלחנן הכהן-חתנו של ר אברהם אבא חסיד מקרוז'."},{"i":38029,"n":"פינפר, יצחק הכהן מניו יורק","f":"חיים","k":"בעל דברי יצחק","b":"רב בניו יורק. חיבר \"דברי יצחק\" נ\"י תרע\"א ובודפסט תרפג."},{"i":38030,"n":"פינפר, פנחס מדרשונישוק","bt":"תרכג","dt":"תרפט","b":"רב בדרשונישוק."},{"i":38031,"n":"פינפר, פסח הכהן מוילנא","f":"חיים מראסיין","k":"בעל חקר אבות","bt":"תקצז-ח","bp":"ראסיין","dt":"תרעג - כג חשון","b":"חתן ר עזריאל וולף מקובנא. תלמיד ר שמואל מאלקסוט. רב בקאזאן, ואגאר, דרשונישוק, שקוד (ר\"ת - קודש), וילנא-תרלד. עסק בחקר מדעי של כתבי הקודש, וסבר כי חלוקת התנ\"ך לפרקים הינה המצאה נוצרית ויש לוותר עליה. ביקר בארצות מערב אירופה לצורך מחקריו ובדק שם כתבי יד עתיקים של התנ\"ך, וחיבר \"מסורת התורה והנביאים\" בתמיכת קהילת וילנא ופרופ' ברלינר, חיבר גם \"ציון ומשפט\", ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":38032,"n":"פינץ","k":"ראה: פינצי","b":"רב ברוסג'וק, פיליבי-תקפט על מקום ר רחמים אברהם וינטורא ור חיים בן אהרן ן ארוליא על מקומו אחריו (עזב בגלל מחלוקת בקהלה), רב בבאזארג'יק, עלה לארץ-תקצז. הסכים על \"סדור תפלת ישראל\", \"טוב ירושלים\", \"דברי שלום\"-תרג. חתם בירושלים בענין עגונה-תקצח. (אולי הוא ר יעקב פינצי מבוסניה וירושלים שהיה חתן ר חיים אברהם גאגין)."},{"i":38033,"n":"פינץ די, שמואל","k":"בעל הכתב בענין סוד ה","b":"אליו נכתב המכתב בענין סוד האלוקות לרופא אברהם מיכאל קרדוזו."},{"i":38034,"n":"פינץ, משה מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":38035,"n":"פינצו, אריה ליב ממנטובה","k":"בעל גור אריה","dt":"תקיד - א טבת","b":"מגדולי חכמי איטליה,רב במנטובה"},{"i":38036,"n":"פינצוק, יעקב ממיר","k":"בעל תורת יעקב","b":"ר\"מ בישיבת נוברדוק. עורך \"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":38037,"n":"פינצוק, פנחס","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":38038,"n":"פינצי, אברהם מעכו","dt":"תרל - שבט","dp":"צפת","b":"סגן קונסול בריטניה בעכו-תקצט, ונפגש עם מונטיפיורי בענין התישבות יהודים בארץ."},{"i":38039,"n":"פינצי, אהרן ממאריי","dt":"שמה - יג כסלו","b":"רב במאריי-איטליה, פיררה. נזכר אצל ר גא\"ל (=גור אריה הלוי) בהגהותיו לש\"ע, ובשו\"ת המבי\"ט. חי בזמנו של הרמ\"ך. קינה לזכרו מהמשורר ר מאיר שלמה."},{"i":38040,"n":"פינצי, אלישע מיכאל מפיררה","b":"תלמיד ר יצחק למפרונטי. רב בפיררה. אביו של ר יצחק רפאל פינצי מפדובה. תשובות ממנו ב\"פחד יצחק\". ועוד תשובות ממנו יחד עם חברו ר אברהם שבתי."},{"i":38041,"n":"פינצי, גור אריה ממנטובה - הנכד","dt":"תקיד - א טבת","b":"רב במנטובה. נכד הרב גא\"ל בעל \"גור אריה\" וחבר הקדמה לספר זקנו. מחדושיו ב\"אמונת חכמים\". נשא ונתן עם תלמידי הרמ\"ז וביניהם - ר אברהם סגרי מ\"ץ בקאזל\"י - (אגרות משניהם בספריית ר מרדכי גירונדי). קינה עליו נדפסה מאת ר\"ש קאלימני."},{"i":38042,"n":"פינצי, דוד ממנטובה","f":"עזריאל","k":"בעל פתח האהל","dt":"תצה","b":"רב במנטובה-תץ, אליסנדריא דילה פאלייה. תלמיד מהר\"י בריאל ור משה זכות. ב\"שמש צדקה\" תשובה ממנו בענין קידושי אורבינו-תפט. בקובץ תשובות רבני איטליה - שאלות רבות ששאל את רבו מהר\"י בריאל. חיבר \"פתח האהל\" בכת\"י. חתנו - הרמח\"ל."},{"i":38043,"n":"פינצי, דניאל מירושלים","bp":"איטליה","b":"מחכמי איטליה, עלה לירושלים ונמנה על חכמיה בשנת שפה, כתב קונטרס בענין הציצית נדפס בחלקו בשות \"באר עשק\" סימן כא."},{"i":38044,"n":"פינצי, חזקיה מאיטליה","b":"מגדולי ההלכה בחכמי איטליה, רב בפיררה-שס. רבו של ר יהודה אריה ממודנא, ובן דורם של מהר\"ם פרובנצאלי והרמ\"ע מפאנו, תשובות בספרי חכמי דורו."},{"i":38045,"n":"פינצי, חיים מפיסארו","k":"בעל עץ חיים","b":"רב בפיסרו. תלמיד ר יצחק גרשון. חיבר \"עץ חיים\" - על תהלים - בכת\"י (אצל ר חיים מיכל)."},{"i":38046,"n":"פינצי, חנניה מגאזולו","b":"רב בגאזולו. נזכר ב\"באר עשק\"."},{"i":38047,"n":"פינצי, יוסף מסרייבו ובלגרד","k":"בעל וילקט יוסף","bp":"סרייבו","dt":"תרי","b":"רב בבלגרד-תקצז. מכתביו נדפס \"וילקט יוסף\", חיבר דינים בלדינו ונדפסו בסידור בלגרד תרב."},{"i":38048,"n":"פינצי, יחיאל מאיטליה","f":"אברהם","b":"רב בפירנצה-תך. תשובה ממנו בשו\"ת הרמ\"ז-תכז."},{"i":38049,"n":"פינצי, יעקב ישראל מריקנטי","b":"רב באיטליה בזמן ר יחיאל טרבוט. חיבר שו\"ת - הוזכרו ב\"פחד יצחק\" - שכתב שראה אותם בבית מדרשו ר\"נ הלוי בפדובה."},{"i":38050,"n":"פינצי, יעקב מרוסג'וק וירושלים","k":"בעל זכות אבות","dt":"תרל - כא שבט","dp":"ירושלים","b":"חתן ר חיים אברהם גאגין. רב ברוסג'וק, פיליבי-תקפט על מקום ר רחמים אברהם וינטורא ור חיים בן אהרן ן ארוליא על מקומו אחריו (עזב בגלל מחלוקת בקהלה), רב בבאזארג'יק, עלה לארץ-תקצז. הסכים על \"סדור תפלת ישראל\", \"טוב ירושלים\", \"דברי שלום\"-תרג. חתם בירושלים בענין עגונה-תקצח. אחיו של הגביר ר משה שהחזיק בישיבה בירושלים. (לפי רוזניס נפטר בשנת תרט). (ראה גם ר יעקב פינסו - לדעת רבלין בחכמי ירושלים המדובר באותו החכם, לדעת פרנקל היה בין חכמי ירושלים בתרטז)."},{"i":38051,"n":"פינצי, יצחק מאיטליה","b":"רב ומקובל באיטליה בזמן ר יעקב פולק, רב בפיזרו-שלג. חיבר פירוש ל\"מערכת אלקים\" לרבינו פרץ. אחיינו היה ר ישראל פינצי - רבו של בעל שלשלת הקבלה."},{"i":38052,"n":"פינצי, יצחק רפאל מאיטליה","f":"אלישע מיכאל","k":"בעל פרי יצחק","bt":"תפח","bp":"פיררה","dt":"תקעג - ז תשרי","dp":"פדובה","b":"רב בקאזלי, פדובה-תקמו. תלמיד ר יצחק למפרונטי ובנו שלמה ושל ר פנחס עבו. רב בפיררה, במלכות פיימונטי תחת ר שבתי אלחנן מהזקנים, קאזלי תחת ר אברהם סגרי - ונשא את נכדתו, ור שמשון באקי - דודו. רב בפדובה ודרשן מפורסם - גם שרים וכמרים היו באים לשומעם. מראשי הסנהדרין שיסד נפוליאון וישב לצדו של הנשיא ר דוד זינצהיים. (יש רושמים פטירתו - יט ניסן). מתלמידיו - ר מרדכי שמואל גירונדי."},{"i":38053,"n":"פינצי, מיכאל יוסף מסרייבו","dt":"תרד - ד אלול","b":"רב בסרייבו."},{"i":38054,"n":"פינצי, מרדכי מאיטליה","k":"בעל נתיב חכמה","b":"רב באיטליה."},{"i":38055,"n":"פינצי, מרדכי משלוניקי","b":"מגדולי חכמי שאלוניקי-ש\"צ"},{"i":38056,"n":"פינצי, משה","dt":"תרלג - כא אב","dp":"וינה","b":"גביר, יסד בירושלים ישיבת \"שבת אחים\" לאנשי בוסניה-תרלא בראשות קרובו - ר אהרן עזריאל, ור אברהם עזריאל שהזכירו בספרו. אחיו של ר יעקב מבוסניה וירושלים."},{"i":38057,"n":"פינצי, משה חיים מאיטליה","f":"אליעזר","b":"תלמיד ר שלמה למפרונטי בפיררה. מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה."},{"i":38058,"n":"פינצי, משה מאיטליה","b":"מחכמי איטליה. נזכר בשו\"ת המבי\"ט."},{"i":38059,"n":"פינצ'י, משה מסרייבו","b":"מרביץ תורה,רב בשאראי-בושנא,עלה לירושלים"},{"i":38060,"n":"פינצי, שלמה מרוויגו","f":"אליקים","k":"בעל מפתח הגמרא","b":"רב ברוויגו בזמן המהרש\"ל. חיבר \"מפתח הגמרא\" - \"מסורת התלמוד\"."},{"i":38061,"n":"פינצי, שמואל יצחק","f":"משה חי","k":"בעל קיצור אזהרות","b":"מחכמי איטליה, חיבר \"קיצור אזהרות לחזנים\" - רג'יו תקף."},{"i":38062,"n":"פינצי, שמואל יצחק מפיררה","f":"אלישע","dp":"פיררה","b":"חתן ר יעקב חי ריקנטי. מלמד מחכמי פיררה. שיר ממנו נדפס ב\"אמת ליעקב\" - ליוורנו תרג."},{"i":38063,"n":"פינצי, שמואל שר שלום מפיררה","k":"בעל אמרי אמת","dt":"תקנא","dp":"פיררה-איטליה","b":"תלמיד ר יצחק לאמפרונטי בעל \"פחד יצחק\". רב בפיררה."},{"i":38064,"n":"פינציק, מאיר מרובנא","f":"יוסף האדמור מברזנא","dt":"תרעה - ז תשרי","b":"חתן דודו ר חיים מברזנא (שושלת ליבישוב)."},{"i":38065,"n":"פינצמי, מנחם","k":"בעל זכות אבות","dt":"תרסב - ל תשרי","dp":"יפו"},{"i":38066,"n":"פינק, אליהו מבלביריקוש","b":"רב בבלבירישוק על מקום ר ברוך גרוסברד, ור חיים לב הי\"ד על מקומו אחריו."},{"i":38067,"n":"פינק, אלתר אשר כץ מאלטשטט","b":"מחכמי אלטשטט - תשובה אליו - צבי לצדיק."},{"i":38068,"n":"פינק, אשר אנשיל","f":"יואל","dt":"תשמו","dp":"ניו יורק","b":"עבר מגליציה לארה\"ב - רב בישיבת תורה ודעת ומראי אגו\"י."},{"i":38069,"n":"פינק, דב הכהן","k":"בעל ברכת חן","b":"תלמיד ישיבת תורה ודעת - ניו יורק. חיבר \"ברכת חן\" ניו יורק תשמו - עם הסכמת ר\"מ פיינשטיין."},{"i":38070,"n":"פינק, דוד מדוקלא","dt":"תרסה - לפני","b":"חתן ר יחיאל מיכל בארוך מדובצק (מחבורת ר\"נ מרופשיץ)."},{"i":38071,"n":"פינק, דניאל מצוויטאו","f":"ראובן","bt":"תרך","b":"רב בצוויטאו, וינה-תרסא. מראשי המזרחי. חיבר ספר להוראת הכתיבה."},{"i":38072,"n":"פינק, זאב אביגדור וולף מטרנוב","bp":"טרנוב","b":"חתן ר יצחק בצלאל שליסל מדזיקוב. דיין בדזיקוב-תרסח, רב בטרנוב. נספה בשואה."},{"i":38073,"n":"פינק, חיים ברוך מניו יורק","f":"דוד אלימלך","b":"חסיד בלז. ניצל מהשואה ועבר לניו יורק - רב בניו יורק."},{"i":38074,"n":"פינק, יואל מליסקא וניו יורק","f":"זאב וולף מליסקא","dt":"תשכה","dp":"ירושלים","b":"רב בליסקא, ניו יורק ור\"מ בישיבת תורה ודעת. עלה לירושלים. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":38075,"n":"פינק, יחיאל מיכל מדוברומיל","f":"דוד מדוקלא","bt":"תרך","dt":"תרעט","dp":"הונגריה","b":"חתן הנגיד ר זאב וולף שוורץ מדוברומיל. רב בדוברומיל-תרסה. חסיד צאנז."},{"i":38076,"n":"פינק, יעקב חזקיהו מרישא","f":"מנחם מנדל אריה'ס","dt":"תשמד","dp":"ירושלים","b":"למד בביהמ\"ד בברלין. ברח לארגנטינה-תרצט, רב בבואנוס איירס, ריו דה ז'נירו, עלה לארץ-תשכב. רב בחיפה."},{"i":38077,"n":"פינק, מנחם מנלי מקראקא","f":"יהושע השל מקראקא","dt":"תרלח","b":"עסקן ציבור ויועץ העיר בקראקא."},{"i":38078,"n":"פינק, משה מליזנסק","b":"מחכמי ליזנסק-תרף."},{"i":38079,"n":"פינק, ראובן מהמבורג","f":"יצחק איצק מבנדזין","k":"בעל תנובת יהודה","r":"רב דק\"ק לויטענבורג","bt":"תקץ","bp":"בנדזין (או מיסלוביץ)","dt":"תרס - ד אייר","dp":"המבורג","b":"מוהל ורב בויטקבה, חרציזין, אלטברון, בוק, לויטרבורג (פרוסיה), מחכמי ביהמ\"ד \"ר ליב בר שאול\" בהמבורג. (היה מעורב במחלוקת עם הרב של המבורג ר אשר אנשל שטרן ופרסם \"חסד ואמת - בגרמנית - כנגד הרב, ובתגובה יצאו נגדו בחוברת \"צדק ומשפט\"). חיבר \"תנובת יהודה\" קראקא תרנו, \"חסד ואמת\".","bk":[["חסד ואמת - ההיתר לקבור בבית הקברות באולסדורף שנקנה על תנאי שאפשר לפנותו",""],["תנובת יהודה - ש\"ס",""]]},{"i":38080,"n":"פינק, שמואל דב מווהנילוב","f":"יחיאל מיכל מדוברומיל","b":"רב בווהנילוב(=ואנילוב). חתן ר דוד אריה מקריפטש."},{"i":38081,"n":"פינקה, דובער","f":"זיסקינד","bt":"תרלז","dt":"תשג","b":"תלמיד ישיבת סלובודקא, וולוזין, כולל קובנא. רב במיאר-פלך וילנא-תרסח. נסמך מאת: ר רפאל שפירא מוולוזין, ר משה דנישבסקי, ר מרדכי וויצעל מסלונים."},{"i":38082,"n":"פינקה, שלמה מקלם","bt":"תרמו","bp":"לומזה","dt":"תשה","b":"תלמיד ישיבת מיר, נשלח לקלם ולמד אצל ר נחום זאב זיו ור צבי ברוידא, ר\"מ בישיבת \"אור תורה\" בקעלם-תרצא (הישיבה הקטנה של קעלם). נספה בשואה."},{"i":38083,"n":"פינקוס, שמשון דוד מאופקים","r":"רב הקהילה החרדית באופקים","bt":"תשד","dt":"תשסא - יב ניסן","b":"חתן ר מרדכי ליב מן - ראש ישיבת \"בית הלל\" מבני ברק. רב הקהלה החרדית באופקים. נספה בתאונה עם אשתו ובתו.","bk":[["שערים בתפילה",""],["ברכות בחשבון - יחוד השם, אמונה, והשגחה",""],["נפש חיה - תפקידה של האם והבת בישראל",""],["נפש שמשון - אגרות ומאמרים",""],["שבת מלכתא - הערות בענייני שבת",""],["שיחות רבי שמשון דוד פינקוס זצ\"ל - אלול",""],["ימים נוראים",""],["גלות ונחמה",""],["הבית היהודי",""],["חנוכה",""],["סוכות",""],["עניני חינוך",""],["פורים",""],["פסח",""],["ספירת העומר",""],["שבועות",""],["שערים בתפילה - על התפילה",""],["תפארת שמשון - על התורה והגדה של פסח",""],["תפארת תורה - חידושים וביאורים בעניינים שונים",""],["אהל מרים",""],["שבת מלכתא",""],["שיחות רבי שמשון דוד פינקוס",""]]},{"i":38084,"n":"פינקל, אברהם מאיר","b":"חתן ר צבי הירש גליקסון מוארשא-ראש ישיבת תורת החיים. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38085,"n":"פינקל, אליעזר יהודה ממיר","f":"נתן צבי הסבא מסלובוד","k":"הסבא מסלובודקה","r":"ראש ישיבת מיר","bt":"תרלט","bp":"קלם","dt":"תשכה - יט תמוז","dp":"ירושלים","b":"תלמיד ישיבות טלז, סלובודקה, סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה), ראדין, בריסק. חתן ר אליהו ברוך קומאיי. ראש ישיבת מיר-תרעז, ובתקופתו הפכה לאחת הישיבות הגדולות והחשובות בעולם, בזמן מלחה\"ע ה-I עבר עם הישיבה לפולטאבה, וחזר למיר-תרף, בשליחות באמריקה-תרפד למען הישיבה. בזמן השואה הצליח לעבור עם הישיבה דרך רוסיה ויפן לארה\"ב, עלה לירושלים-תשא, הקים מחדש את ישיבת מיר בירושלים. חיבר \"דברי אליעזר\". בנו ר חיים זאב ר\"מ בישיבת מיר, ר ביניש ר\"מ בישיבת מיר, ר מאיר. חתנו ר חיים שמואלביץ ראש הישיבה על מקומו אחריו. פרסם מאמרים ב\"תבונה\" - ירושלים תשא.","bk":[["דברי אליעזר - ש\"ס",""]]},{"i":38086,"n":"פינקל, אלתר מעסעעך-הונגריה","b":"פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":38087,"n":"פינקל, אלתר מקולומיאה","b":"מחכמי קולומיאה."},{"i":38088,"n":"פינקל, אשר זעליג הלוי","bt":"תרלו","b":"רב באדעס-תרס\"ו"},{"i":38089,"n":"פינקל, בנימין ביניש","f":"אליעזר יהודה ממיר","b":"ר\"מ בישיבת מיר בירושלים. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":38090,"n":"פינקל, דוד","dt":"תשיח","b":"מרביץ תורה"},{"i":38091,"n":"פינקל, חיים זאב מירושלים","f":"אליעזר יהודה ממיר","b":"חתן ר יוסף חיים זוננפלד (בתו החורגת - לאה). ר\"מ בישיבת \"היכל התלמוד\" בת\"א, ר\"מ בישיבת מיר בירושלים. פרסם מאמרים ב\"שערי אמונה\" - ירושלים תרצה. בנו - ר אריה ראש ישיבת מיר בברכפלד."},{"i":38092,"n":"פינקל, יצחק מיאנוב","b":"רב ומגיד ביאנוב. ספד להרצל-תרסד עם האב\"ד ר שמעון באב\"ד."},{"i":38093,"n":"פינקל, מאיר","f":"אליעזר יהודה ממיר","dt":"תש..","b":"חתן ר צבי הירש גליקסון מוארשא (חתנו של ר חיים סולוביציק). נספה בשואה."},{"i":38094,"n":"פינקל, משה","f":"נתן צבי פינקל","bt":"תרמו","dt":"תרפו - יז ניסן","b":"מרביץ תורה בסלובודקה, חברון. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":38095,"n":"פינקל, משה הערש מוארשא","b":"חתנו - ר יוסף רוזין-הרוגצובר."},{"i":38096,"n":"פינקל, נתן נטע צבי מסלובודקה","f":"משה","k":"הסבא מסלובודקה","bt":"תרט","bp":"ראסיין","dt":"תרפז","b":"מחכמי ליטא, חתן נכדת הרב מקלם. תלמיד ר שמחה זיסל זיו בקלם ועזר לו בהקמת בית הת\"ת בקלם. יסד כולל אברכים בסלובודקא ובקובנא-תרלז. הקים את את ישיבת \"כנסת ישראל\" בסלובודקא-תרלז ועמד בראשה כ-50 שנה וניהלה לפי שיטת המוסר, בתרפה עלה עם הישיבה לחברון. חיבר \"עץ פרי\" לונדון תרכה, ועוד. שיחותיו יצאו לאור ב\"אור הצפון\" ע\"י ר יצחק איזיק שר ור א. גרודזנסקי. מאמר לתולדותיו ב\"היהודי\" - נ\"י תרצו. מתורתו ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה. חוברת לזכרו - במאסף \"תבונה\" - קובנא תרפא.","bk":[["אור הצפון","מחשבה ומוסר - אחרונים"],["שיעורי מוסר (הסבא מסלבודקא)",""]]},{"i":38097,"n":"פינקל, שמואל מגרודנא","b":"מרביץ תורה בגרודנא,רב ביעזנא,ר\"מ בירושלים-תרפ\"ה"},{"i":38098,"n":"פינקל, שמואל מטופורוב","f":"דב","b":"חסיד בלז. רב ומשרטט בתים בטופורוב. חתן ר משה ויינטרויב. ניצל מהשואה לאחר ששירת בצבא הרוסי. עבר לבולטימור."},{"i":38099,"n":"פינקלר, אליעזר דוד מרדושיץ","f":"הלל מרדושיץ","k":"אדמור מרדושיץ","bt":"תריד","dt":"תרפז - כב אד\"א","b":"חתן ר אברהם יצחק מסטשוב (שושלת ליזנסק). אדמו\"ר בראדושיץ."},{"i":38100,"n":"פינקלר, אליעזר מפינטשוב","f":"חיים מאיר מפינטשוב","dt":"תרצז - ז-י שבט","dp":"סוסנוביץ","b":"חתן ר מאיר מאפטא. אדמו\"ר בקיעלץ, סטובניץ (סוסנוביץ)-תרפט. ראש ישיבת אור תורה בפינטשוב."},{"i":38101,"n":"פינקלר, הלל","f":"יצחק שמואל אליהו","dt":"תשה - כז ניסן","dp":"מחנה ריימסדורף","b":"נכד האדמור ר מאיר מנחם פינקלר מפיעטרקוב, ובן האדמור מפיעטרקוב. נספה בשואה בגיל צעיר."},{"i":38102,"n":"פינקלר, הלל מברעזין","dt":"תשג","b":"רב בברעזין"},{"i":38103,"n":"פינקלר, הלל מרדושיץ","f":"יצחק מרדושיץ","k":"אדמור מרדושיץ","dt":"תרסא - כו טבת","b":"נכד-מצד אמו לר ישכר דב בער מרדושיץ. תלמיד ר משה מללוב, ר שלמה מרדומסק, ור חיים מאיר יחיאל ממוגלניצא. אדמור ברדושיץ על מקום אביו."},{"i":38104,"n":"פינקלר, חזקיה פתחיה יהודה","f":"אשר פינקלר","k":"בעל עובר אורח","bt":"תקסג","bp":"למברג","b":"חיבר קונטרס \"עובר אורח\" - צוואה לצאצאיו."},{"i":38105,"n":"פינקלר, חיים מאיר מפינטשוב","f":"יצחק מרדושיץ","k":"אדמור מפינטשוב","dt":"תרעז - כט אדר","b":"תלמיד דודו ר ישראל יצחק, ור שלמה מרדומסק. אדמור בפינטשוב, עבר לקילץ-תרעה. חיבר \"אמרי חיים\", ו\"מנחת יהודה\".","bk":[["אמרי חיים - לחודש אדר",""],["מנחת יהודה - עה\"ת",""]]},{"i":38106,"n":"פינקלר, יצחק מפינטשוב קילץ","f":"אליעזר מפינטשוב","k":"אדמור מפינטשוב בחלם","bt":"תרנח","dt":"תשב","b":"אדמור בחלם. נספה בשואה. לא נשא אישה."},{"i":38107,"n":"פינקלר, יצחק מרדושיץ","b":"חתן ר ישכר דב בער מרדושיץ. רב ברדושיץ-תרג על מקום חותנו."},{"i":38108,"n":"פינקלר, יצחק שמואל אליהו מפיעט","f":"מאיר מנחם מפיעטרקוב","k":"אדמור מפיעטריקוב","bt":"תרנג","dt":"תשה - כז חשון","dp":"מחנה שליבן","b":"חתן ר מנחם דוד מקוזמיר, ישב אצל חותנו בפרגה-ליד וארשא, ולמד עם ר מנחם זמבא. רב ואדמור מרדושיץ בפיעטרקוב על מקום אביו. נספה בשואה. תולדותיו ב\"הוד וגבורה\". בנו הבחור הלל-נספה בשואה. חתנו - הסופר יחיאל גרנטשטין."},{"i":38109,"n":"פינקלר, ישכר דב מלודז","f":"יצחק מרדושיץ","k":"אדמור מרדושיץ בלודז","b":"חתן ר שמואל וינגרטן מרודניק. תלמיד ה\"דברי חיים\" מצאנז. אדמור בלודז."},{"i":38110,"n":"פינקלר, מאיר מנחם מפיעטריקוב","f":"הלל מרדושיץ","k":"אדמור מפיעטריקוב","dt":"תרעב - ה סיון","b":"חתן ר שמואל אליהו מזוואלין (שושלת קוזמיר)."},{"i":38111,"n":"פינקלר, פנחס ישכר מסוסנוביץ","f":"אליעזר מפינטשוב","k":"אדמור מפינטשוב בסוסנ","bt":"תרמג","dt":"תשג","dp":"ליד קראקא","b":"חתן ר משה שלמה יחיאל משילץ (משושלת ללוב). נספה בשואה. אדמור מפינטשוב בסוסנוביץ."},{"i":38112,"n":"פינקלר, קלמיש מרדושיץ","f":"ישראל יוסף מרדושיץ","k":"אדמור מרדושיץ","dt":"תשג","b":"אדמו\"ר בראדושיץ נספה בשואה."},{"i":38113,"n":"פינקלר-בארון, חיים אשר מרדושיץ","f":"אליעזר דוד מרדושיץ","k":"אדמור מרדושיץ","bt":"תרלז","dt":"תשא - כד אדר","dp":"גיטו קילץ","b":"רב בזאלוזיץ, אדמו\"ר ברדושיץ-תרפא. חתן דודו ר מאיר מנחם מפיעטרקוב. מאחרוני בעל המופת, מעולם לא ישן במיטתו, יודע נגן. נשא ונתן עם בעל אבני נזר, המהרש\"ם, ובעל חלקת יואב."},{"i":38114,"n":"פינקלר-בארון, ישראל יוסף מרדוש","f":"אליעזר דוד מרדושיץ","k":"אדמור מרדושיץ","dt":"תרצז - כב תמוז","b":"אדמור ברדושיץ. בעל השכלה רחבה ויודע נגן."},{"i":38115,"n":"פינקלר-וינגרטן, יצחק משדליץ","f":"ישכר דב מלודז","k":"אדמור מרדושיץ בשדליץ","b":"חתן ר גרשן משדליץ (שושלת זלוטשוב). במלחה\"ע ה-I ברח לרוסיה, חזר לשדליץ וכיהן כאדמור מרדושיץ בשדליץ, עבר למזריטש-ליד בריסק. נספה בשואה."},{"i":38116,"n":"פינקלשטין, אברהם ממעלניצא","f":"יעקב מהארחוב","b":"רב במלנצא(=מעלניצע)-ווהלין-תרע."},{"i":38117,"n":"פינקלשטין, חיים מארה\"ב","k":"בעל ניצוצי סלע","bt":"תרסו","dt":"תשמב","b":"תלמיד ישיבת נובהרדוק. חתן ר ישראל פרנקפורטר. עבר לפאריס, ולפני השואה הספיק לברוח לארה\"ב, והתישב בלייקווד. פעל לטובת מוסדות התורה בארה\"ב. חיבר \"ניצוצי אבן\" ושינה שמו ל\"ניצוצי סלע\" - בשם העט \"חי בן ישר שטיין\"."},{"i":38118,"n":"פינקלשטין, יהודה אריה מלובמלא","f":"אליעזר","bt":"תקץ","b":"רב בלובמלא-ווהלין-תריח."},{"i":38119,"n":"פינקלשטין, יוסף ממישקולץ","k":"בעל צפנת פענח","b":"חתן ר מאיר אברהם מהאיו צ'אבה בעל \"פרי צדיק\". רב במישקולץ-תקף."},{"i":38120,"n":"פינקלשטין, יעקב","b":"רב בהארחוב-תר\"ל"},{"i":38121,"n":"פינקלשטין, יעקב שלמה מרדכי","b":"רב בקורוב. מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":38122,"n":"פינקלשטין, עוזר","bt":"1863","bp":"קובנא","dt":"1932","dp":"קובנא","b":"אביו היה רב מטעם באורנבורג. גורשו לתחום המושב וחזרו לקובנא. למד משפטים, חבר ב\"בונד\" גורש מקובנא. בצטרף למפלגה היהודית הדמוקרטית-1919 בליטא, נציגה בסיים הליטאי. סגן נשיא הועד הלאומי היהודי-1920. השתתף בועידת ציריך-1927 בענין הזכויות הלאומיות של המיעוט היהודי, ופרש עם טשרניחוב שבד וד. נומברג בשל עמדתה הציונית ויחסה לביה\"ס האידי. פעיל ב\"ייווא\" ותומך ברשת בתי הספר של \"קולטור ליגה\". פרסם מאמרים בעתונות היהודית בליטא."},{"i":38123,"n":"פינקלשטין, פנחס מפאלעניצא","f":"אברהם","k":"בעל פנים יפות","bt":"תרמה","dt":"תשב - ז אלול","b":"חתן ר יעקב דוד טויב בן האדמור ממודזיץ. רב בפולעניץ(=פאלעניצע)-פלך וארשא-תרסז. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":38124,"n":"פינקלשטין, שמעון יצחק מארה\"ב","f":"יהודה צבי","k":"בעל ראשית בכורי","bt":"תרכב","bp":"קובנא","dt":"תשז","b":"תלמיד ר זלמן בישיבת קובנא ונקרא בשם \"העילוי מסלובודקא\". רב בבולטימור-תרמו, סיסינטי-תרצה, סירקוז, בראנזויל-ניו יורק. נסמך מאת: ר יצחק אלחנן מקובנא, ר יעקב יוסף מניו יורק, ר מעשיל הכהן מבוריסוב. חיבר גם \"בית יצחק\" סט לואיס תרפד, \"עין שמעון\", ועוד. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג. בנו- ר אריה ליב מניו יורק."},{"i":38125,"n":"פינקרלי, זלמן","b":"רב ממשפחת הרבנים פינקרלי - מאליסנדריא דילה פאליא, וירונה, גוריציאה - כמובא ב\"ימי תמימים\"."},{"i":38126,"n":"פינקרלי, זלמן מרוויגו","b":"רב ברוויגו בזמן ר שמואל די פאס. ר משה חגיז מזכירו בספרו \"לקט הקמח\" - שסייע בידו לפרום תפירות ס\"ת שנתקנו בחול המועד - על מנת לחזור ולתקנם בהיתר."},{"i":38127,"n":"פינקרלי, חזקיה אהרן חיים מוירו","f":"רפאל נתן","bt":"תעו","dt":"תקיג - כד אייר","dp":"פדובה","b":"רב בוירונה. תלמיד הר\"ר ריקי. עבר לפדובה. נספד ע\"י ר אפרים לוצאטו ב\"בני הנעורים\". אודותיו ב\"ימי תמימים\" למוהר\"ם נאוורה. סייע ליהודי פרג לאחר גירוש-תקה, וסייע ליהודי וירונה-תקה להחלץ מצרה."},{"i":38128,"n":"פינקרלי, יואל עזריאל מוירונה","f":"נתן","b":"תלמיד ר\"ש מררי בוירונה, רב באלסנדריא דילה פאלייה-תע. תשובה ממנו ב\"פחד יצחק\" וב\"מלחמה לה'\" פסק ממנו נגד נחמיה חיון. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה. מתלמידיו - ר עמנואל ריקי."},{"i":38129,"n":"פינקרלי, מנחם נתן מוירונה","b":"רב בוירונה-תקד."},{"i":38130,"n":"פינקרלי, נתן","b":"מגדולי חכמי איטליה בליוורנו,רוויגו-ת\"ע"},{"i":38131,"n":"פינקרלי, עזריאל יואל","b":"רב באלסנדריה."},{"i":38132,"n":"פינקרלי, רפאל נתן","b":"רב בוירונה-ת\"ע"},{"i":38133,"n":"פינקרפלד, יעקב","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":38134,"n":"פינר אפרים משה","bt":"1800","dt":"ה'תרמ 1880","bk":[["כתבי יד",""],["קצור תלמוד ירושלמי ותלמוד בבלי",""]]},{"i":38135,"n":"פינשטין אברהם אשר בן אריה דוד","bt":"1870","dt":"ה'תשד 1944","bk":[["מגלת פורעניות",""]]},{"i":38136,"n":"פינשטין אריה ליב","bt":"1821","dt":"ה'תרסג 1903","bk":[["אלף המגן",""],["דברי חכמים וחידותם",""],["הגדה לליל שמורים עם באור תלפיות",""],["מגדל דויד",""],["עיר תהלה",""],["תלפיות",""]]},{"i":38137,"n":"פיס, יוסף מפיררה","b":"רב בפיררה בזמן הרמ\"ע ור\"נ טרבוט. תשובה ממנו ב\"פחד יצחק\" וכתב שחתם בבית דון יצחק אברבנאל (נכדו של השר באותו השם)."},{"i":38138,"n":"פיסארו, ראובן מפיררה","b":"מחכמי פיררה."},{"i":38139,"n":"פיסארו, שבתי אלחנן מפיררה","dt":"תקפח - חשון","b":"רב בפיררה. תלמיד ר שלמה למפרונטי. גיסו של ר אברהם ריגייו. תשובות ממנו ב\"במדבר בערבה\"."},{"i":38140,"n":"פיסו, אברהם ממכנאס","b":"מחכמי מכנאס-תקצד."},{"i":38141,"n":"פיסו, יעקב","k":"חתן האר\"י?"},{"i":38142,"n":"פיסו, יצחק מלאריסה","b":"רב בלאריסה - בדור שלאחר הגירוש."},{"i":38143,"n":"פיסו, יצחק ממונסטיר","dt":"תקנא - אחרי","b":"רב במונאסטיר, עם ר עובדיה חיון ור שבתי קמחי."},{"i":38144,"n":"פיסטינר, יהודה ליב מקולומיא","dt":"תקה - ג אייר","b":"תלמיד הבעשט. מחכמי הקלויז בברודי, ר בפיסטין, קולומייא. נספד ב\"תולדות יעקב יוסף\". מתורתו ב\"משנת חסידים\"."},{"i":38145,"n":"פיסילינג, יעקב","b":"בן דודו של ר משה וולף אויש. הקדשה ממנו לבחור שמעון אויש."},{"i":38146,"n":"פיסקאבלו, אברהם מקרומונה","f":"קלונימוס","b":"רב בקרומונה(=קרימונה?)-ש', נזכר בספרי חכמי דורו."},{"i":38147,"n":"פיסרבסקי, מיכאל אהרן","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":38148,"n":"פיעסקין, אבא מראסיין","f":"שמואל מוילנא","b":"רב בראסיין."},{"i":38149,"n":"פיעסקין, יעקב דוד מוילנא","f":"מנחם מנדל","k":"בעל תומת ישרים","bt":"תקנו","dt":"תרלה - א אד\"ב","dp":"וילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז. מחכמי וילנא ועסק במסחר. בעל בית דפוס בוילנא-תקצה. ראש ישיבת מייליס-תריז ונקראה בזמנו על שמו ישיבת ר יעקב פיעסקין. חיבר גם \"יד החזקה\" (מקור השם י\"ד - יעקב דוד - ולא כפי שנכתב ב\"דעת קדושים\" - פטרבורג תרנז, שהמחבר הוא ר אברהם זקהיים). הניח חבורים בכת\"י. בנו ר שמואל על מקומו אחריו בישיבה."},{"i":38150,"n":"פיעסקין, ישראל מחרסון","f":"שמואל מוילנא","b":"רב בחרסון. חיבר שיר בראש ספר זקנו \"תמת ישרים\". אחיו - ר אברהם אבלי יפה מראסיין."},{"i":38151,"n":"פיעסקין, שמואל מוילנא","f":"יעקב דוד מוילנא","bt":"תקעז","dt":"תרמ - יג אדר","dp":"וילנא","b":"ר\"מ בישיבת מייליס בוילנא על מקום אביו. בניו: ר ישראל מחרסון, ר אברהם אבא יפה מראסיין."},{"i":38152,"n":"פיעקורסקי, ישראל ממנדזיב ונ\"י","k":"בעל חקרי הלכות","b":"רב במאנדזיב, ניו יורק."},{"i":38153,"n":"פיערטוג, משה ממיטאוי","f":"חנוך","dt":"תרח","b":"מגיד ומו\"ץ במיטאוי."},{"i":38154,"n":"פיפאנו, אברהם משלוניקי","f":"אהרן","dt":"תרמח -כה-ח אייר","b":"רב בשלוניקי,עלה לירושלים"},{"i":38155,"n":"פיפאנו, אהרן משלוניקי","f":"חנוך פיפאנו","dt":"תרכה-ח -יד סיון","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":38156,"n":"פיפאנו, דוד משלוניקי","f":"אברהם","k":"בעל חשן האפוד","r":"אב\"ד סופיאה וראש הרבנים למדינת בולגריה","bt":"תריא-טו אד\"ב","bp":"שלוניקי","dt":"תרפה - ח כסלו","dp":"סופיה","b":"נינו של ר חנוך פיפאנו. תלמיד ר יהודה קובו. רב במאיור-שלוניקי-תרלז, ערך והוציא לאור ספרים, נאלץ לעזוב, אב\"ד סופיה-בולגריה-תרנט, ספריו נשרפו בדליקה-תרסה, רב ראשי של בולגריה-תרפ\"א, חיבר \"חושן האפוד\" על שו\"ע","bk":[["אבני האפד - שו\"ת, וחידושי דינים באבן העזר",""],["אהבת חסד - דרוש",""],["חגור האפד - חידושי דינים באבן העזר, ומזכרת הגיטין ושמות גיטין",""],["חשן האפד - שו\"ת וחידושי דינים בחו\"מ",""],["מלואים לאפד - חידושי דינים וזכרונות באבן העזר (נדפס בסוף ספר אבני האפד)",""],["מעיל האפד - על ספר החינוך",""],["נושא האפד - שו\"ת באבן העזר (נדפס בסוף ספר אבני האפד ח\"ב)",""],["שלשלת רבני שלוניק וסופיאה - כולל רשימת הרבנים ומעט מתולדותם (נדפס בסו\"ס חגור האפד)",""]]},{"i":38157,"n":"פיפאנו, חיים אליהו מקושטא","b":"רב בקושטא-תף בערך."},{"i":38158,"n":"פיפאנו, חיים חנוך משלוניקי","bt":"תצב","dt":"תקעט - א טבת","dp":"שלוניקי","b":"דיין בשלוניקי, רב בשלוניקי על מקום ר יוסף הכהן ן ארדיט באופן זמני (בגלל מחלוקת בקהלה) וחזר להיות דיין, השיב בהלכה גם לבני כת ה\"דונמה\" שפנו אליו בשאלות. בהשתדלותו הודפסו \"מטה אפרים\" לר אפרים ארדיט, ו\"אבקת רוכל\" לר יוסף קארו שאותו גם הגיה. חתם-תקסט עם ר חיים יוסף ן ארדיט ור שאלתיאל ן שאלתיאל."},{"i":38159,"n":"פיפאנו, יעקב שאול משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה. בנו ר שאול - נספה בשואה."},{"i":38160,"n":"פיפאנו, שאול משלוניקי","f":"יעקב שאול","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה."},{"i":38161,"n":"פיפאנו, שלמה משלוניקי","f":"אהרן","b":"דיין בשלוניקי. אביו של ר דוד פיפאנו מסופיה."},{"i":38162,"n":"פיפאנו, שלמה משלוניקי","b":"דיין בשלוניקי-תרג. הניח כת\"י והיו בידי בן משפחתו ר דוד - המזכירו בספריו."},{"i":38163,"n":"פיפאני, חיים","b":"מחכמי קושטא,עלה לירושלים"},{"i":38164,"n":"פיפי, שמואל משלוניקי","b":"מחכמי שלוניקי-שפ."},{"i":38165,"n":"פיפר, יהודה מקראקא","b":"מחכמי קראקא-תרפד."},{"i":38166,"n":"פיפרנו, אברהם ברוך מאיטליה","b":"סופר קהלת ליוורנו-תקץ"},{"i":38167,"n":"פיפרנו, יצחק מאזמיר","dt":"תקסה - ה שבט","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":38168,"n":"פיציגטון, דוד הלוי","k":"ר' דוד הלוי הרופא","b":"רופא מומחה בקרימונה,דיין בויניציאה-ר\"פ,רב בפירארה"},{"i":38169,"n":"פיציגטון, דוד הלוי מפיררה","f":"אליעזר הלוי","b":"רב בפיררה בזמן ר משה נמירה והרב טרבוט. שאלה ממנו ותשובה מרבני הדור - ר בינידיט ור חייא רופא ובית הדין של בולוניה - נדפסה."},{"i":38170,"n":"פיצר, חיים מסטניסלב","f":"דוד","k":"בעל מנחה חדשה","bp":"סטניסלב","b":"עבר לרדוביץ. חיבר \"מנחה חדשה\" טששרנוביץ תרפט. ?? לא באוצר ??"},{"i":38171,"n":"פיק, אהרן משאוולי","f":"דוד","k":"בעל ר צבי החבתן","bt":"1872","bp":"קיידאן","dt":"1944","dp":"שאוולי","b":"תלמיד ישיבת סלובודקה. התחבר לחוגי המשכילים בקובנא, למד רפואה בפאריס והיה רופא בדרום צרפת. חזר לליטא והתישב בשאוולי. חבר בועד הקהילה, ויו\"ר. פרסם מאמרים רבים בעניני רפואה ועוד. נספה בשואה בגיטו שאוולי. הניח כתב\"י בשם \"מגיא ההריגה\" - זכרונותיו מהגיטו."},{"i":38172,"n":"פיק, אליעזר ליפמן מלאסק","f":"יהושע","dt":"תרז - כד כסלו","dp":"לאסק","b":"דיין ומו\"צ בלאסק"},{"i":38173,"n":"פיק, מנחם אהרן מנייטרא","f":"וולף מניקלשבורג","dt":"תקצב - טו חשון","b":"תלמיד החת\"ס. רב בנייטרא-תקפא."},{"i":38174,"n":"פיק-שוואבך, יעקב דב","b":"אין פרטים"},{"i":38175,"n":"פיקארט, אברהם מצרפת","b":"חבר באסיפה היהודית צרפתית-תקף, יחד עם אברהם פיקארט, פנחס אטראט."},{"i":38176,"n":"פיקארט, מיכאל","k":"בעל חיי אברהם","b":"ר\"מ באשכנז. תלמיד ר אברהם נפתלי שייאר בעל \"תורי זהב\", ר אברהם אוירבך בעל \"נחל אשכול\". חתנו - ר נפתלי הרץ הכהן, נכדו - ר מיכאל קאהן מפולדא."},{"i":38177,"n":"פיקאשו, דוד","b":"סופרו של ה\"בית יוסף\"-לפני שפ\"ה"},{"i":38178,"n":"פיקאשו, שלמה","f":"דוד","b":"תלמיד המקובל ר יעקב צמח. אביו היה סופרו של ר יוסף קארו."},{"i":38179,"n":"פיקהולץ, דב בריש מרוזדול","f":"יצחק","bt":"תרמח","bp":"רוזדול","dt":"תשלז","dp":"קליבלנד","b":"חסיד בויאן, היגר לארה\"ב-תרף, למד תורה ועסק לפרנסתו במסחר."},{"i":38180,"n":"פיקהולץ, זושא","b":"נכד הרב מלוקטש. חתן רבו ר שלום לילינפלד מפודהייץ. רב בפודהייץ, ומראשי חסידי בלז."},{"i":38181,"n":"פיקהולץ, יהודה גרשון מרוזדול","f":"ישראל יואל","k":"בעל מחנה יהודה","bt":"תרב","bp":"רוזדול","dt":"תרעד","b":"נכד החכם צבי. תלמיד מהרי\"א מקומרנא. רב ברוזדול-תרלג, ליסעץ-תרלד. חתן אחיו ר משולם. נסמך מאת: ר יוסף שאול נתנזון מלבוב, ר יצחק איזיק מקומרנא, זקנו - ר יהודה צבי מסקאלוה. חיבר \"מחנה יהודה\" למברג תרם - ובו התקנות מפנקס ועד ד ארצות, ועוד."},{"i":38182,"n":"פיקו (פיקס), אברהם מאיטליה","f":"אליהו בן לוי","k":"בעל טעמי התגין","b":"רב ברומא, לאווינא-רנז."},{"i":38183,"n":"פיקו, יוסף מצפת","b":"מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים."},{"i":38184,"n":"פיקורסקי, ישראל יצחק ממנדזיוב","b":"רב במנדזיוב. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":38185,"n":"פיקסל, אברהם אבא מסאסרעגן","f":"דן יצחק","dt":"תרעו - יז אב","dp":"סאסרעגען","b":"תלמיד הכת\"ס. חתן ר הלל פולק מסאסרגן. רב בסאסרגן."},{"i":38186,"n":"פיקסל, בנימין זאב וולף מעיר חד","bt":"תקנב","bp":"מיאווע","dt":"תרכח - יז סיון","dp":"עיר חדש","b":"תלמיד החת\"ס, ור ברוך פרנקל-תאומים מלייפניק. חתן ר ליב. רב בעיר חדש, אבאני-תקצג - ועזב בגלל המשכילים, ממיסדי קהילת מעזא-טור וכיהן שם כרב, רב בעיר חדש. תשובה אליו ב\"חתם סופר\"."},{"i":38187,"n":"פיקרסקי ישראל יצחק","bt":"1910","dt":"ה'תשנב 1992","bk":[["אבן ישראל",""],["אוצרות השעורים",""],["חקרי הלכות",""]]},{"i":38188,"n":"פירוז - משפחה","b":"משפחת קראים מיוחסת בדמשק וארצות המזרח."},{"i":38189,"n":"פירוז, אליהו מדמשק","f":"גדליה","b":"מחכמי הקראים בדמשק-שנות ה-ת'."},{"i":38190,"n":"פירוט = שיהר-קיואי- קהלה","b":"קהלה ליד סופיה."},{"i":38191,"n":"פירט, אברהם אברל מקרולה","bp":"פירט-גרמניה","b":"תלמיד החת\"ס. מחכמי קרולה, ידידו של ר שמעון בעל \"מכתב סופר\" שישב אז בקרולה, והתיעץ עם ר אברהם בדבר קבלת רבנות מטרסדורף"},{"i":38192,"n":"פירט, אפרים מקרולה","f":"אברהם","dt":"תרעא","b":"תלמיד ר מאיר פרלס. חתן ר וולף סופר מפעסט, רב בפעסט-תרנד על מקום חותנו. פעיל באיגוד קהילות הסטאטוסקוו, וחבר בועדה שהציעה לממשלה להכיר בקהלות הללו."},{"i":38193,"n":"פירט, יחיאל ממישקולץ","dt":"תרפב","b":"דיין במישקולץ-תרס ור משה נתן בלום על מקומו אחריו."},{"i":38194,"n":"פירטו, מנחם הכהן מונציה","b":"מחכמי ונציה, מלמד ודרשן בישיבת ר יום טוב ואלהאוזן."},{"i":38195,"n":"פיריצי, בנציון רפאל הכהן מאיטל","f":"תקטז","k":"בעל פתח עינים","bp":"מנטובה","dt":"תרד","b":"רופא מחכמי ישראל באיטליה. חיבר ספרים בעברית ואיטלקית. מכתב תנחומים אליו משד\"ל על פטירת בתו."},{"i":38196,"n":"פירמון, אלעזר משלוניקי","dt":"רפה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38197,"n":"פירמון, יוסף - ב","b":"חברו של מהרש\"ך, ונזכר בשו\"ת חכמי דורו."},{"i":38198,"n":"פירמון, יוסף מפטרץ-יוון","b":"רב בשלוניקי-שמ, רב עדת הספרדים והסיציליאנים בפטרץ-יוון והיה במחלוקת עם בני העדה הרומנית, היה במחלוקת עם המהרשד\"ם משלוניקי. מתלמידיו - ר שלמה הכהן-מהרש\"ך."},{"i":38199,"n":"פירמון, יוסף משירון","bp":"שירון","dt":"שלט","dp":"פטרץ","b":"רב בשירון(=סיריס)-מקדוניה-שכ, שלוניקי, זאנטי, ליפאנטו, פטרץ, רב הכולל למוריאה. מתלמידיו: ר שלמה הכהן. בניו - ר צדיק על מקומו אחריו, ואולי גם ר יעקב מליפאנטו."},{"i":38200,"n":"פירמון, יעקב מאזמיר","b":"מגדולי חכמי אזמיר-ת\"ל"},{"i":38201,"n":"פירמון, יעקב מליפאנטו","f":"יוסף","b":"רב בליפאנטו-שנות ה-ש'."},{"i":38202,"n":"פירמון, יעקב סמוט משלוניקי","f":"שמואל","dt":"שלג - אחרי","b":"רב בק\"ק קייאנה בשלוניקי. חתם על הסכמות הקהל בשלוניקי. נספד ע\"י ר סעדיה לונגו. היה במחלוקת עם ר משה רוסו משלוניקי. ?? אולי הוא בלבול עם ר יוסף רב ה\"מוריאה\"."},{"i":38203,"n":"פירמון, צדיק מפטרץ","f":"יוסף מפטרץ","b":"רב בפטרץ על מקום אביו. תרגם ללאדינו את \"חובות הלבבות\"."},{"i":38204,"n":"פירמי, יהושע","b":"רב באיטליה. תלמיד הר\"ן טראבוט. תשובות ממנו ב\"עפר יעקב\" - בכת\"י ועמו חתומים ר מנחם שלחני ור חזקיה מנוח פורבנצאלי."},{"i":38205,"n":"פירמי, יוסף מאנקונה","b":"רב באנקונה בזמן בעל \"עפר יעקב\". היה לו מחלוקת הלכתית עם ר מהללאל הללויה מציויא נובא ופסק ביניהם ר עמנואל פראנסיסי מפיררה."},{"i":38206,"n":"פירמיניני מטריאסט","b":"רב בטריאסט-תקלז, פגש את החיד\"א שעבר שם."},{"i":38207,"n":"פירסט, אלעזר","dt":"תרמג","b":"רב בדינדיש"},{"i":38208,"n":"פירסט, אפרים מקראלי","b":"רב בקראלי-תר\"ע"},{"i":38209,"n":"פירסט, זלמן מהידלברג","f":"מאיר טאלמעסינגן","b":"רב בהידלברג-תרג."},{"i":38210,"n":"פירסט, חיים דב מטאפלטשן","dt":"כג טבת","b":"תלמיד הכת\"ס. רב בטאפלטשן. בנו ר לוי שלום אב\"ד טשוס. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":38211,"n":"פירסט, חיים מאלטונא","f":"יוסף מאלטונא","b":"סופר קהלות אה\"ו בזמן מחלוקת ר יונתן איבשיץ ור יעקב עמדין. נזכר אצל היעב\"ץ. היה מעורכי מחזור אלטונא יחד עם ר הנדל חזן. חתנו - הרופא גוקטור גרשון בר טעבלי - אבי משפחת גרשון מאה\"ו."},{"i":38212,"n":"פירסט, יוסף מאלטונא","f":"ירמיה מאלטונא","bp":"אלטונא","dt":"תצט - א אדר","b":"תלמיד ר מרדכי זיסקינד רוטנבורג מלובלין והו\"ל את שו\"ת רבו והוסיף הקדמה, ר משה רוטנבורג מאה\"ו. דיין בהורדנא, אלטונא. חיבר הקדמה ל\"שערי תורה וזמרה\" לר שלמה זלמן האנוי. אחיו - ר שלמה זלמן, בנו - ר חיים סופר קהלת אה\"ו."},{"i":38213,"n":"פירסט, ירמיה מאלטונא","dt":"תסג - כ שבט","dp":"אלטונא","b":"דיין בהמבורג-אלטונא אצל ר זלמן מירלס. אחיו: ר שלמה, ר נתנאל."},{"i":38214,"n":"פירסט, ירמיה מברלין","f":"בנדיט בן ירמיה","dt":"תקן - יח טבת","dp":"ברלין","b":"מחכמי ברלין. משה מנדלסון כתב אליו-תקלח בדבר הצורך בלימוד הלשון העברית."},{"i":38215,"n":"פירסט, ישעיה מוינה","f":"משה - מראה משה","k":"בעל חזון ישעיה","r":"רב קהל עדת ישראל - שיפשול בווינה","bt":"תריז","bp":"מאראש-וואשארהעלי","dt":"תשג - כא אד\"ב","dp":"לונדון","b":"תלמיד הכת\"ס, והשב\"ס. חתן ר שלום קוטנא מאיזנשטט, ועבר לשם. בזיוו\"ש חתן ר שמואל פלסנר מפוזנא. רב בטירנא-תרמא, עפעריעס, פרשוב-תרנה, קהל עדת ישורון (שיף שוהל) בוינה-תרנז. הגיע ללונדון-תרצח. בנו ר משה אהרן רב בוינה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["חזון ישעיהו - לקט מדברי",""]]},{"i":38216,"n":"פירסט, ישראל מהמבורג ואלטונא","b":"פרנס באה\"ו. חתניו: ר משה בן אברהם ברוידא מבומברג, ר משה רוטנבורג מאה\"ו."},{"i":38217,"n":"פירסט, לוי שלום מטשוס","f":"חיים דב מטאפלטשן","bt":"תרמח","bp":"טאפלטשן","dt":"תש..","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור אליעזר חיים דייטש מבאניהאד ור מאיר יהודה פרייא משוראן. חתן ר מרדכי אפרים פישל זוסמן סופר מטשוב. רב בטשוס-תרעד על מקום חותנו. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":38218,"n":"פירסט, מרדכי מפרשבורג","b":"ממיסדי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":38219,"n":"פירסט, משה אהרן מוינה","f":"ישעיה מוינה","bt":"תרלט","bp":"איזנשטט","dt":"תרעב - כב אב","dp":"איזנשטט","b":"תלמיד השב\"ס, וזקנו ר שלום קוטנא מאיזנשטט. רב בשטומפער-שוהל וחברת אמנות אבות בוינה."},{"i":38220,"n":"פירסט, משה ממארוש-ואשארהי","f":"ישעיה","k":"בעל מראה משה-תרצב","bt":"תקעה","bp":"וערעשוואר","dt":"תרל","b":"תלמיד ר צבי הירש הלר בעל \"טיב גיטין\". חתן ר משה נחום רוזנבוים מוואשון, בזיוו\"ש חתן גיסו ר אברהם אליהו משה כץ מפעצעל. רבה הראשון של מארוש-ואשארהי-תרי וראש ישיבה שם ור צבי אהרן ליפשיץ על מקומו אחריו, עבר לקויזנבורג-תקצה, קרלסבורג-תקצט, באויבן ישן-תרה, וערעשוואר-תרו. בנו ר ישעיה פוירסט מוינה חיבר הקדמה לספרו."},{"i":38221,"n":"פירסט, נתנאל מברלין","b":"מראשי הקהילה בברלין. חתם על כתב מינו ר יעקב יהושע לרב בברלין-תץ."},{"i":38222,"n":"פירסט, צבי הרי פינקוס","f":"ראובן","bt":"1883","bp":"בירז'","dt":"1959","b":"תלמיד ישיבת דוינסק. היגר לארה\"ב-1900. ממיסדי ועד הנוער הציוני באמריקה. חבר הנהלת הסתדרות ציוני אמריקה. מנהל קק\"ל ו\"היאס\" בארה\"ב."},{"i":38223,"n":"פירסט, שלום לוי","dt":"תשד","b":"רב בטשוז-תרע\"ד"},{"i":38224,"n":"פירסט, שמעון מוינה וטורונטו","k":"בעל שם משמעון","b":"רב בוינה, טורונטו. חיבר \"שם משמעון\" טורונטו תשם."},{"i":38225,"n":"פירפיניאן, יצחק משלוניקי","dt":"שיד","dp":"שלוניקי","b":"מחכמי שלוניקי. מוצא המשפחה מצרפת."},{"i":38226,"n":"פירפיניאן, מנחם מאזמיר","dt":"תפו - טו אב","dp":"אזמיר","b":"גביר מחכמי אזמיר."},{"i":38227,"n":"פירר, אהרן ליב","f":"שמואל מקראס","dt":"תשג","b":"חתן ר ניסן שנירר מזקליטשין ודיין בקראקא. דיין בקראקא על מקום חותנו. ר\"מ בישיבת בובוב בקראקא. נספה בשואה."},{"i":38228,"n":"פירר, בן ציון מרימנוב","f":"יוסף משה מרימנוב","bt":"תרעד","bp":"קרוסנו","dt":"תשמח","b":"חתן דודו ר יצחק זאב גולדמן-פירר מדזילברץ. רב ברימנוב על מקום אביו. ניצל מהשואה. עלה לארץ-תשח, רב ניר-גלים-תשיז, ור\"מ בישיבת כרם ביבנה. חיבר מאמרים רבים וספרים בעברית ובאידיש ובהם \"חמדת ציון\" קראקא תרצו. מעורכי \"תלפיות\" - טרנוב תרצח."},{"i":38229,"n":"פירר, בנימין מאסטרוזנץ","f":"דניאל","bt":"תר","bp":"אוסטרו-הונגריה","b":"נסמך מאת: ר דוד צבי מדובנא, ר שאול מליק. רב באסטרוזנץ-תרל."},{"i":38230,"n":"פירר, דוד מלנצהוט","f":"שמואל מקראס","bt":"תרנה","dt":"תשב","b":"חתן ר אלעזר שפירא מלנצהוט. רב בלנצהוט לצד חותנו ועל כסאו אחריו. נספה בשואה."},{"i":38231,"n":"פירר, יהושע","b":"נכד אחיו של ר אשר זליג אבי ר שמואל מקראס. עבר לקנדה וכיהן כראש כולל בובוב בטורונטו."},{"i":38232,"n":"פירר, יוסף משה מרימנוב","f":"שמואל מקראס","bt":"תרמט","dt":"תרצה","b":"רב ברימנוב-תרעח. בנו ר בן ציון על מקומו אחריו."},{"i":38233,"n":"פירר, יעקב ישראל מזלוזיץ","f":"שמואל מקראס","k":"בעל חבור על השוע","dt":"תש..","b":"רב בזלוביץ. הניח חיבור על שו\"ע בסגנון הפרי מגדים. נספה בשואה."},{"i":38234,"n":"פירר, מנחם מנדל מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":38235,"n":"פירר, שמואל מקרסני","f":"אשר זליג","k":"בעל הר שפר","bt":"תרכה-ח","bp":"סנקובה (ליד גורליץ)","dt":"תשג","b":"נכד ר יצחק חריף מסמבור. חסיד צאנז ובובוב. חתן ראי\"ה גולדמן מצ'כיה. רב במילובקה, ראש ישיבה בקראקא. רב בקרוסנו(=קראס)-תרסח. נודע כדיין מומחה בדיני ממונות. נספה בשואה על קדוש השם. חיבר \"הר שפר\" ברדיוב תרפג. כל 6 בניו וכל 5 חתניו כיהנו כרבנים. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אחיאסף\" - סטריזוב תרפט, \"אסיפת גדולים\", \"הירדן\" - רישא תרץ, \"הלבנון\" - גורליץ תרפח, \"תלפיות\" - טרנוב תרצח."},{"i":38236,"n":"פירר-גולדמן, יצחק זאב מישליסק","f":"שמואל מקראס","bt":"תרן","bp":"מילובקה","dt":"תשב","b":"רב בישליסק-תרעח, מדזילברץ-תרפג. שינה את שמו לגולדמן (שם אמו - כדי לקבל אזרחות צ'כית). חתן ר אליעזר ליבר מונד ממיקוליב. נספה בשואה. סידר ספר זקנו ר יצחק חריף - האלף לך שלמה."},{"i":38237,"n":"פיררה דיליאון, גבריאל מליוורנו","f":"מיכאל הרופא מליוורנו","b":"גביר מחכמי ליוורנו, תלמיד החיד\"א - שהתגורר בבית אביו ולימד את בניו."},{"i":38238,"n":"פיררה מינדיס, אברהם מארה\"ב","f":"יצחק","dt":"תרנא","b":"רב בברמינגהם-אנגליה, דיין ודרשן בלונדון, ניו פורט-ארה\"ב. תרגם את סידור התפלה לאנגלית. בנו - ד\"ר חיים מינדיס."},{"i":38239,"n":"פיררה, אברהם הספרדי","b":"חיבר בספרדית שני ספרים על השגחת השם - אמשטרדם. (מופיע אצל די רוסי)."},{"i":38240,"n":"פיררה, אברהם ישראל מאמשטרדם","k":"בעל דרך בטוחה","bp":"מדריד","dt":"תנט","dp":"אמשטרדם","b":"מאנוסי ספרד, עבר לאמשטרדם וחזר ליהדות, פרנס הקהלה, נתפס לשבתאות, יסד בחברון בימ\"ד בשם \"חסד לאברהם\", ורצה להתישב בחברון, אך נפטר בדרכו. חיבר \"דרך בטוחה\"."},{"i":38241,"n":"פיררה, אברהם מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":38242,"n":"פיררה, אברהם מקושטא","f":"אליהו","b":"מגיה בדפוס אברהם פרנקו בקושטא-שנות ה-ת'."},{"i":38243,"n":"פיררה, אהרן חיים מירושלים","dt":"תרפג","dp":"אלכסנדריה (נא אמון)","b":"מחכמי ירושלים, שליח לערי תורכיה בשנת תרסח, כתב ב\"המאסף\" שנה א לז ושנה ב לג ועוד. נפטר במהלך שליחותו"},{"i":38244,"n":"פיררה, אהרן רפאל חיים משה אליה","f":"יצחק יהודה-אפר יצחק","k":"בעל תולדות אהרן ומשה","bp":"שלוניקי","dt":"תרמח","dp":"ירושלים","b":"מכונה ארח\"ם (ר\"ת שמו). מחכמי שלוניקי, עלה לירושלים-תרח, מקובל מחכמי \"בית אל\", בשנת תרלב חתם על כתב שליחות ר אברהם יוסף בן שלמה. חיבר ספר \"תולדות אהרן ומשה ואפר יצחק\" ירושלים תרל, \"דבר ה מירושלים\" ירושלים תרלג, ועוד. כתב קמיעות וקונטרסים בלאדינו. נהג לחתום בסוף דבריו - \"דברי אמת ושלום\". בנו - ר יצחק משה שעלה עם אביו לירושלים."},{"i":38245,"n":"פיררה, אליהו מאיטליה וצפת","b":"מחכמי איטליה-ר', ביקר בארץ-קצח וכתב על כך במכתב שנדפס ב\"דברי חכמים\"-תריג ובו מספר שבדרכם טבעו בנו ונכדו בים והוא ניצל בנס והגיע לצפת, ולימד תורה ונתבקש לכהן כרב בצפת. כמה ממכתביו נדפסו ב\"קול מבשר\" לר יצחק עקריש."},{"i":38246,"n":"פיררה, הנרי משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":38247,"n":"פיררה, יעקב מהולנד","dp":"האג","b":"רב קהלת הפורטוגזים בהולנד כ-43 שנה."},{"i":38248,"n":"פיררה, יצחק איזיק מפאריס","bt":"1806","bp":"בורדו-צרפת","dt":"תרם - ד אב","b":"נכד ר יעקב רודריגס-פיררה. כלכלן ומדינאי בפריס, עורך כתב העת \"הכדור\" בפריס. הקים חברות רכבת, בנקים ועוד. אחיו - עמיל."},{"i":38249,"n":"פיררה, יצחק מצרפת","b":"ביקר בארץ-תרלח ורכש את קברי המלכים יחד עם אחיו עמיאל - בהמלצת החוקר הצרפתי פ. די סולצי."},{"i":38250,"n":"פיררה, יצחק משה - אפ\"ר יצחק","f":"אהרן רפאל חיים משה","k":"בעל מעיל קודש","dt":"תרעז - ו שבט","dp":"ירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים, דרשן בישיבת בעלי בתים, וכותב קמיעות. חיבר ספרי מוסר בלדינו וכן \"מעיל קודש ובגדי ישע\" ירושלים תרמח."},{"i":38251,"n":"פיררה, ישראל יעקב מאיטליה","b":"גביר מחכמי ליוורנו, עלה לירושלים, יסד בימ\"ד בירושלים-תנו בהשתדלות ר חיים די סילוה, בשם \"כנסת ישראל\" ובראשו ר חיים ן עטר, ולפי רוזניס שם הישיבה \"בית יעקב\"."},{"i":38252,"n":"פיררה, משה","b":"מצאצאי ר ישראל יעקב שיסד את ישיבת בית יעקב פיררה בירושלים. תומך בישיבה על מקום זקנו-תקמח בערך."},{"i":38253,"n":"פיררה, משה לופז מוינה ולונדון","k":"דון דייגו די אגילאר","bt":"תס","dt":"תקכה","dp":"לונדון","b":"בן למשפחת אנוסים שחזר ליהדות, הגיע דרך לונדון ואמשטרדם לוינה, ועמד שם בראש הקהלה הספרדית, מקורב לקיסר קרלוס השישי וקיבל תואר בארון. פעל רבות למען היהודים בזמן הקיסרית מריה תרזה."},{"i":38254,"n":"פיררה, משה מבוסניה - הנכד","f":"אברהם","dt":"תרמב - כ תמוז","dp":"ירושלים","b":"נכד ר משה מסרייבו וחברון. מחכמי טראבניק-בוסניה, עלה לירושלים-תרלט עם בנו מרדכי."},{"i":38255,"n":"פיררה, משה מחברון","f":"אברהם","dt":"תרכד-ה - אייר","dp":"חברון","b":"מחכמי סרייבו, חברו של ר אליעזר פאפו המזכירו בספרו \"פלא יועץ\". עלה לחברון-תריא, רב ראשי בחברון-תריג. היה מעורב במחלוקת בין הנהלת הכוללות לר שלום בן עבדאלה בענין כספי החלוקה. בניו - בכור אברהם, שלמה, מרדכי. חתנו - ר סלימאן מני."},{"i":38256,"n":"פיררה, משה מטימישואר","f":"יהודה","dt":"תרנח - יג אייר","dp":"טימישואר","b":"רב הקהלה הספרדית בטימישואר-תרלב."},{"i":38257,"n":"פיררה, משה מירושלים ובוסניה","f":"מרדכי","bt":"תרמד","bp":"ירושלים","dt":"תרצב - כט שבט","dp":"סרייבו","b":"עבר מירושלים לטראבניק-בוסניה, חתן דודו והתישב שם, ש\"ץ, שו\"ב, ודיין בטראבניק, עבר לסרייבו וכיהן כמורה ודיין."},{"i":38258,"n":"פיררה, שמואל ברוך מסרייבו","b":"דיין בסרייבו אצל ר יצחק צבי אשכנזי-תן בערך."},{"i":38259,"n":"פירשטין, אהרן מרבקא","f":"ישראל מרדכי","bt":"תרפב","bp":"פודגורזע","dp":"מחנה פלשוב","b":"שו\"ב ברבקא ותלמיד ישיבת בובוב. נספה בשואה."},{"i":38260,"n":"פירשטנטל, רפאל מברסלוי","k":"בעל אבל יחיד","b":"תלמיד ר עקיבא איגר. חיבר \"אבל יחיד\" - ברסלוי תקצח - ובו הספד על רבו."},{"i":38261,"n":"פיש, אביגדור דניאל","f":"אליעזר ממאטע סאלקע","b":"חתן האדמור מטאש."},{"i":38262,"n":"פיש, אהרן ישעיה מהאדאס","f":"צבי אביגדור","k":"אדמור מהאדאס-קדושת א","bt":"תריט","dt":"תרפח - ו טבת","b":"נכד ר יעקב מחסידי יצחק איזיק מקאליב (אשוואר?). תלמיד ר אליעזר צבי מקומרנא. רב ואדמור בהאדאס. חיבר \"קדושת אהרן\", \"נר אהרן\"."},{"i":38263,"n":"פיש, אליעזר מביקסאד","f":"משה מכפר מאסיף","k":"אדמור מביקסאד","bt":"תרם","bp":"כפר מאסיף-מארמארוש","dt":"תשד - כ סיון","dp":"אושוויץ","b":"מצאצאי ר חיים צאנזר ראש חכמי הקלויז בברודי. תלמיד ר חנניה יו\"ט ליפא מסיגט, תלמיד ישיבת ר מרדכי יהודה לעוו מאינטרדם. חתן ר משה זאב בן ישכר בר קאהן מערדא-סנזשארץ. התישב בסיגט ולמד עם האחים העילויים ר חיים צבי ור יואל טיטלבוים בני \"קדושת יו\"ט\". רב בנירבוגדאן-תרסה-תרסה, רב ואדמור בכפר ביקסאד-ליד סטמר, עבר לסטמר וכיהן כאדמור מביקסאד והקים ישיבה. נספה בשואה. חיבר \"שם אליעזר\" ניו יורק תשיד. בנו ר חיים משה ממונשטיר נספה בשואה."},{"i":38264,"n":"פיש, אליעזר מטיסא סלקא","f":"יחזקיה מסאלקא","k":"בעל חיבור על הש\"ס","b":"נכד ר אהרן ישעיה פיש בעל קדושת אהרן מהאדאס. חתן ר שמואל דוד יונגריז מיארמוט. רב בקאדשארד(=קאטשארד)-גליל סאלקא, רב וראש ישיבה בסאלקא, על מקום אבותיו ר יחזקיה פיש. עבר לניו יורק. בנו ר אביגדור דניאל פיש."},{"i":38265,"n":"פיש, בן ציון מבורשה","f":"משה גרשון","k":"בעל געזונדהייטס-תרפח","bt":"תרו","bp":"בורשה","dt":"תשד","dp":"אושוויץ","b":"מצאצאי ר צבי בן משה אברהם רבה הראשון של סיגט. גביר מחכמי בורשה, התקרב לציונות והתכתב עם הרצל. כתב בעתונות העברית - בעיקר ב\"הצפירה\". מחותנו של ר שלמה ליב טאבאק מסיגט בעל \"ערך שי\", ושל ר משה יוחנן שנפלד ממיהאיפאלווא. שלט בשפות רבות. תכנן לעלות לארץ-תרצט אולם כבר לא הספיק. התגורר אצל בנו ר יהושע במארגיטא. נספה בשואה. בגיל 98. חיבר בעילום שמו \"דיא געזונדרהייטס\" שמאלוי תרפח. נכדו יצחק מנחם פיש הו\"ל \"דברי חכמים\" תל אביב תשם, ועוד. ?? לא באוצר ??"},{"i":38266,"n":"פיש, הנריק מלובוש-באראני","b":"רבה האחרון של לובוש-באראני. ניצל מהשואה, ואחריה רב בבודפשט."},{"i":38267,"n":"פיש, זאב וולף מוולשטיין","b":"חתן ר עקיבא איגר מפוזנן מוולשטין. נזכר בשו\"ת ר עקיבא איגר, וחדושים ממנו בהגהות רע\"א לשו\"ע. בנו - ר יהושע."},{"i":38268,"n":"פיש, חיים משה ממונשטיר וסטמר","f":"אליעזר-האדמור מביקסד","k":"בעל בני משה-תשיד","bt":"תרעח","dt":"תשד - כ סיון","dp":"אושוויץ","b":"בן האדמור מביקסאד. תלמיד ישיבת אביו בסטמר. מחכמי סטמר. חתן ר בנימין אב שוורץ ממאנאשטור-ליד סטמר, כיהן כרב במאנאשטור-תש. נספה בשואה."},{"i":38269,"n":"פיש, יהושע","f":"זאב וולף מוולשטיין","b":"נכד(אבי אמו) ר עקיבא איגר מפוזנן."},{"i":38270,"n":"פיש, יואל אשר זליג מסטריקוב","k":"אדמור מקוצק סטריקוב","b":"נכד-בן בתו - ר חיים ישראל מורגנשטרן האדמור מקוצק-פילוב. רב בגרובוב, סטריקוב. אדמור בקוצק-תרצט על מקום דודו ר יוסף מורגנשטרן מקוצק. נספה בשואה."},{"i":38271,"n":"פיש, יוסף אריה ליב מכפר האדאד","f":"צבי אלימלך ממאסיף","k":"בעל דברי יוסף-תשב","bt":"תרלה","bp":"כפר מאסיף","dt":"תשד","b":"מצאצאי ר חיים צאנזר ראש חכמי הקלויז בברודי. תלמיד בעל \"קדושת יו\"ט\" בסיגט. חתן ר יוזפא יואל מלאפוש, רב בכפר האדאד-תרנז ושל הכפר הסמוך שאמשון-מחוז סילאג'. נספה בשואה. דודו של האדמור ר אליעזר פיש מביקסאד."},{"i":38272,"n":"פיש, יוסף הלוי מסטריקוב","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":38273,"n":"פיש, יוסף מרוזנברג","f":"יהודה ליב","k":"בעל מטה יוסף","bt":"תקע","bp":"רוזנברג","dt":"תרן","dp":"אלשא-קובין","b":"תלמיד החת\"ס, ודודו ר יחזקאל סגל מטרנטשין. חתן ר יוסף סגל מליפטא. רב ברוזנברג. בהקדמת ספרו מספר על משפחתו ועל לימודיו בישיבה."},{"i":38274,"n":"פיש, יחזקיה מהאדאס","f":"אהרן ישעיה מהאדאס","k":"אדמור מהאדאס טיסא-סל","bt":"תרמה","dt":"תשד - כח אייר","dp":"אושוויץ","b":"חתן ר ישראל שמעון מאיר ולדמן מבורשא. רב בהאדאס וחתנו - ר ברוך אברהם ריזל ר\"מ ורב לצדו (או על מקומו), אדמו\"ר בטיסא-סלקא. נספה בשואה. חיבר \"לב יחזקיה\". בניו: ר יעקב-נפטר בחיי אביו, ר צבי אביגדור מניר-אדאני, ר אליעזר מקאטשארד, ר ברוך אברהם (ובאמת היה חתנו).","bk":[["לב יחזקיה – הגדה של פסח",""]]},{"i":38275,"n":"פיש, יחיאל מיכל מדינוב","f":"יצחק מפלשטין","b":"רב בדינוב. בניו ר יהושע השל ור יצחק על מקומו אחריו."},{"i":38276,"n":"פיש, יעקב מקאליב","b":"רב בקאליב. נכדו - ר צבי נאפקער, ונכדו גם ר משה יוסף מאונגוואר."},{"i":38277,"n":"פיש, יצחק מפלשטין","bt":"תק","dt":"תקעו","b":"אבי המשפחה. נכד הט\"ז. רב בפלשטין."},{"i":38278,"n":"פיש, ישראל מגרוסורדין","b":"מחכמי גרוסורדין."},{"i":38279,"n":"פיש, נחום מאיר הלוי מחנטשין","b":"רב בחאנטשין(=חנטשין)-תר\"מ"},{"i":38280,"n":"פיש, נחום צבי מביקסאד","f":"אליעזר מביקסאד","k":"אדמור מביקסאד ארה\"ב","b":"ניצל מהשואה ואחריה אדמור מביקסאד בארה\"ב."},{"i":38281,"n":"פיש, נפתלי צבי מדינוב","f":"יצחק מדינוב","bt":"תרא","bp":"דינוב","dt":"תרעג","b":"רב בדינוב, מלמד בביתו של ר אלעזר שפירא השני מלנצהוט. חתן ר אברהם הלוי באל. סופר קרוביו - אדמורי דינוב כ-50 שנה."},{"i":38282,"n":"פיש, צבי אביגדור מאדאני","f":"חזקיה פיש","dt":"תשד","b":"רב באדאני"},{"i":38283,"n":"פישבין, מנחם מדומברובה","b":"מחכמי דומברובה - תשובה אליו בדובב מישרים."},{"i":38284,"n":"פישהוף, יוסף דב מפרשבורג","b":"חתן ר משה גולדשטין מקאשוי."},{"i":38285,"n":"פישהוף, ישעיה מעיר חדש","b":"דיין בעיר חדש-תקף."},{"i":38286,"n":"פישהוף, משלם זלמן מוינה","b":"גביר בווינה-שנת ת'"},{"i":38287,"n":"פישהוף, צבי","dt":"תשג","b":"רב בועד הרבנים בלודז"},{"i":38288,"n":"פישהוף, שלמה מסעליש","f":"יוסף דב מפרשבורג","bt":"תרסא","bp":"פרשבורג","dt":"תשמז - ז סיון","b":"תלמיד הדעת סופר."},{"i":38289,"n":"פישהוף-אוירבך, ב' וו'","f":"משלם זלמן פישהוף","dt":"תסז","b":"מנהיג בווינה,בגירוש ווינה עבר לנילסבורג-ת\"ל"},{"i":38290,"n":"פישו, אברהם משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38291,"n":"פישואה, שמואל משלוניקי","dt":"שפו - יח ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי, טבע בים."},{"i":38292,"n":"פישוהם, יעקב משלוניקי - א","dt":"תלב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38293,"n":"פישוהם, יעקב משלוניקי - ב","f":"שמואל","dt":"תק","dp":"שלוניקי","b":"גביר בשלוניקי, ותרם לצדקה והכנסת כלה."},{"i":38294,"n":"פישי, יהודה משלוניקי.","k":"איל רב דיל פישי","dt":"תלח - יד תמוז","b":"חתן ר ברוך אנגל משלוניקי. רב מובהק בשלוניקי, ורבים השתטחו על קברו."},{"i":38295,"n":"פישי, יעקב משלוניקי","dt":"תמב - לפני","dp":"שלוניקי","b":"רב בשלוניקי. אחיו של ר יהודה."},{"i":38296,"n":"פישי, יצחק מפאס","dt":"של - בערך","b":"רב בפאס. מתורתו ב\"מראה עינים\" לר\"א בהלול."},{"i":38297,"n":"פישל מאיר מלאסק","b":"דיין בלאסק אצל ר דוד דב מייזלש, רב בשאדעק."},{"i":38298,"n":"פישל מבייאה","b":"רב בבאייה על מקום ר מיכל שפיץ - אחרי תקך ור יוסף בן מרדכי על מקומו אחריו-תקל."},{"i":38299,"n":"פישל מבריסק","b":"רב בבריסק. חיבר הגהות על הטור. נזכר ב\"פרישה\"."},{"i":38300,"n":"פישל מזסלב","f":"משה","b":"עלה לטבריה בשנת תקן, היה מראשי קהילת החסידים, בשליחות באירופה ובשנת תקנו היה בקוריץ והדפיס \"עין יעקב\", כשחזר עבר לצפת."},{"i":38301,"n":"פישל מלובלין","f":"משה","b":"רב בלובלין. נזכר בקונטרס הזכרת נשמות \"הרב המאה\"ג מוהר' פישל\""},{"i":38302,"n":"פישל ממאקווא","dt":"תרמא - כא שבט","b":"רב במאקאווי"},{"i":38303,"n":"פישל מפודקמין וטבריה","b":"נזכר באגרת-תקמו."},{"i":38304,"n":"פישל מפרבוזנא ורומניה","f":"משה","b":"רב בפראבוזנא,עבר לרומניה"},{"i":38305,"n":"פישל מקולומיאה","f":"משלם מקולומיאה","b":"רב בקולומיאה על מקום אביו. זקנו של ר משלם איגרא מטיסמניץ."},{"i":38306,"n":"פישל מקונסקוולא","f":"אברהם אביש מקונסקוול","b":"רב בקונסקוולא על מקום אביו."},{"i":38307,"n":"פישל מקראקא","k":"חתן המהר\"ל מפרג","dt":"שעה - ו כסלו","b":"רב בקראקא"},{"i":38308,"n":"פישל משנדובה","b":"רב בשאנדובה-תק\"פ"},{"i":38309,"n":"פישל, אברהם","f":"צבי פישל","b":"רב בלבוב מנהיג דד\"א"},{"i":38310,"n":"פישל, אברהם ירוחם מקולקוב","k":"בעל פרי הארץ","b":"רב בקולקוב-תק\"ל,עלה לצפת"},{"i":38311,"n":"פישל, חנוך הנדיל מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":38312,"n":"פישל, ישראל אהרן הרי","f":"נחמן","bt":"1865","bp":"מאראטש-ליטא","dt":"1948","dp":"ירושלים","b":"היגר לארה\"ב. עסקן ציבור ונדבן. הקים בנין לביה\"ס העברי במאראטש - עיירת הולדתו. גזבר \"ועד העזרה המרכזי\". בנה בירושלים את \"בית הרב\" ולידו ביכ\"נ עבור הרב קוק. תרם לישיבה אוניברסיטה בניו יורק, הקים את קרן הרי פישל ומכספה הוקם מכון הרי פישל."},{"i":38313,"n":"פישל, מיכאל מפאקש","f":"יוסף אליהו פישל מפקש","b":"תלמיד הכת\"ס. מחכמי פאקש. גיסו של ר יחיאל מיכל אויש מפאקש וירושלים."},{"i":38314,"n":"פישל, שלום דב מוערפעלט","f":"מיכאל מפאקש","dt":"תרעח - כט אלול","dp":"וערפעלט","b":"תלמיד הדעת סופר, ור יוסף ליב סופר מפאקש. חתן ר משה טננבוים מוערפעלט, ועבר לשם. רב בוערפעלט-תרעו על מקום חותנו, ר יוסף אשר פולק רב על מקומו אחריו (לאחר שנשא את אלמנתו)."},{"i":38315,"n":"פישלס, ליב מפרג","f":"מהר\"ם","b":"מחכמי פרג"},{"i":38316,"n":"פישלס-בומסלא, מאיר מפרג","bt":"תסג","bp":"בומסלא-ליד פרג","dt":"תקכט - יז כסלו","b":"תלמיד ר יונתן איבשיץ, ר שמואל קרקובר. עשיר, מגדולי דורו, החזיק וכיהן כראש ישיבה בפרג כ-40 שנה - בזמן ה\"נודע ביהודה\". מתלמידיו: ר יעקב גינצבורג בעל \"זרע יעקב\". רבים מכתביו נשרפו בשריפה בפרג-תקיד. בנו - ר ליב. באוצר תאריך פטירתו - תקלז.","bk":[["הגהות מהר\"ם פישלס",""]]},{"i":38317,"n":"פישלע, ישראל חיים","b":"רב בנאדאש-תר\"כ"},{"i":38318,"n":"פישלר, אליעזר יצחק","b":"גבאי האדמו\"ר מנחם מנדל הגר מאויבר-וישיווא, מכתב ממנו-תרצז."},{"i":38319,"n":"פישלר, יחיאל מיכל מפרימישלן","f":"חיים צבי נכד הט\"ז","k":"בעל חסדי אבות","bt":"תקצב","bp":"ברודשין","dt":"תרנה","b":"תלמיד ר מאיר מפרימישלן. מחכמי פרימישלן וחתם ממנה על הסכמות (\"תפארת למשה\" תרכג). חיבר \"חסדי אבות\" למברג תרמא, ועוד."},{"i":38320,"n":"פישלש, ישכר בר","f":"שלמה זלמן מקראקא","dt":"תקצא","b":"דיין בקראקא."},{"i":38321,"n":"פישמן גרשון חנוך הניך","bt":"1880","dt":"ה'תשכה 1965","bk":[["ספיקא דרבנן",""],["שמחת החג",""]]},{"i":38322,"n":"פישמן, גרשון חנוך מרוטקי והרצל","k":"בעל פרי החג","bt":"תרס","dt":"תשכה-ו","b":"רב ברודקי(=רוטקי)-ליטא, עלה לארץ וכיהן כרב בהרצליה-תרצז. חיבר גם \"שמחת החג\", \"ספיקא דרבנן\", ועוד."},{"i":38323,"n":"פישמן, דוד","bt":"תריב","b":"מו\"צ בטבריא-תר\"ע"},{"i":38324,"n":"פישמן, חיים שמואל מבאלטא","f":"קלמן יונה","bt":"תרלז","b":"רב בבאלטא-פודוליה-תרסב."},{"i":38325,"n":"פישמן, חנוך הניך","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":38326,"n":"פישמן, חנוך מרוטקי-קוסקי","k":"בעל שמחת החג","bt":"תרס","dt":"תשכו","b":"חתן ר אליהו דושניצר. רב ברוטקי-קוסקי-פלך לומז'ה, עלה לארץ-תרצח וכיהן כרב בהרצליה."},{"i":38327,"n":"פישמן, יוסף חיים מטעלעגד","f":"שרגא פייש מפרשבורג","bt":"תרכו","bp":"פרשבורג","dt":"תרפו - יב שבט","b":"תלמיד ר יוסף משה אונגר מפישטיאן, ובעל \"ערוגת הבשם\" בהומנא, וישיבת ר משה הרש פוקס בגרוסורדין - והיה תלמידו המובהק. חתן ר עמרם בלום מבערטי-אויפלו בעל \"בית שערים\", רב בכפר טלגד-תרנג במינוי רבו כ-33 שנה. מתורתו בספר אביו \"אור שרגא\"."},{"i":38328,"n":"פישמן, יחזקאל משה מקוזנצי","k":"בעל דבר שלום ואמת","b":"רב בית כנסת בקאזינצי-1836 וניסה להכניס חדושים בקהלתו - היה מחלוקת כנגדו והותקף בכתב ובע\"פ, והשיב למבקריו ב\"דבר שלום ואמת\"-תרכד."},{"i":38329,"n":"פישמן, יעקב הרש","k":"בעל פארוואגלטע"},{"i":38330,"n":"פישמן, מנחם מנדל מיאשון","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":38331,"n":"פישמן, פייש מפרשבורג","f":"יחזקאל מישקולצר","bt":"תקפה","bp":"בוסקוביץ","b":"תלמיד ישיבת ר חיים פולאק בטרביטש. עבר עם אביו לשאפפא ולמישקולץ. רב בסיקסוי ונתפרסם כדרשן ונואם, רב בקלויזנבורג, דרשן בפרשבורג-תרכג. היה ירא שמים אבל בגלל שדרש בגרמנית היה מחלוקת כנגדו מצד ר הלל ליכטנשטין מקולומיא וחתנו ר עקיבא יוסף שלזינגר שאף הדפיסו חוברות כנגדו \"אל העדרים\". בעקבות המחלוקת החליט ר פייש - למרות שהקהל קבלו כדרשן בחסד - להפסיק את דרשותיו עד שהכת\"ס דרש ממנו להמשיך. נבחר כאחד משלושת נציגי פרשבורג לקונגרס יהודי הונגריה בפעשט."},{"i":38332,"n":"פישמן, שמעון מארה\"ב","bt":"1878","bp":"שקודויל-ליטא","b":"היגר לארה\"ב, והתישב בסידני-נברסקה, והיה מהראשונים לגדל שם חיטה, והראשון שיצא חיטה משם. ראש העיר בסידני, עבר לקולורדו ועסק בחקלאות. נבחר לסנטור-1932."},{"i":38333,"n":"פישמן, שמעון מבעטשקרעק","f":"יחזקאל משה ליפשיץ","b":"רב בבעטשקערעק-תר\"ך"},{"i":38334,"n":"פישמן, שרגא פייש מפרשבורג","f":"יחזקאל משה ממישקולץ","k":"בעל אור שרגא-תשיט","bt":"תקפה","bp":"מיסקוביץ-בוהמיה","dt":"תרמא - טז אייר","b":"תלמיד ר אליעזר שטראסר מנוואמעסטא (=עיר חדש). עבר אל חותנו בג'נגש-הונגריה, רב בסיקס-תרי, קלויזנבורג-תרכא, הגיע לבקשת הכת\"ס לכהן כדרשן בפרשבורג-תרכג - כדי לנסות לעצור את מגמת הרפורמה וההתבוללות. נחשב לאחד מגדולי הדרשנים. בנו ר יוסף חיים מטעלענד, חתניו - ר יהודה דייטש ממישקולץ, ר משה שמואל שטרן מסערענטש ור יהודה ליב פרידמן מפרשבורג. נכדו ר מאיר פישמן הו\"ל את ספר זקנו \"אור שרגא\" - תל אביב."},{"i":38335,"n":"פישמן-מימון, אברהם אלימלך","f":"מרדכי הכהן מסטנוב","bt":"תריג","bp":"הוסיאטין","b":"אמו התיחסה לרמב\"ם ולכן שינה שמו למימון. רב בהוסיאטין (של קהילת המתנגדים). נכדו - ר יהודה ליב מנהיג המזרחי בארץ ישראל."},{"i":38336,"n":"פישמן-מימון, יהודה ליב","f":"אברהם אלימלך","k":"בעל הנותן בים דרך","bt":"תרלו","bp":"מרקולשטי","dt":"תשכה - ט תמוז","b":"שינה שמו למימון בגלל מסורת המשפחה שהם מצאצאי הרמב\"ם. נכד ר מרדכי הכהן מסאטנוב. רב במרקולשטי-תרס, אנגעני(=אונגעני)-בסרביה-תרסה, עלה לירושלים-תרעב, מראשי \"המזרחי\", שר הדתות-תשח. חיבר גם \"שרי המאה\". פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח. הו\"ל \"היונה\" - אודסה תרסז, \"השנה\" - תרסז, \"סיני\" - ירושלים תרצז. סייע בעריכת \"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה.","bk":[["ברכת הארץ (נדפס בסוף קיצור שלחן ערוך בהוצאת מוסד הרב קוק)",""],["הנותן בים דרך - ויכוח בין חריף ובקי",""],["הציונות הדתית בהתפתחותה",""],["למען ציון לא אחשה - זכרונות של",""],["מדי חודש בחדשו",""],["מעשים על עשרת הדברות \\ הגדה של שבועות",""],["שרי המאה - ביוגרפיה",""]]},{"i":38337,"n":"פישקרול, אברהם מאיטליה","b":"תשובה ממנו ב\"נחלת יעקב\" למוהר\"י אלפרון - שנה. שיר ממנו ב\"מנחה בלולה\" לר מנחם רפפורט."},{"i":38338,"n":"פישר, אהרן מאיזנשטט","f":"שמשון","bt":"תקפה","dt":"תרמט - כב ניסן","dp":"איזנשטט","b":"תלמיד החת\"ס. חתן ר בנימין זאב וולף אויסטרליץ מאיזנשטט, והתגורר שם.בנו - ר שלמה פישר - רב בקרלסבורג."},{"i":38339,"n":"פישר, אהרן מירושלים","f":"שלמה מקרלסבורג","bt":"תרנו","dt":"תשא","b":"עלה לירושלים. מקובל, תלמיד הרב אלפנדרי - \"הסבא קדישא\". מו\"ל ספרי אביו. בניו - ר ישראל יעקב רב\"ד בירושלים, ר שלמה יהונתן יהודה ראש ישיבת איתרי, ר אליעזר משה ור מאיר צבי רבנים בירושלים."},{"i":38340,"n":"פישר, אליעזר מפרשבורג","f":"משה טוביה מפרשבורג","b":"מראשי חברת \"אהבת ציון\" בפרשבורג."},{"i":38341,"n":"פישר, אפרים פישל מפאטאק","f":"עמרם מיינק","bt":"תרכח","b":"חתן דודו ר צבי פישר מווינערן. רב בווינרן-תרנט על מקום חותנו, שארוש-פאטאק. חיבר מאמרים בכתבי עת. תרגם להונגרית את \"אגרות צפון\" לרש\"ר הירש."},{"i":38342,"n":"פישר, בנימין זאב מבודפשט","f":"חיים מגירבא","bp":"גירבא-פינצעהל","dt":"תשל - ח תשרי","dp":"ירושלים","b":"תלמיד הדעת סופר, ור אלכסנדר שטינברג מקאמאראן. חתן ר דוד גולדשטין מבודפשט ועבר לשם, רב בבודפשט ואב\"ד גירבא-פינצעהעל-תרצו. ניצל מהשואה ואחריה רב בבודפשט, מישקולץ-תשז, עלה לירושלים וכיהן כרב בגבעת שאול."},{"i":38343,"n":"פישר, בצלאל","f":"צבי הירש פישר","b":"רב בפאלאנקא"},{"i":38344,"n":"פישר, בצלאל מטרנטשין","b":"תלמיד השב\"ס, חתן ר אברהם זינגר מוארפאלטא. רב בטרנטשין."},{"i":38345,"n":"פישר, ברוך מפרג","b":"תלמיד ר פנחס ליב (פריידיגר) מאויבן. נסמך מאת ר שלמה יהודה רפפורט מפרג, ר ליב גלוגא, מכתב ממנו לר פנחס ליב ובו בקשת סמיכה-תריב."},{"i":38346,"n":"פישר, גבריאל","b":"רב בפילפיך. בנו ר ידידיה."},{"i":38347,"n":"פישר, דב בר ממטרסדורף","k":"בעל דובב שפתי ישנים","dt":"תרנג","dp":"מטרסדדורף","b":"תלמיד החת\"ס, והכתב סופר. מראשי קהילת מטרסדורף."},{"i":38348,"n":"פישר, דוד [משה]","dt":"תרמ","b":"ראב\"ד בברעזאווא,רב בפישטיאן"},{"i":38349,"n":"פישר, זלמן הלוי","b":"תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":38350,"n":"פישר, חנוך הניך ממאקווא","f":"יעקב מאישאק","bt":"תקפו","bp":"אישאק","dt":"תרנו - כו ניסן","dp":"מאקווא","b":"תלמיד הכת\"ס, ור יחזקאל בנט מנייטרא, וישיבת פרג. רב בדונא-פאלדוואר-תריב, מאקווא-תרכד (הקהלה הצטרפה לזרם הניאולוגי בזמן פלוג הקהלות). בנו - ד\"ר יעקב - רופא ראשי בביה\"ח היהודי בפרשבורג."},{"i":38351,"n":"פישר, חנוך מדונא פולדוואר","bp":"דומבוואר","b":"רב הקהלה הניאולוגית בדונא פולדוואר-מחוז טולנא. אביו של המשורר אמיל מוקאיי."},{"i":38352,"n":"פישר, טוביה כץ מגיסנינג","k":"בעל חלקה טובה","dt":"תריט","b":"רב בגיסינג,טפנר. חיבר גם \"מעשה טוביה\"."},{"i":38353,"n":"פישר, טוביה כץ משארוואר","f":"פנחס הכהן מטעלעקע","bt":"תרכח","dt":"תרפד - ד אדר","b":"תלמיד ר שלמה זלמן ברייער מפפד\"מ. חתנו של ר שמעון חיים פלנר מבעלד. רב בשארוואר-תרפד על מקום ר אפרים פישל סופר ובנו ר מנחם על מקומו אחריו. מתורתו ב\"וכתורה יעשה\", ו\"חלקה טובה\" לדודו ר טוביה מגיסינג. פרסם מאמרים בכתבי עת ומאספים."},{"i":38354,"n":"פישר, ידידיה גוטליב משטולויסנב","f":"גבריאל","k":"בעל דלתים ובריח","r":"אב\"ד שטוהלווייסנבורג","bt":"תקע","bp":"פילפיץ-ליד ראאב","dt":"תרנו - כד תשרי","dp":"איזנשטט","b":"תלמיד החת\"ס, ור פייש ולרשטין מפילפיץ, ור יהושע קאשמן וודיאנר מראב. חתן ר משה גולדשמיד מעטשקע ועבר לשם-תקצא, רב בוואר-פאלאטא-תרו, שטוהל-ויסנבורג-תריג (והיה שם מחלוקת עם המשכילים). \"המשגיח הראשון\" מטעם רבני הונגריה. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד.","bk":[["דלתים ובריח למי השלוח - נגד ספר מי השלוח להתיר גט",""],["ידיד השם - תורת הגה\"צ",""]]},{"i":38355,"n":"פישר, יוליוס מג'יור","b":"רב הקהלה הניאולוגית בג'יור-1887 על מקום ד\"ר שלמה רנשנבורג, וד\"ר מ. שוורץ מור על מקומו אחריו."},{"i":38356,"n":"פישר, יוסף בצלאל","f":"עמרם פישר","b":"רב בויטנץ-תר\"ע"},{"i":38357,"n":"פישר, יוסף יעקב מקאביליאק","f":"אריה ליב","bt":"תרל","b":"רב בסרניץ-תרנה, ניפרשץ, קאביליאק-פלך פולוטובה."},{"i":38358,"n":"פישר, יוסף מקראקא","bt":"תר","bp":"וינה","dt":"תרעד","b":"חזן מפורסם שלמד בברלסוי בקונסרבטוריון ובביהמד\"ר. חזן של הנאורים בקראקא. פתח בית דפוס שנחשב לאחד המשובחים במדינה והדפיס גם בערבית. (בעיר התלוצצו עליו שאת הכנסתו מהחזנות השקיע בדפוס - ואת הכנסתו מהדפוס השקיע במקהילת החזנים)."},{"i":38359,"n":"פישר, יעקב","f":"מנחם","k":"בעל קול בוכים","b":"דומ\"צ בטיסא-בוהר-תרי. חיבר \"קול בוכים\" פרשבורג תרז, \"קול אבל\" וינה תרלד."},{"i":38360,"n":"פישר, יעקב הירש ממאלין ווינה","b":"מוהל בוינה והסביבה-תרמג."},{"i":38361,"n":"פישר, יעקב כץ","dt":"תרעח - יז שבט","b":"רב בזאלא-מיהא-ליפאלווא"},{"i":38362,"n":"פישר, יעקב מבייאה","f":"ר\"מ","b":"דיין בבייאה-תרלד."},{"i":38363,"n":"פישר, יעקב מהינד-וערבעלי","f":"ר\"ש מבוהר","dt":"תרלח - בערך","b":"תלמיד החת\"ס. רב בבוהר-סענט-מיקלאש - תריא, הינד-וערבעלי - תרל,"},{"i":38364,"n":"פישר, יעקב מפרשבורג","bp":"ואג-ועטשע","dt":"תרסג","b":"מיסד בית הספר לבנות של קהלת פרשבורג - בהונגרית וגרמנית. עורך \"היהודי\" - פרשבורג-תרלו-תרלח - ובין הכותבים תלמידי ישיבת פרשבורג. פרסם מאמרים ב\"בכורי העתים\" - פרשבורג."},{"i":38365,"n":"פישר, יעקב מפרשבורג","b":"רופא ומנהל ביה\"ח היהודי בפרשבורג, נשיא מושב זקנים, הקים בי\"ס לחנוך מטפלות בחולים ליד ביה\"ח."},{"i":38366,"n":"פישר, ישראל יעקב מירושלים","r":"ראב\"ד העדה החרדית בי-ם","bt":"1925","dt":"תשסג - כה אד\"א","dp":"ירושלים","b":"תלמיד ר איסר זלמן מלצר, גר\"ז בנגיס. מו\"צ בירושלים. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\".","bk":[["אבן ישראל","מפרשי רמב\"ם"],["אבן ישראל – שו\"ת וחי'",""]]},{"i":38367,"n":"פישר, מאיר צבי","bt":"טו טבת תרפד","dt":"תשעג","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","bk":[["אור בהיר - פסחים, כתובות, סוכה, עירובין, ושו\"ת",""]]},{"i":38368,"n":"פישר, מיכאל מלונדון","b":"פרסם מאמרים ב\"המסילה\" - לונדון תשז."},{"i":38369,"n":"פישר, מנחם הכהן משארוואר","f":"טוביה משארוואר","dt":"תשה - כג ניסן","b":"גיסו של ר מרדכי שטיין רב במושב הזורעים. תלמיד הדעת סופר. חתן דודו ר יואל הלוי פלנר מאויהל, ובזיוו\"ש חתן ר אברהם אהרן כץ מנייטרא. רב בשטיינמאנגר, שארוואר-תרפג על מקום אביו. נספה בשואה."},{"i":38370,"n":"פישר, מרדכי אפרים פישל משאראש","f":"עמרם מיינק","bt":"תרלז","bp":"האלאש","dt":"תשא - ג תשרי","b":"תלמיד השב\"ס, וזקנו ר אליעזר זוסמן מפאקש. חתן דודו (שנפטר) ר צבי הרש פישר מויינערן. רב בויינערן-תרסה על מקום חותנו. שאראש-פוטוק-תרע."},{"i":38371,"n":"פישר, מרדכי מנייטרא","bp":"טארפא","b":"תלמיד ר שמואל דוד יונגרייז. אחיו - ר ליב מנייטרא."},{"i":38372,"n":"פישר, משה בער מוילנא","dt":"תשג","b":"רב בווילנה"},{"i":38373,"n":"פישר, משה טוביה מפרשבורג","b":"מלמד ב\"יסודי התורה\" בפרשבורג-תרמה, הצטרף לציונות. תלמיד ישיבת השב\"ס בפרשבורג, מחברי אגודת \"אהבת ציון\" ונואם באגודה בפרשבורג."},{"i":38374,"n":"פישר, משה יהודה מדטרויט","f":"עמרם מיינק","bt":"תרלט","bp":"רענדק","dt":"תשיז - יח אייר","b":"תלמיד השב\"ס, ור ישעיה זילברשטין מוויצען וזקנו ר אליעזר זוסמן סופר מפאקש. מחברי אגודת \"אהבת ציון\" ונואם באגודה - בהיותו בישיבת פרשבורג. רב קהילת אנשי אונגרן בשיקגו-תרסג, רב בדטרויט."},{"i":38375,"n":"פישר, משה ליב מבאגמעיר","b":"רב בבאגאמעיר. חתנו - ר עמרם בלום מבערעטי-אויפלו."},{"i":38376,"n":"פישר, משה מאלטנדורף","f":"נח ברוך מפרשוב","dt":"תשד","b":"רב באלטנדורף"},{"i":38377,"n":"פישר, נח ברוך מפרשוב","f":"דוד משה מפישטיאן","bt":"תרך","dt":"תרעט - יד תמוז","dp":"פרשוב","b":"תלמיד השב\"ס. חתן ר ידידיה גוטליב פישר משוהל-ויסנבורג. רב במילכדורף(או מיכלשטדט)-תרמז, בעלעניעש(=באלניש)-תרנו, פישטיאן-תרנח על מקום אביו, פרשוב(=עפעריעש)-תרסא."},{"i":38378,"n":"פישר, עמרם מיינק","f":"עקיבא מטעט","k":"בעל דברי עמרם","bt":"תריג","bp":"טעט","dt":"תרפה - יח ניסן","dp":"יינק - ירושלים","b":"תלמיד הכת\"ס, ור פנחס אליהו אסטריכר (אזלרינר) מאויבן. חתן ר אליעזר זוסמן סופר מהאלאש ופאקש. רב בהאלאש-תרלו לצד חותנו, רב בענדעק-תרלח, יינק(=ג'ונק)-תרלט. (לפי אוצר הרבנים - עלה לירושלים). בניו: ר מרדכי אפרים פישל מדעווא-ואניא, ר משה מארה\"ב."},{"i":38379,"n":"פישר, עקיבא מטעט","f":"מרדכי ליב מלשברין","k":"בעל עטרת עקיבא","bt":"תקעח - בערך","bp":"לשברין","dt":"תרנד - יח שבט","dp":"טעט","b":"תלמיד החת\"ס. חתן ר צבי הרש רוזנבוים מטאפיא-ביטשקע. מחכמי מעזא-טור-תרא, פאפא, רב באויקע-תרה, טעט-תרח. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":38380,"n":"פישר, עקיבא מקין סנט-מיקלוש","f":"עמרם מיינק","dt":"תרפז - ו כסלו","dp":"קין - סנט מיקלוש - י-ם","b":"תלמיד הדעת סופר. חתן ר בנימין זיידל מגאלאנטא. עבר ליינק לצד אביו, רב בקין-סנט-מיקלוש-תרפב."},{"i":38381,"n":"פישר, פנחס מטעלעקע","b":"רב בטעלעגד(=טעלעקע)-תר. בנו - ר טוביה משארוואר. אחיו של ר טוביה מגיסינג."},{"i":38382,"n":"פישר, צבי הירש מויינערן","f":"עקיבא מטעט","k":"בעל זכרון צבי","bt":"תרא","bp":"מעזא-טור","dt":"תרסב - יד אד\"ב","dp":"ויינערן (דעווא-וואניא)","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר. חתן דודו ר אבא חייא הירש מסערעד. רב באסאד-תרלב, ויינערן (דעווא-וואניא)-תרמא וחתנו - בן אחיו - ר מרדכי אפרים פישל פישר על מקומו אחריו."},{"i":38383,"n":"פישר, צבי מסעטשין(=סאצ'אן)","f":"מרדכי אפרים פישל","dt":"תשד","b":"רבה האחרון של סעטשין(=סאצ'אן). נספה בשואה."},{"i":38384,"n":"פישר, צבי מתתיהו מזורובנא","dt":"תש..","b":"רב בזובורנא, זביא-תרץ. מאנשי המזרחי. חבר ועד הרבנים בלבוב. נספה בשואה."},{"i":38385,"n":"פישר, שלום","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":38386,"n":"פישר, שלום יהודה מבודפשט","b":"רב בבודפשט. חבר המועצה \"למען ארץ ישראל\". הצטיין כדרשן. תרגם מיוונית להונגרית את \"חיי משה\" לפילון."},{"i":38387,"n":"פישר, שלמה","bt":"תקכה","dt":"תרכה - כז תשרי","b":"צדיק נסתר ביארדינוב"},{"i":38388,"n":"פישר, שלמה אלכסנדר מקלויזנבורג","f":"אהרן מאיזנשטט","k":"בעל קרבני לחמי","bt":"תריב","dt":"תרצב - ב אב","dp":"קלויזנבורג","b":"תלמיד זקנו ר בנימין וולף אויסטרליץ מאיזנשטאדט. והכת\"ס, ור אהרן זינגר ממטרסדורף, ובישיבת ר בער בומברג בוירצבורג-גרמניה. מורה לשפות בהמבורג. חתן ר שמעיה הלוי מנאוואמעסטא. רבה הראשון של הקהלה האורטודוכסית במינכן, המבורג, קרלסבורג-תרנא בקהילת סטטוס קוו - ועזב בגלל מחלוקת עם הקהלה בנוגע להצטרפות למחנה האורטודוכסי ועבר לקלויזנבורג-תרפח. בנו ר אהרן פישר עלה לירושלים ונכדו ר יעקב ישראל מרבני העדה החרדית בירושלים."},{"i":38389,"n":"פישר, שלמה מאלבא יוליא","b":"אב\"ד אלבא-יוליא. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":38390,"n":"פישר, שמואל","b":"רב בנאדיקערעש"},{"i":38391,"n":"פישר, שמחה יואל מדווה ונ\"י","f":"עמרם מיונק","b":"תלמיד ישיבות הונגריה, פפד\"מ, ובעל תואר ד\"ר מהאוניברסיטה שם. רב בדווה(=דיווא)-תרפד - לאחר שהקהלה הצטרפה למחנה האורטודוכסי. חיבר מאמרים בעתונות היהודית בהונגרית ובגרמנית. היגר לקניה-תרצח וכיהן כרב בניירובי. עבר לארה\"ב וכיהן כרב בשיקגו, ניו יורק. פרסם מאמרים."},{"i":38392,"n":"פיתוסי, ברוך מתונס","f":"זלמן","k":"בעל מקור ברוך","b":"רב בתוניס בזמן ר נתן בורגיל בעל \"חק נתן\". חיבר \"מקור ברוך\" - ליוורנו."},{"i":38393,"n":"פיתוסי, חיים","f":"יעקב - מזבח כפרה"},{"i":38394,"n":"פיתוסי, יעקב מתונס","f":"אברהם","k":"בעל ברית יעקב","bp":"תונס","dt":"תקעב","dp":"אלגיר","b":"מחכמי תונס-תקמ, תלמיד ר יוסף זארקו ור שלמה בן עטר. עלה לירושלים לאחר תקס, יצא לשליחות בצפון אפריקה ושם נפטר. חיבר \"ברית יעקב\" ליוורנו תקס, \"מזבח יעקב\" ועוד."},{"i":38395,"n":"פיתוסי, ישועה פרג'י מתונס","f":"מרדכי","bt":"תרסט","bp":"תונס","dt":"תשלא - א תמוז","dp":"צפת","b":"מצאצאי ר יעקב פיתוסי. ונכד ר פרג'י ישועה מתסתור (ליד תונס) שע\"ש נקרא. תלמיד ר ישועה אלמליח, ור דוד קטורזא - שהיה הרב הראשי בתונס בעל \"תנובות שדי\", למד גם אצל ר אהרן ג'רמון וקבלה אצל ר רפאל ג'אמי. חתן ר יוסף הלוי - ראש הקהלה. אחיו ר יצחק המכונה ג'בל אדהב - היה עשיר גדול ותמך בו שישב וילמד. רב בסלימאן וראש ישיבה, חממאם א-לף והקים בה ישיבה-תשה. עלה לארץ והתישב ביבנאל, מושב כרם בן זמרא, באר יעקב, רבה של צפת, ודיין."},{"i":38396,"n":"פיתוסי, ישכר מאלגיר","bt":"תקף","dt":"תרן - בערך","b":"רב בסטיף-אלגיר-תרי כ-20 שנה. ברשימת מסייע הגדת \"ויגד לאברהם\"."},{"i":38397,"n":"פיתוסי, משה מתונס","dt":"תרכו","dp":"ירושלים","b":"דיין בתונס עם ר ישועה בסיס ור נתן בורג'ל השני. חתם על תקנות-תרטו. יתכן שעלה לירושלים."},{"i":38398,"n":"פכטר, אלתר מדמביץ","f":"יהודה מדמביץ","k":"אדמור מזמביץ","dt":"תש..","b":"חתן ר ישראל איסר אייזנברג. רב ואדמור בדמביץ על מקום אביו. נספה בשואה."},{"i":38399,"n":"פכטר, גדליה מדמביץ","b":"רב בדמביץ-תר\"ע"},{"i":38400,"n":"פכטר, חיים אפרים מגורליץ","f":"יהודה מדמביץ","k":"אדמור מגורליץ","b":"רב ואדמור בגורליץ. בנו ר משה וחתנו הרב ברנדויין על מקומו אחריו - נספו בשואה."},{"i":38401,"n":"פכטר, יהודה מדמביץ","f":"פנחס מדמביץ","k":"אדמור מדמביץ","dt":"תרנג - יז ניסן","b":"תלמיד ר צבי הירש מרימנוב. רב ואדמור בדמביץ על מקום חותנו - ר פנחס טמפלר. בזיוו\"ש חתן ר אריה ליב ליפשיץ מוישניצה. בנו ר אלתר על מקומו אחריו, ובנו ר חיים - אדמור בגורליץ."},{"i":38402,"n":"פכטר, משה מגורליץ","f":"חיים אפרים מגורליץ","k":"אדמור מדמביץ גורליץ","dt":"תש..","b":"אדמור מדמביץ בגורליץ-תרצז על מקום אביו. נספה בשואה."},{"i":38403,"n":"פכר, יוסף מטיסמניץ","b":"רב בטיסמניץ-תרנח, בנו ר יהודה דב על מקומו אחריו."},{"i":38404,"n":"פלאג'י, אברהם מאזמיר","f":"חיים","k":"בעל אברהם אזכור","r":"רב דכפר חב\"ד","bt":"תקע","bp":"אזמיר","dt":"תרנט - כג טבת","dp":"אזמיר","b":"רב הכולל באיזמיר ור יוסף עלי על מקומו אחריו, חיבר גם \"שמו אברהם\" הסכים על \"מעשה נסים\" לר משה יצחק הלוי.","bk":[["פדה את אברהם - ד' חלקי שלחן ערוך לפי סדר א' ב'",""],["ויען אברהם",""]]},{"i":38405,"n":"פלאג'י, אברהם מצפת","b":"רב בצפת. בשנת תקנה חתום בצפת על מכתב הקהלה בבקשת עזרה."},{"i":38406,"n":"פלאג'י, אהרן מאזמיר","b":"תלמיד ר נסים חיים שלום מרגונטו ונספד בידי רבו."},{"i":38407,"n":"פלאג'י, בנימין","b":"דודו של \"חקרי לב\""},{"i":38408,"n":"פלאג'י, חיים מאזמיר","f":"יעקב","k":"בעל ארצות החיים","r":"רב הכולל דאיזמיר","bt":"תקמח","bp":"אזמיר","dt":"תרכח - יז שבט","dp":"אזמיר","b":"מגדולי חכמי דורו, מקורב למלכות, רב באזמיר-תקצז, חיבר 95 ספרים.","bk":[["אבי הנח\"ל – אגדת בראשית",""],["ארצות החיים – מעלת ודיני א\"י",""],["בית אבות – אבות",""],["ברכת מועדיך לחיים - דרוש",""],["גנזי חיים – מערכות ע\"ס א' ב'",""],["החפץ חיים – ליקוט ס' הזכרונות",""],["הכתוב לחיים – תהלים",""],["ובחרת בחיים – מפרשי התורה",""],["זכירה לחיים – זוהר וקבלה",""],["חוקי החיים",""],["חיי וחמרא",""],["חיים ביד – יו\"ד",""],["חיים דרכיו למשה תחילה",""],["חיים ומזון – זוהר",""],["חיים ומלך – רמב\"ם",""],["חיים ושלום – אה\"ע",""],["חיים טובים – מדרש שמואל שוחר טוב ומשלי",""],["חיים לגופא- אותיות התורה",""],["חיים לראש – פסח",""],["חיים תחילה- ראש התורה וסופה",""],["חלקם בחיים – דרוש",""],["חקות חיים – חו\"מ",""],["חקקי חיים – שו\"ת",""],["ימצא חיים – תפילות",""],["ישמח חיים",""],["כל החיים – כללי ש\"ס ופוסקים",""],["כף החיים –",""],["כפר חיים – עבודה במוסף יוה\"כ",""],["לב חיים – חקירות וענינים או\"ח",""],["לוח ארז – תנא דבי אליהו",""],["לחיים בירושלים - ירושלמי",""],["מועד לכל חי – לקט לחדשי השנה",""],["מי החסד – מכילתא וילקוט",""],["משא חיים – על ס' משא מלך, ועבודת משא",""],["נפש חיים – ליקוטים",""],["נפש כל חי – ליקוטים",""],["נשמת כל חי – או\"ח יו\"ד",""],["סמיכה לחיים – שו\"ת",""],["ספר חיים – דיני קס\"ת",""],["ספרי חיים – ספרי",""],["עיני כל חי – ש\"ס",""],["עמודי חיים -",""],["פני חיים – תורה",""],["פעולת צדיק לחיים – אבות",""],["פר אחד – פרקי דר\"א",""],["צדקה חיים – הל' מתנו\"ע",""],["צדקה לחיים – צדקה",""],["צוואה מחיים – מוסר",""],["ראה חיים - דרוש",""],["רוח חיים",""],["רפואה וחיים",""],["תוכחת חיים",""],["תורה וחיים -",""],["תנופה חיים – תנ\"ך",""],["משא חיים – על ס' משא מלך",""],["ועבודת משא",""]]},{"i":38409,"n":"פלאג'י, יהודה ליאון מאמשטרדם","f":"יצחק","bt":"תרמז","bp":"אמשטרדם","b":"תלמיד ביהמ\"ד \"עץ החיים\" באמשטרדם, למד שפות עתיקות בליידן, כיהן כפרופ' באמשטרדם, ביקר בארץ-תרצה כשליח קהלת הספרדים באמשטרדם. פרסם מאמרים וספרים."},{"i":38410,"n":"פלאג'י, יוסף מאזמיר","f":"חיים פלאג'י","k":"בעל ויוסף אברהם","b":"חתן ר בכור אברהם ן יקר מאזמיר וירושלים. מחכמי אזמיר-תריג."},{"i":38411,"n":"פלאג'י, יעקב - השבתאי","b":"מנביאי ש\"ץ."},{"i":38412,"n":"פלאג'י, יעקב מאזמיר","k":"מורנו פלאג'י","dt":"תקפח - א אב","dp":"אזמיר","b":"מרבני אזמיר. אביו של ר חיים פלאג'י."},{"i":38413,"n":"פלאג'י, יצחק מאמשטרדם","f":"יהודה","dt":"תרפז - כו כסלו","b":"רב באמשטרדם-תרס. אביו של ר יהודה ליאון פלאג'י"},{"i":38414,"n":"פלאג'י, יצחק מפאס","b":"רב בפאס, חתם על התקנות-שמח. חתנו - ר יהודה עוזיאל בעל \"בית העוזיאלי\". בנו או אחיו - ר שמואל שהיה שגריר מרוקו בהולנד וסייע לאנוסים להתישב שם."},{"i":38415,"n":"פלאג'י, יצחק מצפת","f":"שלמה","k":"חצבני","bt":"תרל","bp":"צפת","b":"נכד ר יעקב פלאג'י מחצביה-לבנון וכונה גם בשם חצבני. רב בצפת, בשליחות במקומות שונים, דיין עם ר עזרא הכהן, ור רפאל מנשה ענתבי."},{"i":38416,"n":"פלאג'י, ישועה מצפת","bt":"תרל","b":"רב עדת הספרדים בצפת-תרצה."},{"i":38417,"n":"פלאג'י, משה שמואל מירושלים","dt":"תריט - כה סיון","dp":"ירושלים","b":"רב ומלמד תורה בירושלים."},{"i":38418,"n":"פלאג'י, רחמים נסים יצחק","f":"חיים","k":"בעל אבות הראש","bt":"תקעג","dt":"תרסז - ד ניסן","dp":"אזמיר","b":"מחכמי אזמיר. חתן ר סעדיה הלוי מירקאדו בעל \"נוה הצדק\", נפטר ללא ילדים. חיבר גם \"נפש היפה\", \"אנך יפה\" ועוד.","bk":[["אבות הרא\"ש – אבות דרבי נתן",""],["אנך יפה - תנ\"ך",""],["ויקרא יצחק – סדר הפרשיות",""],["חלק יפה – הערות בס' הפרשיות",""],["יפה ללב – שו\"ע",""],["יפה לעינים – אגדות",""],["יפה תלמוד",""],["נפש היפה – קבלה",""],["עין יפה – עין יעקב ואגדות",""]]},{"i":38419,"n":"פלאג'י, שלמה דוד מאזמיר","f":"אברהם","bt":"תקצט","b":"נכד ר חיים פלאג'י. מתורתו בספר אביו \"אברהם את ידו\", ובספר זקנו \"חיים ומזון\"."},{"i":38420,"n":"פלאג'י, שמואל","f":"אברהם","b":"נכד ר חיים פלאג'י. דרשה ממנו בספר אביו."},{"i":38421,"n":"פלאג'י, שמואל מהולנד","k":"בעל בית אבל","b":"מגדולי רבני הולנד-תקי."},{"i":38422,"n":"פלאג'י, שמואל ממרוקו","f":"יצחק מפאס?","bp":"פאס","b":"ר יצחק היה אביו או אחיו? בן למשפחת אנוסים במרוקו-שס, וכיהן כשגריר מרוקו בהולנד, ופעל להתישבות האנוסים בהולנד בהתחלה בעיר מידלבורג. אולי הוא שנזכר בספר השירים יחד עם ר שלמה דוראן."},{"i":38423,"n":"פלאויו, יעקב די איבורה","b":"משורר, נשיא היהודים, מאנוסי ספרד והתישב בראגוזה(=דוברובניק), שלוניקי."},{"i":38424,"n":"פלאויטץ, שלמה מפרשבורג","b":"מתלמידי החת\"ס. העתיק מכתב שנשלח אל רבו-תקצד."},{"i":38425,"n":"פלאוס, שלומית פרידה","f":"יצחק שאול","k":"בעל בת ישראל נודדת","bp":"פוניבז","dt":"1963","b":"אביה היה נדבן ציוני בדרום אפריקה ממשפחת מהרש\"ל. נכדת ר נתן נטע פלאום. למדה באוני', עלתה לארץ-1911 והורתה בסמינר לגננות. שהתה בהודו והרצתה על ארץ ישראל, עמדה בקשרים עם גאנדי וטאגורי. חיברה גם \"רבינדראנאת טאגור\". חיבר מאמרים שונים."},{"i":38426,"n":"פלאח, כמוס מטריפולי ובנגזי","bt":"תרלט או תרכו","bp":"טריפולי","dt":"תשא - כד תמוז","dp":"בנגזי","b":"אב\"ד בנגאזי-לוב ורב ראשי במחוז קירינאקיה-לוב, ור יוסף גי'אן על מקומו אחריו. הסכים על \"יוסף חן\". נזכר ב\"אהלי שם\" פינסק תרעב."},{"i":38427,"n":"פלאח, שלום מתונס","b":"רב בסוסא-תונס על מקום ר יוסף גז. בקי בדקדוק."},{"i":38428,"n":"פלאטא, אברהם מארה\"ב","dt":"תרפו","b":"רב באטלנטה-ארה\"ב. נפטר בגיל 107!"},{"i":38429,"n":"פלאטא, יהושע","b":"רב בניישטט-תר\"ע"},{"i":38430,"n":"פלאטא, פיבש פישל מארה\"ב","f":"שמואל יצחק בן שרגא י","bt":"תרלד","bp":"פרושניץ-פלך פלוצק","b":"תלמיד ר יהושע מרדכי צוקרקורן, ובנו ר בנימין זאב. נסמך מאת: ר נחמן שמואל יעקב מיידעסער מבראק, ר שלמה זאלקי קאנאריק, ר מנחם יהודה גוזיק ה\"מאקאווער רב\". חתן הגביר ר חיים יחזקאל צוקרמן מפרושניץ. היגר לארה\"ב-תרסא, וכיהן כרב בניו יורק. פרסם מאמרים ב\"הבאר\", \"הפרדס\", ועוד. חבר אגודת הרבנים באמריקה, ותנועת המזרחי. פעיל בועד ההצלה."},{"i":38431,"n":"פלאטא, צבי הירש מקעלין","k":"בעל הבלעת הדם","b":"רב בקעלין-תרנ. חתנו - ר מאיר לרנר מאלטונא."},{"i":38432,"n":"פלאטא, שלמה ממרוקו","dt":"תקם - לפני","b":"מחכמי מרוקו, נספד מאת ר אברהם מאנסאנו."},{"i":38433,"n":"פלאטו, מנחם מהמבורג","b":"רב בהמבורג-תרע."},{"i":38434,"n":"פלאטוי, יוסף יעקב מפוזן","b":"גביר בפוזן, בעל אחוזות והתמחה בגידול כשות, והקים תעשיה גדולה בנייטאמיסל, ופרסם ספרים ומאמרים על גידול הכשות."},{"i":38435,"n":"פלאיי, אברהם נח","bt":"תרלו","dt":"תרצב - ח אד\"א","b":"ר\"מבהאלוסק,שקלוב,ובהיכל התלמוד בתל אביב"},{"i":38436,"n":"פלאך, גרשון מקוסוב","b":"צדיק נסתר בזמנו של ר חיים מקוסוב - שהיה שולח אליו להיפקד בישועות."},{"i":38437,"n":"פלאם (השל), דוד","f":"שלום","k":"אדמור מאפטא","b":"מצאצאי האדמור ראי\"ה מאפטא ואדמורי בלז. נקרא האדמור מאפטא."},{"i":38438,"n":"פלאם, אברהם דוב ממזריטש לובלין","f":"דוד","k":"בעל יריעות האהל","bt":"תקסד","bp":"מזריטש","dt":"תרלג - כד טבת","b":"מגיד בשברשין, מזריטש, לובלין. חיבר גם \"אבל יחיד\" - הספד על ר אברהם אבלי מביאלא, ור אהרן ארוש מינץ ממזריטש."},{"i":38439,"n":"פלאם, דב בריש (דוד) מאלסק וסקו","f":"שלמה לוצקר","k":"הסגי נהור מאלסק","bt":"תקל","dt":"תרי - כא אלול","b":"תלמיד ר מרדכי מנסכיז, ור אורי מסטרליסק. סגי נהור. רב באלסק, סוקוליבקה, טופורוב. מקורב לגדולי האדמורים. מחותן עם האדמור מבלז."},{"i":38440,"n":"פלאם, דוד מבוברקא - הנכד","f":"יצחק","k":"אדמור מסטרטין","bt":"תרנד-ו","bp":"קורטשין","dt":"תשלא - יב ניסן","dp":"ישראל","b":"נכד ר דוד פלאם מסקאהל, ור שמואל רובין מקארטשין בעל \"בית אהרן\". אדמור חסידי סטרטין בבוברקא. חתן ר משה לנגנר האדמור מקוזובה-סטרטין. היגר לקנדה-תרף עם חמיו - וכיהן כרב ואדמור במונטריאול, עלה לארץ."},{"i":38441,"n":"פלאם, דוד מסקאהל","f":"דב בעריש מסקאהל","b":"חתן ר אלעזר מבלז."},{"i":38442,"n":"פלאם, יצחק מקורטשין","f":"דוד","bt":"תר","dt":"תרעט","b":"חתן ר שמואל אהרן רובין מקורטשין. רב בקורטשין על מקום חותנו."},{"i":38443,"n":"פלאם, שלום מסטרטין ניו יורק","f":"דוד מסקול","k":"אדמור מסטרטין נ\"י","bt":"תרץ","bp":"מונטריאול","dt":"תשסג","b":"הסנדק היה מהר\"ם שפירא. חתן ר יחיאל מיכל מסטרטין-טורקא. אדמור סטרטין בניו יורק וראש ישיבה."},{"i":38444,"n":"פלאם, שלמה מאלסק.","f":"דוב בעריש","b":"רב באלעסק-תר\"ך"},{"i":38445,"n":"פלאם, שלמה מסקאהל","f":"אברהם","k":"אדמור מסקול","bt":"תק","dt":"תקעג - י שבט","b":"מקובל ממשפחת המגיד ממזריטש ותלמידו ומשמש בקודש אצלו. מ\"מ בסקאהל, קוריץ. רשם את תורת רבו והדפיס ממנו \"לקוטי אמרים\" קוריץ תקמא - עם הקדמה. רב בלוצק, קוריץ, סקול. רבו של השר שלום מבלז. חיבר \"דברת שלמה\" זולקוא תרח. רשם את תורת רבו בשם \"מגיד דבריו ליעקב\", עם הקדמה ממנו. מתלמידיו ר שלום מבלז.","bk":[["דברת שלמה – עה\"ת",""]]},{"i":38446,"n":"פלאם, שמואל אהרן מדובעצק","dt":"תשג","b":"רב בדובעצק"},{"i":38447,"n":"פלאנייאש, אברהם מדרדנלים","bt":"שע","bp":"קושטא","b":"שו\"ב בקושטא-ת' בזמן ר חיים בנבנישתי שהיה ממונה על איסור והיתר, שו\"ב ומו\"ץ בדרדנלים, עבר לאזמיר-תכד. שאלה ממנו לר שבתי נאווי מרשיד-מצרים."},{"i":38448,"n":"פלאסטר, משה מזבורוב","b":"פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":38449,"n":"פלאץ, אברהם מארה\"ב","b":"ממיסדי חברת \"שערי חסד\" בניו אורליאנס-ארה\"ב, וביהכנ\"ס \"שערי חסד\" המכונה \"טורא\"."},{"i":38450,"n":"פלאש, ארמין ממוהאץ","dt":"תשד","b":"רבה האחרון של הקהילה הניאולוגית במוהאץ. תרגם הגדה להונגרית. חיבר ספרים בעניני דת ישראל וספרות ישראל. נספה בשואה."},{"i":38451,"n":"פלברבוים, אהרן","f":"אליעזר ליפא פלברבום","dt":"תשד","b":"רב בגוויץ"},{"i":38452,"n":"פלברבוים, אליעזר ליפא","dt":"תרעה - ה כסלו","b":"רב בגעץ"},{"i":38453,"n":"פלברמן, חיים אליהו מנאדי-אידא","b":"אב\"ד נאדי-אידא. חתן ר הלל אונסדורפר מלאשאנץ."},{"i":38454,"n":"פלברמן, ישראל","dt":"תשד","b":"רב בנאדי-אידא"},{"i":38455,"n":"פלג’י אברהם בן חיים","bt":"1809","dt":"ה'תרנט 1899","bk":[["אבי הנחל",""],["אברהם אזכור",""],["אברהם אנכי",""],["אברהם את ידו",""],["אברהם את עיניו",""],["ברך את אברהם",""],["זכותיה דאברהם",""],["שמו אברהם",""],["שמע אברהם",""],["שמע אברהם חלק ב",""],["פדה את אברהם",""]]},{"i":38456,"n":"פלג’י רחמים נסים יצחק בן חיים","bt":"1814","dt":"ה'תרסז 1907","bk":[["אבות הרא\"ש",""],["אנ\"ך יפה",""],["חלק יפה",""],["יפה ללב",""],["יפה תלמוד ג\"ח",""]]},{"i":38457,"n":"פלגמן, משה יוסף","dt":"תרכ - ט סיון","b":"דומ\"צ בה'מאד"},{"i":38458,"n":"פלגר, יהושע אשר זליג מהעדילא","f":"ישכר דב","bt":"תקעה","bp":"גיסינג או פיסלינג","dt":"תרמח - ה שבט","dp":"העדילא-מאדע","b":"מצאצאי ר שמואל שמלקא הורביץ מניקלשבורג. לאחר שנתייתם גדל אצל אחיו - ר יוסף בגיסינג. תלמיד החת\"ס, ור בנימין זאב תרצס-הירשלר מגיסינג. בזיוו\"ש חתן ר אברהם סנדר ממאזע-זמבור. רב בהדילא-מאדע(=ה'מאד)-תרך."},{"i":38459,"n":"פלגר, שמחה ממיקוליניץ","b":"מחכמי מיקוליניץ-תרסט."},{"i":38460,"n":"פלדברג, חיים מאיר משורוויליסק","f":"אברהם מנחם","bt":"תרלז","b":"מצאצאי ר אברהם רגולר-אחי הגר\"א. רב בשורביליסקי(=שורווילישאק)-פלק קובנא-תרסה, קרוק-מחוז קידאן וחתנו ר דוד גולדבר על מקומו אחריו. בנו ד\"ר ליאון עורך ה\"ג'ואיש טיימס\" ביוהנסבורג-דרום אפריקה."},{"i":38461,"n":"פלדברגר, אליעזר","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":38462,"n":"פלדברנד, אברהם אריה משעבעש","f":"אליעזר יצחק ממיקהאזא","bt":"תרם","bp":"מיקאהאזא","dt":"תש..","b":"נינו של ר שלמה גנצפריד. תלמיד השב\"ס, וקרובו ר יחזקאל בנט מסינער וואראלי. מחכמי טאטטשווא, נאדי-אידא. רב בשעבעש-תרפד. נספה בשואה. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":38463,"n":"פלדברנד, אריה הלוי","dt":"תשד","b":"רב בשעבעש"},{"i":38464,"n":"פלדירמאכר, שלום מוילנא","k":"בעל מתת יה","bt":"תריז","bp":"וילנא","b":"תלמיד ישיבת מייליס בוילנא, ואצל ר יעקב פיעסקין. מורה לתלמוד ועברית בוילנא. פרסם מאמרים ב\"הקול\", \"המגיד\", \"הכרמל\", \"המליץ\", \"כנסת הגדולה\" - וארשא תרן, ועוד."},{"i":38465,"n":"פלדמן, אברהם מארה\"ב","f":"יחיאל","bp":"קיוב","b":"היגר לארה\"ב, תלמיד ביהמ\"ד לרבנים בסינסינטי. רב ריפורמי בהרטפורד, חיבר ספרים באנגלית."},{"i":38466,"n":"פלדמן, אברהם מבודפשט","f":"שמעון צבי מאונגואר","dt":"תרפב - יג תמוז","dp":"בודפשט","b":"תלמיד הכת\"ס. חתן ר אהרן הלוי ברייער מפרשבורג. שו\"ב בבודפשט."},{"i":38467,"n":"פלדמן, אברהם מצורטקוב","b":"נכד הגביר ר מאיר סרוצקר. מחכמי צורטקוב-תרסח."},{"i":38468,"n":"פלדמן, אהרן","f":"שמעון מגלנטא","b":"רב בפאנטשאווא."},{"i":38469,"n":"פלדמן, אהרן מאונגוואר","f":"שמעון צבי מאונגוואר","dt":"תרפג - כג חשון","dp":"אונגוואר","b":"תלמיד הכת\"ס. מחכמי אונגוואר."},{"i":38470,"n":"פלדמן, אליהו מהלמיאזב","f":"יהודה ליב","k":"בעל יחוס היהדות והיה","bt":"תרלה","b":"רב בהאלמיזוב(=הלמיאזב)-פלך פאלטאווא-תרס. חיבר \"יחוס היהדות והיהודים לחיים אנושיים\"."},{"i":38471,"n":"פלדמן, אפרים פישל מביטשוקב","f":"משה ישראל ממיהלן","k":"בעל דגל אפרים-תרסח","bt":"תקצט","bp":"מיהלן","dt":"תרסה - כג כסלו","dp":"ביטשקוב או קרטשנוף","b":"חתן ר יהודה אברהם עביר רוזנברג מביטשקוף-ליד קרטשנוף, ועבר לשם והיה גביר מחכמי ביטשקוף, ונחשב לרב הלא רשמי של העיר. התכתב עם גדולי דורו בגליציה והונגריה. בנו ר משה ישראל מברעזן הו\"ל את ספרו \"דגל אפרים\" עם הקדמה והוספות ממנו. חיבר גם \"ידות אפרים\" מרמורש-סיגט תרסח, ועוד."},{"i":38472,"n":"פלדמן, אריה ליב מסעמיהאי","b":"רב בסעמיהאי. דיין וראב\"ד בסטמר כ-28 שנה."},{"i":38473,"n":"פלדמן, אשר מלונדון","f":"חיים","bt":"תרלד","bp":"פינסק","b":"הגיע ללונדון בילדותו. חתן ר יהודה לובצקי מפאריס. דיין ומטיף בקהילת \"כנסת ישראל\" בבלונדון-תרסד."},{"i":38474,"n":"פלדמן, בן ציון מוישינטה","f":"יצחק דוד","k":"בעל זרע יעקב","dt":"תקנח - בערך","b":"רב בפרג-תקכח, אחיו של ר משה מפרג. תלמיד ר מאיר פישלס מפרג. ר\"מ בישיבה בפרג. , רב בהעלישוי"},{"i":38475,"n":"פלדמן, בן ציון מליטא","dt":"תרעו","b":"מגדולי חכמי דורו, רב בפלונגיאן, זאגר חדש על מקום ר יעקב יוסף, וישינטה."},{"i":38476,"n":"פלדמן, בנימין הלוי","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":38477,"n":"פלדמן, גרשון מנחם ממוזשאי","dt":"תשד","b":"רב במוזשאי"},{"i":38478,"n":"פלדמן, דוד מהוסיאטין","f":"שמאי מהוסיאטין","k":"בעל עיר דוד","bt":"תרמה","bp":"טולנא","b":"רב בלייפציג, עבר למנצסטר לפני השואה. חיבר \"עיר דוד\" על שו\"ע לייפציג תרפד, ו\"כתורה יעשה\" - על גיור (וכנגדו יצא \"מנחת כהן\" לר שמריה מנשה אדלר). פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":38479,"n":"פלדמן, זאב וולף","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":38480,"n":"פלדמן, חיים מדראגמירשט","f":"משה ישראל מדרגמירשט","b":"חתן ר שלמה דב הלר מסיגט. רב ליד אביו בדראגמירשט. נספה בשואה."},{"i":38481,"n":"פלדמן, חיים צבי מלברטוב","f":"משה","bt":"תרח","b":"רב בליברטוב(=ליעבער)-ווהלין-תרם. נסמך מאת: ר הרש ליב ממזבוז, ר נפתלי מסקווירא. בניו: ר משה, ר מנחם. חתנו - ר גבריאל ליטמן בעל \"עד לאומים\"."},{"i":38482,"n":"פלדמן, יהודה אריה ליב","b":"רב בסעמיהאלי,ראב\"ד בסאטמר"},{"i":38483,"n":"פלדמן, יוסף מארה\"ב","f":"מנחם","k":"בעל הגיוני יוסף","bt":"תרסג","bp":"וארשא","b":"תלמיד ישיבת \"רבי איטשע\" בוארשא, ר יחיאל מרדכי גורדון בלומזה, סובאלק, ר אהרן יוסף באקשט בלומזה. נסמך מאת: ר י\"ל גורדון מלומזה, ר יוסף צינוביץ מלומזה, ר יחיאל מיכל גורדון מלומזה, ר אהרן יוסף באקשט מ סובאלק, ר יהושע זליג רוך מלומזה, ר מאיר לעוו ממזריטש. היגר לארה\"ב וכיהן כרב בקהלת \"שערי תפלה\" בבולטימור, וקהלת \"אור כנסת ישראל\", \"שערי תורה\", וממנהלי ישיבת חפץ חיים בבולטימור. חבר אגודת הרבנים באמריקה."},{"i":38484,"n":"פלדמן, יעקב בער","b":"גדול בתורה,רב בפטרא-תק\"צ"},{"i":38485,"n":"פלדמן, יצחק מערשעמיען","f":"יעקב דב מפעטרא","b":"תלמיד הכת\"ס. מחכמי ערשעמיען."},{"i":38486,"n":"פלדמן, יצחק שמואל מבודפשט","b":"תלמיד הדעת סופר בפרשבורג. רב בבודפשט. הניח חדושים בכת\"י ובהם דברי תורה מרבו."},{"i":38487,"n":"פלדמן, מנחם מנדל מאונגוואר","f":"שמעון צבי מאונגוואר","dt":"תרנב - א ניסן","dp":"ירושלים","b":"תלמיד הכת\"ס. מלמד באונגוואר, עלה לירושלים-תרמד."},{"i":38488,"n":"פלדמן, מנחם מנדל מנ\"י","b":"פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":38489,"n":"פלדמן, מנחם נחום מארה\"ב","b":"רב באומהא-נברסקה."},{"i":38490,"n":"פלדמן, מרדכי מפרשבורג","b":"שו\"ב וחזן בפרשבורג-אחרי תרפג."},{"i":38491,"n":"פלדמן, משה אהרן מאלשאני","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":38492,"n":"פלדמן, משה ישראל מדרגמירשט","f":"אפרים פישל-דגל אפרים","k":"בעל לקוטי מהרמי-תרצה","bt":"תרמג","bp":"ביטשקוב","dt":"תשג-ד - כו אייר","dp":"אושוויץ","b":"חתן ר יצחק שבדרון מחאצמיר-גליציה - בנו של המהרש\"ם מברעזן, ועבר לברעזן אל חותנו זקנו. ראב\"ד בברעזן, חזר להונגריה-תרעא והתישב בגרוסורדין. רב בכפר דראגמיראש-תרפא, ויסד ישיבת \"דעת תורה\". חסיד האדמור ר חיים הגר מאטיניע, והקים ישיבה בשם \"דעת תורה\". נספה בשואה - כאשר ברכבת בדרך להשמדה לימד את הנוסעים הלכות קבלת עול מלכות שמים ועניני קידוש השם ומסירות נפש. הו\"ל את ספרי חותנו זקנו המהרשם מברעזן. חיבר \"ליקוטי מהרמ\"י\" סטמר תרצה. ?? לא באוצר ??"},{"i":38493,"n":"פלדמן, משה מגלנטא","dt":"תרפז - יג אב","b":"חתן ר שמעון פרידמן מגלנטא, רב בגאלנטא על מקום חותנו, מו\"ץ חרדי בקהלה הניאולוגית בבודפשט-תרע - לאחר שהתיעץ על כך עם הדיין ר דוד ניימן מפרשבורג. חתנו ר מרדכי צבי אורביך מסעמעלין."},{"i":38494,"n":"פלדמן, משה מקופיטשיניץ","f":"מנחם אלתר מזבורוב","k":"בעל סדר ברכות","bt":"תרי","bp":"זבורוב","dt":"תרע","b":"רב בפויטשיניץ. עלה לטבריה. חיבר \"סדר ברכות\" הוסיאטין תרסד, \"דברי משה\" מונקטש תרס. ?? לא באוצר ??"},{"i":38495,"n":"פלדמן, ראובן מקראקא","f":"ישראל צבי","bt":"תרנט","bp":"קראקא","b":"מרצה נודד. חתן ר יהושע השל אלטשר. עלה לארץ-תרצג. פרסם חוברות ומאמרים. רב בתל אביב-תשב. יו\"ר ארגון יוצאי קראקא."},{"i":38496,"n":"פלדמן, שלום בן ציון מזאגר","f":"משה","bt":"תרלו","b":"רב בוישינטא-פלך וילקומיר-תרסג, זאגר ישן-פלך קובנא."},{"i":38497,"n":"פלדמן, שלום מפודוולוטשיסק","b":"רב בפודוולוטשיסק-תרפב."},{"i":38498,"n":"פלדמן, שמריה מהרימלוב","f":"נחמן","bt":"תרמז","bp":"הרימלוב","dt":"תשמח","b":"היגר לארה\"ב וכיהן כנשיא ועד ישיבת כוכב מיעקב."},{"i":38499,"n":"פלדר, אהרן","f":"גדליה מטורונטו","k":"בעל אהלי ישורון","b":"חתן ר משה אדלר. חבר הכולל להוראה של ר משה פינשטיין. חיבר \"אהלי ישורון\" תשלז."},{"i":38500,"n":"פלדר, גדליה מטורונטו","f":"צבי הרש","k":"בעל יסודי ישורון","bt":"תרפא","bp":"איסטריק","b":"ניצל מהשואה ועבר לקנדה - כיהן כרב בטורנטו. חתן ר ישכר דב בריש טייכנר. חיבר גם\"שאילת ישורון\", גליוני ישורון\"-נ\"י תשמט. פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד."},{"i":38501,"n":"פלדרבוים, אברהם חיים מזוואלין","f":"יוסף","bt":"תרכא","b":"רב בטשעכוב-ליד לובלין-תרכה, זוואלין-תרסו-פלך ראדום."},{"i":38502,"n":"פלדשטין, אברהם מפשוורסק","f":"קלונימוס","bt":"תרך","dt":"תש","b":"מחכמי פשוורסק. חתן ר יהושע מרדכי, ובזיוו\"ש חתן ר יהושע הורביץ. הביא לדפוס את צוואת חותנו \"שם דרך\" תרצז - עם הוספות ממנו."},{"i":38503,"n":"פלדשטין, משה יעקב מפשמישל","b":"רב בפשמישל-תרמח אצל ר\"מ מייזלש. חתן ר שמעון שמש ה\"שול\"."},{"i":38504,"n":"פלהאם, יעקב בער מוילנא","f":"זאב וולף","dt":"תרנג - כד תמוז","b":"חתן ר אברהם אבא בן בנימין הדיין בוילנא, דיין בוילנא על מקום חותנו, ומו\"ץ שם."},{"i":38505,"n":"פלהינגר, פייטל מברעטען","b":"רב בברעטען-תר."},{"i":38506,"n":"פלוביץ, יהושע מארה\"ב","k":"בעל חנינא בן חכינאי","bt":"1875","bp":"רוגובה","b":"גדל בקופישוק, תלמיד ישיבה. פעיל בתנועה הציונית. חיבר את \"השבועה\" שהיתה לימים המנון פועל ציון (במנגינת א.מ. ברנשטין). היגר לארה\"ב-1906, פרסם שירים ומאמרים בעתונים שונים."},{"i":38507,"n":"פלוג, יעקב מלמברג","b":"מחכמי למברג. תשובה אליו חסל\"א-תרי."},{"i":38508,"n":"פלודרמכר, גרשון","f":"שלום","bt":"1876","bp":"וילנא","dt":"1943","dp":"וילנא","b":"תלמיד הסמינר למורים בוילנא. מורה בריגה, פעיל ב\"בונד\", נאסר והוגלה לסיביר. חזר לוילנא-1905 והיה מחלוצי החינוך האידי, ממיסדי \"קולטור ליגה\"-1919. חיבר ספרי לימוד באידיש, ומאמרים על נושאי חינוך. עורך \"נייע שול\" ו\"שול פינקס\" יחד עם ז. ריזין. מנהל בי\"ס עממי ע\"ש דבורה קופרשטין. נספה בשואה."},{"i":38509,"n":"פלוטקין, אברהם משליבא","f":"שניאור זלמן","k":"בעל עומקא דדינא","bt":"תריד","bp":"פלאצק","b":"מו\"צ בשליבה(=שעליבע-דיקשיץ)-פלך מינסק-תרלד. חיבר \"עומקא דדינא\" על הלכות נידה - בכת\"י. בניו - ר שניאור זלמן מהאראוויל, ר יעקב ישראל משועדסקא. חתנו - ר יחיאל מיכל תאומים מברעזין."},{"i":38510,"n":"פלוטקין, אריה ליב מניו יורק","b":"רב בבראנזויל, ניו יורק. פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":38511,"n":"פלוטקין, יעקב ישראל משוערסא","f":"אברהם משליבא","b":"חתן ר ברוך מרדכי מטאלין משוערסקא, רב בשבדסקה(=שוערסקא)-מחוז סוראז-תרע על מקום חותנו."},{"i":38512,"n":"פלוטקין, יצחק אלחנן הנדל מקרעו","f":"שמואל אהרן מבוברויסק","k":"בעל שיח יצחק","bt":"תרא","b":"נכד-אבי אמו ר אבא ואלפער ממינסק. תלמיד ר גרשון תנחום ממינסק. נסמך מאת: ר משה ליב ממינסק, הגדול ממינסק, ר יצחק אלחנן מקובנא. מו\"צ במינסק-תרלד, רב בקרעווא-פלך וילנא-תרנב. חיבר גם \"דבר בעתו\". בנו - ר שמואל אהרן מדרעטשין, ר זלמן. מחותנו - ר דוד פאליאק מסאמארע."},{"i":38513,"n":"פלוטקין, שמואל אהרן מדרטשין","f":"יצחק אלחנן מקרעווא","dt":"תרצב - טו תשרי","b":"חתן רש\"י סודרסקי מקובנא. רב בדרעטשין, סמרגון."},{"i":38514,"n":"פלוטקין, שמואל אהרן ממירוסלאוו","b":"רב במירוסלאוו על מקום ר משה שפירא."},{"i":38515,"n":"פלוטקין, שניאור זלמן מהרוועל","f":"אברהם משליבא","b":"חתן ר פנחס ראפקין. רב בהאראוויל(=הארוועל)-מחוז רעציצא-תרע על מקום חותנו."},{"i":38516,"n":"פלויט, חזקיה פיבל משוראן","f":"חיים","k":"בעל לקוטי חבר בן חיי","r":"אב\"ד בשוראני","bt":"תקעח","bp":"קאלין","dt":"תרנה - כז כסלו","dp":"ליפובה","b":"תלמיד החת\"ס והכתב סופר. חתן ר יצחק חיים זיידל. ר\"מ בישיבת פרשבורג בזמן החת\"ס, ור יהודה ליב גרוס על מקומו אחריו, רב בשוראן-תרט ור יהודה גרינוולד על מקומו אחריו.","bk":[["ליקוטי חבר בן חיים (חב\"ח)",""],["ליקוטי חבר בן חיים – ש\"ס, שו\"ע, הספדים, עה\"ת, הגדש\"פ, משניות, רמב\"ם",""]]},{"i":38517,"n":"פלונגיאן, זכריה מוילנא","f":"יעקב סימגר","k":"בעל ספר זכירה","b":"מחכמי ליטא, רב בווילקוביסק-שנות ה-תק."},{"i":38518,"n":"פלונגיאן, מרדכי","f":"שלמה","k":"בעל בן פורת","bt":"תקעד - כח אלול","bp":"פלונגיאן","dt":"תרמד - כז חשון","dp":"וילנא","b":"מצאצאי ר מרדכי יפה בעל הלבושים. תלמיד ר הירש ברודיא מסלנט, ר אהרן מקרטינגא ופינסק, ועוד. התישב בוילנא והיה מורה אצל הגביר ר השל סירקין לבנו ר אבא. פנה להשכלה. ישב אצל הגביר ר ליפעלי אליעאשברג באיווניץ. בספרו \"בן פורת\" מפרש ומרחיב את דברי ר מנשה מאילייה, היה כנגדו מחלוקת מצד החרדים ועבר לוילנא, מלמד בביהמ\"ד לרבנים, מזכיר וראש המגיהים בדפוס \"ראם\" על מקום ר אליהו שטרשון, והוסיף מהערותיו והגהותיו לש\"ס. חיבר גם \"תלפיות\", \"כרם לשלמה\", ועוד. פרסם מאמרים רבים בכתבי עת שונים. לתולדותיו ב\"שפת אמת\" לר נחמיה נתנזון מוילנא. (דברי בקורת כנגדו ב\"האסיף תרמח)."},{"i":38519,"n":"פלונגיאן=פלונגא=פאלאנגי- קהילה","b":"ליטא - מחוז טלז, הועברה לקורלנד. מהישובים היהודיים הראשונים בליטא. ב-1897 ישבו בה כ-2500 יהודים, לפני השואה כ-1700, רבים היגרו לדרום אפריקה, ארה\"ב, ארגנטיה או עלו לארץ. ישיבה בראשות ר חיים יצחק בלוך. רבנים: ר דב בר-תעו, ר יהודה ליב זיו, ר יחאל הלר-תרפטר תרכג, ר גרשון מנדל זיו, ר חיים יצחק בלוך, ר זבולון באריט, ר שמואל אביגדור פיבלסון, ר לוי שפיץ הי\"ד, ר אברהם מרדכי וסלר הי\"ד - רבה האחרון נספה בשואה."},{"i":38520,"n":"פלוס, אברהם מטריפולי","bt":"תן","dt":"תקך","b":"מחכמי טריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":38521,"n":"פלוס, יוסף מטריפולי","f":"אברהם","bt":"תף","dt":"תקן - בערך","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":38522,"n":"פלוס, יצחק מטריפולי","bt":"תקל","dt":"תרי - בערך","b":"רב, דרשן ופוסק בטריפולי. דרשות ושו\"ת ממנו - בכת\"י - בספרית הותיקן."},{"i":38523,"n":"פלוס, נסים מטריפולי","b":"נשיא קהלת טריפולי."},{"i":38524,"n":"פלוס, שאול מטריפולי","b":"נשיא קהלת טריפולי."},{"i":38525,"n":"פלוס, שלום מטריפולי","bt":"תץ","dt":"תקנ - כ אלול","b":"דיין בטריפולי, תלמיד ר מסעוד חי רקח בעל \"מעשה רקח\". עסק במסחר לפרנסתו ובהיותו באיטליה פגש את ר דוד פארדו באיספלטארו ונתידד עמו. כשחזר לטריפולי נתמנה לראב\"ד עם הדיינים ר חיים ואתורי, ור נתן אדאדי. נזכר ב\"שדה יצחק\" לתלמידו ר יצחק גויטע."},{"i":38526,"n":"פלוצקי, אליעזר יהודה מדוואהרט","f":"מאיר דן - כלי חמדה","k":"בעל בית יהודה","dt":"תרס - ו כסלו","b":"רב בדווארט. פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":38527,"n":"פלוצקי, חנוך הניך","f":"מאיר דן","b":"מקורב לאדמו\"ר בעל \"אמרי אמת\" מגור. פעל להוצאת כתבי אביו."},{"i":38528,"n":"פלוצקי, ישראל נתן מאוסטרובה","f":"מאיר דן - כלי חמדה","k":"בעל אמרי ישראל","dt":"תש..","b":"רב בדוואהרט, אוסטרובה. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"אור המאיר\" - וארשא תרצו, פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"יגדיל תורה\" - פראגא-וארשא תרפז, פרסם מאמרים ב\"קול תורה\" - וארשא תרסח. חיבר \"אמרי ישראל\" ונדפס בספר אחיו - \"בית יהודה\". נספה בשואה."},{"i":38529,"n":"פלוצקי, מאיר דן רפאל מאוסטרוב","f":"חיים יצחק","k":"בעל כלי חמדה","r":"רב בדווארט ואחר כך אבד\"ק אוסטרוב","bt":"תרכו","bp":"קוטנא","dt":"תרפח - ו ניסן","dp":"וארשא","b":"תלמיד ר חיים אלעזר ואקס בעל \"נפש חיה\", ר יהושע מקוטנא בעל \"ישועות מלכו\", ישיבת ר אברהם מסוכטושב בעל \"אבני נזר\". רב בדווארט-תרם, אוסטרבצה-תרעח, ראש המתיבתא בוארשא. נשיא אגודת הרבנים בפולין. בשליחות בארה\"ב עם ר אשר לעמל מקירכדורף ור מאיר הילדסהימר מברלין - לשם חיזוק היהדות בארה\"ב. חיבר גם \"חמדת ישראל\", \"שאלו שלום ירושלים\" - אודות זיוף הירושלמי על קדשים (וכנגדו יצא \"חרב נוקמת\" מפרידלנדר. פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו, \"חדרי תורה\" - קראקא תרפו, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג, \"קול תורה\" - פאביאניץ תרפו, \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו. בנו - ר חנוך הניך","bk":[["חמדת ישראל",""],["כלי חמדה",""],["כלי חמדה , חמדת ישראל",""]]},{"i":38530,"n":"פלוצקר, יצחק הכהן מפלוצק","f":"שמואל לסקר כץ","bp":"לאצק","dt":"תקסה","dp":"פלוצק","b":"תלמיד ר פנחס זליג בעל \"עטרת פז\". חתן ר משה באק מפלוצק, ר שמלם זלמן מפיורדא בעל \"בגדי כהונה\". גביר מחכמי פלוצק, ובעל צדקה. חתניו: ר יואל מפלוצק בן ה\"חמדת שלמה\" ובזיוו\"ש (לאחר פטירתו) ר חיים בן יהודה מרביטש (נכד ר מאיר פוזנר בעל \"בית מאיר\"), ר יהודה ליב קמפנר מפלוצק, ר יעקב שלום ליפשיץ מפיעטרקוב, ר אריה ליב לנדא וישגראד ווענגראווי, בנו - ר נתן-חתנו של ר יהודה ליב מרגליות בעל \"פרי תבואה\"."},{"i":38531,"n":"פלוצקר, מנחם מנדל","b":"מגדולי דורו,פרנס המדינה בפוזנא-שפ\"א-שצ\"א"},{"i":38532,"n":"פלוצקר, נתן הכהן מליטומרסק","f":"יצחק מפלוצק","b":"חתן ר יהודה ליב מרגליות בעל \"פרי תבואה\". תלמיד ר מנחם מנדל מקוצק, והרי\"ם מגור."},{"i":38533,"n":"פלורנטין, דוד מירושלים","dt":"תקכא - ה אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":38534,"n":"פלורנטין, דוד משלוניקי","f":"יצחק","bt":"תרלה","bp":"שלוניקי","b":"ממיסדי חברת \"קדימה\" להפצת הלשון העברית-תרנט, יחד עם אהרן כהן. עורך העתון \"איל אב'יניר\", ופעל למען השארת ר יעקב מאיר בשלוניקי-תרע (כשרצה לחזור לירושלים בגלל מחלוקת עם כמה עסקנים)."},{"i":38535,"n":"פלורנטין, דוד משלוניקי - הזקן","f":"שמואל - מעיל שמואל","b":"חתן ר דוד פיג'ון משלוניקי. ראש השו\"ב בשלוניקי-[שע - שפ]. בנו - ר שלמה משלוניקי וקושטא."},{"i":38536,"n":"פלורנטין, דניאל משלוניקי","dt":"תקם","dp":"שלוניקי","b":"מחכמי שלוניקי, בשליחות הקהלה באירופה - בגלל המצב הקשה (מגפות, שריפות ולחץ השלטונות), היה באמשטרדם-תקיט יחד עם ר יוסף ברכה - לקבלת עזרה מהקהלה הספרדית לטובת יהודי שלוניקי."},{"i":38537,"n":"פלורנטין, חיים שמואל - הזקן","k":"בעל מעיל שמואל","dt":"תעט-פז - י אב","dp":"שלוניקי","b":"מגדולי חכמי דורו בשלוניקי, ומלמד לתלמידים. לאחר שחלה נוסף לו השם חיים."},{"i":38538,"n":"פלורנטין, יוסף משלוניקי","dt":"תקיד","dp":"שלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה ן מאיור."},{"i":38539,"n":"פלורנטין, יעקב מירושלים","f":"דוד","b":"מחכמי ירושלים-תקץ."},{"i":38540,"n":"פלורנטין, יעקב משאראי","b":"גביר מקורב לשלטון, הגיע עם המושל החדש מאישקופיא לשאראי-תצז עם חתנו - יעקב בורלא. היה מתורגמן הציר הצרפתי."},{"i":38541,"n":"פלורנטין, יעקב משלוניקי","b":"גביר בשלוניקי-תרסד, תרם עם שותפיו לת\"ת בשלוניקי."},{"i":38542,"n":"פלורנטין, יעקב משלוניקי - א","dt":"תנו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38543,"n":"פלורנטין, יעקב משלוניקי - ב","b":"גביר בשלוניקי-תפה, וסייע בהדפסת \"מעיל שמואל\" לר שמואל פלורנטין."},{"i":38544,"n":"פלורנטין, יצחק מ' משלוניקי","b":"גביר בשלוניקי. שותפו של ר יצחק יוסף שמחה, וגיסו של ר שמואל שמחה, ותרם לת\"ת של גיסו בשלוניקי-תרסד."},{"i":38545,"n":"פלורנטין, יצחק משלוניקי","dt":"תפה","dp":"שלוניקי","b":"רב בשלוניקי. אחיו של ר שמואל. חיבר שו\"ת - ונדפסו עם ספר אחיו \"מעיל שמואל\"."},{"i":38546,"n":"פלורנטין, יצחק משלוניקי","b":"גביר בשלוניקי-תרסד, תרם עם שותפיו לת\"ת בשלוניקי."},{"i":38547,"n":"פלורנטין, שלמה משלוניקי","dt":"תעט","dp":"קושטא","b":"תלמיד ר דניאל אישטרושא. מחכמי שלוניקי, הוסיף על הספר חוסן ישועות לר שבתי די בוטון. תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ. המיר את דתו והיה מראשי כת הדונמה."},{"i":38548,"n":"פלורנטין, שלמה משלוניקי וקושטא","f":"דוד","k":"בעל דורש משפט","b":"מחכמי שלוניקי, עבר לקושטא-תח בערך."},{"i":38549,"n":"פלורנטין, שמואל משלוניקי - הנכ","f":"שמואל","dt":"שצט - יא סיון","dp":"שלוניקי","b":"נכד ר דוד-ראש השו\"בים בשלוניקי. נפטר צעיר."},{"i":38550,"n":"פלורנטין, שמואל משלוניקי-הנכד","f":"דוד","k":"בעל מנחת שמואל","dt":"תקיד - כג אייר","dp":"שלוניקי","b":"נכד ר יצחק-אחיו של ר שמואל פלורנטין הזקן. תלמיד ר שמואל פלורנטין (אחי זקנו) וחיבר הקדמה והגיה את ספרו \"מעיל שמואל\", ור אברהם גטניו. רב הכולל בשלוניקי על מקום ר משה אמריליו, וראש ישיבה. חיבר גם \"עולת שמואל\" (וכתה\"י היה בידי החיד\"א), \"בית הראה\". בניו ר דוד ור משה, וחתנו ר אברהם שיראנו."},{"i":38551,"n":"פלורנטין, שמואל משלונקי - הזקן","dt":"שעה - יג כסלו","dp":"שלוניקי","b":"רב וראש ישיבה בק\"ק \"שלום\" בשלוניקי, על מקום ר דוד ן שושאן, ולצורך כך היה צריך להתיר את נדרם שלא למנות רב במשך עשר שנים - והתיר להם ר אהרן ן חסון משלוניקי. חתם על מעשה בי\"ד בשלוניקי-שמח. בנו ר דוד היה ראש השו\"ב בשלוניקי."},{"i":38552,"n":"פלורסהיים, הרץ מ. מפפד\"מ","f":"מיכאל","dt":"תקלד - ו חשון","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ."},{"i":38553,"n":"פלורסהיים, שלמה מפפד\"מ","b":"מראשי קהילת פפד\"מ. חתם על ביטול החרם כנגד ר נתן אדלר-תקס."},{"i":38554,"n":"פלזן, משה שמחה מפשמישל","f":"מאיר","b":"חסיד בלוזוב ובעל תפלה אצל האדמור. חתן הגביר ר זליג מהלר (המכונה \"רוטשילד של פרמישלא\")."},{"i":38555,"n":"פלט ן, יוסף מספרד ואלגיר","f":"יהודה","k":"בעל תקון ברכות","b":"מיוצאי קלעת בני חמאד-אלגיר, רב בספרד, פרובנס-דתתקך (בלוניל ובנרבונא), דמשק ומשם התכתב עם הרמב\"ם. נזכר אצל הראבי\"ה, בשו\"ת הראב\"ד, וספר המנהגות לר אשר מלוניל. מתלמידיו - ר זרחיה בעל המאור, הראב\"ד, ר אשר בן משלם."},{"i":38556,"n":"פלטא, פיבוש פלטא","bt":"תרלד","b":"רב בניו יורק-תרס\"א"},{"i":38557,"n":"פלטיאל","dt":"תרלא - יג חשון","b":"רב בנויגראד"},{"i":38558,"n":"פלטיאל הנגיד ממצרים","b":"נגיד במצרים-ד'תשמד."},{"i":38559,"n":"פלטיה","f":"חנניה יגל","b":"מגדולי חכמי איטליה-ת\"ל"},{"i":38560,"n":"פלטין, י' ז'","b":"פרסם מאמרים ב\"דברי תבונה\" - קובנה תרף, \"תבונה\" - ירושלים תשא."},{"i":38561,"n":"פלטין, שמואל צבי","bt":"1831","bp":"מאריאמפול","dt":"1897","b":"חיבר ספר דקדוק פולני. הו\"ל בפולנית \"איזראליטה\". פרסם סיפורים מחיי היהודים, ותרגם ספורים מאת קומפרט ואחרים. חיבר ספר היסטוריה בפולנית \"היסטוריה ז'ידוב\"."},{"i":38562,"n":"פלטקוביץ, יוסף","dt":"תרצט","b":"רב ברוזשאן"},{"i":38563,"n":"פלטרוביץ, חיים נחום מאסטרלנקע","f":"צבי מנאויגראד-עץ חיי","k":"בעל תהלות חיים","b":"אחיו של ר שמחה מארה\"ב. רב באסטרלנקע-תרמ."},{"i":38564,"n":"פלטרוביץ, יהודה ליב מסימנא","f":"חיים נחום","k":"בעל שם יהודה","bt":"תרלח","b":"מצאצאי בעל הט\"ז. רב בסימנא-פלך סובאלק-תרס. חיבר שו\"ת בשם \"שם יהודה\", \"הגיון יהודה\" - בכת\"י."},{"i":38565,"n":"פלטרוביץ, יהושע משה מירושלים","f":"צבי מנאויגראד-עץ חיי","b":"מחכמי ירושלים. סייע לאחיו ר חיים נחום בהוצאת ספרו \"תהלות חיים\"."},{"i":38566,"n":"פלטרוביץ, צבי משאקי","b":"רב בשאקי-אחרי תרלה."},{"i":38567,"n":"פלטרוביץ, שמחה מניו יורק","f":"צבי מנאויגראד-עץ חיי","k":"בעל כתר צבי","b":"רב בניו יורק, באפלו-ניו יורק-תרס."},{"i":38568,"n":"פליבוים, שמואל מוישניצה","b":"רב בוישניצה."},{"i":38569,"n":"פליטניק, זלמן מאנגליה","b":"חתן ר משה לנדינסקי מראדין. רב בליברפול-תרס."},{"i":38570,"n":"פליטשינצקי, יוסף צבי הירש","f":"משה שלום","k":"בעל קרוא מקרא","dt":"תרמז - כא שבט","dp":"ברדיטשוב","b":"מלמד בביהמ\"ד לרבנים בזיטומיר. חיבר \"קרוא מקרא\" זיטומיר תרלד."},{"i":38571,"n":"פליטשק, אברהם","b":"רב בבסקוביץ,ורב כולל של מדינת מהרין-תר\"כ"},{"i":38572,"n":"פלייאש, אברהם מטיווה","f":"יוסף","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":38573,"n":"פלייסיג, יעקב","b":"רב בפריישטטל,ווינה-תר\"כ"},{"i":38574,"n":"פלייסיג, יעקב הירש","dt":"תשד","b":"רב בפעלדעש-תר\"צ"},{"i":38575,"n":"פלייסיג, יעקב צבי מוינה","f":"יוסף משוסבורג","bt":"תקעח","bp":"באסקביץ","dt":"תרסא- יז חשון","dp":"וינה","b":"תלמיד החת\"ס. חתן ר מאיר אלמאש-פופר ממטרסדורף. רב בטשענגער-תרו, נאדאודוור, פריישטט-תרטו, וינה-תרלב. (סיפר כי פעם עלתה שאלת הפילוסופיה בפני החת\"ס - ואמר לתלמידיו כי \"אלה הפילוסופים יבואו כולם ויתחרו בי אם לא אראם כי עליתי על כלם...\")."},{"i":38576,"n":"פליישמן, יוסף מסערד-האלי","b":"דומ\"צ בסערדאהעלי-תר\"ע"},{"i":38577,"n":"פליכנפלד, זאב","b":"רב פעלים,רב בדיסלדורף-תרכ\"ז"},{"i":38578,"n":"פלינט, ישראל אהרן מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":38579,"n":"פלינטנשטיין, יצחק מאיר","f":"אהרן דוד","k":"אדמור מאפטא קופיטשני","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. נכד ר אברהם יהושע השל מקופיטשניץ. חתן ר נפתלי הרץ פוגל. אדמור מאפטא-קופיטשניץ בירושלים."},{"i":38580,"n":"פלינקובסקי ברוך בן אפרים שמואל; טריבוש הלל דוד בן עוזר","bt":"1841","dt":"ה'תרסא 1901","bk":[["השתיה כדת",""],["עבודת הכהן",""],["עדן גנים",""],["עין הפסגה",""],["פרץ נבעה",""]]},{"i":38581,"n":"פלינקובסקי, ברוך","b":"רב בקישינוב-תרנ\"ד"},{"i":38582,"n":"פלינקובסקי, שמואל מאודסה","f":"יעקב מיכל","bt":"תרי","b":"רב באדעס(=אודסה)-תרמז, חבר בועד הרבנים-תרע."},{"i":38583,"n":"פליסקין, יהושע זליג","b":"תלמיד ישיבת וולוזין. בנו - ר שמואל מבולטימור."},{"i":38584,"n":"פליסקין, שמואל מארה\"ב","f":"יהושע זליג","k":"בעל דער חפץ חיים","bt":"תרעד","bp":"גלובאקי-פלך וילנא","b":"תלמיד ישיבת פוניבז, ראדין. נסמך מאת: ר משה לנדינסקי מראדין, ר מאיר מאירוביץ מנוברדוק, ר אליעזר קפלן מראדין, ר מנחם זאקס. חתן ר חיים יעקב ישראל ברגר מקליבלנד. רב בקהלת \"בני ישראל\" בבולטימור. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":38585,"n":"פליף, אברהם","dt":"שמט","b":"מתלמידי הארי, כתב יד של על התורה היה בידי החיד\"א והוא מביא ממנו בספריו."},{"i":38586,"n":"פליק, ברוך מחוליוב","b":"מחכמי חוליוב-תרלא."},{"i":38587,"n":"פליק, משה מזטור","b":"רב בזטור."},{"i":38588,"n":"פלישהקר, אליהו","b":"מו\"צ בלודז-תר\"ע"},{"i":38589,"n":"פלישמן, איזידור מפרשבורג","b":"עסקן בקהלת פרשבורג, עזר לתלמידי הישיבה בזמן מלחה\"ע ה-I. מראשי הקהלה-תרצב."},{"i":38590,"n":"פלישמן, גיזי מפרשבורג","b":"חברה בועד הלא רשמי של יהודי פרשבורג ועסקה בהצלת יהודים בזמן השואה - כל זמן שניתן היה."},{"i":38591,"n":"פלישמן, חיים יעקב","bt":"תר - בערך","dt":"תרסח - ד אייר","b":"תלמיד ר שלמה דייטש מנייטרא, ר יחזקאל בנט, ר פנחס ליב פרידען מקומראן. . רב בזשאמבאק-ליד בודפשט כ-50 שנה."},{"i":38592,"n":"פלישמן, יהודה מפרשבורג","f":"מאיר מסערדאוהל","bt":"תרן","bp":"סערדאוהל","dt":"תשה - יז תשרי","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי. חתן ר יוסף קאהן מפרוינקירכן. רב בפרשבורג, מגיד שיעור בחברה \"נחלת עזריאל\". נספה בשואה. בנו ר ישעיה תלמיד הדעת סופר ועלה לירושלים."},{"i":38593,"n":"פלישמן, יהודה מפרשבורג","dt":"תשד","dp":"אושביץ","b":"עלה לארץ וחזר לפרשבורג, מלמד בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה. נספה בשואה."},{"i":38594,"n":"פלישמן, יוסף מסערדאוהל","k":"בעל לקוטי מהריף","bt":"תרי","bp":"סערדאוהל","dt":"תרפו - יג אייר","dp":"סערדאוהל","b":"תלמיד הכת\"ס. מחכמי פרשבורג, רב בסערדאוהל-תרמב."},{"i":38595,"n":"פלישמן, יושע מסטמאר","f":"וולף","b":"מחסידי צאנז בסאטמר. סיפור ממנו על מופת שנעשה לאביו מאת ר אשר יונגרייז בעל מנחת אשר."},{"i":38596,"n":"פלישמן, ישעיה מירושלים","f":"יהודה מפרשבורג","b":"תלמיד הדעת סופר. עלה לירושלים."},{"i":38597,"n":"פלישמן, מאיר מוינה","f":"יוסף מסערדאוהל","b":"תלמיד השב\"ס, רב בקהל \"עדת ישראל\" בוינה-תרעב. נספה בשואה."},{"i":38598,"n":"פלישמן, מאיר מסערדאוהל","f":"יחזקאל מנעמעש-אבאני","b":"אחיינו של ר יהודה אסאד מסערדאוהל. בנו ר יהודה מפרשבורג."},{"i":38599,"n":"פלישר, בנימין הכהן מניו יורק","k":"בעל רביעי בקודש","b":"רב בניו יורק-תש. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":38600,"n":"פלישר, יהודה אריה מבלכטוב","b":"פרסם מאמרים ב\"הנצח\" - לבוב תרפז."},{"i":38601,"n":"פלישר, יהודה ליב מטימישואר","f":"יעקב צבי","k":"אבן עזרא-תרפו","bt":"תרמו","bp":"ערשעקאויוור (=נאוי זאמקי)","dt":"תשטו - יז כסלו","dp":"טימישואר ירושלים","b":"נכד ר ברוך עקפעלד מטשוס בעל \"פאת השדה\". תלמיד ישיבת ר יצחק שוויגר מטאפלטשאן. מחכמי טימישואר ויסד בה בית ספר יהודה אורטודוכסי. ניצל מהשואה, ואחריה חזר לטימישואר. לא הצליח לעלות לארץ ונפטר שם. עסק בחקר ספרי האבן עזרא, ופרסם חבורים רבים והניח נוספים בענין זה. ממיסדי הירחון \"נטעי בחורים\" בטאון תלמידי הישיבות בהונגריה-תרסד ופרסם שם מאמרים, פרסם מאמרים ב\"אהל שם\" - תשב, \"יגדיל תורה\" - פראגא-וארשא תרפז. בנו פרופ' עזרא פליישר."},{"i":38602,"n":"פלישר, יעקב יהושע מדזיקוב","f":"ישראל","bt":"תרעד","bp":"דזיקוב","dt":"תשלז","b":"ר\"מ בתלמוד תורה בברנוב. ניצל מהשואה ועסק בחינוך והצלה אחריה. עלה לארץ-תשט. חתן ר דוד איינהורן. ערך \"ספר הזכרון לקהילת טרנובזג-דזיקוב, וכן כתב נספחים לספרי אדמורי דזיקוב."},{"i":38603,"n":"פלך, יוסף ממצרים","b":"רב בקהלה האשכנזית במצרים בדור שלאחר הרדב\"ז."},{"i":38604,"n":"פלכו, שם טוב מאנגליה וספרד","b":"מגדולי הראשונים-שנת פ', בא מיורק-אנגליה לספרד-ה'פ'. רבו של ר אהרן הכהן בעל \"ארחות חיים\"."},{"i":38605,"n":"פלכן, אליהו משלוניקי","dt":"רפט - ו חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38606,"n":"פלנט, לוי מטולטשין","b":"רב בטולטשין. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא תרע."},{"i":38607,"n":"פלניא, אליעזר","b":"פרסם מאמרים ב\"אור תורה\" - לונדון תרצד."},{"i":38608,"n":"פלנסברג, חיים ירמיהו משאקי","f":"אברהם","k":"בעל נזר הנצחון","bt":"תרב","bp":"קידאן","dt":"תרעד - כא תמוז","b":"רב בדרשונישוק-תרל על מקום ר פנחס פינפר, רב בשאקי-תרמט, באלבירישוק-תרנד על מקום ר משה שמואל הורביץ בעל \"ידי משה\". פרסם מאמרים בכתב עת ובהם \"הלבנון\", ועוד. בתו אסתר היתה אשה למדנית ומשכילה אשת הרב יצחק רובינשטין מוילנא - נודעה בשם \"העילויית משאקי\" ."},{"i":38609,"n":"פלנסוט, שם טוב מספרד","bt":"[ק]","dt":"קן - בערך","b":"מחכמי ברצלונה, ונזכר בשות הרשב\"א טופס ב\"ד שחתם שם עם ר נאשטרוק שלמה (=שלמה אשטרוק)."},{"i":38610,"n":"פלנצגרבן, יעקב יצחק מרדומישל","f":"אליעזר מקולבסוב","k":"בעל בית יעקב","bt":"תרנב","bp":"רדומישל","dt":"תשכח","b":"תלמיד ר שלמה אנגל. חתן ר יעקב בעק מקולבסוב. העמיד תלמידים מגיל 15. היגר לארה\"ב-תרצ ושב לרדומישל. ר\"מ בישיבת ר שלמה קלוגר בניו יורק-תרפד במשך כיובל שנים. חיבר \"בית יעקב\" ניו יורק תשט."},{"i":38611,"n":"פלנר, יואל הלוי מאויהל - הנכד","f":"שמעון חיים מבעלעד","bt":"תרכב","bp":"צעהלים","dt":"תרפה - יג תמוז","dp":"אויהל","b":"גדל אצל זקנו ר מנחם כץ פרוסטיץ מצעהלים. תלמיד הכת\"ס, השב\"ס, ור שמואל ארנפלד ממטרסדורף בעל \"חתן סופר\". חתן ר עקיבא סופר מפאפא ועבר לשם. רב בשטיינמנגר (=סומבוטהעלי)-תרמו ומרביץ תורה בבית מדרשו של ר גרשון שטדלר בסומבוטהי, בעלעד(=באלאד)-תרסב על מקום אביו וראש ישיבה שם, אויהל-תרפב. היה בראש מחזיקי הדת באוברלנד. פעל אצל שלטונות הצבא להעמדת מטבח כשר לחיילים היהודים. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":38612,"n":"פלנר, יואל הלוי ממטרסדורף","f":"חיים","bt":"תקסו","bp":"מטרסדורף","dt":"תרו - כט ניסן","dp":"מטרסדורף","b":"תלמיד החת\"ס. רב במטרסדורף-תקצח. החת\"ס מביא בספרו קושיה חמורה שיישב לו תלמידו ר יואל הלוי ממטרסדורף וכו'."},{"i":38613,"n":"פלנר, שמעון חיים סגל מבעלעד","f":"יואל ממטרסדורף","bt":"תקצז","bp":"מטרסדורף","dt":"תרסא - כז אייר","dp":"צעהלים","b":"נתייתם בילדותו וגדל אצל ר שמעון סופר אב\"ד מטרסדורף בעל מכתב סופר. תלמיד הכת\"ס, ור אהרן זינגר ממטרסדורף ומהרם שיק. חתן ר מנחם כץ פרוסטיץ מצעלהים, ועבר לשם. רב בצעהלים לצד חותנו. רב בעלעד-תרכד ובנו ר יואל על מקומו אחריו. מאמר ממנו ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":38614,"n":"פלסט, נחום מבילגוריי","dt":"תרלח - ד שבט","b":"חתן ר יצחק נתן ברלינר. רב בבילגוריי, פאריצק, גרבוביץ. חתנו - ר משה."},{"i":38615,"n":"פלסטר, מנשה מצאנז","dt":"תש..","b":"רב בצאנז. נספה בשואה."},{"i":38616,"n":"פלסנר, אליהו מאסטראווא","f":"שלמה מאסטראווא","b":"הוא או אביו - אב\"ד אסטראווא-פרוסיה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":38617,"n":"פלסנר, שלמה מפוזנא","k":"שלמה פוזנר","bt":"תקנז","bp":"ברסלוי","dt":"תרמג - כה אב","dp":"פוזנא","b":"רב בפוזנא, מקורב לר עקיבא איגר שביקשו לחבר ספר להגנת התלמוד (שנאסר בפוזנא-תקפה). מתלמידיו: ר צבי קארא מלאבוי. בנו - ר אברהם יצחק הלוי מזאגראווי."},{"i":38618,"n":"פלסנר, שמואל מפוזנא","f":"שלמה מפוזנא","b":"מחכמי פוזנא. חתנו - ר ישעיה פירסט בעל חזון ישעיה."},{"i":38619,"n":"פלסקר, דוד מבלוזוב","f":"אשר זלקא","b":"רב בבלוזוב, צאנז-תקפח (חתם להביא את הדברי חיים כאב\"ד) וכיהן אצלו. בנו ר נחום ראובן על מקומו אחריו בצאנז."},{"i":38620,"n":"פלסקר, נחום ראובן מרישא","f":"דוד מבלוזוב","k":"בעל נחלת ראובן","r":"אב\"ד רישא","bt":"תקעט","dt":"תרלב - טו אייר","b":"תלמיד הדברי חיים מצאנז. חתן ר ישכר בירש הכהן מאושפיצין. רב באושפיצין, צאנז, רישא (שם היתה מחלוקת עם ראשי הקהל). רוב כתביו אבדו בזמן מלחמת העולם הראשונה. חיבר \"נחלת ראובן\" למברג תרסד.","bk":[["נחלת ראובן - דרוש ושו\"ת",""]]},{"i":38621,"n":"פלעגכע, ראובן שמעון מדרמשטט","b":"תלמיד ר יונתן איבשיץ. רב בדרמשטט והמדינה-תקכ."},{"i":38622,"n":"פלעס, ה' מפרשבורג","b":"מורה בביה\"ס של קהלת פרשבורג-תקפה."},{"i":38623,"n":"פלעש, אברהם מוינה","dt":"תא - יד חשון","b":"מגדולי חכמי ווינה"},{"i":38624,"n":"פלעש, אהרן מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":38625,"n":"פלעש, דוד אהרן מפפד\"מ","b":"פרנס מראשי קהילת פפד\"מ-תקיג בזמן המחלוקת בין מחנה קולפא ומחנה קן."},{"i":38626,"n":"פלעש, חיים מקוניץ","bp":"מאדיאר-אוואר","b":"נינו של ר יוסף יוזפא פלאש מועספרין. תלמיד השב\"ס. רב בקוניץ-תרנד, קרומונוי-תרעה. חתנו - ר זאב כהנא מירושלים מהדיר \"תשובות מהרם מרוטנברג\"."},{"i":38627,"n":"פלעש, יוסף","b":"רב בוויסנבורג-תר\"מ"},{"i":38628,"n":"פלעש, יוסף יוזפא מועספרין","f":"שלמה מנייטרא","bt":"תקמח","bp":"גראס-מזריטש","dt":"תריט - א טבת","dp":"ועספרין","b":"תלמיד החת\"ס. חתן ר זלמן וייס מינקביץ. והתגורר בנייטרא לצד אביו. רב בשאטמנסדורף-תקפה, רוגנדורף-תקפו, ועספרין(=ועספראם)-תקצה."},{"i":38629,"n":"פלעש, יוסף מרוסטיץ","f":"אברהם","k":"בעל כתות מני קדם","b":"תרגם את כתבי פילון מאלכסדריה ובהם \"חיי משה\" פרג תקצח, \"היורש דברי אלקים\" פרג תקץ, ועוד. חיבר גם \"רשימת אנשי מופת\" שנדפסה עם \"מקראי קדש\" לר משה לנדא."},{"i":38630,"n":"פלעש, משה דוד מוינה","f":"שמואל מרוגנדורף","bt":"תרלט","bp":"רוגנדורף","dt":"תשג","dp":"בוכנואלד","b":"תלמיד השב\"ס, ור שלמה זלמן ברייער מפפדמ. חתן ר שלום הופבויער מוינה. רב ביהכ\"נ קרויץ-גאסע ו\"שטומפר שוהל\" בוינה-תרפא. ברח לאמשטרדם-תרצט. נספה בשואה."},{"i":38631,"n":"פלעש, שלמה מנייטרא","bt":"תקי","bp":"ניקלשבורג","dt":"תקצב - יד שבט","b":"תלמיד ר גרשון חיות מניקלשבורג, ודיין אצלו בניקלשבורג. רב בגרוס-מזריטש-תקמה, נייטרא-תקס. נשא ונתן עם החת\"ס ונזכר בספריו."},{"i":38632,"n":"פלעש, שמואל מרוגנדורף","f":"מנחם מנדל","b":"נכד ר יוסף יוזפא מועסרפין. בנו - ר משה דוד מוינה."},{"i":38633,"n":"פלץ, דוד מדאברי","b":"מחכמי דאברי-תרע"},{"i":38634,"n":"פלץ, מרדכי מלמברג","f":"משה צבי הירש ענסר","bt":"תקץ","dt":"תרנג","dp":"קראקא","b":"בקי בשפות שלימדו אביו. שינה שמו לשם אמו בהשפעת דודו ר שמריה שטיקלר ממוסט (על מנת להרחיקו מאביו החשוד כמשכיל). מקורב לשר שלום מבלז ומחשובי החסידים. חתן הרב מבילקמין הש\"ב של השר שלום. רב בבילקמין על מקום חותנו - והתפטר מהרבנות על מנת להתפנות לעשיית חסד."},{"i":38635,"n":"פלצינסקי אליעזר מנוח","bt":"1912","dt":"ה'תשסז 2007","bk":[["שלום יהודה",""]]},{"i":38636,"n":"פלצינסקי, אהרן","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38637,"n":"פלצינסקי, אליעזר","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":38638,"n":"פלצינסקי, יהודה ליב מוישקס","b":"תלמיד ישיבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). רב בוישקס-תר\"ס. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38639,"n":"פלצינסקי, יעקב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38640,"n":"פלצינסקי, מאיר מדוינסק","dt":"תש","b":"רב בדוינסק"},{"i":38641,"n":"פלצינסקי, משה מוישקעס","b":"רב בווישקעס-ליד דוינסק כ-50 שנה. חתנו - ר דוד צבי מרעזיצע."},{"i":38642,"n":"פלצינסקי, משה מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":38643,"n":"פלצקר, זושא","f":"שמחה","b":"רב בשדליץ,פלאצק-תק\"פ"},{"i":38644,"n":"פלק","b":"דיין בפרג-ש\"י"},{"i":38645,"n":"פלק, אברהם מאוסטרהא","f":"יושיע","dt":"תפ - א תשרי","dp":"אוסטרהא","b":"פרנס באוסטרהא. בנו ר יהושע ונכדו ר משה ש\"ץ באוסטרהא."},{"i":38646,"n":"פלק, אורי פיבל מברסלוי","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":38647,"n":"פלק, אפרים מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":38648,"n":"פלק, אריה ליב מסקול והנובר","f":"יעקב יהושע-פני יהושע","k":"בעל פני אריה","bt":"תעה","bp":"ליסקא","dt":"תקמט - ח אדר","b":"תלמיד דודו ר צבי הירש אב\"ד הלברשטט. רב בסוירז-תצט, פפד\"מ-תקה על מקום אחיו, סקול-תקי, הנובר-תקכא, ובנו ר ישכר בער על מקומו אחריו-תקמט. היה מעורב במחלוקת עם הנודע ביהודה בנוגע לגט שסידר. חיבר \"פני אריה\" נדפס עם ספר אביו \"פני יהושע\". השאיר חיבורים - בכתב יד. חתן ר טוביה יחיאל מיכל הלפרין מברזן, ובזיוו\"ש חתן ר חיים יונה תאומים מברסלוי. היה מהמכשירים את הגט מקליווא-תקכו. חתם על כרוז כנגד השבתאים - ברודי תקיח. נספד מאת ר אלעזר פלקלש. בניו - ר ישכר בער ברנשטין(12366), ר חיים לוונשטם(6045), ר יחיאל מיכל-אביו של ר אריה ליב ברשנטין מלבוב."},{"i":38649,"n":"פלק, בנימין וולף מאיזנשטט","dt":"תקסו","b":"גביר מחכמי איזנשטט, מלמד תורה, חיבר ספרים בכת\"י."},{"i":38650,"n":"פלק, גבריאל מאמשטרדם","f":"איזיק","k":"בעל הליכות קדם","bt":"תקסג","dt":"תרכט - ערב שבוע","b":"משורר ורב באמשטרדם. תשובה אליו ב\"אוצר החכמה\"-תרצז מאת ר צבי הירש חיות מזולקוא. חיבר גם \"קול בת גלים\" - מצבות חכמי ישראל בהולנד. מראשי חברת \"תועלת\"."},{"i":38651,"n":"פלק, חיים מזכרון יעקב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":38652,"n":"פלק, יהושע הכהן מקרניק וארה\"ב","f":"מרדכי","k":"בעל אבני יהושע","bt":"תקנט","bp":"ברעסט-קיאווסק - פולין","dt":"תרכו","b":"מחכמי קארניק-פרייסין וכונה ר יהושע מקארניק, היגר לארה\"ב-תריד, רב בנובורג - אזור ניו יורק, רב בפאקיפסי, התפטר והיה לדרשן נודד מעיר לעיר - ובספרו תיאר את מעשי הריפורמים ברחבי אמריקה. חיבר \"אבני יהושע\" - ניו יורק תרך - (הספר הראשון בעברית בניו יורק), \"בנין יהושע\", \"חומת יהושע\". נספד ע\"י ר משה אהרנסון בעל הפרדסים, ור יונה באנדי."},{"i":38653,"n":"פלק, יהושע השל מפפד\"מ","f":"אברהם משקלוב","dt":"תקסב - כט ניסן","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":38654,"n":"פלק, יהושע כץ-סמ\"ע","f":"אלכסנדר הכהן","k":"בעל הסמ\"ע","bp":"ורמייזא","dt":"שעד - יט ניסן","b":"תלמיד הרמ\"א והמהרש\"ל. חתן הגביר ר ישראל אידליש מלבוב. פוסק הדור, ראש ישיבה בלבוב. חיבר \"מאירת עינים\"(-סמ\"ע), \"דרישה ופרישה\". מבניו: ר שמואל אלכסנדר סנדר, מלבוב, ר יוסף יוזפא שהו\"ל את ספרי אביו בשם \"כתונת פסים\" עם הוספות ממנו, ר משה. מתלמידיו: ר יהושע מקראקא בעל \"מגיני שלמה\" ו\"פני יהושע\", ר אברהם שרנצל בעל \"איתן האזרחי\", ר בער אילנברג בעל \"בער שבע\", ר פנחס מפולדא. אשתו - בילא - עלתה לירושלים אחר פטירתו."},{"i":38655,"n":"פלק, יהושע מאוסטרהא","f":"אברהם בן יושיע","dt":"תקעב - טו אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בנו ר משה ש\"ץ באוסטרהא."},{"i":38656,"n":"פלק, יהושע מזולקוא","f":"דוד","b":"מחכמי זולקוא, חתם-תעו על תקנה שלא יהיה אחד מקרובי הרב בתוך מנהיגי הקהלה."},{"i":38657,"n":"פלק, יהושע מלבוב","k":"בעל עמק יהושע","dt":"תס - ה אייר","dp":"לבוב","b":"מגיד בלבוב, מתורתו ב\"שכל טוב\", ב\"אור יקרות\", \"סייעתא דשמיא\", \"פרי הלולים\", ועוד."},{"i":38658,"n":"פלק, יהושע מליסא","f":"יצחק איזיק","k":"בעל בנין יהושע","b":"דיין בליסא-תק\"ל"},{"i":38659,"n":"פלק, יהושע מליסא - ב","f":"צבי מוילנא","b":"הגיה את ש\"ס פפד\"מ-תנו."},{"i":38660,"n":"פלק, יהושע מפוזנא","f":"מאיר דרשן","b":"ר\"מ בפוזנא-תס\"ח"},{"i":38661,"n":"פלק, יהושע מרדכי מקורמאנד","b":"רב בקורמאנד-תקם. הוציא גט משובש והיה מחלוקת כנגדו מצד ר אלעזר קליר מרוהנוץ, ור אשר ברבי מפרשבורג שפסלו את הגט ופנו ל\"נודע ביהודה\" שאישר את פסילתם וגזר על הרב פאלק שלא לכתוב גטין על דעת עצמו."},{"i":38662,"n":"פלק, יוסף מהמבורג וברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":38663,"n":"פלק, יושע מלובלין","dt":"תקמב - ג אב","dp":"לובלין","b":"ראש קהילת לובלין. נזכר בפנקס הקהילה אודות דין ודברים שהיו לו עם ר יונה בן אברהם אצל ר שאול מרגליות אב\"ד לובלין."},{"i":38664,"n":"פלק, יעקב יהודה מדירנפורט","b":"רב בדירנפורט,מו\"צ בברסלוי-ת\"ר"},{"i":38665,"n":"פלק, יעקב יהושע מלבוב","f":"צבי הירש מרישא","k":"בעל פני יהושע","r":"נולד אמ\"ת ונפטר יוש\"ר (שם הגדולים)","bt":"תמ-א","bp":"קראקא","dt":"תקטז - יד שבט","dp":"אופנבך - פפד\"מ","b":"מגדולי חכמי דורו. נכד ר נפתלי הירץ אב\"ד לבוב, ונינו-מצד אמו של ר יהושע בעל \"מגיני שלמה\" ונקרא על שמו. תלמיד הב\"ח בבריסק ולובלין. חתן הגביר ר שלמה סגל לנדא מלמברג ועבר לשם, ובזיוו\"ש חתן ר ישכר בריש מלמברג ממשפחת סגל לנדא, ובזיוו\"ש חתן ר אליהו איגר. גיסו של ר הירש חריף ביאלה מהלברשטטחתן ר שלמה לנדא מלבוב. רב פרנס ומנהיג בלבוב וראש ישיבה. בשנת תסג היה פיצוץ של חומר נפץ שהרג 63 יהודים ובהם אשתו ובתו והוא ניצל בנס, רב בטרלא(=טארלי), ריטשוואל, קאריב(=זאריב), ליסקא-תעז, למברג-תעח על מקום החכם צבי (הודח בגלל מחלוקת עם ר משה חיים) שכיהן על מקום זקנו ר נפתלי הירץ, בוצאץ, ברלין-תצא על מקום ר משה בן אהרן מלבוב, והיה מחלוקת כנגדו מצד הפו\"מ פייטל בן אפרים, ועבר לכהן כרב במיץ-תצד על מקום ר יעקב באק בן יוסף רישר בעל \"חק יעקב\" וכמה מתלמידיו עברו עמו למיץ, פפד\"מ-תקב על מקום ר יעקב פופרש בעל \"שב יעקב\" (משם נאלץ לעזוב בגלל מחלוקת - לאחר שתמך בר יעקב עמדין), מנהיים, ורמייזא. נתמנה לנשיא ארץ ישראל. חיבר \"פני יהושע\" אמשטרם תעט. לתולדותיו חיבר ר דוד אריה צינץ - \"עטרת יהושע\". בניו: ר נתן מדוברמיל, ישכר דב בערוש מפודהייץ, ר אריה ליב ליבש מסקול והנובר. חתניו: ר שלמה דב בעריש בן צבי הירש מהלברשטט, ר נפתלי הרץ בן משה אלחנן הלפרין. מכתבים רבים ממנו בענין מחלוקת ר יעקב עמדן ור יונתן איבשיץ. מתלמידיו ר זכריה פודהייץ מפפד\"מ. לתולדותיו ב\"הפלס\" - ברלין תרסא-תרסה - מאת ר יוסף לוינשטין.","bk":[["פני יהושע","מפרשי ש\"ס - אחרונים"],["כלל גדול - כללים (כת\"י)",""],["פני יהושע - ש\"ס",""]]},{"i":38666,"n":"פלק, ישכר דב בריש מפודהייץ","f":"יעקב יהושע-פני יהושע","k":"בעל חזקת אבהתא","bt":"תעג","dt":"תקה - כב חשון","dp":"ברלין","b":"תלמיד דודו ר צבי הירש אב\"ד הלברשטט. חתן ר אריה ליבוש מבוצאץ (ר ליבוש ראש מדינה). רב בפודהייץ, נפטר בדרכו לרבנות בפפד\"א (לפי וונדר) או במיץ. מחדושיו בספרי אביו, תשובות ממנו לדיין ר גרשון קובלנץ מזיא ממיץ - בחיי אביו (שהיה רב במיץ) ב\"קרית חנה\", וב\"פרי מגדים\" מביא מתורתו, ובשו\"ת ר חיים בן שמחה רפפורט תשובה ממנו. בניו - ר צבי הירש מבלחוב ולבוב בעל \"תשע שטות\" ומביא מתורת אביו, ר שלמה מזולקוא, הרב מפסארמקוב-חתן ר יצחק הורביץ מאה\"ו. חתנו - ר צבי הירש מבוסק (או ר צבי הירש מייזלש מזולקוא). נכדו ר ישכר דב בן מרדכי צבי יולש חידש את המצבה על קברו-תרטז."},{"i":38667,"n":"פלק, ישראל מסקאהל","b":"רב בסקול, מחותמי ספר יראים-תקסד."},{"i":38668,"n":"פלק, משה מאוסטרהא","f":"יהושע מאוסטרהא","dt":"תקפז - יג אלול","dp":"אוסטרהא","b":"מחכמי אוסטרהא וש\"ץ בביהכ\"נ הר שפר. ומגבאי הח\"ק."},{"i":38669,"n":"פלק, משה מהמבורג","f":"אליהו מהמבורג","dt":"תקכג - ו ניסן","dp":"אלטונא","b":"חתן ר וולף אופנהיים. דיין בהמבורג. פסק יחד עם חבריו כנגד ר מרדכי הקשר שעבר על תקנת הקהל. היה מתומכי ר יונתן איבשיץ בזמן המחלוקת עם ר יעקב עמדין. גיסו-אח אשתו של ר יוזפא כץ אב\"ד הנובר."},{"i":38670,"n":"פלק, נתן מדוברומיל","f":"יעקב יהושע-פני יהושע","k":"בעל שארית נתן","bt":"תסד","dt":"תקכב - כב תשרי","b":"חתן ר משה מאיר הלוי לנדא מדוברומיל ופרמישלא, רב על מקום חותנו בדוברומיל-תקסו, בנו ר שמחה על מקומו אחריו בדוברומיל. רב כתביו נשרפו. חיבר \"שארית נתן\" וארשא תרנז. הסכים על ספר המצוות לרמב\"ם - פפד\"מ תקטז. הדפיס ספר אביו \"פני יהושע\" ח\"ג. מאמר ממנו ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":38671,"n":"פלק, שאול מאורלא וירושלים","b":"מחכמי ירושלים, חתם-תרטז ב\"מעשה אבות\". ידידו של הר\"י שורץ ונזכר בתשובותיו."},{"i":38672,"n":"פלק, שלמה","b":"רב בווילקומיר-תק\"ע"},{"i":38673,"n":"פלק, שמואל אלכסנדר כץ","f":"יהושע פאלק- הסמ\"ע","dp":"לבוב","b":"מגדולי חכמי לבוב-שנת ת'. נקבר לצד אביו בלבוב. הו\"ל ספר אביו יחד עם אחיו - ר יוסף, ונפטר באמצע ההדפסה. בנו - ר יעקב מזולקוא."},{"i":38674,"n":"פלק, שמואל מבונבורק וברוד","f":"יעקב יהושע-פני יהושע","dt":"תקכא - כה סיון","dp":"ברודי","b":"חתן ר חיים לנדא מפודקמין. רב בברודי. תורה משמו בספר אביו \"פני יהושע\". נפטר ללא בנים."},{"i":38675,"n":"פלקביץ, אפרים מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":38676,"n":"פלקוביץ, אפרים מארה\"ב","bt":"תרמה","dt":"תשכה - יב סיון","b":"רב בקנטון-אוהיו-תרעד, רידפורט-תרפט, עלה לבני ברק-תשיט. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":38677,"n":"פלקון, אברהם מאנקונא","dt":"שיו - ג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":38678,"n":"פלקון, אברהם מפאס","f":"שלמה","b":"רב בפאס בזמן הרשב\"ש."},{"i":38679,"n":"פלקון, אברהם משלוניקי","dt":"תיז - כג אדר","dp":"שלוניקי","b":"מחכמי ישיבת ר שלמה ן מאיור הזקן ור\"מ בישיבה, רב במונסטיר, חזר לשלוניקי."},{"i":38680,"n":"פלקון, אליהו מצפת הזקן","f":"יעקב","b":"מחכמי שלוניקי, עלה לצפת והיה מתלמידי הארי, חתם בשנת שלה בשטר ההתקשרות של תלמידי הארי. חיבר זכרון דברים על גירוש רוח באדר שלא, נדפס כעלון וכן בתוך ספר \"נשמת חיים\" למנשה בן ישראל ח\"ג. גרשם שלום מצא כמה כתבי יד ממנו. ב\"נגיד ומצוה\" לר יעקב צמח נמצא כוונת בקור חולים שקיבל מר' אליהו פאלקון. בנו הוא ר יעקב פאלקון ושניהם נזכרים בספר הגלגולים השלם, ונזכר שם שפעם היה לר אליהו מריבה עם חברו ר יעקב ארזין ועל כך הוסר מלהיות בין התלמידים."},{"i":38681,"n":"פלקון, אליהו מצפת הנכד","f":"יעקב","dt":"תט","b":"דיין מחכמי צפת, נכדו של ר יעקב פאלקו (הזקן). חתם על כתב שליחות של ר יוסף מליריאה, ור יוסף בן ארויה בשנת שצז. בשנת שצד היה בקושטא כנראה בשליחות צפת."},{"i":38682,"n":"פלקון, אליהו משלוניקי","b":"מחכמי שלוניקי, ובקי בדיני חזקות. חברו של ר אברהם חזן - שנפטר רצה. (כנראה הוא קודם לר אליהו פלקון הזקן)."},{"i":38683,"n":"פלקון, אפרים ממרוקו","f":"שלמה","b":"רב בפאס-רן, היה במחלוקת עם ר נתן בוסתו מפאס. נזכר בשו\"ת הרשב\"ש."},{"i":38684,"n":"פלקון, דוד מקושטא","k":"בעל בני דוד","b":"דיין בקושטאא-תע. הניח כתבים רבים ונדפס מהם \"בני דוד\" ע\"י ר נסים יהודה ן יקר."},{"i":38685,"n":"פלקון, טודרוס משלוניקי","b":"רב בשלוניקי. תלמידו - ר דוד בן אברהם שמריה המזכירו בספרו \"תורת אמת\" - שסד."},{"i":38686,"n":"פלקון, יוסף מקושטא","f":"שלמה צלמאן","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע."},{"i":38687,"n":"פלקון, יעקב","f":"אליהו","b":"מחכמי שלוניקי בשנים ש-שג, עלה לצפת והיה מתלמידי הארי. מובא בשות מהריט כאחד החותמים על פסק דין בכפר פקיעין (בוקיעא)."},{"i":38688,"n":"פלקון, משה משלוניקי","dt":"רצח - לפני","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":38689,"n":"פלקון, משה שמואל משלוניקי","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תס."},{"i":38690,"n":"פלקון, רפאל משה מאזמיר","k":"בעל ישיר משה","dt":"תקנו - טו תשרי","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":38691,"n":"פלקון, שמואל משלוניקי","b":"מדפיס בשלוניקי-תעב."},{"i":38692,"n":"פלקון, שמעון מצפת","b":"מחכמי צפת."},{"i":38693,"n":"פלקון, שניאור","f":"יהודה","b":"מחכמי ירושלים, בשנת שכ בשליחות בתורכיה ואיטליה, חתן ר מאיר ן גבאי, והדפיס את ספר חותנו \"תולעת יעקב\", גיסו של ר חיים בן מאיר גבאי והוציא לאור את ספרו \"פסח לה\". חותנו של ר אברהם בן גדליה בן אשר והוציא לאור את ספרו \"אור השכל\". הדפיס בונציה שלב \"תפילות והושענות\"."},{"i":38694,"n":"פלקינפלד, יעקב מריגא","b":"תלמיד ישיבת חב\"ד באוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":38695,"n":"פלקינפלד, מרדכי יואל","f":"שמואל פלקינפלד","b":"בקי,סגי נהור,רב בפוזנא-תק\"פ"},{"i":38696,"n":"פלקירא ן, שם טוב מספרד","k":"בעל מורה המורה","bt":"ד'תתקפה (1225)","bp":"ספרד","b":"רב ומרביץ תורה בפלקירא-ספרד. מחכמי ספרד, בקי במדעים, פילוסוף ומשורר. חיבר איגרת להגנת ה\"מורה נבוכים\" כנגד מתנגדיו, חיבר ספרים רבים במדע, פילוסופיה, מוסר, ופירוש לתנך, חיבר פירוש למורה נבוכים בשם \"מורה המורה\", \"המבקש\", \"דברי הימים\" שאבד, חיבר \"צרי היגון\", , \"חכמת הנפש\" (בכת\"י אצל ר דוד אופנהים).."},{"i":38697,"n":"פלקירא, מתתיהו מלבוב","k":"בעל אספקלריה המאירה","dp":"לבוב","b":"רב בלבוב-תע. הסכים על \"סדור שער השמים\" להשל\"ה."},{"i":38698,"n":"פלקירא, נתן מספרד","f":"יואל הרופא","k":"בעל צרי הגוף","b":"רופא מחכמי ספרד - במאה ה-13, ולמד בעיקר מאביו שהיה רופא גם הוא. חיבר ספר ברפואה בשם \"צרי הגוף\" בעברית, כי בתקופתו השפה הערבית כבר לא היתה שגורה אצל היהודים בספרד."},{"i":38699,"n":"פלקלש, אלעזר מפרג וגוטיין","f":"דוד","k":"בעל תשובה מאהבה","bt":"תקיד","bp":"פרג","dt":"תקפו - יח ניסן","b":"מגדולי המשיבים בדורו. תלמיד ר משה הכהן רופא, ר מאיר פישל'ס, הנודע ביהודה. דרשן, מרביץ תורה, רב בגוטיין ודאבוטשו במעהרן-תקלט, דיין וראב\"ד בפרג-תקמג, ורב ביהמ\"ד של ר יוחנן אדלר פאן פאפער ור ישראל פרנקל. היה מקורב לקיסר פרנץ יוזף והיה גם הצנזור ומבקר הספרים העבריים מטעם הקיסר."},{"i":38700,"n":"פלקן, אליהו מצפת","b":"מגדולי המקובלים בצפת-ש\"כ"},{"i":38701,"n":"פלקנהאוזן, ישכר דב בער","k":"בעל געדיכטע איינעס פ","bt":"תקו","bp":"שאמושטש","dt":"תקנו - לפני","b":"למד בברלין בעזרת הגביר ר דניאל איציק, ובעזרת דודו או גיסו ר ישראל מזאמושטש (שישב אצל הגביר דניאל בברלין), היה מקורב למנדלסון וראמלר. חיבר שירים בגרמנית. רופא בקורלנד. בנו - ר ירוחם בעל \"אוצר נחמד\"."},{"i":38702,"n":"פלקנוי, יהושע משה מפיורדא","dt":"תקפט - כד אייר","b":"ר\"מ ראב\"ד בפיורדא אצל ר בנימין וולף המבורג בעל \"שער הזקנים\". נספד מאת החת\"ס."},{"i":38703,"n":"פלקנפלד, שמואל מפשוורסק","f":"פנחס משה מזולקוא","k":"בעל בית שמואל אחרון","bt":"תצז","dt":"תקסז - כז כסלו","dp":"פוזנן","b":"אביו היה פרנס אחרון של ועד ארבע ארצות. חתן דודו ר צבי הירש מלוקוב. (הישועות יעקב העיד עליו שלא היה גאון כמוהו... מימי הרב השל). רב בבילגוריי-תקך, פשוורסק-תקמג, נבחר לפרשבורג-תקמט אך לא הסתייע, טרנופול-תקנב, פוזנא-תקסא על מקום אחיו ר יוסף לנדא. הסכים על \"בחינת עולם\"-תקמב, \"שערי בינה\"-תקנב, \"אהבת דודים\"-תקנה. תשובה ממנו ב\"השיב משה\" - תקנה. בנו ר מרדכי יואל על מקומו אחריו בפוזנא. חיבר \"בית שמואל אחרון\" נוווידבור תקסו. רבים מכתביו נשרפו. (אצל בובר-זולקוא תאריך פטירתו יד כסלו)."},{"i":38704,"n":"פלקס, שרגא פיבוש מוישניצא","b":"נכד המאור ושמש. מחכמי וישניצא, חסיד בובוב-תרמב."},{"i":38705,"n":"פלקסמן, צבי מפושאלט","dt":"תש..","b":"רבה האחרון של פושאלט-ליטא. נספה בשואה."},{"i":38706,"n":"פלקסנר, אברהם מארה\"ב","f":"משה","bp":"לואיסוויל-קנטקי","b":"רופא בארה\"ב, מחבר ספרי רפואה."},{"i":38707,"n":"פלקסר יצחק דוד","bt":"1907","dt":"ה'תשנט 1999","bk":[["פרזים ומוקפים",""],["שערי יצחק",""]]},{"i":38708,"n":"פלקסר, יעקב הכהן מפרידריכשטט","f":"אברהם","k":"בעל דבר ליעקב","bt":"תרכט","dt":"תשב - כה ניסן","b":"רב ביקובשטט(=יאקאבשטאדט)-תרסב, פרידריכשטט-קורלנד-תרסח, היגר לארה\"ב וכיהן כרב בכמה קהילות ובהם ניו הייבן-תרפג. חיבר \"דבר ליעקב\" סט לואיס תרפה. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":38709,"n":"פלקסר, יצחק","k":"בעל שערי יצחק","bt":"תרעו","bp":"פולין","dt":"תשנט","b":"תלמיד ישיבת חכמי לובלין. עלה לארץ לפני השואה. ר\"מ בישיבת \"שפת אמת\" מעל 50 שנה. ראב\"ד בד\"צ אגודת ישראל, חבר מועצת גדולי התורה.","bk":[["שערי יצחק [עהש\"ס",""],["הל' יו\"ט שני",""],["פרזים ומוקפים]",""]]},{"i":38710,"n":"פלר, יצחק מסנוק","f":"שמשון מיכל מסנוק","k":"העילוי מסנוק","bt":"תרלו","dt":"תרצד","dp":"ירושלים","b":"חתן נכדת ר חיים יעקב מניישטט. , היגר לארה\"ב-תרנ והיה שם סוחר ורב וממיסדי ישיבת מהרש\"ק ומראשי המזרחי. עלה לירושלים-תרצב ורכש את אדמות נחלת יצחק למרגלות הקסטל כדי להקים שם שכונה חרדית."},{"i":38711,"n":"פלר, שמשון מיכל הלוי מסנוק","f":"משה דניאל סגל","bt":"תקץ","dt":"תרעז","dp":"ירושלים","b":"רב בסנוק. חסיד בלז ומלמד לנכדי האדמור. עלה לצפת-תרסז, ועבר לירושלים."},{"i":38712,"n":"פ\"מ, צבי הירש מברעזנא","b":"חתן ר שמעון וינטר (אחיו של ר אליעזר משטמפן). מחכמי ברעזנא. בנו - ר אברהם מוואץ."},{"i":38713,"n":"פמרנציק, אריה","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":38714,"n":"פן, יודל יורי","f":"משה","bp":"אז'אראני","b":"למד באקדמיה לאמנות בפטרבורג, פתח בי\"ס לאמנות בויטבסק-1912. צייר טיפוסים מחיי היהודים, ובהם \"הרב הזקן\", ועוד."},{"i":38715,"n":"פנדלר, בן ציון","k":"בעל גיא חזיון"},{"i":38716,"n":"פנחס","k":"בעל דברי שלום","b":"חתן ר מרדכי בן יוסף הורוביץ. רב-שנת תקן. בנו - ר מרדכי"},{"i":38717,"n":"פנחס","b":"חתן ר ברוך הלברשטם. רב-שנת תרן. חתנו - ר משלם פיבש הלפרין."},{"i":38718,"n":"פנחס","f":"יעקב יוסף","b":"רב-שנת תק\"מ. בנו ר יעקב יוסף."},{"i":38719,"n":"פנחס אליהו ממנטובה","f":"אליהו צמח ממילי","b":"רב במנטובה בזמן ר משה פרובנצאלי. תשובה ממנו ב\"פחד יצחק\"."},{"i":38720,"n":"פנחס אלימלך מדאראג","b":"שו\"ב בדאראג בזמן האדמור ר שמואל פרנקל מדאראג, ונעשה לו נס שם."},{"i":38721,"n":"פנחס אלימלך מזבארז","f":"אליהו","dt":"תקצט - כו אייר","b":"רב בזבארז"},{"i":38722,"n":"פנחס אליעזר מפשוורסק","b":"רב בבוברקא-תרכג, דובצק"},{"i":38723,"n":"פנחס בכור רבי מאזמיר","b":"גיסו של ר חיים פלאג'י. ונזכר ב\"ראה חיים\"."},{"i":38724,"n":"פנחס דוד מיאנינה","b":"דיין ביאנינה-תמה."},{"i":38725,"n":"פנחס דוד מירושלים","dt":"תרלט - יז כסלו","b":"רב בבוקין,עלה לירושלים"},{"i":38726,"n":"פנחס הכהן","b":"סייע לר משה ישראל מרודוס בהדפסת ספרו \"משאת משה\"."},{"i":38727,"n":"פנחס הכהן מאדרינופול","b":"מחכמי אדריאנופול, חברו של ר יוסף צרפתי בעל \"יד יוסף\". בנו - ר דוד."},{"i":38728,"n":"פנחס הכהן מאנקונה","f":"אברהם","b":"גביר מחכמי אנקונה, אירח את החיד\"א בביתו-תקלו."},{"i":38729,"n":"פנחס הכהן מבוכרה","k":"רבי פנחס הכהן הגדול","b":"מגדולי חכמי הדור,ראב\"ד בבוכרה-סמרקנד,קווקז,תשכנד,תורכיסתן,כוראסאן,אפגניסתן-תקפ\"ג-תרי\"ח"},{"i":38730,"n":"פנחס הכהן מלוטמרסק","b":"רב בלוטמרסק-תק\"ס"},{"i":38731,"n":"פנחס הכהן ממצרים","f":"יונה","b":"מחכמי מצרים בזמן הרמב\"ם."},{"i":38732,"n":"פנחס הכהן ממרוקו (אזוז)","bp":"מראקש","dt":"תשיב - יד טבת","b":"מצדיקי מרוקו, ורבים עולים על קברו."},{"i":38733,"n":"פנחס הכהן מפרס","dt":"תרכא","b":"רב ביאזד-פרס - תרכא, נפטר בדרכו לארץ. בנו ר ישמעאל הכהן שנרצח בפרעות בצפת-תרפט."},{"i":38734,"n":"פנחס הלוי מאנטיניווקא","bt":"תרל","dt":"תרצה - כט ניסן","b":"רב באנטיניווקא"},{"i":38735,"n":"פנחס הלוי מאפטא","f":"מאיר הלוי","b":"רב באפטא-ת\"ר"},{"i":38736,"n":"פנחס הלוי מברצלונה","f":"רבינו יוסף הלוי","b":"מגדולי הראשונים,מרביץ תורה בברצלונה-שנת כ'"},{"i":38737,"n":"פנחס הלוי מספרד","f":"יוסף בר בנבנשתי","b":"פייטן מחכמי ספרד בזמן שלפני הרשבא. אחיו ורבו של ר אהרן הלוי (=הרא\"ה). חיבר פיוטים ואזהרות."},{"i":38738,"n":"פנחס הלוי מרוזניאטוב","b":"רב ברוזניאטוב-תרטז, אטיניא-תרכב."},{"i":38739,"n":"פנחס הלוי משערשוב","f":"עזריאל","k":"בעל נחלת עזריאל","b":"תלמיד ר יונתן איבשיץ. רב בשערשאב,ונגרוב-תק\"נ"},{"i":38740,"n":"פנחס המגיד מפלאצק ושניפישוק","f":"יהודה","k":"בעל כתר תורה","bt":"תקז או תקל","dt":"תקפג - ג שבט","dp":"וילנא","b":"מגיד מישרים בפלאצק וכונה \"דער פאלאצקער מגיד\", שניפישוק-ליטא, והיה דורש בקהילות רוסיה ופולין. ביקר בוילנא ופגש את הגר\"א שהזמינו לשמש מלמד לנכדיו. מגיד ורב בשניפישוק-ליד וילנא על מקום ר משה בן יוסף הלוי, ועל מקומו אחריו ר דוד יהודה ליב טיללעס בן דב בער. חיבר גם \"כתר תורה\", ועוד. (לפי יהדות ליטא נפטר - תקסז)."},{"i":38741,"n":"פנחס וולף","k":"בעל נברשת הלנה","b":"גדול בחכמה ומדע,רב פעלים,רב בקלן-תרצ\"ה,עלה לפ\"ת-תש\"י"},{"i":38742,"n":"פנחס זאב מצפת וטבריה","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":38743,"n":"פנחס זליג אשר","f":"שאול","b":"רב בלאמז-תק\"צ"},{"i":38744,"n":"פנחס זליג מאמשטרדם","b":"סופר ודיין באמסטרדם-תס\"ח"},{"i":38745,"n":"פנחס זליג מבריסק","f":"יוזפא","b":"ר\"מ בבריסק"},{"i":38746,"n":"פנחס זליג מלאסק","f":"משה","k":"בעל עטרת פז","dt":"תקל - ו ניסן","dp":"לאסק","b":"תלמיד ר שמואל קראקויער בפרג. רב בלאסק(=לוסק) ובנו ר צבי על מקומו אחריו. חיבר \"עטרת פז\" פפד\"א תקכח. בנו - ר אריה ליב-חתנו של ר שמואל לסקר מלוסק."},{"i":38747,"n":"פנחס זליג מפאפא","b":"רב בפאפא"},{"i":38748,"n":"פנחס יקותיאל לאזיל סגל","f":"אברהם","dt":"תעו-ז - כד סיון","dp":"לבוב","b":"מראשי קהלת לבוב."},{"i":38749,"n":"פנחס ליב הכהן מאורלא","f":"נתן מתתיהו הכהן","b":"רב בגאנינצז,אורלא"},{"i":38750,"n":"פנחס ליב הכהן מטאפיא-סעלא","b":"רב בטאפיא-סעלא על מקום ר ישעיה בן ישראל הכהן-תקס בערך, היה מחלוקת כנגדו בענין גט. (אולי הוא ר פנחס מונק ממשפחת החת\"ס)."},{"i":38751,"n":"פנחס מאוסטרהא","f":"יונה","k":"אדמור מאוסטרהא","b":"מצאצאי ר יונה מאוסטרהא-תלמיד הבעשט והמגיד ממזריטש."},{"i":38752,"n":"פנחס מאוסטרהא","f":"יעקב יוסף - ייבי","k":"אדמור מאוסטרהא","dt":"תקסו - כב כסלו","dp":"אוסטרהא","b":"צעיר בניו של רב ייב\"י. מחכמי אוסטרהא. הו\"ל עם אחיו את \"רב ייב\"י\". נפטר בצעירותו. מבניו: ר יעקב יוסף מאוסטרהא, ר משה מרוזיסטשוב-פלך קיוב."},{"i":38753,"n":"פנחס מאלטונא","f":"גמליאל מאלטונא","dt":"תרלב - כב תמוז","dp":"אלטונא","b":"מגיד בח\"ק באלטונא. חיבר דרשות בכת\"י. נכדו הרופא גבריאל לאנצקראן."},{"i":38754,"n":"פנחס מאליק","b":"רב באליק-תק\"צ"},{"i":38755,"n":"פנחס מאלכסנדריה","b":"מגדולי חכמי מצרים-ד'תתק\"נ"},{"i":38756,"n":"פנחס מאשכנז","dt":"רנו - ט תשרי","b":"מגדולי חכמי אשכנז,מרביץ תורה בפוזנא,פרג"},{"i":38757,"n":"פנחס מבסקביץ","b":"רב בבסקוביץ-תק\"מ"},{"i":38758,"n":"פנחס מברנוב","f":"שמרל","b":"רב בברנוב, מגדולי חריפי גליציה. חתונו של ר יחיאל וינמן מקולבסוב."},{"i":38759,"n":"פנחס מגניוועשוב","b":"רב בנגיוושאב-תק\"פ"},{"i":38760,"n":"פנחס מדובנקא","b":"רב בדובנקא-תר\"ל"},{"i":38761,"n":"פנחס מדינוביץ","k":"בעל שפתי צדיקים","b":"תלמיד ר אברהם יהושע השל מאפטא."},{"i":38762,"n":"פנחס מהומאנא ואוהל","b":"רב באויהל-תר בערך."},{"i":38763,"n":"פנחס מוילנא","f":"אברהם","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":38764,"n":"פנחס מטרניגרד","dt":"תרלב - יב שבט","b":"רב בגראשקוב,טרניגרד"},{"i":38765,"n":"פנחס מלבוב","b":"רב בלבוב-תק\"י"},{"i":38766,"n":"פנחס מלבוב","f":"מנחם מאניש","b":"נכד הש\"ך. אב\"ד לבוב. בנו ר מאניש סגי נהור."},{"i":38767,"n":"פנחס מלודמיר ואוסטרהא","f":"שאול מלודמיר","dt":"תקמו -- יא תמוז","dp":"אוסטרהא","b":"הגיע לעת זקנתו לאוסטרהא אל בנו ר אריה יהודה ליב-חתן ר נחמן כץ. התצטרף לח\"ק והיה גבאי שם. מבניו: ר ישכר בר מטולטשין, ר אריה יהודה ליב מאוסטרהא."},{"i":38768,"n":"פנחס מלכוויץ","b":"רב בלכוויץ-תר\"ס"},{"i":38769,"n":"פנחס ממצרים","f":"משלם","b":"דיין באלכסנדריה בזמן הרמבם, ונזכר בתשובות הרמבם."},{"i":38770,"n":"פנחס מסטובניץ","b":"רב בסטאבניץ-תר\"נ"},{"i":38771,"n":"פנחס מפוזנא","f":"פילטא","k":"בעל ברית שלום","b":"רב בוולאדאווע-תנ, פוזנא. חיבר \"ברית שלום\" - י\"ל ע\"י בנו ר יחזקאל בפפדמ תעח."},{"i":38772,"n":"פנחס מפילץ","b":"רב בפילץ-תר\"ל"},{"i":38773,"n":"פנחס מצפת","f":"הרב מקלעוואן","b":"מראשי קהלת צפת-תרלב, חתם עם ר שמואל הלר ור רפאל זילברמן."},{"i":38774,"n":"פנחס מקולק","b":"רב בקולק"},{"i":38775,"n":"פנחס מקידאן","f":"אליעזר","k":"בעל אבן הראשה-כת\"י","dt":"תץ - בערך","dp":"קידאן","b":"רב בקידאן על מקום ר יהושע השל הלוי, ור משה מרגליות על מקומו אחריו. חיבר גם \"אבן השהם\", אבן פינה\", \"אבן שתיה\", ועוד - בכת\"י."},{"i":38776,"n":"פנחס מקראקא","f":"ישראל","b":"מו\"צ בקרקא-ת\"ל"},{"i":38777,"n":"פנחס מרומנובה","b":"רב ברומאנובה-תר\"מ"},{"i":38778,"n":"פנחס מרוצוואל","dt":"תרל - כב כסלו","b":"רב ברוצוואל"},{"i":38779,"n":"פנחס מרישא ואוסטרהא","f":"שמואל הקדוש","b":"הגיע מרישא ואולי מקודם מפפד\"א, פרנס באוסטרהא-תפט."},{"i":38780,"n":"פנחס משה הלוי מסט עוסטאטוס","bt":"תפז","dt":"תקמט - כב תמוז","dp":"סט עוסטאטוס","b":"רב בסט עוסטאטוס-אמריקה התיכונה."},{"i":38781,"n":"פנחס משה מזולקוא","f":"אברהם רבי חיימש","b":"חתן ר ישראל איסר מזולקוא. רב בסווירז, ראב\"ד בזולקוא-תקו, פרנס אחרון של ועד דד\"א (הועד בוטל עם חלוקת פולין-תקל). הסכים על \"פורת יוסף\", \"ברכת יוסף ואליהו רבה\", \"באר היטב\", \"נטע שעשועים-תקח, ועוד. בניו: ר יוסף הצדיק מפוזנא, ר שמואל מבילגוריי. גיסו - ר נפתלי הרץ מברודי וזולקוא, ר יעקב יצחק בן משה חיים מזאמושץ. אחיו - ר צבי הירש מלובלין, ר חיים מלובלין."},{"i":38782,"n":"פנחס משה מלבוב","k":"משה חריף השני","b":"אב\"ד בלבוב, חתם-תסא על תקנות קהלת זולקוא. הסכים על ירושלמי-אמשטרדם תע."},{"i":38783,"n":"פנחס משימאנדא","b":"רב בשומאנד(=שימאנדא)-תקע."},{"i":38784,"n":"פנחס משקלוב","k":"בעל הנחות הר\"פ","dt":"תקפה","b":"חסיד בעל התניא ובנו ר דב בער שאמר עליו \"הוא הפילדמרשל של החסידים\". רשם את תורת רבותיו ונדפסו בשם \"הנחות הר\"פ\". ?? לא באוצר ??"},{"i":38785,"n":"פנחס שמואל זנויל","f":"אברהם מוארשא","b":"נינו של ר יעקב מליסא בעל \"חוות דעת\"."},{"i":38786,"n":"פנחס שמערינר","b":"חתן ר שמואל תאומים מאלטונא וזאמושט. בנו - ר משה מהאלוסק."},{"i":38787,"n":"פנחס, יצחק","f":"אברהם צבי מטיקטין","k":"בעל רגשי יצחק","b":"תלמיד ישיבת ראדין, סלובודקא, סלוצק, וולוזין."},{"i":38788,"n":"פנט חיים בצלאל בן יחזקאל","bt":"1803","dt":"ה'תרלד 1874","bk":[["דרך יבחר",""]]},{"i":38789,"n":"פנט, אברהם שמואל מקרלסבורג","f":"יעקב מרטיאג-ליד דעש","k":"בעל אשיב אברהם-תשלב","bt":"תרלח-ט","dt":"תשכז - יג סיון","dp":"תל אביב","b":"נכד בעל \"מראה יחזקאל\". תלמיד בעל \"קדושת יו\"ט\" בסיגט. חתן ר מנשה שמחה פרידמן מסאבראנץ. רב בקלויזנבורג, רבה הראשון של הקהלה החרדית בקרלסבורג-תרסז על מקום זקנו בעל מראה יחזקאל שישב שם 60 שנה לפניו. ניצל מהשואה, ואחריה עלה לארץ-תשו והתישב בתל אביב. בנו ר חיים אלתר רב ברמת אביב הו\"ל ספר אביו עם תוספות ממנו בשם \"תפוחי חיים\" - תל אביב תשלב."},{"i":38790,"n":"פנט, אלימלך אלתר","f":"יוסף מדעש ונ\"י","b":"רב בניו יורק."},{"i":38791,"n":"פנט, אלימלך מדעש","f":"יצחק יחיאל מדעש","bt":"תרנה","bp":"דעש","dt":"תשד - יח סיון","b":"תלמיד בעל \"ערוגת הבשם, בחוסט. חתן האדמור ר אברהם חיים הורביץ מלינסק. נשיא כולל \"אהבת ציון\" בדעש-תש על מקום אביו. נספה בשואה."},{"i":38792,"n":"פנט, אריה ליב מגרוסורדין","f":"אשר שמואל מהידאלמאש","bt":"תרכג","dt":"תרצז - כג תשרי","dp":"גרוסורדין","b":"נכד ר חיים בצלאל פנט מטאשנאד. תלמיד השב\"ס. חתן ר אליהו קורלנדר מגרוסורדין. מחכמי דעש, גרוסורדין."},{"i":38793,"n":"פנט, אשר שמואל מטשאנד","f":"חיים בצלאל מטשאנד","k":"בעל אש דת","bt":"תקצה","bp":"טשאנד","dt":"תרסט - י שבט","b":"תלמיד ר יהודה אסוד. חתן הגביר ר יצחק איזיק הכהן מפאיא - נכד בעל \"קונטרס הספיקות\". מחכמי הוניאד. בזיוו\"ש חתן הגביר ר אשר זליג מראקאש, מחכמי היד-אלמאש. רב בהידאלמאש-תרמא על מקום ר נתן נטע סלומון. חיבר \"דברות אש\" ונדפס עם ספר אביו \"ים הרחב\", \"אש דת\" ועוד חיבורים שאבדו בשואה. (במורשת הונגריה - אביו היה ר יחזקאל בעל \"מראה יחזקאל\"). ?? לא באוצר ??"},{"i":38794,"n":"פנט, אשר שמואל מירושלים","f":"יחיאל מאיר מהידאלמש","b":"חתן ר מנחם מנדל למברגר מטיסא-פולגאר."},{"i":38795,"n":"פנט, דב בריש","f":"יוסף מדעש ונ\"י","b":"חתן ר משה נתן נטע ממאקווה, התגורר בחיפה, בני ברק."},{"i":38796,"n":"פנט, חיים אלתר מבאניא ות\"א","f":"אברהם שמואל מקרלסבור","k":"בעל תפוחי חיים-תשלב","bt":"תרעה","bp":"קרלסבורג","dt":"תשמד - יב ניסן","dp":"תל אביב","b":"תלמיד ר שלמה צבי הכהן שטראסר בדברצין. חתן ר משה אהרן קרויס מבאניא, וכיהן כרב בבאניא אצל חותנו. ניצל מהשואה, ואחריה רב בבאניא. בזיוו\"ש חתן ר מאיר שלום רוטנברג אדמור בקלינורדין. עלה לארץ-תשו, וכיהן כרב ברמת אביב. חיבר גם \"אשישות חיים\" ירושלים תשלד, ועוד."},{"i":38797,"n":"פנט, חיים אלתר מנאדי-באניא","b":"חתן ר משה אהרן מנאדי-באניא. רב בנאדי-באניא לצד חותנו. עלה לארץ וכיהן כרב ברמת אבית."},{"i":38798,"n":"פנט, חיים בצלאל מטשאנד","f":"יחזקאל-מראה יחזקאל","k":"בעל דרך יבחר-תרנג","r":"אב\"ד טשנאד והגליל ארבעים שנה","bt":"תקסג","bp":"ביליץ","dt":"תרלד - יט ניסן","dp":"טשאנד","b":"תלמיד החתם סופר. חתן הגביר ר אריה ליב (דוד) ניילנדר מאלפאר-ליד סטנוב ועבר לשם-תקפד. רב בבלקאן, הידאלמאש-תקצד, טשנאד-תקצה וכל מחוז סולנוק הפנימית כ-40 שנה. חיבר גם \"ים הרחב\", \"אוצר חיים\". בנו ר אשר שמואל מהידלאמאש.","bk":[["אוצר החיים - עה\"ת (כת\"י)",""],["דרך יבחר - שו\"ת",""],["ים הרחב - גיטין ורוב סוגיות הש\"ס והש\"ע (כת\"י)",""]]},{"i":38799,"n":"פנט, חיים בצלאל מרטיאג","f":"יעקב מרטיאג","k":"בעל דברי בצלאל-תרצט","bt":"תרלה","bp":"ערדא-סענזשארץ","dt":"תרעה - ט טבת","b":"תלמיד ר משה פאנט בדעש, וישיבת ר יהודה גרינוולד בסטמר, ובישיבת בעל \"קדושת יו\"ט\" בסיגט. חתן האדמור ר זאב וולף ציטרון מדאראד. רב ברטיאג-תרנט על מקום אביו (למרות שההחלטה הקודמת היתה שהרבנות שמורה לחתן העתידי של הבת הצעירה). נפטר צעיר ואלמנתו נישאה לר יהושע ליבוביץ שכיהן אחריו כרב האחרון ברטיאג. בנו ר משה שמואל פאנעטה חיבר הקדמה לספר אביו."},{"i":38800,"n":"פנט, חיים ברוך מדעש","f":"יעקב אלימלך ממארוש","bt":"תרסט","bp":"מארוש-אויוואר","b":"נכד ר יחזקאל פאנט בדעש ונתחנך בביתו. חתן ר חיים הלברשטם מסטמר-תרפט. רב בדעש-תרצב. נספה בשואה."},{"i":38801,"n":"פנט, חיים מנחם מדעש","f":"משה מדעש","k":"אדמור מדעש","bt":"תרנד","bp":"דעש","dt":"תשד - יח סיון","b":"לאחר שנתייתם גדל אצל אחיו ר יחזקאל מדעש בעל \"כנסת יחזקאל\". תלמיד בעל \"ערוגת הבשם\" בחוסט, ואחיו בעל \"קרן לדוד\" באויבר-וישיווה. חתן ר יעקב שמשון קאנר האדמור מצ'חוב. אדמור בדעש לחלק מחסידי אביו, ועמד בראש ישיבה שם. בנו יחידו הבחור יחזקאל-נספה בשואה."},{"i":38802,"n":"פנט, יהודה ליב מטערצאל","f":"יחזקאל-מראה יחזקאל","b":"חתן ר יהודה דוד רוטנברג מטאליא בעל \"תהלה לדוד\"."},{"i":38803,"n":"פנט, יוסף מביליץ","dt":"תקעט - ו תשרי","dp":"ביליץ(=ביעלץ)","b":"אביו של ר יחזקאל מקרלסבורג."},{"i":38804,"n":"פנט, יוסף מדעש","f":"יחזקאל מדעש","k":"אדמור מדעש","bt":"תרנה","dt":"תשכב - י אב","dp":"ניו יורק","b":"חתן הגביר ר דב בריש וינברג מקראקא. רב בטקנדורף, אילאנדה-מחוז סאמוש-תרפו על מקום ר יוסף צוקרמנדל וראש ישיבה שם, וכיהן גם כאדמור מדעש. ניצל מהשואה, עם 9 מילדיו שהוברחו לרומניה בעזרת איכרים רומנים (שסייעו להם כנגד המשטרה ההונגרית). אחרי השואה כיהן כרב בדעש. היגר לפריס, וארה\"ב-תשט וכיהן כאדמור מדעש בניו יורק.","bk":[["שארית יוסף",""]]},{"i":38805,"n":"פנט, יוסף מטאשנד","f":"יצחק משה מדעש","b":"חתן קרובו ר מרדכי ליב ליברמן מטאשנד."},{"i":38806,"n":"פנט, יחזקאל מדעש","f":"משה מדעש","k":"אדמור מדעש-כנסת יחזק","bt":"תרל או תרלב","dt":"תרץ - כב כסלו","b":"בגיל 6 כבר רשם חדושי תורה, ובן 7 הניח תפילין. תלמיד זקנו ר מנחם מנדל פאנט מדעש. חתן הגביר ר שמואל יהודה פולק מאויבר-וישוה ועבר לשם. מקורב לאדמור ר יחזקאל הלברשטם משינאווא. רב במארוש-אויוואר(=אויבר)-תרנה ובנו ר יעקב אלימלך על מקומו אחריו, רב ואדמור בדעש-תרסג על מקום אביו וראש ישיבה שם. בנו ר יעקב אלימלך חיבר הקדמה לספר אביו. נספד ב\"קול בוכים\" לר משה מרדכי קלרמן - דעש תרץ. חיבר \"כנסת יחזקאל\"."},{"i":38807,"n":"פנט, יחזקאל מטאשנד","f":"יוסף מטאשנד","bt":"תרלג","dt":"תש..","dp":"אושוויץ","b":"תלמיד השב\"ס. מחכמי טאשנד ועמד בראש הקהלה, עבר לדעש-תרצו. נספה בשואה."},{"i":38808,"n":"פנט, יחזקאל מטערצאל","f":"יהודה ליב מטערצעל","bt":"תריב","bp":"טערצל","dt":"תרע.. - ה טבת","dp":"טערצל","b":"נכד ר יחזקאל פנט מקרלסבורג. תלמיד הכת\"ס, ודודו ר מנחם מנדל פנט מדעש. חתן ר זאב וולף שיק מברגסאס ועבר לשם-תרלה, רב בטערצל."},{"i":38809,"n":"פנט, יחזקאל מנחם מדעש","f":"יצחק יחיאל מדעש","k":"אדמור מדעש","bt":"תרנז","dt":"תשד","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט. חתן ר משה זאב קאהן ממארוש-ואשארהי-בנו של בעל \"בינת ישכר\". אדמור בדעש-תש על מקום אביו. נספה בשואה."},{"i":38810,"n":"פנט, יחזקאל מקרלסבורג","f":"יוסף מביליץ","k":"בעל מראה יחזקאל","bt":"תקמג","bp":"ביליץ(=ביעליץ)","dt":"תרה - כ ניסן","b":"חתן הגביר ר משה הניך(=העניק) מלינסק. תלמיד ר ברוך פרנקל בעל \"ברוך טעם\", ר שמואל לנדא מפרג, ר ליב פישלעס מפרג, ר אלעזר פלקלש מפרג, ר מנחם מנדל מלינסק, חסיד ר מנחם מנדל מרימנוב (שלח מכתב לאביו המתנגד ובו תיאור החצר של האדמור - אז בפריסטיק) ומקורב לגדולי האדמורים. רב בלינסק, איסטריק, טערצאל-הונגריה-תקעג והתקרב לאדמור מקלוב ר יצחק טויב - שהיה האדמור הראשון בהונגריה, קרלסבורג והמחוז-תקפג (בהמלצת החתם סופר - החת\"ס שנתבקש להמליץ על רב לקהלת קדלבורג(=קרלסבורג) המליץ על שלשה: ר יחזקאל, ר אליקים גץ, ר דניאל פרוסטיץ). היה מנהיג יהודי טרנסילבניה, מינה מורי הוראה ושוחטים, יסד בתי חינוך ותיקן תקנות, התיר למעלה ממאתים עגונות. חיבר גם \"מנחם ציון\" ובו מתורת האדמור מרימנוב - טשרנוביץ תריא, ועוד. כתב תשובה על החסידות לר שלמה פילץ מביליץ - נדפסה והועתקה פעמים רבות. פעל לטובת הישוב היהודי בארץ ישראל והעביר את הכספים שהתאספו אצלו לבעל \"ישמח משה\" בסיגט. בניו: ר חיים בצלאל מטשאנד, ר מנחם מנדל מארישאר ודעש, ר יהודה ליב, ר יצחק משה, חתניו: ר יהודה הכהן בן שמואל זנויל מסיגט, ר יוסף אריה כהנא בן נחמן מסיגט."},{"i":38811,"n":"פנט, יחיאל מאיר מהידאלמאש","f":"אשר שמואל מהידאלמאש","bt":"תרך","dt":"תשד - ד אדר","b":"תלמיד דודו ר מנחם מנדל פנט בדעש, וישיבת ה\"חתן סופר\" במטרסדורף. חתן הגביר ר אלימלך רוזנפלד מכפר סעפלאק - \"אספן החתנים\". בזיו\"ש חתן גיסו ר משה סופר בן הכתב סופר. רב וראש ישיבה בבוטשום(=וורמעזא)-תרסו וחתנו ר חיים צבי ליכטנשטין רב לצדו ועל מקומו אחריו, רב בהידאלמאש-תרסט על מקום אביו כ-35 שנה."},{"i":38812,"n":"פנט, יעקב אלימלך מדעש","f":"יחזקאל - האדמור מדעש","k":"אדמור מדעש-זכרון יעק","bt":"תרמט","bp":"אויבר-וישווה","dt":"תשד - יח סיון","b":"נתמנה לרב במארוש-אויוואר(ואשאר-העלי)-תרסג על מקום אביו בהיותו בן 14 אך החל בכהונתנו בתרסט. חתן האדמור מצ'חוב ר יעקב שמעון קאנר. רב בדעש-תרפו לצד אביו וראש הישיבה שם, רב ואדמור בדעש-תרץ על מקום אביו. מראשי ארגון הקהלות האורטודוכסיות בטרנסליבניה. נספה בשואה. תלמידו ר דב בר שפיצר הו\"ל את ספרו \"זכרון יעקב\" נ\"י תשיג."},{"i":38813,"n":"פנט, יעקב מרטיאג","f":"יצחק משה מדעש","k":"בעל שארית יעקב-תרעז","bt":"תרג","bp":"דעש","dt":"תרנט - יד ניסן","b":"נכד בעל \"מראה יחזקאל\". תלמיד ישיבת דודו ר מנחם מנדל פאנט בדעש, ישיבת בעל \"ייטב לב\" בסיגט, וישיבת ר מאיר א\"ש באונגוואר. חסד צאנז. חתן הגביר ר יעקב צודיק מערדא-סענזשארץ. רבה הראשון של רטיאג-גליל דעש-תרלט וראש ישיבה שם כ-20 שנה, ובנו ר חיים בצלאל בעל \"דברי בצלאל\" על מקומו אחריו. בנו ר אברהם שמואל הו\"ל את ספרו \"שארית יעקב\" עם הקדמה ממנו."},{"i":38814,"n":"פנט, יצחק יחיאל מדעש","f":"משה - האדמור מדעש","k":"אדמור מדעש","bt":"תרכג","bp":"כפר נימיזשא","dt":"תש - יד שבט","dp":"דעש","b":"תלמיד זקנו ר מנחם מנדל פאנט בדעש. חתן ר משה מביקאווסק-תרמב. לאחר פטירת אביו כיהן אחיו ר יחזקאל כאדמור מדעש, ור יצחק נתמנה לנשיא כולל \"אהבת ציון\" בדעש."},{"i":38815,"n":"פנט, יצחק משה מדעש","f":"יחזקאל-מראה יחזקאל"},{"i":38816,"n":"פנט, יצחק צבי איזיק ממיקלוש","f":"חיים בצלאל ממאראש","bt":"תרסב","bp":"מאראש-לודאש","dt":"תשכח - א סיון","dp":"ירושלים","b":"תלמיד הדעת סופר, ור שלמה זלמן ברייער מפפדמ. חתן ר דוד גולדשטין מבודפשט. רב בבודפשט על מקום חותנו (קהילת \"שומרי שבת\"), קין-סנט מיקלוש-תרצג. ניצל מהשואה ואחריה רב בבודפשט. רב בדטרויט (ארה\"ב)."},{"i":38817,"n":"פנט, ישראל זאב מטעגלאש","b":"נכד ר יחזקאל פנט מקרלסבורג ור יהודה דוד רוטנברג מסנט פעטער. חתניו - ר בנציון בלום מבערעטי, ר ישראל משה מאנדל מעגלאש, ור שלמה זלמן שטרן מטימישואר."},{"i":38818,"n":"פנט, מנחם מנדל מדעש","f":"יעקב אלימלך מדעש","bt":"תרפב","dt":"תשד","b":"תלמיד ישיבת אביו בדעש. חתן ר ברוך בן ישראל פריינד מהוניאד. רבה של הוניאד-תשב. נספה בשואה."},{"i":38819,"n":"פנט, מנחם מנדל מדעש","f":"יחזקאל-מראה יחזקאל","k":"בעל שערי צדק-תרמד","bt":"תקעח","bp":"טערצאל","dt":"תרמה - יג תשרי","b":"תלמיד החת\"ס, ר שלמה זלמן בניהאד מפרשבורג. חתן הגביר ר יהודה ליב קרויס מאויהל ועבר לשם והתקרב ל\"ישמח משה\". רב בכפר ארישאר-ליד דעש-תרב (בגלל שנאסרה על רוב היהודים הישיבה בדעש), דעש-תריח והחל לשמש כאדמור מדעש, והקים כולל \"אהבת ציון לזיבנבירגן\" וישיבה גדולה בדעש. נחשב לראש היהדות החרדית בטרנסילבניה. בנו ר משה על מקומו אחריו בדעש (בנו ר יחזקאל בעל \"כנסת יחזקאל\" אחריו ובנו ר יעקב אלימלך בעל \"זכרון יעקב\" אחריו). חתנו - ר שבתי ניסל בעל \"מבשר טוב\". חיבר \"אבני צדק\", \"שערי צדק\", ועוד. היה מאותם שנתנו שלום לעני בביהמ\"ד של החת\"ס - במעשה הידוע. בעתון \"עמוד היראה\"-תרכז נכתב שרבים החלו להתפלל בנוסח ספרד ובין היתר בגלל האדמור מדעש, וכן בעתון הגרמנית \"דער אונגרישע איזראעליט\"-תרמז מתלונן שהעיר דעש הפכה למעוז חסידי פולני.","bk":[["מעגלי צדק [עה\"ת] (דעעש)",""]]},{"i":38820,"n":"פנט, משה מדעש","f":"מנחם מנדל פנט","bt":"תרג","dt":"תרסג - כד כסלו","b":"חתן ר יצחק יחיאל כהנא-נכד \"קונטרס הספיקות\", ובזיוו\"ש חתן ר נחום בנימין מקלויש. חסיד צאנז. רב באורישר נימוזשא, אדמור בדעש על מקום אביו. בנו ר יחזקאל בעל \"כנסת יחזקאל\" על מקומו אחריו. חתנו ר יהודה פרידלנדר מבורגו-פרונד."},{"i":38821,"n":"פנט, משה מדעש-שאץ","f":"יחזקאל מדעש","k":"אדמור מדעש שאץ בארהב","dt":"תשל - ז אב","b":"חתן ר משה מושקוביץ משאץ וטשרנוביץ. היגר לארה\"ב, וכיהן כאדמור מדעש-שאץ בארה\"ב."},{"i":38822,"n":"פנט, נחום מאיר מדעש-שאץ","f":"משה מדעש-שאץ","k":"אדמור מדעש שאץ בארהב","b":"אדמור מדעש-שאץ בארה\"ב על מקום אביו."},{"i":38823,"n":"פנט, פנחס מדברצין","f":"יהודה ליב מטערצל","b":"נכד ר יחזקאל פנט מקרלסבורג. חתנו - ר אברהם שמואל בנימין ניימן מקלויזנבורג."},{"i":38824,"n":"פנט, צבי אלימלך מבני ברק","f":"חיים אלתר מתל אביב","b":"נכד ר מאיר שלום רוטנברג בן ר יהוסף האדמור מקאסאן."},{"i":38825,"n":"פנט, צבי מאיר מדעש","f":"יוסף מדעש","b":"חתן ר יחזקאל מנחם מדעש. נשיא כולל \"אהבת ציון זינבירגן וסילאדי\". התגורר בבני ברק, ועבר לארה\"ב. בנו ר יצחק יחיאל מבני ברק."},{"i":38826,"n":"פנט, שמואל יהודה","f":"יוסף מדעש ונ\"י","b":"חתן ר יחזקאל מנחם מדעש. מתגורר בניו יורק."},{"i":38827,"n":"פנטא, אליעזר מנדל מניקלשבורג","dt":"תנ","b":"רב בניקלשבורג והמדינה. חתנו - ר אשר אנשל וינר מפרג."},{"i":38828,"n":"פנטינסקי, קופל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38829,"n":"פניאל מרדכי מקושטא ושלוניקי","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":38830,"n":"פניאל, שלמה","f":"אברהם","k":"בעל אור עינים","b":"מחכמי תורכיה-שיב. חיבר \"אור עינים\""},{"i":38831,"n":"פניגשטין, אריה מרדכי מיפו ונ\"י","f":"ברוך חיים","bt":"תרסו","bp":"יפו","b":"תלמיד ישיבת \"אור זורח - נוה שלום\", ואצל רש\"מ זילברמן מוירשוב, ר\"י הלוי קלמנס מתל אביב. רב בלוס אנגלס-תרצב, סטוקטון-תרצו, וניס-לוס אנגלס-תרצז."},{"i":38832,"n":"פנסטר, ישראל","dt":"תשג","b":"רב בלמברג,דרוהביטש"},{"i":38833,"n":"פנסטר, מאיר אברהם מדרוהוביטש","k":"אדמור מלמברג","b":"אדמור מלמברג בדרוהוביטש, בנו ר ישראל רב בלמברג ובדרוהוביטש - נספה בשואה."},{"i":38834,"n":"פנציירי, שבתי מרומא","b":"רב ברומא. תשובה ממנו בשו\"ת הרמ\"ז. חתום על פסק עם ר יוסף פייאמיטה."},{"i":38835,"n":"פנצר, חיים מגורליץ","b":"מחנך ומנהל \"יסודי התורה\" בקראקא."},{"i":38836,"n":"פנצר, יהודה ל' יצחק מדרוהוביטש","f":"יוסף מדרוהוביטש","k":"בעל פרי יהודה","bt":"תרנה","dt":"תשג","b":"מחכמי דרוהוביטש שהתפרנס ממסחר. נספה בשואה. חיבר \"פרי יהודה\" למברג תרפז. ?? לא באוצר ??"},{"i":38837,"n":"פנצר, יוסף מדרוהוביטש","f":"יהודה יצחק","k":"בעל פרי יוסף","bt":"תרכו","bp":"דזיקוב","dt":"תרעט","b":"מכונה \"העילוי מדזיקוב\". חתן ר שמואל זנויל גולדפינגר מאוסטרובצה. רב בדרוהוביטש-תרנו. חיבר \"פרי יוסף\" דרוהוביטש תרנז. חתניו - ר זאב וולף ניסנבוים בעל \"כבוד הלבנון\", ר יצחק שפירא בן האדמור ר חיים יחיאל מיכל מדרוהוביטש."},{"i":38838,"n":"פנקובסקי, חנוך הניך מאוסטרובצא","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":38839,"n":"פנקס, דוד צבי מתל אביב","b":"מראשי בית הכנסת הגדול בתל אביב. עורך המאסף \"בית הכנסת\" - תל אביב תשו."},{"i":38840,"n":"פנר, משה מאוזירן","bp":"פשמישל","dt":"תשג","dp":"טלוסט","b":"חתן ר מרדכי אפשטיין מאוזירן. רב באוזירן על מקום חותנו. נספה בשואה."},{"i":38841,"n":"פס, ברוך מרישא","b":"חסיד צאנז. מחכמי רישא, רב בלנצהוט. גיסו של ר אליעזר צוקר מברגסז - והחליפו חדו\"ת-תרלז."},{"i":38842,"n":"פסברג, יחיאל מיכל מבוליחוב","f":"יעקב","bt":"תרלו","bp":"בוליחוב","dt":"תש..","b":"חתן ר שמעון הכהן פישביין. מחכמי הולין (ליד קלוש) ומלמד לצעירים, עבר לקרכוביץ (ליד דולינה) . נספה בשואה."},{"i":38843,"n":"פסווג, יהושע מרוהטין","b":"בנו של אב\"ד רוהטין. תשובה אליו - טוט\"ד."},{"i":38844,"n":"פסח אהרן מניקלשבורג וירושלים","b":"מחכמי ירושלים, בשליחות-תרכב ביה\"ח \"ביקור חולים\"."},{"i":38845,"n":"פסח הכהן מאלטונא","f":"יעקב הכהן","bp":"אלטונא","dt":"תקצא - ט סיון","dp":"אלטונא","b":"נכד ר שמואל עלקין בעל \"מקום שמואל\". תלמיד ישיבת וילנא. דיין באלטונא. אחיו - ר משה-אביו של הדיין ר יעקב הכהן."},{"i":38846,"n":"פסח הכהן מזסלב","f":"שלמה זלמן מאוסטרהא","b":"חתן ישכר דב בער מגזע צבי מזלוטשוב. רב בזסלב. גיסו של ר יעקב שמעון מזסלב. אביו של ר אבא הכהן זוסמן."},{"i":38847,"n":"פסח הכהן מלנטשנא","b":"תלמיד ר לוי יצחק מברדיטשוב, והחוזה מלובלין."},{"i":38848,"n":"פסח הלוי מקושטא","f":"גבריאל","b":"מדפיס בקושטא-תקיד אצל ראובן ונסים בני יונה אשכנזי."},{"i":38849,"n":"פסח יהודה הכהן מטרנוב","b":"רב בטרנוב. חתנו ר נפתלי צבי גולדברג על מקומו אחריו."},{"i":38850,"n":"פסח יהודה הכהן מסקיהיד","f":"שבתי","dt":"תרס - בערך","b":"רבה הראשון של סקיהיד-תרכט. בנו או נכדו ר שבתי כהן קאהן - מדפיס בסקיהיד."},{"i":38851,"n":"פסח מאוסטרהא","f":"אריה ליב","dt":"תקסח - אחרי","b":"דין באוסטרהא. הסכים על \"עין יעקב\"-תקעא, ועוד."},{"i":38852,"n":"פסח מאלטונא","f":"אלקנה","k":"בעל תקון פסח","dt":"תקג - כב אלול","dp":"אלטונא","b":"תלמיד ר אברהם ברוידא. הו\"ל ספר אחיו ר שמואל \"מקום שמואל\" עם שיר הקדמה ממנו וגם מחדושיו, חיבר \"תקן פסח. בנו - ר אלקנה מאלטונא."},{"i":38853,"n":"פסח מאלסטויקער","b":"תלמיד בעל התניא, בנו ר דב בער, ונכדו הצמח צדק."},{"i":38854,"n":"פסח מוילנא","f":"צבי","dt":"תקנא - ב אלול","b":"חתן ר זלמן - מגיד בוילנא. דיין בוילנא ומו\"צ."},{"i":38855,"n":"פסח מוילנא","f":"דב בער","dt":"תקסד - כט תמוז","dp":"וילנא","b":"מחכמי וילנא."},{"i":38856,"n":"פסח מזולקוא","f":"יצחק מסאסלב וזולקוא","k":"הו\"ל קרנים עם דן ידי","dt":"תפה - טו אד\"ב","dp":"זולקוא","b":"רב בזאסלב(=סאסלב) על מקום אביו, מגיד בזולקוא על מקום אביו. דודו (אחי אמו) ר שמשון אוסטרופולר, הו\"ל ספר קרנים עם פירוש דן ידין לדודו - ר שמשון. נזכר ב\"מפעלות אלקים\"."},{"i":38857,"n":"פסח מליגום","dt":"תרכז","b":"אב\"ד ליגום. בנו - ר אליהו יאנובר."},{"i":38858,"n":"פסח מנובאק","dt":"תרלט","b":"רב בנובאק"},{"i":38859,"n":"פסח מקראקא","dt":"תקכט - א סיון","b":"עק\"ה,מגדולי חכמי קרקא"},{"i":38860,"n":"פסח מקראקא","f":"דוד","dt":"תקכט - כו סיון","dp":"קראקא","b":"גביר מחכמי קראקא, נהרג עק\"ה."},{"i":38861,"n":"פסח מראוונא","dt":"תרלג - כד אלול","b":"רב בוורשה"},{"i":38862,"n":"פסח משקלוב","dt":"תצז - ט אייר","b":"דיין בברודי"},{"i":38863,"n":"פסח, אברהם יוסף מבלגיה וארה\"ב","f":"מנחם מנדל בן אברהם י","k":"בעל מי באר","bp":"לודז","b":"תלמיד אדמורי גור ה\"שפת אמת\" ובנו. נסמך מאת ר יחזקאל ליפשיץ מקאליש בעל \"המדרש והמעשה\". רב באנטורפן-תרפה, ור\"מ ב\"יסודי התורה\", ויסד ישיבה, ניצל מהשואה דרך צרפת, היגר לארה\"ב-תשב. רב ור\"מ בישיבת תומכי תמימים-ניו יורק-תשד."},{"i":38864,"n":"פסח, אליהו מקנדיא","b":"גביר מחכמי קנדיא-שנות ה-ת'."},{"i":38865,"n":"פסח, אלעזר מקושטא","dt":"שנט","dp":"[קושטא]","b":"מחכמי קושטא, חתן ר שמואל יפה בעל \"יפה תואר\". מתורתו ב\"יפה ענף\" לחותנו. קרובו של הגביר ר משה בן אברהם פסח, שסייע לר שמואל יפה להדפיס את ספריו."},{"i":38866,"n":"פסח, דוד ביג משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":38867,"n":"פסח, יצחק מקרסובזר-קרים","f":"מאיר","b":"תלמיד ר חזקיה מדיני בעל \"שדי חמד\" בקרסובזר."},{"i":38868,"n":"פסח, מאיר מקרסובזר-קרים","b":"מחכמי קארסובאזאר(=קרסובזר)-קרים וממקורבי ר חזקיה מדיני בעל \"שדי חמד\" המזכירו בספרו. בנו - יצחק."},{"i":38869,"n":"פסח, משה מקושטא","f":"אברהם","b":"גביר בקושטא, קרובו של ר אליעזר פסח שהיה חתנו של ר שמואל יפה בעל \"יפה תואר\". מימן את הדפסת ספרי ר שמואל \"יפה מראה\" ו\"יפה תאר\"."},{"i":38870,"n":"פסח, משה שמעון מלאריסה","bt":"תרכט","bp":"לאריסה","dt":"תשטז - כח חשון","b":"רב בוולו-יוון (ליד שלוניקי), בעל ספריה חשובה, וחיבר הגהות רבות, חלקם מאביו שהיה רב בשלוניקי. החזיק בספריה חשובה ובה ספרים בלאדינו וכתבי יד רבים. פרסם מאמר ב\"המאסף\"."},{"i":38871,"n":"פסח, שלמה","dt":"תקנז","b":"נספד ע\"י גיסו ב\"מראה האופנים\"."},{"i":38872,"n":"פסחוביץ, חיים מסטרי-דאראגי","f":"יחזקאל","bt":"תרלז","bp":"ליפנישוק-פלך וילנא","b":"תלמיד קיבוצי תורה באיישישוק, לידא, סלובודקא, בריסק, קובנא, וילנא. רב בסטארי-דאראגי-פלך מינסק-תרס. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. נסמך מאת: ר שלמה הכהן מוילנא, ר מאיר נח לוין מוילנא, ר מרדכי מסלונים, ר חיים יהודה סאסניצע מסמרגון, ר חיים סגלוביץ מוילנא, ר פנסח רוזובסקי משוינצאן."},{"i":38873,"n":"פסחיא קרודו, חיים"},{"i":38874,"n":"פסטרנק, אברהם חיים מקוזלוב","b":"מחכמי קוזלוב-תרז."},{"i":38875,"n":"פסטרנק, יהושע","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":38876,"n":"פסטרנק, שלמה ממישקולץ","b":"ניצל מהשואה ואחריה דיין במישקולץ, חתם-תשו עם ר יקותיאל מרדכי שיק, ור אברהם יצחק."},{"i":38877,"n":"פסל, אברהם שמואל שמלקא הלוי","b":"חסיד ר נפתלי מרופשיץ. רב בפשצלוב. מקורב לגדולי האדמורים."},{"i":38878,"n":"פסל, הירש מנאגי-קאניזא","b":"רב הקהילה הניאולוגית בנאג'י-קאניזא-תריא על מקום ליאופולד לעוו, ונימן אדא על מקומו אחריו."},{"i":38879,"n":"פסל, יעקב יצחק מקורטשין","bt":"תרפט","bp":"קורטשין","b":"ניצל מהשואה. היגר לשטוקהולם ומשם כותב בעתוני העולם בעניני יהדות."},{"i":38880,"n":"פסל, מרדכי מגורליץ","b":"דומ\"צ בגורליץ-תר\"מ"},{"i":38881,"n":"פסל, מרדכי מסאסוב","bt":"תרסו","bp":"סאסוב","dt":"תשג","dp":"זלוטשוב","b":"מעסקני צא\"י וממשתתפי \"בית יעקב\". הוציא אסופה משיריו וספוריו בתרצח. נספה בשואה."},{"i":38882,"n":"פסלבורג, אברהם מפרג","f":"זלמן פסלבורג","dt":"תקו - כו אדר","b":"דומ\"צ בפרג"},{"i":38883,"n":"פסלבורג, זלמן","f":"אשר אנשיל וינר","dt":"תקה","dp":"לייפן","b":"עק\"ה"},{"i":38884,"n":"פסלר, בן ציון מקולומיאה","f":"ליפמן מגווזדיץ","k":"בעל די אידישע רעליגי","bt":"תרנד","bp":"גווזדיץ","dt":"תשב","b":"בעל תואר דוקטור מאוני' וינה. התקרב לבעל התשובה ד\"ר נתן בירנבוים. ממנהיגי צא\"י ופא\"י. יסד עתון \"אונזער ווארט\". פרסם מאמרים ושירים בעתונים שונים. חיבר חוברות וביניהם \"די אידישע רעליגיע..\" קולומיאה תרפט. נספה בשואה."},{"i":38885,"n":"פסמניק, מרדכי","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":38886,"n":"פסנר, יעקב מקראקא","b":"מחכמי קראקא - תשובה אליו \"מנחת יחזקאל\"."},{"i":38887,"n":"פסקוביץ, חיים ברוך","b":"ר\"מ בישיבת \"בית יוסף\"-ביאליסטוק. היגר לארה\"ב. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב, \"אוהל יוסף\" נ\"י תשו."},{"i":38888,"n":"פסקי דין מבית הדין הגדול (המאה ה- 20)","bk":[["משפטי שאול",""],["פסקי דין רבניים (א",""]]},{"i":38889,"n":"פסקין, יעקב מוילנא","b":"ראש ישיבת מייליס בוילנא."},{"i":38890,"n":"פסקין, שמואל","bt":"1871","bp":"וילנא","b":"נכד ר יעקב פסקין ראש ישיבת מייליס. למד הנדסה ורפואה בארה\"ב, והצטרף לתנועה הסוציאליסטית בהשפעת אחיו ישראל. עורך \"צייט גייסט\", פרם חוברות סוציאליסטיות ובהם \"סטרייקס און זייער ניצליכקייט פאר דיא ארבייטער\", ועוד."},{"i":38891,"n":"פסקל, יוסף אירווינג","f":"ישעיהו","bt":"1890","bp":"שאקי","b":"היגר לארה\"ב ולמד רפואה. מייסד המכון לאופומטריה ונשיאו."},{"i":38892,"n":"פעטופי, משה יוסף","b":"רב בווערעשוואר-תק\"צ"},{"i":38893,"n":"פעטני, דוד צבי מפרשבורג","k":"בעל מהרש\"א הארוך","b":"מחכמי פרשבורג. חיבר ספר על המהרש\"א - טירנוי תשב. ?? לא באוצר ??"},{"i":38894,"n":"פעטני, מרדכי מוייצען","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":38895,"n":"פעטשו, אברהם מאזמיר","b":"רב באיזמיר"},{"i":38896,"n":"פעסיס, פנחס מדובנא","k":"בעל עיר דובנא","bt":"תרכט","bp":"דובנא","dt":"תרסד","b":"עבר אל חותנו באליק. פרסם מאמרים ב\"המליץ\", הצפירה\", ועוד. חיבר גם \"עטרת הלויים\", הניח חבורים בכת\"י ובהם \"ר שלמה מדובנא\", \"קרית חכמים\"."},{"i":38897,"n":"פעסל, משה משטמפן","f":"שמואל","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":38898,"n":"פעסעלעס - משפחה","b":"מקור השם מהאשה פעסל אמו של ר אברהם משטמפן."},{"i":38899,"n":"פעסעלעס, אברהם משטמפן","f":"שמואל","bp":"אובן ישן","dt":"תקסג - כד טבת","dp":"שטמפן","b":"ממגורשי אויבן ישן (בודפשט). מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן. חתנו ר יעקב קופל קונשטט בעל חידושי יעב\"ץ."},{"i":38900,"n":"פעסעלעס, אליהו מוילנא","f":"צבי הירש","dt":"תקלא - ט תשרי","dp":"וילנא","b":"אחיו של ר שלמה זלמן ריבלין משקלוב. חתן ר יוסף בלוך (ולפי ברוורמן-אנשי שם - היה חתן ר אלחנן בן שבתי חפץ). גביר עשיר מראשי קהילת וילנא ומראשי יהדות ליטא. קרובו של הגר\"א ותמך בו - היה ממונה על עזבון זקנו ר משה ריבקש בעל \"באר הגולה\". בניו - ר יוסף אלי'ס-חתן ר אביגדור רבה האחרון של וילנא, ר דב בר-חתן ר אריה בלוך. חתניו: ר נח מינדעס ליפשיץ בעל \"פרפראות לחכמה\", יצחק איזיק בן אברהם מעמדין, ר שמעון הגדול מוילנא (=אברהם שמעון בן צבי הירש פראגר)."},{"i":38901,"n":"פעסעלעס, אנשל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":38902,"n":"פעסעלעס, אריה ליב מוילנא","b":"גביר מראשי קהלת וילנא-תקע בערך."},{"i":38903,"n":"פעסעלעס, דב בער מוילנא","f":"אליהו פעסעלעס מוילנא","dt":"תקלז-ט- כח אלול","dp":"וילנא","b":"מחכמי וילנא. חתן ר אריה ליב בלוך מוילנא. בניו: ר אריה ליב (המכונה - ר ליבלע ר בערס) ור צבי הירש."},{"i":38904,"n":"פעסעלעס, יהודה מוילנא","f":"יוסף מוילנא","dt":"תקסט","dp":"וילנא","b":"מחכמי וילנא, נפטר בחיי אביו."},{"i":38905,"n":"פעסעלעס, יוסף מוילנא","f":"אליהו פעסעלעס מוילנא","k":"יוסף אלי'ס","bp":"וילנא","dt":"תקעא - יט כסלו","dp":"וילנא","b":"מצאצאי ר משה רבקה'ש בעל \"באר הגולה\". חתן ר שמואל בן אביגדור רבה האחרון של וילנא. מחכמי וילנא. עמד בקשרי מכתבים עם דוד פרידלנדר ושאר משכילי ברלין, שלמה דובנא ישב אצלו בוילנא כשעזב את ברלין וחיבר לכבודו \"ברכת יוסף\" על שציווה לכתוב כל 24 ספרי הקדש על קלף. זכה לאותות הצטיינות מפוניאטובסקי מלך פולין על מעשי חסד רבים שעשה. לכבודו כתב ולכבוד אחייניו הגבירים ר ליב ור הירש בני בער - כתב ר יחזקאל את הספר תולדות אדם. בנו ר יהודה נפטר בחיי אביו-תקסה."},{"i":38906,"n":"פעסעלעס, משה משטמפן","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן. אחיו - ר אברהם."},{"i":38907,"n":"פעסעלעס, שמואל משטמפן","f":"אברהם","b":"חתן ר יוסף קוטנפלן. מחכמי שטמפן. נאסר בזמן מלחמת נפוליאון. חתנו - ר קופל אלטקונשטט בעל חדושי יעב\"ץ. חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":38908,"n":"פער, נפתלי הרץ מברלין","f":"אהרן אופנהיים מפפד\"מ","dt":"תסח - ג שבט","dp":"ברלין","b":"אחיו של ר מיכל אב\"ד פרידבורג ואויפבאך. חתן ר יהודה יודא ברלין. בנו ר יהודה בער - פרנס בפפד\"מ."},{"i":38909,"n":"פעראטי, גיוסטיניא לעווי","b":"משוררת בסאסא פערדאטא-איטליה."},{"i":38910,"n":"פעריי, יעקב מהאג","dt":"תרמג - ה תשרי","b":"רב הספרדים בהאג"},{"i":38911,"n":"פערל, אהרן בר מפרג","k":"בעל פתחי צדק","b":"מחכמי פרג. חיבר \"אבל כבד\" על מגילת איכה, \"פתחי צדק\"."},{"i":38912,"n":"פערסיץ, זליג ממוסקבה","b":"גביר ממוסקבה-תרע. תרם לישיבות בירושלים. מחותן עם ר שלמה קרליבך מליבק."},{"i":38913,"n":"פערפלאציק, יצחק הלוי מקרוסנא","f":"אהרן","bt":"תרכה","dt":"תרצב - שבט","b":"רב בקרסנא(=קראסנא)-ווהלין-תרנ, פלטניצה(=פלאטניצא)-פלך מינסק, עלה לארץי-תרצב."},{"i":38914,"n":"פעשיס, מרדכי","b":"מגדולי חכמי דורו,רב בנאראיוב"},{"i":38915,"n":"פפה נתנאל חיים","bt":"1835","dt":"ה'תרסה 1905","bk":[["דבר ישועה",""],["מגיד מישרים",""]]},{"i":38916,"n":"פפיגיה, מרדכי צבי מרישא","b":"מחכמי רישא - תשובה אליו \"שואל ומשיב\"."},{"i":38917,"n":"פפירקורן, מאיר","b":"תלמיד ר יוסף קולון. תמך בר יעקב פולק במחלוקת כנגדו בענין מיאון קטנה."},{"i":38918,"n":"פפירקורן, צבי הירש מלבוב","dt":"תיד - כה כסלו","b":"דיין בלבוב"},{"i":38919,"n":"פפלצבורג, יצחק איצק","f":"מאיר","k":"בעל באר יעקב","b":"חתן ר יוסף שטיינהרט מאלזס המזכירו בספרו. גם דודו ר ישעיה פיק (גיסו של חותנו) הזכירו בספרו. אחיו - ר יעקב ברלין מפיורדא, ערך והו\"ל - \"באר יעקב\" לר יעקב ברלין - פירודא תקכז - עם חדושים ותוספות ממנו."},{"i":38920,"n":"פפנהיים, אהרן","b":"מרביץ תורה בנירנברג-ר\"י"},{"i":38921,"n":"פפנהיים, בנימין וולף","f":"חיים צבי","bt":"תרי","bp":"פרשבורג","dt":"תרצח - ט אייר","dp":"וינה","b":"תלמיד הכת\"ס. חתן ר גבריאל שיף מצעהלים. רב בפריז, וינה-תרנה וכיהן כראש הקהלה החרדית שיף-שוהל, ועסקן היהדות החרדית."},{"i":38922,"n":"פפנהיים, הרמן מפרשבורג","f":"וולף","b":"מראשי קהלת פרשבורג על מקום אביו - בזמן הכת\"ס."},{"i":38923,"n":"פפנהיים, וולף מפרשבורג","b":"ממנהיגי היהדות החרדית בפרשבורג, יחד עם גיסיו ר משה בטלהיים, ור שמואל גוטמן (שהיו נשואים לאחיות והתעשרו כאשר גיסם-אחי נשותיהם המומר מוינה הוריש להם את כל רכושו העצום), תרמו לקהלה בזמן החת\"ס."},{"i":38924,"n":"פפנהיים, עזריאל איזידור מפרשבו","b":"עמד בראש אגף הקנאים בפרשבורג-תרף המכונים בשם \"השחורים\" בתמיכת אגודת ישראל. ראה הקהלה-תרצב."},{"i":38925,"n":"פפנהיים, קלמן מפרשבורג","b":"ראש קהלת פרשבורג-תרכג בזמן הכת\"ס. היה בקשרים עם השלטונות והצליח למנוע את השתלטות המשכילים בראשות ר זליג ליב שיק. נבחר כאחד משלושת נציגי פרשבורג לקונגרס יהודי הונגריה בפעשט."},{"i":38926,"n":"פפנהיים, שלמה מברסלוי","k":"בעל יריעות שלמה","bt":"תק","dt":"תקעד","b":"רב בברסלוי. חיבר \"יריעות שלמה\", \"ארבע כוסות\" ועוד. (אולי הוא שחתם שמו \"שלמה פפ\"ה)."},{"i":38927,"n":"פפנהיים, שמואל מפרשבורג","b":"ראש קהלת פרשבורג-תרלו."},{"i":38928,"n":"פפנהים שלמה","bt":"1740","dt":"ה'תקעד 1814","bk":[["אגדת ארבע כוסות",""],["ארבע כוסות",""],["חומר ביד היוצר",""],["חשק שלמה",""],["יריעות שלמה",""],["יריעות שלמה [ג\"ח]",""],["מאמר גאולת מצרים ומצות תפלין",""]]},{"i":38929,"n":"פפר, אברהם שמואל מניסקא","bt":"תרסב","bp":"ניסקא","b":"נכד ר חיים ריישר. התגורר ברדומישל ורישא, ניצל מהשואה לרוסיה, עבר לאוסטריה והיה רב ומחנך מטעם אגו\"י במחנה וולץ. עבר ללונדון ויסד ת\"ת. עלה לארץ. מחותן עם האדמור מסקווירא-ניו יורק."},{"i":38930,"n":"פפר, אלתר שאול מויליצקה","f":"ישראל אלימלך","k":"בעל אבני זכרון-תרפג","bt":"תרלד","bp":"ויליצקה","dt":"תרצו - יט ניסן","dp":"ניו יורק","b":"תלמיד ר שרגא פיבש וולף מצאנז, ר אריה ליב הורביץ מסטרי שהביא מתורתו בספרו \"הרי בשמים\". חתן הגביר ר מאיר יהודה ליב יגר מביטשקוב. פתח ישיבה בביטשקוב-תרנו בבית חותנו, רב וראש ישיבה בסערט-תרסו, חזר לביטשקוף-תרסט. היגר לארה\"ב-תרעב וכיהן כרב ק\"ק \"אנשי אונגרין\" בניו יורק. חיבר \"אבני זכרון\" מרמורש-סיגט תרפג. פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג.","bk":[["אבני זכרון – שו\"ת",""]]},{"i":38931,"n":"פפר, זליג ליב מקווגאורש וירושל","bp":"הונגריה?","dp":"ירושלים","b":"תלמיד החתם סופר, רב בקווגאורש (הונגריה). בשנת תריח עלה לירושלים."},{"i":38932,"n":"פפר, יהודה אריה ליב מקיצע","bp":"שטמפן","dt":"תרה - כז אלול","dp":"וינה","b":"תלמיד החת\"ס. רב בטשוס-תקעב, קיצע-תקפג."},{"i":38933,"n":"פפר, יחיאל מיעזערזאני","b":"רב ביעזערני-תרע. חתנו - ר אליעזר ניסן מדארנא-ואטרא."},{"i":38934,"n":"פפר, יחיאל מלשקוביץ","bp":"לשקוביץ","b":"חסיד צורטקוב. חתן ר משה בעזנער ראש הקהל באוזירן. רב באוזירן (והיה על זה מחלוקת בין האדמור ר ישראל מצורטקוב שתמך בו לבין הצדיק ר ולוולי גוטסמן)."},{"i":38935,"n":"פפר, מנחם מנדל משטמפן","b":"מחכמי שטמפן, חתם-תקסט עם ראשי הקהלה."},{"i":38936,"n":"פפר, משה מבודפשט","f":"חיים","dt":"תשז - כו אדר","dp":"בודפשט","b":"תלמיד השב\"ס, ור שמעון סופר מערלוי(=אויהל). רב בחברת ש\"ס בבודפשט. ניצל מהשואה."},{"i":38937,"n":"פפרוש, אברהם יצחק מירושלים","f":"צבי הירש","k":"הו\"ל הגדה","dt":"תרנג","dp":"ירושלים","b":"סופר ונאמן הכולל בירושלים, בשנת תרכג בשליחות לרוסיה, הדפיס הגדה בירושלים בשנת תרכג"},{"i":38938,"n":"פפרמן, נחום","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":38939,"n":"פפרקורן המומר","b":"מומר באשכנז-רס שעסק בהלשנות על היהודים ובעיקר על התלמוד."},{"i":38940,"n":"פפרקורן, צבי הירש מלבוב","f":"יהודה ליב","dt":"תיד - כה כסלו","dp":"לבוב","b":"דיין בלבוב. חתם-שצט עם ר יוסף הלר, ר שמשון בן קלונימוס קלמן, ועוד. חתם-שצז עם ר משה נכנע מייזות(=מייזיס), ועוד."},{"i":38941,"n":"פצילינו-פסילינו, שמואל מקושטא","b":"מדפיס בקושטא-רעו. הדפיס \"שות הרשב\"א\"."},{"i":38942,"n":"פצינר, יצחק מאיר","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":38943,"n":"פצ'יצ'ה ן, יוסף מאלגיר","f":"מרדכי","bt":"שך - בערך","dt":"שץ - בערך","b":"הגיע מפאס, רב במסתגאנם. נזכר ב\"חוט המשולש\" על שאלות ששאל מר שלמה דוראן."},{"i":38944,"n":"פצ'יצ'ה, סעדיה ן עמרון מפאס","bp":"מכנאס ?","b":"סופר בי\"ד בפאס-שנא עם ר יעקב ן דנאן."},{"i":38945,"n":"פצלאן ן, אפרים","f":"עזריה","b":"מחכמי המזרח-ד'תת. חיבר פיוטים ונמצאו מהם בגניזה."},{"i":38946,"n":"פצנובסקי, אברהם צבי מפילץ ופיע","f":"אלעזר מפיעטריקוב","k":"בעל ברית אברהם","dt":"תקעט-צד - ז אדר","b":"חתן ר יהודה ליב ליפשיץ מאופוטשנא. רב בפילץ-תקס, פיעטרקוב-תקעב. תלמיד החוזה מלובלין, ותלמיד זקנו ר שלמה זלמן מפיעטריקוב ואפאטשינוב, ור משה מפיעטריקוב. חיבר \"ברית אברהם\". בנו ר משה הירש מלובלין. חתנו - ר אברהם צילך בן מאיר מלאסק."},{"i":38947,"n":"פצנובסקי, יוסף מלודז ופביאניץ","f":"משה מפיעטרקוב","k":"בעל פרדס יוסף","b":"רב בלודז-תרץ, פביאניץ. פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד. אחיו של ר שלמה זאב מלודז."},{"i":38948,"n":"פצנובסקי, יצחק מלושצבה","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":38949,"n":"פצנובסקי, מיכאל","b":"רב בגלובנה"},{"i":38950,"n":"פצנובסקי, שלמה זאב מלודז","f":"משה מפיעטרקוב","b":"נכד(-אבי אמו) ר דוד דב מייזלש מלאסק. תלמיד ר ישראל יהושע מקוטנא. חתן ר אלתר רדליך מלודז. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"הנצח\" - לבוב תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג. אחיו - ר יוסף מפביאניץ."},{"i":38951,"n":"פצ'ניק, אברהם שמואל מברזנא","f":"יוסף האדמור מברזנא","k":"אדמור מסטעפין ברזנא","bt":"תריא","dt":"תרעה-ח - יא טבת","b":"חתן ר מרדכי מזוויהל (שושלת זלוטשוב). אדמור בברזנא על מקום אביו-הוכתר ע\"י זקנו ר אהרן מטשרנוביל בגיל 19, וכיהן כאדמור כ-50 שנה."},{"i":38952,"n":"פצ'ניק, אהרן מרובנא","f":"יצחק מברזנה","k":"אדמור מברזנא רובנא","bt":"תרמט","dt":"תשג - י שבט","b":"חתן ר נחום מסמבור. אדמור בחיי אביו, התישב ברובנא-תרצב. בזמן השואה הצטרף לפרטיזנים,ושם נפל בקרב"},{"i":38953,"n":"פצ'ניק, יוסף מברזנא","f":"יצחק מברזנא","k":"אדמור מסטעפין ברזנא","bt":"תקצד","dt":"תרל - כד תשרי","b":"חתן ר שמואל אשכנזי-חתן ר יצחק מאיר מזינקוב, ובזיוו\"ש חתן ר אליקים עגציל מאוסטרהא. אדמור בברזנא על מקום אביו כ-4 שנים."},{"i":38954,"n":"פצ'ניק, יוסף מסארני","f":"אברהם שמואל מברזנא","k":"אדמור מסארני","dt":"תרפ - ה ניסן","b":"חתן ר שלום מברהין-קוידנוב (לכוביץ). אדמור בסארני, עבר לקיוב-תרעד וחזר אל חסידו בסארני. פעל הרבה למען הפליטים - בזמן מלחה\"ע ה-I."},{"i":38955,"n":"פצ'ניק, יחיאל מיכל מברזנא","f":"דוד מסטעפין","k":"אדמור מסטעפין ברזנא","dt":"תרט - טו כסלו","b":"חתן ר ליב מסטולין-תלמיד ר שלמה מקרלין. ישב בסטולין, כיהן כמגיד בבאהפאלי, ברזנא."},{"i":38956,"n":"פצ'ניק, יחיאל מיכל מברזנא","f":"יצחק מברזנא","k":"אדמור מברזנא","dt":"תשב - יב אלול","dp":"ברזנא","b":"חתן האדמור מראדום. עלה לארץ ולמד בסמינר \"מזרחי\" בירושלים. חזר לחו\"ל וכיהן כאדמור בקרלין-תרפט, ברזנא. נספה בשואה."},{"i":38957,"n":"פצ'ניק, יצחק","f":"יהושע נחום פצ'ניק","dt":"תשב - יד אלול","b":"רב באנטונובקה"},{"i":38958,"n":"פצ'ניק, יצחק מברזנא","f":"יחיאל מיכל מברזנא","k":"אדמור מסטעפין ברזנא","dt":"תרכה - טז אלול","b":"חתן ר אהרן מטשרנוביל. אדמור בברזנא על מקום אביו."},{"i":38959,"n":"פצ'ניק, יצחק מברזנא","f":"אברהם שמואל מברזנא","bt":"תרכז","dt":"תרצט - כג סיון","b":"נכד ר אהרן מטשרנוביל, ונכד-אבי אמו ר מרדכי מזוויהל. חתן ר מרדכי מלויאב (שושלת טשרנוביל). אדמו\"ר בברעזנא-ווהלין-תרעח. חתנו - ר שלום בן ר שלמה זלמינה מואדרשקוב-בסרביה. בניו: ר אהרן, ר יחיאל מיכל."},{"i":38960,"n":"פצ'ניק, נחום יהושע מברזנא דומב","f":"אברהם שמואל מברזנא","k":"אדמור מברזנא","bt":"תרמ","dt":"תשב - יד אלול","dp":"סארני","b":"חתן ר אלתר מרדכי ספרד מאוסטרהא, נציג וואהלין בנשיאות אגו\"י בפולין. רב בסארני (אך התגורר בדומברוביץ)ברזניץ,קליסוב,רוקיטנה,סוחוב,אנטונובקה. נספה בשואה וכן נספה בנו ר יצחק-יב אלול תשב."},{"i":38961,"n":"פצ'ניק, ר' א'","b":"פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":38962,"n":"פקהויז, יצחק משואל מזלוטשוב","b":"מחכמי זלוטשוב - תשובה אליו בטוט\"ד."},{"i":38963,"n":"פקודה ן, בחיי","k":"בעל חובת הלבבות","b":"מחכמי ספרד, מגדולי חכמי המוסר בדורות הראשונים,מופלא במדע ובקדושה,דיין בסרגוסה-ד'ת\"ת"},{"i":38964,"n":"פקודה ן, דוד","f":"אלעזר","b":"משורר, מחכמי ספרד-ר' בערך (אולי בן דודו של ר' בחיי אבן פקודה)"},{"i":38965,"n":"פקטה, יעקב מניר-באטור","k":"בעל אמת ליעקב","dt":"תרפח - ט אדר","b":"תלמיד ר יהושע פריד האדמור מקאפוש. דומ\"צ בניר-באטור-תרסג."},{"i":38966,"n":"פקלי, יעקב הכהן מצפת","b":"מרביץ תורה בצפת-תר\"ל"},{"i":38967,"n":"פקלנישקי, מאיר מיאלוק","dt":"תשג","b":"רבה האחרון של יעלק(=יאלוק). נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":38968,"n":"פקר, אליהו","f":"רפאל","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט."},{"i":38969,"n":"פקר, יעקב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":38970,"n":"פקר, יצחק איזיק","f":"ישראל יקותיאל","k":"בעל מלמד להועיל","b":"חיבר \"מלמד להועיל\" - אודסה תרנח."},{"i":38971,"n":"פקר, נתן נטע מבוריסוב ונ\"י","b":"רב בבוריסוב, ניו יורק."},{"i":38972,"n":"פקר, שמואל יעקב מנאווי-אודסה","f":"ישראל","bt":"תרכו","b":"ר\"מ בקעלם, רב בנאווי אדעס(=נאווי-אודסה)-פלך חרסון-תרסו."},{"i":38973,"n":"פקריס, חיים ל.","f":"שמואל","bt":"1908","bp":"אליטא-ליטא","dp":"פאס","b":"היגר לארה\"ב ולמד מתמטיקה ומדעים. ראש הקבוצה לפיסיקה במכללת קולומביה, עלה לארץ והיה ראש המחלקה למתמטיקה במכון ויצמן."},{"i":38974,"n":"פראג', חיים מזרחי מאלכסנדריה","b":"מדפיס באלכסנדריה. הדפיס את כתב העת \"המאסף\"."},{"i":38975,"n":"פראג', יום טוב מקושטא","f":"אברהם","b":"רב בקושטא. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":38976,"n":"פראג', יעקב מאלגיר","f":"שלם","bt":"של","dt":"ת - בערך","b":"רב בתלמסאן, נזכר בשטר-שף ומכונה \"כמוהר\"ר\" - ולדברי ר יוסף משאש התואר היה מיוחד לגדולים."},{"i":38977,"n":"פראג', שמעיה מאלגיר","bt":"תי","dt":"תף - בערך","b":"רב ומשורר בתלמסאן. מפיוטיו בכתבי יד יהודי תלמסאן."},{"i":38978,"n":"פראגו, דוד מירושלים","b":"מחכמי ישיבת \"נוה שלום\" בירושלים-תקיח."},{"i":38979,"n":"פראג'י, אליהו מקושטא","bt":"תרם","bp":"קושטא","b":"עלה לירושלים, מנהל בחברת יק\"א ורכש קרקעות בארץ."},{"i":38980,"n":"פראג'י, דוד מירושלים","b":"מחכמי ישיבת פירירה בירושלים-תקיח."},{"i":38981,"n":"פראג'י, יום טוב מקושטא","b":"רב בקושטא-שנות ה-ש'. התכתב עם ר שלמה הכהן משלוניק."},{"i":38982,"n":"פראג'י, יעקב מהמה ממצרים","k":"בעל שו\"ת","bp":"פרג?","b":"מחכמי אלכסנדריה-שנות ה-ת'. בקי במקרא ודקדוק ומלמד לתלמידים. תשובה ממנו ב\"מטה יוסף\" לר יוסף הלוי. נזכר אצל החיד\"א שראה את חיבוריו. גיסו - ר שבתי נאווי מרשיד-מצרים."},{"i":38983,"n":"פראג'י, יצחק מירושלים","b":"מקובל מחכמי ירושלים. בשליחות-תקכב בתנוס וחיבר שם הקדמה ל\"תולדות יצחק\" עם השליח ר משה שפירא, ואולי הוא שכתב מצפת-תקנה לר שלמה מולכו ושם מספר שישב בשפרעם."},{"i":38984,"n":"פראג'י, יצחק מקושטא","f":"יום טוב","b":"רב בקושטא-שנות ה-ש'."},{"i":38985,"n":"פראוניל, שמואל ממרוקו","f":"יצחק","b":"רב בפאס-שי, וחתם אז בענין כתובה."},{"i":38986,"n":"פראטו, דוד מאיטליה","f":"אהרן יונתן","k":"בעל תפלה לדוד","bt":"תרמב-ח","bp":"ליוורנו","dt":"תשיא - כט אד\"א","b":"תלמיד ר אליהו בן אמוזג, רה\"ח מרגלית, מכללת פירנצה, עבר לטריפולי ופעל לארגון הקהלה, רב באלכסנדריה-תרפח על מקום ר רפאל די לה פרגולה והקים שם ישיבה, רומא-תרצו, חיבר \"תפלה לדוד\". עורך \"השבוע הישראלי\", \"ישראל\"."},{"i":38987,"n":"פראם, פנחס זליגמן מבאד-הומבורג","bt":"תקפב","bp":"גרוסלנגהים","dt":"תרנח - כב סיון","dp":"פפד\"מ","b":"תלמיד החת\"ס והכת\"ס, וחתן רבו ר יצחק דב במברגר מוירצבורג. מורה אצל ר זעקל ליב וורמסר ממיכלשטט - הבע\"ש ממיכלשטט. רב מבאד-הומברוג-תריא, רב ביהכ\"נ של שמעון וולף רוטשילד בפפדמ, ועבר לשם."},{"i":38988,"n":"פראנג'י, חיים מנחם מקושטא","k":"בעל ישמח לב","b":"מגדולי דייני קושטא-תרלא, חיבר שו\"ת \"ישמח לב\" ו \"מטה לחם\", אב\"ד-תרנג. מכתב אליו מר בן ציון בנימין רודיטי-תרל שהדפיס את ספרו."},{"i":38989,"n":"פראנים, אלישע","f":"יעקב","k":"בעל פירוש לתורה","b":"רב בפיררה-ש'. תשובה ממנו ב\"פחד יצחק\". כנראה הוא בעל פירוש לתורה - כת\"י הנמצא באוכספורד."},{"i":38990,"n":"פ'ראנסייא, דוד מאזמיר","k":"בעל אפד בד","dt":"תרט","dp":"איידין","b":"מחכמי איזמיר, רבה של איידין, דיין בבית דינו של בעל , חיבר \"אפד בד\", \"חקרי לב\""},{"i":38991,"n":"פראנצירי, אפרים","dp":"דמשק","b":"מחכמי טורקיה וארץ ישראל-ש', תלמיד ר חיים ויטאל, ערך וסידר מכתבי רבו. נזכר ב\"נגיד ומצוה\" שהנהיג לומר \"אידרא רבא\" בשבועות, ונזכר גם ב\"לב דוד\" לחיד\"א."},{"i":38992,"n":"פרב, יהודה הכהן מבוצאץ","b":"מחכמי בוצאץ. חתנו היה כנראה ר שלום מרדכי צ'צ'קס."},{"i":38993,"n":"פרביאש, דוד יהודה ליב","f":"אברהם צבי מקמינקא","b":"מכתבו-תרפט - בראש ספר \"תקנת רבים\"."},{"i":38994,"n":"פרבר, אליעזר יעקב מלונדון","b":"רב בלונדון. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":38995,"n":"פרבר, אליעזר ליפמן","f":"יהודה ליב מסלובודקא","k":"בעל דברי אליעזר","bt":"תריג","dt":"תרנב - יא חשון","b":"רב בקיזניצא"},{"i":38996,"n":"פרבר, אריה ליב","dt":"תשג","b":"דיין בלומז'ה-תרע\"ב,רב בקורוצין,בראיגרונד"},{"i":38997,"n":"פרבר, בנימין מוינוטה","b":"רב בוינוטה על מקום ר בנימין ליפשיץ."},{"i":38998,"n":"פרבר, יהודה ליב מסלובודקא","b":"רב בסלובודקה-תר\"נ. בניו: ר אליעזר ליפמן מקוזניצא, ר מרדכי משאוויל, ר דוד, ר צבי הירש מאנגליה."},{"i":38999,"n":"פרבר, יוסף מסלובודקה ותל אביב","k":"בעל עין יוסף","b":"ר\"מ בסלובודקה, עלה לתל אביב-תש וכיהן כראש ישיבת \"בית התלמוד\". פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, \"היכל התלמוד\" - ת\"א תשא - בקובץ התורני שיצא לאור ע\"י בית המדרש \"בית התלמוד\"."},{"i":39000,"n":"פרבר, ישראל מפיקאלן","dt":"תשג","b":"רב בפיעקלין(=פיקאלן). נספה בשואה."},{"i":39001,"n":"פרבר, מרדכי משאוועל","f":"יהודה ליב מסלובודקא","b":"רב בשאוועל-תר\"פ"},{"i":39002,"n":"פרבר, משה מראקישוק","b":"ר\"מ בדוינסק, צמח, ראקישוק. לימד בישיבה וב\"חדרים\" שם."},{"i":39003,"n":"פרבר, צבי הירש מלונדון","f":"יהודה ליב מסלובודקא","k":"בעל כרם הצבי","bt":"תרלט-מג","bp":"סלובודקא-קובנא","dt":"תשכז - כ חשון","b":"תלמיד ר יצחק אלחנן בקובנא, ר יצחק בלזר, ר משה דנישבסקי, ור נפתלי אמסטרדם. רב בקליקול-פלך קובנא-תרסז. היגר לאנגליה וכיהן כעסקן בישיבת \"עץ חיים\" בלונדון, ר\"מ בישיבת מנצסטר (בראשות ר מנחם דב דנוצקי), רב קהלה בלונדון-תרע. ממיסדי ויו\"ר אגודת הרבנים בלונדון. חיבר גם \"אשת חיל\", ועוד. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"אור תורה\" - לונדון תרצד, \"אפריון\" - בודפשט תרפד, \"מגד ירחים\" - סטמר תרפה, \"המגיד\" - סטמר תרפח, \"שערי ציון\" - ירושלים תרפא.","bk":[["כרם הצבי",""],["אשת חיל",""]]},{"i":39004,"n":"פרבר, ראובן מאושפיצין","f":"יהושע אשר זליג","k":"בעל פאר מרדכי","bt":"תרכט","bp":"אושפיצין","dt":"תשטו - כג סיון","b":"תלמיד ר שלמה הלברשטט. בעל תואר דוקטור. רב בויטקוביץ, ובקהלות הסביבה אודרברג ונייטיטשיין. רב צבאי במלחמת העולם הראשונה. עיבד ספרי לימוד אחרי המלחמה והוסיף ערכי תודעה יהודית. פרסם בעברית ובגרמנית. פעיל במזרחי, עלה לתל אביב-תרצה. חיבר \"פאר מרדכי\" תל אביב תשיא, ועוד."},{"i":39005,"n":"פרבשטין, אברהם יהודה","bt":"תרעז","dt":"תשנז","b":"תלמיד ישיבת \"תפארת ישראל\" בחיפה, חברון בירושלים, מיר-ליטא, מקורב לחזון איש. חתן הגר\"י סרנא ראש ישיבה חברון, ר\"מ וראש ישיבת חברון-תשז כ-50 שנה. מראשי מערכת האנציקלופדיה התלמודית.","bk":[["כנסת אברהם",""]]},{"i":39006,"n":"פרג, אברהם אהרן הלוי","k":"בעל תבלין למצוה","r":"דרשן בחורבת רבי יהודה החסיד","bt":"תרל","dt":"תרפא","dp":"ירושלים","b":"חתנו של ר משה נחום ולנשטיין ראבד בירושלים. היה דורש בבית כנסת החורבה, ראש כולל בתי אונגרין, וראש ישיבת המשתלמים. השתתף בעריכת הפירוש הירושלמי שהוציא אברהם משה לונץ. חיבר \"תבלין למצוה\" ירושלים תרע. ועוד ספרים בכתב יד.","bk":[["נרות אהרן - רמב\"ם",""],["תבלין למצוה - הגדה של פסח",""]]},{"i":39007,"n":"פרג, בנימין זאב מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":39008,"n":"פרג, יהודה מפיזרו","b":"שליח קהלת פיזרו לקושטא בענין החרם על אנקונא-שטז."},{"i":39009,"n":"פרג, יצחק איציק מפרג","bp":"פרג","b":"תלמיד החת\"ס. כשרצה לחזור לפרג מפרשבורג - רמז לו החת\"ס שישאר, אולם הוא נסע למשפחתו, והצטער על כך, וסיפר על כך לר שמעון סופר לאחר ארבעים שנה."},{"i":39010,"n":"פרג, יצחק מאיטליה","b":"רב בפירארה"},{"i":39011,"n":"פרג, רחמים יוסף חיים-רי\"ח טוב","f":"יצחק פרג","k":"בעל מסעי הירח","dt":"תרסג - ד אייר","dp":"ירושלים","b":"מחכמי ירושלים, מלמד ב\"דורש ציון\". פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39012,"n":"פרג-אופלטקה, יצחק","f":"מרדכי","k":"בעל פרי יצחק","bt":"תקפ","bp":"פרג","dt":"תרס - יא שבט","dp":"ירושלים","b":"תלמיד החת\"ס. עלה לירושלים-תקצח (בברכת החת\"ס). חתן ר ברוך עייאש מירושלים (נכד הראשון לציון ר יעקב משה עייאש). ממיסדי וראש ישיבת \"דורש ציון\" (שבה למדו בני הקהלה הספרדית), וממיסדי כולל אונגרין. כל תלמידי החת\"ס שעלו לירושלים - לא יצאו עוד משם. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז. (תאריך פטירתו ע\"פ ריבלין שמציין תרם! ולא תרס)."},{"i":39013,"n":"פרג-אופלטקה, רפאל מירושלים","f":"אברהם","bt":"תרמד","bp":"ירושלים","b":"רופא בירושלים, מנהל משרד הבריאות בתל אביב."},{"i":39014,"n":"פרגאן, דוד","f":"מסעוד","b":"מחכמי מרוקו"},{"i":39015,"n":"פרג'ון, אברהם מטבריה","b":"עלה לטבריה"},{"i":39016,"n":"פרג'ון, יעקב היוצר ממרוקו","k":"בעל פרח שושן","b":"תלמיד ר מימון אלבאז. מחכמי תארודאנת-נוף סוס-מרוקו, גלה עם היהודים-שע לכפר תאמגרת, נאסר בעלילה, ועבר לכפר אופראן, וכפר אקא. חיבר \"פרח שושן\" ושם גם קורותיו."},{"i":39017,"n":"פרג'ון, ציון מג'רבה","dp":"גאבס-תונס","b":"תלמיד ר מכלוף עידאן. מחכמי ג'רבא, רב בגאבס-תונס."},{"i":39018,"n":"פרג'ון, רחמים מלוב","f":"יעקב","dt":"תרסז","b":"רב בבנגאזי, ונשיא הקהלה. נזכר אצל ר משה סרוסי ב\"וישב משה\" תונס תרנז, מתורתו ב\"כמוס עמדי\" לר כמוס עג'יב."},{"i":39019,"n":"פרג'י מהמה, יעקב מאלכסנדריה","b":"סופר,אומן,פוסק,מחנך,רב באלכסנדריה,נא אמון-ת\"נ"},{"i":39020,"n":"פרג'י, אליאס ביג משלוניקי","dt":"תרפא","dp":"שלוניקי","b":"רופא צבאי בשלוניקי-תרס. פרופ' לרפואה בקושטא."},{"i":39021,"n":"פרג'י, ויטאל מתורכיה","bt":"1868","bp":"שירון","b":"עו\"ד, וחבר בפרלמנט התורכי."},{"i":39022,"n":"פרג'י, יעקב מאיטליה","k":"בעל שו\"ת מהרי\"ף","b":"מחכמי איטליה?"},{"i":39023,"n":"פרג'י, יצחק מירושלים","b":"מחכמי ירושלים, בשנת תקכב בשליחות בתונס יחד עם ר משה שפירא, וכתב שם הקדמה לספר \"תולדות יצחק\", בשליחות בתורכיה. בשנת תקכא חתם על כתב שליחות ר חיים מודעי."},{"i":39024,"n":"פרג'י, יצחק מצפת","b":"מצאצאי מהר\"י פראנג'י ממצרים. מחכמי צפת. בשליחות בצפון אפריקה-תקט, בהיותו בתונס פגש את ר עוזיאל לחייאך בעל \"משכנות הרועים\" המזכירו בספרו."},{"i":39025,"n":"פרג'י, מאיר משלוניקי","b":"מדפיס בשלוניקי-שנד אצל המדפיסים ממשפחת בת שבע."},{"i":39026,"n":"פרג'י, מנחם מלאריסה","b":"מראשי קהלת לאריסה-תמח."},{"i":39027,"n":"פרג'י, משה משלוניקי","dt":"תנט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":39028,"n":"פרג'י, עזרא","b":"נזכר בשו\"ת ר יצחק אלגזי."},{"i":39029,"n":"פרגילה, אברהם מצפת","b":"מחכמי צפת-רן. לא חתם על אגרת השמיטה של חכמי צפת-רסד אך העידו שהצטרף עמם בע\"פ כי הוא מושבע ועומד שלא לחתום משום מעשה שהיה. תלמידו ר משה בן יצחק הלוי הדיין מצפת."},{"i":39030,"n":"פרגר (פרענער), אהרן מוילנא","f":"צמח","k":"ר אהרעלע צמח'ס","dt":"תקצז - ב כסלו","b":"ראש הדיינים בוילנא. הסכים על ש\"ס וילנא, על כמה פסקים בפנקס הגר\"א. קרובו של ר אבלי מוילנא. אחיו - ר בנימין שו\"ב בוילנא."},{"i":39031,"n":"פרגר חיים יוסף אריה בן משה אליעזר","bt":"1840","dt":"ה'תרעב 1912","bk":[["כתבי ר יאשע שו''ב",""]]},{"i":39032,"n":"פרגר, אברהם סגל מפרשבורג","f":"מרדכי הלוי מפרשבורג","bt":"תקצח","bp":"פרשבורג","dt":"תרסב - כ כסלו","dp":"טאפלשטשן","b":"תלמיד הכת\"ס, ור שלמה קוועטש מניקלשבורג, ור נתן בנימין ליבר מפרשבורג. גר במאראש-לודאש, מגיד בפרשבורג-תרכט, מו\"צ בטאפלטשן(=טפלשטיין)-תרמז. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39033,"n":"פרגר, אברהם שמעון מוילנא","f":"צבי הירש","k":"ר שמעון הגדול","dt":"תקלז - ו טבת","dp":"וילנא","b":"חתן ר אליהו פעסעלעס מוילנא. תלמיד ר יונתן איבשיץ (ועמד לצדו בזמן המחלוקת). מו\"צ, מגדולי חכמי וילנא בזמן הגר\"א. והיה ראשון המו\"צים בוילנא - (לאחר התבטלות משרת האב\"ד כיהנו רק בתפקיד מו\"ץ). נקרא גם \"שמעון וילנא\" או \"שמעון רגלור\". אחיו - ר מרדכי בן ר מרדכי ר צמח'ס (כך אצל ריבלין בתוח\"י). אולי הוא שחתם ראשון על כתב רבנות ר שמואל כראב\"ד בוילנא."},{"i":39034,"n":"פרגר, איזיק מגלוגא","b":"רב בגלוגא רבתי-תע\"ז"},{"i":39035,"n":"פרגר, אליהו הירש מברוכזאל","b":"אב\"ד ברוכזאל-תר."},{"i":39036,"n":"פרגר, בנימין וולף מפרשבורג","f":"מרדכי הלוי מפרשבורג","bt":"תר","bp":"פרשבורג","dt":"תרעא - כב ניסן","dp":"ירושלים","b":"תלמיד הכת\"ס. עלה לירושלים-תרכט. חתן ר שמעון דייטש מירושלים. בניו - ר יעקב הלוי פרג מירושלים ור אברהם אהרן ראש ישיבת שומרי החומות בעל \"נרות אהרן\"."},{"i":39037,"n":"פרגר, דוד מבוטשטש","b":"ראש מדינה בגליל לבוב, חתם-תנב על תקנת קהלת זולקוא עם ר מרדכי גומפרכט מזולקוא, בעל הט\"ז (ושם מופיע התאריך-תכד), ועוד, חתם-תמח על חרם בזולקוא עם ר הלל בעל \"בית הלל\", חתם בקוליקוב-תן על תקנות הקהלה, חתם-תמו ביריד ירוסלב."},{"i":39038,"n":"פרגר, חיים יוסף אריה מבריסק","f":"משה אליעזר","k":"בעל מנחת יוסף","bp":"בריסק","dt":"תרעב - ב טבת","dp":"טבריה","b":"תלמיד האדמו\"ר מהר\"ם מקוברין, בעל יסוד העבודה, האדמו\"ר מהר\"ש מסלונים. שו\"ב בבריסק בזמן ר יוסף דב סולוביציק (שהקפיד לאכול רק משחיטתו). עלה לארץ והתישב בטבריה. חיבר גם ספר אמרות וסיפורי צדיקים בשם כתבי ר\"י שו\"ב."},{"i":39039,"n":"פרגר, יהודה ליב מפרג","f":"וולף","dt":"תפא","dp":"ונדסבק","b":"מחכמי פרג, עבר לואנדסבק. בנו - ר מאיר"},{"i":39040,"n":"פרגר, יוסף מאלטונא","f":"שמעון","k":"בעל גחלי אש","bt":"תעד","bp":"אלטונא","dt":"תקכח - יח כסלו","dp":"אלטונא","b":"מחכמי אלטונא, היה מעורב במחלוקת ר יונתן איבשיץ ור יעקב עמדין והיה מגדולי מתנגדיו של ר יונתן והוא זה שהחל בבדיקת הקמיעות ונחשד בזיוף כדי להחשיד את ר יונתן. חיבר \"אספקלריא המאירה\", \"גחלי אש\" - בענין המחלוקת."},{"i":39041,"n":"פרגר, יעקב סגל מאדא","f":"מרדכי הלוי מפרשבורג","k":"בעל שאילת יעקב","bt":"תרג או תרט","bp":"פרשבורג","dt":"תרעח - כז סיון","dp":"אדא","b":"תלמיד הכת\"ס. חתן מהרם שיק מחוסט ועבר לשם-תרכז. רב באדא ופעטראווסלע-תרלג. בזיוו\"ש חתן ר צבי טויבר. בנו ר שלמה ברוך על מקומו בפעטרווסלע, בנו גם ר צבי מפאפראד. מתורתו ב\"וילקט יוסף\", שו\"ת \"בן יהודה\"."},{"i":39042,"n":"פרגר, ישכר דב בריש מוישניצא","f":"משה מוישניצא","k":"בעל מוצל מאש","bt":"תקע","bp":"וישניצא","dt":"תרלה","b":"רב בסטרי, וישניצא, סירב לרבנות רימנוב למרות ציווי הדברי חיים שיקבלה - שלשה ימים אחר כך נשרף ביתו וספריו ואז עבר לרימנוב-תרכד. חיבר \"מוצל מאש\" למברג תרכה."},{"i":39043,"n":"פרגר, ליב הלוי מגרץ","f":"שמעון","b":"מלמד באלטונא, ראב\"ד בגרעטץ-תפ. אחיו של ר יוסף."},{"i":39044,"n":"פרגר, מאיר זונדל מוארשא","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":39045,"n":"פרגר, מאיר זונדל מזאקראטשין","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39046,"n":"פרגר, מנחם סגל מלבוב","b":"חתם-תסא בפנקס קהלת זולקוא."},{"i":39047,"n":"פרגר, מרדכי הלוי מפרשבורג","b":"מחכמי פרשבורג. בניו - יעקב אב\"ד אדא, ור אברהם מטאפלאטשן. חתנו - ר ישעיה ישכר בער וייס מפרשבורג."},{"i":39048,"n":"פרגר, משה מניקלשבורג - א","k":"בעל מעשי ה","b":"מקובל,איש מופת מגיד שיעור בניקלסבורג-תנ\"ו"},{"i":39049,"n":"פרגר, משה סגל מחוסט","f":"צבי הירש מפופראד","b":"מכתב ברכה ממנו לר יוסף צבי דושינסקי מחוסט."},{"i":39050,"n":"פרגר, צבי הירש מפאפראד","f":"יעקב - שאלת יעקב","bt":"תרלו או תרמב","bp":"אדא","dt":"תשב - כז טבת","dp":"פאפראד","b":"תלמיד השב\"ס. חתן ר יעקב שיק מנאדאודוואר ועבר לשם. רב בקראמפאך-תרסא, פאפראד(=פופראד)-תרסט וחתנו ר יוסף שמואל אדלר על מקומו אחריו. חתנו - ר ישראל נח בריסק רב בקרית אתא. מתורתו בספר אביו \"שאילת יעקב\", פרסם מאמרים ב\"וילקט יוסף\". בניו - ר משה, ר אשר אנשל מואשארהאלי, ר דוד מסאלאש."},{"i":39051,"n":"פרגר, שלמה ברוך מפעטרווסלא","f":"יעקב פרגר","bt":"תרמח","dt":"תשד","b":"רב בפעטרווסלע-תרע\"ג"},{"i":39052,"n":"פרגרינו, אברהם מספרד ואיטליה","b":"מאנוסי ספרד, חזר ליהדות באיטליה-שנות ה-ש'. חיבר ספר בספרדית ותורגם לעברית בשם \"צריח בית אל\" - בידי ר מרדכי לוצאטו."},{"i":39053,"n":"פרדו","k":"ראה: פארדו","b":"רב בסרייבו, עלה לארץ ישראל ונפטר בדרכו. חיבר \"פירות גינוסר\", \"תועפות ראם\". תלמידו - ר דוד פינטו - כתב על רבו בספרו \"מזמור לדוד\"."},{"i":39054,"n":"פרדזשמייסקי, צבי מזאגר","bt":"תרמא","dt":"תרפב - כא שבט","b":"רב בזאגר ישן, רב בליזובה(=לייז'ובה)."},{"i":39055,"n":"פרדמסקי, אליעזר מרימשאן וארה\"ב","f":"יעקב","bt":"תרם","dt":"תשכט - טו כסלו","b":"תלמיד ישיבת טלז, ראדין, מיר, כולל קובנא. נסמך מאת: ר יחיאל מיכל אפשטין, ר זלמן סנדר שפירא ממאלץ וקריניק, ר אליהו ברוך קאמאי ממיר. רב ברימשאן-פלך קובנא-תרסז, קרמנצוג, ראש אגודת הרבנים בליטא-תרעח, בשליחות אגודת ישראל בארה\"ב-תרפג, רב בניו יורק, וסגן יו\"ר אגו דת הרבנים, חבר בתנועת המזרחי. בנו - הרב ד\"ר עקיבא פרמסקי, חתנו - ר ישראל שלמה רוזנברג מהרטפורד, עו\"ד ר יעקב הכט."},{"i":39056,"n":"פרדס, אליהו מירושלים","f":"בן ציון","bt":"תרנו","bp":"ירושלים","b":"מחנך בירושלים, מנהל ביה\"ס לבנות \"מזרחי\"."},{"i":39057,"n":"פרדס, אליהו פנחס","bt":"תרנג-יז תמוז","bp":"ירושלים","dt":"תשכח-לב-יא ניסן","dp":"ירושלים","b":"מרביץ תורה בירושלים, רב ראשי ברמת גן-תשי\"ג, רב ראשי בירושלים-תשכ\"א"},{"i":39058,"n":"פרדס, בן ציון נסים מירושלים","bt":"תרכב","bp":"ירושלים","dt":"ל' שבט תשג","b":"מחכמי \"בית אל\" בירושלים, דרשן. בשליחות במרוקו.","bk":[["פרדס התורה",""]]},{"i":39059,"n":"פרדס, דוד מסטאשוב","f":"מרדכי מסטאשוב","k":"אדמור מסטאשוב וסוסנו","bt":"תרב","dt":"תרפא - ח אייר","b":"אדמור בסטאשוב וסוסנוביץ. בנייו ר יוסף מנשה ור שמואל אליהו."},{"i":39060,"n":"פרדס, חיים ליב מקולבסוב","b":"מחכמי קולבסוב-תרכח."},{"i":39061,"n":"פרדס, ישראל יעקב מסטאשוב סוסנו","f":"דוד מסטאשוב","k":"אדמור מסטשוב בסוסנוב","dt":"תש..","b":"חסיד ר חיים שמואל מחנטשין (לובלין). אדמור מסטאשוב בסוסנוביץ על מקום אביו. כונה כ\"רבי יענקלה מסטאשוב\". נספה בשואה."},{"i":39062,"n":"פרדס, מרדכי מסאטשוב","f":"שמואל אהרן מסטאשוב","k":"אדמור מסטאשוב","b":"אדמור בסטאשוב."},{"i":39063,"n":"פרדס, שלמה נתן מסטאשוב","f":"מרדכי מסטאשוב","dt":"תרצח","b":"סירב לאדמורות והתפרנס מכתיבת סת\"ם, והיה נערץ על חסידים רבים."},{"i":39064,"n":"פרדס, שמואל אהרן מטשקובה","f":"שלמה נתן הלוי","k":"בעל אבני שמואל","bt":"תרמז-נב","bp":"סטשוב","dt":"תשיז","b":"נסמך מאת: ר יואב יהושע מקינצק, ר מאיר יחיאל האדמור מאוסטרובצא. רב בזאריק-פלך פיעטרקוב, ר\"מ בישיבת \"מגדל עוז\" בזווירציה-פלך פיעטרקוב, ר\"מ בבנדין. רב בטשקובה(=שטשאקאווא)-גליציה. היגר לארה\"ב-תרפד. רב בניו יורק, ושיקגו. עורך \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, ור שמחה עלברג עורך על מקומו אחריו. חיבר \"אבני שמואל\" לודז תרעז. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"המגיד\" - סטמר תרפח-תרצט."},{"i":39065,"n":"פרדס, שמואל אהרן מסטאשוב","f":"מרדכי מסטאבניץ","b":"רב וראש ישיבה בסטאשוב, סירב לאדמורות, ונחשב לאחד מצדיקי הדור."},{"i":39066,"n":"פרדקין שניאור זלמן בן שלמה","bt":"1830","dt":"ה'תרסב 1902","bk":[["דרשת תורת חסד",""],["תורת חסד",""]]},{"i":39067,"n":"פרדקין, ישראל שמעון מקאמיען","f":"שניאור זלמן יוסף מדר","bt":"תריז","b":"תלמיד כולל קובנא. רב בקאמין(=קאמיען)-פלך ויטבסק-תרן. נסמך מאת: ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא, ר יצחק בלזר מפטרבורג."},{"i":39068,"n":"פרדקין, שניאור זלמן יוסף מדריב","f":"בנימין חיים מלאדי","dt":"תרמג","b":"מגדולי חסידי חב\"ד,רב בדריבין"},{"i":39069,"n":"פרדקין-לאדיאר, שניאור זלמן","k":"בעל תורת חסד","r":"נדפס ביחד עם הספר עבודת ישראל","bt":"תקץ","bp":"ליאדי","dt":"תרסב - ה ניסן","dp":"ירושלים","b":"מגדולי תלמידי הצמח צדק מליובאויטש, ובנו ר שמואל ור שלמה זלמן מקפוסט. רב בפלאצק, דוינסק, לובלין-תרכח על מקום ר יהושע השל אשכנזי, עלה לירושלים-תרנב וכיהן כרב החסידים שם, עבר לחברון-תרנט לבקשת האדמור הרש\"ב וחזר לירושלים. מתולדותיו ב\"תורת חסד מלובלין\". תשובה ממנו לאדמור מסוכטשוב בעל \"אבני נזר\" ב\"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז.","bk":[["תורת חסד","שו\"ת - אחרונים"],["תורת חסד – שו\"ת",""]]},{"i":39070,"n":"פרובנצאל, יוסף מאלגיר","f":"ברכיה","bt":"קפ","dt":"רן - בערך","b":"מחכמי הוניין-אלגיר ועסק במסחר. שאלה ממנו לרשב\"ש, ור צמח בנו."},{"i":39071,"n":"פרובנצאל, יעקב מקושטא","b":"דיין מחכמי קושטא-שנות ה-ת'-תק'. נזכר ב\"כהונת עולם\"."},{"i":39072,"n":"פרובנצאל, ישועה הלוי מהוניין","f":"יוסף","bt":"ר","dt":"רע","b":"רב בהוניין, בזמן חברו ר צמח דוראן שאתו התכתב. לדעת ר יצחק רוש - הוא זהה לר ישועה בעל \"הליכות עולם\"."},{"i":39073,"n":"פרובנצאלי, אברהם ממנטובה","f":"דוד בן אברהם","dt":"שמ-שעב - אחרי","b":"מקובל, רופא, חוקר, רב במנטובה-שסח, רב בקזאלי-שעב. רבו של בעל \"שער אריה\" (=אברהם פלטירנו) והיה עם תלמידו בכנס רופאים בפואה (ואולי הכוונה לזקנו?). חתם על אגרת אביו לרצה להקים בביתו בית מדרש ללימודי כל החכמות. חיבר שיר שנדפס בראש \"ראשית חכמה\", וב\"מאור עינים\" לר עזריה. בניו: ר דוד, ר משה, ר יהודה, ר בנציון."},{"i":39074,"n":"פרובנצאלי, דוד ממנטובה","f":"אברהם פרובינציאלי","k":"בעל עיר דוד","b":"רב במנטובה-שלח. אחיהם של ר יהודה ור משה פרובנציאלי. חיבר \"עיר דוד\", \"מגדל דוד\". (חיבר השגות לספר \"עש\"ב\" שחיבר אחד מן האדומים)."},{"i":39075,"n":"פרובנצאלי, חזקיה מנוח מאנקונה","f":"ישראל","b":"רב באנקונה בזמן ר מנחם שולחני ור יהושע פירמי וחתם עמם ב\"עפר יעקב\" אודות ס\"ת."},{"i":39076,"n":"פרובנצאלי, יהודה ממנטובה","f":"דוד או אברהם","k":"בעל נפוצות יהודה","b":"רב במנטובה-שכ. אחיהם של ר דוד ור משה ממנטובה. חיבר \"נפוצות יהודה\" בכת\"י. תשובה ממנו ב\"מאור עינים\". מתלמידיו - ר אברהם משער אריה."},{"i":39077,"n":"פרובנצאלי, יהודה נתן","k":"בעל פירוש לרות ואסתר","b":"חיבר פירוש על רות ואסתר."},{"i":39078,"n":"פרובנצאלי, יעקב מנפולי","f":"דוד","k":"בעל דברי חכמים","bt":"רנ","bp":"נפולי","b":"דיין בנפולי-רמ אצל ר יעקב לנדא בעל האגור, והסכים על ספר האגור. חיבר \"דברי חכמים\" מיץ תרנו."},{"i":39079,"n":"פרובנצאלי, מנוח","b":"מרביץ תורה בלוקה-ת\"נ"},{"i":39080,"n":"פרובנצאלי, משה ממנטובה","f":"אברהם","k":"רמ\"ף - בעל בשם קדמון","dt":"שלו - ג תשרי","b":"רב במנטובה בזמן הרמ\"ע - שהשיג עליו בענין תפלין בחול המועד במלים חריפות בגלל הזלזול בספר הזהר. חיבר השגות ל\"מאור עינים\" ונדפסו בסוף הספר. חיבר שו\"ת וחיבור על הרמב\"ם - מקצתם נדפסו בונציה. חיבר \"בשם קדמון\" עם פירוש מנכדו ר אליעזר פרובנצאלו. תשובה ממנו בשו\"ת הרמ\"א-שיא."},{"i":39081,"n":"פרובנצלו משה בן אברהם","bt":"1503","dt":"ה'שלה 1575","bk":[["ביאור זה יצא ראשונה",""]]},{"i":39082,"n":"פרוגרמנסקי, יוסף מפושאלט","dt":"תש","b":"רבה האחרון של שידלובה, רבה האחרון של פושאלט. נספה בשואה."},{"i":39083,"n":"פרווזניק, מנחם מנדל פנחס","f":"נחמיה","k":"בעל תשובות מנחם","bt":"תרלד","b":"נכד ר שמעון סיינאוביץ. חתן הגביר ר אהרן בן ציון מאגליניצקי מוידוקלא-פלך קובנא. תלמיד ר חנוך הניך גינצבורג מהאידוצישוק, ר בערע ליב מהאידוצישוק-פלך וילנא, ר יחזקאל הכהן מוריז, ישיבת ר יעקב קופל מרגליות בדוינסק - והיה מקורב לרבנים ר מאיר שמחה הכהן והרוגצובר, כולל קובנא והיה ממקורבי ר יצחק אלחנן ור משה דנישבסקי. רב באיגנלינה(=איגנאלינא)-פלך וילנא-תרסג, רסיצה(=ראסיצא,רעסיצא)-פלך ויטבסק-תרסה. מתורתו ב\"תורה מציון\" - ירושלים תרנה-תרסה - והסכימו עמו ר יוסף רוזין - הרוגצובר ועוד. נסמך מאת: ר יעקב זאב כהנא מגאוורא בעל \"שארית יעקב\", ר אלכסנדר משה לפידות מראסיין, ר משה לוי מנעמקאסט בעל \"דברי משה\", ר יוסף ראוונסון. חיבר גם \"אבל משה\" - הספד על ר אלכסנד משה לפידות. פרסם מאמרים ב\"תו\"מ\" לר שמואל צוקרמן, \"המאסף\" - ירושלים."},{"i":39084,"n":"פרוזינר-דויגר, אליעזר מוילקובי","f":"חנוך הניך מקלווריה","dt":"תרטז","dp":"דויג","b":"נכד ר יהודה מוילנא - היסו\"ד. תלמיד בקלויז הגר\"א בוילנא. חתן ר מרדכית מרגליות - אשתו איטא היתה מפורסמת כלמדנית. רב בוילקוביטש(=וילקוביסק). בניו - ר חנוך הניך מויליאמפול, ר אברהם אפרתי, חתנו - ר שמואל איסר הכהן מוילנא. אחיינו-בן אחותו - ר יהודה בכרך בעל נימוקי הגרי\"ב."},{"i":39085,"n":"פרוזניץ, ליב מפפד\"מ","b":"שבתאי והוגלה מפפד\"מ-תפ בערך. מכתב ממנו אל ישעיה משיח - בענין נסיון השבתאים למנות אחד מאנשיהם לרבה של מיינץ."},{"i":39086,"n":"פרוזנסקי לינובסקי, ניקולאי","f":"אוסיפ","bt":"1846","bp":"פפפרוז'אן-פלך גרודנא","b":"פרסם ב\"המליץ\". היגר לארה\"ב וכתב בעתונות היהודית. פרסם באודסה חוברות ברוסית בשם \"המיטיבים אנו לעשות בהכותנו את היהודים\", ו\"האשם היהודי בזה שהוא יהודי\", \"חלומו של קרושגן\". הו\"ל קבצי סיפורים."},{"i":39087,"n":"פרוזנר, אברהם מלונשטיץ","f":"יהודה ליב","b":"אב\"ד לונטשיץ. הסכים על \"ויכתב משה\" פפד\"א תנד."},{"i":39088,"n":"פרוזנר, יעקב מזולקוא","f":"יהודה ליב","b":"מחכמי זולקוא, חתם-תיט על תקנת הקהלה."},{"i":39089,"n":"פרוזנר, משה","f":"שלמה זלמן","bt":"1840","bp":"קיידאן","dt":"1895","b":"תלמיד ישיבת קידאן, תלמיד דודו ר אברהם עבר יפה. פנה להשכלה ועבר לפוניבז ולוילנא ולמד בביהמ\"ד לרבנים. חזר לפוניבז ופגש את יל\"ג, הגיע לקובנא-1863 ופגש את מאפו. פרסם מאמרים ב\"המליץ\", סייע ללילינבלום, לי. ליפקין, ולהרמן שפירא. מורה לעברית בבי\"ס של ברמן בפטרבורג. מורה לבניו של הברון גינצבורג ובבית היתומים שלו."},{"i":39090,"n":"פרוח ן, שלמה מברשך","f":"יהודה","bt":"קי - בערך","dt":"קסה - בערך","b":"דיין בברשך-אלגיר. נזכר בשות הריב\"ש."},{"i":39091,"n":"פרוחובניק, אברהם יהושע","f":"בנימין יצחק","bt":"תרטז","b":"רב בסקירילוב(=סקריהאלאוו)-פלך מינסק-תרסח."},{"i":39092,"n":"פרוידשטט, משה מאור קטן רופא","f":"יהודה","b":"רופא מחכמי פפד\"מ. חתם על תקנות הקהל-של."},{"i":39093,"n":"פרוכטהנדלר, איסר מקראקא","f":"שלמה","k":"בעל תורת ישראל","bt":"תרנב","bp":"קראקא","dt":"תשטז","b":"חסיד שיניבה ובלוזוב. חתן הגביר ר פנחס הזנפלד מדובצק. רב ברעדים-תרפד, ציריך-תרפח. חיבר \"תורת ישראל\" ירושלים תשנז."},{"i":39094,"n":"פרוכטהנדלר, ישראל איסר","f":"צבי","k":"בעל תפארת ישראל","dt":"תרץ","b":"תלמיד השואל ומשיב והדברי חיים. רב בזאבווע, גדוב-תרלב, דינוב-תרלח, דובשיץ-תרמח, בוקובסק-תרנב. חתן ר מרדכי יעקובר. חיבר \"תפארת ישראל\" - ירושלים תשנז."},{"i":39095,"n":"פרוכטר, חיים מאויבר-וישיווה","f":"יהודה אריה","k":"בעל ראשית אוני-תרם","b":"נכד ר שמואל פרוכטר מגדולי חסידי ר חיים מקאסוב. גביר מחכמי אויבר-וישווה. גיסו של ר נפתלי שוורץ בעל \"בית נפתלי. ?? לא באוצר ??"},{"i":39096,"n":"פרוכטר, שלמה מסוטשעל ונ\"י","f":"שמואל מסוטשעל","k":"בעל דברי שלמה-תרפז","bp":"סוטשעל","dt":"תשכה - כד אייר","dp":"ירושלים","b":"מצאצאי ר שלמה פרוכטר אחיינו של האדמור שמואל הורביץ מניקלשבורג שהיה מראשוני היהודים באויבר-וישיווה. תלמיד בעל \"קדושת יום טוב\", השב\"ס, ור אליעזר דייטש. חתן ר דוד דוידוביץ ממיטל-אפשא, ובזיוו\"ש חתן ר פרץ פאטיפא מסלאטפינא. מחכמי כפר סיטשל-עד תרפו. היגר לארה\"ב-תרפב, עלה לירושלים. חיבר גם \"אגרת שלמה\" ירושלים תשך. ובה ספר היוחסין של האחים - ר שלמה פרוכטר, ר מרדכי שטרן ור אברהם אדלר - נכדיו של ר צבי הירש הורביץ מצ'ורטקוב אביו של בעל ההפלאה."},{"i":39097,"n":"פרוכניק, יוסף מלנצהוט","f":"שמואל","b":"תלמיד הישמח משה. רב בלנצהוט-תקנד."},{"i":39098,"n":"פרום, זליגמן","b":"רב פעלים,רב באר הומברג-תר\"פ,בבית הטפסר רוטשילד בפפד\"מ"},{"i":39099,"n":"פרומן, יעקב יהושע מלודז","k":"בעל נחלת יעקב יהושע","b":"גביר מחכמי לודז. מצאצאי האדמור ר אפרים פישל מסטריקוב. חברם של בעל \"ראשית בכורים\" והגאון מקוזיגלוב. נספה בשואה. רוב חדושיו אבדו ומהשרידים נדפס \"נחלת יעקב יהושע\" על התורה - תל אביב תשיט."},{"i":39100,"n":"פרומן, יצחק זאב מליטעטוב","dt":"תרסה - בערך","b":"רב בליטעטוב-תרנ ובנו ר שלמה על מקומו אחריו-תרסה."},{"i":39101,"n":"פרומן, שלמה מליטעטוב","f":"יצחק זאב","bt":"תרכד","b":"מו\"צ בליטעטוב-פלך קאליש-תרמה, ורב-תרסה על מקום אביו."},{"i":39102,"n":"פרומנזון, אברהם חיים מארה\"ב","b":"מצאצאי המנגן \"דער וילנער בעלי-בית'יל\". סופר אנגלי וציוני, פרסם מאמרים ב\"די אידישע טאגעבלאט\" בניו יורק."},{"i":39103,"n":"פרומקין ישראל דב בן אלכסנדר סנדר","bt":"1850","dt":"ה'תרעד 1914","bk":[["ספורים מעתקים משפת אשכנז",""]]},{"i":39104,"n":"פרומקין, אברהם מארה\"ב","f":"ישראל דב","bp":"ירושלים","b":"היגר לניו יורק, עוזרו של ר צבי הירש מסליאנסקי-תרסב בעתון \"דיא אידישע וועלט\"."},{"i":39105,"n":"פרומקין, אריה ליב מליטא וירוש","f":"שמואל קלמר","k":"בעל תולדות חכמי י-ם","bt":"תרה","bp":"קובנא או קלם","dt":"תרעו - ח סיון","dp":"פתח תקוה","b":"למד בישיבת סלובודקה, חתן ר אהרן הדס מפיקלין-פלך קובנא. עלה לירושלים-תרכח, בעקבות אביו. עסק במחקר, חיבר \"תולדות חכמי ירושלים\", ומסע אבן שמואל\", חזר לרוסיה והדפיס את ספרו בוילנא, הקים ישיבה בפיקלין יחד עם ר זאב מזעדיק, בשנת תרלו היה רב בעיר אלקסוט ותרם הרבה לישוב היהודי. בשליחות ר יצחק אלחנן מקובנא-תרמא בגרמניה על מנת לעזור לחובבי ציון - ונפגש עם וילהלם קרל רוטשילד - שהבטיח את עזרתו. בשנת תרמג חזר לירושלים, רכש שטח בפתח תקוה עבור הגביר ליהמן מגרמניה. ואחר כך השתקע בפתח תקוה. עבר ללונדון והשלים שם את ספרו על חכמי ירושלים. חזר לארץ-תרעא. חיבר ספרים ומחקרים, ובהם \"תולדות אליהו\", ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" מתוך כת\"י דודו - ר אליהו קלישר, \"תורה מציון\" - ירושלים תרנה-תרסה. לתולדותיו בספרו \"תולדות חכמי ירושלים\". חתניו - ר חיים צבי צייטלין מירושלים ולונדון, בנימין יהלום מפתח תקוה, ר משה צבי סגל מירושלים. בניו - שמואל, אליהו אפרים.","bk":[["תולדות חכמי ירושלים",""]]},{"i":39106,"n":"פרומקין, יהודה מנחם","f":"אליעזר"},{"i":39107,"n":"פרומקין, יואל","b":"חתן הגביר ר שאול ליפשיץ. חתנו - ר מאיר פרידלנד מרגנבורג."},{"i":39108,"n":"פרומקין, יעקב מהורדנא","f":"משה מרדכי","dt":"תרלב - כב אב","dp":"הורדנא","b":"גביר מחכמי הורדנא."},{"i":39109,"n":"פרומקין, ישראל דב מירושלים","f":"אלכסנדר","k":"עורך החבצלת","bt":"תרי","bp":"דוברובנא","dt":"תרעד - יד אייר","dp":"ירושלים","b":"עלה לירושלים-תרך עם אביו. חתן ר ישראל בק, יסד מחדש את העתון \"החבצלת\" של חותנו. סופר מחכמי ירושלים, עסקן צבור, פעל במוסדות שונים וסייע בהתישבות התימנים בכפר סילואן בירושלים. מבניו - גד-שופט בירושלים."},{"i":39110,"n":"פרומקין, ישראל צבי","f":"יעקב","bt":"1832","bp":"גרודנא","dt":"1894","dp":"בפרנצסבד","b":"גביר בקובנא. מיסד חברת \"סומך נופלים\", מנהל בנק הסוחרים. השתתף באסיפות בפטרבורג כנציג קובנא. קיבל תואר מהשלטון \"אזרח נכבד לדורותיו\". בניו: ד\"ר שמחה - רופא בפטרבורג, יעקב שעבר לברלין ועסק בעניני ציבור."},{"i":39111,"n":"פרומר, אברהם דוד מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":39112,"n":"פרומר, דב בריש מאושפיצין","f":"משה מקשנוב","k":"אדמור מאושפיצין","bt":"תקם","bp":"קשנוב","dt":"תקצח - כ כסלו","b":"תלמיד החוזה מלובלין, ור שלמה בוכנר מקשנוב. רב ואדמור באושפיצין-תקפח לאחר פטירת רבו. ידיד של ר עקיבא איגר. תלמידו ר יעקב שרף מזאטור בעל \"דרכי יושר\" על מקומו אחריו באושפיצין. לתולדותם מאת ר מנחם מנדלי סופר - \"שלשה עדרי צאן\". חיבר \"דברי צדיקים\" זולקוא תקפו. (באוצר הרבנים חודש פטירתו - סיון)","bk":[["דברי צדיקים",""]]},{"i":39113,"n":"פרומר, יעקב אבן מארה\"ב","b":"רב בניו הייבן-ארה\"ב. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":39114,"n":"פרומר, ישראל אלימלך","f":"גולדברג, ישראל חיים","k":"אדמור מלודז","dt":"תש..","b":"אחיו של ר ישראל חיים גולדברג מסטאצק. חתן ר בצלאל יאיר מאלכסנדר-לודז. אדמור בלודז-תרצב. נספה בשואה."},{"i":39115,"n":"פרומר, ליב","dt":"תשג","b":"רב בסוסנובצה"},{"i":39116,"n":"פרומר, צבי אריה מקוזיגלוב","f":"חנוך הנדל","k":"בעל ארץ צבי","r":"שיעורי רא\"צ פרומר שנמסרו ביח\"ל, הו\"ל בקובץ מקבצאל.","bt":"תרמד","bp":"טשילאדז (ליד בנדין)","dt":"תשג","dp":"גיטו וארשא","b":"מייסד המשנה היומית. גדל אצל דודו ר יהודה אריה זילברברג. למד אצל האבני נזר בסוכטשוב. חתן דודו ר יהודה שרגא שוייצר ממילוביץ. רב בטשילאדז על מקום ר שלמה שטנצל. ראש ישיבה בסוכטשוב. רב בקוזיגלוב על מקום דודו ר יצחק גוטנשטין. רב בזווירציה, סוסנוביץ - תלמידיו הוציאו שם את \"אהל ישרים\". ראש ישיבת חכמי לובלין-תרצד. ביקר בארץ עם רבו ר דוד מסו כטשוב-תרצה. יזם את לימוד המשנה היומית. נספה בשואה. חיבר שו\"ת \"ארץ צבי\" לובלין תרצט ועוד. הו\"ל \"מקבצאל\" - לובלין תרצז. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"דגל התורה\" - וארשא תרפב, \"כתר תורה\" סוסנוביץ-פיעטרקוב תרץ, \"תלפיות\" - טרנוב תרצח, ב\"עמק הלכה\" - וארשא תרפו, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז.","bk":[["ארץ צבי","שו\"ת - אחרונים"],["שיח השדה","מערכות"],["שיח השדה (הרב מקוז'יגלוב)",""]]},{"i":39117,"n":"פרונסולי, אליהו חיים מליוורנו","b":"רב בליוורנו. אחיו של ר המשורר ר יצחק חיים."},{"i":39118,"n":"פרוסולוני, יצחק חיים מסיינה","bp":"סיינה","dt":"תקנד - כג סיון","dp":"ליוורנו","b":"רב בסיינה, ליוורנו ומלמד בישיבת ר אליעזר מריקנטי ויועץ כלכלי בבית מסחר. ידידו של החיד\"א. (כמובא ב\"קול עוגב\" - לר\"א פיפרנו). משיריו ב\"קול עוגב\". חתם בהסכמת \"פת לחם\" לר אלישע חביליו עם חכמי ליוורנו."},{"i":39119,"n":"פרוסט, ישראל מאיטליה","b":"אחיו או אחיינו של ר נחום משאדיק. בנו - ר אברהם קורפורר מירושלים."},{"i":39120,"n":"פרוסט, עוזר יהושע מלמברג","b":"שולט בשפות ובעל תואר דוקטור. רב באנדריחוב-תרס, ברודי."},{"i":39121,"n":"פרוסט-קורפורר, אברהם מירושלים","f":"ישראל","bt":"תרב","bp":"וארשא","dt":"תרנו - כח כסלו","dp":"ירושלים","b":"בן אחיהם של ר נחום משאדיק ורי\"ל לעווי. חתן ר משה ריבלין משקלוב. עלה לירושלים עם דודיו (בדרכו למד רוחקות בקורפו ונקרא שמו קורפורר). תלמיד הגאון מקוטנא בעל זית רענן. רב ור\"מ בירושלים. מייסדי שכונות \"מאה שערים\" ו\"בית דוד\"."},{"i":39122,"n":"פרוסטיץ, אברהם מבסקביץ","k":"בעל כפות המנעול","b":"תלמיד ר יונתן איבשיץ. אב\"ד נאוע, אויסע, בסקביץ."},{"i":39123,"n":"פרוסטיץ, אהרן שבתאי מרכניץ","f":"יצחק מרכניץ","k":"בעל שו\"ת","dt":"תקז - א כסלו","b":"רב ברכניץ-תץ על מקום ר אברהם אפשטין שכיהן על מקום אביו של ר אהרן - ר יצחק. חיבר שו\"ת - תפז. נזכר בשו\"ת מהר\"ם בשם ר אהרן מזריטש."},{"i":39124,"n":"פרוסטיץ, בנימין זאב וולף מלוגש","f":"דניאל מלוגאש ופרשבור","k":"שטינשנידר","dt":"תקצט או תרה","b":"תלמיד החת\"ס. חתן ר אליקים געץ שווערין מבאיא-הונגריה (לפי החת\"ס ותלמידיו - ר אליקים גץ בודנצקי מקארמענד וכיהן שם כרב-תקפא). רב בגיסינג, לוגאש-תקף. נפטר בחיי אביו. נזכר אצל החת\"ס, תשובה ממנו ב\"אמרי אש\"."},{"i":39125,"n":"פרוסטיץ, דניאל מפרשבורג","f":"בנימין זאב","k":"בעל מחנה דן-תרסז","bt":"תקיט-כט","bp":"טיביטשאו-ליד פרוסניץ","dt":"תרו - ו אדר","dp":"פרשבורג","b":"תלמיד ישיבת ר מאיר ברבי בפרשבורג. חתן הגביר ר איצק מלוגאש, וישב שם וכיהן בפועל כרב המקום, דיין בפרשבורג אצל ר משולם איגרא ואח\"כ אצל החת\"ס. יסד בפרשבורג \"מחזיקי תורה\", כשחת\"ס הגיע לפרשבורג הפכו לאיש סודו ואמונו ולמדו ביחד קבלה. ראב\"ד בבית דינו של החת\"ס-תקצז, על מקום ר מרדכי טאסק - וקיבל קמיע מהחת\"ס לאחר שהפציר בו. מאמרים ממנו ב\"מגד ירחים\" - סיגט תרנח. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא. בנו - ר בנימין וולף מיערגין, ר איסר, היו לו 6 חתנים ומהם ר משה ברגר קוטנדורף."},{"i":39126,"n":"פרוסטיץ, יצחק","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":39127,"n":"פרוסטיץ, יצחק מרכניץ","f":"אברהם","dt":"תס - א סיון","b":"רב ברכניץ (הראשון שנודע משם). נודע כפועל ישועות. בנו ר אהרן שבתאי על מקומו אחריו - וביניהם ר אברהם אפשטין. (אולי היה גם רב בגאיא)."},{"i":39128,"n":"פרוסטיץ, ישראל איסר שטינשנידר","f":"דניאל מפרשבורג","k":"בעל מקוה ישראל","bt":"תקעט","bp":"פרשבורג","dt":"תרלז - ל אב","dp":"פרשבורג","b":"תלמיד החת\"ס (שאף מל אותו בלידתו). מקובל. חתן ר מנחם מנדל שעהן(=שיין, שאהן) מרעטה בעל \"מנחת פתים\". רב ומגיד בפרשבורג, בנו ר דניאל על מקומו אחריו."},{"i":39129,"n":"פרוסטיץ, מנחם כץ מצעהלים","f":"אליעזר הכהן וואנפריד","r":"אב\"ד צעהלים","bt":"תקנב-ה","bp":"פרוסטיץ","dt":"תרנא - טז אד\"א","dp":"צעהלים","b":"תלמיד החת\"ס. חתן ר ישכר בר פרנק סגל מפרשבורג בעל \"מחנה ישראל\" ועבר לשם. רב בפרוסטיץ, רוגנסדורף(=רגנדורף)-תקצד, צעהלים-תר כ-50 שנה וראש ישיבה וחתנו - ר דוד פרידמן על מקומו אחריו. מתלמידיו ר אהרן חיים שיק, ר משה גרינוולד בעל \"ערוגת הבושם\". מתורתו ב\"תולדות וחדושי ר מנחם כץ פרוסטיץ\" בני ברק תקן. החת\"ס מביא מחדושיו בספריו. מהיחידים שלמדו מחת\"ס קבלה. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד.","bk":[["תולדות וחי' ר' מנחם כ\"ץ פרוסטיץ",""]]},{"i":39130,"n":"פרוסטיץ, משה כץ מנייטרא","f":"מנחם כץ","bt":"תרב","bp":"צעהלים","dt":"תרפז - יב טבת","dp":"נייטרא","b":"תלמיד הכת\"ס, ר שמעון סופר מקראקא. חתן ר אברהם אהרן פשרהופר מפרוינקירכן. רב בצעהלים לצד אביו-תרכה, קהל \"עדת ישראל\" בוינה, מגנדורף(=מוגנדורף)-תרמב, טאקייא(=טוקאי)-תרנא, נייטרא-תרנה ובנו ר אברהם אהרן כץ (מכונה כץ ולא פרוסטיץ) רב לצדו ועל מקומו אחריו. גיסו - ר דוד פרידמן מצעהלם."},{"i":39131,"n":"פרוסטיץ, משה מרכניץ","f":"יצחק פרוסטיץ","b":"דיין ברכניץ-תק\"מ"},{"i":39132,"n":"פרוסטיץ, שבתי מרכניץ","dt":"תקטז - כח כסלו","b":"רב ברכניץ"},{"i":39133,"n":"פרוסקין, פסח מקוברין","k":"בעל חדושי סוגיות","bt":"תרלט","dt":"תש - יא תמוז","b":"תלמיד ישיבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). מגדולי מרביצי תורה בשקלוב, אמציסלב, רב בקוברין-תרפד. פרסם מאמרים ב\"אהל תורה\" - ברנוביץ תרפד.","bk":[["שעורי ר' פסח מקוברין","שיעורים"]]},{"i":39134,"n":"פרופיטה, אברהם משלוניקי","b":"מחכמי שלוניקי-שך."},{"i":39135,"n":"פרופייט, דון ווידאל","b":"משורר, פייטן, מחכמי ברצלונה-נ', אולי הוא רבינו פנחס הלוי"},{"i":39136,"n":"פרופס, אליעזר הכהן מאמשטרדם","f":"משה","dt":"תנח - ב אב","dp":"לבוב","b":"רב ור\"מ באמשטרדם, לבוב. ובספר כלילת יופי ובעקבותיו בובר כותב כי הרב הזה בטעות נרשם."},{"i":39137,"n":"פרופס, יוסף יהודה הכהן מהיישין","f":"זאב","bt":"תרכד","b":"רב בהיישין-פלך מוהילוב-תרנג."},{"i":39138,"n":"פרופס, שלמה מאמשטרדם","b":"מדפיס באמשטרדם."},{"i":39139,"n":"פרוק, יהודה מוינה","b":"מגדולי חכמי ווינה-ת\"פ"},{"i":39140,"n":"פרוש, אברהם יצחק מירושלים","f":"צבי הירש","b":"ראש משפחת טרכטנברג בירושלים. סופר ונאמן הכולל בירושלים, בשליחות-תרכג ביה\"ח \"בקור חולים\" ברוסיה. נזכר ב\"זכרון לחובבים הראשונים\" ד."},{"i":39141,"n":"פרוש, יחזקאל מוערזאן וירושלים","f":"שמואל","dt":"תרטז - א תמוז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":39142,"n":"פרוש, מנחם מנדל","dt":"תקפז - ל שבט","b":"מקובל,מגדולי חכמי שקלוב"},{"i":39143,"n":"פרוש, מנחם מנדל מירושלים","k":"בעל בתוך החומות","b":"תלמיד ישיבת עץ חיים בירושלים. נתמנה לשוחט ע\"י ר אריה ליב רשקס משניפישוק יחד עם ר אליהו ראם. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":39144,"n":"פרוש, נפתלי הירש ממיר וירושלים","dt":"תרכו - יט חשון","b":"מחכמי בוברויסק, פרוש מחכמי מיר (התבודד כ-14 שנה), עלה לירושלים. מחכמי ירושלים. בניו - ר שלמה זלמן, ר גרשון. אבי משפחת פרוש בירושלים."},{"i":39145,"n":"פרוש, נפתלי צבי מירושלים","b":"מראשי קהלת הפרושים בירושלים, חתם-תרסט על תקנות חברת \"שערי חסד\" בירושלים."},{"i":39146,"n":"פרוש, עקיבא מירושלים","k":"בעל קול השופר","b":"ממקורבי ר יצחק ירוחם דיסקין בירושלים-תרפב. הו\"ל \"קול השופר\" בעילום שמו, ובו מכתבים כנגד הרב קוק."},{"i":39147,"n":"פרוש, צבי הירש מירושלים","f":"יוסף","b":"מחכמי צפת וירושלים, עלה עם ר חיים הכהן רפפורט מפינסק בשנת תקפו, בשנת תקץ בשליחות קהל פרושים בהונגריה. מסר אגרת מר ישראל משקלוב ל\"חתם סופר\", ובשובו באו עמו כמה מתלמידיו של ה\"חתם סופר\". בשנת תקצז בשליחות עם ר נתן נטע בן סעדיה לסיוע בבנית ה\"חורבה\"."},{"i":39148,"n":"פרוש, שלמה זלמן מירושלים","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"ועד חכמים\" - ירושלים תרפג. ראה גם ר שלמה זלמן בהרן."},{"i":39149,"n":"פרוש-גליקמן, אליהו נחום מירושל","b":"פרסם מאמרים ב\"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":39150,"n":"פרוש-גליקמן, משה מירושלים","b":"פרסם מאמרים ב\"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":39151,"n":"פרוש-גליקמן, נחום מירושלים","b":"מחכמי ירושלים"},{"i":39152,"n":"פרוש-גליקמן, שלמה זלמן","b":"מגדולי חכמי ירושלים-תר\"ס"},{"i":39153,"n":"פרז'ון, משה","k":"בעל ויכתוב משה"},{"i":39154,"n":"פרזיסוסקר, אליעזר מזמברוב","b":"רב בזמברוב. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":39155,"n":"פרזיסכר, יצחק דוד הכהן","f":"ישראל יהודה","bt":"תרכח","dt":"תשא","b":"רב בסלומפא(=סלופמא)-פלך קיעלץ-תרנג, שפערוב-פלך פיעטרקוב, זליחוב-פלך שדליץ."},{"i":39156,"n":"פרזיסכר, ישראל יהודה","b":"רב-שנת תר\"מ"},{"i":39157,"n":"פרח, יצחק מספרד ושלוניקי","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי."},{"i":39158,"n":"פרח, שלמה משלוניקי","dt":"רפה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":39159,"n":"פרחון - משפחה","b":"משפחה במרוקו שמוצאה בעיר קלעה-חמאד."},{"i":39160,"n":"פרחון, יהודה ממרוקו","b":"מחכמי מרוקו בזמן הרמב\"ם, ודן עמו בענין טריפות."},{"i":39161,"n":"פרחון, שלמה מאלגיר ואיטליה","f":"אברהם בעל הערוך","k":"בעל מחברת הערוך","bt":"ד'תתס","bp":"מרוקו","dt":"ד'תתקם - בערך","dp":"איטליה","b":"תלמיד רבנו אפרים. מגדולי המדקדקים הראשונים, מחכמי קלעא(=קלעת חמאד)-מרוקו-ד'תתקכ\"א, עבר לאיטליה."},{"i":39162,"n":"פרחי יוסף שבתי","bt":"1802","dt":"ה'תרמב 1882","bk":[["תקפו של יוסף",""]]},{"i":39163,"n":"פרחי מירקדו, מאיר","f":"ראה פרחי, מאיר"},{"i":39164,"n":"פרחי, אברהם מאזמיר","f":"דניאל","bt":"תרלד","bp":"אזמיר","b":"תלמיד ר שמואל פונטרימולי. ש\"ץ בק\"ק שונצין באזמיר, בקי בחכמת הפרצוף, ויודע עתידות. עלה לארץ."},{"i":39165,"n":"פרחי, אברהם פרץ מסופיה","dt":"תקן - כג אלול","dp":"סופיה","b":"מחכמי סופיה."},{"i":39166,"n":"פרחי, אהרן הכהן","f":"יהושע","dt":"תקעג - ח אדר","b":"רב בשלוניקי."},{"i":39167,"n":"פרחי, אליהו מירושלים","b":"מחכמי ישיבת \"נוה שלום\" בירושלים-תקיח."},{"i":39168,"n":"פרחי, אליעזר מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-תקיח. חתם-תקיו על שטר התקשרות עם חכמי ירושלים."},{"i":39169,"n":"פרחי, דוד יוסף","k":"בעל אהבת עולם","b":"מרבני דמשק-תרמ. חיבר \"אהבת עולם\""},{"i":39170,"n":"פרחי, הלל מדמשק","f":"יעקב מאיר","k":"סדור פרחי","bt":"תרכח","bp":"דמשק","b":"רופא במצרים, יסד חברת \"צדקה ומרפא\", פרסם ספרים בערבית."},{"i":39171,"n":"פרחי, חיים (נסים) מדמשק ועכו","f":"שאול","bt":"תקך","bp":"דמשק","dt":"תקעט - א אלול","dp":"עכו","b":"יועץ הפחה בדמשק ועכו בזמן מלחמת נפוליאון, נרצח ע\"י המושל."},{"i":39172,"n":"פרחי, חיים מסופיה","f":"אהרן בכור","bt":"תרלז","bp":"סופיה","b":"פרסם מאמרים בעתוני התקופה, יסד אגודה \"השחר\", פעיל ציוני בבולגריה, נשיא התאחדות הקהלות, עלה לארץ-תרצו והתישב בתל אביב."},{"i":39173,"n":"פרחי, חיים מסופיה - א","f":"אברהם","b":"רב בסופיה-שנות ה-ת'."},{"i":39174,"n":"פרחי, יהודה רפאל","b":"מרבני דמשק-תרל\"ח"},{"i":39175,"n":"פרחי, יהושע אשרי","b":"מרבני ירושלים"},{"i":39176,"n":"פרחי, יום טוב מאיר מחברון","b":"מחכמי חברון, חבר בית דינו של ר אליהו מאני ובשנת תרכב חתם עמו על פסק דין. אחת מתשובותיו בספר \"שערי רחמים\"."},{"i":39177,"n":"פרחי, יוסף יהודה אצלאן מדמשק","bt":"תרכד","bp":"דמשק","b":"מראשי קהלת דמשק, נשיא \"בני ברית\"-תרפג, סייע למגורשים לדמשק בזמן מלחה\"ע ה-I."},{"i":39178,"n":"פרחי, יוסף מירושלים","dp":"ירושלים","b":"מחכמי ירושלים-שנות ה-תק', נפטר צעיר."},{"i":39179,"n":"פרחי, יוסף שבתי - ישפ\"ה","f":"יהושע אשר","k":"בעל עושה פלא","bt":"תקסב","bp":"ירושלים","dt":"תרב","dp":"ליוורנו","b":"חיבר \"עושה פלא\" ליוורנו תרל ועוד רבים, כמו כן הוציא לאור ספרים של חכמים נוספים."},{"i":39180,"n":"פרחי, יצחק מאיטליה","k":"בעל טעמי המצות","b":"תלמיד ר שלמה מולכו. מקובל מחכמי איטליה, בתקופת המבי\"ט - ר משה טרני. ממשפחה ממגורשי ספרד. רבו של הרמ\"ע מפאנו בקבלה."},{"i":39181,"n":"פרחי, יצחק מירושלים","dt":"תקעג - ז אלול","b":"מרבני ירושלים"},{"i":39182,"n":"פרחי, יצחק מצפת","f":"שלמה","k":"בעל מתוק לנפש","bt":"תקלט-מב","bp":"צפת","dt":"תריג - ג-ח אייר","dp":"ירושלים","b":"מחכמי צפת וירושלים ומחכמי ישיבת \"בית אל\", תלמיד ר יום טוב אלגזי, ר אברהם שלום מזרחי שרעבי-הרא\"ש (נכד הרש\"ש) ראש הישיבה. בשליחות קהילת ירושלים וחברון מספר פעמים. בשליחות בדמשק יחד עם רבו להצלת השר ר חיים פרחי-תקפא שנאסר עם ר חיים פיזנטי. מראשי ישיבת \"תפארת ישראל\" יחד עם הרב האג\"ן, הקים את ישיבת \"חיי עולם\" בירושלים. חיבר \"מתוק לנפש\", \"מרפא לנפש\" ועוד. חתם על מכתב רבני ירושלים כנגד אספת הריפורמים בברונשויג בתוך \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":39183,"n":"פרחי, ישראל חנוך מירושלים","f":"יצחק","bt":"תקפו","bp":"ירושלים","b":"מחכמי חברון-תקפו, בשליחות באדריאנופול-תרכח. (לדעת בניהו היה סגינהור משום שלא נמצאה חתימתו). בשנת תרל חתם עם רבני חברון."},{"i":39184,"n":"פרחי, ישראל מירושלים","b":"רב בישיבת \"בית אל\" בירושלים."},{"i":39185,"n":"פרחי, מאיר יום טוב נסים מירקדו","k":"מירקאדו פרחי","b":"מחכמי ירושלים, בשנת תרג הסכים לספר \"דברי שלום\", היה אפוטרופוס על אלמנת הר\"י אמזלג ויתומיה. בשנת תרי בשליחות הקהלה."},{"i":39186,"n":"פרחי, מאיר שלמה","b":"אין נתונים"},{"i":39187,"n":"פרחי, מנחם מירושלים","k":"בעל רב פעלים","bt":"תקצה","bp":"רודוס","b":"עלה עם אביו משומלא לירושלים, מורה ברוסג'וק, פרסם מאמרים בעתוני התקופה. מתומכי ר יהודה חי אלקלעי."},{"i":39188,"n":"פרחי, משה מדמשק","f":"שאול","b":"אחיו של ר חיים מעכו, שכר עם אחיו צבא כדי לנקום את מות אחיהם בעכו."},{"i":39189,"n":"פרחי, משה מטבריה","dp":"טבריה","b":"מחכמי טבריה בזמן חידוש הישוב ע\"י ר חיים אבולעפיה-תק. חתם על כתב שליחותם של ר מסעוד בונאן ור דוד יוסף מלמד ור שמואל שלם."},{"i":39190,"n":"פרחי, משה מירושלים","dt":"תקעה - יז אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":39191,"n":"פרחי, נסים חיים מירושלים","f":"נתן","dt":"תקסט - טו חשון","dp":"ירושלים","b":"גביר בירושלים. חתן ר יום טוב אלגזי."},{"i":39192,"n":"פרחי, רפאל אליעזר מירושלים","b":"מחכמי ישיבת בית אל בירושלים-תקיד, חתם על שטר התקשרות עם ר שלום שרעבי - הרש\"ש-תקיח."},{"i":39193,"n":"פרחי, רפאל מדמשק","f":"שאול","b":"אחיו של ר חיים מעכו, שכר עם אחיו צבא כדי לנקום את מות אחיהם בעכו."},{"i":39194,"n":"פרחי, שלמה מדמשק","f":"שאול","dt":"תקפא","dp":"עכו?","b":"אחיו של ר חיים מעכו, שכר עם אחיו צבא כדי לנקום את מות אחיהם בעכו, ונרצח בדרכו."},{"i":39195,"n":"פרחי, שלמה מירושלים","dt":"תקנח - כז סיון","dp":"ירושלים","b":"רב בירושלים, אביו של ר יצחק פרחי הדרשן."},{"i":39196,"n":"פרחי, שמואל אברהם מירושלים","b":"רב בירושלים-תקע, וחתם על שטר חזקה עם ר רחמים פנחס מזרחי, עם ר יוסף פרחי."},{"i":39197,"n":"פרחיה הכהן מאיטליה ושלוניקי","f":"שמואל","bp":"איטליה","dt":"שח - ל תשרי","dp":"שלוניקי","b":"רופא, מגדולי חכמי איטליה, ר\"מ בק\"ק \"איטליה\" בשלוניקי. מחותמי ההסכמות בשלוניקי. בניו: ר שמואל ור דניאל - רופאים בשלוניקי, בנו ר אברהם - דיין בשלוניקי-שכה, ר משה - רופא, ר יוסף. נספד מאת ר משה אלמושנינו."},{"i":39198,"n":"פרחיה חנן משלוניקי","dt":"תקמז - ו תמוז","dp":"ירושלים","b":"רב בשלוניקי-תקלד, עלה לירושלים."},{"i":39199,"n":"פרחיה ממצרים","f":"נסים","b":"מחכמי מצרים בשנת ה' אלפים, בשנת מו חתם על חרם הנשיא מדמשק נגד ר שלמה פטיט שערער על ספרי הרמבם. כנראה שראה את ר אברהם בן הרמבם."},{"i":39200,"n":"פרחיה ממצרים - א","f":"יוסף","b":"מחכמי מצרים בזמן הרמב\"ם. דיין בלמחלה-ד'תתקן. חתם על תקנות חכמי מצרים-ד'תתקמז (1187) והתקנות הובאו בתשובות הרמבם."},{"i":39201,"n":"פרחיה מתימן","f":"משלם","dt":"קסז","dp":"תימן","b":"פיוסוף מחכמי תימן בסוף המאה-14. חיבר שאלות ותשובות בפילוסופיה-[לפני קסז], כהמשך לתשובת ר יעקב בן יפת הכהן שהשיב לשואל אלמוני ופנה לר פרחיה שיכתוב גם הוא."},{"i":39202,"n":"פרחיה, אברהם הכהן משלוניקי","f":"יהושע","dt":"תסו-תעט","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":39203,"n":"פרחיה, אברהם הכהן משלוניקי","f":"פרחיה הכהן משלוניקי","dt":"שנג - ג חשון","dp":"שלוניקי","b":"דיין בשלוניקי-שכה. אחיו של הרופא דניאל"},{"i":39204,"n":"פרחיה, אברהם הכהן משלוניקי","b":"דיין בשלוניקי, חתם-תקפו -בענין עגונה."},{"i":39205,"n":"פרחיה, אברהם הכהן משלוניקי","f":"מרדכי","b":"חכם שלם בשלוניקי-ראשית שנות ה-תר'."},{"i":39206,"n":"פרחיה, אברהם הכהן משלוניקי ומצ","dt":"תפה - אלול","dp":"אלכסנדריה","b":"רופא, ראש ישיבה בקהלת איטליה ישן בשלוניקי, עבר לאלכסנדריה-מצרים, טבע בים-ליד אלכסנדריה. בנו - ר חיים."},{"i":39207,"n":"פרחיה, אברהם יצחק הכהן משלוניק","dt":"תרעה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":39208,"n":"פרחיה, אברהם משלוניקי","f":"חסדאי משלוניקי","b":"דיין בשלוניקי-אחרי תלח."},{"i":39209,"n":"פרחיה, אהרן הכהן משלוניקי","f":"חיים אברהם","k":"בעל פרח מטה אהרן","r":"רב הכולל של העיר שלוניקי","bt":"שפז או תה","bp":"שלוניקי","dt":"תנז","dp":"שלוניקי","b":"תלמיד ר חסדאי פרחיה הכהן. ר\"מ בשלוניקי-תם, רב ראשי בשלוניקי-תמט על מקום ר אליהו קובו. חיבר גם \"פרחי כהונה\", ועוד. כנראה שנתן מכתב המלצה לנחמיה חייא חיון לרבנות אישקופיא. בניו: ר עזריאל שהדפיס את ספריו באמשטרדם, ר יהושע. חתנו - הגביר ר יעקב הכהן פרחיה.","bk":[["פרח מטה אהרן [שו\"ת]",""],["בגדי כהונה - דרושים",""],["זכרון דברים - הלכה",""],["פרחי כהונה - ב\"ק, ב\"מ, כתובות, גיטין, ע\"ז, קידושין",""]]},{"i":39210,"n":"פרחיה, אהרן הכהן משלוניקי","f":"יהושע","dt":"תקעה - אד\"ב","dp":"שלוניקי","b":"דיין בשלוניקי, חתם-תקעב עם רבני שלוניקי. בנו ר יהושע ונכדו ר אהרן - נפטרו בחייו. נספד מאת ר יעקב רפאל מנשה."},{"i":39211,"n":"פרחיה, אהרן הכהן משלוניקי","f":"יצחק","dt":"תרכח","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר."},{"i":39212,"n":"פרחיה, גבריאל הכהן משלוניקי","dt":"תרסא","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":39213,"n":"פרחיה, דניאל הכהן מלאריסה","bp":"שלוניקי","b":"מראשי קהלת לאריסה-תפב."},{"i":39214,"n":"פרחיה, דניאל הכהן משלוניקי","f":"פרחיה הכהן משלוניקי","k":"בעל שארית יוסף","dt":"שלה - ח תמוז","dp":"שלוניקי","b":"רופא מחכמי טורקיה, ראש ישיבה ומחבר, רב ק\"ק \"איטליה\" בשלוניקי. למד פילוסופיה, מתימטיקה, רפואה, אסטרונומיה. משריפה גדולה של כל ספריו נותר רק פירוש לספר \"שארית יוסף\" לר יוסף בן שם טוב ן ישועה. חתם על הסכמות הקהל, וחתם-שלג על החרם נגד הרופא דאוד. אחיו - ר שמואל על מקומו אחריו בקהלת איטליה."},{"i":39215,"n":"פרחיה, דניאל הכהן משלוניקי - ב","b":"מחכמי שלוניקי-שנות ה-ת'. בניו - ר וידאל, ר יעקב."},{"i":39216,"n":"פרחיה, וידאל הכהן משלוניקי","f":"דניאל משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":39217,"n":"פרחיה, חיים אברהם הכהן משלוניק","f":"משה","dt":"תכח - תשרי","dp":"שלוניקי","b":"חתן ר אהרן ן חסון. רופא ורב הכולל בקהלת \"איטליה ישן\" בשלוניקי-תכו בזמן ה\"תשובה הגדולה\" (של שבתי צבי). מבניו: ר אהרן, ר שמואל, ור יהושע הרופא."},{"i":39218,"n":"פרחיה, חיים הכהן משלוניקי","f":"חסדאי","dt":"תפג - לפני","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":39219,"n":"פרחיה, חיים הכהן משלוניקי - ב","f":"אברהם משלוניקי ומצרי","b":"גביר מחכמי שלוניקי-סוף שנות ה-ת'."},{"i":39220,"n":"פרחיה, חסדאי הכהן","f":"שמואל","k":"בעל תורת חסד","bt":"שף - בערך","dt":"תלז-כד - אלול","b":"תלמיד ר חיים שבתי. רב בק\"ק איטליה ישן בשלוניקי-תלא, ר\"מ ודיין ורב על מקום ר מנחם שולם. מתלמידיו: ר דניאל ג'יראסי בעל \"אודה השם\". בנו - ר אברהם, ר שמואל (לפי רוזניס). מתורתו ב\"פרח מטה אהרן\" לתלמידו ר אהרן חיים הכהן.","bk":[["תורת חסד [שו\"ת]",""]]},{"i":39221,"n":"פרחיה, יהודה חיים משלוניקי","b":"פעיל ציוני ביון, פרסם חוברות, מחזות, ביקר בארץ."},{"i":39222,"n":"פרחיה, יהודה חננאל משלוניקי","b":"מחכמי שלוניקי-תרע בערך. עלה לארץ ויסד את \"ישיבת אליהו\" בתל אביב, ופעל להקמת ביהכ\"נ \"אליהו הנביא\" ו\"שושנה\"."},{"i":39223,"n":"פרחיה, יהושע הכהן משלוניקי - א","dt":"תנו","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":39224,"n":"פרחיה, יהושע הכהן משלוניקי - ב","f":"אהרן בן יהושע","k":"בעל ויקרא יהושע","bt":"תקלא","bp":"שלוניקי","dt":"תקע - ו אייר","b":"חתן ר יצחק הכהן חסיד. רב, דרשן, וראש ישיבה בשלוניקי. מתלמידיו: ר אברהם דוד, ר יוסף שאלתיאל. בנה ביה\"כ \"לה פלאסה|, פעל למען קופת ביקור חולים. מלומד בנסים. בנו ר יצחק הו\"ל את ספרו \"ויקרא יהושע\", עם הוספות מבנו ר אהרן. נספד מאת ר יעקב רפאל מנשה."},{"i":39225,"n":"פרחיה, יעקב משלוניקי","f":"דניאל משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":39226,"n":"פרחיה, יעקב משלוניקי וירושלים","dt":"תקסז - יא אייר","dp":"ירושלים","b":"מחכמי שלוניק, עלה לירושלים."},{"i":39227,"n":"פרחיה, יצחק הכהן מירושלים","f":"יהושע","bt":"תקסב","dt":"תרמב - אחרי","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים. חידושים שלו הופיעו בספר אביו \"ויקרא יהושע\"."},{"i":39228,"n":"פרחיה, יצחק הכהן משלוניקי","f":"אברהם","k":"בעל ספר הישר","dt":"תרצו","dp":"שלוניקי","b":"ראש המוהלים בשלוניקי על מקום ר יוסף קרסו (מל כ-12,000 ילדים). חיבר ספר בהלכות שחיטה - בכת\"י, וספר הישר בלאדינו על התורה - שלוניקי תרנח. אחיו - ר חיים - בועד הרבנים בשלוניקי."},{"i":39229,"n":"פרחיה, מרדכי בכור הכהן משלוניק","k":"רב כהנא","dt":"תרט","dp":"שלוניקי","b":"דרשן ומוכיח בשלוניקי, והיה עולה לתיבה בכל צרה, מכונה \"רב כהנא\"."},{"i":39230,"n":"פרחיה, משה הכהן משלוניקי","f":"אברהם","dt":"תח","dp":"שלוניקי","b":"מחכמי שלוניקי-סוף שנות ה-ש'. נספה במגפה הגדולה בשלוניקי-תח. בנו - ר אברהם חיים."},{"i":39231,"n":"פרחיה, משה הכהן משלוניקי","f":"פרחיה","dt":"שץ - אלול","dp":"שלוניקי","b":"רופא ורב בשלוניקי. אחיו - ר דניאל בעל \"שארית יוסף\", בנו - ר אברהם."},{"i":39232,"n":"פרחיה, משה מארטא-יוון","b":"מחכמי ארטא בזמן ר שמואל קלעי."},{"i":39233,"n":"פרחיה, שלמה הכהן משלוניקי","b":"מחכמי שלוניקי. הו\"ל \"בן פורת יוסף\" לר יוסף קובו-תקנז."},{"i":39234,"n":"פרחיה, שמואל משלוניקי","f":"פרחיה הכהן משלוניקי","dt":"שעב - אחרי","dp":"שלוניקי","b":"משורר, ופוסק מחכמי שלוניקי, חתם על הסכמות הקהלה בשלוניקי. כמה משיריו נדפסו בהקדמות לספרי חכמי דורו. בנו - ר חסדאי פרחיה הכהן."},{"i":39235,"n":"פרחיהו (פרוכובניק), אפרים נחום","f":"אברהם יהושע","bt":"1885","bp":"קלינקוביץ","dt":"1959","dp":"ירושלים - בית זרע","b":"מורה לעברית בקובנא, בישיבת לידא, בגימנסיה העברית ובסמינר למורים של \"תרבות\" בקובנא. עסקן ציוני וגדולי המחנכים בליטא ובעל השפעה רבה על הנוער. ציר בקונגרס הציוני. עלה לארץ-1933 והיה מורה בפתח תקוה ובגימנסיה הרצליה בתל אביב. קובץ לזכרו \"בנתיב המורה\" ת\"א תשכב."},{"i":39236,"n":"פרטוש, נסים מאלגיר","b":"מחכמי אפלו-אלגיר. הו\"ל \"גואל ציון\" גרבה תשיג יחד עם ר יחייא בן מרדכי עטייה מאפלו-אלגיר."},{"i":39237,"n":"פרטוש, פרץ מאלג'יר","bt":"תס - בערך","dt":"תקל - בערך","b":"רב במזאב (גרדאייה)-אלג'יר. נזכר בשות ר יהודה ן עייאש."},{"i":39238,"n":"פרטוש, שמואל מדומבוואר","b":"רב ניאולוגי בדומבוואר-1889. פעיל ציוני."},{"i":39239,"n":"פריאר, שבתי ממנוסטרישץ","b":"מחכמי מנוסטרישץ."},{"i":39240,"n":"פריבה, נסים ממצרים","b":"מחכמי מצרים בזמן הרדב\"ז"},{"i":39241,"n":"פריברג, נחמן דב מדוקלא","b":"מחכמי דוקלא-תרפח."},{"i":39242,"n":"פריד, אברהם מבסקביץ","b":"רב בבסקביץ. חתנו של ר מרדכי סערעד מסערדאוהל (שי\"א שהיה נכד של ה\"תוספת שבת\"). היה חביב אצל החת\"ס. אביו של ר מאיר אב\"ד יאלע."},{"i":39243,"n":"פריד, אהרן מביסערמן(=בוסורמני)","f":"אלימלך או אפרים פישל","k":"בעל אומר לציון","bt":"תקעג","bp":"ביסערמן","dt":"תרנא - כ סיון","dp":"ביסרמן או ירושלים","b":"אביו היה היהודי היחיד בעיר. תלמיד חותנו ר אלעזר לעוו מסנטוב, והחת\"ס - שהפקיד בידיו ללמד את בנו ה\"כתב סופר\" . רב במעזא-טשאטה-תקצג, שאמשון-תקצז, דברצין-תרטז, ביסערמען(=בסארמני)-תרך. (לפי גליס עלה לירושלים ונפטר שם). חיבר שו\"ת מהרא\"פ, \"אומר לציון\" אויהל תרלב, \"צל הכסף\" אונגואר תרלח ועוד,"},{"i":39244,"n":"פריד, אהרן צבי ממוואלקא","b":"נכד ר אהרן צבי פריד ממארגרטן(=מארגרטין). חתנו - ר עקיבא בלוי מקראסנא."},{"i":39245,"n":"פריד, אהרן צבי ממרגרטן וניגרש","dt":"תרטו - יח אב","b":"רב במארגרטן, עבר לכפר ניגרשד-ליד סטמר."},{"i":39246,"n":"פריד, אליעזר יצחק מוולוזין","f":"הלל מהורדנא","bt":"תקע","dt":"תריג - יט אלול","b":"נכד-אבי אמו ר חיים מוולוזין. חתן דודו - ר יצחק מוולוזין. רב ור\"מ בוולוזין-תרט בזמן חותנו ועל מקומו אחריו. בנו - ר חיים הלל. חתניו - ר חיים מאיר נח מסטופצי ומוסקבה, ר אברהם דב מאירומן."},{"i":39247,"n":"פריד, אליעזר ליב","b":"חיבר שיר בשבח אסיפת המדינה בעברית והונגרית, ובסופו ברכה לקיסר פרנץ יוזף."},{"i":39248,"n":"פריד, אליעזר מניגרשט","b":"דומ\"צ בניגרשט-תר\"ע"},{"i":39249,"n":"פריד, אליעזר מקלויזנבורג","f":"חיים יעקב מטיסא-ליק","dt":"תרצ.. - בערך","b":"נכד ר אהרן צבי פריד מניגרשד, דיין בניגרשד - סוף המאה ה-19, דיין בקלויזנברוג והיה במחלוקת עם כמה מרבני טרנסילבניה בראשות ר שאול בראך מקרולה - על רקע פילוג הקהלה הספרדית. על כך נדפסו קונטרסים בעד ונגד. הו\"ל כתב עת בקלויזנבורג-תרצא ובו עסק בענין פילוג הקהלות."},{"i":39250,"n":"פריד, אריה ליב מבודפשט","b":"חתן ר זאב וולף ציטרון. רב בבודפשט."},{"i":39251,"n":"פריד, הלל מהורדנא","f":"שמחה","dt":"תקצג - ב אדר","dp":"הורדנא","b":"חתן ר חיים מוולוזין (שם אשתו אסתר וחתמה על תנאים לביתה אחר שנתאלמנה). ר\"מ בישיבת וולוזין. מו\"צ בהורדנא על מקום אביו, וחתנו - ר יחזקאל על מקומו אחריו. נספד בידי ר דוד מנוברדוק. מתשובותיו בספר נכדו \"חוט המשולש\". בנו - ר אליעזר יצחק מוולוזין."},{"i":39252,"n":"פריד, חיים אלתר","f":"משה אהרן פריד","dt":"תשד","b":"רב בה' מאד"},{"i":39253,"n":"פריד, חיים הלל מוולוזין","f":"אליעזר יצחק מוולוזין","dt":"תרמא - ו כסלו","b":"מצאצאי ר חיים מוולוזין, חתן ר שמואל לנדא-חתנו של ר יצחק מוולוזין. ר\"מ בוולוזין, גיסו של הנצי\"ב. הו\"ל \"חוט המשולש\" לאבותיו - בעילום שמו."},{"i":39254,"n":"פריד, חיים יעקב מטיסאליק","f":"אהרן צבי פריד","dt":"תרעז - כד טבת","b":"רב בטיסאליק"},{"i":39255,"n":"פריד, חיים מסנט-פעטר","bt":"תרטו","dt":"תרפח - ה תמוז","b":"תלמיד ישיבת מאד אצל בעל \"קול אריה\". חתן ר יצחק גליק מסנט-פעטר בעל \"חינוך בית יצחק\", רב בסנט-פעטר(=סט-פטר)-תרמח על מקום חותנו, וחתנו ר משה חיים גרינפלד על מקומו אחריו. עוד מחתניו - ר אשר אנשל יונגרייז מקוזניץ, ר משה הלוי יונגרייז מעזא-קישוועד. מצאצאיו - ר נתן נטע פריד מניו יורק."},{"i":39256,"n":"פריד, חיים צבי מקאפוש","f":"יעקב מאיר מקאפיש","dt":"תשג - ו אייר","dp":"קאפוש","b":"תלמיד דודו - ר מנחם יהודה פריד מסערעדנא, בעל ערוגת הבושם. חתן ר מנחם גרשון מוסקוביץ מטשעטשוויץ-חתנו של ר יושע ברוך רייניץ מטשעטשוויץ. נפטר צעיר."},{"i":39257,"n":"פריד, יהודה מאונגואר","b":"רב באונגוואר-תק\"נ"},{"i":39258,"n":"פריד, יהושע השל הכהן מקאפיש","f":"גדליה בן שלמה","k":"אדמור מקאפיש","r":"אב\"ד קאפיש","bt":"תקפג או תקצה","dt":"תרפא - כא סיון","dp":"קאפיש","b":"נתייתם בילדותו ולמד אצל ר מאיר כהנא בטשטשוביץ, תלמיד מהר\"ם א\"ש באונגוואר, הדברי חיים מצאנז, ר צבי הירש מליסקא, ור יצחק איזיק מזידיטשוב. חתן ר נחמיה מראדוואנקא. רב ואדמור בקאפיש-תרל והקים שם ישיבה, בנו ר יעקב מאיר על מקומו בחייו-תרס. חתנו ר אהרן וייס מבנידקוביץ ומונקטש. חיבר \"זכרון יהושע\" (או ישועה). אחיו - ר יחיאל מיכאל. עליו בספר אנשי מופת לברוין.","bk":[["זכרון יהושע",""]]},{"i":39259,"n":"פריד, יוסף אליהו משוקיאן","f":"יהודה ליב","k":"בעל אהל יוסף","bt":"תרא","bp":"קראקינובה","dt":"תרפז - ו אייר","b":"רב בשוקיאן, ניו יורק-תרנא. חיבר את ספר השו\"ת הראשון שנדפס בניו יורק \"אהל יוסף\" ניו יורק תרסג."},{"i":39260,"n":"פריד, יוסף מסאלונטה וגרוסורדין","dt":"תרצה - אלול","dp":"גרוסורדין","b":"שו\"ב וחזן בסאלונטה-תרלט, ובהמשך רב הקהלה-תרמה - ולמרות שהקהלה היתה ניאולוגית היה רב אורטודוכס, עבר לגרוסורדין-תרפה. נספד ע\"י ר בנימין פוקס רבה של גרוסורדין."},{"i":39261,"n":"פריד, יחיאל מיכל הכהן - הזקן","dt":"תרכא - טו אייר","b":"מו\"צ בטשאניע. בנו - בעל \"פני מבין\"."},{"i":39262,"n":"פריד, יחיאל מיכל הכהן - הנכד","f":"נתנאל","k":"בעל תורת יפה","dt":"תשב","b":"רב באוי-וארוש-תרעו על מקום אביו, ובנו ר עוזר על מקומו אחריו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39263,"n":"פריד, יעקב מאיר הכהן מקאפיש","f":"יהושע השל מקאפיש","k":"אדמור מקאפיש","bt":"תרטו","dt":"תרצו - י כסלו","dp":"קאפיש","b":"חתן גיסו ר אהרן וייס מבנדקוביץ. רב ואדמור במונקאטש, קאפיש-תרס על מקום אביו - בחיי אביו. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד (בהוצאת בניו). בניו - ר פנחס, ר חיים צבי, ר מרדכי דוד על מקומו אחריו, ר נפתלי מפאווליץ. חתניו - ר יקותיאל יהודה גרינוולד מיארע, ר אהרן וייס מבנדקביץ."},{"i":39264,"n":"פריד, יצחק מהוסיאטין","b":"מחכמי הוסיאטין-תרכד."},{"i":39265,"n":"פריד, יצחק מטרענטשין","f":"עוזר מקלינורדין","bp":"קלינורדין","b":"תלמיד הדעת סופר, ר יהושע השל לנדא מוינקא, ועוד. רב בטרנטשין, ניצל מהשואה ואחריה רב בקלינורדין, עבר לניו יורק. עורך ספרי הגאון מרוגטשוב."},{"i":39266,"n":"פריד, יצחק מקלינורדין","dt":"תרסז - יט תמוז","b":"נכד ר ירמיה ממטרסדורף. תלמיד מהר\"ם א\"ש מאונגוואר. גביר מחכמי קלינורדין. חתנו - ר ירמיה פריד בעל פני מבין המביא מתורתו בספרו בשם \"זכרון יצחק\"."},{"i":39267,"n":"פריד, יצחק מקלינורדין","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":39268,"n":"פריד, ירמיה מזאסלב","b":"רב בזאסלב,עלה לא\"י-תרצ\"ב,דיין בתל אביב"},{"i":39269,"n":"פריד, ישעיה מקראלי","b":"חתן ר מאיר בן ירמיהו לנדא ממטרסדורף. גביר מחכמי קראלי-תקצ."},{"i":39270,"n":"פריד, ישראל מאונגואר","dt":"תריד","b":"דומ\"צ באונגוואר"},{"i":39271,"n":"פריד, מאיר יעקב","k":"בעל ימים ושנים","bt":"1871","bp":"קאלואריה","dt":"1940","dp":"תל אביב","b":"יסד את \"בני ציון\" בוארשא וחברת \"חובבי שפת עבר\". ציר בועידת מינסק, וחיבר ספר על הועידה \"די גרוזיע ציוניסטען אסיפה אין מינסק\". פרסם ב\"הצפירה\", ועוד. בהשפעת י.ל. פרץ עבר לכתוב באידיש. כתב ספר על דרייפוס שתורגם לשפות רבות. חיבר ספרים וזכרונות."},{"i":39272,"n":"פריד, מאיר מיאלע-באגעדא","f":"אברהם מבסקביץ","k":"בעל מאיר עיני חכמים","bt":"תקס","bp":"[בסקביץ]","dt":"תריט","b":"תלמיד החת\"ס. מחכמי קאמארן, סערדאוהל-תקץ, רב ביאלע, באגעדא. בנו גם ר מרדכי פריד אב\"ד מרטינסברג."},{"i":39273,"n":"פריד, מנחם מנדל מפוליאן","b":"רב בפוליאן-תר\"ע"},{"i":39274,"n":"פריד, מנחם מקלינורדין","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":39275,"n":"פריד, מרדכי דוד הכהן מקאפיש","f":"יעקב מאיר מקאפיש","dt":"תשד","b":"חתן ר יהודה פרידלנדר מבאקאני. רב בקאפיש על מקום אביו. סייע לאחיו ר נפתלי - בהוצאת \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד (בהוצאת אביו). נספה בשואה?"},{"i":39276,"n":"פריד, מרדכי ממרטינסברג","f":"מאיר פריד בוסקוביץ","k":"בעל ברוך מרדכי","bt":"תריא","bp":"סערדאוהל","dt":"תרעג - כה אד\"א","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור פנחס ליב פרידמן מקאמארן. חתן ר אברהם וייס, ובזיוו\"ש חתן ר מאיר פרנקל. רב באסאנפא-תריא (מזמן יסוד הקהלה), טעליקא-תרלד, מארטינסברג-תרמה (לשם עבר מושב הרבנות של הקהלות הקודמות). פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":39277,"n":"פריד, משה אהרן מטיסאלוק","f":"חיים יעקב פריד","bt":"תרמ","dt":"תשד","b":"דומ\"צ בטיסאלוק"},{"i":39278,"n":"פריד, משה יעקב מסנט מרטון","dt":"תשד","b":"רב בקין סנט מרטון. חתן ר ישראל הלוי יוגנרייז מנאדאודוואר."},{"i":39279,"n":"פריד, משה ממונקטש","dt":"תרלז - כט ניסן","b":"רב בקאסאן,ראב\"ד במונקאטש"},{"i":39280,"n":"פריד, נפתלי הכהן ממיהאלביץ","f":"יעקב מאיר מקאפיש","dt":"תשד","b":"רב במיהאלביץ-צ'כוסלובקיה, פאבעליץ. הו\"ל \"שערי אורה\" - מיהאלביץ תרץ-תרצד - יחד עם אחיו ר מרדכי דוד."},{"i":39281,"n":"פריד, נתן נטע","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":39282,"n":"פריד, נתנאל הכהן מקלינורדין","f":"יחיאל מיכל","k":"בעל פני מבין","bt":"תריח","bp":"שעניע","dt":"תרעז - ד אלול","b":"לאחר שנתייתם גדל אצל דודו ר ישכר בר פרידמן מזעשיסעוו (זשיפועווער), ר אברהם הכהן בעל \"קול אריה\", ר חיים צבי מנהיימר, ר חיים צבי מאונגוואר. חתן הגביר ר יצחק פריד מקלינוארדין. ר\"מ בישיבה בקלינורדין. רב באוי-וארוש-תרנב, ובנו ר יחיאל מיכאל מלכיור על מקומו אחריו. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא. מאמר ממנו ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד. שאלה ממנו לר שמואל דוד יונגרייז.","bk":[["פני מבין [שו\"ת",""],["עה\"ת]",""],["כליגמא",""]]},{"i":39283,"n":"פריד, נתנאל הכהן מראצפרט","dt":"תרפז - יב חשון","b":"דומ\"צ במאד, ראצפערט(=ראצפערד)-תרנז. נסמך מאת בעל \"בית נפתלי\"."},{"i":39284,"n":"פריד, עוזר הכהן מאויוארוש","f":"יחיאל מיכל","dt":"תשד","b":"רב באוי-וארוש על מקום אביו. נספה בשואה."},{"i":39285,"n":"פריד, עוזר מקראלי","b":"גביר בקראלי, בנה בימ\"ד ומינה למגיד את ר זלמן וולף בעל \"עמק המלך\"."},{"i":39286,"n":"פריד, עזרא מברצל","dt":"תשג","b":"רב בברצל-תרצ\"ו"},{"i":39287,"n":"פריד, פייטל מוילנא","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":39288,"n":"פריד, פנחס הכהן","f":"יעקב מאיר מקאפיש","dt":"תשא - כא תשרי","b":"תלמיד בעל ערוגת הבושם, ובעל באר שמואל מאונסדורף. נפטר צעיר."},{"i":39289,"n":"פריד, קלונימוס קלמן מראצפרט","dt":"תשד","b":"דומ\"צ בראצפערט"},{"i":39290,"n":"פריד, שלמה יהודה ליב מקאפאלטש","f":"מרדכי ממרטינסברג","b":"רב בקאפאלטש."},{"i":39291,"n":"פריד, שמואל מוילנא","f":"חיים הלל מוולוזין","bt":"תרכט","bp":"וולוזין","dt":"תשא","dp":"פונרי","b":"נכד ר אליעזר יצחק-נכדו של ר חיים מוולוזין. תלמיד ישיבת וולוזין. חתן ר יהודה ליב חזנוביץ מוילנא. רב בנובוסביט(=נאויסוועט)-פרבר וילנא-תרסו, דיין בוילנא-תרע על מקום חותנו. חבר בועד הרבנים בוילנא-תרע. השתתף במשלחות רבנים שונות ובהם בענין משפט בייליס. היה בגרמניה-תרעד וארגן ועד עזרה לפליטים היהודים, ובוילנא-תרעד יסד חברה \"עזרה מהירה\" לעזרה לפליטים. מראד \"יאקופו\" וממיסדי הבנק העממי המרכזי בוילנא. פעל לטובת נפגעי השטפונות בדרום פולין-תרפז. מייסד בתי תלמוד תורה בוילנא, ומראשי המזרחי. נספה בשואה. נסמך מאת: ר רפאל שפירא מוולוזין."},{"i":39292,"n":"פריד, שמואל מצ'ורגוי","dt":"תשד","b":"רב בקהילה הניאולוגית בצ'ורגוי. נספה בשואה."},{"i":39293,"n":"פריד, שמחה מלענטשני","f":"אריה ליב-דברי אריה","bt":"תעז","b":"נכד ר שמחה רפפורט מדובנא. רב בלענטשני."},{"i":39294,"n":"פריד, שמחה מנעשויז והורדנא","f":"מרדכי","dt":"תקעג - ח אלול","dp":"הורדנא","b":"רב בנעשוויז, מו\"צ בהורדנא. בנו - ר הלל-חתנו של ר חיים מוולוזין."},{"i":39295,"n":"פריד-כהנא, עוזר ממונקטש","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39296,"n":"פריד-פסקוביץ, מאיר מיאללע","k":"בעל מאיר דברי חכמים","b":"רב ביאללע-תר\"י"},{"i":39297,"n":"פרידברג חיים דב בריש","bt":"1870","dt":"ג'תתקנו 196","bk":[["כתר כהונה",""],["בית עקד ספרים",""],["לוחות זכרון",""],["מרגניתא שפירא",""],["תולדות הדפוס העברי",""],["תולדות הדפוס העברי בפולניה",""],["תולדות משפחת הורוויץ",""],["תולדות משפחת שור",""]]},{"i":39298,"n":"פרידברג, אברהם משה","b":"רב מדינת הסן"},{"i":39299,"n":"פרידברג, אברהם שלום - הר שלום","k":"בעל זכרונות לבית דוד","bt":"1838","bp":"גרודנא","dt":"1903","dp":"וארשא","b":"פרסם בעתונים שונים, פעיל בהוצאת חובבי ציון. פרסם ב\"המליץ\" לישוב ארץ ישראל, עבר לוארשא וערך את \"אשכול\". צנזור של ספרים עבריים. חיבר גם ספר הזכרונות, ועוד."},{"i":39300,"n":"פרידברג, אריה ליב","b":"בנו ר מרדכי מהאלוסק בעל \"דברי מרדכי\"."},{"i":39301,"n":"פרידברג, בנימין וולף מואנדסבק","f":"יוסף","k":"בעל אמתחת בנימין","dt":"תקכח - י סיון","dp":"ונדסבק","b":"פרנס בואנדסבק. עמד לצדו של ר יונתן איבשביץ בזמן המחלוקת, חתם על האגרת לבעל \"פני יהושע\" בפפד\"מ. אחיהם של ר יצחק ור גומפא-דיין המבורג. חיבר \"אמתחת בנימין\". בנו - ר הרץ."},{"i":39302,"n":"פרידברג, חיים דב בריש מקראקא","f":"אברהם מאיר הלוי","k":"בעל בית עקד ספרים","bt":"תרלז","bp":"קראקא","dt":"תשכא","b":"חוקר הספר העברי ומשפחות בעם ישראל. חתן ר משה פנחס רייזפלד. בעל ספריה גדולה ובית מסחר לספרים בפפד\"מ. עבר לאנטורפן. ניצל מהשואה אולם ספריו אבדו. עלה לארץ-תשו. חיבר \"בית עקד ספרים\", ועוד."},{"i":39303,"n":"פרידברג, יהודה ליב","b":"רב בפיורדא-תק\"מ"},{"i":39304,"n":"פרידברג, יוסף מאיר מהמבורג","f":"אברהם משה","dt":"תצה - כב שבט","b":"מו\"צ בהמבורג, רב בפרידבורג, הנובר-תמה. מבניו: אריה יהודה מהמבורג, יוסף מואנדסבק, חתניו - ר ישראל מרדכי גימפל שנאפיר, ר עוזר הילדסהיימר מאלטונא."},{"i":39305,"n":"פרידברג, יוסף מונדבסק","f":"מאיר מהנובר","dt":"תקיא","dp":"ונדסבק","b":"מחכמי ונדבסק."},{"i":39306,"n":"פרידברג, יצחק מואנדסבק","f":"יוסף","bp":"המבורג","dt":"תקכג - ג טבת","dp":"ונדסבק","b":"מצאצאי הרופא ר גומפל פרידברג, נכד-אבי אמו ר אפרים הקשר בעל \"לוית חן\". מיושבי הקלויז של ר ישכר בער הכהן בהמבורג, ר\"מ בקלויז של ר יונתן איבשיץ. מו\"צ בואנדסבק. נזכר אצל ר יעקב עמדן - שביקש מר יעקב להתיר לו נדר של נידוי (כנראה היה מעורב במחלוקת היעבץ ור יונתן איבשיץ)."},{"i":39307,"n":"פרידברג, מ. מפפד\"מ","dt":"תכב","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":39308,"n":"פרידברג, מיכאל מיכל","f":"שמשון","k":"בעל מיכל מים","dt":"תקכג - כו תמוז","dp":"ונדסבק","b":"חתן ר יוסף מאיר פרידברג מהנובר. דרשן, ר\"מ ודיין בואנדסבק, המבורג-תץ. בזמן המחלוקת היה לצדו של ר יונתן איבשיץ וחתם על האגרת לרבני פולין. חיבר גם \"עץ חיים\". גיסו - ר מרדכי גומפל שנאפר שסייע לו להתקבל כדיין בהמבורג."},{"i":39309,"n":"פרידברג, מרדכי גומפא מאה\"ו","f":"יוזבל","bt":"תצב","bp":"המבורג","dt":"תקסד - יג אדר","dp":"אלטונא","b":"נכד הרופא ר גומפא, ונכד-אבי אמו ר אפרים הקשר בעל \"אדני פז\". דיין באה\"ו בזמן ר רפאל הכהן. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג. אחיו: ר יצחק מואנדסבק, ר בנימין וולף בעל \"אמתחת בנימין\"."},{"i":39310,"n":"פרידברג, מרדכי מהאלוסק","f":"אריה ליב","k":"בעל דברי מרדכי","b":"רב בהאלוסק, איהומען, מאלסטבקה-תר."},{"i":39311,"n":"פרידברג, שמואל מאנגליה","f":"מרדכי","bt":"תרכב","bp":"פורטסמות-אנגליה","b":"תלמיד ביהמ\"ד \"אריה קולדש\" בפורטסמות. חתן ר י' עמנואל מברמינגהם. רב בניו קסל-תרמו ויסד בימ\"ד, ליברפול-תרנא ויסד שם את \"ועד השחיטה\". פרסם מאמרים ובהם על \"רבי יהודה הלוי\", \"הרמב\"ם\", \"משה מנדלסון\", ועוד."},{"i":39312,"n":"פרידברג-דורלך, וולף מפפד\"מ","b":"דיין בפפד\"מ-תץ. היה בועדה שאישרה איזה ספרים ניתן להדפיס בפפד\"מ, יחד עם חבריו ר יואל ענגרש, ור משה ראפ."},{"i":39313,"n":"פרידגער,יצחק איציק מאויבן","b":"תלמיד ר פנחס יהודה ליב פרוידיגר מאויבן. רשם את חדושי רבו - בכת\"י."},{"i":39314,"n":"פרידוס, אברהם זלמן מארה\"ב","f":"אברהם","bp":"ריגא","dt":"תרפד - כב תשרי","dp":"ניו יורק","b":"ראש מחלקת הספרים העבריים בספריה העירונית בניו יורק. לכבודו \"חקירות בדבר הביבליוגרפיה העברית\" ליהושע בלוך."},{"i":39315,"n":"פרידל מברוד","dt":"תקמג - לפני","b":"תלמיד הבעשט. חברו של ר מנחם מנדל מפרמישלן. עלה לארץ-תקכה עם ר\"נ מהורודנקה. בספר \"אהבת ציון\" - תיאור המסע. הניח כתבים הנזכרים ב\"אמרי פנחס\". בנו ר פאליק."},{"i":39316,"n":"פרידליב, שמואל ממיטאוי","f":"יהודה ליב","b":"בנה מחדש את ביהכ\"נ במיטאוי."},{"i":39317,"n":"פרידליבר, יצחק איציק מסערעד","bp":"סערעד","dt":"תקפח - בערך","b":"תלמיד החת\"ס. רב באויהל-תקפב. נפטר בצעירותו. מוזכר ב\"חתם סופר\"."},{"i":39318,"n":"פרידליכר, איגנץ מסולנוק","b":"רב בקהילה הניאולוגית בסולנוק. נאלץ לעזוב בגלל מחלוקת."},{"i":39319,"n":"פרידלינג, יחיאל מזקשביץ","dt":"תשג","b":"רב בזקשוויץ"},{"i":39320,"n":"פרידלינג, צבי הירש מבסקביץ","k":"בעל רץ כצבי","bt":"תרמד","bp":"זאמושטש","dt":"תשג","b":"רב בזאמושץ, בסקוביץ(=יסקוביצה), בופונזק-(=פרבר וארשא)-תרצו. נספה בשואה. הו\"ל כתב עת \"הבאר\" - זאמושץ תרפד, חיבר \"רץ כצבי\", ועוד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"המפלפל\" - קראקא תרעג, \"שערי חכמה\" - אוזרוב תרפד."},{"i":39321,"n":"פרידלנד, בצלאל","f":"נתן פרידלנד","dt":"תמג"},{"i":39322,"n":"פרידלנד, דוד מירושלים","f":"יונה","bt":"תקפז","bp":"רזיטשע (ויטבסק)","dt":"תרמה - כה שבט","dp":"ירושלים","b":"תלמיד החת\"ס, והכתב סופר. רב בחרסון, בזיוו\"ש חתן ר אריה דב. עלה לירושלים עם אביו-תריט, בשליחות באירופה-תרכו - תרלה. מראשוני פתח תקוה-תרמג."},{"i":39323,"n":"פרידלנד, נתן מטוירינין","f":"יוסף","k":"בעל כוס ישועה ונחמה","bt":"1815","bp":"טאווריג","dt":"1883","b":"תלמיד ישיבת פוניבז, סלנט. דרשן נודד, מגיד בטוירינין-תריט. בספרו הסביר שהגאולה תבוא בדרך הטבע ועכשיו שעת הכושר, פגש בטהורן-פרוסיה את ר צבי הירש קלישר ומאז פעל כשליח התנועה לישוב א\"י. פגש את אדולף כרמיה בפאריס-תרך, ועם ד\"ר אלברט כהן. נתקבל לראיון אצל נפוליאון השלישי והשיג לו תזכיר ממנו ור צבי קלישר. פגש את מונטיפיורי בלונדון שסירב לשתף עמו פעולה. פעל בשליחות החברה לישוב א\"י מיסודם של ד\"ר חיים לוריא, ור אליהו גוטמכר ור צבי קלישר. עלה לירושלים-תרמב. חיבר גם \"יוסף חן\", \"קול צופיך\", ועוד."},{"i":39324,"n":"פרידלנד, נתן מפיהם","b":"מגדולי נכבדי דורו,ראש מדינת פיהם-תכ\"ד"},{"i":39325,"n":"פרידלנדר, אהרן מאיר מבוליחוב","f":"זלמן ליב משארקוז","k":"בעל אברך","bt":"תקפז","bp":"שארקוז-אילאק","dt":"תרלה - כג תשרי","b":"תלמיד הישמח משה והמהר\"ם א\"ש, והמהרי\"א מזידיטשוב - שהיה מחותנו. רב בוולובה-תרך, בוליחוב-תרכה. בנו ר יהודה זלמן ליב על מקומו אחריו בבוליחוב. חיבר \"אברך\" מונקטש תרנג, ועוד."},{"i":39326,"n":"פרידלנדר, אלימלך מבארגו-פרונד","f":"יהודה מבורגו-פרונד","k":"עורך כנסת חכמים","bt":"תרמג","dt":"תשד","b":"תלמיד זקנו ר משה פאנט מדעש. חתן הגביר ר נפתלי חיים הולנדר מליזנסק, ועבר לשם. חזר לבורגו-פרונד והתכתב עם גדולי דורו. גבאי ישיבת \"אהל משה\" בירושלים. הו\"ל כתב עת תורני - \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה. רב בבורגו-פרונד(=בארגאפרונד)-תרעג על מקום אביו."},{"i":39327,"n":"פרידלנדר, אלעזר בינוש","f":"יהושע פאלק","bt":"תרנא","bp":"ראדוילישוק","b":"תלמיד ישיבת סלובודקא, מאלטש, מיר. נסמך מאת: ר ברוך קאמאי ממיר, ר אליעזר יהודה פינקל ממיר, הרב קרקובסקי מוילנא, הרב אבוביץ מנוברדוק. חתן הגביר ר יעקב מאסלאוואטער מנוברדוק. ממיסדי ישיבת \"אהל תורה\" בנוברדוק עם הרב אבוביץ וכיהן כר\"מ בישיבה. היגר לארה\"ב-תרפד, וכיהן כרב קהלת \"בית ישראל\" בבולטימור, \"אגודת אחים\", \"שערי צדק\", וממיסדי ישיבת \"נר ישראל\" בבולטימור. חיבר ספרים בהלכה - בכת\"י."},{"i":39328,"n":"פרידלנדר, דוד יאחים","f":"קניגסברג","bt":"תקל","b":"למד פילוסופיה אצל עמנואל קנט, רפואה. רופא בברודי. חיבר ספרים ברפואה."},{"i":39329,"n":"פרידלנדר, דוד ליב מלאפוש","f":"משה מקלינורדין","bt":"תקצג","bp":"קלינורדין","dt":"תר.. -טז ניסן","b":"תלמיד מהרם שיק. מראשי הקהל בלאפוש-תרך. אביו של ר יהודה אב\"ד בורגו-פרונד, ואחיו של האדמור ר חיים פרידלנדר מליסקא בעל \"טל חיים\"."},{"i":39330,"n":"פרידלנדר, דוד מברלין","f":"חיים ליב","bt":"תקיא","bp":"קניגסברג","dt":"תקצד","b":"חתן ר דניאל יפה-ראש הקהל בברלין, וגיסו וחברו של ר יצחק איצק, מקורב למשה מנדלסון. היה גם במיטאוי-קורלנד. סייעו בהדפסת \"מצפה יקותיאל\" - שהפצתו נאסרה בידי ביה\"ד באה\"ו - שם כיהן ר רפאל הכהן שכנגדו פנה הספר, הכחיש יחד עם גיסו - כי ר צבי הירש רבה של ברלין הצטרף למחרימים אותם."},{"i":39331,"n":"פרידלנדר, זלמן ליב","f":"פרידמן, שלמה יהודה","b":"רב בבאלחוב-תר\"ס"},{"i":39332,"n":"פרידלנדר, חיים","f":"נתן פרידלנדר","dt":"תסו"},{"i":39333,"n":"פרידלנדר, חיים מבוליחוב","f":"אהרן מאיר מבוליחוב","b":"מחכמי בוליחוב."},{"i":39334,"n":"פרידלנדר, חיים מליסקא","f":"משה מקלינורדין","k":"אדמור מליסקא","bt":"תר","dt":"תרסד - ט אייר","b":"חתן ר צבי הירש פרידמן האדמור מליסקא. רב ואדמור בליסקא(=אולס-ליסקא) על מקום חותנו. חיבר\"טל חיים וברכה\", ועוד. חתנו - ר אהרן אויש מלופעני."},{"i":39335,"n":"פרידלנדר, חנוך הניך (הנדל)","f":"משה מרדכי","k":"בעל דברי חנוך","bt":"תרי","bp":"סמילוביץ-פלך מינסק","dt":"תרעג - ב חשון","b":"מצאצאי ר יצחק אברהם גינצבורג מסמילוביץ-אחיו של בעל \"שאגת אריה\". תלמיד ישיבת וולוזין וכונה בשם \"העילוי מסימילוביץ\", תלמיד ר יוסף דב סולוביציק בסלוצק, ר יהושע ליב דיסקין בשקלוב. חתן אחות ר גרשון תנחום ממינסק, ובזיוו\"ש חתן בת למשפחת ר משה פינס (גיסו - ר זלמן פינס מסויסלאויטש) ממינסק ונכדת ר יעקב מקרלין בעל \"משכנות יעקב\" - כנראה ר דב בער שהיה גביר במינסק. רב בלאפיטש-פלך מינסק-תרם, אב\"ד פאריטש(=פאריץ)-פלך מינסק-תרנה, ראש ישיבה במינסק, ממקורבי הגדול ממינסק. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"הפלס\" - ברלין תרסא-תרסה, \"תורה מציון\" - ירושלים תרנה-תרסה. נסמך מאת: ר ירוחם יהודה פרלמן \"הגדול ממינסק\", ר יוסף דב סולוביציק, ר ראובן מדוינסק. חיבר גם \"דברי דודים\", \"תולדות חנוך\", ועוד."},{"i":39336,"n":"פרידלנדר, יהודה אריה","f":"נחמן","k":"בעל בית יהודה","b":"עבר מרומניה לגרמניה-תרמד. חיבר פירוש \"בית יהודה\" על הירושלמי - מגנצא תרמה. יתכן והא שלמה יהודה בן מנחם - שהו\"ל את הירושלמי קדשים החשוד כזיוף. חיבר \"איילת השחר\" שירים לשבת - בכת\"י, והקדישם לר מאיר להמן ממגנצא."},{"i":39337,"n":"פרידלנדר, יהודה ליב ממילהויזן","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":39338,"n":"פרידלנדר, יהודה מבוקין","f":"חיים פרידלנדר","dt":"תשד","b":"רב בבוקין(=באקאני)-תרעג. חתנו - ר מרדכי דוד הכהן פריד מקאפיש."},{"i":39339,"n":"פרידלנדר, יהודה מבורגו-פרונד","f":"דוד ליב מלאפוש","bt":"תרכו","bp":"לאפוש","dt":"תרעג - ז אדר","b":"תלמיד ר מנחם מנדל פאנט מדעש, בעל \"ייטב לב\" מסיגט, ודודו ר חיים פרידלנדר האדמור מליסקא. חתן ר משה פאנט מדעש, רב בנימוזשא(=נימיז'ה)-תרמד על מקום חותנו שעבר לדעש. רבה הראשון של בורגו-פרונד-ליד ביסטריץ-תרמה. (יתכן ושנת פטירתו תרעט)."},{"i":39340,"n":"פרידלנדר, יהושע פאלק","b":"רב-שנת תר\"ס"},{"i":39341,"n":"פרידלנדר, יואל מלונדון","f":"מאיר","k":"בעל ברכות ה'","bt":"תרלא","b":"תלמיד ביהמ\"ד לרבנים בהנובר, ביהמ\"ד לרבנים בלונדון, בעל תואר ד\"ר. רב ומטיף בלונדון-תרנו. פרסם מאמרים וחיבר ספרים ובהם \"ברכות ה'\", \"מקור התפילות\"."},{"i":39342,"n":"פרידלנדר, יוזפא מליסקא","f":"צבי הירש מליסקא","k":"אדמור מליסקא ארה\"ב","bt":"תרעח","dt":"תשלא - כח שבט","b":"חתן ר אברהם יהושע השל האדמור מלובלין-נכדו של החוזה מלובלין. ניצל מהשואה ואחריה היגר לארה\"ב-תשז וכיהן כאדמור מליסקא בארה\"ב.","bk":[["צבי וחמיד - עה\"ת מועדים וש\"ס",""]]},{"i":39343,"n":"פרידלנדר, יעקב מאיר צבי משוראן","k":"בעל דרך ימה","bp":"בוניהאד","dt":"תרח - יא חשון","b":"דיין בבוניהאד(=בניהאד), שוראן-תקץ. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. נשא ונתן עם החת\"ס. מחדושיו נדפס ע\"י נכדו (בן בתו) ר שאול בראך מקאשוי - \"דרך ימה - הבה תמים\". בנו - ר שמואל."},{"i":39344,"n":"פרידלנדר, מנחם","k":"בעל דברי נחומים","b":"רב באטאד,קאווגרש,פילפץ,דיורדי-תר\"כ"},{"i":39345,"n":"פרידלנדר, מנחם ממארגרטן","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":39346,"n":"פרידלנדר, מנחם מנדל מבורגו-פרו","f":"יהודה מבורגו-פרונד","k":"אדמור מקלויזנבורג","bt":"תרמז","dt":"תש - יח טבת","dp":"גרוסורדין","b":"נכד - מצד אמו - בעל \"ייטב לב\" מסיגט. חתן דודו ר חיים פרידלנדר האדמור מליסקא. אדמור מבורגו-פרונד-תרעג בקלויזנבורג לאחר פטירת אביו, עבר לגרוסורדין וישב בבית מדרש \"טל חיים\" ע\"ש חותנו."},{"i":39347,"n":"פרידלנדר, מנחם מנדל מיערגין","dt":"תרמה - בערך","b":"תלמיד החת\"ס. גיסו של ר מרדכי יהודה גליק מיאהאנא. רב בסנט-יערגין-תקצח. מראשי אסיפת הרבנים בפאקש-תרד."},{"i":39348,"n":"פרידלנדר, מנחם מנדל מסטרי","f":"יעקב הכהן","dt":"תרלח","b":"מחכמי סטרי."},{"i":39349,"n":"פרידלנדר, מנחם מנדל מסערט","f":"יצחק איזיק","dt":"תש..","b":"לאחר שנתייתם גדל אצל זקנו ר פנחס הורביץ בעל \"פתחא זוטא\" בגרוסורדין. תלמיד ישיבת ר אליעזר הגר בויזניץ. חתן ר ברוך אברהם בינדיגר מדעש. ר\"מ בישיבת ר ברוך הגר בסערט, ברח לדעש-תש והיה מגיד שם. נספה בשואה."},{"i":39350,"n":"פרידלנדר, מרדכי צבי","b":"פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרכה."},{"i":39351,"n":"פרידלנדר, משה","dt":"תרו","b":"דומ\"צ בקליינוורדיין"},{"i":39352,"n":"פרידלנדר, משה דוד מבורגו-פרונד","f":"מנחם מנדל מבורגו-פרו","k":"אדמור מליסקא נ\"י","dt":"תשמג - כט כסלו","b":"מצאצאי אדמורי ליסקא. אדמור מליסקא בניו יורק."},{"i":39353,"n":"פרידלנדר, משה מבורגו-פרונד","f":"אלימלך מבורגו-פרונד","dt":"תשד - סיון","b":"חתן ר משה ישראל פלדמן מדראגמירשט. רב לצד אביו בבורגו-פרונד(=ברגפרונד). נספה בשואה."},{"i":39354,"n":"פרידלנדר, משה מטנקה","b":"רב בטנקה-תרנט."},{"i":39355,"n":"פרידלנדר, צבי הירש מליסקא","f":"חיים מליסקא","k":"אדמור מליסקא","bt":"תרלד","dt":"תשד - כז אייר","dp":"אושוויץ","b":"חתן הגביר ר יצחק איזיק ממאדע. רב במאד, גאווא, אדמור בליסקא על מקום אביו (חלק מהחסידות עבר לקרסטור(=קרסטיר) עם תלמיד אביו - האדמור ר ישעיה שטינר), הועבר ע\"י הנאצים לאויהל, סירב לעזוב את חסידיו ולברוח. נספה בשואה. חיבר \"שערי הישר\". בניו: ר שמעון, ר חיים, ר אברהם - נספו בשואה עם בני משפחתם. ?? לא באוצר - הספר קיים ??","bk":[["שארית ליהודה",""],["שערי הישר - תהלים",""]]},{"i":39356,"n":"פרידלנדר, צבי הירש מליסקא","f":"יוזפא מליסקא","k":"אדמור מליסקא נ\"י","b":"אדמור מליסקא בנ\"י על מקום אביו."},{"i":39357,"n":"פרידלנדר, שלמה טוביה הלוי","f":"שלמה טוביה הלוי משצו","k":"בעל תפארת שלמה","bt":"תרכד","bp":"שצוצין-פלך לומז'א","b":"תלמיד ישיבות איישישוק, וולוזין. רב בראטנא-ווהלין-תרסג. חיבר \"תפארת שלמה\" וארשא תרסג, חדושים ופסקים - בכת\"י."},{"i":39358,"n":"פרידלנדר, שלמה יהודה","f":"מנחם","k":"ירושלמי זרעים-תרסה","bt":"תרך","bp":"ויטסבק או בישנקוביץ-רוסיה","dt":"תרפד - ח שבט","dp":"סטמר","b":"תלמיד ישיבת וולוזין-תרלב. רב במילהויזן-אלזס-[תרמ..], עבר להונגריה והתישב בוייצען והתחבר לר ישעיה זילברשטין בוייצען. עבר לסטמר ונודע כחכם ולמדן, וההדיר התוספתא עם פירוש ממנו. החל להדפיס ירושלמי על זרעים מתוך כת\"י שמצא לטענתו בקושטא, וקיבל הסכמות מרבנים וחוקרים חשובים - ובהם ר חיים סולוביציק מבריסק, לאחר שנדפס נתעורר חשדם של רבנים וחוקרים שזהו זיוף, ועל כך יצאו קונטרסים ומאמרים שונים, והדעה המקובלת היתה שאכן זייף את ספרו.","bk":[["מבוא לתוספתא",""],["תוספתא חשק שלמה",""]]},{"i":39359,"n":"פרידלנדר, שלמה יהודה מפשוורסק","f":"אהרן מאיר","k":"בעל אמרי מהרזל","bt":"תרל","dt":"תרפא","b":"רב בפשוורסק, בוליחוב על מקום אביו. חתן ר פנחס חיים הורביץ בעל \"פתחא זוטא\". חיבר \"אמרי מהרז\"ל\" גרוסורדין תרפח."},{"i":39360,"n":"פרידלנדר, שלמה ליב","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":39361,"n":"פרידלנדר, שלמה מליסקא","f":"צבי הירש מליסקא","k":"בעל אהבת שלמה","dt":"תשם - א טבת","b":"נינו של ר צבי הירש פרידמן האדמור מליסקא. ניצל מהשואה, ואחריה היגר מבודפשט לארה\"ב. חיבר \"אהבת שלמה\" נדפס בתוך \"אך פרי תבואה\" - תשכא.","bk":[["אהבת שלמה (נדפס בתוך ספר אך פרי תבואה)",""]]},{"i":39362,"n":"פרידלנדר, שמואל","f":"יעקב מאיר משוראן","b":"חתנו - ר דוד צבי ארנפלד בן החתן סופר."},{"i":39363,"n":"פרידלנדר, שמואל מניו אורליאנס","b":"דיין בניו אורליאנס-תרכג, אצל ר ישכר דב אילאווי, יחד עם הדיין ר אברהם לעהמן."},{"i":39364,"n":"פרידלנדר, שמעון","dt":"תשד","b":"רב בליסקא"},{"i":39365,"n":"פרידלנסקי, משה אריה ליב מפטרבו","f":"משלם פיבש","k":"הו\"ל קהלת משה","b":"חתן ר אריה ליב גינצבורג מוילנא-נפטר תרכה (שהיה חתן ר יוסף זקהיים מוילנא) גביר בפטרבורג. אסף ספרים עבריים ותרם את האוסף למוזיאון האסיאתי בפטרבורג. רשימת ספריו נדפסה בשם \"קהילת משה\" - פטרבורג תרנג. שלח שליח מיוחד לאסוף זכרונות לתולדות משפחת אשתו-מצד אמה - זקהיים - נדפס בשם \"דעת קדושים\" - פטרבורג תרנח."},{"i":39366,"n":"פרידלר, אברהם","k":"בעל זעקת שבר","b":"שנת תק\"צ"},{"i":39367,"n":"פרידלר, נפתלי","b":"פרסם מאמרים ב\"קול תורה\" - גייטסהד תשז."},{"i":39368,"n":"פרידמן דב אריה","bt":"1844","dt":"ה'תרפ 1920","bk":[["דרך אמונה",""],["תולדות ישרון",""]]},{"i":39369,"n":"פרידמן מאיר","bt":"1831","dt":"ה'תרסח 1908","bk":[["ארבעה גידולין שאסרו חכמים",""],["ברייתא דמלאכת המשכן",""],["דבר",""],["המשנה",""],["מאיר עין",""],["נספחים לסדר אליהו זוטא",""],["ספרי עם תוספות מאיר עין",""],["פסיקתא רבתי",""]]},{"i":39370,"n":"פרידמן, אברהם","f":"יעקב שלמה מפשמישל","bt":"תרלא","b":"למד אצל אחיו ר יחיאל דב לאחר שנתייתם בילדותו. חתן הגביר ר ישראל טאג (ראש העיר בדינוב). חסיד בלוזוב. נספה בשואה."},{"i":39371,"n":"פרידמן, אברהם אליהו","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39372,"n":"פרידמן, אברהם דב הכהן מטרווה","b":"רב בטרווא-תרצז."},{"i":39373,"n":"פרידמן, אברהם חנוך מסטמר","f":"צבי יהודה - חתן החתס","bt":"תרכו-לה","bp":"טאפלאטשן","dt":"תשד - יב סיון","dp":"אושוויץ","b":"מכונה גם גרינוולד. נכד החת\"ס. לאחר שנתייתם גדל אצל דודו ר יוספא סופר - בן החת\"ס ולאחר שר יוספא נהרג עבר לדודו ר יהודה גרינוולד. תלמיד השב\"ס, ודודו שאצלו גדל. חתן דודו ר יוסף צבי גרינולד - אחיו התאום של רבו. דיין בסטמר-תרסה אצל דודו ר יהודה גרינוולד. נספה בשואה. הו\"ל ספרי רבו ודודו ר יהודה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. בנו ר יהושע פאלק - דיין בקאשוי."},{"i":39374,"n":"פרידמן, אברהם יהושע השל מאדזד","f":"יצחק מבוהוש","k":"אדמור מאדז'אד","bt":"תרכא","dt":"תש - טו אלול","b":"חתן דודו זקנו ר מנחם נחום משטפינשט, ובזיוו\"ש חתן ר זלמן הורנשטין. רב ואדמור באדזאד ובגאלאץ-תרס."},{"i":39375,"n":"פרידמן, אברהם יעקב מבויאן-לבוב","f":"יצחק מבויאן-פחד יצחק","k":"אדמור מבויאן-ללוב","bt":"תרמד","dt":"תשב - ב אלול","dp":"לבוב","b":"חתן ר אהרן שור מברדיטשוב, ובזיוו\"ש חתן ר מרדכי טברסקי האדמור מלויאב. אדמור מבויאן בלמברג על מקום אביו. ביקר בארץ-תרצג והדליק את המדורה בלג בעומר במירון. נספה בשואה. היה חשוך ילדים. חיבר \"נחלת יעקב\" ירושלים תשלג.","bk":[["נחלת יעקב",""]]},{"i":39376,"n":"פרידמן, אברהם יעקב מסדיגורא","f":"מרדכי שלום יוסף","k":"אדמור מסדיגורא ב\"ב","bt":"תרפח","b":"חתן ר יוסף אריה פלדמן. רב בניו יורק, עלה לארץ-תשלג. ראש ישיבת רוזין בבני ברק. אדמור מסדיגורא בתל אביב - בני ברק-תשלט על מקום אביו. חיבר \"עקבי אבירים\" תל אביב תשמד, ועוד."},{"i":39377,"n":"פרידמן, אברהם יעקב מסדיגורא א","f":"ישראל מרוזין","k":"אדמור מסדיגורא","r":"אדמו\"ר הראשון מסדיגורא","bt":"תקף","dt":"תרמג - יא אלול","b":"מגדולי האדמורים בדורו. חתן ר יוסף דוד מאליק, ובזיוו\"ש חתן ר אהרן בן אשר מקרלין, ובזיוו\"ש חתן אחיו ר מנחם נחום משטפינטש. אדמור בסדיגורא-תריא על מקום אביו. נאסר-תרטז בגלל הלשנה. מחשובי האדמורים בדורו. בנו ר ישראל על מקומו אחריו בסדיגורא. מתורתו נדפס \"אמת ליעקב\" בתוך \"אור פני צדיקים\" ע\"י ר ירמיה הלמן - זיטומיר תרסב. נספד ב\"אבל כבד\" לר נחום בער - טשרנוביץ תרמג.","bk":[["אמת ליעקב",""]]},{"i":39378,"n":"פרידמן, אברהם יעקב מסדיגורא ב","f":"ישראל מסדיגורא","k":"אדמור מסדיגורא-וינה","r":"אדמו\"ר מסדיגורא","bt":"תרמד","bp":"סדיגורא","dt":"תשכא- כח כסלו","dp":"תל אביב","b":"חתן ר יצחק מאיר השל מקופיטשיניץ. אדמור בסדיגורא על מקום אביו (54 שנה). עבר לוינה אחר מלחמת העולם הראשונה. ניצל מהשואה ועלה לארץ-תרצח, והתגורר בתל אביב - קיבל על עצמו לטאטא את אדמת ארץ ישראל, אחר שאולץ ע\"י הנאצים לטאטא את רחובות וינה. חיבר \"אביר יעקב\" ירושלים תשנח. לתולדותיו \"אביר המלכות\" לר אריה בקנרוט - ירושלים תשסד. פרסם מאמרים ב\"כנסת מרדכי\" - פרמישלא תרצח.","bk":[["אביר יעקב",""],["עקבי אבירים – עה\"ת ומועדים",""]]},{"i":39379,"n":"פרידמן, אברהם יעקב מקראקא","f":"זאב וולף מדזיקוב","k":"בעל איזוב","bt":"תרן","bp":"דזיקוב","dt":"תשכה","dp":"תל אביב","b":"חסיד צורטקוב. עבר מקראקא לבלגיה וניצל מהשואה. חתן ר יחיאל מיכל ברעניג מניישטט, ובזיוו\"ש חתן ר אפרים אהרן מנוביטנץ נכד הישמח משה. עלה לארץ והיה חבר הרבנות הראשית בתל אביב. חיבר \"איזוב\" תל אביב תשיג."},{"i":39380,"n":"פרידמן, אברהם יצחק מדעווא ונ\"י","k":"בעל מצבת זכרון-תשא","b":"מחכמי דעווא-רומניה. עורך הירחון \"הבחור\" - דעווא תרפח. פרסם מאמרי פולמוס כנגד ר יוסף שמעון פאלקמסטמר עורך \"בית ועד לחכמים\" שהיה מחלוקת ביניהם. הדפיס בדפוס צילום \"ראשית בכורי קציר\" - ונציה תעה."},{"i":39381,"n":"פרידמן, אברהם מכפר מיקולה","f":"דב בער","k":"בעל לקוטי שושנים-תרפ","bt":"תר","dt":"תרע","b":"תלמיד ישיבת ר בנימין זאב מנדלבוים בסטמר, אצל ר יהודה אסאד, והכת\"ס. מחכמי כפר מיקולה-ליד סטמר, עסק בחקלאות והיה רב לא רשמי. ?? לא באוצר ??"},{"i":39382,"n":"פרידמן, אברהם מקובנא","f":"יצחק דוד מניישטט","k":"בעל בית אברהם","bt":"תרכב","b":"תלמיד ר ישראל איסר שפירא ממזריטש, ישיבת וולוזין. ר\"מ בישיבה בווילקי-תרמט, מו\"צ בקובנא-תרנב, רב בלוגנסק(=ענגלעס)-תרנד, לוהנסק-פלך יקטרינסלב-תרנז. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא, ר יעקב חריף מוילנא, ר רפאל שפירא מוולוזין. חיבר שו\"ת \"בית אברהם\" וחדושים - בכת\"י."},{"i":39383,"n":"פרידמן, אברהם משטרסניץ","b":"חתן ר שלמה דייטש. רב בשטרסניץ. חתנו ר שמואל יפה שלזינגר."},{"i":39384,"n":"פרידמן, אברהם משימאנדא","bt":"תקעא - בערך","dt":"תרלט - כד תמוז","b":"רב בשימאנדא-ליד אראד-תקצד. רב בקרלסבורג (ובהשפעתו הפכה לקהילת סטטוס-קוו) והרב הכולל האחרון (אחריו בטל התפקיד) בטרנסילבניה-תרה - בתמיכת הניאולוגים והשלטונות, והיה מחלוקת על כך עם החרדים, וכשנבחר ר הלל ליכטנשטין לרבה הראשון של קלויזנבורג - ביטל הרב פרידמן את המינוי ור הלל נאלץ לחזור למארגרטן. פעל בוינה כנגד ערים שאסרו התישבות יהודים בהם - וביניהם קלויזנבורג-תריא, עניעד. נזכר בחת\"ס שאסר עליו להתיר יבמה הזקוקה לחליצת קטן-תקצד."},{"i":39385,"n":"פרידמן, אברהם מתתיהו משטפנשט","f":"מנחם נחום משטפנשט","k":"אדמור משטפינשט","bt":"תרח","dt":"תרצג - כא תמוז","dp":"שטפינשט-תל אביב","b":"חתן ר יחיאל מיכל מקולבסוב-בן ר אשר ישעיהו מרופשיץ וחתנו של ר יצחק רייך. ובזיוו\"ש חתן דודו ר יוסף מונסון, ובזיוו\"ש חתן ר אהרן שור מברדיטשוב. אדמור בשטפנשט על מקום אביו-תרכט. מגדולי האדמורים ברומניה. נפטר ללא ילדים. לתולדותיו \"מחולל הפלאות משטפנשט\" לר אברהם יעקב סלומון."},{"i":39386,"n":"פרידמן, אברהם צבי הירש","f":"אשר למיל מזבורוב","b":"רב בברדיוב והמהרשם הביאו לעמוד בראש הישיבה בצאנז."},{"i":39387,"n":"פרידמן, אברהם צבי יהודה","k":"הרשלה קרשיבר","bp":"קרשוב","b":"רב בשיניבה, צשינוב."},{"i":39388,"n":"פרידמן, אברהם קלונימוס מטורנא","f":"דוד סודיטץ","dt":"תרסו - כב תשרי","b":"תלמיד ר שמלקא קליין מסעליש. דיין ורב בכפר ניר מעדיאש, טורנא-ליד סטמר."},{"i":39389,"n":"פרידמן, אברהם שלום ירוחם מטורץ","f":"משה זאב","bp":"ליסקא-הונגריה","dt":"תשד","b":"תלמיד ר יהודה גרינוולד בסטמר. מלמד בטשאנד ודיין וראש חסידי סיגט בטשאנד, רבה האחרון של טורץ-ליד סטמר - אחרי תרעח. נספה בשואה."},{"i":39390,"n":"פרידמן, אהרן אורי מנאדאש","f":"ברוך פרידמן","b":"רב בנאדאש-תק\"ס"},{"i":39391,"n":"פרידמן, אהרן מבויאן צ'רנוביץ","f":"מנחם נחום מבויאן","k":"אדמור מבויאן","bt":"תרן","dt":"תשב - יד חשון","dp":"טרנסיסטריה","b":"נכד ר יצחק מבויאן. אדמור מבויאן בטשרנוביץ על מקום אביו-תרצו. חתן ר חיים הגר מאטיניא, ובזיוו\"ש חתן ר ישראל מויזניץ. נספה בשואה. חיבר \"תולדות אהרן\" ירושלים תשד."},{"i":39392,"n":"פרידמן, אהרן מברלין","k":"בעל שיר לשלמה","bt":"1855","bp":"שאקי","dt":"1936","dp":"ברלין","b":"למד מוסיקה אצל ליבנדובסקי, ובברלין. חזן בברלין-1882 עד 1932. קיבל תואר \"מנהל מלכותי של מוסיקה\" מהשלטון הגרמני. חיבר ספרים בגרמנית על שירה וחזנות, ובהם \"ספר זכרון לבית הכנסת הישן של ברלין\", ועוד."},{"i":39393,"n":"פרידמן, אהרן מהוסיאטין","f":"שלום יוסף","b":"רב בהוסיאטין"},{"i":39394,"n":"פרידמן, אהרן מניו יורק","k":"בעל חכמת הנפש","b":"רב בניו יורק-תרסט. ?? לבדוק אם אין באוצר בלבול בין שני אנשים עם אותו השם ??"},{"i":39395,"n":"פרידמן, אהרן מסדיגורא","f":"ישראל מסדיגורא","k":"אדמור מסדיגורא","r":"האדמו\"ר מסדיגורא","bt":"תרלז","dt":"תרעג - יט תשרי","b":"חתן ר שלום יוסף מהוסיאטין. אדמור בסדיגורא על מקום אביו-תרסז, בנו ר מרדכי שלום יוסף על מקומו אחריו. חיבר \"קדושת אהרן\" וארשא תרעג. חיבר ניגונים. פרסם מאמרים ב\"כנסת מרדכי\" - פרמישלא תרצח.","bk":[["קדושת אהרן - על התורה",""]]},{"i":39396,"n":"פרידמן, אהרן משאקי","b":"רב בשאקי."},{"i":39397,"n":"פרידמן, אהרן משה ממילניצא","f":"שלום יוסף ממילניצה","k":"אדמור ממילניצא","dt":"תש..","b":"לאחר שנתייתם גדל אצל קרובו ר משה מבויאן בקראקא. חתן ר שמואל פנחס שפירא מלודז-בלנדוב(שושלת קוזניץ). אדמור ממילניצא על מקום אביו - לאחר שאחיו ר יעקב סירב לאדמורות. נספה בשואה."},{"i":39398,"n":"פרידמן, אהרן מתתיהו","f":"אברהם יהושע השל","bt":"תרנב","bp":"אדז'וד","dt":"תרעז","b":"אחיו של ר מנחם נחום מאיצקן. התגורר בפשקאן, טשרנוביץ. פנה להשכלה ופרסם מאמרים בעברית, אידיש ורומנית. נפטר צעיר, הניח כתבים ובהם \"דער רבי ר בער\" - על קרוב משפחתו - בנו של ר ישראל מרוזין, לאחר פטירתו שרפו בני משפחתו את כתביו."},{"i":39399,"n":"פרידמן, אהרן צבי מניו יורק","k":"בעל טוב טעם","b":"רב בניו יורק-תרלה. חיבר גם \"לווית חן\"."},{"i":39400,"n":"פרידמן, אורי ליפמן הכהן מפרידר","f":"שלום","bp":"פוסוואל","b":"תלמיד ר יהודה ליב מפוסוואל, בזיוו\"ש חתן ר יוסף שו\"ב מנייריא, ועבר לשם. רב מטעם בפרידריכשטט(=נייריא). בניו - ר יחזזקאל ראובן, ר אברהם שו\"ב, ר אליהו, ר יחיאל מדאגקרוי, ר בצלאל מאיר רגנשבורג מנייריא."},{"i":39401,"n":"פרידמן, אליהו צבי ה' מויליצקה","f":"אברהם מויליצקה","dt":"תרעד","b":"גביר ונדבן חסיד שיניבה. חתן ר מרדכי הירשפלד מקראקא."},{"i":39402,"n":"פרידמן, אליעזר אליהו","f":"בנימין מטרוקי","k":"בעל בית ארזים","bt":"1858","bp":"קאלם","dt":"1936","dp":"תל אביב","b":"תלמיד ישיבת וילון, יורבורג, קלם. מקורב לרש\"י פין, קלמן שולמן, ולראשוני חובבי ציון בוילנא. פרסם ב\"המגיד\" ו\"המליץ\". יסד עם י.ל. גולדברג את \"אוהבי ציון\". חבר ב\"בני משה\". עסק במסחר בקיוב וסוכן של ל. ברודסקי. עבר לוארשא והיה פעיל ציוני. בימי משפט בייליס עזר לרב ישעיהו מאז\"ה ולסופר י. יזראלסון בסנגוריה. חזר לקובנא-1921 והו\"ל \"הצופה\". עלה לארץ-1925 וחזר לליטא ושב לארץ-1934. חיבר גם \"הציונות והעם\", ועוד."},{"i":39403,"n":"פרידמן, אלכסנדר זושא מוארשא","k":"בעל מעיינה של תורה","r":"נעקה\"ש בשואה הארורה","bt":"תרנז","bp":"סוכטשוב","dt":"תשג-ד","dp":"ליד לובלין","b":"רב וסופר בוארשא, מזכ\"ל אגודת ישראל-תרפה. מייסד \"דגלנו\" - בטאון אגודת ישראל, פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח. נספה בשואה.","bk":[["מעינה של תורה – עה\"ת",""]]},{"i":39404,"n":"פרידמן, אלתר שלמה מאיר מצפת","k":"בעל בית שלמה","b":"מכונה טשערמיריוויצער. מחכמי צפת, חסיד ר דוד משה מצורטקוב. חתנו - ר עמרם בלוי מירושלים - הזקן."},{"i":39405,"n":"פרידמן, אפרים מטימשוואר","f":"מרדכי מטיסא-נאנא","k":"בעל ילקוט אפרים-תרסה","bt":"תרמז","bp":"טיסא-נאנא","dt":"תשך - א ניסן","dp":"בני ברק","b":"תלמיד השב\"ס, ור ישעיה זילברשטין מוויצען, ור יהודה אלטמן במעזא-טשאט. חתן ר יוס שטרנברג מבודפשט. עסקן בטימישואר, מראשי הקהלה האורטודוכסית בפאבריק-שטאדט. עבר לגרוסורדין-תרצח, ניצל מהשואה ואחריה היה מראשי אגודת ישראל ברומניה. עלה לארץ והתישב בבני ברק."},{"i":39406,"n":"פרידמן, אפרים מלבוב","f":"שלום","b":"דיין בלבוב(מחוץ לעיר)-תטו בזמן הט\"ז שחתם עמו-תכא ועם ר יהודה אברהם הלוי, ר ישעיה בן סנדר כץ. חתם-תטו עם ר אברהם גראפין מלבוב, ועוד. בנו - כנראה ר שלום מאוסטרהא-נפטר תעו."},{"i":39407,"n":"פרידמן, אפרים ממארוש-ואשארהי","f":"אברהם","k":"בעל עבודת שיר-תרצט","dt":"תש..","b":"מזכיר הקהלה האורטודוכסית במארוש-ואשארהי. נספה בשואה. חיבר גם \"הדרת קדש\" גרוסורדין תשב."},{"i":39408,"n":"פרידמן, אריה ליב מפרשבורג","b":"ראב\"ד ומגיד שיעור בפרשבורג-תר\"ס"},{"i":39409,"n":"פרידמן, אריה מדעש","b":"תלמיד ישיבת דעש ועורך כתב העת \"האורה\" - דעש תרפט, בתמיכת האדמור ר יעקב אלימלך פנט מדעש."},{"i":39410,"n":"פרידמן, אריה מניר-באטור","b":"חתן בן גיסו של מהר\"ם א\"ש. מחכמי ניר-באטור."},{"i":39411,"n":"פרידמן, בן ציון הכהן מדובצק","dt":"תרפט - בערך","b":"חסיד בלוזוב, רב בדובצק, אחיו ר יעקב מחשובי חסידי בלז בדובצק. אמו היתה הצדקת גיטשיס שהיתה לובשת ציצית."},{"i":39412,"n":"פרידמן, בן ציון מאושמור","f":"יהושע","k":"בעל רבבות אפרים","bt":"תרכ","b":"מצאצאי השל\"ה. רב באושמור-ווהלין-תרמו. חיבר גם \"דרישת ציון\", \"אגודת ציון\" - קובץ שו\"ת עם ביאורים ממנו."},{"i":39413,"n":"פרידמן, בן ציון מפיקאלן","b":"רב בפיקאלן-תרמח על מקום גיסו ר יעקב וילנציק בעל \"דלתי תשובה\"."},{"i":39414,"n":"פרידמן, בנימין מטרוקי","k":"העילוי מראסיין","bt":"תקצט","bp":"ראסיין","dt":"תרעח - ז סיון","dp":"וילנא","b":"חתן ר יצחק איזיק מקלם. רב בטרוקי-תרכה, מו\"צ באנטוקולי-ליד וילנא. בנו העסקן והסופר ר אליעזר אליהו פרידמן בעל \"בית ארזים\"."},{"i":39415,"n":"פרידמן, בצלאל מארה\"ב","f":"יוסף","bp":"ניו יורק","b":"תלמיד ישיבת רבי יצחק אלחנן בניו יורק. נסמך מאת: הרב ד\"ר הלל קליין, הרב ד\"ר דב רבל, ר משה זבולון מרגליות, ר שלום אלחנן יפה (הראשון מילידי אמריקה שנסמך בישיבה). רב קהלת \"פועלי צדק\" בפיטסבורג-תרף, רב בוושינגטון הייטס בניו יורק-תרצב, חבר אגודת הרבנים באמריקה, ותנועת אגודת ישראל ונציגה באו\"ם. בעל השכלה כעו\"ד, עסקן ציבור."},{"i":39416,"n":"פרידמן, ברוך","b":"רב בנאדאש-תקמ\"ה"},{"i":39417,"n":"פרידמן, דאנאש מבודפשט","bt":"1926","dt":"תשד","b":"רב ניאולוגי ראשי בבודפשט. חיבר מאמרים בנושאים יהודיים בהונגרית ובגרמנית. נספה בשואה. סגנו מור ליכטמן בעל \"חזיונות זכריה\"."},{"i":39418,"n":"פרידמן, דב בר","f":"משה צבי פרידמן"},{"i":39419,"n":"פרידמן, דב בר מליאובה","f":"ישראל מרוזין","k":"אדמור מלעווע","bt":"תקפז","dt":"תרלו - יג כסלו","dp":"סדיגורא","b":"חתן ר מרדכי מטשרנובל. אדמור בהוש, עבר לסקולען, והתישב בלעווע (ליאובה). (היה מקורב למשכילי טשרנוביץ - ועל כך פרצה המחלוקת עם צאנז). בסוף ימיו בחצר אחיו בסדיגורא. ספר עליו - \"רבי דב מליאובה\" לר מתתיהו יחזקאל גוטמן. חיבר \"דובר מישרים\" בני ברק תשמט."},{"i":39420,"n":"פרידמן, דב בר מצורטקוב","f":"ישראל מצורטקוב","bt":"תרמב","bp":"צורטקוב","dt":"תרצו - כד אלול","b":"חתן דודו ר יצחק \"הפחד יצחק\" מבויאן. עבר עם אביו לוינה. סירב לאדמורות שטפנשט. אדמור בוינה על מקום אביו יחד עם אחיו ר נחום מרדכי. מראשי אגודת ישראל. בנו ר דוד משה מלונדון."},{"i":39421,"n":"פרידמן, דוד","f":"יצחק מבוהוש","bt":"תרכד","dt":"תרמט - ה שבט","b":"חתן ראי\"ה השל ממזבוז. בנו ר מנחם מנדל אדמור בבוהוש."},{"i":39422,"n":"פרידמן, דוד יהודה מאוסטרליה","bt":"תרלה","bp":"בודפשט","b":"תלמיד ביהמ\"ד לרבנים בלונדון. רב בפירת-אוסטרליה. הו\"ל עתון \"חכם חרשים\" - באנגלית."},{"i":39423,"n":"פרידמן, דוד מבוהוש","f":"יצחק מבוהוש","k":"אדמור מבוהוש","dt":"תרמה - ה שבט","b":"חתן ר אברהם יהושע השל ממזבוז (אפטא), ובזיוו\"ש חתן ר אפרים זלמן ממאציוב (טשרנוביל). אדמור בבוהוש."},{"i":39424,"n":"פרידמן, דוד מחרסקוב","b":"מחכמי חרסקוב, תלמיד האב\"ד ר צבי הירש תאומים."},{"i":39425,"n":"פרידמן, דוד מנאדש","f":"אהרן אורי פרידמן","dt":"תקפג","b":"רב בנאדאש-תק\"ס"},{"i":39426,"n":"פרידמן, דוד מפלוישט","f":"שלום יוסף משפיקוב","k":"אדמור מפלוישט","bt":"תרנח","dt":"תשא - כז חשון","dp":"רומניה - ארץ ישראל","b":"נכד ר דוד מבוהוש-שפיקוב. חתן ר אהרן מאוזירניץ (שושלת טשרנוביל). אדמור בפלוישט-תרץ. נספה בשואה (נהרג ברומניה)."},{"i":39427,"n":"פרידמן, דוד מצעהלים","f":"ישראל משה מקערט","k":"בעל שלמי דוד","bt":"תריא","bp":"קערט","dt":"תרסו - א אדר","dp":"צעהלים","b":"תלמיד הכת\"ס. ור מנחם פרוסטיץ מצעהלים, חתן רבו ר מנחם פרוסטיץ. רב בצעהלים על מקום חותנו-תרנא ור אליעזר דוד גרינוולד על מקומו אחריו."},{"i":39428,"n":"פרידמן, דוד מקרלין","f":"שמואל","k":"בעל פסקי הלכות","bt":"תקפח","bp":"ביאלא-פולין","dt":"תרע-ה - ד אדר","dp":"קרלין","b":"חתן הגביר ר שמריהו לוריא (צוקרמן) ממוהילוב וחותנו שלחו ללמוד אצל גיסו ר זלמן ריבלין שלימדו בשיטת הגר\"א, ור מנשה מאיליא. רב בקרלין-תרכח כ-50 שנה, ונחשב לזקן ההוראה ומגדולי הדור. חיבר גם \"דרכי ההוראה\", \"עמק ברכה\", ועוד. מראשוני \"חובבי ציון\" והשתתף בועידת קטוביץ, אך התנגד לציונות. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים תרכג. סירב לרבנות מינסק (ונתמנה - הגדול ממינסק). גיסו - ר יחיאל מיכל פינס"},{"i":39429,"n":"פרידמן, דוד משה מצרוטקוב","f":"ישראל מרוזין","k":"אדמור מצורטקוב","r":"אדמו\"ר מטשורטקוב","bt":"תקפח","dt":"תרסד - כא תשרי","b":"חתן ר אהרן מטשרנוביל, ובזיוו\"ש חתן אחיו ר שלום יוסף מסדיגורא. רב ואדמור בפוטיק, צורטקוב-תריט, בנו ר ישראל על מקומו אחריו. מחשובי האדמורים בדורו. חיבר \"דברי דוד\" הוסיאטין תרסד, ועוד. תולדותיו ב\"תפארת אדם\". בנו ר נחום מרדכי - נפטר על פניו.","bk":[["דברי דוד - ליקוטים",""],["דברי דוד (טשורטקוב)",""]]},{"i":39430,"n":"פרידמן, דוד שלמה מלמברג","f":"שמואל","k":"בעל אמרי שפר","b":"רב ודרשן בלמברג. חתן ר שאול מילר. חיבר \"אמרי שפר\" למברג תרפא."},{"i":39431,"n":"פרידמן, הלל מדומבוואר","dt":"תשד","b":"רב הקהלה הניאולוגית בדומבוואר-מחוז טולנא-1929. נספה בשואה."},{"i":39432,"n":"פרידמן, זאב וולף מטרנוב","f":"ישראל יצחק","dt":"תש..","b":"דיין בטרנוב. נספה בשואה."},{"i":39433,"n":"פרידמן, זאב וולף מסטרופקוב","b":"דומ\"צ בסטראפקוב-תרל\"ו"},{"i":39434,"n":"פרידמן, זאב וולף מקראקא","f":"אליהו צבי הירש","bt":"תרלט","dt":"תשב","b":"חתן ר מאיר רפפורט מקראקא. פרנס הקהלה בקראקא. נספה בשואה."},{"i":39435,"n":"פרידמן, זוסיא מאודסה","f":"אהרן","bt":"תרלג","bp":"ברדיטשוב","b":"רב באודסה-תרסב."},{"i":39436,"n":"פרידמן, זלמן יעקב מארה\"ב","f":"ברוך מרדכי","k":"בעל מנחת יעקב","bt":"תרכה","bp":"מאראטש","dt":"תרצח - י טבת","b":"תלמיד ר משה מנאוידואר-פלך וילנא, ר יוסף מבאלטרימאנץ, ר שמואל איסר הכהן בישיבת מייליס בוילנא, ר שבתי ואלאך מרוזנאי, ר יהודה ליפשיץ ממערטש. חתן ר יעקב ליפשיץ מקובנא. חתן ר יעקב ליפשיץ מקובנא. רב בניו יורק-תרנב, בוסטון-תרנג. נסמך מאת: ר יצחק אלחנן מקובנא, ר הלל מאמציסלאו, ר אלכסנדר משה לפידות, ר יצחק שרשבסקי מנישויעז. חיבר גם \"אמת ואמונה\" כנגד המהרסים בדת - ניו יורק תרנה\", \"שושנת יעקב\", ועוד."},{"i":39437,"n":"פרידמן, חיים אהרן","f":"נחום מרדכי","b":"רב-שנת תר\"ע"},{"i":39438,"n":"פרידמן, חיים אהרן מצורטקוב","f":"ישראל מצורטקוב","bt":"תרלג","dt":"תרפו","dp":"וינה","b":"חתן דודו ר נחום מרדכי מצורטקוב, ובזיוו\"ש חתן ר דוד מבוהוש."},{"i":39439,"n":"פרידמן, חיים אורי מקרסטור","dt":"תשד","b":"דומ\"צ בקרסטור(=קרסטיר)-תרפ\"ט"},{"i":39440,"n":"פרידמן, חיים אלתר מסטריזוב","b":"עבר לניו יורק וכיהן כרב - לפני מלחמת העולם הראשונה. תורה ממנו בספר \"פרח לבנון\" לרא\"ל ויסבלום. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":39441,"n":"פרידמן, חיים מדומבראד","f":"יצחק אייזיק מנירדהזא","bt":"תריז","dt":"תרעג - י שבט","b":"רב בדומבראד(=דאמבראד)."},{"i":39442,"n":"פרידמן, חיים ממיקולא","f":"אברהם ממיקולא","dt":"תשב - כד טבת","dp":"גרוסורדין","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן ר יהודה ליב וינברגר מניגרעשט. מחכמי מיקולא."},{"i":39443,"n":"פרידמן, חיים מפריסטיק","f":"שלום יצחק הכהן מצאנז","b":"רב בפריסטיק, ר\"מ בישיבת בובוב ובין תלמידיו - בן האדמור (לימים האדמור מבובוב)."},{"i":39444,"n":"פרידמן, חיים מראחוב","b":"רב בראחוב. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":39445,"n":"פרידמן, חיים נטע","dt":"תשג","b":"רב בטשערוויץ"},{"i":39446,"n":"פרידמן, חיים שלמה מקראקא","f":"אליקים","k":"בעל איך וועל זיי","bt":"תרעג","bp":"קראקא","dt":"תשמו","b":"חסיד ותלמיד ישיבת בלז. ניצל מהשואה וסייע בהצלת האדמור מבלז ועוד יהודים רבים. התישב באנטורפן אחר השואה, עלה לארץ-תשט. ממיסדי ישיבת בלז בירושלים, חזר לאנטורפן-תשיח. חיבר \"איך וועל זיי איבערלעבן\" ירושלים תשמה, מפתקאות שרשם נדפס ע\"י נכדו ר יואל צבי פרידמן - \"בצילא דמהימנותא\" ניו יורק תשס."},{"i":39447,"n":"פרידמן, חנניה יום טוב מראחוב","b":"מחכמי ראחוב, אולי בנו של ר שלמה פרידמן מראחוב."},{"i":39448,"n":"פרידמן, י. מארה\"ב","k":"בעל פרידמאנ'ס מעשה'ל","bt":"1883","bp":"קובנא","b":"היגר לארה\"ב. פרסם מאמרים בעתונים האידיים \"העראלד, אבענד פוסט, מורגן ז'ורנל. \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":39449,"n":"פרידמן, יהודה","b":"מו\"צ בפרוינקירכן-ת\"ר"},{"i":39450,"n":"פרידמן, יהודה ליב מסאבאטיטש","f":"ברוך מפוהרליץ","b":"רב בסאבאטיטש(=סאבאטיש)-תקמז."},{"i":39451,"n":"פרידמן, יהודה ליב מפריישטט","f":"שלום מפריישטט","b":"תלמיד החת\"ס. רב בפריישטט-תקץ על מקום אביו. תשובה אליו ב\"חתם סופר\"."},{"i":39452,"n":"פרידמן, יהודה ליב מפרשבורג","f":"דוד מפרוינקירכן","k":"בעל הריב\"ד","bt":"תרכג","bp":"פרוינקירכן","dt":"תרעט - שבט","b":"תלמיד הרב פשרהופער בפורינקירכן, ר יוסף העניג בנייטרא, ר משה הירש פוקס בסערעד. חתן ר פייש פישמן מפרשבורג. דיין בפרשבורג-תקנג, וראב\"ד ור\"מ בישיבה על מקום ר דוד ניימן. פרסם מאמרים בכתבי עת ומאספים, הניח חדושים ושו\"ת - בכת\"י. גיסו - ר יוסף חיים פישמן מטעלנד."},{"i":39453,"n":"פרידמן, יהודה ליבוש","f":"שלום פרידמן","b":"דומ\"צ בפריישטטל-תר\"ס"},{"i":39454,"n":"פרידמן, יהושע","f":"אליעזר אליהו","k":"בעל מבחר השירה הרומי","bt":"1885","bp":"וילנא","dt":"1934","b":"תלמיד גימנסיה בצ'נסטחוב, למד משפטים בוארשא ופטרבורג, עבר למסוקבה אחר המהפכה, חזר לליטא-1922 והיה מנהל הגימנסיה העברית בוילקוביסק, מנהל הגימנסיה לבנות בקובנא. עלה לארץ-1933. תרגם קטעים מהספרות הרומית."},{"i":39455,"n":"פרידמן, יהושע פאלק מקאשוי","f":"אברהם חנוך מסטמר","k":"בעל זכרון יוסף","dt":"תשד - כט אייר","b":"תלמיד הדעת סופר, ודו\"ז ר יהודה גרינולד מסטמר, ור אליעזר דוד מטסמר. חתן ר שאול בראך מקראלי וקאשוי, ועבר לקראלי, ועבר עם חותנו לקאשוי, וסייע לחותנו בניהול הישיבה. רב ביהמ\"ד בקאשוי-תרפט ודיין שם-תרצז. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39456,"n":"פרידמן, יוסף אליעזר - הזקן","f":"שלמה פריידש משקלוב","b":"רב-שנת ת\"ר"},{"i":39457,"n":"פרידמן, יוסף אליעזר מהודיץ","f":"שמואל בן יוסף אליעזר","k":"בעל שו\"ת","bt":"תרטז","b":"נכד-אבי אמו ר אהרן ליפשיץ מבליניץ. רב בהודיץ(=האדיץ)-פלך פולטובה-תרנד. התכתב עם גדולי דורו וחיבר שו\"ת - בכת\"י."},{"i":39458,"n":"פרידמן, יוסף בן ציון מקובנה","f":"משה יפה משקודוויל","bt":"תריז","bp":"ניישטט-טאווריג","dt":"תרפט","b":"תלמיד ר ישראל סלנטר. חתן ר חיים נתנזון מז'ידיק. ר\"מ בישיבת סלובודקה, וקלויז נביאז'ר בקובנא, ראגולה. ברח לרוסיה בזמן מלחה\"ע ה-I, ואחריה רב בפיקאלן על מקום גיסו ר יעקב וילנציק, ויטבסק (לפי אוצר הרבנים). חיבר חדושים על הש\"ס - בכת\"י."},{"i":39459,"n":"פרידמן, יוסף הכהן מרימנוב","f":"צבי הירש מרימנוב","k":"אדמור מרימנוב","bt":"תרד","dt":"תרעג - כד ניסן","b":"נתייתם בילדותו וגדל אצל ר ישראל מרוזין שנשא את אמו, ואחר אצל ר אברהם יעקב מסדיגורא - משם קיבל את השם פרידמן. חתן נכדת הבעשט. רב ואדמור ברימנוב בהשתדלות האדמור מסדיגורא. חתנו (מבתו היחידה) ר אשר ישעיה הוריבץ מדזיקוב בעל \"מעדני מלך\" על מקומו אחריו, ונכדו ר צבי חיים על מקומו אחריו. מכתב מצורף מאשתו - פריידא."},{"i":39460,"n":"פרידמן, יוסף מאנטורפן","f":"יעקב מברעזאווא","bt":"תרכא","bp":"וערבא","dp":"אנטורפן-פיטע (הולנד)","b":"תלמיד השב\"ס. חתן ר מרדכי הכהן הולנדר ממישקולץ. מחכמי אנטורפן."},{"i":39461,"n":"פרידמן, יוסף מגבוזדיץ","f":"יהושע","bt":"תריט","dt":"תרצד","b":"תלמיד ונכד-אבי אמו ר מאיר רפפורט מברודשין, ר אורי פיבל מקולומיאה בעל \"גידולי הקדש\". חסיד ר שמואל אברהם אבא הגר מהורודנקה והביא לדפוס את ספרו \"שפתי צדיק\". רב בדורוהוי-תרמט, גבוזדיץ-תרנא. נסמך מאת: ר יהודה ליב לנדא בעל \"יד יהודה\", מוהר\"י תאומים מטרניגרד. חיבר כללים על הש\"ס, ופרוש למשנה ולתורה."},{"i":39462,"n":"פרידמן, יוסף מגלוגוב","b":"מחכמי גלוגוב-תרנז."},{"i":39463,"n":"פרידמן, יוסף מהאדאז","f":"יצחק אייזיק פרידמ","dt":"תרסו","b":"מו\"צ בהאדאז(=האדאהז)."},{"i":39464,"n":"פרידמן, יוסף מטימבורג","b":"הדפיס \"ויכתוב משה\" ו\"שם משמואל\" בעצת האדמור ר שלמה מבובוב."},{"i":39465,"n":"פרידמן, יוסף מיקטרינסלב","b":"רב ביקטרינוסלב-תרל\"ה"},{"i":39466,"n":"פרידמן, יוסף מניו יורק","b":"דרשן,רב בברוקלין-ת\"ש"},{"i":39467,"n":"פרידמן, יוסף מרעדים","f":"אברהם דב הכהן","bt":"תקף","dt":"תרם","b":"מחכמי רעדים ומלמד לתלמידים."},{"i":39468,"n":"פרידמן, יחיאל דב מפשמישל","f":"יעקב שלמה הכהן","bt":"תרכה","bp":"פשמישל","dt":"תרפא","b":"רב בפשמישל. חתן ר אליעזר בלאו מפשמישל, מחשובי חסידי בלז וחסידי הסביבה היו מתאספים אצלו בחגים."},{"i":39469,"n":"פרידמן, יחיאל מדאנקרוי","f":"אורי ליפמן מפרידריכש","b":"מחכמי דאנקרוי. חתנו - ר אברהם זאב בן אליהו קצנלנבוים."},{"i":39470,"n":"פרידמן, יעקב","f":"שלום יוסף ממילניצה","bt":"תרע","dt":"תרלב","b":"סירב לאדמורות על מקום אביו-תרעז ואחיו ר אהרן משה התמנה לאדמור ממילניצה בקולומיי. משורר, ניצל מהשואה, ואחריה עלה לארץ והתישב בבית דגן שם עסק בחקלאות ובכתיבת שירה."},{"i":39471,"n":"פרידמן, יעקב אלעזר מראקושהעדי","f":"שלמה זלמן מראקושהעדי","k":"בעל תפארת אלעזר","dt":"תשלו","dp":"ניו יורק","b":"ניצל מהשואה ואחריה רב בראקושהעדי על מקום אביו. עבר לניו יורק."},{"i":39472,"n":"פרידמן, יעקב דוד מפשקן","f":"משה יהודה ליב מפשקן","k":"אדמור מפשקאן","bt":"תרנב","dt":"תשטו - כב אב","dp":"תל אביב","b":"נכד ר יצחק מבוהוש. חתן ר פנחס מזינקוב (שושלת אפטא). רב ואדמור בפשקאן-רומניה על מקום אביו. ניצל מהשואה, ואחריה עלה לארץ-תשי והתישב ביפו. מתורתו בספר אביו \"ברכת משה\"."},{"i":39473,"n":"פרידמן, יעקב הכהן מחוסט","f":"שמואל דוד - אבני צדק","dt":"תשד","b":"דומ\"צ בחוסט על מקום אביו."},{"i":39474,"n":"פרידמן, יעקב יהושע מדרוהוביטש","b":"רב בדרוהוביטש-תרסח."},{"i":39475,"n":"פרידמן, יעקב יוסף מדרוהוביטש","dt":"תרצו","dp":"ירושלים","b":"סופר כולל גליציה בדרוהוביטש בימי מהריל'ס. חתן ר שמואל לרר. עלה לירושלים-תרצג."},{"i":39476,"n":"פרידמן, יעקב יוסף שלמה מואסלוי","f":"חיים דב הלפרין מואסל","k":"אדמור מוואסלוי","bt":"תרס","dt":"תשמה - יא טבת","b":"נקרא גם הלפרין. חתן ר יעקב שמשון קנר מטשחויב (צאנז). אדמור בגאלאץ, בוקרשט. ניצל מהשואה, ואחריה עלה לארץ-תשי עם אביו, והתישב בנהריה, עבר לתל אביב."},{"i":39477,"n":"פרידמן, יעקב מבויאן","dt":"תשג","b":"רב מבאיאן"},{"i":39478,"n":"פרידמן, יעקב מברעזאווא","b":"רב בוערבא, ברעזאווא. בנו ר יוסף מאנטורפן."},{"i":39479,"n":"פרידמן, יעקב מהוסיאטין","f":"יצחק מבוהוש","k":"אדמור מהוסיאטין","bt":"תרלו-ט","bp":"בוהוש-רומניה","dt":"תשיג-ז -יח חשון","b":"חתן דודו ר ישראל מהוסיאטין. מראשי המזרחי, עבר לוינה - בזמן מלחה\"ע ה-I, עם חותנו, עלה לתל אביב-תרצז עם חותנו, אדמור מהוסיאטין-תשט על מקום חותנו אחריו, בנו ר יצחק על מקומו אחריו. חיבר \"אהלי יעקב\" ירושלים תשכב."},{"i":39480,"n":"פרידמן, יעקב מטעט","b":"אביו של ר מרדכי פרידמן איש שלום מבערעטי-אויפלו."},{"i":39481,"n":"פרידמן, יעקב ממזריטש","b":"מכתב ממנו לר נחום גינצבורג ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39482,"n":"פרידמן, יעקב מנדל מנדבורנה","bt":"תקץ","dt":"תרס","b":"רב בנדבורנה, בנו ר ישעיה על מקומו אחריו. (זמן רב לא היה רב בנדבורנה בגלל תקנה מזמן הפרנקיסטים - שהגיעו עד אליה)."},{"i":39483,"n":"פרידמן, יעקב מנחם מנדל","f":"ישראל שלום יוסף","k":"אדמור מבוהוש ב\"ב","b":"נכד האדמור ר יעקב דוד מפשקאן, והאדמור ר יצחק מבוהוש תל אביב. אדמור מבוהוש בבני ברק על מקום זקנו."},{"i":39484,"n":"פרידמן, יעקב פרץ מביהאר","f":"יצחק איזיק מנירדהאזא","k":"בעל פרי יעקב","r":"רב באודווארי","bt":"תרח או תרטו","dt":"תרפט - כו אב","dp":"גרוסורדין","b":"חתן ר מנחם גרשון גרינולד מבאדראג-קרסטור. רב בסערענטש-תרמב, ביהאר-אודווארי-תרמז.","bk":[["פרי יעקב \\ אהלי יעקב – ש\"ס",""]]},{"i":39485,"n":"פרידמן, יעקב צבי","dt":"תשד","b":"רב בראחוב"},{"i":39486,"n":"פרידמן, יעקב צבי מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":39487,"n":"פרידמן, יעקב קופל מנרעדהאוא","f":"יהודה מפרוינקירכן","bt":"תקצא","bp":"פפרוינקירכן","dt":"תרסו - כו כסלו","dp":"נירדהאזא","b":"תלמיד הכת\"ס. רב ביעמרינג-תריח, נירדהאזא-תרכו. בנו - ר שמואל בניין דיין בנירדהאזא."},{"i":39488,"n":"פרידמן, יעקב שאול מניו יורק","k":"בעל לווית חן","b":"רב בניו יורק-תרלז."},{"i":39489,"n":"פרידמן, יעקב שלמה מסנוק","f":"אברהם הכהן מפשמישל","bt":"תרן","bp":"דינוב","dt":"תשמח","b":"חתן ר אלימלך מלר מרקובא. מחכמי סנוק ומראשי הקהלה. ניצל מהשואה. רב במחנות הניצולים לאחר השואה, רב במינכן-תשח, עלה לארץ-תשטז וכיהן כרב בית כנסת בפתח תקוה. והיה מקורב לאדמורים בארץ. חתנו - ר שמואל רוזובסקי ראש ישיבת פוניבז."},{"i":39490,"n":"פרידמן, יעקב שלמה מפשמישל","f":"יוסף הכהן מרעדים","bt":"תרה","dt":"תרלג","b":"מחכמי פשמישל ומלמד לבחורים שלא בשכר. חתן ר יעקב כץ מפשמישל."},{"i":39491,"n":"פרידמן, יעקב שמעון יחזקאל מבנד","b":"מחכמי בנדין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":39492,"n":"פרידמן, יצחק איזיק מבאיאם וניר","f":"משה יוסף מנפאקר","k":"בעל תפארת יצחק","r":"רבה של נירדהאז בהונגריה","bt":"תקפב","bp":"נאפקר","dt":"תרנד - יט שבט","dp":"נירעדהאזא","b":"תלמיד החת\"ס, ור אברהם שמואל בנימין סופר מפרשבורג, ור בנימין זאב וולף לעוו מוערבא ור שאול ענגל מקאליב, והדברי חיים מצאנז. חתן ר יעקב פרץ זילברמן ממריאפאטש. רב בבאלקאן-תריב, ביהאר-נאדי-באייאם-תריג על מקום ר יעקב גוטליב, רב קהילת היראים בנירדהאז(=נירג'-האזה)-תרם וחתנו ר שלום וידר על מקומו אחריו. חיבר \"תפארת יצחק\" ירושלים תשמב. (ראה גם: פרידמן, קרל - רב ניאולוגי שם). בניו: ר יעקב פרץ מביהאר-אודווארי, ר משה צבי מניי-פעסט, ר חיים מזאמבראד, בעל \"אור המאיר\".","bk":[["תפארת יצחק - שו\"ת",""]]},{"i":39493,"n":"פרידמן, יצחק איזיק מיאנושי","f":"משה דוד פרידמן","dt":"תשד","b":"רב ביאנושי-תרפ\"ח"},{"i":39494,"n":"פרידמן, יצחק איזיק מקורטו","k":"בעל גאון יצחק","b":"רב בקורטו,טאבורג-תר\"פ"},{"i":39495,"n":"פרידמן, יצחק אריה","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":39496,"n":"פרידמן, יצחק דוד מניישטט","f":"משה פרידמן","b":"רב בניישטט-תר\"ל"},{"i":39497,"n":"פרידמן, יצחק ישכר מסיגד-וארלי","b":"תלמיד השב\"ס, מחכמי סינער-ואראלי-תרסט."},{"i":39498,"n":"פרידמן, יצחק מבוהוש א","f":"שלום יוסף מסדיגורא","k":"אדמור מבוהוש","bt":"תקצה","dt":"תרנו - י אלול","b":"חתן ר דוד הגר מזבלטוב (שושלת קוסוב). אדמור בפוטיק-תריא, איזמאיל-בסרביה-תרטז, בוהוש, מפיצה של החסידות במולדבה. בנו ר ישראל שלום יוסף על מקומו אחריו כאדמור מבוהוש. בשנת תרמב שלח את חסידיו ליסד את המושבה ראש פינה.","bk":[["אגרות קודש באהוש",""]]},{"i":39499,"n":"פרידמן, יצחק מבוהוש ב","f":"שלום יוסף משפיקוב","k":"אדמור מבוהוש","bt":"תרסב-ג","bp":"שפיקוב","dt":"תשנב - יד אב","b":"חתן דודו ר מנחם מנדל פרידמן מבוהוש. אדמור משפיקוב על מקום אביו - בגיל 17! , עבר לבודפסט-תרצא, אדמור מבוהוש בבוקרשט על מקום חותנו-תשג. עסק בהצלה בזמן השואה, ניצל מהשואה. עלה לארץ-תשי. התישב בתל אביב ובני ברק והיה מזקני האדמורים בארץ."},{"i":39500,"n":"פרידמן, יצחק מבויאן","f":"אברהם יעקב מסדיגורא","k":"אדמור מבויאן פחד יצח","bt":"תרי","dt":"תרעז - יז אדר","dp":"וינה","b":"חתן ר יוחנן מרחמיסטריבקה (שושלת טשרנוביל). אדמור בסדיגורא, בויאן. חיבר \"אוריאן תליתאי\" ירושלים תשם."},{"i":39501,"n":"פרידמן, יצחק מהוסיאטין","f":"יעקב מהוסיאטין","k":"אדמור מהוסיאטין","r":"אדמו\"ר מהוסיאטין","bt":"תרס","dt":"תשכח - ט אלול","dp":"תל אביב","b":"עלה לארץ-תרצז, אדמור הוסיאטין בתל אביב-תשיז על מקום אביו. האדמור האחרון לבית הוסיאטין.","bk":[["שיח יצחק",""]]},{"i":39502,"n":"פרידמן, יצחק מטירנא","f":"שמעון יהודה מלובלוי","dt":"תשג - יב תשרי","dp":"פולין","b":"תלמיד הדעת סופר, ור נח ברוך פישר מפרשוב, ועוד. רב בלובלוי-תרפה על מקום אביו, טירנא-תרצו. נספה בשואה."},{"i":39503,"n":"פרידמן, יצחק ממזריטש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39504,"n":"פרידמן, יצחק מקלינורדין","b":"דומ\"צ בקליינוורדיין"},{"i":39505,"n":"פרידמן, יצחק מרימנוב","f":"ישראל מסדיגורא","k":"אדמור מרימנוב-סדיגור","bt":"תרמו","dt":"תרפה - יא כסלו","dp":"ניו יורק","b":"חתן ר אשר ישעיה הורביץ מרימנוב בעל \"מעדני מלך\". אדמור בסדיגורא על מקום אביו, ועבר לרימנוב. בזמן המלחמה עבר לבודפשט ולוינה. היגר לארה\"ב-תרפד. החסיד ר יוסף רפפורט הדפיס לזכרו \"עקידת יצחק\" ניו יורק תרפה. בגיל 13 חתם עם צדיקי רוזין על \"אור האמת\" הוסיאטין תרנט."},{"i":39506,"n":"פרידמן, יצחק צבי מויטענץ","b":"רב בוויטענץ-תר\"ס"},{"i":39507,"n":"פרידמן, יקותיאל יהודה מאיבנובי","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":39508,"n":"פרידמן, ישכר דב מקרולה","f":"נח יום טוב ליפא","k":"בעל גבעת פנחס-תרפד","bt":"תרכב","bp":"יולניצא-מחוז ברג","b":"לאחר שנתייתם גדל אצל אחיו. תלמיד ישיבת ר שמואל דוד יונגריז מפהר-ג'ארמאט, ר משה דייטש בשאלגא-טאריאן, וה\"חתן סופר\" במטרסדורף. חתן ר אשר שמואל פאנט מהיאלדמאש, ועבר לשם וכיהן כרב הגליל. רב בקיראידארוץ-ליד סטמר-תרסב, קרולה-תרפד. נספה בשואה. חיבר גם \"מטה ישכר\" תרץ. פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":39509,"n":"פרידמן, ישכר דוב מדארוץ","k":"בעל תולדות יחזקאל","b":"רב בדארוץ-תר\"ע"},{"i":39510,"n":"פרידמן, ישעיה מבאשאץ","f":"שבתי מאלשא-קובין","b":"חתן ר שבתי זינגר מבאשאץ. רב בבאשאץ ליד חותנו."},{"i":39511,"n":"פרידמן, ישעיה מטאפלטשן","f":"צבי יהודה מטאפלטשן","dt":"תרצו - כב אלול","b":"נכד החת\"ס. חתן ר פנחס לינק מטאפלטשן, ועבר לשם. רב בטאפלטשן."},{"i":39512,"n":"פרידמן, ישעיה מנדבורנה","f":"יעקב מנדל מנדבורנה","bt":"תרי","dt":"תרפז","b":"רב בנדבורנה על מקום אביו-תרס, חתנו ר זאב וולף לוסטהויז על מקומו אחריו."},{"i":39513,"n":"פרידמן, ישראל חיים מראחוב","k":"בעל לקוטי מהרי\"ח","r":"אב\"ד ראחוב","bt":"תריב","dt":"תרפב - כד סיון","b":"תלמיד הדברי חיים מצאנז, בעל \"ייטב לב\". רב בראחוב, ובנו ר שלמה זלמן על מקומו אחריו.","bk":[["לקוטי מהרי\"ח - מנהגי הלכה",""]]},{"i":39514,"n":"פרידמן, ישראל יו\"ט מבאדן","b":"חתן ר צבי הרש פרלס מקיצע. בנו ר מרדכי מאיר - רב בקיצע על מקום זקנו."},{"i":39515,"n":"פרידמן, ישראל יום טוב","f":"נחמיה פרידמן","b":"רב-שנת תר\"פ"},{"i":39516,"n":"פרידמן, ישראל יצחק מטרנוב","b":"רב בטרנוב-תרטז, בנו ר שרגא דוד על מקומו אחריו."},{"i":39517,"n":"פרידמן, ישראל מאיר מצאנז","b":"רב בצאנז, סטרופקוב אצל ר אברהם שלום הלברשטט. נספה בשואה."},{"i":39518,"n":"פרידמן, ישראל מבויאן-לייפציג","f":"יצחק - הפחד יצחק","k":"אדמור מבויאן-לייפציג","bt":"תרלח","dt":"תשיא-ב - א אלול","dp":"צפת","b":"חתן דודו ר שלמה מסדיגורא. אדמור מבויאן בלייפציג על מקום אביו. ניצל מהשואה דרך שוויץ, עלה לארץ-תרצט והתיישב בתל אביב."},{"i":39519,"n":"פרידמן, ישראל מהוסיאטין","f":"מרדכי שרגא מהוסיאטין","k":"אדמור מהוסיאטין","bt":"תריח","bp":"הוסיאטין","dt":"תשט - כט כסלו","dp":"טבריה","b":"חתן ר אבי עזרא זליג שפירא מסדיגורא-סטרי ומוגילניצה, ובזיוו\"ש חתן ר חיים הגר מאטיניא. אדמור בהוסיאטין על מקום אביו. עבר לוינה בזמן מלחה\"ע ה-I. עודד את חסידיו לעלות לארץ. עלה לארץ-תרצז והתישב בתל אביב והיה זקן האדמורים בארץ. חתנו ר יעקב בן יצחק מבוהוש על מקומו אחריו כאדמור הוסיאטין בתל אביב. בזמן השואה התפלל על קבר \"אור החיים\" והבטיח שיהודי ארץ ישראל לא יפגעו."},{"i":39520,"n":"פרידמן, ישראל ממיטאוי","f":"דוד","k":"ישראל פעסיס","bp":"ראסיין-פלך קובנא","dt":"תרד - כז אדר","dp":"מיטאוי","b":"תלמיד ר יהושע זליג יורברגר. רב במיטאוי על מקום ר דוד יחזקאל (ר אליהו בנו של ר דוד יחזקאל היה מועמד כנגדו). בנה ביכ\"נ ומקוה במיטאוי. תשובות ממנו ב\"זכרון יעקב\" להרב מבויסק. היה גם מבקר (צנזור) מטעם השלטון."},{"i":39521,"n":"פרידמן, ישראל מסדיגורא","f":"אברהם יעקב מסדיגורא","k":"אדמור מסדיגורא","bt":"תריב","dt":"תרסז - יג תשרי","b":"חתן האדמור ר יצחק מבוהוש, ובזיוו\"ש חתן דודו ר שלום יוסף מסדיגורא. אדמור בסדיגורא על מקום אביו, בנו ר אהרן על מקומו אחריו."},{"i":39522,"n":"פרידמן, ישראל מצורטקוב","f":"דוד משה מצורטקוב","k":"אדמור מצורטקוב","r":"אדמו\"ר מטשורטקוב","bt":"תריד","bp":"פאטיק","dt":"תרצד - יג כסלו","dp":"וינה","b":"חתן דודו ר אברהם יעקב מסדיגורה. אדמור בצורטקוב על מקום אביו, בנו ר נחום מרדכי על מקומו אחריו. כונה הפיקח שבאדמורים, עודד עליה לארץ, ממייסדי ומראשי \"אגודת ישראל\". התישב בוינה בזמן מלחמת העולם הראשונה ונשאר שם על מנת לחזק את הקהלה בוינה. חיבר \"עטרת ישראל\" הוסיאטין תרסד, \"ישמח ישראל\" וינה תרצג, \"גנזי ישראל\", ועוד. בנו ר חיים אהרן.","bk":[["גנזי ישראל",""],["ישמח ישראל – שבתות ומועדים",""],["נזר ישראל – עה\"ת ומועדים",""],["תפארת ישראל – עה\"ת",""],["אור ישראל",""]]},{"i":39523,"n":"פרידמן, ישראל מקערט","f":"מרדכי גימפל","k":"בעל הגהות מהרי קערט","bt":"תקסח","bp":"ראדוואנקא","dt":"תרלז - כה טבת","dp":"וערבא","b":"לאחר שנתייתם גדל אצל בעל \"ישמח משה\". תלמיד החת\"ס, ור יחזקאל בנט מנייטרא. חתן ר דוד שליסל מקערט. רב בקערט, וערבא-תרטו. ?? לא באוצר ??"},{"i":39524,"n":"פרידמן, ישראל מרוזין","f":"שלום שכנא מפרובישץ","k":"אדמור מרוזין","r":"אדמו\"ר מרוז'ין","bt":"תקנז","dt":"תריא - ג חשון","b":"חתן ר משה אפרתי מברדיטשוב, ובזיוו\"ש חתן ר דוד לייב לייבנר מדוקלא ואלמנת ר צבי הירש מרימנוב. אדמור ברוזין. ישב במאסר הרוסים-תקצז, ברח מרוזין והתישב בסדיגורא-בוקובינה וכיהן כאחד מגדולי האדמורים בדורו. מתורתו ב\"אורות ישראל\", ו\"נר ישראל\".","bk":[["עירין קדישין",""],["ישועות ישראל",""],["נחלת ישראל",""],["עירין קדישין ג",""],["עירין קדישין תניינא",""],["פאר לישרים",""]]},{"i":39525,"n":"פרידמן, ישראל שלום יוסף מבוהוש","f":"יצחק מבוהוש","k":"אדמור מבוהוש","bt":"תרטז-כג","dt":"תרפג - כג ניסן","b":"חתן ר משה אברהם צוקרמן מרשקוב, בזיוו\"ש חתן ר יוסף פרידמן מרימנוב. אדמדור בבוהוש על מקום אביו, והקים ישיבה שבה למדו גדולי רומניה לעתיד. בקי ברפואה. נשיא כולל רומניה בארץ ישראל. חיבר \"פאר ישראל\" ירושלים תשלט.","bk":[["פאר ישראל – עה\"ת , אגרות קודש באהוש חלק ב'",""]]},{"i":39526,"n":"פרידמן, ליאון יהודה מצרפת ואלג","b":"רב בקצמטינא מטעם הקונסיסטואר-תרסו, אלגיר - תרעג-תרפח. דרשה ממנו בספר \"דרושים\" לר אברהם זרביב, ומכתב ממנו ב\"צעקת הרועים\" לר אליהו בן גיגי - תונס תרעה."},{"i":39527,"n":"פרידמן, ליב","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":39528,"n":"פרידמן, ליבוש מקראקא","b":"נכד ר מאיר רפפורט מלוקאווא. רב בביהמ\"ד ליקובא בקראקא-תרצד."},{"i":39529,"n":"פרידמן, מאיר יצחק מניו יורק","f":"יעקב","k":"בעל מאורי יצחק","dp":"ירושלים","b":"תלמיד הכת\"ס, ר הלל ליכטנשטין, ר חיים סופר. רב בניו יורק, עלה לירושלים."},{"i":39530,"n":"פרידמן, מאיר ישראל איסר","f":"בן ציון הכהן מדובצק","k":"בעל אמרי ישראל","bt":"תרנט","dt":"תשנד","b":"חסיד בלוזוב, חתן ר אברהם עבר פטרפרוינד מקרניץ. ר\"מ בישיבת בובוב בקרניץ. ניצל מהשואה ועבר לניו יורק וכיהן כאב\"ד קרניץ בניו יורק. חיבר \"אמרי ישראל\" ניו יורק תשנה."},{"i":39531,"n":"פרידמן, מוריץ מלינץ","b":"רב בלינץ-אוסטריה."},{"i":39532,"n":"פרידמן, מנחם גרשון","f":"יעקב פרץ פרידמן","k":"בעל אגם מים","bt":"תרמ","dt":"תשד - טו סיון","b":"חתן ר יצחק יוסף בליך. נספה בשואה. חיבר \"אגם מים\".","bk":[["אגם מים",""]]},{"i":39533,"n":"פרידמן, מנחם יהודה","f":"מרדכי מכפר ארהעי","k":"בעל עבודת הקדש-תרצה","b":"מחכמי סטמר. נספה בשואה. הו\"ל דיני שחיטה ממהר\"י וייל בשם \"עבודת הקדש\" עם תוספות ממנו - אראדעא תרצה. ?? לא באוצר ??"},{"i":39534,"n":"פרידמן, מנחם מנדל מבוהוש","f":"דוד מבוהוש","k":"אדמור מבוהוש","bt":"תרלו","bp":"בוהוש","dt":"תשג - יא תשרי","b":"נינו של ר ישראל מרוזין. חתן דודו ר ישראל שלום יוסף האדמור מבוהוש. עמד בראש הישיבה בבוהוש יחד עם גיסו ר דוד טברסקי. אדמור מבוהוש-תרפג על מקום חותנו. כתביו נשרפו בביתו על ידי הקומוניסטים."},{"i":39535,"n":"פרידמן, מנחם מנדל מראסיין","dt":"תרעב - אלול","dp":"ברלין","b":"חתן ר יוסף אשרי מראסיין. גביר מחכמי ראסיין. הניח חדושים בכת\"י."},{"i":39536,"n":"פרידמן, מנחם נחום דובער מסדיגו","f":"שלום יוסף מסדיגורא","k":"אדמור מסדיגורא","bt":"תרג","dt":"תרמג - כז אב","dp":"וינה","b":"התייתם בילדותו וגדל אצל אחיו ר יצחק מבוהוש. חתן דודו ר אברהם יעקב מסדיגורא (בחתונה השתתפו כ-50000 יהודים) ועבר לשם ויחד עם גיסו ר שלמה מסדיגורא סייע לחותנוו האדמור בהנהגת העדה. חובב ספר, ובעל ספריה חשובה וערך לספריה קטלוג, וכן הדפיס רשימת הספרים שמתכונן לקנות. נפטר בטרם התמנה לאדמור מסדיגורא לחסידי רוסיה. (היו לו 3 סוגי חותמות: \"נחלת אבותי\" - ספרים שירש מאביו, \"מנחת שי\" - ספרים שקיבל מחסידיו, \"קנין כספי\")."},{"i":39537,"n":"פרידמן, מנחם נחום מאיצקן","f":"אברהם יהושע השל מאדז","k":"בעל דברי מנחם","r":"רב באיטצקאן (בוקבינא), ומיועד להיות אדמו\"ר משטפנשט","bt":"תרלט","bp":"שטפנשט","dt":"תרצג -כ-כא סיון","b":"נכד ר יצחק האדמור מבוהוש. חתן האדמור ר ישראל מצורטקוב. חוקר ופילוסוף. רב באיצקן-תרסז. עבר לוינה במלחה\"ע ה-I, לשטפינשט אל דודו האדמור ר אברהם מתתיהו וכונה בשם \"האדמור הצעיר\", נועד למלא מקום דודו האדמור משטפנשט אך נפטר קודם לכן. חיבר \"דברי מנחם\" קראקא תרעג, ועוד. היה מחלוקת מצד החרדים כנגד ספרו \"דברי מנחם\".","bk":[["דברי מנחם - כו דרשות",""],["החלום ופתרונו - חלומות",""],["מן - אבות",""],["על האדם - מוסר",""],["על האמת והשקר",""],["על היופי - היופי ביהדות",""]]},{"i":39538,"n":"פרידמן, מנחם נחום מלמברג הוסיא","f":"שלום יוסף מהוסיאטין","k":"אדמור מהוסיאטין","bt":"תרם","dt":"תשג","b":"חתן דודו ר ישראל מהוסיאטין. אדמור מהוסיאטין בלמברג-תרצז לאחר עליית חותנו לארץ. נספה בשואה."},{"i":39539,"n":"פרידמן, מנחם נחום מצ'רנוביץ","f":"יצחק - הפחד יצחק","k":"אדמור מבויאן צרנוביץ","bt":"תרכט","bp":"סדיגורא","dt":"תרצו-ט - יט אב","b":"חתן דודו זקנו ר מרדכי שרגא מהוסיאטין. אדמור מבויאן בטשרנוביץ על מקום אביו (לאחר שבויאן חרבה במלחמת העולם הראשונה), בנו ר אהרן על מקומו אחריו. ביקר בארץ ישראל-תרפז. חיבר \"דברים ניחומים\" טשרנוביץ תרצז, \"זה ינחמנו\", \"תפארת מנחם\". תולדותיו ב\"משכנות הרועים\". ועוד. משמשו ר אלתר בירברייער הדפיס הספד עליו \"קול נהי בכי תמרורים\" טשרנוביץ תרצו."},{"i":39540,"n":"פרידמן, מנחם נחום משטפנשט","f":"ישראל מרוזין","k":"אדמור משטפנשט","r":"האדמו\"ר הראשון משטיפנשט","bt":"תקפג","dt":"תרכט - יד כסלו","b":"חתן ר אלעזר קושנסקי. אדמור בשטפנשט-תריב. מראשוני ומגדולי האדמורים ברומניה, בנו ר אברהם מתתיה על מקומו אחריו.","bk":[["רבי מנחם נחום (שטפנשט)",""],["נר ישראל - שיחות ותורות",""]]},{"i":39541,"n":"פרידמן, מנחם צבי","f":"חיים פרידמן","dt":"תשד","b":"רב בקערעסטעש-תרצ\"ב"},{"i":39542,"n":"פרידמן, מנחם צבי ממעזא-קערסטש","f":"חיים מדאמברד","dt":"תש..","b":"תלמיד הדעת סופר. חתן ר אשר אליקים טשעך מבורשוד-מעזא-קערסטעש. רב בבורשוד-מעזא-קערסטעש-תרצב על מקום חותנו. נספה בשואה."},{"i":39543,"n":"פרידמן, מנשה שמחה","bt":"תרטו","dt":"תרפו - א שבט","b":"רב בסוברנץ"},{"i":39544,"n":"פרידמן, מרדכי ליב מברטפלד","dt":"תרכד - טו אדר","b":"ראב\"ד בברטפלד"},{"i":39545,"n":"פרידמן, מרדכי מאוסטראווא","b":"רב באסטראווא-תר\"נ"},{"i":39546,"n":"פרידמן, מרדכי מאיר מקיצע","f":"ישראל יו\"ט מבאדן","k":"בעל אמרי מרדכי","bt":"תרנט","dt":"תשמד- כ ניסן","dp":"ירושלים","b":"נכד ר צבי הרש פרלס מקיצע. תלמיד הדעת סופר. רב בקיצע על מקום חותנו (עוד בבחרותו בהוראת זקנו). חתן ר ברוך משה נחמיה לבל מירושלים ור\"מ בפרשבורג. עלה לארץ ולימד תורה בבני ברק. הו\"ל ספר זקנו \"הגהות מהר\"י קערט\" עם ביאור ממנו \"אמרי מרדכי\"."},{"i":39547,"n":"פרידמן, מרדכי מיאנושהאזא","f":"פנחס ליב פרידמן","b":"רב ביאנושהאזא-תר\"נ"},{"i":39548,"n":"פרידמן, מרדכי ממזריטש","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":39549,"n":"פרידמן, מרדכי שלום יוסף","f":"ישראל פרידמן","r":"האדמו\"ר מסאדיגורה","bt":"ה'תרנז","dt":"ה'תשלט","b":"רב בטשרנוביץ-תר\"פ","bk":[["כנסת מרדכי (סדיגורא-פשמישל)",""],["כנסת מרדכי",""]]},{"i":39550,"n":"פרידמן, מרדכי שלום יוסף מסדיגו","f":"אהרן מסדיגורא","k":"אדמור מסדיגורא","bt":"תרנז","bp":"סדיגורא","dt":"תשלט - כט ניסן","b":"חתן ר ישראל שלום יוסף השל ממזבוז (שושלת אפטא). אדמור בסדיגורא על מקום אביו-תרעג (בגיל 16), בנו ר אברהם יעקב על מקומו אחריו. ביקר בארץ-תרצג. שלח את חסידיו בטורקא לשכונת צבי ליד נתניה. עבר לוינה, פשמישל-תרצד והקים שם ישיבה. עלה לארץ-תרצט והציל את רוב ספריו. התישב בתל אביב. בביקור בארה\"ב-תשי ושהה זמן רב בניו יורק, והיה עוד כמה פעמים שם. כיהן כאדמור כ-70 שנה. חיבר \"כנסת מרדכי\" לובלין תרצו. הו\"ל כתב עת \"כנסת מרדכי\" - פרמישלא תרצח. נזכר \"בזקן אהרן\", ועוד. ?? לא באוצר ??"},{"i":39551,"n":"פרידמן, מרדכי שלמה מניו יורק","f":"יצחק - הפחד יצחק","k":"אדמור מבויאן","bt":"תרנא","dt":"תשלא - ה אדר","b":"חתן ר ישראל שלום יוסף השל ממזבוז (שושלת אפטא). אדמור מבויאן בוינה על מקום אביו. עבר לניו יורק-תרפז. ביקר כמה פעמים בארץ. הקים ישיבות רוזין בארץ. מתורתו ב-\"תפארת ישראל\" ירושלים תשמד.","bk":[["רבי מרדכי שלמה (בויאן)",""]]},{"i":39552,"n":"פרידמן, מרדכי שרגא מצ'רנוביץ","f":"מנחם נחום מבויאן","bt":"תרן","dt":"תשב - יז טבת","b":"חתן דודו האדמור ר ישראל מבויאן-לייפציג, ובזיוו\"ש חתן האהבת ישראל מויזניץ. אדמור מבויאן בטשרנוביץ עם אחיו ר אהרן. נספה בשואה."},{"i":39553,"n":"פרידמן, מרדכי שרגא פיביש","f":"ישראל מרוזין","k":"אדמור מהוסיאטין","bt":"תקצד","bp":"סדיגורא","dt":"תרנד - כב אייר","b":"חתן דודו ר צבי קובלנסקי מברדיטשוב. התגורר במיקוליניץ, סטריסוב-תרטו, הוסיאטין-תרכה וכיהן כאדמור מהוסיאטין, בנו ר ישראל על מקומו אחריו."},{"i":39554,"n":"פרידמן, משה אהרן מרימא-סמבאט","k":"בעל אמרות","b":"רב בטאליא על מקום ר דוד יהודה רוטנברג, רימאסמבאט(=רימו-סומבוט)-תריא."},{"i":39555,"n":"פרידמן, משה דוד מגרוסורדין","f":"יעקב פרץ מאודווארי","k":"בעל פרי חמד-תקצג","bt":"תרמא","dt":"תשד","b":"תלמיד בעל \"קדושת יו\"ט\" בסיגט, ובעל \"ערוגת הבשם\" בחוסט. חתן ר יהושע בריסק מטיסא-דאדא. רב באראנד-ליד דברצין, דיין בגרוסורדין-תרסו ורב חברת \"אהבת רעים\". בנו - ר שלמה זלמן מטענקע וניו יורק. נספה בשואה. (לפי מורשת הונגריה - שם אביו - שלמה זלמן מטנקה)."},{"i":39556,"n":"פרידמן, משה יהודה ליב מפשקן","f":"יצחק מבוהוש","k":"אדמור מבוהוש-פשקן","bt":"תרכה","dt":"תשז - י אלול","b":"חתן דודו ר מנחם נחום דובער מסדיגורא. עבר לפשקן וכיהן כאדמור מבוהוש-פשקאן, בנו ר יעקב דוד על מקומו אחריו. ניצל מהשואה. מתורתו ב\"ברכת משה\" ירושלים תשמו."},{"i":39557,"n":"פרידמן, משה יוסף","b":"נשלח מגליציה לפקח על השוחטים בהונגריה על ידי ר אשר ישעיה מרופשיץ."},{"i":39558,"n":"פרידמן, משה יוסף מפאטיק","b":"מו\"צ בפאטיק-ת\"ר"},{"i":39559,"n":"פרידמן, משה ליב מפרושקן","f":"יצחק פרידמן","k":"אדמור מפרוקשן","dt":"תרצז - י אלול","b":"אדמו\"ר מפרושקן"},{"i":39560,"n":"פרידמן, משה מבויאן-קראקא","f":"שלום יוסף מהוסיאטין","k":"אדמור מבויאן-קראקא","bt":"תרמא","bp":"הוסיאטין","dt":"תשג - ג אלול","b":"תלמיד חותנו זקנו ר יצחק מבויאן, ושל דודו ר ישראל מהוסיאטין. חתן ר מנחם נחום מבויאן-טשרנוביץ. אדמור מבויאן אחרי-תרעז, עבר לוינה-תרעב, קראקא-תרפה. נשיא \"ישיבת חכמי לובלין\" אחרי מהר\"ם שפירא, ומנהלה הרוחני-תרצ\"ד. נספה בשואה, וכתביו אבדו. מתורתו ב\"דעת משה\" ירושלים תשז. פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":39561,"n":"פרידמן, משה מיוהניסבורג","bt":"תרכ","dt":"תרפה - ו סיון","b":"תלמיד ישיבות ליטא. רב ביוהניסבורג-תרנז."},{"i":39562,"n":"פרידמן, משה מפרוזאני","b":"רב בפרוזאני-תר\"י"},{"i":39563,"n":"פרידמן, משה מרדכי גומ' מפשמישל","b":"דיין בפשמישל-תרכב."},{"i":39564,"n":"פרידמן, משה משאקי","bt":"תרלה","dt":"תרצה - יז כסלו","b":"רב בשאקי."},{"i":39565,"n":"פרידמן, משה משקודוויל","b":"רב בשקודוויל-תר\"מ"},{"i":39566,"n":"פרידמן, משה צבי מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":39567,"n":"פרידמן, משה צבי מנייפעסט","f":"יצחק אייזיק","k":"בעל הכנה ליום טוב","bt":"תרה או תריח","dt":"תרצג","b":"רב בהאדהאז-תרנד, רבה הראשון של נייפעסט(=אוי-פשט), עבר למונקטש. פרסם מאמרים ב\"וילקט יוסף\". אחיו של ר חיים פרידמן מדאמבראד."},{"i":39568,"n":"פרידמן, נחום דב","f":"שלום יוסף מסדיגורא","b":"נכד ר ישראל מרוזין."},{"i":39569,"n":"פרידמן, נחום מטרנופול","dt":"תשג","b":"רב בטרנופול"},{"i":39570,"n":"פרידמן, נחום מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה."},{"i":39571,"n":"פרידמן, נחום מרדכי מצורטקוב","f":"דוד משה מצורטקוב","dt":"תרל","dp":"דלטין","b":"חתן דודו ר שלום יוסף מסדיגורא. נפטר צעיר."},{"i":39572,"n":"פרידמן, נחום מרדכי מצורטקוב","f":"ישראל מצורטקוב","k":"אדמור מצורטקוב","r":"אדמו\"ר מטשורטקוב","bt":"תרלד","bp":"צורטקוב","dt":"תשו - יח אד\"ב","b":"חתן דודו ר שלמה מסדיגורא. אדמור מצורטקוב בוינה-תרצד על מקום אביו יחד עם אחיו ר דובער (למרות שסירב - נענה לציווי אמו). עלה לארץ-תרצט. חבר \"מועצת גדולי התורה\". חיבר \"דורש טוב\" ירושלים תשכד.","bk":[["דורש טוב [על המועדים] (טשורטקוב)",""],["דורש טוב – תורה ומועדים",""]]},{"i":39573,"n":"פרידמן, נחמיה מוינה","f":"ישראל משה מקרט","bt":"תרכה","bp":"וערבוי","b":"תלמיד ישיבת פרשבורג, צעהלם. רב ומג\"מ בביהמ\"ד \"מרפא לנפש\"-וינה-תרנו."},{"i":39574,"n":"פרידמן, נפתלי","bt":"1863","bp":"יוזדא-מחוז שאוולי","dt":"1921","dp":"קיסינגן - פוניבז","b":"עורך דין בפוניבז. הופיע במשפטים על פרעות במחוזות שאוולי ופינבז והרשיע את הנאשמים. חבר עיריה בפוניבז, והתפטר. ציר בדומה. בזמן מלחמ\"ה ה-I הגן על היהודים מפני חשדות ועלילות, ודאג לפליטים ומגורשים. סגן היו\"ר של המוצעה הליטאית - \"טאריבה\" בפטרבורג. חזר לליטא ונבחר לנשיאות ועידת הקהילות ול\"ועד הארץ\"."},{"i":39575,"n":"פרידמן, נפתלי הירצקא מגרוסורדי","f":"משה דוד מגרוסורדין","bt":"תרסו","b":"רב בבית כנסת \"בית יצחק\" בגרוסורדין-תרץ. ניצל מהשואה - בעזרת מפקד פלוגת העבודה שהיה מחסידי אומות העולם והכירו עוד לפני המלחמה). היגר לארה\"ב וכיהן כרב בלוס אנג'לס ועמד בראש מערכת הכשרות שם, רב בניו יורק."},{"i":39576,"n":"פרידמן, נתן מראקישוק","b":"שו\"ב בראקישוק - למגדון גדול ות\"ח."},{"i":39577,"n":"פרידמן, נתן צבי","k":"בעל אוצר הרבנים","r":"רב שיכון ה' בבני ברק","bt":"כה תמוז תרעד","dt":"ו' אלול תשנג","b":"ניצל מהשואה, ואחריה רב במחנה פרנוולד-גרמניה, עלה לארץ.","bk":[["אוצר הרבנים",""],["נצר מטעי – שו\"ת",""],["פרפראות לתורה",""]]},{"i":39578,"n":"פרידמן, עזריאל ממיהאלוביץ","dt":"תשג","b":"רב במיהאלוביץ. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":39579,"n":"פרידמן, פנחס","f":"יעקב שלמה מפשמישל","bt":"תרכח","dt":"תרף","b":"חתן ר שלמה הכהן ניימן מפשמישל. חסיד בלז, ואחר כך סטרטין."},{"i":39580,"n":"פרידמן, פנחס אליהו מזארמין","f":"יצחק מוארשא","bt":"תרס","b":"תלמיד ר מאיר דונשלעס, רשם את חדושי רבו בשם \"ישועות פנחס\" - בכת\"י (כשהיה בן 17)."},{"i":39581,"n":"פרידמן, פנחס אליעזר מיונגטאון","b":"רב ביונגטאון-אוהיו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":39582,"n":"פרידמן, פנחס מפריסטיק","f":"[בן ציון מדובצק]","b":"מחכמי פריסטיק וסטריזוב. ההדיר \"מאה קשיטה\"-תרנב. חתן ר ישראל אהרן אנגלנדר מפריסטיק, רב בפריסטיק על מקום חותנו."},{"i":39583,"n":"פרידמן, צבי הירש כץ מברגסאס","b":"דומ\"צ בברגסאס-תר\"נ. בנו - ר שמואל דוד מחוסט."},{"i":39584,"n":"פרידמן, צבי הירש מבעזעד","b":"חתן ר עוזר אולמן מבעזעד. מחכמי בעזעד, מאנדאק. חתנו - ר צבי הירש פרידמן מבעזעד."},{"i":39585,"n":"פרידמן, צבי הירש מהאטסעג","f":"מנשה שמחה מסובראנץ","k":"בעל צבי חמד-תרפד","bt":"תרמב","bp":"הידו-נאנאש","dt":"תשכט - ג סיון","dp":"ניו יורק","b":"נכד ר ישראל אפרים פישל סופר מהאידו-נאנאש. תלמיד בעל \"קדושת יו\"ט\" בסיגט, ותלמיד בעל \"ערוגת הבשם\" מחוסט. חתן ר זאב וולף ציטרון האדמור מדאראג. רב בהאצג (=הטסג)- בקהלה החרדית שהתפלגה מהניאולוגים. הו\"ל ספר זקנו \"אפסי ארץ\". היגר לארה\"ב-תרפב וכיהן כרב בניו יורק - בקהלת \"אהבת ישורון\"."},{"i":39586,"n":"פרידמן, צבי הירש מליסקא","f":"אהרן","k":"אדמור מליסקא-פרי תבו","bt":"תקן-נח","dt":"תרלד - יד אב","b":"תלמיד ר משה טיטלבוים מאויהל, ר צבי הירש מבוניהאד(=בניהאד), ה\"דברי חיים\" מצאנז. אב\"ד ליסקא-תר, והחל לכהן כאדמור בליסקא - ובזמנו היתה הקהלה למרכז החסידות בהונגריה, וחתנו ר חיים פרידלנדר על מקומו אחריו. חיבר \"אך פרי תבואה\", \"הישר והטוב\", ועוד. מתולודתיו ב\"דרכי הישר והטוב\". אחריו עברה החסידות לבודרוג קרסטור.","bk":[["הישר והטוב – ש\"ס ודרוש, אור הישר והטוב, אך פרי תבואה – עה\"ת",""]]},{"i":39587,"n":"פרידמן, צבי חיים זיידא משרובקא","f":"מאיר בנימין בן יהודה","bt":"תרכה","b":"רב בשארובקה-פודוליה-תרמו. נסמך מאת: ר יצחק אלחנן מקובנא, ר משלם פיבל מגרידינג, ר אלתר מקונסטנטין."},{"i":39588,"n":"פרידמן, צבי יהודה מטאפלטשן","f":"חנוך","bp":"טאפלטשאן","dt":"תרלז - ז כסלו","dp":"טאפלטשן","b":"תלמיד החת\"ס והכת\"ס. חתן החת\"ס-תרז (לאחר פטירתו). מחכמי טאפלטשאן."},{"i":39589,"n":"פרידמן, קלונימוס קלמן","dt":"תשד","b":"רב בנירלוגאש"},{"i":39590,"n":"פרידמן, קרל (יצחק) מנירג-האזה","b":"רבה הראשון של הקהילה הניאולוגית בניראג-האזה. (לפי מורשת רבני הונגריה - הוא זהה לר יצחק איזיק פרידמן בעל \"תפארת יצחק\")"},{"i":39591,"n":"פרידמן, רפאל מרדכי מדעש","b":"מיסד הישיבה בדעש-תרפט, יחד עם ר משה מרדכי קלרמן."},{"i":39592,"n":"פרידמן, שבתי מאלשא-קובין","f":"שמעון יהודה מלובלוי","b":"תלמיד השב\"ס. חתן ר אברהם גרינבורג מקעזמארק. רב באלשא-קובין-תרסח. נספה בשואה. בנו ר ישעיה מבאשאץ."},{"i":39593,"n":"פרידמן, שבתי מלבוב","b":"דיין בלבוב, חתם-תרצט עם ר ישראל יהודה ולפסברג ור נתן נטע לייטר."},{"i":39594,"n":"פרידמן, שבתי מסטאויסק וארה\"ב","k":"בעל יקב זאב","b":"רב בסטאויסק, ארה\"ב-תשיא. פרסם מאמרים ב תלמיד אחיו ר ישכר בריש מבענדין, חתן ר אלכסנדר זיסקינד ליפשיץ מאוזארקוב. רב ביאנוב(=יאנווא-פאלאצק)-תרמד, מאדוב(מאקאווי)-תרמח, סטשוב-תרסא, גלה לרוסיה במלחמה העולם ה-I, וחזר לסטשוב. עבר לאמריקה, רב בטורונטו-תרף, סט לואיס-תרפז, טורונטו בשנית. פעל רבות למען שמירת השבת וגם פנה לממשלה לתת אפשרות ליהודים לשמור על השבת. תיקן עירוב בעיר (כנראה הראשון באמריקה). נספד ב\"הפרדס\". חיבר גם \"דברים ככתבם\" סט לואיס תרצב, \"יביע אומר\", חיבר זכרון ממלחמת העולם ה-I - לודז תרפו, פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. \"שערי ציון\" - ירושלים תרפא."},{"i":39595,"n":"פרידמן, שלום יוסף","f":"נחום דוב","b":"חתן ר ישראל פרידמן בן האדמור ר אברהם יעקב מסדיגורה."},{"i":39596,"n":"פרידמן, שלום יוסף מהוסיאטין","f":"מרדכי שרגא מהוסיאטין","bt":"תרך","dt":"תרמג - ז טבת","b":"חתן ר אפרים זלמן מרגליות מציוב (ווהלין). נפטר בצעירותו."},{"i":39597,"n":"פרידמן, שלום יוסף ממילניצה","f":"מנחם נחום דב בר","k":"אדמור ממילניצא","bt":"תרלא","dt":"תרפז - כ אב","b":"אדמור במילניצה והתישב בטשרנוביץ. חתן דודו ר ישראל מסדיגורא ובזיוו\"ש חתן ר מרדכי יוסף טברסקי מזלטופול. אדמור במילניצא, עבר ללמברג. בנו - המשורר יעקב פרידמן."},{"i":39598,"n":"פרידמן, שלום יוסף מסדיגורא","f":"ישראל מרוזין","k":"אדמור מסדיגורא","bt":"תקעג","dt":"תרי - יא אלול","dp":"לייפציג","b":"חתן ר דן יונגרלייב מראדויל (זלוטשוב). אדמור בסדיגורא אחרי פטירת אביו - פחות משנה. בנו - ר נחום דב."},{"i":39599,"n":"פרידמן, שלום יוסף מצ'רנוביץ","f":"ישראל מסדיגורא","k":"אדמור מסדיגורא-טשרנו","bt":"תרלט","dt":"תרפג-צו -יח שבט","b":"חתן ר ברוך הגר מויזניץ. אדמור מסדיגורא בטשרנוביץ."},{"i":39600,"n":"פרידמן, שלום יוסף משפיקוב","f":"דוד מבוהוש","k":"אדמור משפיקוב","bt":"תרלו-ח","dt":"תרף - יד אדר","b":"חתן ר מרדכי טברסקי האדמור משפיקוב (שושלת טשרנוביל), אדמור בשפיקוב על מקום חותנו-תרנז - והיה לאדמור היחיד מבית רוזין שהורשה להתגורר ברוסיה."},{"i":39601,"n":"פרידמן, שלום מאוסטרהא","f":"אפרים מלבוב בן שלום","dt":"תעו - כב אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":39602,"n":"פרידמן, שלום מהליטשובה","b":"רב בהעליטשאבא,פריישטטל-תר\"ה"},{"i":39603,"n":"פרידמן, שלום מפרישטט","f":"אהרן","bp":"פריישטט","dt":"תקצא - בערך","b":"תלמיד החת\"ס.רב בנייטרא, העלישטאבא, פריישטאט-תקפג על מקום ר אברהם יצחק בלום."},{"i":39604,"n":"פרידמן, שלמה","f":"יחיאל מיכל מדובצק","b":"חתן נכדת ר משה כץ עלוביטש מדוקלא. מדברי תורתו בספר נכדו \"נחלי דבש\"."},{"i":39605,"n":"פרידמן, שלמה זלמן מאקושהעדי","f":"צבי הרש מבעזעד","bt":"תרנה","bp":"בעזעד","dt":"תש..","b":"תלמיד הדעת סופר. חתן ר בנימין זאב בלוי מסנטוב, ובזיוו\"ש חתן ר מיכאל חיים פשקס ממאקווא. מחכמי טאליא-תרפד, ראקושיהעדי-תרצה, ובנו ר יעקב אליעזר על מקום אביו לאחר השואה."},{"i":39606,"n":"פרידמן, שלמה זלמן מטענקע ונ\"י","f":"משה דוד מגרוסורדין","k":"בעל ברכה משלשת-תרצג","bt":"תרסז","bp":"גרוסורדין","b":"תלמיד דודו ר מרדכי בריסק בטשאנד. חתן ר אשר אנשיל וייס מנאג'פאלו. רב בטנקה(=טנקא)-ליד גרוסורדין-תרפט. ניצל מהשואה, ואחריה היגר לארה\"ב וכיהן כרב בניו יורק. חיבר \"ברכה משולשת\" גרוסורדין תרצג."},{"i":39607,"n":"פרידמן, שלמה זלמן מראחוב","f":"ישראל חיים מראחוב","b":"תלמיד בעל \"קדושת יו\"ט\" וראש ישיבה. חתן ר שמואל זלמן וינברגר ממארגרטן. רב בראחוב, ניצל מהשואה ואחריה ראב\"ד בסטמר - ועסק בהתרת עגונות. עבר לשוייץ וכיהן כרב בלוגנו, עלה לארץ."},{"i":39608,"n":"פרידמן, שלמה זלמן מראקושהאדי","dt":"תשד","b":"רב בראקושהעדי-תרצ\"ה"},{"i":39609,"n":"פרידמן, שלמה חיים מסדיגורא","f":"ישראל מסדיגורא","k":"אדמור מסדיגורא","r":"אדמו\"ר מסדיגורא","bt":"תרמז-נז","dt":"תשלב - כו אב","b":"חתן הגביר ר שמואל הורנשטין מרדומישל. אדמור מסדיגורא על מקום אביו (יחד עם אחיו), עבר לוינה-תרעד ועזב את האדמורות. חזר לאדמורות על מקום אחיו ר אברהם יעקב. פעל להצלת ילדים מהמסיון. היה פעיל בתנועה הציונית ובמזרחי. עלה לארץ-תרצח והתגורר בתל אביב, ונהג אדמורות רק לאחר פטירת אחיו. מתורתו ב\"אמרי קודש\", פרסם מאמרים בעתוני זמנו. תולדותיו ומתורתו בקובץ \"דברים בעתם\", חיבר \"לאזרח בישראל\" תל אביב תשיח.","bk":[["חיי שלמה – עה\"ת",""]]},{"i":39610,"n":"פרידמן, שלמה מאויהל","f":"יעקב מקארלי","k":"ר שלמה טשעטשאויצער","dt":"תרעט - תשרי","b":"תלמיד בעל \"ייטב לב\" בסיגט."},{"i":39611,"n":"פרידמן, שלמה מבאדן תל אביב","f":"דוד מצעהלים","bt":"תרכט","dt":"תשכז - כג חשון","dp":"בני ברק","b":"רב בווינר-באדען-תר\"ע,עלה לתל אביב-תרצ\"ט"},{"i":39612,"n":"פרידמן, שלמה מלמברג","f":"שלמה","k":"בעל נחלי דבש","bt":"תרעב","bp":"למברג","dt":"תשב","b":"חיבר \"נחלי דבש\" למברג תרפט."},{"i":39613,"n":"פרידמן, שלמה מסדיגורא","f":"אברהם יעקב מסדיגורא","bt":"תרד","bp":"קרלין","dt":"תרמא - יז-כ שבט","b":"נכד לר ישראל מרוזין ולר אהרן מקרלין. חתן ר צבי הירש מרימנוב, ובזיוו\"ש חתן דודו ר דוד הלפרין-חתן ר ישראל מרוזין. סייע לאביו באדמורות. נפטר בחיי אביו. תלמידו ר מאיר לייביש לנגרמן מטורקא הביא מתורתו בספריו."},{"i":39614,"n":"פרידמן, שלמה מצורטקוב","f":"נחום מרדכי מצורטקוב","k":"אדמור מצורטקוב","r":"האדמו\"ר מטשורטקוב","bt":"תרנד","bp":"צורטקוב","dt":"תשיט - טו חשון","b":"חתן דודו ר ישראל מסדיגורא. אדמור מצורטקוב בתל אביב על מקום אביו. חיבר \"דברי שלמה\" ירושלים תשכא.","bk":[["דברי שלמה – מועדים",""]]},{"i":39615,"n":"פרידמן, שלמה משקלוב","k":"ר' שלמה פרידמן-החוזר","b":"רב בשקלאוו-תק\"צ"},{"i":39616,"n":"פרידמן, שמאי מקראקא","f":"בן ציון הכהן מדובצק","k":"בעל בית שמאי","b":"מחכמי קראקא. חיבר \"בית שמאי\" קראקא תרץ. ?? לא באוצר ??"},{"i":39617,"n":"פרידמן, שמואל","f":"יוסף אליעזר פרידמן","b":"רב-שנת תר\"כ. חתן ר אהרן לפישיץ מבליניץ."},{"i":39618,"n":"פרידמן, שמואל בנימין מהונגריה","f":"אברהם חנוך מסטמר","b":"נינו של החת\"ס. מראשי הקהל ואגודת ישראל. אחיו - ר יהושע פאלק מקאשוי."},{"i":39619,"n":"פרידמן, שמואל דוד כץ מחוסט","f":"צבי מברגסאס","k":"בעל אבני צדק","bt":"תריח","dt":"תרצג","b":"נכד ר שמואל-אב\"ד פאטאליטש. מו\"צ בוורצקי-תרמט, דיין בחוסט, ובנו ר יעקב הכהן פרידמן על מקומו אחריו. חיבר גם \"הרי בשמים\", \"הרי השדה\", ועוד. ?? לא באוצר ??"},{"i":39620,"n":"פרידמן, שמואל מביאלה","b":"רב בביאלא-ת\"ר"},{"i":39621,"n":"פרידמן, שמואל מסערדאהלי","f":"אברהם צבי מצאנז","dt":"תשד","dp":"בודפשט","b":"חתן ר אריה ליב הלברשטם ממושינה וקעזמרק. רב בסערדאהעלי."},{"i":39622,"n":"פרידמן, שמחה מטשען","bt":"תקפו","dt":"תרנג","b":"רב בליבכוביץ, טשען-תריח."},{"i":39623,"n":"פרידמן, שמעון יהודה מלובלוי","f":"ישראל יעקב מפעטשי","bt":"תרב","dt":"תרפד - יז אד\"ב","dp":"לובלוי","b":"תלמיד הכת\"ס. חתן ר פרץ מנדלר. רב בלובלוי-תרלב."},{"i":39624,"n":"פרידמן, שמעון מגלנטא","f":"אהרן","bp":"נייטרא","dt":"תרנא - כד כסלו","dp":"גלנטא","b":"תלמיד החת\"ס. רב בהעלישטאבא לאחר פטירת דודו ר שלמה שטרן-תרד, רב בסערדאוהל-תריז, יאלע-תרך, אגעדא - עזב לאחר שהקהלה לא הצטרפה אליו בזמן פירוש הקהלות האוטודוכסיות, גלנטא-תרלב, חתנו ר משה פלדמן על מקומו אחריו. מתלמידיו - אחיינו ר דוד זלצר והביא ממנו בספרו \"דברי דוד\"."},{"i":39625,"n":"פרידמן, שמעון מדזיקוב","f":"מאיר חיים מגורליץ","k":"בעל אמרי שמעון","bt":"תקץ","bp":"גורליץ","dt":"תרסה","b":"חתן ר משה ספיר מדזיקוב. חבירו של ר אליעזר הורביץ מדזיקוב. רב בדזיקוב. חיבר \"אמרי שמעון\" מונקטש תרסו. פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח."},{"i":39626,"n":"פרידמן, שמעון מלובליניץ","f":"מאיר","k":"בעל דברי ישעיהו","bt":"תרי","b":"נכד ר שמעון הלוי פוגלמן. תלמיד ר דב צומבר מברלין, ביהמ\"ד לרבנים בברלין. רב בלובליניץ-תרלח-פרוסיה. חיבר גם \"דרשות למועדים\", \"ארבע דרשות\", ועוד. חתנו - ר חיים אופנהים מטאהרן, ר אהרן מנדל מוינה."},{"i":39627,"n":"פרידמן-איש שלום, יצחק איזיק","f":"יוסף","k":"בעל אמרי בינה","bt":"תרלד","bp":"יקטרינוסלב","dt":"תשד - ז תשרי","b":"נולד במושבה יהודית בפלך יקטרינסלב. תלמיד ישיבות טלז, קובנא. רב בגרוזד-תרסה על מקום ר אהרן ולקין, קורשאן-תרעד, רב בארה\"ב-תרפב, טבריג(=טאווריג,טאווריק)-תרפז, עלה לארץ-תרצה וכיהן כרב בנחלת יצחק בת\"א. ממיסדי \"המזרחי\" בליטא. לאחר סגירת ישיבת וולוזין חיבר מחזה \"חזיון סגירת ישיבת וולוזין\" שהוצג בישיבות ליטא. חיבר גם \"חקר יצחק\", \"הגיון יצחק\", \"ישראל ותורתו\", ועוד. פרסם מאמרים ב\"המאור\" - תל אביב תרצה, \"המגיד\" - סטמר תרפח-תרצט."},{"i":39628,"n":"פרידמן-איש שלום, מאיר","k":"בעל מאיר עין","bt":"תקצא","bp":"קאשוי - ליד","dt":"תרסט - כט חשון","dp":"וינה","b":"מגדולי חכמי חכמת ישראל. הו\"ל ספרא ומכילתא עם הגהות בשם \"מאיר עין\". לתולדותיו - בנדיקט, ארשת ב."},{"i":39629,"n":"פרידמן-איש שלום, מרדכי מבערטי","f":"יעקב מטעט","k":"בעל תכלת מרדכי","dt":"תרפח - כז כסלו","dp":"טעט","b":"תלמיד השב\"ס, ור יעקב קופל רייך מבודפשט. חתן ר משה אונגר. רב בשימאני-תרמט, טעט-תרנה, בערטי-אויפלו-תרעב על מקום ר בן ציון בלום. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":39630,"n":"פרידמן-איש שלום, מרדכי מדרזני","dt":"[תרם?]","b":"חתן ר שלמה דייטש מנייטרא. חתניו - ר שמואל שלזינגר-יפה מארניאש, ור משה פישר מאטלנדורף, ור שמואל חיים שור מבוקרשט."},{"i":39631,"n":"פרידן, משה מהמבורג","f":"פנחס ליב מקאמארן","bt":"תקצו","bp":"קאמארן","dt":"תרס - כ אלול","dp":"המבורג","b":"תלמיד הכת\"ס. רב בחאדציזען (מחוז פוזנא)-תרכט, קלמר(=קאלמאר)-תרלג, מחכמי הקלויז בהמבורג-תרלו על מקום ר גוטליב מוזס."},{"i":39632,"n":"פרידן, פנחס ליב מקאמארן","f":"משה לייפניק","k":"בעל דברי פני אריה","bt":"תקסב","bp":"באנהארט","dt":"תרלג - טו סיון","b":"תלמיד ר וולף בוסקוביץ בעל \"סדר משנה\". דיין בבאניהאד. רב בקאמארן(=קומרארום)-תקצז על מקום ר אברהם פריישטט כ-42 שנה. בניו ר מרדכי אליעזר מאדא, ר משה מהמבורג, חתניו - ר מרדכי אליעזר ובר מאדא-ירושלים, ר מרדכי רייכנפלד מינושהאזא, ור שלמה ליפמן ולדלר משלאנק."},{"i":39633,"n":"פרידנברג, ברוך ממוסקבה","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":39634,"n":"פרידנברג, יעקב מקרלסבורג","f":"משה","dt":"תקעח - יח תמוז","b":"רב בזעמלין(=זימון)-קרואטיה, רב בקרלסבורג-תקצח ורב הכולל בטרנסילבניה על מקום ר משה מרגליות."},{"i":39635,"n":"פרידנברג, סנדר מאוסטרובצא","k":"בעל באר בשדה","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"קול תורה\" - וארשא תרסח."},{"i":39636,"n":"פרידנזון, אברהם מקאליש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39637,"n":"פרידנזון, אהרן משה מסלונים","f":"מרדכי","k":"בעל שערי דמעה וישועה","dt":"תרלח - יד אב","dp":"ירושלים","b":"נינו של ר שמואל בעל \"בית שמואל\" על שו\"ע, עלה לירושלים-תריח, חיבר ספר \"שערי דמעה וישועה\" ירושלים תרכא, ו\"הזכרון\" ירושלים תרלד, ועוד בכתב יד."},{"i":39638,"n":"פרידנזון, אליעזר גרשון","bt":"תרס","dp":"גיטו וארשא","b":"מצאצאי ר\"ח אוירבך בעל \"דברי משפט\". עסקן ציבור (מגיל 17!) וסייע לשרה שנירר ביסוד \"בית יעקב\", ממיסדי צא\"י, מיסד תנועת הבנות \"בתיה\", עורך בטאון \"בית יעקב\". נספה בשואה."},{"i":39639,"n":"פרידנזון, דוד הכהן","f":"מאיר","k":"בעל מוסדות תבל","bt":"תקיח","bp":"פריזנהויזן","dt":"תקפח - ח ניסן","dp":"קרלסבורג","b":"מחכמי פירט, ברלין, דיין באונסדורף, דומ\"צ באויהל(=אוהעל)-תקס. חיבר גם \"כליל החשבון\"."},{"i":39640,"n":"פרידנזון, יהושע","b":"רב בקאלנא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. בנו - ר מאיר-רופא בקרלסבורג."},{"i":39641,"n":"פרידנזון, יהושע","f":"שמואל שמלקא פרידנזון"},{"i":39642,"n":"פרידנזון, שמואל מקאליש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39643,"n":"פרידנזון, שמואל שמלקא מלודז","f":"יהושע פרידנזון","k":"בעל מנחת שמואל","b":"דומ\"צ בלודז-תר\"מ"},{"i":39644,"n":"פרידנטל, מרדכי","k":"בעל עיקרי אמונה","b":"תלמיד ר צבי הירש בושקא מגלאגוי ואה\"ו. רב-שנת תק\"נ"},{"i":39645,"n":"פרידנטל, שאול מבאניהאד","f":"יהודה ליב ליסא","dt":"תרמב - כט אד\"א","b":"ראב\"ד בבוניהאד(=בניהאד) על מקום ר יצחק משה פרלס."},{"i":39646,"n":"פרידנטל, שמואל מגאיטיין","b":"תלמיד השב\"ס. חתן ר משה הלוי וייס מפרשבורג. רב בגאיטיין-תרע-תרפב."},{"i":39647,"n":"פרידנס, ישראל מליברפול","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":39648,"n":"פרידנשטין, שמעון אליעזר","k":"בעל עיר גיבורים","bt":"תריב","bp":"הורדנא","b":"תלמיד ר נחום מהורדנא. פרסם-תרלח ב\"הקול של ראדקינזאן\" מאמר \"צעקת ענוים\", \"כנסת הגדולה\" - וארשא תרן, ועוד מאמרים בעתונים שונים. חיבר גם \"תקות ישראל\" - תרן, \"עץ פרי\", ועוד."},{"i":39649,"n":"פרידעל, ישראל מבאלעט","b":"אב\"ד באלעט-תרסח."},{"i":39650,"n":"פרידפלד, אברהם מטרנופול","b":"שו\"ב בטרנופול."},{"i":39651,"n":"פרידפלד, צבי הכהן מטרנופול","b":"מחכמי טרנופול. תשובה אליו - \"מהרש\"ם\"."},{"i":39652,"n":"פרידריך, אלחנן מפילעק","dt":"תשד","b":"רב בפילעק"},{"i":39653,"n":"פרידריך, חיים מטורץ","f":"יהודה משארוש-פאטאק","dt":"תרסא- טו אב","b":"אביו ר יודל חסיד היה מהחסידים הראשונים בהונגריה שנקראו חסידי \"אש ואור\" - על שם הכפר אשוואר-מחוז סאבולץ'. רב בטורץ-ליד סטמר-תרכח כ-33 שנה. חתנו - ר יצחק קליין מסטמר עורך \"אהל יצחק\"."},{"i":39654,"n":"פרידריך, חיים שלמה","dt":"תשד","b":"רב בקיראליהלמץ"},{"i":39655,"n":"פרידריך, חנניה יו\"ט ליפא מפילק","f":"יצחק איזיק מהומנא","dt":"תשד - כב סיון","b":"תלמיד הדעת סופר. חתן ר שמואל בניימין הלי גונגרייז מפילעק. רב בפליעק לצד חותנו. נספה בשואה."},{"i":39656,"n":"פרידריך, יעקב","b":"תלמיד ישיבה (בית אברהם - וארשא?). פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":39657,"n":"פרידריך, יצחק איזיק מטורץ","f":"חיים מטורץ","bt":"תרלה-ט","bp":"טורץ","dt":"תרפז - י חשון","dp":"הונא","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט. חתן ר דוד יהודה ליב זלצר מהומנא. דיין בהומנא לצד חותנו. רב בטורץ-תרסא על מקום אביו, רב בהומנא-תרעט על מקום חותנו."},{"i":39658,"n":"פרידריך, ישראל מקראקא","b":"מחכמי קראקא-תרצג. תשובה אליו - \"מנחת אברהם\"."},{"i":39659,"n":"פרידריך, מאיר מקראקא","b":"מחכמי קראקא. תשובה אליו - \"דובב מישרים\"."},{"i":39660,"n":"פרידריך, מרדכי צבי","b":"פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":39661,"n":"פרידריכסלפד, דוד מאמשטרדם","f":"צבי הירש","k":"בעל זכר צדיק","bp":"ברלין","dt":"1810","b":"מקורב למנדלסון בברלין, עבר לאמשטרדם. פרסם מאמרים וספרים, ובהם \"זכר צדיק\" - תולדות נפתלי הרץ ויזל, \"מענה רך\", ועוד. פעל למתן זכויות ליהודי הולנד."},{"i":39662,"n":"פרידריכספלד דוד בן צבי הירש","bt":"1755","dt":"ה'תקע 1810","bk":[["מענה רך",""]]},{"i":39663,"n":"פריווס, משה","f":"ישעיה","b":"חתן ר חיים אלעזר וקס מקאליש בעל \"נפש חיה\". חתנו ר מנחם מנדל אלתר מגור."},{"i":39664,"n":"פריז, אריה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":39665,"n":"פריזאק, מרדכי מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":39666,"n":"פריזמן, אברהם יוסף מזגוריצה","f":"חיים נחום","bt":"תר","b":"רב בזגוריצה-בסרביה-תרנט. נסמך מאת רי\"ש נתנזון מלבוב. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":39667,"n":"פריזנהוזן, מאיר מקרלסבורג","f":"דוד","b":"רופא בקרלסבורג בזמן ר יחזקאל פנט."},{"i":39668,"n":"פריזר, שאול דוד מליביטשוב","f":"ראובן מליביטשוב","b":"גביר מחכמי ליביטשוב. הדפיס \"מגילת יחוסין\" של המשפחה - ליביטשוב תרנז."},{"i":39669,"n":"פריי, יוסף שמואל","k":"בעל דקדוק עברי","b":"חיבר \"דקדוק עברי\" ניו יורק תקפג."},{"i":39670,"n":"פריי, יצחק צבי מסערדאוהל","f":"משה פרייא פאל","bt":"תרז","bp":"סערדאוהל","dt":"תרעו - י שבט","dp":"סערדאוהל","b":"תלמיד הכת\"ס, וקרובו ר משה הרצפלד רו\"מ מסערדאוהל, ור יהודה אסד. חתן רבו הכתב סופר. מחכמי סערדאוהל."},{"i":39671,"n":"פריי, ישעיה מלעמעש","f":"מאיר יהודה ליב משורן","bt":"תרסד","bp":"שוראן","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר משה דייטש מלעמעש. רב בלעמעש-תרפח על מקום חותנו, רב בשוראן. נספה בשואה."},{"i":39672,"n":"פריי, מאיר יהודה ליב משוראן","f":"יצחק צבי חתן הכת\"ס","k":"בעל שבט מישור","bt":"תרלח","bp":"סערדאוהל","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור נח ברוך פישר מפרשוב, ר כלב פיבל שלזינגר מטאפלאטשן, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. חתן ר ישעיה ארנפלד משוראן. רב בשוראן-תרסג על מקום חותנו וראש ישיבה, בזיוו\"ש חתן ר יעקב קופל קרויס מאטש (אלמנת ר משה וינקלר ממארטינסברג). ממנהיגי אגו\"י. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"עמק הלכה\" - באטארקס תרפא, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":39673,"n":"פריי, מאיר מוויצען","f":"משה זאב פרייא-פאל","b":"תלמיד הכת\"ס, ור יהודה אסאד. רשם בכת\"י מתורת רבותיו."},{"i":39674,"n":"פריי, משה","dt":"תשג","b":"רב בנעדיעד"},{"i":39675,"n":"פרייא, יצחק משטמפן","b":"דיין ומו\"ץ ומלמד לילדים בשטאמפי-תקי."},{"i":39676,"n":"פרייברג, יהודה אריה מקרשניק","dt":"תשא","b":"רב בוונווליץ,קרשניק"},{"i":39677,"n":"פריידיגר, אברהם מבודפשט","f":"משה מבודפשט","b":"ראש הקהלה בבודפשט."},{"i":39678,"n":"פריידיגר, יצחק איזיק מהעלישויא","k":"בעל זכרון יצחק","b":"רב בהעלישויא. נכדו - ר יקותיאל קויפמן הו\"ל את ספרו \"זכרון יצחק\" עם הוספות."},{"i":39679,"n":"פריידיגר, יקותיאל קויפמן מבודא","f":"משה מבודפשט","bt":"תרלג","bp":"בודפשט","dt":"תשז - ל אב","dp":"ציריך","b":"תלמיד השב\"ס, חתן ר אברהם הכהן אורנשטין מקיוב. מחשובי חכמי בודפשט. ניצל מהשואה ועבר לשוויץ. הו\"ל ספר זקנו ר יצחק איזיק \"זכרון יצחק\" עם הוספות ממנו."},{"i":39680,"n":"פריידיגר, משה מבודפשט","f":"פנחס יהודה ליב מאובן","k":"בעל משה ידבר","bt":"תקעח","dt":"תרנז","b":"חתן ר יצחק ליב סופר-בנו של הכת\"ס. סירב לרבנות. פרנס ומנהיג ק\"ק \"יראים\" בבודפשט. בניו - ר אברהם - ראש הקהל בבודפשט, ר יקותיאל קויפמן פריידיגר מבודפשט, ר פנחס דוד-חתנו של ה\"דעת סופר\". חתנו - ר אברהם מאיר בלוי מבודפשט. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":39681,"n":"פריידיגר, פנחס דוד מבודפשט","f":"משה מבודפשט","b":"חתן הדעת סופר. ראש הקהלה החרדית בבודפשט. עלה לירושלים, בני ברק."},{"i":39682,"n":"פריידיגר, פנחס יהודה מאויבן","f":"יצחק איזיק-זכרון יצח","bp":"העלישוי","dt":"תריח - כב תמוז","dp":"בודפשט","b":"רב באיזשאק, ראב\"ד באויבן על מקום ר מאיר ליב אסטרייך ור\"מ בישיבה ור יצחק גבריאל גראג על מקומו אחריו. בנו - ר משה בעל \"משה ידבר\"."},{"i":39683,"n":"פריידין, ברוך שלום","dt":"תשג","b":"רב במלדצנה"},{"i":39684,"n":"פריידין, דב מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":39685,"n":"פריידין, יהושע","k":"בעל אבן יהושע","b":"רב באזרניצה-תר\"ס"},{"i":39686,"n":"פריידין, מאיר יהודה ממירהאראד","f":"צבי הירש","bt":"תרכ","b":"רב במירהאראד ישן-פלך פולטובה-תרנה."},{"i":39687,"n":"פריידין, מנחם מנדל מטשרני","f":"שמואל","k":"בעל עליות מנחם","b":"רב בטשארני(=צארי?)-תרסז, בראנזוייל-ארה\"ב."},{"i":39688,"n":"פריידין, שמואל מפליסא","f":"לוי יצחק","bt":"תרלח","b":"תלמיד ישיבת \"תומכי תמימים\"-חב\"ד. רב בפליסא-פלך וילנא-תרסה. אחיו של ר מנחם בעל \"עליית מנחם\"."},{"i":39689,"n":"פריידינגר, שלמה מאיר","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":39690,"n":"פריידקין, יוסף ליב","b":"רב-שנת תר\"מ"},{"i":39691,"n":"פריידר, אברהם מרעדניק","b":"רב ברענדיק-ת\"ר"},{"i":39692,"n":"פריידר, משה","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":39693,"n":"פריידר, נתן מטשארני","k":"בעל צמח השדה","bt":"תקסג","dt":"תריז - כח אלול","b":"דיין בצעהלים-הונגריה, רב בצעהלים על מקום ר משה סגל גלוגא, רב בטשארנא(=צ'ורנא). עמד בקשרי שו\"ת עם החת\"ס."},{"i":39694,"n":"פריידש, שלמה מליאדי","k":"בעל כרם חמד","b":"רב בליאדי, סאמראן. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, פרסם מאמרים ב\"יגדיל תורה\" - אודסה תרלט, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"מכילתא דרבנן\" - אודסה תרמו, \"שמעתתי דרבנן\" - אודסה תרמז, \"תורה מציון\" - ירושלים תרנה-תרסה. אחיו: ר נחום טוביה אב\"ד פיראטין ורעטשיצע, ר מרדכי אידל אב\"ד סעווינישאק, ר שמואל בן ציון רשל אב\"ד סעניא."},{"i":39695,"n":"פריידש, שלמה משקלוב","b":"תלמיד בעל התניא. חתן ר מרדכי בן אליעזר צייטליש. רב בשקלאב-תק\"צ. בנו - ר יוסף אליעזר פרידמן. חתנו - האדמור ר יהודה ליב שניאורסון מקאפוסט (בן הצמח צדק)."},{"i":39696,"n":"פרייוירט, ישראל אברהם","f":"שלמה זלמן","dt":"תש..","b":"חסיד צורטקוב, עבר מקראקא לפרימישלן, לבוב-תרץ. נספה בשואה. פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":39697,"n":"פרייז, ישכר הלוי מוירצבורג","bt":"תרב","bp":"אמשטרדם","dt":"תרעג","b":"תלמיד השב\"ס. חתן ר משה טוביה לעהמן מפרשבורג - חתנו של החת\"ס. מחכמי וירצבורג. בנו ר יוסף עקיבא פרייז - רב בברסלוי."},{"i":39698,"n":"פרייזיס, בנימין זאב מאויבן","f":"שמואל מאויבן","b":"דיין באויבן."},{"i":39699,"n":"פרייזיס, שמואל מאויבן","f":"יצחק","b":"ראב\"ד באויבן. מכונה פרייזיס על שם אמו \"פרייזי\" שהיתה מפורסמת בצדקתה."},{"i":39700,"n":"פרייל, אלעזר מאיר ממנצסטר","f":"אלחנן","k":"בעל המאור","bt":"תרמא","bp":"בירז'-ליטא","dt":"תרצד - יד תשרי","b":"תלמיד ישיבות שאדובה, טלז. רב בשאדובה, בשליחות ישיבת טלז באנגליה, ונתקבל לרב במנצסטר-תרסז, רב בניו יורק-תרעא, רב בטרנטון, אליזבט-ארה\"ב, ר\"מ בישיבת \"רבי יצחק אלחנן\" בנ\"י. הו\"ל כתבי אחיו ר יהושע יוסף. עורך \"היכל התורה\" - נ\"י תרצג. פרסם מאמרים בהלכה ובשאלות הזמן ב\"יגדיל תורה\", \"הפרדס\", \"מגדל תורה\" - נ\"י תרפה, \"שערי ציון\" - ירושלים תרפא."},{"i":39701,"n":"פרייל, יהושע יוסף מקרוק","f":"אלחנן","k":"בעל אגלי טל","bt":"תריח","bp":"בירז'","dt":"תרנו","dp":"קובנא","b":"תלמיד ר אשר ניסן מבירז, ישיבות ואבלוניק, ואיישישוק, שוינציאן. חתן ר חיים שפירא-בן אחי ר ליב שפירא. רב בקרוק(=קראקי)-מחוז קידאן-תרמה על מקום ר מאיר רבינזון שעבר לשוינציאן. פרסם מאמר נגד ר י' הוזנטהל (בתגובה למאמרו \"אל רועי ישראל\") שעשה רושם רב בשעתו. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"הפלס\" - ברלין תרסא-תרסה."},{"i":39702,"n":"פרייליך, בן ציון","dt":"תש","b":"רב בוורקא"},{"i":39703,"n":"פרייליך, חיים מקראקא","b":"מחכמי קראקא. תשובה אליו - \"אור המאיר\"."},{"i":39704,"n":"פרייליך, יצחק דוד מנור","f":"אהרן","bt":"תרכג","b":"נכד רי\"ז מקוזניץ, ונכד ר דוד טביל מטצעפלאוו-בנו של ר אלעזר הכהן רפפורט מפיאסק. רב בנור-פלך לומזה-תרמט."},{"i":39705,"n":"פרייליך, ישעיה נתן מסבדאקה","b":"תלמיד ר משה גרינולד בעל \"ערוגת הבשם\". שו\"ב בהונגריה. נסמך להוראה ע\"י רבו ואחרים. רב ושו\"ב בסאבדאקה. הו\"ל \"שערי דורא\" עם פירוש והגהות ממנו בשם \"שערי בינה\"."},{"i":39706,"n":"פרייליך, מרדכי מוישנא","b":"מחכמי וישנא. ממשתתפי \"אסיפת חכמים\" - תרעב."},{"i":39707,"n":"פריימן ישראל מאיר מטושין","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג. אולי הוא שהיה רב באוסטרובה."},{"i":39708,"n":"פריימן, אהרן","f":"ישראל מאיר-ענפי יהוד","b":"חתן ר מרדכי הורביץ בעל מטה לוי. חיבר עם ר מאיר הילדסהיימר - \"ברכת אברהם\"."},{"i":39709,"n":"פריימן, ארצ'יבלד","bt":"1880","bp":"וירבאלן","dt":"1944","dp":"אוטאווה","b":"היגר בילדותו לקנדה. נשיא ההסתדרות הציונית בקדנה, נשיא \"עדת ישורון\" באוטאווה. סייע להביא מאות יתומים יהודים מאוקראינה לאוטאווה לאחר מלחמ\"ה ה-I. תורם למפעלים ציוניים ואחרים."},{"i":39710,"n":"פריימן, י' יצחק","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":39711,"n":"פריימן, יצחק איזיק מקראקא","b":"שו\"ב בלייפציג. הוציא לאור \"חדושי אנשי שם\" למהרש\"ק."},{"i":39712,"n":"פריימן, ירחמיאל מאלכסנדר","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":39713,"n":"פריימן, ישראל מאיר מאוסטרובה","f":"יהודה","k":"בעל ענפי יהודה","dt":"תרמד - ב אלול","dp":"אוסטרובה?","b":"חתן ר יעקב יוקב עטלינגר מהמבורג. תלמיד ישיבות הונגריה, ובעל תואר ד\"ר. רב בפילענע(=פולעהנע), אוסטרובה-תרלב. הו\"ל ספר \"והזהיר\" עם פירוש ממנו בשם \"ענפי יהודה\". בניו - ר אהרן, ר יעקב."},{"i":39714,"n":"פריימן, מאיר מניו יורק","k":"בעל תורת מאיר","bt":"תרג","b":"תלמיד ישיבת וולוזין, היגר לארה\"ב-תרכו והיה שו\"ב. עסקן צבורי ופעל לטובת בתי חסד וצדקה, ויסד ת\"ת - וייעד לו את הכנסות ספרו. חיבר גם \"יד מאיר\" צפת תרעג. חיבר גם \"מטעי מאיר\" סט לואיס תרפג, ועוד."},{"i":39715,"n":"פריימן, מנחם מנדל מערזשעבעט","b":"רב בערזשעבעט-וארוש-תרס עד מלחמת העולם ה-I."},{"i":39716,"n":"פריימן, מנשה מאלכסנדר","b":"ר\"מ בישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":39717,"n":"פריינד, אברהם יהושע מנאסוד","f":"משה אריה מסיגט","k":"אדמור מנאסוד-מלחמת ח","bt":"תרטו","bp":"סיגט","dt":"תרצב - יא אלול","b":"אחיו של הגביר ר חיים פריינד מסטמר. תלמיד מהרם שיק בחוסט, והדברי חיים מצאנז. חתן ר מרדכי יהודה לעוו מאינטרדאם, ועבר לשם. רב בראדנא-תרלט בגליל הרבנות של חותנו. רב באינטרדם ונאסוד-תרסה על מקום חותנו. והחל לנהוג אדמורות וכיהן כאדמור מנאסוד לחסידי צאנז-קלויזנבורג. קנאי ומתנגד לציונות - והיה מחלוקת בקהילה כשאסר שחיטתו של השוחט ר דוד מושקוביץ שנטה לדעות ר משה שמואל גלזנר מיסד הציונות הדתית בטרנסילבניה. נכדו ר משה אריה פריינד - ראש ישיבה סטמר בירושלים, הו\"ל את ספרו \"מאור יהושע\"-ירושלים תשכז. לתולדותיו \"הדרת קודש\" לר אפרים בן אברהם פרידמן. בניו: ר חנוך הניך אב\"ד רוגנא, ר ישראל אב\"ד הוניאד, ונכדו ר משה אריה מירושלים. הסכים על \"שערי דעה\" - קלויזנבורג תרפח. חיבר \"מלחמת חובה\".","bk":[["מאור יהושע – שו\"ת",""]]},{"i":39718,"n":"פריינד, אברהם מבירשאף","b":"אב\"ד בירשאף. הסכים על \"עקידת יצחק\" פרשבורג תרח."},{"i":39719,"n":"פריינד, אברהם מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":39720,"n":"פריינד, אלימלך מאינטרדם","f":"חנוך הניך","dt":"תשד","b":"נכד ר אברהם יהושע פרידמן. רב באינטרדם-תרצג על מקום זקנו - את רבנות נאשוד ירש אחיו ר משה אריה. נספה בשואה."},{"i":39721,"n":"פריינד, אלכסנדר יעקב","dt":"תרעו - שבט","dp":"ירושלים","b":"תלמיד בעל דברי חיים מצאנז. חתן ר יחזקאל משלם טלר מניר-באכטא. רב בניר-באכטא-הונגריה,,עלה לירושלים-תרם, נזכר בשו\"ת מהרם שיק, וב\"פרי השדה\". חיבר כרוז מודפס (דף בודד) לאיסור מצות מכונה - ירושלים תרסח. מצאצאיו משפחות פריינד, בריכטא, וייספיש ועוד."},{"i":39722,"n":"פריינד, אריה ליב","b":"דומ\"צ בנאד-שאללא-תר\"י"},{"i":39723,"n":"פריינד, אשר מירושלים","f":"אריה מרדכי","b":"נכד היהודי הקדוש מפשיסחא. חתן ר אברהם שטרנברג מצפת. רב בירושלים-תשי ועומד בראש אגודות חסד \"יד עזרה\" בירושלים ובאשדוד."},{"i":39724,"n":"פריינד, ברוך מהוניאד","f":"ישראל מהוניאד","dt":"תשד - יג סיון","b":"חתן ר נפתלי מווישניץ. אדמור מקומי בהוניאד לחסידי זקנו ר אברהם יהושע מנאסוד. רבנות העיר נשמרה לחתנו - ר מנחם מנדל פאנט-תשב. נספה בשואה."},{"i":39725,"n":"פריינד, דוד אריה יהודה מסאסרגן","f":"ישראל מסאסרגן","k":"בעל פרדס דוד-תשמו","dt":"תשמה - כג ניסן","b":"תלמיד ר יעקב יחזקיה גרינוולד בהוניאד, ור שאול בראך בקאשוי. חתן ר יחזקאל פאנט מדעש, ובזיוו\"ש גיסו של ר אברהם יצחק קאהן האדמור מתולדות אהרן בירושלים. פעיל באוגת ישראל ברומניה. רב הצעיר בסאסרגן לצד אביו. רב בקהילת יוצאי טרנסילבניה בבוקרשט. ניצל מהשואה, ואחריה רב בסאסרגן ומחברי ארגון הקהלות האורטודוכסי. עלה לארץ וכיהן כרב בנתניה, עבר לירושלים. חיבר גם \"אלופי יהודה\" ובו מתולדות המחבר."},{"i":39726,"n":"פריינד, חנוך הניך מאינטרדם","f":"אברהם יהושע מנאסוד","dt":"תרצב - כא אב","b":"רב הוראה באינטרדם, אצל אביו. לפי אלפסי היה רב ברוגנא והוניאד - ונספה בשואה."},{"i":39727,"n":"פריינד, טוביה גדליה מקראלי","f":"יהושע מקראלי","dt":"תרלט - יט שבט","dp":"ירושלים","b":"תלמיד החת\"ס. חתן ר משה צבי עהרנרייך. מחכמי קראלי, עלה לירושלים."},{"i":39728,"n":"פריינד, יוסף שמואל מירושלים","f":"יהושע מקראלי","dt":"תרכח - ו אלול","dp":"ירושלים","b":"מחכמי ירושלים. אחיו - ר טוביה גדליה, ר אברהם יעקב משה."},{"i":39729,"n":"פריינד, יעקב מפרמישלא","f":"יונה אברהם","k":"בעל שארית יעקב","b":"מחכמי בוריסלוב-תרלה. חיבר \"שארית יעקב\" פרמישלא תרץ."},{"i":39730,"n":"פריינד, יעקב שלום מבני ברק","f":"ישראל מסאסרגן","b":"ר\"מ בבני ברק."},{"i":39731,"n":"פריינד, ישראל מהוניאד","f":"אברהם יהושע מנאסוד","dt":"תש - א-ב אד\"ב","b":"תלמיד בעל \"קדושת יו\"ט\" בסיגט. חתן ר זאב גולדברגר מהוניאד. רב בראדנא-תרסד על מקום אביו, הוניאד-תרץ על מקום חותנו (אולם למעשה נבחר במקומו ר צבי קינסטליכר והיה מחלוקת ודין תורה על כך). סירב לאדמורות, מחשובי חסידי ר יואל טיטלבוים - ויואל משה. בנו ר משה אריה ראש ישיבת סטמר בירושלים."},{"i":39732,"n":"פריינד, ישראל מסאסרגן","f":"משה או סיני","k":"בעל שארית ישראל-תשמו","bt":"תרמה","bp":"הונגריה","dt":"תשד - טו סיון","dp":"אושוויץ","b":"נכד ר אריה ליב פריינד משאלא. תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין, ור שלמה זלמן ברייער בפפד\"מ. חתן ר משה דוד סופר מסאסרגן. רב בסאסרגן(=סאס-רעגין)-תרעא על מקום חותנו למעלה מ-30 שנה, נתמנה לרב בפראשוב אולם נשאר בסאסרגן. נספה בשואה. חיבר \"שארית ישראל\" בסוף \"אלופי יהודה\" ו\"פרדס דוד\" לבנו ר דוד יהודה מסאסרגן. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"לקט ששנ\"ה\" - סטמר תרצד, \"וילקט יוסף\"."},{"i":39733,"n":"פריינד, מרדכי יהודה ממישלניץ","b":"ר\"מ בישיבת בובוב במישלניץ."},{"i":39734,"n":"פריינד, מרדכי יהודה מראדנא","f":"ישראל מהוניאד","dt":"תשד","b":"חתן ר יצחק מרישא בן שלום מקמינקא. רב לצד אביו בראדנא והוניאד. רב בראדנא-תרצח על מקום גיסו ר אשר שטינמץ. נספה בשואה. מתורתו בספר גיסו ר אשר שטינמץ \"מקוה ישראל\"."},{"i":39735,"n":"פריינד, משה אריה מירושלים","f":"ישראל מראדנא והאניאד","r":"גאב\"ד העדה החרדית ירושלם","bt":"תרסד","dt":"תשנו","dp":"ירושלים","b":"רב ומנהל הישיבה בראדנא. ניצל מהשואה, ואחריה רב בסטמר. עלה לארץ וכיהן כראש ישיבת \"ייטב לב\" בירושלים. ראב\"ד העדה החרדית בירושלים-תשם.","bk":[["רבי משה אריה פריינד (רמ\"א)",""],["עטרת יהושע – עה\"ת, ש\"ס, שו\"ת, הגש\"פ, ימים נוראים,",""]]},{"i":39736,"n":"פריינד, משה אריה מנאסאד","f":"אברהם יהושע פריינד","dt":"תשד","b":"רב בנאסאד-תר\"פ"},{"i":39737,"n":"פריינד, משה אריה מנאסוד","f":"חנוך הניך","dt":"תש..","b":"נכד האדמור מנאסוד ר אברהם יהושע פריינד. רב בנאסוד-תרצג על מקום זקנו. חתן ר אשר אנדל כץ מדנוא-סערדאהי. נספה בשואה."},{"i":39738,"n":"פריינד, משה אריה מסיגט","b":"גביר בסיגט."},{"i":39739,"n":"פריינד, משה צבי מסט מיקלוש","f":"ישראל מסאסרגן","dt":"תשה - ו אדר","dp":"מחנה אבנזה","b":"תלמיד הדעת סופר, ור מרדכי בריסק מטאשנד. חתן ר דוד יהודה זילברשטין מוויצען. רב בדיערעש(=גרג'ו)-סט מיקלוש-תרצז. נספה בשואה."},{"i":39740,"n":"פריינד, נחום מרדכי מסטמר","f":"טוביה גדליה מקראלי","dt":"תרס - ז תמוז","dp":"סטמר","b":"חתן ר ברוך מייזלס, ובזיוו\"ש חתן ר סיני יהודה ליב וייס מסטמר. מחכמי סטמר. חתן ר בנימין שנפלד ממיהאלפאלוא."},{"i":39741,"n":"פריינד, נפתלי יוסף מראזאן","f":"אברהם מנחם","k":"בעל פני לוי","bt":"תרכא","bp":"זעליב","b":"תלמיד ר אביגדור יהודה ליבוש הלוי לוונטל מקויל. חתן ר אשר גינצבורג בן ר מנחם נחום מסוכטשוב. רב בקאדני-תרמה, באשניץ-פלך שדליץ, ראזאן-פלך לומזה. קיבל אות כבוד מהקיסר על פעילותו הציבורית. חתניו: ר זאב בערגסון מוואלאמין,ר מנחם בנימין פומרנץ מוארשא."},{"i":39742,"n":"פריינד, קלמן מפרשבורג","b":"ממיסדי האגודה הציונית \"יגדיל תורה\" (ששינתה שמה ל\"אהבת ציון\") בפרשבורג - אחרי תרנז - שעסקה בלימוד גמרא למשתתפיה."},{"i":39743,"n":"פריינד, שמואל מפרג","f":"ישכר בר","k":"בעל עיר הצדק","bt":"תקנח","b":"תלמיד בעל \"ברוך טעם\", ר צבי רנשבורג, בעל \"שמן רוקח\". דיין בפרג-תרי, ונלחם כנגד הריפורמים. חיבר גם \"אמרות טהורות\", \"פתשגן האגרת\" - כנגד \"דרכי המשנה\" לפרנקל, ועוד."},{"i":39744,"n":"פריינד, שמחה מפרמישלא","b":"מוכר ספרים בפרמישלא-תרנו"},{"i":39745,"n":"פריינד-גרוסהאבר, משה מיינק","f":"יצחק איציק גריסהבר","k":"ר' משה מיונק","bt":"תקנז","bp":"פאקש","dt":"תרלג - ט כסלו","dp":"יינק","b":"תלמיד החת\"ס, ור בנימין זאב בסקביץ מבאניהאד. רב ביינק-תקעה. (באוצר הרבנים - רב בפאקש-קץ?). אחר פטירתו עברה ספרייתו לישיבת בניהאד של ר משה פולק"},{"i":39746,"n":"פריינדליך, אפרים פישל מסאמוש","bp":"פולין","dt":"תרל.. - בערך","b":"רב בסאמוש-אויוואר-תרי, ורב בית הסהר שם. נזכר בשו\"ת מהר\"ם בריסק."},{"i":39747,"n":"פריינטי, אברהם ממכנאס-מרוקו","dt":"תקמא - ו כסלו","b":"מחכמי מכנאס. חיבר שיר לכבוד פסח."},{"i":39748,"n":"פריינטי, דוד ממכנאס","b":"מחכמי מכנאס-שנות ה-תק'. פסק ממנו ב\"תקפו של יוסף\"."},{"i":39749,"n":"פריינטי, יהושע מירושלים","b":"מחכמי ירושלים בזמן ר חיים ן עטר."},{"i":39750,"n":"פריינטי, יעקב מאלגיר","f":"שלמה","k":"בעל ויגש יעקב","dt":"תרנד","dp":"ירושלים","b":"רב באלגיר, עלה לירושלים. חיבר \"ויגש יעקב\" אלגיר תרנד, פירוש לספר המסורה לריב\"ה, דרושים, פירוש על \"מים עמוקים\", ועוד."},{"i":39751,"n":"פריינטי, יעקב מירושלים","b":"מחכמי ירושלים, אחד התלמידים הראשונים בישיבת \"כנסת ישראל\", מתלמידי ר חיים בן עטר וכנראה שהקדים ועלה לפני רבו. בשליחות באיטליה (בזמן עליית ה\"אור החיים\"). נמנה על ראשי הישיבה לאחר פטירת ר חיים, ובשנת תקד בשליחות הישיבה באיטליה."},{"i":39752,"n":"פריינטי, יעקב מפאס","b":"פייטן מחכמי פאס-שנות ה-ר', חתם על התקנות. חיבר קינות."},{"i":39753,"n":"פריינטי, יעקב מתונס ואלגיר","f":"יוסף","k":"בעל שארית יעקב","bt":"תקץ","bp":"תונס","dt":"תרלט","dp":"ענאבא-אלגיר","b":"הגיע מתונס, רב בענאבא-תריט. חתם על זכות קהלת ספרדים בטבריה על כספי קופת רמב\"ה. חיבר \"שארית יעקב\" ירושלים תשמג."},{"i":39754,"n":"פריינטי, שלמה מאיר","k":"בעל אמרי שפר","b":"דיין בבנזרת בשנות ה-תק'. תשובה ממנו עם ר אברהם כרייף, ב\"חוקי חיים\" למהרא\"ח בורג'יל."},{"i":39755,"n":"פריינטי, שם טוב מטנג'יר וצרפת","bt":"תרך","bp":"טנג'יר-מרוקו","b":"מנהל מוסדות כי\"ח בירושלים, קושטא, התישב בפאריס."},{"i":39756,"n":"פרייס, אברהם אהרן מארה\"ב","f":"יוסף","k":"בעל משנת אברהם","r":"אב\"ד ור\"מ טורנטו קנדה","bt":"תרנט","bp":"סטאשוב","dt":"תשנד","b":"נסמך מאת: ר אברהם יצחק סולמן מחמלניק. רב בטורונטו-תרצג, ויסד ישיבה \"תורת חיים\".","bk":[["אמרי אברהם",""],["משנת אברהם - ענינים וספר חסידים",""]]},{"i":39757,"n":"פרייס, אברהם מארה\"ב","b":"גביר ונדבן בניו יורק."},{"i":39758,"n":"פרייס, מנחם מנדל","k":"בעל תפארת מנחם","b":"ראב\"ד בביאלא-תר\"ס"},{"i":39759,"n":"פרייער, שלמה יעקב מג'יור","b":"רב הקהלה הניאולוגית בג'יור-1839 - 1860, ובימיו כיהן כמטיף וכדיין ניאולוגי הרב ד\"ר שלמה רנשנבורג ועל מקומו אחריו."},{"i":39760,"n":"פרייפלד, שמואל ממודרן","b":"רב במודרן-תרס. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":39761,"n":"פריישטט, אברהם יהודה ליב","f":"יוסף פריישטט","bt":"תקה","bp":"גאלגויץ","dt":"תקסח - כט שבט","b":"רב בבוניהאד(=בניהאד)-תקם על מקום ר ישראל בן יהודה אריה. חיבר קינה ליום השריפה הגדולה-תקנד שכילתה את הרובע היהודי ואת בית הכנסת - וביום הזכרון נהגו לומר את הקינה."},{"i":39762,"n":"פריישטט, אברהם מקומורן","f":"שמעון","k":"בעל אמרי שפר","dt":"תקצ - ז-י אב","b":"תלמיד ר משלם איגרא בפרשבורג. רב בקומורן(=קומארום)-תקסג. נזכר בשו\"ת החת\"ס, וה\"נודע ביהודה\"."},{"i":39763,"n":"פריישטט, אהרן משה מפרוינקירכן","f":"קלונימוס פריישטט","dt":"תקנא - כד אדר","b":"רב בפרוינקירכן-תקל\"ג"},{"i":39764,"n":"פריישטט, ברוך מוינה","f":"מיכאל אליעזר","dt":"תרמה - ט אלול","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן גיסו ר זלמן בנדינר מוינה. התגורר בוינה, פדובה."},{"i":39765,"n":"פריישטט, יוסף מהעלישוי","b":"רב בהעלישוי-תק\"כ"},{"i":39766,"n":"פריישטט, יצחק יהודה ליב מוינה","f":"מיכאל אליעזר","bt":"תקעא","bp":"פרשבורג","dt":"תרנו - ח חשון","dp":"וינה","b":"תלמיד החת\"ס. חתן הרב מפורגו מפדובה, ובזיוו\"ש חתן ר יהודה ליב וייס מגירבא. רב בוינה-תקצא וממיסדי הקהלה החרדית - בראשות חתן החת\"ס ר בנימין שלמה שפיצר. התישב בפדובה לרגל עסקיו."},{"i":39767,"n":"פריישטט, קלונימוס","b":"רב-שנת תק\"כ"},{"i":39768,"n":"פריישטט, שמעון מפרוינקירכן","dt":"תקנג - כד סיון","dp":"אויבן(=בודפשט)","b":"חתן ר צבי הירש פריישטט ולפי ברוין - חתן ר מרדכי דייטש בעל מור דרור. רב בפרוינקירכן. בנו - ר אברהם מקאמארן."},{"i":39769,"n":"פריכה, נסים ממצרים","b":"רב במצרים בזמן ר נסים ענקארי, מהריק\"ש ור חיים כפוסי."},{"i":39770,"n":"פריכר, נסים מירושלים","b":"מגדולי רבני ירושלים-ש\"ס"},{"i":39771,"n":"פרילוקר, צבי הירש מבריסק","f":"דוד","dt":"תקף - כד כסלו","dp":"בריסק","b":"מחכמי בריסק-תקנב. נספד ב\"אגודת אזוב\"."},{"i":39772,"n":"פרילוקר-שילל, אברהם צבי","f":"יעקב","k":"בעל שואל אמת","dt":"תרן","dp":"ירושלים","b":"חיבר \"שואל אמת\" וילנא תרמד, אלמנתו - חיה שימא - הו\"ל את ספרו \"משאת יעקב\" ירושלים תרנא אחר פטירתו,"},{"i":39773,"n":"פריליכמן, יצחק איזיק דב","k":"בעל ליקוטי יקרים","b":"חיבר פירוש \"ליקוטי יקרים\" על תהלים - למברג תרלט."},{"i":39774,"n":"פרילמן, אליהו ברוך מירושלים","b":"תלמיד ישיבות ירושלים - עץ חיים, תורת חיים, מאה שערים. מחכמי ירושלים."},{"i":39775,"n":"פרימו, יהודה שמואל","k":"בעל אמרי שפר","bt":"שצד","dt":"תסה-ח - טז סיון","dp":"אדרינופול","b":"גדל במצרים, ואחר כך בסופיה, תלמיד ר יהודה שרף ומזכירו בספרו \"אמרי שפר\". עלה לירושלים ובשנת תכב בשליחות בתורכיה, ראב\"ד באדרינופול-תלא. בצעירותו נטה לשבתאות ואף שימש כמזכירו, אך לימים התחרט ואף גירש את אברהם קרדוזו השבתאי מן העיר. ספרו \"אמרי שפר\" נדפס עם ספרו של חתנו - ר משה הכהן \"כהונת עולם\" קושטא תק. רוב כתביו אבדו בשריפה, וחתנו ר משה הכהן קיבץ מהנשאר והדפיסם בשם \"כהונת עולם\".","bk":[["אמרי שפר",""]]},{"i":39776,"n":"פרימו, שמואל מירושלים ואדרינופ","bp":"מצרים או ברושה","dt":"תסח - טז סיון","dp":"אדרינופול","b":"ש\"ץ בירושלים, סופרו ומזכירו של שבתי צבי, ונזכר ב\"בעי חיי\". חזר בו לאחר המרת ש\"ץ, ונתמנה לאב\"ד באדרינופול. חתנו - ר משה הכהן."},{"i":39777,"n":"פרימו, שמואל מסופיה","b":"גביר בסופיה, העביר שאלה לר שלמה הכהן בשלוניקי בשליחות קהלת סופיה."},{"i":39778,"n":"פרימנשאל, מרדכי בער מברסלוי","k":"בעל יסודי הדת","b":"מחכמי ברסלוי, נזכר-תרג ברשימת המזמינים של הספר מנחם צבי לר צבי הירש דייטש."},{"i":39779,"n":"פרינבאך, יהודה ליב","b":"דיין בברלין-תקלח אל ר צבי הירש מלונדון וברלין."},{"i":39780,"n":"פרינדל, יהודה זונדל מרדכי","f":"נחמיה אריה מעיר ישן","k":"בעל זכרון יהודה","bt":"תקעה","dt":"תרן","b":"רב בעיר ישן (סמבור) על מקום אביו, בנו ר נחמיה על מקומו אחריו. חיבר \"זכרון יהודא\" פרמישלא תרלו."},{"i":39781,"n":"פרינדל, נחמיה מעיר ישן","f":"יהודה זונדל מרדכי","dt":"תרסו","b":"רב בסמבור ישן על מקום אביו."},{"i":39782,"n":"פרינוביץ, יוסף שלמה","k":"בעל געדיכטא","bt":"1871","bp":"אלקסוט-פרבר קובנא","b":"היגר לארה\"ב והתישב בפילדלפיה. חיבר שירים ופרסם בעתונים שונים ובהם \"פאלקס אדווקעט\". לכבודו יצאו כתביו בשני כרכים-1921. ?? לא באוצר ??"},{"i":39783,"n":"פרינס, אברהם מהולנד","b":"רב בהולנד. ניצל מהשואה, ואחריה רב בגרונינגן-הולנד. עלה לארץ-תשי. וכיהן כרב ברחובות."},{"i":39784,"n":"פרינסיפאל, רפאל מסרייבו","b":"רב בסרייבו-שץ."},{"i":39785,"n":"פרינץ, אברהם מאמשטרדם","k":"בעל ליקוטי צבי?","bt":"תקכח","dt":"תריא","b":"תלמיד ר יצחק הלוי מלעמגו באמשטרדם. הניח חיבור בכת\"י יומן זכרונות ובו גם מתורת רבו, ועל קהלת אמשטרדם ועוד."},{"i":39786,"n":"פרינץ, אליעזר ליפמן מאמשטרדם","f":"רפאל","bt":"תקצה","dt":"תרעו - יג חשון","b":"גביר תלמיד חכם ועסקן ציבור באמשטרדם ופרנקפורט. הגהותיו נדפסו בש\"ס וילנא. עמד בקשרים עם גדולי חכמי דורו. מתורתו ב\"פרנס לדורו\". פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. מתורתו ולתולדותיו - \"פרנס בדורו\" - תשנג.","bk":[["פרנס לדורו",""],["פרנס לדורות",""]]},{"i":39787,"n":"פרינץ, גרשון משטרוויץ","b":"גבאי ארץ ישראל לפני השואה."},{"i":39788,"n":"פרינץ, יצחק מפודקמין","b":"מחסידי הוסיאטין בפודקמין-תרסד."},{"i":39789,"n":"פרינץ, משה מקאשוי","b":"מראשי קהלת קאשוי, חתם-תרלג על כתב מינוי ר משה יונגרייז."},{"i":39790,"n":"פרינץ, צדוק מירוסלב","f":"יצחק","dt":"תש","dp":"הולשיץ","b":"מחסידי טיטשין בירוסלב. הרבנית שרה שנירר מאורחות ביתו."},{"i":39791,"n":"פריס, שמלקא מקריסנפולי","b":"רב בקריסנפולי-תרע."},{"i":39792,"n":"פריס-חורב, יהודה מטרנוב ות\"א","f":"יצחק","bt":"תרנה","bp":"טרנוב","dt":"תשיז","b":"עלה לארץ-תרפה, והקים בימ\"ס \"חורב\" בתל אביב ששימש בית ועד לחכמים. ההדיר \"זמירות ישראל\" תל אביב תשו - עם מבוא והערות. חתן ר שמעון הרץ מדזיקוב. פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":39793,"n":"פריסיאדו, בן ציון","b":"מחכמי ירושלים, בשנת תרכה שליח ישיבת \"בית אל\" במצרים, בשנת תרלד בשליחות עדת המערבים"},{"i":39794,"n":"פריסיאדו, ששון מבוסניא וי-ם","f":"משה","k":"בעל שמן ששון-תרכט","bt":"תקפג","bp":"בוסניה","dt":"תרסג - יח ניסן","dp":"ירושלים","b":"מחכמי ירושלים, עלה לירושלים עם אחיו ר אפרים בן ששון, ראש ישיבת \"בית אל\". . בשליחות בבבל והודו. פגש בירושלים את ר יחזקאל שרגא הלברשטם משינווא בנו של ה\"דברי חיים\" שבא לבקרו."},{"i":39795,"n":"פריסקו, אברהם מקושטא","k":"בעל ברך את אברהם","b":"מצאצאי ר משה חיים מקושטא בעל \"ידיו של משה\". רב בקושטא."},{"i":39796,"n":"פריסקו, דוד מקושטא","bt":"תריד","bp":"קושטא","dt":"תרצג - ו כסלו","dp":"ניצה-צרפת","b":"פעיל צבור ממשכילי קושטא, ממתנגדי הציונות והרצל. פרסם מאמרים בעתוני התקופה. הו\"ל \"איל טיימפו\" כ-45 שנה בקושטא, עבר לניצה-צרפת."},{"i":39797,"n":"פריסקו, מרדכי מתבץ","f":"אליהו","b":"רב בתיביץ(=טיווה)-במוריאה-יון בדור שלאחר הגירוש."},{"i":39798,"n":"פריסקו, משה חיים מקושטא","k":"בעל ידיו של משה","dt":"תקסח - ח תשרי","b":"תלמיד ר אליהו פאלומבו בקושטא. ממונה על איסור והיתר בקושטא-תקלז, ואב\"ד-תקן. בניו ר יצחק ור נסים חיים שכתב הקדמה לספר אביו וכיהן כדיין בקושטא. תלמידו ר שמואל חיים חיבר הוא הקדמה לספר רבו. חתם-תקסה על תשובה לר אליעזר די טולידו יחד עם חבריו ר יצחק הכהן ור משה ן זונאנא. חתם גם-תקפז? עם ר אברהם גבאי, ר אליהו צבי ור שמואל חיים. (לפי זה תאריך פטירתו שנה)"},{"i":39799,"n":"פריסקו, נסים חיים משה מקושטא","f":"משה - ידיו של משה","dt":"תרכז - כב אדר","b":"דיין בקושטא, חכם באשי-תקצט-תרא, אב\"ד-תריד. חתם-תקצד על בקשת עזרה עבור קהלת איזנימיט עם ר חזקיה רפאל הכהן ור אליעזר די טולידו."},{"i":39800,"n":"פריעדע, מיכאל יצחק מזדונסקואלא","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":39801,"n":"פריץ, ישראל יהודה משיקגו","f":"יוסף מברסלוי","k":"בעל משכנות ישראל","bp":"ברסלוי","dt":"תשלה - יד אייר","dp":"מנצסטר","b":"תלמיד הדעת סופר. חתן ר דוד יהודה גולדשמיד. רב בקניגסברג-תרפח, שלאנק-תרצב, מארבורג-תרצו, ניצל מהשואה ואחריה עבר לאמריקה. רב בשיקגו-תשט, עלה לירושלים, רב במנצסטר."},{"i":39802,"n":"פריצול, אברהם מפיררה ואויניון","f":"מרדכי","k":"בעל מגן אברהם","bt":"ריא","bp":"אביניון","dt":"רפה","dp":"פיררה","b":"סופר ומעתיק מחכמי איטליה, מוסיקאי. חיבר \"מגן אברהם\" שעב - והוא ספר ויכוח עם הנוצרים - נאלץ להשתתף בויכוח בהוראת הדוכס ארקוליס (כתה\"י היה בידי ר בנימין שלמה מינירבי. עוד חיבר \"ארחות עולם\", \"פרחי שושנים\"."},{"i":39803,"n":"פריצול, וידאל מספרד","b":"מחכמי אביניון(ספרד) בזמן הראשונים, חיבר פירושים על הכוזרי"},{"i":39804,"n":"פריצול, יעקב","f":"חיים וידאל","k":"בעל בית יעקב","b":"חיבר-קפב \"בית יעקב\" - פירוש על ספר הכוזרי, וכנראה שהיה אצל ר יהודה מוסקאטו ונעזר בו בספרו \"קול יהודה\" על הכוזרי."},{"i":39805,"n":"פריצקר, משה מברדיטשוב","f":"אשר","k":"בעל דברי חכמים","bt":"תרכה","dt":"תשיא","dp":"ירושלים","b":"נכד ר ישראל פריצקר בעל \"בית ישראל\". מו\"צ בברדיטשוב-תרמח, עלה לירושלים-תרעח. נסמך מאת: ר יוסף יוזפא אפרתי מברדיטשוב, ר דוד ארטינבורג מברדיטשוב."},{"i":39806,"n":"פריצר, שמואל מהלוסק","b":"רב בהלוסק"},{"i":39807,"n":"פריק, אליעזר ממינסק","b":"שמש בית המדרש במינסק בזמן הגדול ממינסק שהעריך את גדלותו בתורה ודן בשאלה אם מותר לתלמיד חכם כזה להיות שמש מצד כבוד התורה."},{"i":39808,"n":"פריש, אליעזר מטירגאל מטורגל","k":"בעל יכהן פאר","dt":"תרסט - בערך","b":"חתן ר מתתיהו לנדא מפנזשט. רב בטירגאל-פארמאס-תרל ובנו ר אפרים פישל על מקומו אחריו-תרסט, פנזשט על מקום חותנו."},{"i":39809,"n":"פריש, אפרים מארה\"ב","f":"דוד","k":"בעל תקוניו של חזקיהו","bt":"1890","bp":"סובוטש","dt":"1957","dp":"ניו יורק","b":"היגר לארה\"ב. תלמיד היברו יוניון קולג'. רב ריפורמי בניו יורק ומקומות נוספים. מזכיר ועידת הרבנים האמריקאים ועורך השנתון שלה."},{"i":39810,"n":"פריש, אפרים פישל מטורגל","f":"אליעזר מטורגל-יכהן פ","bt":"תרלז","b":"רב ברומניק סאראט-תרסא, טורגול פרומס(=טירגאל פרומאס)-רומניה-תרסט על מקום אביו."},{"i":39811,"n":"פריש, אפרים פישל מפרימישלן","b":"מחכמי פרימישלן - תשובות אליו ב\"שואל ומשיב\"."},{"i":39812,"n":"פריש, ברוך מאיר מצורטקוב","f":"אביגדור צבי ממונקטש","bt":"תקף","dt":"תרנט","b":"מצאצאי ה\"פני יהושע\" (סיפר כי היה לו בירושה פנ\"י על מסכת כתובות וכל פיסקה נסתיימה במלים \"לאו כל מוחא סביל דא\" - וגזר שלא להדפיסו ולגונזו). רב בצורטקוב, סאסוב ושוב בצורטוקב (לאחר מחלוקת שפרצה בין חסידי צורטקוב לבין האב\"ד ר ישעיה מאיר כהנא שפירא), נכדו ותלמידו ר יעקב לנדא על מקומו אחריו."},{"i":39813,"n":"פריש, גרשון מירושלים","f":"נפתלי צבי","bp":"ירושלים","dp":"ירושלים","b":"נאמן ביה\"ח \"שערי צדק\" בירושלים."},{"i":39814,"n":"פריש, דוד מאיר מברזן","f":"יהושע","k":"בעל יד מאיר","bt":"תקעב","bp":"רוהטין","dt":"תרמב","b":"מצאצאי ה\"פני יהושע\". רב בברזן-תקצט, נמנה על גדולי דורו. חיבר \"יד מאיר\" למברג תרמא."},{"i":39815,"n":"פריש, חיים צבי הירש מווהנילוב","b":"רב בווהנילוב, קרליפקה-תרכב."},{"i":39816,"n":"פריש, יצחק איזיק","dt":"תשד","b":"רב בבערעג-ראקוש"},{"i":39817,"n":"פריש, ישראל מטיסמניץ","b":"רב בטיסמניץ."},{"i":39818,"n":"פריש, צבי הירש ליפא מגרודזיסק","b":"רב בגרודזיסק, שיניבה."},{"i":39819,"n":"פריש, שמעון מנשה מבוליחוב","b":"רב בבוליחוב-תרמט."},{"i":39820,"n":"פרישוסר, יהושע מאיר מסאסוב","f":"רפאל","bt":"תרנז","bp":"סאסוב","dt":"תשלו","b":"חסיד בלז. חתן ר שמואל יהודה מברודי. חתן ר שלמה מייער מסאסוב. . ניצל מהשואה והגיע ללונדון (לפני פרוץ המלחמה). בזיוו\"ש חתן ר בן ציון מבובוב. היה גביר ונדיב גדול בלונדון."},{"i":39821,"n":"פרישט, ישראל מאיר מאוסטרבה","b":"הו\"ל \"אור המאיר\" - וארשא תרצו, לזכרו של ר מאיר דן פלאצקי. בעריכת ר אברהם בנימין גלאויטשאווער."},{"i":39822,"n":"פרישמן, דוד יעקב מקדלבורג","f":"אברהם הלברשטט","bt":"תקעב","dt":"תרנב - יב טבת","dp":"קדלבורג","b":"תלמיד החת\"ס. גיסו של ר יעקב קאפל קרויס אב\"ד אטש. רב בקדלבורג-תרלג. (העיד כי החת\"ס היה מקפיד שלא להעמיד יחד את הספרים \"פני יהושע\" עם \"כרתי ופלתי\" וה\"תומים\" - ופעם אחת ראה שהעמידם יחד והסביר לו שגילו לו מן השמים שכבר השלימו הגאונים ז\"ל זה עם זה ובטלה המחלוקת)."},{"i":39823,"n":"פרישמן, יצחק איזיק צבי","b":"רב בווכטרליץ-תר\"ס"},{"i":39824,"n":"פרישמן, יצחק איזיק צבי","f":"דוד יעקב מקדלבורג","bt":"תריד","dt":"תרסז - אב","b":"תלמיד השב\"ס. חתן ר יוסף ברזניץ מואכטרליץ. רב בואכטרליץ-תרלח על מקום חותנו."},{"i":39825,"n":"פרישמן, נפתלי","b":"רב בלודמיר-תרע\"ד"},{"i":39826,"n":"פרישמן, שמעון מטרנוב","b":"נכד מהר\"י מטומשוב, אמו נכדת רבני נרול. חתן נכדת רי\"א נרופשיץ והאור לשמים. מלמד בטרנוב-תרץ."},{"i":39827,"n":"פרישרמן, יהושע מטומשוב","f":"יוסף פרישרמן-גרין","k":"אדמור מטומשוב","bt":"תקפה","bp":"טומשוב","dt":"תרסו - יט תמוז","b":"אביו היה אדמור מיריטשוב וטומשוב ולא הסתייע לו לשבת על מקומו. סירב לאדמורות ולבסוף הסכים וכיהן כאדמור מטומשוב. מקורב לאדמורי דורו. ביקר בארץ מספר פעמים ורצה להתישב בירושלים אך נאלץ לעזוב (לאחר שסטר לזוג שטייל שלובי זרוע בירושלים - והתברר כי המדובר בפקיד נכרי גבוה). בזיוו\"ש חתן ר אריה ליביש קנר מרימנוב, בנו ר יוסף אריה על מקומו בטומשוב."},{"i":39828,"n":"פרישרמן, יוסף אריה ליב מטומשוב","f":"יהושע מטומשוב","k":"אדמור מטומשוב","bt":"תרל","dt":"תרעו - כה אד\"ב","b":"רב ואדמור בטומשוב על מקום אביו. מקורב לאדמורים משיניבה וצשינוב. חתן ר שמואל אהרן מקורטשין. בנו ר משה כיהן כאדמור מטומשוב בניו יורק."},{"i":39829,"n":"פרישרמן, מאיר אברהם","dt":"תשג","b":"רב בטומאשוב-לוב"},{"i":39830,"n":"פרישרמן, משה מטומשוב נ\"י","f":"יוסף אריה מטומשוב","k":"אדמור מטומשוב נ\"י","bt":"תרסג","dt":"תשלד - ח אדר","dp":"ניו יורק","b":"חסיד בלז. לאחר שנתייתם גדל אצל דודו ר אשר רובין מקורטשין. חתן ר ברוך רובין האדמור מברוזדוביץ וגערלא(=סאמוש אויוואר)(שושלת רופשיץ), ובזיוו\"ש חתן ר משה גרינצוייג מאפשא. רב ואדמור בסאמאש-איוואר על מקום חותנו. ניצל יחיד מהשואה - עבר לניו יורק וכיהן כאדמור מטומשוב בניו יורק."},{"i":39831,"n":"פרישרמן, צבי אלימלך מהאלמין","f":"יהושע מטומשוב","k":"אדמור מהאלמין","dt":"תשי","dp":"אנטורפן","b":"נכד ר יוסף מיארטשוב. אדמור בהאלמין. ניצל מהשואה, ואחריה עבר לאנטורפן. בניו נספו בשואה."},{"i":39832,"n":"פרישרמן, שלום מסטמר טומשוב","f":"יוסף אריה ליבוש","k":"אדמור מטומשוב סטמר","dt":"תשד - טז סיון","b":"בנו של האדמור מטומשוב בפולין. חתן ר אהרן יחיאל מנדבורנא. אדמור בסטמר לפני השואה. נספה בשואה."},{"i":39833,"n":"פרישרמן-גרין, יוסף מיאריטשוב","f":"שמעון","k":"אדמור מיאריטשוב","bt":"תקמז","dt":"תקצט - כה ניסן","b":"חתן הגביר ר אהרן מסטרי-דזיקוב. תלמיד החוזה מלובלין שהעיד עליו כי הוא אחד מל\"ו צדיקים. רב בנארול, יריטשוב, טומשוב - עמד שם בראש החולקים על ר מנחם מנדל מקוצק ונאלץ לעזוב בגלל המחלוקת."},{"i":39834,"n":"פרל, אהרן יוסף","b":"משכיל - להוסיף פרטים."},{"i":39835,"n":"פרל, בן ציון","bt":"תרמח","dt":"תרצ - כח סיון","b":"רב בניו יורק"},{"i":39836,"n":"פרל, יוסף מטרנופול","k":"בעל מגלה טמירין","bt":"תקלד","bp":"טרנופול","dt":"תר - כג תשרי","dp":"טרנופול","b":"משכיל, בתחילה היה מקורב לחסידות, אך פנה להשכלה והפך לאחר מראשי המתנגדים לחסידות בגליציה, וחיבר ספרים כנגד החסידים - חלקם בעילום שמו. הקים בית ספר בטרנופול, בנה בית כנסת ופעל למינוי ר שלמה ליב רפפורט לרב בטרנופול."},{"i":39837,"n":"פרל, יעקב מזבורוב - א","b":"רב בזבורוב-תק\"צ"},{"i":39838,"n":"פרל, יעקב מזבורוב - ב","b":"רב בזבורוב-תרס."},{"i":39839,"n":"פרל, ישעיה","f":"יעקב פרל","dt":"תרטז - יג כסלו","b":"רב בקורימא"},{"i":39840,"n":"פרל, מרדכי דוד מקינסק","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":39841,"n":"פרל, משה מוארשא","b":"רב בוארשא. פרסם מאמרים ב\"מגד ירחים\" - סטמר תרפה."},{"i":39842,"n":"פרל, נתן יעקב מקינצק","k":"אדמור מרדושיץ קינצק","dt":"תשא-ג","b":"נכד האדמור ר ישראל יצחק בארון מרדושיץ. אדמור ברדושיץ וקינצק"},{"i":39843,"n":"פרל, שמואל מאיר","f":"יעקב פרל","dt":"תריד - א אב","b":"רב בזבורוב"},{"i":39844,"n":"פרלא, דב מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":39845,"n":"פרלא, חיים אליהו מוארשא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":39846,"n":"פרלא, ירוחם פישל","f":"אריה צבי","k":"בעל פרוש ספר המצוות","r":"רי\"פ","bt":"תרו","bp":"וארשא","dt":"תרצד","dp":"ירושלים","b":"מחכמי פולין-ליטא, תלמיד ר משה יהושע דיסקין בלומזה, עבר לבריסק ולמד אצל ר חיים מבריסק, דחה הצעות לרבנות. חיבר פירוש על ספר המצוות לר סעדיה גאון וארשא תרעד, ועוד. בשנת תרפו עלה לירושלים. חיבר ספרים וכתבים רבים, חלקם נדפסו. כתביו היו אצל ר מנחם כשר בירושלים. פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב. ?? לא באוצר ??","bk":[["הגהות רבי ירוחם פישל פרלא",""],["פירוש על ספר המצוות להרס\"ג",""],["פרחי ציון - כפתור ופרח",""]]},{"i":39847,"n":"פרלברגר, צבי מויליצקה","dt":"תרלב","b":"ראש הקהלה וראש העיר ויליצקה."},{"i":39848,"n":"פרלברגר, שלמה ממישלניץ","bt":"תרסז","bp":"מישלניץ","dt":"תשב","b":"למד בישיבת בובוב במישלניץ. חתן ר צבי מאיר שוץ מלימנוב. נספה בשואה."},{"i":39849,"n":"פרלגבר, יעקב משוקיאן","f":"יהודה ליב","k":"בעל דברי יעקב","bt":"תרכא","b":"תלמיד ישיבת וולוזין. רב בוויגעוועג-תרן, שוקיאן-פלך קובנא. נסמך מאת: הנצי\"ב. חיבר גם \"נחלת יעקב\", \"אמרי יעקב\"."},{"i":39850,"n":"פרלגר, אליעזר ליפא משטקטשין","dt":"תקצה - ז תשרי","b":"תלמיד החוזה מלובלין ור דוד מללוב. מפורסם במופתיו. בנו ר יחיאל אלתר מאיוואנצק."},{"i":39851,"n":"פרלגר, יחיאל אלתר מאיוואנצק","f":"אליעזר ליפא משטקטשין","dt":"טו אב","b":"חתן ר יעקב מאפטא."},{"i":39852,"n":"פרלוב, אברהם אהרן מפוחאוויץ","f":"שלמה חיים מקוידנוב","k":"אדמור מפוחאוויץ","b":"אדמור בפוחאוויץ-ליד לונינץ. בנו ר משה צבי."},{"i":39853,"n":"פרלוב, אברהם אלימלך מקרלין","f":"ישראל מסטולין-הינוקא","k":"אדמור מקרלין","bt":"תרנב","dt":"תשג - יד חשון","b":"חתן דודו ר מרדכי יוסף מזלטיפולא. אדמור בסארני, קרלין, הקים ישיבה בלונינץ, רוב חסידי אביו עברו אליו. ביקר בארץ כמה פעמים, בביקורו האחרון הפצירו בו שישאר אך חזר אל חסידיו בקרלין. נספה בשואה."},{"i":39854,"n":"פרלוב, אברהם מפוחאויץ","f":"ברוך מרדכי מקוידנוב","b":"רב בפוחאוויטש-תר\"נ"},{"i":39855,"n":"פרלוב, אהרן מקוידנוב","f":"ברוך מרדכי פרלוב","k":"אדמור מקוידנוב","bt":"תקצט","dt":"תרנז - כו אלול","b":"אדמו\"ר בקוידנוב. חתן דודו ר דב משה בן שלמה חיים מקוידנוב. מתורתו ב\"זכר צדיק\" ו\"דובר שלום\" ו\"שיח אבות\". הו\"ל \"אור הנערב\" לר משה קורדובירו עם פירוש \"נראה אור\" ממנו."},{"i":39856,"n":"פרלוב, אהרן מקוידנוב","k":"אדמור מסטולין","dt":"תשג","b":"אדמו\"ר מקוידנוב(=קוידינוב) בסטולין"},{"i":39857,"n":"פרלוב, אלימלך מקרלין","f":"ישראל פרלוב","dt":"תש","b":"רב בקארלין"},{"i":39858,"n":"פרלוב, אליעזר מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":39859,"n":"פרלוב, אלתר ישראל שמעון מנובומ","f":"יעקב מנובומינסק","k":"אדמור מנובומינסק","bt":"תרלה","dt":"תרצג - ו טבת","dp":"וארשא","b":"חתן ר ברוך מאיר מאזארניץ (טשרנוביל). עבר לוארשא - בזמן מלחה\"ע ה-I, וכיהן כאדמור מנובומינסק בוארשא. חיבר \"תפארת איש\", בנו ר נחום מרדכי על מקומו אחריו כאדמור נובומינסק בניו יורק.","bk":[["תפארת איש (נובומינסק)",""]]},{"i":39860,"n":"פרלוב, אלתר שלמה חיים מקוידינב","f":"יוסף מקוידנוב","k":"אדמור מקוידנוב","dt":"תרעז - יז אייר","b":"חתן ר אברהם שמואל מברזנא (סטעפין). אדמור בקוידנוב - שנה אחת."},{"i":39861,"n":"פרלוב, אשר מסטולין","f":"ישראל מסטולין-הינוקא","dt":"תשג","b":"חתן ר מרדכי טברסקי משפיקוב, ובזיוו\"ש ?. למד מוסיקה. רב בסטולין - לא כיהן כאדמור."},{"i":39862,"n":"פרלוב, ברוך מרדכי מקוידנוב","f":"שלמה חיים מקוידנוב","k":"אדמור מקוידנוב-לכוב","bt":"תקעח","dt":"תרלא-ה - ב תשרי","b":"חתן ר שלום מאוזדא. אדמור בקוידנוב-תרכב. נשיא ארץ ישראל ל\"כולל קוידנוב\"."},{"i":39863,"n":"פרלוב, דוד משה מסאלויץ","f":"אהרן מקוידנב","b":"רב בסאלאוויטץ-תר\"ס"},{"i":39864,"n":"פרלוב, יהודה אריה ליב מוולדובה","f":"יעקב מנובומינסק","k":"אדמור מנובומינסק","bt":"תרלח","bp":"נובומינסק","dt":"תשכא - י אלול","b":"חתן ר דוד טברסקי ממקרוב (טשרנוביל). רב בוולודובה (ליד בריסק)-תרסב, ברח לרוסיה - במלחה\"ע ה-I, לובלין, היגר לארה\"ב-תרפד, וכיהן כאדמור מנובומינסק בניו יורק, עלה לארץ-תרצג והדפיס את ספרו \"לב אריה החדש\", חזר לארה\"ב. חיבר גם \"קול יהודה\". בנו ר יעקב על מקומו אחריו."},{"i":39865,"n":"פרלוב, יהושע השל מבוליחוב","f":"שמעון מזאוויחוואסט","k":"אדמור מבוליחוב","bt":"תר","dt":"תרסד","b":"מצאצאי ר יצחק מנסכיז. אחיו של ר יעקב פרלוב מנובומינסק. חתן ר ישראל שמואל מטומשוב (חלם). אדמור בבוליחוב, וחתנו ר שלמה חיים פרלוב על מקומו אחריו."},{"i":39866,"n":"פרלוב, יוחנן מסטולין-לוצק","f":"ישראל פרלוב","k":"אדמור מסטולין-קרלין","bt":"תרנד","bp":"סטולין","dt":"תשטז - כא כסלו","dp":"ניו יורק - טבריה","b":"מצאצאי האדמור אהרן מקרלין. חתן האדמור ר שמעון שלמה מאלויק, ובזיוו\"ש חתן ר יצחק משאץ-רדוביץ (שושלת זלוטשוב). אדמור מקרלין סטולין בלוצק-תרפב לאחר פטירת אביו. ניצל מהשואה, והסתיר עצמו בין הניצולים, אולם נתגלה והוכתר כאדמור מסטולין-קרלין. עלה לארץ-תשו והתגורר בחיפה והיה למנהיג חסידי קרלין בארץ, הגיע לניו יורק-תשח, וכיהן כאדמור מסטולין-קרלין על מקום אחיו ר יעקב חיים. הקים ישיבת קרלין בניו יורק. נכדו ר ברוך מאיר יעקב על מקומו אחריו בניו יורק ועלה לירושלים. מתורתו ב\"כתבי קדש\"."},{"i":39867,"n":"פרלוב, יוסף מוארשא","f":"אלתר ישראל שמעון","k":"אדמור מנובמינסק ורשא","bt":"תרעו","dt":"תשה - ב אייר","dp":"ברגן בלזן","b":"בן האדמור מנובומינסק. חתן ר אליעזר שלמה מוולומין (קוזמיר), רב ואדמור בוארשא על מקום אביו - בהיותו בן 17. נספה בשואה."},{"i":39868,"n":"פרלוב, יוסף ממינסק","f":"אהרן פרלוב","b":"רב במינסק-תר\"מ"},{"i":39869,"n":"פרלוב, יוסף מנובומינסק","f":"אלתר ישראל שמעון","bt":"תרעו","dt":"תשה","b":"אדמו\"ר מנובומינסק,נספה בשואה שבועיים אחרי השחרור"},{"i":39870,"n":"פרלוב, יוסף מקוידנוב","f":"אהרן מקוידנוב","bt":"תריד","dt":"תרעו - כו כסלו","dp":"מינסק","b":"חתן דודו זקנו ר נח מהורודישץ, ובזיוו\"ש חתן נכדת \"היהודי הקדוש\" מפשיסחא. רב בקוידנוב והקים ישיבה \"תומכי צדק\" ועמד בראשה."},{"i":39871,"n":"פרלוב, יעקב חיים מסטולין ארה\"ב","f":"ישראל מסטולין-הינוקא","k":"אדמור מקרלין-סטולין","dt":"תשו - ו אייר","dp":"דטרויט","b":"חתן ר אברהם יהושע השל טברסקי מטשדונוב (טשרנוביל). הגיע לארה\"ב-תרפד, וכיהן כאדמור מקרלין-סטולין בניו יורק. נפטר בנסיעתו לביקור אצל חסידיו בדטרויט. מתורתו ב\"ברכת אהרן\", ב\"הפרדס\", ועוד."},{"i":39872,"n":"פרלוב, יעקב יצחק מקוידנוב","f":"יוסף מקוידנוב","k":"אדמור מקוידנוב","bt":"תרסג","dt":"תרעט - כח טבת","b":"נתמנה לאדמור מקוידנוב בגיל 13 ונפטר בגיל 16. מתורתו ב\"שיח אבות\"."},{"i":39873,"n":"פרלוב, יעקב מנובומינסק","f":"שמעון קצנלנבוגן מזאו","k":"אדמור מנובומינסק","bt":"תרג","dt":"תרסב - כג אד\"א","b":"חתן ר אריה יהודה ליב מפרוסקרוב (ברדיטשוב). נקרא פרלוב ע\"ש משפחת זקנו ר שלמה חיים פרלוב מקוידנוב. רב בסטרושלה, הינטעטש, רב ואדמור בנובומינסק-תרלג והקים שם ישיבה, בנו ר אלתר ישראל שמעון על מקומו אחריו כאדמור מנובומינסק בוארשא. חיבר \"שופרא דיעקב\"."},{"i":39874,"n":"פרלוב, יעקב מנובומינסק ארה\"ב","f":"נחום מרדכי מנובומינס","k":"אדמור מנובומינסק נ\"י","b":"חתן ר אברהם מזידיטשוב-שיקגו. ראש ישיבה בארה\"ב. חיבר \"עדת יעקב\"."},{"i":39875,"n":"פרלוב, ישראל מסטולין - הינוקא","f":"אשר מקרלין - הנכד","k":"אדמור מקרלין סטולין","bt":"תרכט","dt":"תרפב - ב תשרי","dp":"פפד\"מ","b":"חתן דודו זקנו ר דוד מזלטיפולא (טשרנוביל). נתייתם בילדותו והוכתר כאדמור וכונה \"הינוקא מסטולין\". בנו ר אשר המכונה \"פרנקפורטר\", חתנו - ר אברהם שפירא האדמור מגוודיץ."},{"i":39876,"n":"פרלוב, ישראל צבי הירש","f":"ברוך מרדכי מקוידנוב","b":"חתן האדמור ר יעקב יצחק ממאקרוב. נפטר צעיר ללא ילדים. לזכרו הו\"ל אחיו - ר שלום \"הצבי ישראל\"."},{"i":39877,"n":"פרלוב, משה אהרן","dt":"תשג","b":"רב בקוברין"},{"i":39878,"n":"פרלוב, משה מסטולין","f":"ישראל מסטולין","k":"אדמור מקרלין סטולין","bt":"תרנא","dt":"תשב - כט אלול","b":"חתן ר פנחס מקנטיקוזיבא (ליניץ). אדמור בסטולין וראש ישיבה. ביקר בארץ והקים בימ\"ד בתל אביב. המשיך לכהן גם תחת שלטון הקומוניסטים ברוסיה. נספה בשואה."},{"i":39879,"n":"פרלוב, נח מהורודישץ","f":"שלמה חיים מקוידנוב","k":"אדמור מהורודישץ","dt":"תרסד - י טבת","b":"חתן ר מרדכי מאוסטילא (נסכיז)."},{"i":39880,"n":"פרלוב, נחום מקוזניץ","dt":"תשג","b":"רב בקוזניץ"},{"i":39881,"n":"פרלוב, נחום מרדכי מנובומינסק","f":"אלתר ישראל שמעון","k":"אדמור מנובומינסק","r":"אדמו\"ר מנובומינסק","bt":"תרמז","bp":"נובומינסק","dt":"תשלו - ט אלול","b":"נכד(-אבי אמו) ר ברוך מאיר טברסקי מאזארניץ. רב בסוקולוב, תלמיד וחתן ר יצחק זליג מורגנשטרן מסוקולוב (קוצק), נסמך מאת: ר אליעזר שלום פארצוב, ר שמואל מונגרוב. רב בסוקולוב עם חותנו ומילא את מקומו כשעזב את העיר, בשליחות אגודת ישראל בארה\"ב, רב ואדמור בקהלת \"עדת יעקב\" בניו יורק-תרפו, וכיהן כאדמו\"ר מנובומינסק בארה\"ב. חבר מועצת גדולי התורה של אגו\"י.","bk":[["פאר נחום",""]]},{"i":39882,"n":"פרלוב, נחמיה מקוידנוב-ברנוביץ","f":"אהרן מקוידנוב","k":"אדמור מברנוביץ","dt":"תרפז - כא תמוז","b":"חתן דודו זקנו ר אברהם אהרן פרלוב מפוחאוויץ. עבר לברנוביץ והיה בקשרים עם חסידיו שבשלטון הקומוניסטי. מבניו ר נפתלי-חתן ר ישכר דב מבלז."},{"i":39883,"n":"פרלוב, שלום אלתר מקוידנוב ברנ","f":"נחמיה מקודינוב ברנוב","k":"אדמור מקוידנוב-ברנו","bt":"תרסד","dt":"תשא - ו חשון","dp":"וילנא","b":"חתן ר ירחמיאל צבי משדליץ (פשיסחא). אדמור מקוידנוב-ברנוביץ על מקום אביו."},{"i":39884,"n":"פרלוב, שלום מבראהין","f":"ברוך מרדכי מקוידנוב","k":"בעל דברי שלום","r":"אדמו\"ר מקוידנוב","bt":"תריא","dt":"תרפו - כו חשון","b":"חתן ר יוסף מברזנא (סטעין). רב בברזנא, בראהין-פלך מינסק-תרן. חיבר גם \"משמרת שלום\", \"שם אהרן\" ועוד. חיבר גם \"עטרת שלום\" והוא פירוש על הזמר \"יה אכסוף\" לזקנו ר אהרן הגדול מקרלין.","bk":[["דברי שלום – עה\"ת",""],["הגהות והערות – מדרש פנחס החדש",""],["הלולא רבא החדש",""],["משמרת שלום – או\"ח",""],["עטרת שלום – זמר קה אכסוף",""],["שם אהרן",""],["שם אהרן , דברי שלום – עה\"ת , הגהות והערות – מדרש פנחס החדש, הלולא רבא החדש , עטרת שלום – זמר קה אכסוף",""]]},{"i":39885,"n":"פרלוב, שלמה חיים מאווריטש","f":"אהרן מקוידנוב","k":"אדמור מאווריטש","dt":"תרנז - יד ניסן","b":"חתן ר נחום דובער בן ר יוסף יצחק מאווריטש (ליובאוויטש). אדמור באווריטש בחיי אביו."},{"i":39886,"n":"פרלוב, שלמה חיים מבוליחוב","f":"יעקב מנובומינסק","k":"אדמור מבוליחוב נובומ","bt":"תרם","bp":"נובומינסק","dt":"תשג - יא תמוז","dp":"סטרי","b":"בגיל 12 התכתב עם גדולי דורו. חתן דודו ר יהושע השל קצנלנבוגן-פדובא מבוליחוב. רב ואדמור בבוליחוב על מקום חותנו והקים ישיבה. נספה בשואה. חיבר \"דרך החיים\"-\"קהילת שלמה\" על סדר תפלות לכל השנה - מרמורש-סיגט תרסז, \"תוספות חיים\" - בכת\"י (לא הדפיסו במצוות אביו)."},{"i":39887,"n":"פרלוב, שלמה חיים מבראהין","f":"שלום מבראהין","bt":"תרמז","dt":"תרצד","dp":"סיביר","b":"הוגלה לסיביר ונפטר שם."},{"i":39888,"n":"פרלוב, שלמה חיים מקוידנוב","f":"אהרן יפה","k":"אדמור מלכוביץ-קוידיד","bt":"תקנז","dt":"תרכב - יז אב","b":"חתן ר דב משה-חתנו של ר שלמה מקרלין. נתייתם בילדותו וגדל אצל זקנו ר אשר פרלוב מסטולין - ומכאן שמו \"פרלוב\". הוכתר לרב ואדמור בטורוב ע\"י זקנו. אדמור מלכוביץ בקוידנוב על מקום דודו ר נח מלכוביץ."},{"i":39889,"n":"פרלוב, שמעון מזוויכסט","f":"פנחס מאוסטילא","k":"אדמור מזוויכסט","b":"אדמו\"ר בזווכיסט-תר\"מ"},{"i":39890,"n":"פרלוביץ, יצחק נטע מויזנא","f":"שמואל","b":"ר\"מ ומשגיח בישיבת ויזנא-תרן אצל ר בצלאל אטלאס."},{"i":39891,"n":"פרלין, משה מרדכי מלובשוב","b":"חתן ר ראובן קאהן מנארווא. רב בלובעשאוו(=לובאשוב)-פלך מינסק-תרס."},{"i":39892,"n":"פרליק, שמואל יצחק מברוסילוב","f":"אברהם","bt":"תרכח","b":"מו\"צ בבוריסלוב-פלך קיוב-תרנג."},{"i":39893,"n":"פרלמוטר, אברהם צבי מראדום","f":"אליעזר","k":"בעל דמשק אליעזר","dt":"תרפז - ט סיון","b":"רב בראדום, מו\"צ בוארשא, ממיסדי אגודת ישראל בפולין וחבר מטעמה בפרלמנט הפולני."},{"i":39894,"n":"פרלמוטר, דב","b":"פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":39895,"n":"פרלמוטר, דוד אריה","b":"רב בברעזין"},{"i":39896,"n":"פרלמוטר, מנחם מנדל מטשבין","b":"מחכמי טשבין - תלמיד ר דב וידנפלד שהביא ממנו ב\"דובב מישרים\"-תרצה."},{"i":39897,"n":"פרלמוטר, משה מוארשא ובריסק","f":"יעקב אהרן מבריסק","k":"בעל אבן משה","b":"תלמיד ר משה ליב זילברברג בלאסק. מו\"צ בוארשא, בריסק-תרי."},{"i":39898,"n":"פרלמן, אברהם י' הלוי מארה\"ב","f":"נחמן","b":"מצאצאי ר אברהם מקאליסק. רב ביהמ\"ד \"שערי תורה\" ביפו, הגיע לארה\"ב-תרפה וכיהן כרב בניו יורק."},{"i":39899,"n":"פרלמן, אברהם יצחק משקודוויל","k":"בעל פני אברהם","bt":"תרן","bp":"טלז","dt":"תשג","b":"מגדולי הרבנים בדורו. תלמיד ישיבות טלז, סלובודקה. חתן ר ישכר בר משקודוויל. רב בשקודוויל-תרעג וחידש את הישיבה הקטנה במקום. נספה בשואה עם בני עדתו. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"בית ועד לחכמים\" - סטמר תרפב, \"דברי תבונה\" - קובנה תרף, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"עמק הלכה\" - באטארקס תרפא, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":39900,"n":"פרלמן, אהרן יעקב ממזובצק","f":"י\"ל","bt":"תרכה","dt":"תש","b":"רב במאזובצק(=מאזאוועצק)-פלך לומזה-תרנט."},{"i":39901,"n":"פרלמן, אליהו ברוך מירושלים","dt":"תשטו - כח אדר","dp":"ירושלים","b":"תלמיד ישיבות עץ חיים ותורת חיים בירושלים. מחכמי ירושלים, חתם על כרוזים ומכתבים עם רבני ירושלים."},{"i":39902,"n":"פרלמן, אליהו מגאראדיא","f":"ירוחם יהודה-הגדול ממ","bt":"תרכז","dt":"תשג","b":"תלמיד ישיבת וולוזין. חתן ר דב ברוידא מטלז וירושלים. רב בגאראדיה-פלך מינסק. הו\"ל ספר אביו \"אור גדול\". חתנו - ר פרץ יגל מארה\"ב."},{"i":39903,"n":"פרלמן, אלימלך מירושלים","f":"ישראל איסר מרוזוודוב","b":"לאחר פטירת אביו-תרי עלה עם אמו לירושלים וגדל אצל זקנו ר אשר כהנא-שפירא מזאלין וירושלים. חתן ר ברוך בנימין זאב וינשטוק מירושלים. מראשי העדה החסידית בירושלים, וממיסדי שכונות בתי פרלמן (ליד מאה שערים). בשליחות בגליציה-תרלז מטעם כולל אוסטריה-גליציה (על השליחות נדפסו הקונטרסים \"אגרת פתוחה\" ו\"אגרת בקורת\" - לבוב תרלז). חתם-תרסה עם ר יצחק בלזר."},{"i":39904,"n":"פרלמן, בן ציון","f":"ירוחם יהודה-הגדול ממ","dt":"תרפא - כב ניסן","b":"בנו הצעיר של \"הגדול ממינסק\". חתן הגביר ר משה קנטרוביץ מסמילוביץ. גביר ותלמיד חכם. נאסר ע\"י הקומוניסטים ושוחרר חולה ונפטר, אשתו בנו ובנותיו - עלו לארץ."},{"i":39905,"n":"פרלמן, בן ציון מלעווינפאל","f":"אהרן","bt":"תרלז","b":"רב בלעווינפאל-פודוליה-תרסה."},{"i":39906,"n":"פרלמן, דוד מאלקסאט","dt":"תשד","b":"רב באלעקסאט"},{"i":39907,"n":"פרלמן, זאב מאיוויא","dt":"תשג","b":"רב באיוויא"},{"i":39908,"n":"פרלמן, יוסף שמואל ממישלניץ","f":"נפתלי בנימין","b":"רב במישלניץ-תרנו על מקום אביו. תלמיד הדברי חיים."},{"i":39909,"n":"פרלמן, ירוחם יהודה ליב ממינסק","f":"שלמה זלמן מבריסק","k":"הגדול ממינסק-אור גדו","r":"הגדול ממינסק,","bt":"תקצה","bp":"בריסק","dt":"תרנו - ז שבט","dp":"מינסק","b":"מגדולי דורו, חתן ר יעקב-דיין בבריסק, ובזיוו\"ש חתן ר נחמן ניימרק מבריסק. תלמיד ר ישראל סלנטר בקלויז נביאז'ר. ביקר אצל ר איזל חריף בסלונים שהתפעל מידיעותיו. רב בסאלץ(=סעלץ), פרוז'אן(פרוזין), מינסק. השתתף באסיפות רבנים. חיבר \"אור גדול\". פרסם מאמרים ב\"יגדיל תורה\" - אודסה תרלט. אחיו-ר בנימין כתב את תולדותיו בהקדמה לספרו \"בן אוני\".","bk":[["אור גדול","מפרשי רמב\"ם"],["אור גדול - תשובות וכתבים",""]]},{"i":39910,"n":"פרלמן, ישראל איסר מרוזוודוב","b":"תלמיד החוזה מלובלין. חתן ר יחיאל אשר שמואל כהנא-שפירא מזלין (אסתר פייגא שבזיוו\"ר היתה אשת האדמו\"ר שלמה ליב מלנטשא - לאחר פטירת ר ישראל איסר עלתה לירושלים אל אביה עם בנה ר אלימלך). רב ברוזוודוב-תקס? - עד תרי בערך. (התאריכים לא מסתדרים)"},{"i":39911,"n":"פרלמן, מנשה יחזקאל","f":"משה מקראקא","dt":"תשב","b":"חתן ר אברהם שנעה. נספה בשואה."},{"i":39912,"n":"פרלמן, משה","f":"ירוחם - הגדול ממינסק","dt":"תרצה","dp":"קובנא","b":"גביר ותלמיד חכם. חתן ר דב ברוידא מטלז וירושלים. חיבר \"מדרש הרפואה\" ת\"א תרפו."},{"i":39913,"n":"פרלמן, ניסן מבלוזוב","f":"הרב הצדיק","b":"מחכמי בלוזוב. חתן ר חיים גורליצר."},{"i":39914,"n":"פרלמן, נפתלי בנימין ממישלניץ","f":"מנחם ישכר דב מגורליץ","bt":"תקעה","dt":"תרנה","b":"חתן הגביר ר מנשה יחזקאל מלימנוב. רב במישלניץ, בנו ר יוסף שמואל על מקומו אחריו."},{"i":39915,"n":"פרלמן, צבי הירש","f":"ברוך","k":"בעל ילקוט אבנים","b":"מחכמי הפרושים בירושלים, חתנו של ר בן ציון שלז. חיבר \"ילקוט אבנים\" ירושלים תרלה, ועוד."},{"i":39916,"n":"פרלמן, צבי מאיר מלונדון","f":"יחיאל ירחמיאל מהנובר","bt":"תרסג","bp":"הנובר","dt":"תשמה","b":"חסיד אלכסנדר. חתן ר ר חיים שאול הלוי שנדורף. התגורר בברלין. ניצל מהשואה כשעבר ללונדון-תרצח, היה שם עוסק בתורה וגמ\"ח. מחותן עם האדמור מאלכסנדר."},{"i":39917,"n":"פרלמן, שלמה זלמן","f":"ירוחם יהודה-הגדול ממ","b":"גביר מחכמי וארשא. חתן הגביר ר אפרים ביאליסטוצקי מדרעטשין."},{"i":39918,"n":"פרלס, אברהם צבי מפינפקירכן","f":"יאקב פרלס","b":"רב בפינפקירכן-תר\"נ"},{"i":39919,"n":"פרלס, אלעזר מחעלמא ופרג","b":"רב בחעלמא,פרג"},{"i":39920,"n":"פרלס, ארמין מפעטש","bt":"1853","dt":"1914","b":"רב בקהילה הניאולוגית בקאצ'קאמאט, פעטש, יסד במקום תלמוד תורה. מגדולי הנואמים בהונגריה. חיבר מאמרים ודרשות ב-4 כרכים, פרסם בעתונות ההונגרית."},{"i":39921,"n":"פרלס, ברוך אשר מבייאה","dt":"תרכב - בערך","b":"תלמיד החת\"ס. דיין בבייאה. בנו ר פרץ - רב במינכן."},{"i":39922,"n":"פרלס, זלמן מבנוביץ","b":"רב בבנוביץ-תקפ\"ד"},{"i":39923,"n":"פרלס, חיים מהורדנא","f":"יהודה","dt":"תרי - כד תשרי","dp":"הורדנא","b":"גביר מחכמי הורדנא."},{"i":39924,"n":"פרלס, יאקב מקראלי","f":"יצחק משה פרלס","b":"דומ\"צ בקראלי-תר\"כ"},{"i":39925,"n":"פרלס, יוסף מבאייה ומינכן","dt":"תרנה","b":"רב בבאייה, מינכן."},{"i":39926,"n":"פרלס, יעקב מאונגריש ברוד","b":"דיין בברודא-תק\"נ"},{"i":39927,"n":"פרלס, יעקב מקרולה","f":"יצחק משה-בית נאמן","dt":"תרע - בערך","b":"דיין בקרולה אצל אחיו ר מאיר האב\"ד. בנו ר אברהם צבי מפעטש הו\"ל ספר זקנו ר יצחק משה - \"בית נאמן\"."},{"i":39928,"n":"פרלס, יצחק משה מבאניהאד","f":"יעקב","k":"בעל בית נאמן","r":"אב\"ד באניהאד","bt":"תקמד","bp":"אונגריש בראד","dt":"תריד - טו אב","dp":"אונגריש בראד","b":"תלמיד החת\"ס בדרזניץ, ר משולם איגרא מפרשבורג, ר יוסף ור שמואל מפוזנא. חתן ר שלמה זלמן בריל מאונגריש בראד. רב בגויטיין(=קויטיין)-תקעג, קוליץ, קיש מארטון, האליטש-תקף, איזנשטט-תקפב, בניהאד-תרא ועזב בגלל מחלוקת עם ראשי הקהילה שדרשו תיקונים בדת וחזר לאונגריש ברוד. מכתב מהחת\"ס אליו שלא יעזוב את רבנות איזנשטט. סירב להשתתף בכנס רבנים שארגן בפאקש ר פנחס הורביץ מפאקש שביקש להגיע לפשרה במחלוקת קהלות הונגריה (כדי שלא יראה שהוא מוכן לפשרות בעיניני הדת). בזמן כהונתו בבניהאד הונהג שרב העיר רושם את כל הילודים בקהלה. מתלמידיו: ר בנימין ברייער מטאבי, ר זאב וולף מבודפשט, ר יצחק זליג מטולצ'בה, ועוד. היה גם ראש ישיבה ונתן רשות לתלמידים ללמוד את שפת המדינה (לא על חשבון הלימוד בישיבה). בנו - ר מאיר מקארלי.","bk":[["בית נאמן - שו\"ת",""]]},{"i":39929,"n":"פרלס, מאיר מקראלי","f":"יצחק משה-בית נאמן","bt":"תקעא","bp":"אונגריש-בראד","dt":"תרנד - טו תשרי","dp":"קראלי","b":"תלמיד החת\"ס, ור יחזקאל סגל מטרנטשין. חתן ר יצחק פרנקל-ב\"ח מקרולה(=קראלי). רב בקראלי-תקצה על מקום חותנו כ-60 שנה. בזיוו\"ש חתן ר יחזקאל הכהן רויז מקראלי. (היתה הצעה לשידוכו עם בת החת\"ס - אך לא הסתייע). בניגוד לרבים מחבריו לא פרש בזמן פילוג הקהילות וקהילתו נשארה קהילת סטטוס קוו - בהשפעת חתניו שכיהנו בקהלות לא אורטודוכסיות, והיה מחלוקת מצד כמה מהרבנים על כך. סירב לרבנות איזנשטדט ונשאר בקרולה לבקשת ידידו הכת\"ס שחשש מה יקרה בקרולה אם יעזוב. הניח חבורים בכת\"י, ובצוואתו ציוה שלא להדפיס את ספריו אלא כעבור 25 שנה מפטירתו."},{"i":39930,"n":"פרלס, משה יהודה מוערבא","f":"צבי הרש ברודא מוערבא","b":"מחכמי וערבא. אביו של ר צבי הרש מקיצע."},{"i":39931,"n":"פרלס, פיבל מקניגסברג","f":"יוסף פרלס","bt":"תרלד","b":"גדול בתורה ומדעים,רב בקניגסברג-תרנ\"ט"},{"i":39932,"n":"פרלס, צבי הירש מקיצע","f":"משה יהודה ליב מוערבא","bt":"תרך","bp":"וערקי או וערבא","dt":"תשד - ב תשרי","dp":"עיר חדש","b":"תלמיד השב\"ס, ור אברהם אליעזר זאב אלט מקוברסדורף, ועוד. חתן ר אברהם לעווי ממטרסדורף. רב בקיצע, קטנדורף והגליל על מקום חותנו זקנו - ר מאיר אבלס. גורש לפרשבורג עם כל הקהלה ואח\"כ לעיר חדש. חתנו ר ישראל יו\"ט פרידמן מבאדן, ונכדו ר מרדכי מאיר פרידמן על מקומו אחריו בקיצע."},{"i":39933,"n":"פרלס, צבי הרש מוערבא","f":"יעקב מאונגריש בראד","dt":"תרטו - ח חשון","dp":"וערבא","b":"תלמיד החת\"ס. חתן ר שמואל מוערבא. רב בוערבא(=וערבוי)-תקצו."},{"i":39934,"n":"פרלשטין, אברהם יצחק מארה\"ב","f":"צבי הירש","bp":"רוזשאני","b":"רב ביהמ\"ד \"צמח צדק\" בשיקגו."},{"i":39935,"n":"פרלשטין, אלעזר קלונימוס מדמביץ","f":"משה שמהרש'ס","dt":"תשג","b":"חסיד שינאווא בדמביץ, וסירב לרבנות שם. חתן ר אביש קנר מסנוק ועבר לקראקא ולמד ולימד שם. נספה בשואה. גיסיו: ר מאיר קליגר מקרקוביץ, ר אליעזר טיפנברון."},{"i":39936,"n":"פרלשטין, דב ברל מצאנז","f":"שלמה זלמן מאונסדורף","b":"רב בצאנז-תרלט."},{"i":39937,"n":"פרלשטין, חיים צבי ממונקטש","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":39938,"n":"פרלשטין, יוסף מקופנהגן","b":"רב בקופנהגן. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":39939,"n":"פרלשטין, שלמה זלמן מאונסדורף","f":"קלונימוס קלמן","bp":"ביאליסטוק","dt":"תרל - כו כסלו","dp":"אונסדורף","b":"רב בבימ\"ד ר פיבש קעלין עהרנשטם בפרוסטיץ, רב בבאנוביץ, אונסדורף על מקום ר יחזקאל בעל \"תורת יחזקאל\" (בהמלצת החת\"ס) ור שמואל רוזנברג על מקומו אחריו. בנו - ר דב בר מסאנץ, חתנו - ר אברהם ישכר לייכטאג מהוניאד."},{"i":39940,"n":"פרם, דוד מדרום אפריקה","k":"בעל לידער און פאעמעס","bt":"1903","bp":"פוניבז","b":"חיבר פואימות מחיי היהודים בליטא בהשפעת קולבק. חיבר שירים ברוסית. פרסם שירים ומאמרים בעתונות האידית. היגר לדרום אפריקה-1927. עבר לארגנטינה וחזר לדרום אפריקה. חיבר ספרים."},{"i":39941,"n":"פרם, חיים מדאמבראד","b":"אב\"ד דאמבראד. נכדו - ר חיים שורץ ממאראשהעויז."},{"i":39942,"n":"פר\"מ, אהרן מניו יורק","k":"בעל עולת החודש","b":"רב בניו יורק. עורך הירחון \"עולת החודש\" יחד עם ר יצחק גליק."},{"i":39943,"n":"פרמוט, זלמן מקובנא","dt":"תשא - ה אלול","b":"מרביץ תורה בקובנא. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":39944,"n":"פרמון, אברהם משלוניקי","f":"מרדכי","dt":"רצה - ב חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":39945,"n":"פרמינגר, יוסף דוד מבוצאץ","f":"מיכל","b":"מחכמי בוצאץ. הוציא לאור \"כתם פז\" לרצה מסמוטרישטש - טשרנוביץ תרלג - עם הקדמה ממנו."},{"i":39946,"n":"פרמינגר, מאטי' מסטרוזניץ","b":"רב בסטרוזניץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":39947,"n":"פרמנטל, אליהו חלפן הלוי מפאריס","k":"בעל שיר השלום","bt":"תקך","bp":"פיורדא","dt":"תקפו","dp":"פאריס","b":"ש\"ץ, סופר ומורה לשון הקדש בפאריס. בנו - יעקב."},{"i":39948,"n":"פרמנטל, יעקב הלוי מפאריס","f":"אליהו חלפן","bt":"תקנט","dt":"תרכב","dp":"ניצא-צרפת","b":"מוסיקאי בפאריס. חיבר ניגונים לתפלות"},{"i":39949,"n":"פרן, אברהם יעקב","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":39950,"n":"פרן, אלימלך מרידיק","b":"חתן האדמור ר מאיר יאלעס מקרקוביץ."},{"i":39951,"n":"פרנאקו, שלמה ממצרים","b":"רב באלכסנדריה-שסב, לאחר שבנו נפטר במגפה עלה עם בני עירו לרמלה. חיבר פירוש על אבן עזרא."},{"i":39952,"n":"פרנבך, ליב מהייצפלד","b":"רב בהייצפלד"},{"i":39953,"n":"פרנד, דוד הלוי מלונדון","f":"יהודה ליביש מדובצק","k":"בעל קול דודי","bt":"תשג","bp":"צרפת","b":"מחכמי ניצה (צרפת), עבר ללונדון-תשלה. חתן ר קלונימוס קלמן גוטוירט מפריז. חיבר \"קול דודי\" תשלד."},{"i":39954,"n":"פרנדא, שמחה מאויבן","b":"ראב\"ד באויבן-שנת ש'"},{"i":39955,"n":"פרנדיס אפריקני, יוסף מליוורנו","b":"מגדולי דורו,רב בליוורנו-תק\"י"},{"i":39956,"n":"פרננדיס דיאס, אברהם בכור משלונ","f":"יעקב","dt":"תקמג","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":39957,"n":"פרננדיס דיאס, דוד משלוניקי","f":"שלמה - אורחות צדיקים","k":"הו\"ל ארחות צדיקים","dt":"תקנה","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת הספרים \"שם יוסף\"-תקכט, \"תוצאות חיים\"-תקל, \"וארחות צדיקים\" לאביו (כנראה צ\"ל בנו)-תקל. נספד מאת ר יעקב רפאל מנשה."},{"i":39958,"n":"פרננדיס דיאס, דוד משלוניקי","dt":"תרלא","dp":"שלוניקי","b":"גביר בשלוניקי. אחיהם של יעקב אליהו, משה."},{"i":39959,"n":"פרננדיס דיאס, חיים מרדכי","b":"מחכמי צפת בשנת תקנא חתם על כתב שליחות ר חיים מודעי."},{"i":39960,"n":"פרננדיס דיאס, חיים שלמה מירושל","f":"דוד","k":"בעל סוכת דוד","bp":"איטליה","dt":"תקלא - טו תמוז","dp":"שלוניקי","b":"נולד כנראה באיטליה, ישב בשלוניקי, עלה לירושלים והיה מחכמי \"בית אל\" בירושלים, בזמן ר גדליה חיון, וחבר בחבורת המקובלים \"ברית השבעה עשר\" (שהיתה קודם לכן חבורה של 12 מקובלים בישיבת \"אהבת שלום\"). חתם על שטר התקשרות עם ר שלום שרעבי בשנת תקיב. חבר \"בית אל\" בשנים תקיד - תקיט. נפטר בחיי אביו בזמן שהלך לשלוניקי להדפיס את ספר אביו \"ארחות צדיקים\" (ולפי \"זכרון שלוניקי\" ו\"כנסת ישראל\" - המדובר בספרו שלו במימון אביו הגביר). הניח חדושים בכת\"י ומהם נדפסו על ידי גיסו ר יעקב שמואל בן חסון בתוך ספרו \"בית המלך\" והם נספח בשם \"סוכת דוד\" - שלוניקי תקסד. בניו: ר יוסף דוד, ור אליהו - סייעו בהדפסת ספרו."},{"i":39961,"n":"פרננדיס דיאס, יעקב אליהו משלונ","dt":"תרכח","dp":"שלוניקי","b":"גביר בשלוניקי, ועסק בהסדרת עניני החינוך יחד עם ד\"ר משה אלאטיני. אחיו: משה, ודוד - גבירים בשלוניקי."},{"i":39962,"n":"פרננדיס דיאס, משה משלוניקי","dt":"תרלא","dp":"שלוניקי","b":"גביר בשלוניקי. אחיהם של יעקב אליהו, דוד."},{"i":39963,"n":"פרננדיס דיאס, שלמה מירושלים","f":"דוד","b":"מחכמי ישיבת בית אל בירושלים-תקיח. חתם-תקיב על שטר התקשרות חברים."},{"i":39964,"n":"פרננדיס דיאס, שלמה משלוניקי","dt":"תקצח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":39965,"n":"פרננדיס, אברהם משלוניקי","dt":"תרמא - טו תמוז","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":39966,"n":"פרננדיס, דוד משלוניקי","dt":"תקכט","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":39967,"n":"פרננדיס, יצחק משלוניקי","b":"גביר בשלוניקי ומשבעת טובי העיר-תקף בזמן ר שאול מולכו, והיה מחלוקת בינם לבין הרב בענין המס."},{"i":39968,"n":"פרננדיס, ליאונרדו משלוניקי","dt":"תרמז","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":39969,"n":"פרננדיס, משה דוד (ג'ון) משלוני","dt":"תרעב","dp":"שלוניקי","b":"רופא בשלוניקי-תרס."},{"i":39970,"n":"פרננדיס, שלמה משלוניקי","b":"גביר בשלוניקי-תריז ונמנה על שבעת טובי העיר."},{"i":39971,"n":"פרנס משטיפי","f":"אליהו הקטן","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":39972,"n":"פרנס, אברהם מדובנא","dp":"דובנא","b":"חתן הט\"ז (נשא את בת הט\"ז מאשתו השניה)."},{"i":39973,"n":"פרנס, אהרן מירושלים","f":"חיים יעקב פרנס","b":"רב בירושלים"},{"i":39974,"n":"פרנס, אליהו מאישטיפי","f":"שמואל","k":"בעל ספר הזכרון","b":"מחכמי וידרין, רב בקהל אישטיפי בקושטא (על שם העיר שטיפי(=שטיפאנוב) במקדוניה שרבים מבניה התישבו בקושטא). חיבר \"ספר הזכרון\" על התורה, ובו גם שיר לכבוד ר משה קפסאלי. חיבר פיוטים שנכנסו למחזורים ישנים. ראה גם אליהו הלוי הזקן מקושטא."},{"i":39975,"n":"פרנס, אליהו מירושלים","b":"מחכמי ירושלים-תקיח."},{"i":39976,"n":"פרנס, אליהו מירושלים - ב","f":"חיים יעקב","b":"מחכמי ירושלים, חתם על תקנת הקהל-תקעא יחד עם ר רפאל יוסף סאפורטה."},{"i":39977,"n":"פרנס, דוד מדובנא","f":"משה פרנס וואהלין","k":"מארשאלקאווין","dt":"תקפא - יג אד\"א","dp":"דובנא","b":"נכד דוד פרנס בן אברהם פרנס בן ר זאב וולף מאליק. חתן ר צדוק דער רייכער-בנו של משה פנחס חריף מלבוב. גביר מחכמי דובנא, יסד בית מדרש (בחצר ר צדוק ברציס קלויז), והחזיק תלמידי חכמים. בנו - הגביר ר צדוק מדובנא, חתנו - ר חיים יעקב בן זאב וולף מדובנא."},{"i":39978,"n":"פרנס, חיים יעקב מירושלים","b":"מחכמי ירושלים-תרי, ראש חברת ארבע משמרות-תריד."},{"i":39979,"n":"פרנס, יהודה ליב מקראקא","bt":"תרלה","dt":"תרסא","b":"תלמיד ר פנחס דמביצר. חתן ר יואל סופר בן הרש\"ס."},{"i":39980,"n":"פרנס, יהודה מוישניצא","f":"ברוך","b":"מראשי הקהל בוישניצא. חתנו היה ה\"ברוך טעם\"."},{"i":39981,"n":"פרנס, יוסף יצחק","f":"אברהם יהושע מדוקלא","bt":"תרלה","dt":"תשכז","b":"חסיד צאנז ושיניבה. חתן ר אברהם בנימין הלוי הורביץ. עבר לארה\"ב לפני מלחמת העולם הראשונה, והתגורר בבורו פארק."},{"i":39982,"n":"פרנס, יצחק משה מישניצה","f":"נתן נטע מישניצה","dt":"תרעז","dp":"צפת","b":"מחכמי ישניצה. מחותן לאדמור משיניבה. חתן ר יהושע השל פ\"ת בן ה\"ברוך טעם\". עלה לארץ-תרע והתגורר בצפת."},{"i":39983,"n":"פרנס, ישראל מטרנופול","f":"מרדכי שלמה מטרנופול","k":"בעל יפה נוף","bt":"תקצה","dt":"תרסה","b":"נכדו של ר גרשון מקיטוב (חתן הבעשט). רב בטרנופול-תרל. עודד לעליה לארץ ופעל ליסוד המושבה מחניים. חתן ר גדליהו דוד זיידען מפרימישלן. חיבר \"יפה נוף\" למברג תרנא."},{"i":39984,"n":"פרנס, מנחם מנדל מזבנא","f":"נתן נטע מישניצה","dt":"תרפב","dp":"טרנוב","b":"מחכמי זבנא. נכד ר שמעון מירוסלב - בביתו שרו את ניגון זקנו על \"תנו שבח ושירה\"."},{"i":39985,"n":"פרנס, משה המדפיס","f":"אליעזר הרופא","b":"מדפס בתורכיה-שז."},{"i":39986,"n":"פרנס, משה מירושלים","dt":"תמו","dp":"ירושלים","b":"נכד ר\"י פרנס אשכנזי. רב בירושלים."},{"i":39987,"n":"פרנס, נתן נטע מישניצה","f":"יצחק משה","bt":"תקן","dt":"תרל","b":"מחכמי ישניצה. חתנו של ר שמעון מירוסלב."},{"i":39988,"n":"פרנס, צדוק מדובנא (מארשלקוביץ)","f":"דוד מארשלקוביץ","dt":"תקצה - יט סיון","dp":"דובנא","b":"חתן ר מרדכי צבי הורביץ מהארחוב. גביר מחכמי דובנא, תמך בלומדי תורה ועניים בדובנא. ראה משפחת בר\"ץ בדובנא. בנו - הגביר ר יצחק איציקל ר צדוק'ס מארשלקוביץ. חתניו - ר נפתלי הרץ רפפורט בעל עזרת כהנים, ר יצחק אליהו לנדא, ר יעקב יעקל-(ממשפחת ר משה קרמר מוילנא), ר מרדכי זאב אשכנזי מלובלין,"},{"i":39989,"n":"פרנס, שבתי מירושלים","b":"מגדולי חכמי ירושלים-תק\"נ"},{"i":39990,"n":"פרנס, שלמה זלמן הלוי","f":"שמואל הלוי","b":"מגדולי ונכבדי וורשה-תק\"כ"},{"i":39991,"n":"פרנס-מרשלקוביץ - משפחה","k":"בר\"ץ - ברצ'ס","b":"משפחה בדובנא. נקראו גם ברצ'ס (בני ר צדוק'ס)."},{"i":39992,"n":"פרנסדורף, אהרן זלמן משה מהמבור","f":"מאיר","dt":"תקנו - כ אייר","dp":"המבורג","b":"דיין בהמבורג אצל ר רפאל הכהן. חתם על צוואת ר עקיבא בלוך. בנו - ר צדוק"},{"i":39993,"n":"פרנסדורף, זלמן מהנובר","f":"צדוק","k":"הו\"ל אכלה ואכלה","bp":"המבורג","dt":"תרם","dp":"הנובר","b":"חתן ר יוסף ברנד. ראש ביהמ\"ד למורים בהנובר. הו\"ל \"אכלה ואכלה\" לר אליהו בחור - עם מבוא ממנו. הו\"ל \"מסורה גדולה\" - הנובר תרלו."},{"i":39994,"n":"פרנסדורף, יעקב סגל","f":"מיכאל פרנסדורף","dt":"תרכא - יד ניסן","b":"מו\"צ בהנובר"},{"i":39995,"n":"פרנסדורף, מיכאל מהנובר","f":"מאיר","dt":"תקנה - ד כסלו","b":"דיין בהנובר (באוצר תאריך פטירתו - תקעא)"},{"i":39996,"n":"פרנסדורף, צדוק מהמבורג","f":"אהרן זלמן משה מהמבור","dt":"תקפב - כה חשון","dp":"אלטונא","b":"דרשן, מגיד בהמבורג (באוצר הרבנים תאריך פטירתו - תרח)"},{"i":39997,"n":"פרנסיס, אברהם משלוניקי","dt":"תסב","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":39998,"n":"פרנסיס, אברהם משלוניקי","f":"יצחק","k":"בעל שו\"ת","b":"רב בשלוניקי. חיבר שו\"ת ונדפס בסוף \"טל אורות\" - שלוניקי תקנח."},{"i":39999,"n":"פרנסיס, אליהו מאזמיר","b":"גביר באזמיר-שנות ה-תק'. נספד מאת - ר נסים חיים שלום מרגונטו."},{"i":40000,"n":"פרנסיס, אליהו משה מאמשטרדם","f":"משה","bt":"תרלה-ט","bp":"שלוניקי","dt":"תשב","b":"דיין בשלוניקי-תרפד, דיין באמסשרדם-תרפח והקים ישיבה שאליה צורפה הספריה של הקהלה, נספה בשואה. פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד, \"המאסף\"."},{"i":40001,"n":"פרנסיס, אליהו משלוניקי","dt":"ש - אחרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40002,"n":"פרנסיס, בכור שלמה משלוניקי","dt":"תרמג","dp":"שלוניקי","b":"גביר בשלוניקי-תריז ונמנה על שבעת טובי העיר, וסגן נשיא ועד הקהלה, וממונה מתעסק בצרכי ציבור."},{"i":40003,"n":"פרנסיס, דוד ממנטובה","dt":"תיא","b":"מחכמי מנטובה. בניו - ר עמנואל, ר יעקב."},{"i":40004,"n":"פרנסיס, חיים משלוניקי וחיפה","bt":"תרלה","bp":"שלוניקי","dp":"חיפה","b":"מחכמי שלוניקי, רב בחיפה-תרסט, דיין אצל ר' מסעוד התשואל תרסה."},{"i":40005,"n":"פרנסיס, יוסף מהמבורג","b":"משורר מחכמי הספרדים בהמבורג-שנות ה-ת'. חיבר שיר על תרגום \"ראשית חכמה\", שיר מספד על הקדוש ר אברהם נוניץ בערנר, ואת נוסח המצבה של ר יצחק ישורון אב\"ד קהל ספרדים בהמבורג."},{"i":40006,"n":"פרנסיס, יוסף משלוניקי","b":"דיין בשלוניקי-שיג, חיבר פירוש ל\"בחינות עולם\" פיררה שיד."},{"i":40007,"n":"פרנסיס, יעקב ממנטובה","f":"דוד","bt":"שעה","bp":"מנטובה","dt":"תכז - ה תמוז","dp":"פירנצי","b":"רב ומשורר. משיריו ב\"קול עוגב\". אחיו של ר עמנואל פראנסיס שכתב קינה לזכרו."},{"i":40008,"n":"פרנסיס, יעקב משלוניקי","dt":"תרלד - כה שבט","dp":"שלוניקי","b":"גביר בשלוניקי. נספה בשריפה בביתו עם כל משפחתו."},{"i":40009,"n":"פרנסיס, יצחק משלוניקי","dt":"תרפו","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":40010,"n":"פרנסיס, יצחק משלוניקי וקושטא-א","k":"פלפולא חריפתא","bp":"שלוניקי","dt":"תטו","dp":"קושטא","b":"תלמיד ר יצחק בארקי, ור חיים שבתי בשלוניקי, מרביץ תורה בקושטא-שפ, דיין-תטז עם ר חיים קטן ור יונתן גלנטי. רב הכולל בלאריסה. מתשובותיו ב\"פני משה\"."},{"i":40011,"n":"פרנסיס, יצחק משלוניקי וקושטא-ב","f":"משה","k":"בעל פני יצחק","dt":"תקג - לפני","b":"מרביץ תורה בקושטא-תק, רב הכולל בלאריסה(=לארסו) ור חיים בן דוד אבולעפיה מאזמיר על מקומו אחריו (ולפי רוזניס ר אליה חנדלי על מקומו אחריו כשעבר לשלוניקי). (יש המחליפים בינו לבין ר יצחק הראשון - אולם מתברר שהוא זה ששם אביו משה)."},{"i":40012,"n":"פרנסיס, מרדכי מדובניצה","b":"מראשי קהלת דובניצה-שנות ה-ת'-תק'."},{"i":40013,"n":"פרנסיס, מרדכי ממצרים","b":"גביר מחכמי מצרים-שי. דודו וחותנו של האר\"י, שגדל אצלו אחר שנתייתם מאביו."},{"i":40014,"n":"פרנסיס, מרדכי משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"פני אהרן\" לר אהרן אמריליו-תקנו, יחד עם אחיו שלמה."},{"i":40015,"n":"פרנסיס, מרדכי משלוניקי","dt":"תקצד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40016,"n":"פרנסיס, משה משלוניקי","f":"דוד","bt":"תריג","bp":"שלוניקי","b":"מחכמי שלוניקי, עלה לירושלים-תרצג. בנו - ר אליהו מאמשטרדם."},{"i":40017,"n":"פרנסיס, עמנואל מאיטליה","f":"דוד","k":"בעל צבי מודח","bt":"שעח","bp":"ליוורנו או מנטובה","dt":"תסג - תעח","dp":"ליוורנו","b":"משורר מחכמי איטליה בונציה ומנטובה, עבר לאלגיר-תל, חתם שם על הסכמה-תסג. חזר לאיטליה ויחד עם אחיו-ר יעקב חיבר שירים כנגד שבתי צבי בשם \"צבי מודח\". חתם עם רבני אלגיר-תסג על הסכמה ל\"הלכות קטנות\" לר יעקב חאגיז. שיר ממנו ב\"דבר שמואל\". חתם-תנט על מכתב תמיכה בר משה חגיז-המני\"ח."},{"i":40018,"n":"פרנסיס, ציון","b":"רב באיטליה. חתם עם הרמ\"ע בפסק \"ימין ה' רוממה\" ועם ר עובדיה ספורנו."},{"i":40019,"n":"פרנסיס, שלמה דוד משלוניקי","dt":"תרכב","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":40020,"n":"פרנסיס, שלמה משלוניקי","dt":"תקעד - תמוז","dp":"שלוניקי","b":"גביר בשלוניקי. נפטר במגיפה. נספד ע\"י ר יעקב מנשה משלוניקי."},{"i":40021,"n":"פרנסיס, שלמה משלוניקי","dt":"תלו - כז אדר","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד ר אברהם מוטאל. נספד ע\"י ר שלמה אמריליו."},{"i":40022,"n":"פרנסיס, שלמה משלוניקי","dt":"תקעד","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"פני אהרן\" לר אהרן אמריליו-תקנו, יחד עם אחיו מרדכי."},{"i":40023,"n":"פרנסיס, שמואל מירושלים","dt":"תרי - ו חשון","b":"מחכמי ירושלים."},{"i":40024,"n":"פרנע, יוסף חיים מוארשא","k":"בעל גן יוסף","b":"רב בוארשא-תרנב."},{"i":40025,"n":"פרנצבלוי, אברהם נורמן מארה\"ב","bt":"תרסא","bp":"ניו יורק","b":"תלמיד שלמה זלמן שכטר, מנהל ביהמ\"ד למורים של הריפורמים, מלמד בהיברו יוניון קולג'."},{"i":40026,"n":"פרנצבסקי, יוסף","dt":"תשג","b":"רב בפביניץ"},{"i":40027,"n":"פרנצבסקי, שמעון מיוזפוב","dt":"תשג","b":"רב ביוזעפוב. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":40028,"n":"פרנצוז, אלכסנדר חיים","f":"שמואל שמלקא","k":"הו\"ל ההפלאה","b":"הוציא לאור את חדושי הפלא\"ה - תרנה."},{"i":40029,"n":"פרנצוז, משה יהודה ליב","k":"בעל המליץ","b":"מצאצאי המהרש\"א. חיבר \"המליץ\" למברג תרץ."},{"i":40030,"n":"פרנציס, ישראל משקלוב וצפת","f":"יהודה","dt":"תקנב - לפני","b":"בשליחות-תקמח. בנו ר יודל."},{"i":40031,"n":"פרנק (ורנק), דוד מנירנברג","b":"מגדולי חכמי אשכנז,מרביץ תורה בטרברק, נירנברג-ריא-רכט."},{"i":40032,"n":"פרנק יששכר בר","bt":"1770","dt":"ה'תרה 1845","bk":[["חוט המשולש",""],["מחנה ישראל",""]]},{"i":40033,"n":"פרנק צבי פסח בן יהודה ליב","bt":"1873","dt":"ה'תשכ 1960","bk":[["דבר לישראל ולעמים",""],["הר צבי",""],["ימי הפורים",""],["שעשועי צבי",""]]},{"i":40034,"n":"פרנק, אברהם","f":"שלמה","k":"בעל כנור קטן","bt":"1884","bp":"מאריאמפול","b":"עלה לארץ וניהל בי\"ס ברחובות, עבר לוארשא-1909 ופרסם ב\"היינט\", \"הצפירה\", ועוד ובין מאמריו אודות ארץ ישראל. בשליחות \"מאמענט\" יחד עם אנסקי בישיבות ליטא ופולין."},{"i":40035,"n":"פרנק, אברהם שאול ליב מאלטונא","f":"הירש מאלטונא","dt":"תקצז - ב אד\"א","dp":"אלטונא","b":"מחכמי הקלויז ודיין באלטונא אצל ר עקיבא ורטהיימר. בנו - ר מנדל פרנק."},{"i":40036,"n":"פרנק, אברהם שלמה מלינץ","b":"רב בלינץ-אוסטריה."},{"i":40037,"n":"פרנק, אדולף מצרפת","k":"בעל שיטת חכמת הקבלה","bt":"תקסט","bp":"צרפת","b":"פרופסור בצרפת, סגן הקונסיסטואר בפאריס, נשיא חברת כי\"ח על מקום יצחק אדולף כרמיה. חיבר ספרים בפילוסופיה והיסטוריה. חיבר גם \"הפילוסופיה והאמונה\", ועוד."},{"i":40038,"n":"פרנק, אהרן","bt":"1889","bp":"שידלובה","dt":"1945","dp":"דכאו","b":"תלמיד ישיבות ליטא. מורה בבי\"ס עברי בנובו פולטבקה-אוקראינה. יסד את הגימנסיה העברית בוירבאלן יחד עם י. רבינזון. תרגם יצירות. למד במכון הגבוה למדעי היהדות בברלין. מורה בגימנסיה בוירבאלן, שאוולי. פרסם מאמרים בעתוני התקופה. נספה בשואה."},{"i":40039,"n":"פרנק, גרשון מפרשבורג","f":"בער מפרשבורג","b":"מראשי קהלת פרשבורג."},{"i":40040,"n":"פרנק, הירש מאלטונא","f":"חיים","bp":"הלברשטט","dt":"תקמח - ה אייר","dp":"אלטונא","b":"תלמיד ר צבי הירש ביאלע חריף מהלברשטט, ר ברוך כהנא רפפורט בפיורדא. חתן ר מנלי מאלטונא, ובזיוו\"ש חתן ר ליב דישערא. עסק במסחר עם הודו, גביר ודיין באלטונא אצל ר רפאל הכהן וחתם אחריו, ועמד לצדו של ר רפאל בזמן המחלוקת על הספר \"מצפה יקותיאל\". בניו: ר חיים, ר משה, ר אברהם שאול ליב. חיבר חדושים על הש\"ס - בכת\"י."},{"i":40041,"n":"פרנק, זאב מירושלים","k":"בעל תולדות זאב","b":"מחכמי ירושלים-תרץ. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":40042,"n":"פרנק, י' ל'","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":40043,"n":"פרנק, יעקב","f":"ליב","bt":"תפו","bp":"ברז'אנקה-ליד הוסיאטין","dt":"תקסב - יג כסלו","b":"מיסד תנועת הפרנקיסטים, השתמד. בניו - ליב עמנואל (תקיז-תקכג), יעקב (תקכב-תקלג), רוך (תקכד-תקעז), יוסף (תקכח-תקנז), בתו - חוה - עמדה בראש כת הפרנקים אחר פטירתו."},{"i":40044,"n":"פרנק, ישכר בער מפרשבורג","f":"גרשון","k":"בעל מחנה ישראל","dt":"תרה - ז סיון","dp":"פרשבורג","b":"אביו הגיע מתורכיה והתישב בצוקרמנדל, ואח\"כ פרשבורג. מחכמי פרשבורג, שו\"ב, מזכיר הקהלה בזמן החת\"ס, ביקר את אמו של החת\"ס בפרנקפורט בשליחותו. חיבר \"מחנה ישראל\" וינה תקעו - דיני נידה בגרמנית, מודע עלי דרך, ועוד. צייר אומן וצייר גם את החת\"ס. חתנו - ר אשר וכטרליץ מפרשבורג."},{"i":40045,"n":"פרנק, מאיר הכהן מהידוועג-ארדא","f":"שמחה הכהן","b":"תלמיד הכת\"ס והשב\"ס. מחכמי הידוועג-ארדא-תרמג, ולמד שם את מלאכת השו\"ב משוחטי פרשבורג."},{"i":40046,"n":"פרנק, מנדל מבריסק","b":"רב בפוזנא, בריסק-רפט."},{"i":40047,"n":"פרנק, משה מאלטונא","f":"הירש מאלטונא","b":"תלמיד ר יונתן איבשיץ, גביר מחכמי אלטונא. החזיק בפירוש לספר בראשית בכת\"י מרבו - ר יונתן איבשיץ."},{"i":40048,"n":"פרנק, משה קלונימוס","k":"בעל השם אקרא","b":"חסיד בובוב. תלמיד ר יהושע פנחס בומבך מדרוהוביטש. חתן ר שמחה הכהן רפפורט מפריסטיק. בוחן בישיבת צאנז. חיבר \"השם אקרא\" בילגוריא תרצג. ?? לא באוצר ??"},{"i":40049,"n":"פרנק, ניסן","f":"יואש","k":"בעל רשל","bt":"1889","bp":"ליטא","b":"תלמיד \"מקוה ישראל\". עבר למצרים ויסד אגודה לתיאטרון. עבר לפאריס וחיבר מחזות בעברית וצרפתית, ופרסם בעתונים יהודיים ברחבי העולם. חיבר גם \"פאריזער מאטיווען\", ועוד. ?? לא באוצר ??"},{"i":40050,"n":"פרנק, פסח","f":"שרגא פיבל מאלקסוט","b":"חתן ר ליב ברוידא-אחיו של ר שמחה זיסל מקעלם. גיס-אחי אשתו של ר איסר זלמן מלצר, ור משה מרדכי אפשטין."},{"i":40051,"n":"פרנק, צבי פסח מירושלים","f":"יהודה ליב","k":"בעל הר צבי","bt":"תרלג-ז","bp":"קובנא","dt":"תשכא - כב כסלו","b":"תלמיד ישיבות טלז, סלובודקה, עלה לירושלים-תרנב עם הוריו ולמד בישיבת \"תורת חיים\" בירושלים. דיין אצל ר שמואל סלנט-תרסח, רב בירושלים-תרסז, ואב\"ד-תרצה. יסד את \"מדרש בני ציון\" - לבירור הלכות התלויות בארץ והו\"ל \"כרם ציון\" - ירושלים תרצה ופרסם שם מאמרים. חיבר גם \"מילי דברכות\", ועוד. פרסם מאמרים ב\"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קול תורה\" - ירושלים תרץ, \"שערי ציון\" - ירושלים תרפא, \"תורת ארץ ישראל\" - ירושלים תרץ.","bk":[["הר צבי","שו\"ת - אחרונים"]]},{"i":40052,"n":"פרנק, שמואל תנחם מירושלים","b":"מזכיר בית הדין הרבני בירושלים-תשך."},{"i":40053,"n":"פרנק, שרגא פיבל","b":"גביר מחכמי אלקסוט-תרם. בניו - ר רפאל, ר פסח. חתניו: ר איסר זלמן מלצר, ר משה מרדכי אפשטין, ר ברוך הורביץ מאלקסוט, ר שבתי קרמר מסלוצק."},{"i":40054,"n":"פרנק, שרגא פיבל מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג."},{"i":40055,"n":"פרנק-קמינצקי, משה דוד","k":"בעל ביאור לבחינת עול","b":"חיבר ביאור לבחינת עולם."},{"i":40056,"n":"פרנקו אלמידה, אברהם משלוניקי","dt":"תקד","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":40057,"n":"פרנקו מנדס, דוד (חפשי)","k":"בעל שפר התקונים","bt":"תעג","bp":"אמשטרדם","dt":"תקנג - כד תשרי","dp":"אמשטרדם","b":"מקובל, מחבר, משורר, מחכמי הספרדים באמשטרדם, מראשי ביהמ\"ד \"עץ חיים\", היתה לו יד במדעים, מתלמידי הרמח\"ל. מאמר ממנו ב\"פרי עץ חיים\" - אמשטרדם - ובו לתולדות הישיבה. חיבר גם \"גמול עתליה\", \"שפר התקונים\" ובסופו תולדות גדולי ישראל באמשטרדם."},{"i":40058,"n":"פרנקו סראנו, יוסף מאמשטרדם","b":"מחכמי אמשטרדם, ראש ישיבה. תרגם תורה לספרדית עם פירוש וביאור לתרי\"ג מצוות - אמשטרדם תנה."},{"i":40059,"n":"פרנקו, אברהם מחברון","f":"נסים","bt":"תרנז","bp":"חברון","b":"תלמיד ר יצחק מלכיאל מני, ר יוסף מני, ישיבת \"שדי חמד\", למד רוקחות, עסק בהוראה וברוקחות, מנהל בי\"ס לשומרונים בשכם, בחברון, פעיל בהסתדרות הספרדים, ומנהל הכוללות בחברון."},{"i":40060,"n":"פרנקו, אברהם מליוורנו","f":"משה מליוורנו","b":"גביר בליוורנו, יסד עם אחיו יוסף ורפאל ישיבה ובימ\"ד בירושלים בשם \"יפאר ענוים\" ובראשה-תקיח עמד - ר אברהם בן אשר."},{"i":40061,"n":"פרנקו, אברהם מקושטא","f":"שלמה","b":"מדפיס בקושטא לצד אביו. חתנו - ר אברהם בן מאיר רוזניס - שסייע לו בהגהת והדפסת \"זהב שב\"א\"."},{"i":40062,"n":"פרנקו, אברהם משלוניקי","dt":"רפא - כ טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40063,"n":"פרנקו, בן ציון","f":"חיים רחמים יוסף","bt":"תריח","dt":"תרמא"},{"i":40064,"n":"פרנקו, בן ציון בכור מחברון","f":"מאיר רבנו","bp":"חברון","b":"למד רפואה בביירות, עבר לחיפה ועסק ברפואה-תרפב."},{"i":40065,"n":"פרנקו, גבריאל אהרן"},{"i":40066,"n":"פרנקו, דוד מאמשטרדם","k":"בעל דברי הימים לבני"},{"i":40067,"n":"פרנקו, דוד מונציה","b":"רב בויניציאה-ש\"פ"},{"i":40068,"n":"פרנקו, חזקיה מרודוס","f":"משה מירושלים","b":"גביר מראשי הקהלה ברודוס, עורך העתון התורכי \"סילאם\" ומקורב לשלטון האיטלקי, יסד וערך באזמיר \"איל קומירסייאל\", בקושטא - \"לה בוז די אוריינטי\"-תרצא."},{"i":40069,"n":"פרנקו, חיים מגליפולי","bp":"מעלאס","b":"רב בגליפולי-תרנד."},{"i":40070,"n":"פרנקו, חיים רחמים יוסף-החרי\"ף","f":"רפאל נסים","k":"בעל שערי רחמים","bt":"תקצה","bp":"רודוס","dt":"תרסב - כח חשון","dp":"חברון או ירושלים","b":"תלמיד ישיבת \"ישראל\" ברודוס וחתן רבו ר רפאל יצחק ישראל, רב סופר בי\"ד ודיין ברודוס, עלה לירושלים-תרכח וכיהן כדיין אצל ר יעקב שאול אלישר, בשליחות באירופה-תרל, ואחר בשליחות בקושטא ובוינה שם פגש את הקיסר פרנץ יוסף הראשון, אחר כך בשליחות בצפון אפריקה-תרלו. רב בחברון-תרלח על מקום ר אליהו מני שהתפטר מתפקידו, ובעל ה\"שדי חמד\" על מקומו אחריו. חיבר \"שערי רחמים\" ירושלים תרמב, ועוד. חלקם בכתב יד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":40071,"n":"פרנקו, חיים שלמה","bt":"תקנט","b":"עלה לצפת בשנת תקץ ונמנה על חכמיה, בשליחות באפריקה בשנת תקצב, ואדרינופול בשנת תרב."},{"i":40072,"n":"פרנקו, יהודה משלוניקי","dt":"שפה - כ תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40073,"n":"פרנקו, יהודה מתונס","b":"מחכמי תונס,רב בסוסא-תקל\"ג"},{"i":40074,"n":"פרנקו, יוסף מאיטליה","k":"בעל שלחן הפנים","b":"מגדולי חכמי איטליה-ש\"נ"},{"i":40075,"n":"פרנקו, יוסף מליוורנו","f":"משה מליוורנו","b":"גביר בליוורנו, יסד עם אחיו אברהם ורפאל ישיבה ובימ\"ד בירושלים בשם \"יפאר ענוים\" ובראשה-תקיח עמד - ר אברהם בן אשר."},{"i":40076,"n":"פרנקו, יוסף מרודוס","b":"רב ברודוס-תק\"צ"},{"i":40077,"n":"פרנקו, יוסף משלוניקי","dt":"תך - ה שבט","dp":"שלוניקי","b":"מחכמי שלוניקי. מצאצאי ר יצחק פרנקו."},{"i":40078,"n":"פרנקו, יעקב מחברון","f":"מאיר רבנו מחברון","bt":"תרנח","bp":"חברון","b":"פרסם מאמרים בשפות שונות, מעורכי \"דאר היום\", עבר לביירות."},{"i":40079,"n":"פרנקו, יצחק מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":40080,"n":"פרנקו, יצחק ממגניסיאה","b":"מחכמי מגניסיאה-שנות ה-ת' (אחר פטירת ר משה עוזיאל)."},{"i":40081,"n":"פרנקו, יצחק משלוניקי","dt":"שפא - ח אב","dp":"שלוניקי","b":"מרביץ תורה בשלוניקי-שף."},{"i":40082,"n":"פרנקו, יצחק משלוניקי","dt":"ת","b":"דיין ור\"מ בשלוניקי. חתם עם מהרשד\"ם-שכב."},{"i":40083,"n":"פרנקו, מאיר רבנו מירושלים","f":"רחמים יוסף-שערי רחמי","bt":"תרכו","bp":"ירושלים","dt":"תרצא-ז -כז תשרי","b":"מחכמי חברון, דיין אצל ר חזקיה מדיני, לימים רב העדה בחברון. דברי תורתו בספר אביו \"שערי רחמים\" ובקבצי תורה ובהם \"המאסף\". נשאר רב ספרדי יחיד בחברון אחר הטבח-תרפט, רב העדה החברונית בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":40084,"n":"פרנקו, משה יהודה מירושלים","f":"יוסף","bt":"תקצז","bp":"רודוס","dt":"תרעח - א טבת","dp":"ירושלים","b":"מחכמי רודוס. נתמנה לרב-תרנא והיה מחלוקת על כך אולם לבסוף הוכר ע\"י כל הסיעות. עלה לירושלים-תרעב ונבחר (שלא על דעתו) לכהן כראשון לציון על מקום ר נחמן בטיטו, והיה מחלוקת על כך, ופרש-תרעה (בזמן מלחמת העולם הראשונה)."},{"i":40085,"n":"פרנקו, משה מאיטליה","f":"שלמה","b":"מחכמי ליוורנו ותלמיד ר חיים ן עטר בעל \"אור החיים\", ועלה לירושלים עם בני חבורתו של ר חיים בן עטר ולמד בישיבתו בשנת תקב. ערך את ספר רבו \"מאור החיים\". אולי בניו - הגבירים מליוורנו - יוסף, רפאל ואברהם - שיסדו את ישיבת \"יפאר ענוים\"."},{"i":40086,"n":"פרנקו, משה ממצרים","b":"מחכמי מצרים-תס."},{"i":40087,"n":"פרנקו, משה ממרוקו","dp":"סאלי-מרוקו","b":"מחכמי סאלי ומלומד בנסים."},{"i":40088,"n":"פרנקו, משה מסרייבו","b":"גביר מראשי קהלת סרייבו-שנות ה-ת'."},{"i":40089,"n":"פרנקו, נסים רפאל מחברון","f":"רחמים יוסף","bt":"תרלד","bp":"ירושלים או חברון","dt":"תרעג - כב ניסן","dp":"חברון","b":"מחכמי ירושלים, שו\"ב מחכמי חברון, ר\"מ בישיבת ר חזקיהו מדיני. בשליחות במצרים-תרעב, כשחזר היה דיין בחברון אצל ר חנוך חסון. יסד חברת חסד \"צדקה ומרפא\"."},{"i":40090,"n":"פרנקו, רפאל אליעזר","b":"מגדולי רבני ירושלים-תקצ\"ו"},{"i":40091,"n":"פרנקו, רפאל מליוורנו","f":"משה מליוורנו","b":"גביר בליוורנו, יסד עם אחיו אברהם ויוסף ישיבה ובימ\"ד בירושלים בשם \"יפאר ענוים\" ובראשה-תקיח עמד - ר אברהם בן אשר."},{"i":40092,"n":"פרנקו, רפאל מצפת","b":"מחכמי צפת. בשליחות צפת בחו\"ל. נזכר ב\"קול יעקב\" ושם שירים לכבודו."},{"i":40093,"n":"פרנקו, רפאל משלוניקי","b":"מדפיס בשלוניקי אצל יתומי בצלאל אשכנזי-תקיג."},{"i":40094,"n":"פרנקו, שלמה ממצרים","k":"בעל פירוש על אבן עזר","b":"רב בנא אמון(=אלכסנדריה), עם מות בנו במגיפה עלה עם כל בני עירו ועלה לרמלה-שסב. חיבר פירוש על אבן עזרא. אחיו - ר שם טוב מאלכסנדריה."},{"i":40095,"n":"פרנקו, שלמה מקושטא","dt":"ת","b":"מדפיס בקושטא-שצט. בנו - אברהם וחתנו - יעקב בכר שלמה גבאי - מדפיסים על מקומו אחריו."},{"i":40096,"n":"פרנקו, שם טוב מאלכסנדריה","b":"מחכמי אלכסנדריה-שסב, נזכר ב\"אהלי יעקב\" לר יעקב קשטרו."},{"i":40097,"n":"פרנקו, שמואל מירושלים","dt":"תקעג - כז אב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":40098,"n":"פרנקו, שמואל משלוניקי","dt":"רעה - לפני","b":"מקובל מחכמי ספרד, עבר לשלוניקי בזמן גירוש ספרד-רנב, נזכר במהרשד\"ם."},{"i":40099,"n":"פרנקל אברהם בן זאב וולף","bt":"1910","dt":"ה'תשד 1944","bk":[["דופקי תשובה",""]]},{"i":40100,"n":"פרנקל איסר","bt":"1933","dt":"ה'תשע 2010","bk":[["תפילין",""]]},{"i":40101,"n":"פרנקל זכריה","bt":"1801","dt":"ה'תרלה 1875","bk":[["דרכי המשנה",""],["מבוא הירושלמי",""]]},{"i":40102,"n":"פרנקל יעקב יהודה אריה ליב בן יום טוב צבי","dt":"ה'תש 1940","bk":[["גבורת אריה",""],["לקוטי מהרי\"ל",""],["מגדנות מהרי'ל",""]]},{"i":40103,"n":"פרנקל תאומים, פנחס","b":"רב-שנת תר\"ל"},{"i":40104,"n":"פרנקל, אברהם אבא משדליץ","bt":"תרלב","dt":"תשכא","b":"תלמיד ר אברהם בורנשטין בעל \"אבני נזר\"."},{"i":40105,"n":"פרנקל, אברהם אביש מאלפין","b":"מחכמי אלפין. חתן ר יעקב הורביץ ממעליץ."},{"i":40106,"n":"פרנקל, אברהם אלתר מניגרעשט","b":"חתן ר אהרן מרגליות-פרקש מניגרעשט. גיסו ומחותנו-תרסה של ר מאיר וייס ממאדיאר לאפוש."},{"i":40107,"n":"פרנקל, אברהם זאב וולף מפשוורסק","f":"בנימין מלינסק","k":"בעל משיב כהלכה","bt":"תקם","bp":"לינסק","dt":"תרט - א שבט","b":"תלמיד החוזה מלובלין. שינה שמו מריישר לפרנקל בעברו לרישא. חתן ר אברהם משה מפשוורסק, ובזיוו\"ש חתן הגביר ר דוד נתנזון מברודי. (ולפי אלפסי חתן ר יעקב מקטילבורג-חתן ר שמואל שמלקא מניקלשבורג). רב בפשוורסק, ברודי, רישא. מקורב לאדמורים. חיבר \"משיב כהלכה\" קראקא תרמה."},{"i":40108,"n":"פרנקל, אברהם חיים מלימנוב","f":"ראובן","dt":"תרצא","dp":"קראקא","b":"חסיד שינאווא וצשינוב. חתן ר אלכסנדר זושע בלויגרונד. ראה קהילת לימנוב."},{"i":40109,"n":"פרנקל, אברהם מאוסטרוב ולומזה","f":"מרדכי דב","bt":"תרם","b":"רב באסטראוו(אוסטרוב)-פלך לומזה-תרסד."},{"i":40110,"n":"פרנקל, אברהם מאיר מארה\"ב","f":"זאב וולף","bt":"תרכג","bp":"נאוידואהר","dt":"תרצג - ו חשון","b":"תלמיד ונכד-אבי אמו ר גרשון זאגערער מביאליסטוק, תלמיד ישיבת גרודנא אצל ר פרץ חריף, ור משה. חתן הגביר ר ישראל רודנסקי מרודזישאק-ליד וילנא. מו\"צ בוילנא-תרנה, באפלו-ניו יורק-תרסא. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר יצחק יעקב ריינס, ר מרדכי מאשמינא, רי\"מ מסלובודקא."},{"i":40111,"n":"פרנקל, אברהם מויליפולי","f":"שלמה זלמן מויליפולי","k":"אדמור מויליפולי","bt":"תרב","dt":"תרנא - ט שבט","dp":"רישא","b":"אדמור בויליפולי על מקום אביו. חתן ר יעקב יצחק מוויניטש. מפורסם כבעל מופת."},{"i":40112,"n":"פרנקל, אברהם מידלוב","dt":"תש","b":"רב ביעדלוב-פולין."},{"i":40113,"n":"פרנקל, אברהם מלבוב","f":"מרדכי אריה","k":"אדמור מפרימישלן-למב'","b":"אדמור מפרימישלן בלמברג. אחיו ר צבי אדמור בפרימישלן."},{"i":40114,"n":"פרנקל, אברהם מנאיראד-סערעדא","f":"זאב מבוסרמין","k":"בעל דופקי תשובה-תשב","bt":"תרע","dt":"תשד","b":"מצאצאי האדמור ר שמואל פרנקל-מב\"ח מדאראג. תלמיד ר משה פורהאנד ממאקאווע. חתן ר גרשון מנדל קאהן מערדא-סענזשארץ. רב בנאיראד-סערעדא. נספה בשואה."},{"i":40115,"n":"פרנקל, אברהם מ\"ש מבודפשט","bt":"תר-תרב","bp":"דברצין","dt":"תרצו - כח תשרי","b":"תלמיד השב\"ס, וישיבת גרוסורדין. פרנס וראש רבני הונגריה האורטודוכסים בבודפשט. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה, \"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":40116,"n":"פרנקל, אברהם שרגא צבי מדאראג","f":"שמואל מדאראג","k":"אדמור מדאראג","dt":"תרסח - ב-כ טבת","dp":"בערטי-אויפאלו","b":"נבחר כאדמור בדאראג על מקום אביו-תרמג אך סירב ועבר לברט אויפלו, וגיסו ר זאב וולף ציטרון נתמנה לאדמור."},{"i":40117,"n":"פרנקל, אהרן מארה\"ב","k":"מתרגם במעון אריות","bt":"1886","bp":"מאראטש","b":"היגר לארה\"ב וניהל בי\"ס של יק\"א. פרסם ב\"העולם\" מאמרים על המושבות היהודיות בקנדה. הו\"ל את \"האומה\", הצטרף ללגיון היהודי בזמן מלחמ\"ה ה-I ושהה כמה שנים בארץ ישראל. תרגם רומן של קולונל פטרסון \"במעון אריות\"."},{"i":40118,"n":"פרנקל, אהרן מקאסאן","b":"רב בקאסאן-תק\"צ"},{"i":40119,"n":"פרנקל, אורי ליפמן מאונסדורף","f":"אליעזר פרנקל","b":"נכד ר שרגא פיבש פרנקל, וה\"צמח צדק\". מבניו: ר יצחק, ר שרגא פיבש מרוסקא, ר ברוך מקאליב."},{"i":40120,"n":"פרנקל, איזיק שלום מבייאה","b":"דיין בבאייה-תקן-תקס בערך."},{"i":40121,"n":"פרנקל, אליהו מלאואלאק","f":"מאיר יהודה פרנקל","k":"בעל אבני אליהו","dt":"תרמח - טו סיון","b":"תלמיד ר אשר אנשל יונגרייז בעל מנחת אשר. רב בלעוועלעק(=לאואלאק)-מחוז סאבולץ. חיבר גם \"אורות אלים\". חתנו ר אברהם בצלאל גרינוולד על מקומו אחריו."},{"i":40122,"n":"פרנקל, אליהו מפשוורסק","dt":"תש","b":"רב בפשוורסק"},{"i":40123,"n":"פרנקל, אלימלך מירוסלב","dt":"תשא","b":"רב ביערוסלב"},{"i":40124,"n":"פרנקל, אליעזר מטרנוב","bt":"תרמט","bp":"טרנוב","b":"תלמיד ביהמ\"ד בברלין-תרסו. עלה לארץ-תרעא, רב בדולה-טוסלה-תרעג."},{"i":40125,"n":"פרנקל, אליעזר משלאגטריאן","dt":"תשד","b":"מרביץ תורה בשלגאטריאן"},{"i":40126,"n":"פרנקל, אלעזר אלימלך מפרשבורג","dt":"תשד","b":"מרבני פרשבורג"},{"i":40127,"n":"פרנקל, אלעזר מדינוב","f":"אלתר מדינוב","b":"רב בדינוב-תרעט."},{"i":40128,"n":"פרנקל, אלתר אריה ליב מגלינא","f":"יוסף שאול מגלינא","dt":"תרע.. - בערך","b":"דיין מחכמי גלינא. חתן ר משה כהן רפפורט מליזנסק. הביא לדפוס-תרנח את \"תורת הראם\" לזקנו."},{"i":40129,"n":"פרנקל, אפרים פישל מביאלא","f":"יצחק פרנקל","b":"רב בביאלא-תק\"צ"},{"i":40130,"n":"פרנקל, אריה ליבש","f":"יצחק מאיר פרנקל"},{"i":40131,"n":"פרנקל, אשר ישעיה מסטרליסק","f":"ישראל אריה ליב","k":"אדמור מסטרליסק","bt":"תרלט","dt":"תשב","b":"בן האדמור מפרימישלן. חתן ר לוי יצחק קליגהופט האדמור מסטרליסק. אדמור בסטרליסק על מקום חותנו. עבר לסטרי. נספה בשואה."},{"i":40132,"n":"פרנקל, בן ציון מניו יורק - א","f":"יוסף חיים משנדישוב","dt":"תשלה - ד תמוז","dp":"ניו יורק","b":"רב קהילת \"בני שלמה זלמן\" בניו יורק."},{"i":40133,"n":"פרנקל, בן ציון מניו יורק - ב","f":"שלמה זלמן מויליפולי","b":"בן האדמור מויליפולי בנ\"י. רב בקהילת \"בני רבי שלמה זלמן\" בפלטבוש."},{"i":40134,"n":"פרנקל, בנימין","k":"בעל נצח והוד","bp":"וארשא","b":"חיבר \"נצח והוד\", \"תרועת מלך\" - לונדון תקצו. היה באיטליה ופגש את ר מרדכי גירוני המספר עליו בספרו."},{"i":40135,"n":"פרנקל, בנימין מהאנוי","b":"רב בהאנוי-תקכ. חתנו - ר מרדכי אדלר ונכדו ר נתן אדלר מלונדון."},{"i":40136,"n":"פרנקל, בנימין ריישר מלינסק","f":"צבי הירש מפשוורסק","b":"גביר מחכמי לינסק, ועבר לרישא (מכאן שמו ריישר)."},{"i":40137,"n":"פרנקל, ברוך מסוקולוב","f":"ישראל אריה ליב","k":"אדמור מסוקולוב","b":"בן האדמור מפרימישלן. חתן ר יעקב הלפרין מסוקוליבקה. אדמור בסוקולוב, ואחר בלמברג, רב בפעסט. בנו ר ישראל אריה ליב הלפרין - אדמור בלמברג ובניו יורק. הדפיס \"הליכות עולם\" למברג תרסז עם הקדמה ממנו."},{"i":40138,"n":"פרנקל, ברוך מרדכי מאשווער","f":"אליהו","dt":"תרטו - ח אב","dp":"גרוסורדין","b":"נכד ר ישראל איסר מבאכטא מצאצאי ר יעקב קופל מליקובא. אביו היה מחסידי אשווער(=אש ואור) של ר יצחק איזיק מקאליב. תלמיד ר לוי יצחק מברדיטשוב, ור אהרן מזיטומיר, נחשב לאחד מאבות החסידות בהונגריה. בסוף ימיו בגרוסורדין."},{"i":40139,"n":"פרנקל, ברמן מאנסבך","f":"קאפל פרנקל מווינה","dt":"תסט","b":"רב באנסבך"},{"i":40140,"n":"פרנקל, גרשון דוד מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":40141,"n":"פרנקל, גרשון מפפד\"א","b":"רב בפפד\"א-תק. הסכים על 'באר יעקב'-פיורדא תקכז."},{"i":40142,"n":"פרנקל, דוד מברלין","f":"נפתלי הירש ניימרק מי","bp":"ברלין","b":"תלמיד ישיבות קוברין, בריסק. בקי באגדה ובספרות יהודית. צמחוני וטבעוני. בגיל 17 התמנה למגיד בקמניץ, והתפרסם מאוד. בשליחות חובבי ציון ברוסיה ובהשפעתו נוסדו עשרות אגודות לישוב הארץ, אולם היה גם מחלוקת כנגדו והיו שרדפוהו על דעותיו העצמאיות. היגר ללונדון-תרן וכיהן כמטיף-דרשן באנגלית."},{"i":40143,"n":"פרנקל, דוד מדורנווטורא","bt":"תרכז","dt":"תרצג - יג תשרי","b":"רב בדורנווטרא-תרנ\"ט,ניו יורק-תרע\"ב"},{"i":40144,"n":"פרנקל, דוד מדעסוי","f":"משה","dt":"1865","b":"מנהל ביה\"ס מטעם הממשלה. סופר בלשון אשכנז. הו\"ל כתב עת \"שולמית\" והוא הראשון בגרמנית - יחד עם ר זאב וולף."},{"i":40145,"n":"פרנקל, דוד מהאנוי","b":"מצאצאי ר שאול וייל. רב בהאנוי(=הנאו). חתנו ר מרדכי אדלר מהנובר, ונכדו - ר נתן מלונדון."},{"i":40146,"n":"פרנקל, דוד מהוסיאטין","f":"יחזקאל מהוסיאטין","bt":"תרלו","bp":"סנוק","dt":"תשח","dp":"ניו יורק","b":"גיסו של ר ליפא שווגר. רב בהוסיאטין על מקום אביו. ניצל מהשואה ועבר לארה\"ב. הקים את חבורת \"דובבי שפתי ישנים\" בהוסיאטין כמשקל נגד לחברת מקיצי נרדמים בברלין - וההדירו והדפיסו ספרי קדמונים. ערך \"ספר היובל למארכס\" - ניו יורק תשג."},{"i":40147,"n":"פרנקל, דוד מירלש מברלין","f":"נפתלי צבי הירש מירלש","k":"בעל קרבן העדה","bt":"תסג","bp":"ברלין","dt":"תקכב - כב סיון","b":"תלמיד בישיבת ר יעקב הכהן או בישיבת ר מיכל חסיד בברלין. חתן ר ליב הלברשטט מהמבורג ועבר לשם, התישב בברלין ועסק במסחר באבנים טובות, מגדולי חכמי דורו, רב בדעסוי, רב בפפד\"א-תקג על מקום ר משה בן אהרן מלבוב, ראב\"ד (אך לא אב\"ד) גם בברלין והמדינה-תקד וראש ישיבה על מקום ר מרדכי טאקלעס שכיהן כאב\"ד על מקום ר יעקב יהושע בעל \"פני יהושע\" בעזרת גיסו ר נתן פייטל הפרנס שהתחייב לממן דיין נוסף לקהילה בגלל שלר דוד יש בקהילה קרובים מדרגה ראשונה שאינו יכול לדונם (והדיין שנבחר היה ר יואל זקש בן יקותיאל מגלוגא שהיה אב\"ד באוסטרליץ). גיסו-בעל אחותו ר יהושע השל בן שאול - אב\"ד וילנא. חיבר שיר לכבוד הצלחת המלך פרידריך במלחמה-תקה - תורגם ללשון אשכנז ע\"י ר אהרן בן שלמה גומפריש, ועוד שירים אח\"כ בתרגום משה מנדלסון לגרמנית. מתלמידיו - משה מנדלסון מדעסוי. חיבר פירוש לירושלמי בשם \"קרבן העדה\".","bk":[["קרבן העדה, שיירי קרבן",""]]},{"i":40148,"n":"פרנקל, דוד מנפלקוביץ","f":"יהושע מרישא","bt":"תרכב או תרכה","bp":"זבלטוב","dt":"תשב או תשה","b":"תלמיד ר משה הלברשטם מברדפלד, ר משה אפטר מטארני. חתן ר אליעזר יצחק גרדין מאיזביצא, ועבר לשם. רב בנפלקוביץ-תרן. נסמך מאת: ר יצחק אהרן אטינגא מלבוב, ר בעריש רפפורט מראווא רוסקא, ר משה בן עמרם מחוסט, ר אלסנדר שמואל הלפרין מלבוב. הניח חדושים, שו\"ת ודרושים - בכת\"י. נספה בשואה. בנו ר יהושע אב\"ד סלטין וצשינוב."},{"i":40149,"n":"פרנקל, הילמן","f":"יצחק","b":"נכד ר אלעזר קליר בעל אור חדש."},{"i":40150,"n":"פרנקל, וילהלם מפרשבורג","b":"נשיאה הראשון של הקהלה הניאולוגית בפרשבורג."},{"i":40151,"n":"פרנקל, זאב וולף מפשוורסק","k":"בעל משיב כהלכה","dt":"תרט - א חשון","b":"עשיר,רב ברישא,רב בפשוורסק"},{"i":40152,"n":"פרנקל, זאב מבוסרמין","b":"נכד האדמור ר שמואל מדאראג. שו\"ב בבוסערמין(=בוסרמין). בנו - ר אברהם מנאראד סערעדי."},{"i":40153,"n":"פרנקל, זכריה מברסלוי","f":"יעקב קופל","k":"בעל דרכי המשנה","bt":"תקסב","bp":"פרג","dt":"תרלה","b":"תלמיד ר בצלאל רגנשבורג. יסד את ביהמ\"ד לרבנים בברסלוי."},{"i":40154,"n":"פרנקל, זכריה מנדל מירוסלב","f":"מאיר פרנקל","b":"חתן ר אריה ליב הורביץ. רב בירוסלב(=יערוסלב)-תקע"},{"i":40155,"n":"פרנקל, זעקיל מהמבורג","f":"יצחק","k":"בעל כתובים אחרונים","bt":"1765","bp":"פארחים-מקלנבורג שוועדין","dt":"1835","dp":"המבורג","b":"גביר מלומד בהמבורג, ועמד בראש הטמפל הריפורמי. חיבר ספרים ומאמרים, תרגם מיונית ספרי פילוסופיה בשם \"כתובים אחרונים\", חיבר סידור חדש (ריפורמי) בלשון אשכנז עם חברו מאיר ברסלוי."},{"i":40156,"n":"פרנקל, חגי חנוך הלוי","f":"דוד הלוי","dt":"תנא - יג תשרי","b":"מחכמי וינה, עשיר, מרביץ תורה, לאחר הגירוש-תל - רב בפירט, במברג, האנוי, לאדמר (לודמיר?)"},{"i":40157,"n":"פרנקל, חיים","bt":"1857","bp":"וילקומיר","dt":"1920","dp":"הומברוג","b":"תלמיד ישיבת וולוזין. יסד בוילקומיר מפעל בורסקאות עם אחיו, מפעל לעורות בשאוולי. חתן דורה רוטהרוזן מדוינסק. פתח רשת בתי חרושת ועסק בעסקנות ציבורית ומפעלי חסד, ובהם \"הרחיב את ביה\"ח היהודי בשאוולי, מימן ת\"ת ל-250 ילדים, הקים ת\"ת בוילקומיר. ציר בועידת קובנא. בנו יעקב התישב בניו יורק."},{"i":40158,"n":"פרנקל, חנוך הניך מדורוהוי חיפה","f":"משלם זלמן רבין פרנק","k":"אדמור מרישא","bt":"תרמט","dt":"תשכד - יט סיון","dp":"חיפה","b":"חתן הגביר ר מיכל אהרן דילר מבלוזוב. כיהן כאדמור מרישא, רב ואדמור בדורוהוי-תרצו על מקום דודו - ר חיים רבינזון מדורוהוי בן האדמור בודורוהי ואביו, והמשיך גם בתקופת שלטון הקומוניסטים. עלה לארץ-תשכב, והקים את בית מדרשו \"יד יוסף\" בחיפה. בנו ר זלמן פרנקל."},{"i":40159,"n":"פרנקל, יאנו מסאגאד","b":"רב ניאולוגי בסאגאד, ניצל מהשואה ואחריה חזר לתפקידו כרב בסאגאד, עלה לארץ-1949, ור יוסף שינדלר על מקומו אחריו."},{"i":40160,"n":"פרנקל, יהודה אריה ליב","f":"משלם זלמן רבין פרנק","dt":"תרעז - ב סיון","b":"שם משפחתו כשם זקנו מצד אמו - ר לוי יצחק פרנקל מבוקרשט-נכד הבעשט. נכד ר יוסף אהרן רבין מדורוהוי ובוצאץ. אדמור על מקום זקנו-תרעג בבוטושאן."},{"i":40161,"n":"פרנקל, יהודה חריף מלוטימורסק","f":"יצחק","k":"בעל בית יהודה","bt":"תקו","dt":"תקסה - ז אב","b":"חתן ר שמואל לסקר מלוסק. רב בפודמביץ, לוטמירסק(=לוטימורסק), ראב\"ד בלוסק."},{"i":40162,"n":"פרנקל, יהודה יצחק אריה מלינסק","f":"חיים מרדכי מלינסק","k":"בעל שני צמידים","bt":"תקף","dt":"תרנג","b":"חסיד צאנז. רב בלינסק על מקום אביו. רב בסנוק-תריח. (לא נכנס במחלוקת צאנז סדיגורא בעירו). חתן ר מאיר ענגלרד מסנוק. חיבר \"שני צמידים\" פרמישלא תרם."},{"i":40163,"n":"פרנקל, יהודה יצחק מויליפולי","f":"שלמה זלמן מויליפולי","bt":"תרנז-סא","bp":"ויליפולי","dt":"תשמג","b":"נכד ה\"מאור ושמש\". תלמיד ר\"א שטינברג מברודי, ר פנחס הורביץ מברודשין, ונסמך מהם ומאת: ר\"ש פיהרר מקרוסני, ר\"ש הירץ מבורשטשוב, רי\"מ קאנאל, ר\"ח פוזנר, רח\"י גושכטר מוארשא. חתן ר אלעזר אפשטין מזלושיץ-ניישטט. עבר לזלושיץ והיה רב כעזר לחותנו, ר בידלובה-תרעח. עלה לארץ-תרצה והתישב בתל אביב."},{"i":40164,"n":"פרנקל, יהודה ליב הכהן מאודסה","b":"רב באדעס-תרמ, ובנו ר משה על מקומו אחריו."},{"i":40165,"n":"פרנקל, יהודה ליב מברלין","f":"דוד - קרבן העדה","bp":"דעסוי","dt":"תקסו - ד שבט","dp":"ברלין","b":"חתן ר שמואל הילמן ממיץ. רב בדעסוי. בנו - הגביר ר מיכל מברלין. חתנו הרופא ר נתן וינרסהיים כץ."},{"i":40166,"n":"פרנקל, יהושע","f":"פנחס פרנקל","b":"רב-שנת תר\"מ. חתן ר יעקב הגר, בנו ר דוד פרנקל."},{"i":40167,"n":"פרנקל, יהושע מדארנא-ווטרה","dt":"תשג","b":"רב בדארנא-ווטרא"},{"i":40168,"n":"פרנקל, יהושע מסניאטין","b":"תלמיד ר מאיר אריק, ה\"מחזה אברהם\", ר\"ש אנגל, בעל \"אבן יקרה\". אב\"ד סניעטין(=סניאטין)-תרצו."},{"i":40169,"n":"פרנקל, יהושע מרעטיאג","b":"רב בדעש. ראש ישיבה ברעטיאג. בנו - ר משה מזשיבא."},{"i":40170,"n":"פרנקל, יואל וולף מברסלוי","f":"דוד - קרבן העדה","bt":"תקו","b":"חתן קרובו ר יצחק יוסף תאומים מברסלוי ועבר לשם. נזכר בהקדמת ר איצק בחור מליסא ל\"שאילתות רב אחאי\" דירנפורט תקמו. בניו: הגבירים ר דוד ור יונה מברסלוי."},{"i":40171,"n":"פרנקל, יוחנן מפוטיק וזלוטי","b":"רב בפוטיק, זלוטי. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":40172,"n":"פרנקל, יונה מברסלוי","f":"יואל וולף בן דוד","dt":"1846","dp":"ברסלוי","b":"נכד ר דוד בעל \"קרבן העדה\". גביר בברסלוי. הקים מוסדות צדקה וחסד, ותרם מעזבונו להקמת ביהמ\"ד לרבנים בברסלוי-הוקם תריד."},{"i":40173,"n":"פרנקל, יוסף אהרן מפרשבורג","k":"בעל בית המדות","b":"מחכמי פרשבורג. חיבר \"בית המדות\" על מסכת מדות - טירנוי תשא."},{"i":40174,"n":"פרנקל, יוסף חיים משנדישוב","f":"אברהם מויליפולי","k":"אדמור משנדישוב-ויליפ","bt":"תרכה","dt":"תשב - ו אב","b":"רב בויליפולי-תרסד על מקום אביו, רב ואדמור בשנדישוב. חתן ר אלתר זאב הורביץ מסטריזוב (שושלת רופשיץ). ביקר בארץ-תרץ. היה בארה\"ב-תרץ וחזר לפולין. נספה בשואה. בניו ר שלמה זלמן - אדמור מויליפולי-ניו יורק, ר בן ציון - נפטר כז תמוז תשלט."},{"i":40175,"n":"פרנקל, יוסף מביליץ","f":"מנחם מנדל","bt":"תרלו","bp":"קראקא","dt":"תשד","b":"חסיד צאנז. גביר מחכמי קראקא. נספה בשואה. בנו ר שבתי מניו יורק - מו\"ל רמב\"ם פרנקל."},{"i":40176,"n":"פרנקל, יוסף מויליפולי","f":"בן ציון מניו יורק","k":"אדמור מויליפולי בנ\"י","b":"נכד האדמור ר שלמה זלמן מויליפולי. חתן ר לוי יצחק האדמור מבוסטון. אדמור בפלטבוש-נ\"י."},{"i":40177,"n":"פרנקל, יוסף שאול מגלינא","f":"אריה ליב","dt":"תרנז","b":"גביר מחכמי גלינא."},{"i":40178,"n":"פרנקל, יחזקאל מסנוק","f":"אברהם אבוש","k":"בעל דברי אברהם","bt":"תרא","dt":"תרעב","b":"חתן ר ברוך מנחם מנדל מבוכניה. רב בנוביטניץ-תרכט, סנוק(=סאנוק), הוסיאטין-גליציה-תרלז, חיבר \"דברי אברהם\" תרמו, \"תרת לרעותא\", \"קונטרס תרל\" קולומיאה תרנג, ועוד."},{"i":40179,"n":"פרנקל, יחזקאל שרגא מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":40180,"n":"פרנקל, יחיאל","b":"פרסם מאמרים ב\"בית המדרש\" - קראקא תרמח."},{"i":40181,"n":"פרנקל, יעקב ליב מסטמר","f":"יו\"ט צבי","k":"בעל משנת חסידים-תרסט","bt":"[תרי]","b":"מצאצאי ר יעקב החסיד מאש ואור - בישוב אשוואר-ליד קאליב. תלמיד בעל \"ייטב לב\" בסיגט. בזמן מלחמת העולם ה-I התגורר בכפר פירצא-ליד ניר-באטור, התישב בסטמר, ועסק בחיבור ומכירת ספרים. נפטר לפני השואה. חיבר גם \"גבורת אריה\" תרעו, \"מגדנות מהרי\"ל\", ועוד."},{"i":40182,"n":"פרנקל, יעקב מבוטושאן בני ברק","f":"מרדכי פרנקל מחיפה","k":"אדמור מבוטושאן ב\"ב","b":"חתן האדמור מאלכסנדר. אדמור מבוטושאן בני ברק."},{"i":40183,"n":"פרנקל, יעקב מקמינקא","b":"רב בקמינקא-תרלד, בנו ר שלום על מקומו אחריו."},{"i":40184,"n":"פרנקל, יעקב קופל סגל","b":"מגדולי ווינה-ת\"י"},{"i":40185,"n":"פרנקל, יצחק הלוי מפרדן","f":"חנוך הניך","dt":"תקטו - יח תשרי","b":"רב בפרדן"},{"i":40186,"n":"פרנקל, יצחק ידידיה מתל אביב","f":"אהרן","k":"בעל תעלומות חכמה","bt":"תרע","bp":"לונטשיץ","dt":"תשמו","b":"תלמיד ר\"מ זמבה בוארשא, ונסמך ממנו ומאת: האדמור מאוסטרובצה, אב\"ד בנדין, ר מאיר דן פלוצקי, ועוד. רב בריפין-תרצב, יפו-תרצה, תל אביב. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"המאור\" - תל אביב תרצה.","bk":[["דרך ישרה",""]]},{"i":40187,"n":"פרנקל, יצחק מחוסט וירושלים","f":"אליהו - אבני אליהו","bt":"תרכג","dt":"תרצא - אב","dp":"ירושלים","b":"אביו היה רבה של לעועלעק. נכד ר יואל צבי ראטה מחוסט. מגדולי הונגריה. עלה לירושלים-תרס. דיין אצל ר יוסף חיים זוננפלד ואצל ר יצחק ירוחם דיסקין. הוציא לאור ספרי אביו עם תוספות שלו ובהם \"ויעטר יצחק\" ו\"בני אלים\" ירושלים תרעג. חתם על כרוזים בנושאים שונים ובין היתר כנגד הרב קוק."},{"i":40188,"n":"פרנקל, יצחק מטיסמניץ","dt":"תקע - כג תשרי","b":"רב בטיסמניץ"},{"i":40189,"n":"פרנקל, יצחק מליכטנשטט","b":"תלמיד ר מאיר ברבי מפרשבורג. חתן ר אלעזר קליר בעל \"אור חדש\". רב בליכטנשטט-תקץ, פלאם."},{"i":40190,"n":"פרנקל, יצחק מלמברג","b":"רב ברודשין-תקס, טיסמניץ-תקסה (על מקום ר משולם איגרא). סידר והגיה \"שנות אליהו\" להגר\"א ועם הוספות משלו - תקנט."},{"i":40191,"n":"פרנקל, יצחק מקראלי ב\"ח-בית חלפ","f":"אורי ליפמן מבית חלפן","k":"בעל זבד טוב-תקסו","bt":"תקמב או תקלו","bp":"אונסדורף","dt":"תקצה - כח תשרי","dp":"קראלי","b":"תלמיד החת\"ס במטרסדורף. אחיו של ר יעקב ענגלנדר פרנקל. חתן ר יואב רוזנבוים מאונסדורף וסאטנוב (או סנטוב). רב בסנטוב על מקום חותנו-תקע, רב בקראלי(=קרולה)-תקפ על מקום ר משה אריה אסטרייכר (בהשפעת דוד אשתו הגביר ר ישעיה בן יצחק פריד מקרולה), חתנו - ר מאיר פרלס על מקומו אחריו. (אלמנתו נישאה לר מאיר א\"ש מאונגוואר - כשבא אביה לבחור חתן - הציע לו החת\"ס את שני הבחורים ובגורל נבחר ר יצחק, והבחור השני היה בעלה השני). ספרו \"זבד טוב\" נדפס עם ספר חותנו \"חן טוב\". הניח שבעה חבורים בכת\"י וציוה למכור את ספריתו כדי להדפיסם והדבר בא לפני החת\"ס אם לקיים את צוואתו. אלמנתו נישאה לר מאיר איזנשטט באישור החת\"ס ועל כך בשו\"ת חת\"ס."},{"i":40192,"n":"פרנקל, יצחק מקשביץ","b":"רב בקשביץ-תקצב אצל רצ\"ה הורביץ."},{"i":40193,"n":"פרנקל, יצחק מרוגנדורף","dt":"תקצג - כו ניסן","b":"רב ברוגנדורף,פרוינקירכן"},{"i":40194,"n":"פרנקל, ישראל אברהם מברוד","b":"מחכמי ברודי - תלמיד ר יצחק חיות. הוציא לאור ספר רבו \"שיח יצחק\" עם תוספות משלו - תרע. פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט."},{"i":40195,"n":"פרנקל, ישראל אריה ליב מפרמישלן","f":"צבי הירש מפרימישלן","k":"אדמור מפרימישלן","bt":"תקץ","dt":"תרנא","b":"חתן ר אלימלך רובין מסוקולוב. אדמור מפרימישלן על מקום אביו, בנו ר ישראל אריה על מקומו אחריו."},{"i":40196,"n":"פרנקל, ישראל אריה מטרנוב","b":"מחכמי טרנוב - תרפט."},{"i":40197,"n":"פרנקל, ישראל מברודא","f":"קאפל פרנקל","b":"רב בברודא-ת\"מ"},{"i":40198,"n":"פרנקל, ישראל משטמנסדורף","f":"פסח משטמנסדורף","k":"בעל שארית ישראל","bt":"תקצט","dt":"תרפב - יא כסלו","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור עזריאל הילסהימר מאיזנשטט, ומהר\"ם שיק. חתן ר יהודה שפיצר. רב בשטמנסדורף על מקום אביו, פרשבורג-תרעח. חיבר \"שארית ישראל\" ונדפס בסוף ספר אביו \"זבח פסח\". השתתף בועידת \"המזרחי\" בפרשבורג - למרות לחצים מצד חבריו החרדים לבל ישתתף. ?? לא באוצר ??"},{"i":40199,"n":"פרנקל, לודוויג אברהם אלעזר","k":"בעל ירושלימה","b":"בשליחות הגבירה עליזה הרץ למל מוינה, לצורך הקמת בתי ספר מודרנים בקהלות המזרח. חיבר ספר בגרמנית על מסעותיו בקהלות ישראל במזרח, ותורגם בחלקו לעברית בשם \"ירושלימה\"."},{"i":40200,"n":"פרנקל, לוי יצחק מבוקרשט","f":"משלם זלמן מירושיב","dt":"תרכד","b":"שינה שמו לפרנקל. נין לר לוי יצחק מברדיטשוב. רב בבוקרשט-תרט והיה לו מחלוקת שם - גם עם המלבים). חתן ר יעקב יוסף טירר ממאהליב. עלה לארץ-תרלב והתישב בצפת. מכתב אליו ב\"פליטת סופרים\" - וילנא תרכג."},{"i":40201,"n":"פרנקל, לוי יצחק מברדיוב","dt":"תשד","b":"רב בברדיוב"},{"i":40202,"n":"פרנקל, לוי יצחק מסטרי","f":"אשר ישעיה מסטרליסק","k":"בעל רבי אורי מסטרליס","dt":"תש..","b":"בן האדמור מסטרליסק. פרסם בעתונות האידית בפולין. חיבר \"רבי אורי מסטרליסק\" פשמישל תרפז. נספה בשואה. ?? לא באוצר ??"},{"i":40203,"n":"פרנקל, לוי יצחק מצ'רנוביץ","f":"יוסף אהרן מדורוהוי","b":"בן האדמור מבוצאץ. רב בטשרנוביץ."},{"i":40204,"n":"פרנקל, מאיר יהודה","b":"רב-שנת תר\"י"},{"i":40205,"n":"פרנקל, מאיר מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":40206,"n":"פרנקל, מאיר מדאראג","f":"שמואל מדאראג","dt":"תרסט - ל ניסן","b":"מחכמי ראצפרט. בן האדמור מדאראג."},{"i":40207,"n":"פרנקל, מאיר מדמביץ","f":"שלמה זלמן מויליפולי","k":"אדמור מויליפולי בדמב","b":"אדמור מויליפולי בדמביץ-תרצח על מקום אביו - עוד בבחרותו. נספה בשואה."},{"i":40208,"n":"פרנקל, מאיר מויליפולי","k":"אדמור מויליפולי","dt":"תשג","b":"אדמו\"ר בווילפולה"},{"i":40209,"n":"פרנקל, מאיר מויצנהויזן","b":"רב בוויצנהוזן-תרה."},{"i":40210,"n":"פרנקל, מאיר ממזריטש","f":"אריה ליב פרנקל","b":"רב במזריטש-תק\"מ"},{"i":40211,"n":"פרנקל, מנחם מנדל מלמברג","b":"מחכמי למברג. חתן ר בנימין מבקשביץ. בנו ר שמחה נתן מדינוב חתן ר נחמיה ויינברגר."},{"i":40212,"n":"פרנקל, מנחם מרומן","bt":"תרע","bp":"צשינוב","dt":"תשלג","b":"בעל תואר ד\"ר מוינה. רב ברומן-תרצה, ניצל מהשואה, עלה לארץ-תשי והתישב ברמלה."},{"i":40213,"n":"פרנקל, מנחם נפתלי צבי מדינוב","f":"שמחה נתן מדינוב","k":"העילוי האדום, מנצפ\"ך","bt":"תרנג","bp":"דינוב","dt":"תשג","b":"חתן רבו ר אברהם ישכר אביגדור מטרווה. עסקן ציוני בדינוב, כתב בעתונים בת קול והמצפה תחת שם עט. תלמיד ר שמואל שנפלד מביליץ ור אברהם ישכר אביגדור מטרווה. נספה בשואה"},{"i":40214,"n":"פרנקל, מנשה מליזנסק","f":"שלמה זלמן מידלובה","bt":"תרסג","dt":"תשכה","b":"חתן ר יחזקאל לנדא מליזנסק, רב בליזנסק על מקום חותנו. ניצל מהשואה, ועבר לעשווענה - שם פעל לשיקום היהודים. היגר לארה\"ב וכיהן כרב בניו יורק."},{"i":40215,"n":"פרנקל, מרדכי דוב","dt":"תשג","b":"רב ביאבורזנא(=יאוורדזשנע)."},{"i":40216,"n":"פרנקל, מרדכי מאדיל משוואבך","k":"בעל מנחת עני","b":"נכד ר חגי חנוך העניך מבאמבוריק והענא. רב באנשבך, שאפליך, אילר אייכין, שוואבך. חיבר \"מנחת עני\". חתן ר דבער הלוי מקמניץ בן ר יהודה בעל \"גאון צבי\" שהו\"ל \"אספקליה המאירה\", ונדפס עם ספר חתנו \"מנחת עני\"."},{"i":40217,"n":"פרנקל, מרדכי מבוטושן וחיפה","f":"יהודה אריה ליבוש","bt":"תרעה","bp":"בוטושן","dt":"תשמד - טו אד\"ב","dp":"מרסל","b":"חתן האדמור ר יעקב מושקוביץ משאץ (שושלת זלוטוב). רב בבוטושאן על מקום אביו, בוקרשט, ניצל מהשואה ואחריה פעל לשיקום חיי היהודים ואף ישב בבית הסוהר על כך. עלה לארץ והתישב בחיפה ומיסד מוסדות בוטושן בעיר. בניו: ר יהודה אריה ליבוש, ר סיני מאיר מיבניאל, ר יעקב מבוטושאן בני ברק, ר משה אהרן, ר חנוך הניך, ור שמאי."},{"i":40218,"n":"פרנקל, מרדכי מסורוקה","b":"רב בסורוקוה-תרס ור יעקב נאסטאסקין על מקומו אחריו-תרסא."},{"i":40219,"n":"פרנקל, משה אליקים בריעה","bp":"צ'כיה","b":"רב בפוטוליטש, למברג וגורש מפולין לצכיה-תרצט."},{"i":40220,"n":"פרנקל, משה הכהן מאודסה","f":"יהודה ליב","bt":"תרל","bp":"פינסק","b":"רב באודסה-תרנט על מקום אביו."},{"i":40221,"n":"פרנקל, משה יהודה ליב מאיזביצה","f":"דוד מנפלקוביץ","bt":"תרן","bp":"איזביצה","dt":"תשלה","dp":"ירושלים","b":"חתן ר שמואל פרייז מאוליאוב. רב בוינה, עבר לארה\"ב-תרצט וכיהן כרב בניו יורק, עלה לארץ-תשלג."},{"i":40222,"n":"פרנקל, משה ליב מנפלקוביץ","b":"רב בנפלקוביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":40223,"n":"פרנקל, משה מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":40224,"n":"פרנקל, משה מברסלוי","b":"חתן ר יונתן איבשיץ. מחכמי ברסלוי, נזכר ב\"כרתי ופלתי\"."},{"i":40225,"n":"פרנקל, משה מהנשוביץ","b":"רב בהנשוביץ-תקמו, שעבעש-תר\"י"},{"i":40226,"n":"פרנקל, משה מז'יבוי","f":"יהושע","dt":"תשד - יח סיון","b":"חתן ר שלום וידר מנירדהאזא בעל \"משמיע שלום\". דיין בז'יבוי לפני השואה. נספה בשואה."},{"i":40227,"n":"פרנקל, משה מזשיבא","f":"יהושע מרעטיאג","bt":"תרלט","bp":"דעש","dt":"תשד - יח סיון","b":"תלמיד השב\"ס. חתן ר שלום וידר מנירעדהאזא. נספה בשואה. חתנו - גיסו ר נפלתי הירצקא וידר דיין בנירעהאזא. ור אשר שמואל כץ רב בדזשיבא ומונטריאול."},{"i":40228,"n":"פרנקל, משה ממיקוליטשין","b":"רב במיקוליטשין-תרסט."},{"i":40229,"n":"פרנקל, משה מפעשטרזעבעט","b":"נאמן קהלת פעשטערזשעבעט, חתם-תרפט עם הרב - ר אברהם דב קריסהאבער."},{"i":40230,"n":"פרנקל, משה שלום מפרשבורג","b":"דיין בפרשבורג אצל החת\"ס. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא, ועל צוואת ר יוסף קוטנפלן-תקעד."},{"i":40231,"n":"פרנקל, משלם זלמן","f":"יוסף אהרן מדורוהוי","dt":"תרנז - כח סיון","b":"בן האדמור מבוצאץ, נפטר בחיי אביו. בנו: ר יהודה ליביש אב\"ד בוטושאן בעל \"חדושי מהרי\"ל\" - נדפס בסוף \"יד יוסף\"."},{"i":40232,"n":"פרנקל, משלם זלמן מבוקרשט","f":"משה אפרים מקאליש","b":"חתן ר אליעזר ליפא-חתנו של ר לוי יצחק מברדיטשוב. רב ביארושיב, בוקרשט-תר."},{"i":40233,"n":"פרנקל, משלם זלמן מירושיב","dt":"תרח","b":"רב בירושיב (יריטשוב), בוקרשט-תרג, יאסי-תרח. חתן ר אלעזר ליפא (חתן ר לוי יצחק מברדיטשוב)."},{"i":40234,"n":"פרנקל, משלם זלמן מצ'רנוביץ","bp":"צ'רנוביץ","dt":"תשנב","b":"ניצל מהשואה. עלה לארץ. חתן ר לוי הרלינג."},{"i":40235,"n":"פרנקל, משלם מבליגרד","b":"רב בבליגרד-תרפח."},{"i":40236,"n":"פרנקל, משלם צבי מפומרן","b":"נכד ר משה רוקח מקארוב בן השר שלום מבלז. רב בפומרן."},{"i":40237,"n":"פרנקל, נפתלי הירצקא מירושלים","b":"חתן ר ישכר דב גולדשטין. רב חוג חתם סופר בירושלים על מקום חותנו."},{"i":40238,"n":"פרנקל, נפתלי הירש מברלין","f":"יוסף","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":40239,"n":"פרנקל, נפתלי הירש מירלש מברלין","f":"בנימין מירלש","k":"נפתלי הירש ניימארק","dt":"תקב-ד - כה סיון","dp":"ברלין","b":"אביו היה מגולי וינה והגיע לברלין. דיין מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין, ואח\"כ מתומכי ר משה בן אהרן מלבוב-רבה של ברלין בזמן המחלוקת כנגדו. בניו - ר דוד-אב\"ד ברלין בעל \"קרבן העדה\", ר שלמה - הדפיס ביסניץ ספרי הרמב\"ם בהסכמת ר משה בן אהרן מלבוב - ושם מכונה אביו ר נפתלי הירש ניימארק, ר אברהם, ר אליה מברלין, ר בנימין מפירט, ר יוסף-חתן ר גרשון-אב\"ד פפד\"א. חתניו: ר פייטל בן חיים אפרים מהמבורג וברלין, ר חיים יונה תאומים, ובזיוו\"ש ר השיל-אב\"ד וילנא."},{"i":40240,"n":"פרנקל, פנחס ליב","dt":"תשד","b":"רב בוועיליטשקא"},{"i":40241,"n":"פרנקל, פנחס מרישא","f":"זאב וואלף פרנקל","b":"רב ברישא-תר\"י"},{"i":40242,"n":"פרנקל, פסח משטמנסדורף","f":"משה עלישטאבי-פרנקל","k":"בעל זבח פסח","bt":"תקעב או תקסו","bp":"באסאן","dt":"תרכד - ב אייר","b":"תלמיד החת\"ס, ור יהודה אסאד. חתן ר מענקי כץ מעיר חדש ועבר לשם. ראב\"ד בעיר חדש - אצל ר אלעזר שטרסר, רב בשטמנסדורף-תרך, בנו ר ישראל על מקומו אחריו. (לפי גרינוולד שם אביו - ישראל)."},{"i":40243,"n":"פרנקל, צבי אריה מסיגט","f":"אליעזר","k":"בעל אמרי בינה-תרנז","dt":"תרכב - כב חשון","b":"מחכמי סיגט. (לא עלה לצפת בניגוד למה שנאמר בטעות). חתנו ר יצחק אהרן שוורץ ובנו ר מרדכי שוורץ - שובי\"ם בסיגט וחברו הקדמות לספרו."},{"i":40244,"n":"פרנקל, צבי הירש הענא","f":"חגי חנוך הלוי","bt":"תכב","dt":"תק","b":"גדול בנגלה בנסתר ובמדע,רב בהיידלסברג-תס\"ד,אנסבך-תסט, סופר בהענא, רב בשוואבך-תע, נתפס בעלילה וישב 24 שנים בבית סוהר. בנו ר חנוך הניך"},{"i":40245,"n":"פרנקל, צבי הירש מטימישואר","f":"ישראל","dt":"תקנז - יז כסלו","b":"תלמיד ר יחזקאל לנדא בעל ה\"נודע ביהודה\" בפרג, והיה סמוך על שלחנו ולימד את בני רבו-תקיז. רב במורביה, רב בטימישואר-תקמא. בתו פייגלה נהרגה עק\"ה בטימישואר-תקף. ר צבי שאל את רבו ה\"נודע ביהודה\" בדבר האיסור הישן בטימישואר על הדג \"שטירל\" ורבו השיב לו להתיר - למרות המנהג הקיים לאיסור. לאחר פטירתו הפך הנושא למחלוקת בין ר אהרן חורין ור יצחק גריסהאבר - דבר שהחל מחלוקת גדולה שתרמה להקמת התנועה הניאולוגית בהונגריה."},{"i":40246,"n":"פרנקל, צבי הירש מסדילקוב","f":"דוד","k":"אדמור מפרימישלן","b":"מצאצאי הבעשט. רב בסדילקוב. חתן ר מאיר מפרימישלן. אדמור מפרימישלן על מקום חותנו, בנו ר ישראל אריה ליב על מקומו אחריו."},{"i":40247,"n":"פרנקל, קלמן אליעזר מראדזין","b":"מחכמי ראדזין ומראשי הקהלה, עלה לארץ-תרפד."},{"i":40248,"n":"פרנקל, ראובן","f":"אברהם אביש מאלפין","k":"דער רבצנס","bt":"תקץ","dt":"תרמד","dp":"צפת","b":"חסיד רופשיץ-צאנז. חתן ר שאול ממעליץ. עלה לארץ-תרמד."},{"i":40249,"n":"פרנקל, ש' מב\"ח קומאדר","k":"בעל אמרי שפר","bt":"תקעה","dt":"תרמז - טז חשון","b":"רב בדורוג"},{"i":40250,"n":"פרנקל, שלום","b":"דומ\"צ בפרשבורג-תקע\"ה"},{"i":40251,"n":"פרנקל, שלמה זל'מן יוסף מויליפו","f":"אברהם מפטשינוב","k":"אדמור מויליפולי","bt":"תקסב-ד","dt":"תריח - יג כסלו","b":"תלמיד ר מאיר מאפטא, ר נפתלי צבי מרופשיץ, ותלמיד מובהק לר שמעון מירוסלב - שסמכו להנהגה. מקורוב לגדולי האדמורים (היה במחלוקת עם הדברי חיים). רב ואדמור בויליפולי (ליד רופשיץ), בנו ר אברהם וחתנו ר יצחק צבי הירש שיף על מקומו אחריו. נטמן ליד ה\"מאור ושמש\" על פי בקשתו. מפורסם כבעל מופת."},{"i":40252,"n":"פרנקל, שלמה זלמן מויליפולי","f":"אברהם מויליפולי","k":"אדמור מויליפולי דמבי","bt":"תריח","dt":"תרצח - יט טבת","dp":"דמביץ","b":"רב ואדמור בויליפולי, ידלובה-תרנז, רב בדמביץ-תרפג. חתן ר אפרים פרנקל מסנוק. בנו - ר יהודה יצחק מתל אביב."},{"i":40253,"n":"פרנקל, שלמה זלמן מויליפולי","f":"יוסף חיים","k":"אדמור מויליפולי נ\"י","bt":"תרנח","bp":"גליציה","dt":"תשלה-ט - ד תמוז","dp":"ניו יורק","b":"האדמור מויליפולי בניו יורק. בנו ר בן ציון - רב בניו יורק."},{"i":40254,"n":"פרנקל, שלמה זלמן מיאדלובא","f":"אברהם","bt":"תרלא","b":"רב ביאדלוב(=יעדלאווא)-תרנז."},{"i":40255,"n":"פרנקל, שלמה מאה\"ו","f":"נפתלי צבי הירש מירלש","dt":"תקמט - ג סיון","dp":"אלטונא","b":"תלמיד ר יהושע פאלק בעל \"פני יהושע\" בברלין, ר ברוך כהנא רפפורט מפיורדא. גביר מחכמי המבורג. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת (למרות שהיה קרובו של היעב\"ץ). סייע לאחיו ר דוד בהדפסת ספרו \"קרבן העדה\", הו\"ל רמב\"ם ושו\"ע ביעסניץ. מבניו: ר משה מהמבורג."},{"i":40256,"n":"פרנקל, שמאי מבוטושאן","f":"יוסף אהרן מדורוהוי","b":"בן האדמור מבוצאץ. רב בבוטושאן."},{"i":40257,"n":"פרנקל, שמואל","f":"יעקב","bt":"תקף","b":"נכדו - ר יעקב בעל \"בית יעקב\" קראקא תרעג."},{"i":40258,"n":"פרנקל, שמואל מעפריעס","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":40259,"n":"פרנקל, שמואל מפאפא","b":"פרסם מאמרים ב\"כתר תורה\" - גרבה תרצח."},{"i":40260,"n":"פרנקל, שמואל קומודר חלפן מדראג","f":"שרגא פיבל מרוסקא","k":"אדמור מדאראג-אמרי שפ","r":"אב\"ד דאראג","bt":"תקעה","dt":"תרמב - טו חשון","b":"אחיינו(-בן אחיו) של ר ברוך בעל \"ברוך טעם\". חתן הגביר ר יצחק רויט מפאטשוי. תלמיד דודו ר יצחק פרנקל מקראלי, גיסו - ר זאב וולף טננבוים בעל רחובות הנהר, ר מאיר א\"ש מאונגוואר, הדברי חיים מצאנז שהכתירו כרב ואדמו\"ר בדאראג (מחמת ענותנותו סירב ללבוש בגדי אדמו\"ר), וחתנו ר זאב וולף ציטרון על מקומו אחריו-תרמג. חיבר \"אמרי שפר\". בנו ר מאיר מרצפרט. חתנו גם ר יעקב צבי ויסמן מסובוסלו. על שמו ביהכ\"נ \"אמרי שפר\" בירושלים. חתם שמו פרנקל מב\"ח (מבית חלפן). חברו של מוהר\"ם ברודא.","bk":[["אמרי שפר – עה\"ת",""]]},{"i":40261,"n":"פרנקל, שמחה מסקאווין","dt":"תשג","b":"רב בסקאווין"},{"i":40262,"n":"פרנקל, שרגא פיבוש מגינז רוסקא","f":"אורי ליפמן מבית חלפן","b":"רב בגינז רוסקא-תר\"ך"},{"i":40263,"n":"פרנקל-הלבן, יצחק מטיקטין","f":"יהושע יחזקאל פרנקל","b":"רב בטיקטין-תק\"ס"},{"i":40264,"n":"פרנקל-מיכלשטט, אברהם מבודפשט","f":"צבי מיכלשטט פרנקל","bt":"תרך","bp":"דברצין","dt":"תרצז - כח תשרי","dp":"בודפשט","b":"תלמיד השב\"ס, ור ישראל יצחק אהרן לנדסברג מגרוסורדין, ור משה צבי הררש פוקס מגרוסורדין. חתן ר עזריאל טויבר מצעלים. רב בבודפשט, ממיסדי חברת ש\"ס שם-תרנג, נשיא הלשכה האורטודוכסית-תרסה, חתנו ר שמואל זנויל כהנא-פרנקל על מקומו אחריו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":40265,"n":"פרנקל-תאומים, אברהם","b":"נכד הדברי חיים. אביו היה אב\"ד בוכניה."},{"i":40266,"n":"פרנקל-תאומים, אברהם משדליץ","f":"יצחק מאיר מירסלוב","b":"אב\"ד שדליץ. הסכים על \"תשואות חן\" דובנא תקנז."},{"i":40267,"n":"פרנקל-תאומים, אהרן","f":"יצחק מאיר מזבורוב","b":"אביו בן הקיקיון דיונה."},{"i":40268,"n":"פרנקל-תאומים, אהרן זאב","f":"אביגדור מזבורוב","bt":"תר","bp":"סקלט","dt":"תרעח","b":"חתן ר יוסף שמען אלטברג מטרמבובלה, היגר לארה\"ב-תרנב. בנו ר מנחם מאניש בעל \"כור הזהב\"."},{"i":40269,"n":"פרנקל-תאומים, אהרן מזבורוב","f":"אברהם מזבורוב","dt":"תקפה"},{"i":40270,"n":"פרנקל-תאומים, אהרן מטרנופול","b":"נכד הקיקיון דיונה. רב בטרנופול-תרח."},{"i":40271,"n":"פרנקל-תאומים, אליהו מפשוורסק","f":"יהושע השל מליביטשוב","bt":"תרלז","bp":"ליביטשוב","dt":"תשג","b":"חתן הגביר ר אברהם אינגבר. רב בכפרים פשענדזל ויאראטשין (ליד רודניק). רב בפשוורסק-תרפד. מחשובי הרבנים בגליציה. נספה בשואה."},{"i":40272,"n":"פרנקל-תאומים, אלימלך מיברוב","f":"יהושע השל מליביטשוב","k":"בעל הפלאת נדרים","bt":"תרמה","bp":"ליביטשוב","dt":"תשג","b":"חסיד שיניבה וצשינוב. חתן דוד מנחם באבד בעל \"חבצלת השרון\" מיברוב. רב ביברוב על מקום חותנו. נספה בשואה. חיבר \"הפלאת נדרים\" בילגוריא תרצו."},{"i":40273,"n":"פרנקל-תאומים, אלימלך מפודהייץ","f":"ישראל אריה ליב מפרמי","k":"אדמור מפרימישלן","bt":"תרם","dt":"תרעה - כא אב","b":"בן האדמור מפרימישלן. חתן ר נחום מנרול - נכד האדמור ר אשר ישעיה מרופשיץ. אדמור מפרימישלן בפודהייץ. בנו ר אשר ישעיה - אדמור מלמברג."},{"i":40274,"n":"פרנקל-תאומים, אליעזר","f":"שאול פייבל פרנקל","b":"בנו - ר אורי ליפמן מב\"ח."},{"i":40275,"n":"פרנקל-תאומים, אריה ליבוש","f":"שאול פייבל תאומים","b":"רב בזאוויכוואסט"},{"i":40276,"n":"פרנקל-תאומים, אשר ישעיה מלבוב","f":"אלימלך מפודהייץ","k":"אדמור מלמברג","b":"ממשפחת אדמורי פרמישלן."},{"i":40277,"n":"פרנקל-תאומים, אשר ישעיה מסטרלי","f":"ישראל אריה ליב מפרמי","k":"אדמור מסטרליסק","dt":"תש..","dp":"סטרי","b":"בן האדמור מפרמישלן. חתן ר לוי יצחק מסטרליסק. אדמור בסטרליסק על מקום חותנו, עבר לסטרי-תרעד. בנו ר ישראל אריה. נספה בשואה."},{"i":40278,"n":"פרנקל-תאומים, ברוך מוישניצה","f":"חזקיה יחזקאל יהושע","k":"בעל ברוך טעם","r":"אב\"ד ור\"מ בלייפניק, וחמיו של הדברי חיים מצאנז","bt":"תקך","dt":"תקפח - ז תמוז","b":"תלמיד ר משלם איגרא בטיסמניץ. חתן ר יהודה פרנס מוישניצה ובזיוו\"ש חתן רי\"ל הלוי מליסא, ובזיוו\"ש חתן ר צבי יהושע הלוי הורביץ מטריביטש. רב בוישניצה (מתנגד בעיר של חסידים - סבל ממחלוקת). והקים שם ישיבה. רב בלייפניק-תקס והקים שם ישיבה. מגדולי חכמי דורו. חיבר \"עטרת חכמים\" יוזפוב תרכו, \"ברוך טעם\" ועוד. מאמר ממנו ב\"עמק הלכה\" - באטארקס תרפא. בנו - ר יהושע השל, חתניו - ר חיים הלברשטם, ר מאיר יחיאל קמינר, ר מנחם מאניש בן נתן נטע יונה תאומים מברודי.","bk":[["ברוך שאמר","מפרשי ש\"ס - אחרונים"],["חדושי ברוך טעם","מפרשי ש\"ס - אחרונים"],["ברוך טעם [הקדמות]","מערכות"],["ברוך טעם [שער א]","מערכות"],["ברוך טעם [שער ב]","מערכות"],["ברוך טעם [שער ג]","מערכות"],["ברוך טעם [שער ד]","מערכות"],["ברוך טעם [שער ה]","מערכות"],["ברוך טעם [שער ו]","מערכות"],["ברוך טעם [שאלה ותשובה]","מערכות"],["ברוך טעם [סוגיא דהמפקיד חמץ]","מערכות"],["עטרת חכמים","שו\"ת - אחרונים"],["אמרי ברוך","מפרשי שו\"ע"],["ברוך טעם",""],["גליוני הפלתי",""],["מרגניתא דר\"ב",""],["עטרת חכמים חלק א",""],["אמרי ברוך - ד' חלק שו\"ע",""],["אמרי ברוך - ד' חלק שו\"ע , ברוך טעם , ברוך שאמר, זר השלחן , משנת רב - משניות , עטרת חכמים - שו\"ת וחידושים",""],["זר השלחן",""],["משנת רב - משניות",""],["עטרת חכמים - שו\"ת וחידושים",""]]},{"i":40279,"n":"פרנקל-תאומים, ברוך מסוקוליבקא","f":"ישראל אריה ליב מפרמי","k":"אדמור מסוקוליבקא","b":"ממשפחת אדמורי פרמישלן. חתן ר יעקב הלפרין מסוקוליבקא. אדמור בסוקוליבקא על מקום חותנו, עבר ללמברג."},{"i":40280,"n":"פרנקל-תאומים, דב בריש מצשינוב","f":"יהושע השל מקומרנא","bt":"תקפה","dt":"תרם","b":"חתן הנגיד ר יונה מירוסלב. רב בקומרנא-תריב על מקום אביו, קניהניטש-תריח, צשינוב-תרכג, בנו ר פנחס על מקומו בצשינוב."},{"i":40281,"n":"פרנקל-תאומים, חזקיה יחזקאל פי","f":"יונה-קיקיון דיונה","k":"בעל פנים מסבירות","dt":"תצב","b":"יש אומרים ששמו היה ר יהושע פיבל. חתן ר ליב דער הויכער מקראקא (הגבוה) בעל \"תקוני תשובה\". רב בצילץ, פרמישלא-תסג (ועזב בגלל מחלוקת ועל מקומו ר שמואל מסלונים - ועל כך בספרו תקע שופר), ברסלוי-תעח. חיבר \"פנים מסבירות\" זולצבך תעה, \"תקע שופר\" ברעסלא תעט. בניו - ר אריה ליב מקרשוב, ר חיים יונה מברסלוי, ר יוסף יאסקי מקראקא. חתנו - ר יואל בן יצחק איזיק הלפרין הגדול מאוסטרהא. גיסו - בעל \"בית שמואל\"."},{"i":40282,"n":"פרנקל-תאומים, חיים יונה מפרמיש","f":"יחזקאל פיבל-פנים מסב","k":"בעל עלה דיונה","bt":"תנח","dt":"תפח","b":"תלמיד ר יחיאל מיכל בעל \"נזר הקדש\" בגלוגא. רב בפרמישלא, צילץ, ברעסלוי-תפב על מקום ר שמלקא כץ בן ה\"סמיכת חכמים\". חתן ר דוד הופנהים (אשתו שרה - היתה מלומדת בתלמוד וכתבה מגילת אסתר כשרה), ובזיוו\"ש חתן ר נפתלי הירש מירלש פרנקל. בנו ר יצחק יוסף, חתנו ר אריה ליב מהנובר, ר צבי הירש מזבאריז.","bk":[["סדר משנה","מפרשי רמב\"ם"],["קונטרס ר' חיים יונה [דינא דגרמי]",""]]},{"i":40283,"n":"פרנקל-תאומים, י' מאיר מפיעטרקו","b":"רב בפיעטרקוב-ת\"ר"},{"i":40284,"n":"פרנקל-תאומים, י' שרגא מויליצקה","dt":"תשג","b":"רב בוויליצקה"},{"i":40285,"n":"פרנקל-תאומים, יהודה אריה ליב","f":"יעקב מברסלא","k":"בעל עדות נאמנה","b":"מצאצאי הקיקיון דיונה. מחכמי קראקא. חיבר \"עדות נאמנה\" דעסוי תקעג, ועוד."},{"i":40286,"n":"פרנקל-תאומים, יהודה אריה ליב","f":"יצחק מאיר בן אברהם","bt":"תפ","dt":"תקנח","b":"נכד ר משה חריף לבוב מפרשבורג. חתן ר עזריאל מיריטשוב. רב ביריטשוב-תקכט על מקום חותנו, צורטקוב-תקלד. בנו - ר יוסף תאומים מבורשטין."},{"i":40287,"n":"פרנקל-תאומים, יהודה ליב","f":"יהושע יחזקאל פייבל","b":"רב במזוויכוואסט-תק\"ע"},{"i":40288,"n":"פרנקל-תאומים, יהונתן שמעון","f":"יעקב מקלסני","k":"בעל חדושי תורה","bt":"1770","bp":"קלסני","dt":"ה'תר","b":"חתן ר ישראל מוישניצה. התגורר בוישניצה ולמברג. עלה לארץ-תקצח וחזר להעלות את משפחתו. חיבר \"חדושי תורה\" למברג תקסד, ועוד.","bk":[["דברי תורה","מפרשי רמב\"ם"],["דברי תורה – ש\"ס ורמב\"ם",""],["חידושי תורה – בראשית שמות",""],["מעיני ישועות – הגדה של פסח",""],["עץ פרי קודש – קיצור דינים",""]]},{"i":40289,"n":"פרנקל-תאומים, יהושע השל","f":"אליהו מפשוורסק","k":"בעל נחלת אבי","b":"חתן הגביר ר יצחק ליב ארנברג מקעמעטש. רב בגורליץ. חסיד בלז. נספה בשואה. חיבר \"נחלת אבי\" בילגוריא תרצז. ?? לא באוצר ??"},{"i":40290,"n":"פרנקל-תאומים, יהושע השל","f":"פנחס מצשינוב","dt":"תרנד","b":"נכד(-אבי אמו) ר יחזקאל הלברשטם משינוואה. רב בסאפוקב. חתן האדמור ר שמואל חיים הורביץ-שטרנפלד מחנטשין (ולאחר פטירתו נישאה אלמנתו לר אלימלך מגרודזיסק). חתנו - ר אליהו הברלנד. נזכר בספר זקנו \"דברי יחזקאל\"."},{"i":40291,"n":"פרנקל-תאומים, יהושע השל מאולנו","b":"רב באולנוב. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":40292,"n":"פרנקל-תאומים, יהושע השל מנריוב","f":"יעקב יצחק מנריוב","bt":"תר","dt":"תרנד - אד\"ב","b":"רב בנריוב על מקום אביו, ליבטשוב-תרמו. חתן ר אלעזר הורביץ ממריאמפול."},{"i":40293,"n":"פרנקל-תאומים, יהושע השל מקומרנ","f":"ברוך בעל ברוך טעם","bt":"תקם","dt":"תרג - ד תמוז","b":"גיסו של הדברי חיים. מגדולי חסידי החוזה מלובלין (בניגוד לרצון אביו המתנגד) - החוזה רצה למנותו כיורשו בהנהגת חסידות גליציה ומשסירב מסרה לשר שלום מבלז. בהוראת רבו התקרב לר עזיראל \"ראש הברזל\" מלובלין. רב בקומרנא (יום אחד - כדי לא לשבור את מסורת הרבנות במשפחתו), רב ברידיק (שבועיים - מאותה הסיבה). עסק במסחר ודחה הצעות שונות לרבנות. התנהג באדמורות והיה מקורב לשר שלום מבלז שחיכה לו כדי לחנוך את בית מדרשו. בניו: ר דב בעריש מציעשינוב, ר יעקב מפשוורסק, ר יחזקאל שרגא מקלאסנא."},{"i":40294,"n":"פרנקל-תאומים, יהושע פיבל","f":"יונה-קיקיון דיונה","b":"ראה גם לפי חזקיה פיבל"},{"i":40295,"n":"פרנקל-תאומים, יהושע פיבל מפודג","f":"יעקב מפודגורזע","bt":"תרנב","dt":"תשב-ג","dp":"טורקסטן","b":"רב בפודגורזע-תרפט על מקום אביו. חתן דודו ר שמחה מסקאווין. גלה לסיביר בזמן השואה ושם נפטר."},{"i":40296,"n":"פרנקל-תאומים, יונה ממיץ","f":"ישעיה מפרג","k":"בעל קיקיון דיונה","bt":"שנו","bp":"פרג או ליטא","dt":"תכט - טז ניסן","dp":"מיץ","b":"הראשון שנקרא בשם פרנקל בנוסף לתאומים. תלמיד דודו ר פנחס הורביץ מקראקא-גיסו של הרמ\"א. רב בנמירוב, לובמלא, בלז, הורדנא-תד על מקום ר יצחק איזיק בן אברהם, פינסק-תטו. ברח לוינה בפרעות תח. רב במיץ. מתלמידיו ר יצחק מוילנא ופוזנא(רבו של בעל מגן אברהם), ור ניסן בעל \"בית יהודה\" וחדושי מהריב\"ן. חיבר \"קיקיון דיונה\" אמשטרדם תל, ועוד. בזיוו\"ש חתן ר מאיר בן שאול קצנלנבוגן-ואהל(=וייל) או של בנו - ר יהודה מבריסק. בניו - ר ישראל שהו\"ל את ספרו \"קיקיון דיונה\", ר יעקב שולהויף (אימץ שם חותנו), ר יצחק מאיר, ר יהושע פיבל. חתנו - ר מרדכי בן ר השל מקראקא, ר אביגדור קרא מגלוגא."},{"i":40297,"n":"פרנקל-תאומים, יוסף יוסקא","f":"יחזקאל פיבל-פנים מסב","b":"בנו של ר חיים יונה מפרמישלא או של אביו ר חזקיה יחזקאל. זקנו של הפרי מגדים (בהקדמת הפמ\"ג כותב שהיה חתן ר ישעיה אביו הקיקיון!)."},{"i":40298,"n":"פרנקל-תאומים, יחזקאל שרגא פיב'","f":"יהושע השל מקומרנא","k":"בעל דברי יחזקאל","bt":"תקף","dt":"תרמה","b":"רב בקלסני ויליצקה - בהוראת הדברי חיים, חתנו ר שמואל שמלקא עזריאל על מקומו אחריו. חתן ר שמואל רוזנר מברדיוב. חיבר \"דברי יחזקאל\" פאדגורזע תרסט."},{"i":40299,"n":"פרנקל-תאומים, יעקב יצחק מנריוב","f":"יהושע השל מקומרנא","bt":"תקפג","dt":"תרנג - כז תרנג","b":"רב בנריוב-תרי, מיעכוב, שקונז(קשונז)-תרכט, פשוורסק, צשינוב-תרלג. חתן ר יהודה הולנדר מצאנז. בנו ר יהושע השל על מקומו בנריוב אחריו."},{"i":40300,"n":"פרנקל-תאומים, יעקב מפודגורזע","f":"שמעון אלתר מפודגורזע","bt":"תרכז","dt":"תרפט","b":"רב בקולשיץ-תרן, פודגורזע-תרסב על מקום אביו, בנו ר יהושע פיבל על מקומו אחריו. חתן ר משה משיניבה."},{"i":40301,"n":"פרנקל-תאומים, יעקב משלם מהומין","b":"גביר תלמיד חכם מהומין. בנו ר יצחק קלמן-חתן הגביר ר אפרים זלמן זוסמן מאוסטרהא בן הגביר ר אבא צבי מאוסטרהא."},{"i":40302,"n":"פרנקל-תאומים, יצחק יוסף מקראקא","f":"חיים יונה מפרמישלא","bt":"תפא","dt":"תקנד - טז חשון","b":"תלמיד ר צבי הירש חריף מהלברשטט. רב בסלוצק-תקא, קראקא-תקג על מקום ר דוד שמואל (ועזב בגלל מחלוקת) ור יצחק לנדא על מקומו אחריו, התישב בברסלא והתעשר מאוד, כיהן כרב ללא שכר על מקום ר ברוך ויזל והתפרנס ממסחר באתרוגים, על כסאו אחריו ר ישעיה פיק. חתן ר שמואל מסלוצק או לברטוב ונזכר בשבחי הבעשט עם אחיו ר גדליה כעשירים גדולים. חתנו - ר שאול בעל \"כסא דהרסנא\"."},{"i":40303,"n":"פרנקל-תאומים, יצחק מאיר","f":"אברהם בן יצחק מאיר","b":"חתן ר משה חריף. בנו - ר אריה ליב מצורטקוב. חתנו - ר יהושע פיבל מטרניגרד וזולקוא."},{"i":40304,"n":"פרנקל-תאומים, יצחק מאיר מוינה","f":"יונה-קיקיון דיונה","k":"בעת כתנות אור","dt":"תסב - בערך","b":"בקי בשפות וברפואה חתן הגביר ר משה מירלש מוינה ועבר לשם, ובזיוו\"ש חתן גיסו ר אברהם ב\"ר מירלש פו\"מ טרעביטש. גיסו גם ר יהודה ליב קרוכמל בן הצמח צדק מניקלשבורג. ישב בהמבורג, רופא בחצר המלך בוינה וגורש מוינה עם כל היהודים-תל ועבר להיות רב בזולקוא, נתמנה להיות רופא המלך ין סוביסקי-תמג יחד עם ר שמחה פורטיג. רב בסלוצק-תנא, פינסק-תנד על מקום ר יואל הלפרין שעבר לאוסטרהא, פרמישלא על מקום ר יוסף סגל חריף אבל נפטר לפני שהגיע. חיבר \" כתנות אור\" על \"עין יעקב\" הכולל את הספרים \"בית יהודה\" לר יהודה די מדינא וחדושי ר יאשיהו פינטו \"מאור עינים\" - אמשטרדם תמד. הסכים על \"זבחי טוביה\", \"אל חי ואמת\" המבורג תסב. לפי פין היה חתן ר אביגדור קרא בן שניאור והיה גיסו של ר יעקב בן אפרים נפתלי."},{"i":40305,"n":"פרנקל-תאומים, יצחק קלמן","f":"יעקב משלם מהומין","b":"מחכמי אוסטרהא-תרס. חתן ר אפרים זלמן זוסמן מאוסטרהא."},{"i":40306,"n":"פרנקל-תאומים, ישראל אריה ליב","f":"צבי הירש מפרמישלן","k":"אדמור מפרמישלן","bt":"תקץ","dt":"תרנא - יג ניסן","b":"נכד ר מאיר מפרמישלן - הנכד, וגדל אצלו. חתן ר אלימלך מסוקולוב (רופשיץ). אדמור בפרמישלן על מקום אביו. (באוצר הרבנים תאריך פטירתו - יג כסלו)."},{"i":40307,"n":"פרנקל-תאומים, ישראל אריה ליב","f":"ברוך מסוקוליבקא","k":"אדמור מלמברג סוקוליב","dt":"תשכב - ט אייר","b":"ממשפחת אדמורי פרמישלן."},{"i":40308,"n":"פרנקל-תאומים, ישראל ממיץ","f":"יונה-קיקיון דיונה","dt":"תסה","b":"פו\"מ בגלוגוי(=גלוגא)-תמ, רב במיץ. הוציא לאור את ספר אביו \"קיקיון דיונה\" עם הקדמה ממנו."},{"i":40309,"n":"פרנקל-תאומים, מבוקובסק","f":"דב בריש מצשינוב","bt":"תר","dt":"תרלט","b":"חתן רי\"ש משינאווא. רב בבוקובסק, צשינוב-תרכט על מקום אביו. סידר לדפוס עם אביו את ספר זקנו ר ברוך - \"עטרת חכמים\"."},{"i":40310,"n":"פרנקל-תאומים, מנחם אליעזר","b":"אין פרטים. (כנראה בן למשפחת ר יהושע ור פנחס פרנקל-תאומים)."},{"i":40311,"n":"פרנקל-תאומים, מנחם מאניש","f":"אהרן זאב מסקלט","k":"בעל כור הזהב","bt":"תרכג","bp":"סקלט","b":"חתן ר נחום יהודה הכהן עלנברג. היגר לארה\"ב. חיבר \"כור הזהב\" ניו יורק תרפח."},{"i":40312,"n":"פרנקל-תאומים, מנחם מרדכי","f":"אלתר ישכר","k":"בעל דרוש וחדוש","bt":"תרמב","bp":"ירושלים","dt":"תשלב","dp":"ירושלים","b":"חתן ר אברהם דוד הלוי. עבר לארה\"ב וכיהן כרב בישיבת ר חיים ברלין-תרפא. חזר לירושלים. ממנהיגי אגודת ישראל. רב בפילדלפיה. חיבר גם \"באר האבות\" ועוד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז.","bk":[["באר האבות [מלוא הבאר] - אבות",""],["דרוש וחדוש - על התורה",""],["באר האבות [מלוא הבאר] - אבות , דרוש וחדוש - על התורה",""]]},{"i":40313,"n":"פרנקל-תאומים, מרדכי דב","f":"שמחה מסקאווין","dt":"תש..","b":"רב ביבורוזנה-תרצז. חתן האדמור מקוזניץ-לובלין. נספה בשואה."},{"i":40314,"n":"פרנקל-תאומים, פנחס אריה ליב","f":"שמואל שמלקא מקלסני","bt":"תרנח","dt":"תשא","b":"רב בקלסני-ויליצקה על מקום אביו. . חתן ר חיים פרנס מישליסק (ישניצה). נספה על קדוש השם בשואה."},{"i":40315,"n":"פרנקל-תאומים, פנחס מצשינוב","f":"דוב בער מצשינוב","b":"חתן האמדור ר יחזקאל שרגא הלברשטם משינאווא, והיה מקורב לחותנו זקנו בעל \"דברי חיים\" מצאנז ונזכר בספרו. רב בוקאוסק, צשינוב-תרכט על מקום אביו. הו\"ל \"עטרת חכמים\" לזקנו בעל \"ברוך טעם\". בנו - ר יהושע השל.- נפטר צעיר."},{"i":40316,"n":"פרנקל-תאומים, צבי הירש","f":"דוד","k":"אדמור מפרמישלן","dt":"תרטז - ב טבת","b":"נכד ר משה חיים אפרים בעל \"דגל מחנה אפרים\". חתן ר מאיר מפרמישלן - הנכד, ואדמור בפרמישלן על מקומו אחריו. נפטר צעיר. בנו ר בנימין - חתן ר יחיאל מיכל מהאליטש (בערזאן)."},{"i":40317,"n":"פרנקל-תאומים, שמואל","b":"מעורכי \"דגל התורה\" - אויבר-וישווה תרפח."},{"i":40318,"n":"פרנקל-תאומים, שמואל עזריאל","f":"פנחס תאומים פרנקל","bt":"תרכב","b":"רב בוויליצקה(=ויעליטשקא)-תרע."},{"i":40319,"n":"פרנקל-תאומים, שמואל שמלקא","f":"פנחס מבוקובסק","bt":"תרכב","dt":"תרצד","b":"חתן דודו ר יחזקאל שרגא מקלסני-ויליצקה. רב בקלסני-וילצקה על מקום חותנו. בנו ר פנחס אריה ליב על מקומו אחריו."},{"i":40320,"n":"פרנקל-תאומים, שמחה מסקאווין","f":"שמעון אלתר מפודגורזע","bt":"תרל","dt":"תשג","b":"רב בסקאווין (ליד פודגורזע), פודגורזע-תרסט. חתן דודו ר נפתלי הלברשטט מקשנוב. בנו ר שמעון אלתר על מקומו אחריו בסקאווין. מחותן עם האדמורים מזלושיץ, ויליפולי, קרלין. נספה בשואה."},{"i":40321,"n":"פרנקל-תאומים, שמעון אלתר","f":"יחזקאל שרגא מקלסני","bt":"תרי","dt":"תרסב - א פסח","b":"נכד הדברי חיים. חתן ר דוד הלברשטט מקשנוב. רב בפוגדורזע-תרכו בהשתדלות זקנו הדברי חיים. בנו ר יעקב על מקומו אחריו."},{"i":40322,"n":"פרנקל-תאומים, שמעון אלתר","f":"שמחה מסקאווין","bt":"תרסב","dt":"תשה","b":"רב בסקאווין על מקום אביו. חתן ר אהרן אלימלך שניאור זלמן טברסקי מקרוסנו. נספה בשואה."},{"i":40323,"n":"פרנקל-תאומים, שמעון יחזקאל","f":"יהושע פיבל מפודגורזע","bt":"תרעד","bp":"קרלסבד","b":"רב בפודגורזע, קראקא. ניצל מהשואה, עלה לארץ-תשי וכיהן כרב בקרית אונו."},{"i":40324,"n":"פרנקלין, אברהם מאיר מוילנא","k":"בעל חקר דעת","b":"רב בוילנא, באפלו-ארה\"ב."},{"i":40325,"n":"פרנקנטל, יצחק אריה","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":40326,"n":"פרנקנטל-שוחט, משה מירושלים","bt":"תריט","dt":"תשב","b":"תלמיד מהרי\"ל דיסקין. חתן ר ישעיה אורנשטין מירושלים. מחכמי ירושלים, וראש השו\"בים - בגיל 40 פרש ועסק רק בתורה. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג."},{"i":40327,"n":"פרנקנשטין, יצחק אורי מירושלים","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":40328,"n":"פרנקפורטר, אברהם יהודה מפעלשא","f":"משה יוסף מקעזמארק","bt":"תרטז","dt":"תרפה - טו אדר","dp":"אלשא-צעצע","b":"תלמיד השב\"ס, מחכמי פעלשא-צעצע. אחיו ר יעקב - אדמור בקאשוי."},{"i":40329,"n":"פרנקפורטר, אהרן אלימלך מטיסא","b":"אב\"ד טיסא-באגדאן."},{"i":40330,"n":"פרנקפורטר, אורי מאוברדורף","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":40331,"n":"פרנקפורטר, ברוך מפפד\"מ","b":"בנו - ר יעקב קלצקי מוילקוביסק ווילנא, נכדו - ר ברוך מרדכי ליפשיץ בעל \"ברית יעקב\"."},{"i":40332,"n":"פרנקפורטר, דוד מהעלישויא","f":"יוסף ליב","dt":"תרעג - כט תשר","b":"תלמיד השב\"ס. דומ\"צ בסאבאטישט-תרלה, העלישויא-תרנא."},{"i":40333,"n":"פרנקפורטר, יהודה אריה ליב מפפד","f":"יוסף שמואל מקרקא","dt":"תצז - יט טבת","b":"מחכמי פפד\"מ-אביו היה רבה של פפד\"מ. חתן ר שמואל שאטין הכהן. רב במטרסדורף-תץ. ערך את הגהות אביו לש\"ס והוסיף הגהות משלו, ובנו הדפיס את הש\"ס-תפא עם ההגהות (היה מחלוקת בינו לבין שותפו ר משה קן-חתנו של ר שמשון ורטהיימר - והיה צו מהקיסר שאסר על הפצת הש\"ס במשך שנים רבות). חיבר חדושים ושו\"ת - בכת\"י."},{"i":40334,"n":"פרנקפורטר, יהודה מפרשבורג","f":"יעקב קופל","bt":"תקסה","dt":"תרן - כג חשון","dp":"פרשבורג","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשבורג. רב בפרשבורג. חדושי החת\"ס שנמסרו ממנו ב\"תורת משה\"."},{"i":40335,"n":"פרנקפורטר, יהושע","f":"יעקב מקאשוי","dt":"תשד","b":"רב בקאשוי"},{"i":40336,"n":"פרנקפורטר, יוסף דוד מפאריס","b":"רב קהלת \"עדת יראים\" בפאריס-תשלה."},{"i":40337,"n":"פרנקפורטר, יוסף ליב מהעדיעס","f":"נתן נטע מהעדיעס","b":"תלמיד החת\"ס והכת\"ס. גיסו של ר הלל ליכטנשטין מקולומיאה."},{"i":40338,"n":"פרנקפורטר, יוסף מטאב","f":"נתן בשאלגא-טאריאן","b":"רב בטאב."},{"i":40339,"n":"פרנקפורטר, יעקב מקאשוי","f":"משה יוסף מקעזמארק","k":"אדמור מקאשוי","dt":"תשג - כב חשון","dp":"קאשוי","b":"תלמיד השב\"ס, ור אברהם גרינבורג מקעזמארק, ור משה פולק מבאניהאד. חתן ר ישראל חיים ברוין-העברי מבודפשט. אדמור בקאשוי-תרמה. בניו - ר יהושע רב בקאשוי, ר ישראל חיים - אדמור בקאשוי, ר אהרן אלימלך רב בטיסא-באגדאן."},{"i":40340,"n":"פרנקפורטר, יעקב מקראקא","f":"ר\"י","dt":"תריד - כ תשרי","b":"דיין בקראקא."},{"i":40341,"n":"פרנקפורטר, ישראל חיים מקאשוי","f":"יעקב מקאשוי","k":"אדמור מקאשוי","b":"אדמור בקאשוי על מקום אביו."},{"i":40342,"n":"פרנקפורטר, ישראל מלמברג","f":"דוד לבין","k":"בעל באר ישראל","bt":"תרלד","bp":"למברג","dt":"תשג - כא אדר","b":"נכד ה\"תבואות שור\". ממיסדי \"המזרחי\" בלמברג עם ר ראובן מרגליות. עבר לפריז-תרפז וכיהן כרב. חתן ר אורי אופנר מקומרנא. נספה בשואה. חיבר \"באר ישראל\" בילגוריא תרצז, ועוד."},{"i":40343,"n":"פרנקפורטר, מנחם מנדל מפרשבורג","f":"נתן נטע מהעדיעס","k":"הו\"ל שירת משה","bt":"תקעה","dt":"תרנד - בערך","b":"תלמיד החת\"ס, ור יהודה אסאד מסעדאוהל, ור שלמה זלמן בניהאד מפרשבורג. שימש בקדש אצל החת\"ס. חתן ר שלמה ורטהימר מפעזזינג. מחכמי פרשבורג, וינה-תרכב. הו\"ל \"שירת משה\" לחת\"ס, \"שירי מצות\" לר\"י איבשיץ, ו\"ברכת המים\"."},{"i":40344,"n":"פרנקפורטר, משה","dt":"תקנח - ד ניסן","b":"חתן ר חנוך הניך משנייטוך."},{"i":40345,"n":"פרנקפורטר, משה יוסף מקעזמארק","dp":"פאני","b":"מחכמי קעזמארק. בניו - ר אברהם יהודה מפעלשא-צעצע, ר יעקב האדמור מקאשוי, ור נתן משאלגא-טאריאן."},{"i":40346,"n":"פרנקפורטר, משה מאמשטרדם","f":"שמעון","k":"בעל באר היטיב","bt":"תלב","dt":"תקכב","b":"דיין באמשטרדם, עבר לפפד\"מ. חיבר גם פירוש למכילתא בשם \"זה ינחמנו\", \"נפש יהודה\" והוא קיצור \"מנורת המאור\", ועוד. מחותניו: ר זלמן אפטרודה, ר משה במברג."},{"i":40347,"n":"פרנקפורטר, משה מוינקוועצי","f":"דוד מהעלישוי","bt":"תרלה","bp":"סאבאטישט","dt":"תשא","b":"תלמיד השב\"ס. חתן ר מרדכי יוסף פוגל מקעמפען. רב בארוואר-תרסט, וינוועצי ובאנאי לוקה-תרעד. מהדיר פירוש המשנה לרמבם."},{"i":40348,"n":"פרנקפורטר, נתן משאלגא","f":"משה יוסף מפאני","bt":"תרכז","bp":"קעזמארק","dt":"תשד - כד סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה פולק מבאניהאד. חתן ר משה גולדשטין מקאשוי. רב בשאלגא-טאריאן. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. נספה בשואה. בנו ר יוסף מטאב."},{"i":40349,"n":"פרנקפורטר, נתן נטע מהעדיעס","f":"שמואל פרנקפורטר","b":"רב בהעדיעס-ת\"ר"},{"i":40350,"n":"פרנקפורטר, נתן נטע ממטרסדורף","f":"אריה ליב פרנקפורטר","dt":"תקמב - א תמוז","b":"רב במטרסדורף"},{"i":40351,"n":"פרנקפורטר, עקיבא - הזקן","f":"אליעזר","b":"מחכמי אשכנז, ומשורר. נכדו - ר עקיבא הדרשן מפפד\"מ - והיו שהחליפו ביניהם."},{"i":40352,"n":"פרנקפורטר, עקיבא מפפד\"מ","f":"יעקב","bp":"נויס","dt":"שנז - יד אייר","dp":"פפד\"מ","b":"נכד ר עקיבא פרנקפורטר בן אליעזר. חתן ר שמעון גינצבורג (י\"א מפוזנא וי\"א שהיה אחר והיה מפפד\"מ או שהיה מקודם מפפד\"מ ועבר לפוזנא). שו\"ב בפפד\"מ-שי על מקום דודו, דרשן ודיין בפפד\"מ-שכד. חיבר תפילות ופיוטים וחלקים יצאו לאור ע\"י תלמידו ר אליהו בעל שם לואנץ. היה עשיר גדול בזכות חותנו וארגן הקמת חברות צדקה וחסד. חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ. נספד ע\"י המהר\"ל מפרג. מתלמידיו: ר יעקב בן יצחק מסנדומיר-פולין בעל \"פירוש המסורה\"."},{"i":40353,"n":"פרנקפורטר, שלמה מקניגסברג","f":"דוד מסאבטישט","bt":"תרלו","bp":"סאבאטישט","b":"תלמיד השב\"ס, ור יהודה גרינולד מסטמר. רב בקעלין-תרסח, לאבזיטץ-תרעג, קהילת \"אהבת רעים\" בברלין-תרפז, קניגסברג-תרצב. מהדיר פירוש המשנה לרמב\"ם. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד."},{"i":40354,"n":"פרנקפורטר, שמואל מהעדיעס","f":"נתן נטע מהעדיעס","b":"נכד ר אריה יהודה ליב פרנקפורטר ממטרסדורף. תלמיד החת\"ס. חיבר קונטרס בכת\"י ובו תורת רבו."},{"i":40355,"n":"פרנקפורטר, שמואל ממטרסדורף","f":"נתן נטע פרנקפורטר","b":"רב במטרסדורף-תקמ\"ב"},{"i":40356,"n":"פרנקפורטר, שמעון","b":"מגדולי חכמי פרנקפורט-ת\"מ"},{"i":40357,"n":"פרנקפורטר, שמעון דוקטר מקראקא","f":"זלמן","b":"רופא בקראקא. חתם-תקנד שמו 'פ\"פ' (פרנקפורטר?)"},{"i":40358,"n":"פרנקפורטר-שפירא, יהודה ליב","f":"הירש","k":"בעל הרכסים לבקעה","bt":"תקג","bp":"אלטונא","dt":"תקצו - יז טבת","dp":"המבורג","b":"רב באלטונא. אחיו של ר מנחם מנדל מאלטונא, אחיינו - ר שמשון רפאל הירש המביא ממנו בפירושו לתורה. חיבר \"הרכסים לבקעה\" אלטונא תקעה."},{"i":40359,"n":"פרנקפורטר-שפירא, מנחם מנדל","f":"צבי הירש","bt":"תקב","bp":"המבורג","dt":"תקפג - יח אדר","dp":"אלטונא","b":"תלמיד ר יונתן איבשיץ. חתן ר ליב זלמן מאלטונא. מלמד בברלין והו\"ל \"תורת הבית\" לרשב\"א, מראשי קהלת המבורג-תקע, ומשגיח הת\"ת, ראב\"ד באלטונא-תקעב (לאחר היפרדות אה\"ו). הסכים על \"משנת דרבי אליעזר\". בניו: ר גבריאל, ר רפאל אריה-אביו של ר שמשון רפאל הירש, ר מיכאל, ר משה מנדלסון בעל \"פני תבל\". חתניו: ר חיים מאי מהמבורג."},{"i":40360,"n":"פרנקפורטר-שפירא, מנחם מנדל-א","b":"מחכמי פרנקפורט, דיין בהמבורג-תן. ראש משפחת פרנקפורטר מהמבורג. בניו - ר אברהם, ר שלמה-דיין בפרנקפורט."},{"i":40361,"n":"פרנקפורטר-שפירא, שלמה מאלטונא","f":"מנחם מנדל","dt":"תפט - יח כסלו","dp":"אלטונא","b":"חתן ר שמעון בן (או חתן) ר שמואל מוכסן ממינסק. דיין באלטונא. אבי משפחת מנדלסון מהמבורג. נינו - ר שמשון רפאל הירש."},{"i":40362,"n":"פרס, חיים מירושלים","dt":"תרנד - כט אד\"א","dp":"ירושלים","b":"מראשוני המשכילים בירושלים, עורך העתון \"שערי ציון\", ופרסם מאמרים בלשון ובנין הארץ."},{"i":40363,"n":"פרס, יוסף","bt":"1881","bp":"וילנא","dt":"1925","b":"מוסיקאי. הקים הרכב יחד עם אחיו מיכאל וגיסתו מורינא וניגנו ברחבי העולם ולפני מלכי אירופה."},{"i":40364,"n":"פרס, שלמה","bt":"1870","bp":"קאלואריה","b":"תלמיד ישיבת פלונגיאן, ז'אגר, וילנא. אנכריסט. היגר לאנגליה והתקרב לתנועת העבודה. פרסם ב\"ארבייטער פריינד\" מאמר על הנביאים והסוציאליזם. עבר לבוסטון והיה עורך הירחון \"דאס נייע ווארט\". התישב כחקלאי בפנסילבניה."},{"i":40365,"n":"פרסבורגר, אברהם","dt":"תקמט","b":"הרב הראשון באלברט-אירשא"},{"i":40366,"n":"פרסבורגר, אהרן מבאניהאד","f":"יוסף ממטרסדורף","k":"בעל פאר אהרן","bt":"תרלו-מד","bp":"מטרסדורף","dt":"תשד - סיון","dp":"אושוויץ","b":"ר שמואל רוזנברג מאונסדורף, תלמיד השב\"ס, ור ישעיה זילברשטין מוויצען. חתן ר חנניה ברגר מבאנפי-הוניאד ועבר לשם. רב בפאפא-תרעג, רבה האחרון של בניהאד-תרפד (ולפי מורשבת רבני הונגריה - רבה האחרון של פאפא). נספה בשואה. בנו ר שמואל מבאניהאד - הו\"ל מספריו. חיבר גם \"בית ישראל השלם\"."},{"i":40367,"n":"פרסבורגר, יוסף ממטרסדורף","f":"בצלאל","k":"בעל תפארת יוסף","bt":"תרז או תרכא","bp":"סערדאוהל","dt":"תרפד - כב כסלו","dp":"מטרסדורף","b":"תלמיד הכת\"ס, ור יכאל הופמן מסעדאוהל, ור יהודה אסאד. חתן ר אהרן זינגר ממטרסדורף ועבר לשם. רב במטרסדורף-תרנה, חתנו ר ישראל טויסיג על מקומו במטרסדורף - ואח\"כ עלה לירושלים."},{"i":40368,"n":"פרסבורגר, מיכאל מפאפא","f":"יוסף ממטרסדורף","bt":"תרלט","bp":"מטרסדורף","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר שמואל לוי וינברגר מסערדאוהל. רב בנאדי-באניא-תרסה, ערדא-בעניא-תרסט, פאפא-תרפז. נספה בשואה."},{"i":40369,"n":"פרסבורגר, שמואל מבאניהאד","f":"אהרן מבאניהאד","b":"ניצל מהשואה, ואחריה רב בבניהאד על מקום אביו, רב ביהכ\"נ שיפשוהל בוינה."},{"i":40370,"n":"פרסקי, בנימין מקרטינגא","dt":"תשג","b":"רב בקרטינגן"},{"i":40371,"n":"פרסקי, דב אריה מירושלים","k":"בעל כתר תורה","b":"מחכמי ירושלים."},{"i":40372,"n":"פרסקי, חיים בנימין מקרטינגה","bt":"תרמב","dt":"תשא","b":"חתן ר צבי הירש זאב שור מקרטינגה, רבה האחרון של קרטינגה על מקום חותנו. נספה בשואה."},{"i":40373,"n":"פרסקי, יוסף יוזל מוולוזין","b":"חתן ר שמשון מוולוזין בעל \"זכרון שמשון\". זקן העדה בוולוזין. חתנו - ר זלמן טוביה מרקוביץ."},{"i":40374,"n":"פרסקי, ליב מוילאן","dt":"תשג","b":"רב בווילאן"},{"i":40375,"n":"פרסקי, משה מלידא","bt":"תרמד","dt":"תשב","b":"מו\"צ ור\"מ בלידא-תרע\"ה,רב בפודבורז-תר\"פ"},{"i":40376,"n":"פרסקי, צבי יהודה ליב מוילון","dt":"תש..","b":"רבה האחרון של וילון על מקום ר שמואל מנחם הלוי כץ. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":40377,"n":"פרערא כץ גרוס, משה","b":"רב בפעטשי-נידורף-תר\"ל"},{"i":40378,"n":"פרערוי, שאול ממונקטש","b":"דומ\"צ במונקאטש"},{"i":40379,"n":"פרעש, יעקב ממונשטיר","f":"יהודה","b":"רב במונשטיר-שץ."},{"i":40380,"n":"פרעש, מרדכי מטבריה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":40381,"n":"פרץ","k":"בעל פאר הלכה","b":"רב-שנת ת\"ס"},{"i":40382,"n":"פרץ - משפחה","b":"משפחה במרוקו בעיר דאדיש ובעיר טיולית."},{"i":40383,"n":"פרץ הגדול מפשיסחא","dt":"תקעד","b":"תלמיד היהודי הקדוש מפשיסחא."},{"i":40384,"n":"פרץ הכהן מברצלונה","f":"יצחק","k":"בעל מערכת האלקות","b":"רב בברצלונה בזמן הר\"ן. מתלמידיו הריב\"ש ואחיו ר יצחק הצרפתי ואחיו דון קרשקש(?), ור יונה דיסמאשטרי חותנו של הרשב\"ץ. כנראה שהוא המחבר של \"מערכת האלקות (והדבר שנוי במחלוקת). חיבר גם חדושים לש\"ס ומהם ב\"יבין שמועה\" לר שלמה אלגזי."},{"i":40385,"n":"פרץ הכהן מברצלונה ומרשיליה","f":"יצחק הכהן","dt":"קל","b":"מגדולי חכמי התורה,בקי,מרביץ תורה במרשיליא,ברצלונה"},{"i":40386,"n":"פרץ הכהן מלובלין","b":"רב בלובלין-תק\"צ"},{"i":40387,"n":"פרץ הכהן מספרד","dt":"קיח","b":"מגדולי חכמי ספרד"},{"i":40388,"n":"פרץ הכהן מרוזוודוב","dt":"תקעד","b":"תלמיד היהודי הקדוש. רב ברוזוודוב."},{"i":40389,"n":"פרץ מאוסטרהא","f":"צבי","dt":"תמט - כה אדר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אולי בנו הוא ר יוסף יוזפ מאוסטרהא שהיה בועד ארבע ארצות."},{"i":40390,"n":"פרץ מאשכנז","b":"מגדולי חכמי אשכנז,מרביץ תורה-ק\"ע"},{"i":40391,"n":"פרץ מברוד","f":"משה","k":"בעל שריד ופליט","b":"רב ודרשן בברודי-תק, למד אצל ר ישראל אבד לאקטש ובישיבת ר ברוך כהנא בפיורדא. חיבר \"שריד ופליט\" בכתב יד. בשנת תקכד עלה לארץ ישראל בחבורה של ר נחמן מהורודנקא והתישב בצפת. חיבר \"בית פרץ\" זוקלווא, תקלט, ועוד."},{"i":40392,"n":"פרץ מירושלים","f":"קולון, פרץ","bp":"אשכנז","b":"הגיע מקושטא או מצרפת, רב בקהלה האשכנזית בירושלים-שנות ה-ר'-ש'."},{"i":40393,"n":"פרץ מירושלים","f":"משה","k":"בעל שבח ותהלה לא\"י","b":"מחכמי ירושלים, הו\"ל \"שבח ותהלה לארץ ישראל\" תקלא."},{"i":40394,"n":"פרץ מכלוף מג'רבה","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":40395,"n":"פרץ ממצרים","dt":"תיא","dp":"מצרים","b":"ג'יליבי במצרים-תיא על מקום ר אברהם אלכולי, ור יעקב ביבאס על מקומו אחריו. נהרג עק\"ה."},{"i":40396,"n":"פרץ מקורביל","f":"אליהו","k":"הר\"ף","dt":"ס","b":"מגדולי הפוסקים בדורו בצרפת,מרביץ תורה בקורבייל"},{"i":40397,"n":"פרץ מקושטניץ","b":"מגדולי הפוסקים בחכמי אשכנז-ר\"י"},{"i":40398,"n":"פרץ מקראקא","b":"רב בקרקא לאנשי ביהם-רע\"ט"},{"i":40399,"n":"פרץ, אברהם","f":"שלמה","b":"משורר. אולי בנו - ר אהרן מג'רבא בעל משחת אהרן."},{"i":40400,"n":"פרץ, אברהם מאדרינופול","f":"אליהו","b":"מחכמי שלוניקי, סופר הקהל באדרינופול-תקסו. אחד מ-4 החכמים שנתמנו לדון בענין המס באדרינופול (יחד עם ר יעקב אברהם גירון, ר חיים שמואל דאנון, ור אברהם ן ארוליא)."},{"i":40401,"n":"פרץ, אברהם מקושטא","f":"יעקב","k":"בעל אבני שהם","b":"מחכמי קושטא-תקץ, חיבר \"אבני שוהם\", \"אגורה באהליך\", ועוד."},{"i":40402,"n":"פרץ, אברהם מקושטא וירושלים","dt":"תרכט - יא סיון","dp":"קושטא","b":"עלה לארץ-תרטו."},{"i":40403,"n":"פרץ, אברהם משלוניקי","f":"ישעיהו","b":"מחכמי שלוניקי-תרע, עלה לירושלים."},{"i":40404,"n":"פרץ, אברהם משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'-תק'."},{"i":40405,"n":"פרץ, אהרן מג'רבה","k":"בעל בגדי אהרן","b":"ממגורשי ספרד, הגיע לפאס-מרוקו, היה בדרכו לארץ עם חבריו ר שמעון לביא ור מסעוד אלפסי ובדרכו הגיע לג'רבה ונשאר לכהן כרב בג'רבה-שט."},{"i":40406,"n":"פרץ, אהרן מג'רבה","f":"אברהם","k":"בעל בגדי אהרן","dt":"תקכו","b":"מרביץ תורה, רב ראשי בג'רבא, חיבר \"בגדי אהרן\",\"משחת אהרן\". בניו, ר חזקיה בעל מכתב לחזקיהו ור מיכאל ונכדו - ר מימון בן מיכאל סייע להו\"ל את ספריו."},{"i":40407,"n":"פרץ, אהרן משלוניקי","dt":"שסה","dp":"שלוניקי?","b":"מחכמי שלוניקי."},{"i":40408,"n":"פרץ, אהרן משלוניקי","dt":"שסא - י אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40409,"n":"פרץ, אליהו מאדרינופול","dt":"תקכג - ו אייר","dp":"אדרינופולי","b":"משורר, רב באדרינופול על כמה קהלות, בזמן הפירוד (חלק מהקהלות מינו את ר ירוחם אליקים גירון ואחרות את ר מנחם בכמוהר\"ר מרדכי). משורר. בנו - ר אברהם סופר הקהל. (אצל רוזניס נרשם תאריך פטירתו בטעות - תרכג)."},{"i":40410,"n":"פרץ, אליהו מוילנא","f":"ישכר בער בונם","bt":"תקסו","dt":"תרכז - ט תשרי","b":"מו\"צ בווילנה-תרט\"ז"},{"i":40411,"n":"פרץ, אליהו מקושטא וירושלים","dt":"תרג - כד טבת","dp":"ירושלים","b":"מחכמי קושטא, עלה לירושלים-תקצב-ו, חתם עם ר אברהם גאגין ור חיים דוד פנסו על קבלת עדות עגונה."},{"i":40412,"n":"פרץ, אפרים מגאבל","b":"מרבני גאבל-תקמ\"ח"},{"i":40413,"n":"פרץ, אריה ליבש","f":"משה פרץ מליברטוב","b":"רב בליברטוב-תק\"ס"},{"i":40414,"n":"פרץ, דוד","k":"בעל מגן דוד","bp":"יוונילן(מרוקו)","dt":"תרפו - יט טבת","b":"חכם שלם וכולל, מקובל, דיין מרביץ תורה ביוונילן(בהרי האטלס), חיבר \"מגן דוד\" על התורה"},{"i":40415,"n":"פרץ, דוד מתונס","b":"מחכמי תונס"},{"i":40416,"n":"פרץ, חגי","b":"מקובל,מרביץ תורה במרוקו"},{"i":40417,"n":"פרץ, חזקיה מג'רבה","f":"אהרון בעל משחת אהרן","k":"בעל מכתב לחזקיהו","b":"דיין בג'רבה, חיבר \"מכתב לחזקיהו\". אולי בנו - ר מימון שסייע להדפיס ספר זקנו."},{"i":40418,"n":"פרץ, חיים ישעיה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי, ונודע בזכרונו המצויין. נספה בשואה."},{"i":40419,"n":"פרץ, יהודה מאיטליה (ומרוקו?)","f":"יוסף","k":"בעל פרח לבנון","b":"מחכמי ונציה, שהה במצרים-תסה, רכושו אבד כשאונייתו טבעה, הגיע לנפולי ונאסר ע\"י הספרדים, דרשן בעירו, כתב ספר לאנוסים השבים ליהדות, שהה בהולנד ולונדון. חיבר גם \"נחל איתן\"."},{"i":40420,"n":"פרץ, יהודה מירושלים","b":"מראשי קהלת ירושלים ואחד משבעת טובי העיר, חתם על התקנה כנגד הפירוד בקהלה-שפג."},{"i":40421,"n":"פרץ, יוסף מרדכי משלוניקי","dt":"תרסד","dp":"שלוניקי","b":"ראב\"ד בשלוניקי. הניח חבורים בכת\"י (ונמצאים בספריה הלאומית בירושלים)."},{"i":40422,"n":"פרץ, יעקב בכור מירושלים","f":"אברהם","bt":"תרכו","bp":"ירושלים","b":"לאחר שנתייתם גדל אצל ר חיים הלוי מכיאו. תלמיד \"דורש ציון\". חתן אברהם עשור מטנג'יר וירושלים. ש\"ץ בביה\"כ יאנינה (בהנהלת הגביר מאיר גאני)."},{"i":40423,"n":"פרץ, יצחק ליבוש","f":"יהודה","k":"בעל העגב","b":"משורר אידי."},{"i":40424,"n":"פרץ, יצחק מירושלים","b":"מחכמי ירושלים וממקובלי ישיבת \"בית אל\"-תרפז."},{"i":40425,"n":"פרץ, יצחק ממראקש","b":"רב מחוז מראקש-מרוקו."},{"i":40426,"n":"פרץ, יצחק משה משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה."},{"i":40427,"n":"פרץ, יצחק משלוניקי","dt":"שעו - כה אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":40428,"n":"פרץ, יצחק מתל אביב","f":"חיים גוטמן","k":"בעל יסודות","bt":"1899","bp":"יאזנה","dt":"1967","b":"תלמיד ישיבת סלובודקה, לידא. למד כלכלה ובלשנות שמית בגרמניה. מורה לעברית בנירנברג ומינכן. עלה לארץ-1934 והיה מורה בת\"א. ראש הפקולטה לעברית באנו' ת\"א. פרסם מאמרים בכתבי עת שונים, וספרים בנושא הלשון העברית."},{"i":40429,"n":"פרץ, ישעיה מרדכי משלוניקי","dt":"תרעח","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של האב\"ד ר יוסף פרץ."},{"i":40430,"n":"פרץ, כליפא מג'רבה","b":"מחכמי ג'רבא-תר, בזמן ר רחמים חורי בעל \"כסא רחמים\" מזכירו בספרו."},{"i":40431,"n":"פרץ, מיכאל מג'רבה","f":"אהרן","dt":"תקלב","b":"רב בג'רבה. בנו - ר מימון סייע להדפיס ספר זקנו \"משחת אהרן\"."},{"i":40432,"n":"פרץ, מסעוד מאספי-מרוקו","dp":"אספי","b":"מחכמי אספי בזמן ר סעדיה ן דבוח."},{"i":40433,"n":"פרץ, מסעוד מטריפולי","bt":"תס","dt":"תקל","b":"דיין בטריפולי, ונזכר במכתב בענין פדיון שבויים."},{"i":40434,"n":"פרץ, מרדכי מצפון אפריקה ורוסיה","b":"חכם מצפון אפריקה, עבר לאוקראינה בתחילת המאה ה-20, וכיהן כרב באחת הקהילות. ומצאצאיו משפחת פרץ - אשכנזים."},{"i":40435,"n":"פרץ, משה","k":"בעל משה בחירו","b":"תלמיד ר יצחק בוכובזא."},{"i":40436,"n":"פרץ, משה יעקב מירושלים","bt":"תקפו","dt":"תרסו - יב אייר","dp":"ירושלים","b":"רב בירושלים, חבר בועד של ר יהודה חי אלקלעי-תרלא לטובת ישוב הארץ."},{"i":40437,"n":"פרץ, משה מחברון","b":"מחכמי חברון. בשליחות במרוקו-תי !(והוא כנראה השליח הראשון מחברון הידוע בשמו), שאלות ממנו בהיותו במכנאס וטיטואן לר שמואל צרפתי בפאס."},{"i":40438,"n":"פרץ, משה מחברון","b":"מחכמי חברון. חתם על כתב שליחות ר שמואל הכהן-תקמח."},{"i":40439,"n":"פרץ, משה מליברטוב","f":"ישראל פרץ","b":"רב בליברטוב-תק\"מ"},{"i":40440,"n":"פרץ, נסים מספרד","b":"מחכמי ספרד, עלה על המוקד בידי האינקביזיציה-ריב - וניצל בדרך נס. בנו ר אברהם היה ממגורשי ספרד שהגיעו למרוקו."},{"i":40441,"n":"פרץ, עיוש ממרוקו","b":"צדיק ומלומד בנסים. רב בכפרים תיקרת ותמערופט ליד תאזכת-מרוקו. מסופר על מעשה נס שעשה עם אריה."},{"i":40442,"n":"פרץ, רחמים מתונס","b":"מחכמי תונס- שנות ה-תר'. חתם על הסכמה ל\"מעייני הישועה\" לר ישועה הכהן מתונס."},{"i":40443,"n":"פרץ, רפאל חיים בנימין מתורכיה","f":"אברהם - אבני שהם","k":"בעל זכרנו לחיים","b":"רב בשאלוניקי-תרח, מגדלים (=דרדנלים), וגליפולי. נזכר בספרי ה\"שדי חמד\". הו\"ל ספר אביו - \"אבני שהם\"."},{"i":40444,"n":"פרץ, שלמה חי בכור","f":"יעקב","bt":"תרמז","bp":"ירושלים","b":"תלמיד \"דורש ציון\", \"תפארת ירושלים\", שו\"ב בירושלים, ומורה בת\"ת עדת הבוכרים-תרסח, מזכיר הכוללות, ועוד."},{"i":40445,"n":"פרץ, שלמה משלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה הלוי הבחור ומגדולי ישיבתו."},{"i":40446,"n":"פרץ, שלמה משלוניקי וקושטא","bt":"שפ","bp":"שלוניקי","dt":"תח","dp":"קושטא","b":"מחכמי שלוניקי, עבר לקושטא, נפטר צעיר. גיסו (בעל אחותו) של ר דוד קונפורטי בעל \"קורא הדורות\"."},{"i":40447,"n":"פרץ, שלמה סלימאן ממרוקו","f":"ישראל","k":"בעל חכמת שלמה","bt":"תרמו","bp":"מרוקו","dt":"תשלו - כו אד\"א","b":"רב בדאדס-מרוקו במשך כ-30 שנה. עלה לארץ-תשיג והתישב בצפת וטבריה. נינו ר משה פרץ הו\"ל את ספרו \"חכמת שלמה\"."},{"i":40448,"n":"פרץ, שמואל","f":"משה פרץ","k":"ר' שמואל הקדוש","b":"רב-שנת תק\"ע"},{"i":40449,"n":"פרץ, שמואל מאזמיר","b":"רב באזמיר. חתם ב\"מזכרת משה\"."},{"i":40450,"n":"פרצבסקי, זלמן מקופישוק","bt":"תרע","dt":"תשא - אב","b":"גיסו של ר אליהו מאיר פיבלסון. רבה האחרון של קופישוק על מקום גיסו. נספה בשואה."},{"i":40451,"n":"פרצוביץ, אריה צבי מטראקי","dt":"ט תשרי - תשב","b":"חתן ר נחום גרינהו מטרוקי, רב בטראקי(=טרוקי)-תרפג על מקום חותנו. נספה בשואה עם בני קהלתו ומשפחתו. בנו - ר נחום."},{"i":40452,"n":"פרצוביץ, נחום ממיר וירושלים","f":"אריה צבי מטרוקי","bt":"תרפג","dt":"תשמז","b":"תלמיד ישיבת מיר, ר אלחנן וסרמן, ר ברוך בר ליבוביץ. חתן ר חיים שמואלביץ ממיר. ניצל מהשואה והגיע לשנחאי-סין. ר\"מ בישיבת מיר בירושלים. נפטר צעיר. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו."},{"i":40453,"n":"פרצוור, בנימין זאב מזולקוא","b":"דיין בזלקווא"},{"i":40454,"n":"פרצוור, יהודה אברהם מגידונגן","b":"רב בגידונגן-תפ\"ה"},{"i":40455,"n":"פרק, ירחמיאל מדובייק","bp":"דובייק-ליטא","b":"תרגם פרקי אבות וחמש מגילות לאידיש - וילנא תרעה."},{"i":40456,"n":"פרקובסקי, ישראל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":40457,"n":"פרקויף, נתן נטע מלמברג","dt":"תרס","b":"דיין בלמברג - אצל רא\"ל ברודא."},{"i":40458,"n":"פרקל, צבי","dt":"תשג","b":"רב בסוכאטוב"},{"i":40459,"n":"פרקש, אברהם מבודפשט","bt":"תרב","bp":"שימלויא","b":"תלמיד הכת\"ס. רב בבודפשט, עורכו הראשון של הבטאון האורטודוכסי \"מאדיאר זשידא\", והיה ממיסדי הקהלה האורטודוכסית בבודפשט."},{"i":40460,"n":"פרקש, חיים בונם מקאראד","f":"אהרן הלוי מקלויזנבור","b":"תלמיד הכת\"ס, ור הלל ליכטנשטין מקולומיא. חתן ר ישראל דייטש מקלויזנבורג-תרכו. מחכמי קאראד סנט מארטון-תרלה."},{"i":40461,"n":"פרקש, יוסף ממפדמ","dt":"תשג - יא תשרי","b":"תלמיד השב\"ס. חתן ר מאיר הירשלר מפרשבורג. רב בפפדמ ליד ר שלמה זלמן ברייער. נספה בשואה."},{"i":40462,"n":"פרקש, יצחק יואל","b":"תלמיד ישיבת וערפעלט. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":40463,"n":"פרקש, שמואל זונדל מליפטע","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":40464,"n":"פרשט, זלמן","b":"דיין ונאמן באלטונא-ת\"מ"},{"i":40465,"n":"פרשטינר, יצחק","f":"אהרן ליב","b":"רב-שנת תק\"ס"},{"i":40466,"n":"פרשל, זאב וולף חיים מיגולניצה","f":"משה","b":"מחכמי יגולניצה. אחיו של ר יוחנן מפוטיק."},{"i":40467,"n":"פרשל, יוחנן מפוטיק","f":"משה","k":"בעל וישב משה","bt":"תריח","bp":"יגולניצה","dt":"תרפט - ח אייר","b":"נכד מהר\"י מהורודנקה. תלמיד ר משה תאומים. חתן הגביר ר צבי הירש גולדברג. רב בפוטיק-זלוטי-תרם, צורטקוב (בזמן מלחמת העולם ה-I), סניאטין. חיבר תפלה שאמרה כל יום שיזכה לקדש את השם - נדפסה ע\"י בנו ר משה בסניאטין תרפט. מראשי המזרחי. חיבר \"וישב משה\" מונקטש תרסד, הניח חדושים בכת\"י ובהם \"כרם צבי\", ועוד. פרסם מאמרים ב\"הבאר\" - זאמושץ-וארשא - תרפד. נכדו - הסופר טוביה פרשל בניו יורק."},{"i":40468,"n":"פרשל, יוסף","k":"בעל וישב משה","b":"פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד."},{"i":40469,"n":"פשאד ן, יצחק גירונדי","f":"יהודה","b":"פייטן בספרד-שנות ה-ד'תתק, מפיוטיו במחזורי והראן, אלגיר ותונס."},{"i":40470,"n":"פשדמיסקי, אברהם - שדמי","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט, \"אורים\" - ירושלים תשז."},{"i":40471,"n":"פשט ן, נסים בן ציון","b":"תלמיד השדי חמד, ונזכר בספרו \"מכתב לחזקיהו\"."},{"i":40472,"n":"פשיבולסקי, משה","b":"פרסם מאמרים ב\"יבנה\" - פאביאניץ תרפד."},{"i":40473,"n":"פשיסכר, יוסף מנחם הכהן מויסוקי","dt":"תשג","b":"בנו חורגו של ר צדוק הכהן מלובלין (אמו נישאה לו בזיוו\"ש). חתן ר אפרים צבי אינהורן מאמסטוב. רב בויאסקי(=ויסוקי), לובלין. נספה בשואה. חתם עם רבני לובלין על מכתב לרב קוק בירושלים."},{"i":40474,"n":"פשמיש, ירוחם משה מפשוורסק","f":"יקותיאל יעקב","b":"ניצל מהשואה. הדפיס ספרי זקנו ר משה מפשוורסק."},{"i":40475,"n":"פשקיז, משה מניקלשבורג","f":"צדוק צוקרמן","dt":"תריד","b":"דיין בניקלסבורג-תקס\"ד"},{"i":40476,"n":"פשקס, אהרן אלעזר מגלנטא","f":"בנימין בונם מסערדאוה","k":"בעל באר רחובות","bt":"תקפ","bp":"סערדאוהל","dt":"תרמד - א אדר","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור אליעזר ליפמן שטיין מסערדאוהל. חתן ר בנימין זאב וולף רוסט-טרוטצר. רב בקאטה-תריב, גלנטא-תריז-תרלג על מקום ר ליב טלטש ור מנחם דייטש על מקומו אחריו, עבר לסערדהאלי. חיבר \"באר רחובות\", \"מעשה אבות\", \"עת ספוד\", ועוד.","bk":[["באר רחובות",""],["מעשה אבות",""],["משמרת אלעזר",""]]},{"i":40477,"n":"פשקס, בנימין בונם מסערדאוהל","b":"חתניו - ר עקיבא קליין מנייטרא, ר שמואל עהרנפלד אב\"ד מטרסדורף."},{"i":40478,"n":"פשקס, מיכאל חיים ממאקווא","b":"חתן ר אליעזר זוסמן סופר מפאקש."},{"i":40479,"n":"פשקס, משה מבודפשט","f":"ישעיה מסערדאוהל","bt":"תרמב","bp":"סערדאוהל","dt":"תשכב - טו שבט","dp":"בודפשט","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט. ניצל מהשואה ואחריה סגן יו\"ר הועד היהודי של המדינה."},{"i":40480,"n":"פשרהופר, אברהם אהרן מפרוינקירכ","f":"משה קאניזשא-פשרהופר","bt":"תקעה","bp":"פרשבורג","dt":"תרכט - ל תשרי","dp":"פרוינקירכן","b":"תלמיד החת\"ס, ור צבי הרש הלר חריף מאויבן. רב בפרוינקירכן-תקצז, יעמרינג-תרב, פרוינקירכן-תריא על מקום אביו ובנו ר משה מרדכי על מקומו אחריו. הסכים על \"עקידת יצחק\" פרשבורג תריח."},{"i":40481,"n":"פשרהופר, משה מפרוינקירכן","f":"אברהם","bt":"תקן או תקנה","bp":"נאדי-קניזשא","dt":"תקצז - טז תשרי","dp":"פרוינקירכן","b":"תלמיד החת\"ס. חתן ר מרדכי טאסק מפרשבורג ועבר לשם-תקעד. רב ביינק-תקפו, פרוינקירכן-תקצג, בנו ר אברהם אהרן על מקומו אחריו. אלמנתו נישאה לר חיים קיצע מאירשא, אביו של חתנו - ר מרדכי שלזינגר מסארוואש."},{"i":40482,"n":"פשרהופר, משה מרדכי מסערעד","f":"אברהם אהרן מפרוינקיר","bt":"תרה","dt":"תרעו","b":"תלמיד הכת\"ס, ור יהודה אסאד. רב בפאפא-תרכג, פרוינקירכן-תרל על מקום אביו, סערעד-תרמח. פרסם מאמרים ב\"תל תלפיות\", ועוד."},{"i":40483,"n":"פשריאל, יוסף","b":"מעיןן גדול-ת\"נ"},{"i":40484,"n":"פשריאל, לוי משלוניקי","dt":"תכב","b":"מעיין ודרשן בשלוניקי-תח."},{"i":40485,"n":"פתחי, אהרן מבגדד","dt":"תרמד - יז אייר","b":"מרבני בגדאד"},{"i":40486,"n":"פתחיה מאוסטרהא","b":"פרנס מאוסטרהא-שנות התק'. ונזכר בפנקס הח\"ק ששלחו לו דבש."},{"i":40487,"n":"פתחיה מברלין","f":"צבי סגל","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":40488,"n":"פתחיה מוילנא","f":"משה - באר הגולה","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא. נכדו(-בן בתו) - הגר\"א."},{"i":40489,"n":"פתחיה מוילנא","f":"משה","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא."},{"i":40490,"n":"פתחיה מטפאלטשן","bp":"טאפלטשן","dt":"תרלה - בערך","b":"תלמיד החת\"ס. מחכמי יינק-תקפ."},{"i":40491,"n":"פתחיה מלבוב","f":"דוד","b":"רב בלבוב. (יש שהחליפו בינו לבין ר פתחיה בן דוד לידא מפפד\"מ אך בובר מוכיח שמדובר בחכם אחר)."},{"i":40492,"n":"פתחיה מפפד\"מ","dt":"שצז - כא ניסן","b":"גדול בנגלה ונסתר, רב בפפד\"מ, ור חיים הכהן מפרג על מקומו אחריו, וורמס(=וורמייזא)-שפח ור אליהו לואנץ \"בעל שם\" על מקומו אחריו, ניקלשבורג. סייע בהדפסת ספר הכוונות לאר\"י (ועל רקע זה אף נאסר לזמן קצר) ויחד עמו הסכימו ר יוסף האן, ר מאיר רויטלינגר, ר נתן בן אברהם העלן, ועוד. הספר הוצא מא\"י בניגוד לחרם שלא להוציאו לחו\"ל. מחברי המשלחת שקיבלה את פני הקיסר פרדיננד-שפט. נספד מאת ר אברהם רפפורט בעל \"איתן האזרחי\" (שם רשום שנת פטירתו - שצד?)."},{"i":40493,"n":"פתחיה מפרג","f":"יוסף מאובן","dt":"שנט - כה שבט","dp":"פרג","b":"סופר קהילת פרג - כ-30 שנה. בנו - ר נפתלי סופר ונכדו ר משה רבקש בעל באר הגולה."},{"i":40494,"n":"פתחיה מרגנשבורג בעל התוספות","k":"בעל הסיבוב","dt":"ד'תתקל","b":"אחיו של רבינו יצחק בעל התוספות. חיבר סיבוב העולם. ערך מסעות בקהילות ישראל בעולם,מפרג לפולין,קיוב,קרים,אסיה,אראמניה,בבל,סוריה,ארץ ישראל."},{"i":40495,"n":"פתחיה משה מקרמניץ","b":"בניו - ר ישכר דב בר מקרמניץ, ר יוסף מאובין."},{"i":40496,"n":"פתייא, יהודה מבגדד","f":"משה ישועה","k":"בעל יין הרקח","bt":"תריא או תרלא","bp":"עיראק","dt":"תשב - כז אב","dp":"ירושלים","b":"מקובל, תלמיד ר שמעון אגסי, עלה לירושלים-תרסה, תרפג, תרצד ואז נשאר בה. חיבר \"יין הרקח\" על האדרא."},{"i":40497,"n":"פתייא, משה מבבל","f":"ישועה","bt":"תקץ","bp":"בבל","dt":"תרסה - יג טבת","b":"רב ופייטן בבבל. הקים בית דפוס-תרכו והדפיס עשרות ספרים. מפיוטיו בספר בנו ר יהודה \"יין הרקח\"."},{"i":40498,"n":"פתייא, שאול מירושלים","f":"יהודה","k":"בעל הרהורים","dt":"תש..","dp":"ירושלים","b":"איש חסד מחכמי ירושלים, הו\"ל כתבי אביו. הקים את מפעל החסד \"חזון פתיה\"."}];
